// ===== 游戏大厅 V0.2.2（可拖动悬浮按钮 + 可拖动面板 + 自定义角色） =====
// 悬浮游戏机按钮 → 圆形游戏图标 → 各游戏大厅（麻将对弈/棋牌/小游戏/推理桌游全部内置）
// 角色来源：读取「数据库本体」的重要角色表/恋爱对象表/人物关系表，也支持大厅内创建自定义角色

$(() => {
  'use strict';
  console.log('[小游戏机 V0.2.2] 初始化');

  // ========== 本地存储配置与持久化键名 ==========
  const CONFIG_KEY = 'werewolf_extension_config';
  const SAVE_GAME_KEY = 'werewolf_extension_saved_game';
  const MATCH_HISTORY_KEY = 'werewolf_extension_match_history';
  // 游戏中心 API 配置
  const LINKAGE_API_CONFIG_KEY = 'werewolf_extension_linkage_api_config';

  // ========== 统一难度中枢（快速 / 标准 / 强力） ==========
  // 所有"本地代码 AI 对战"的游戏统一从这张表取参数：以后加第四档只需在下面每个键补一项。
  // 难度完全由本地算法参数决定（LLM 只负责角色台词），因此不涉及任何对外接口。
  // 参数含义：
  //   depth   搜索深度        sims    蒙特卡洛模拟次数      timeMs  单步思考时间上限（毫秒）
  //   blunder 主动失误概率    candK   候选池宽度（1=只走最优） noise  打分抖动幅度
  //   memory  记忆强度(0/1/2) bluff   诈唬频率              model  是否开启对手建模
  const DIFFICULTY = {
    fast: { depth: 1, sims: 8, timeMs: 200, blunder: 0.22, candK: 4, noise: 1.00, memory: 0, bluff: 0.02, model: false },
    normal: { depth: 2, sims: 20, timeMs: 800, blunder: 0.07, candK: 2, noise: 0.45, memory: 1, bluff: 0.10, model: false },
    strong: { depth: 3, sims: 40, timeMs: 1500, blunder: 0.00, candK: 1, noise: 0.00, memory: 2, bluff: 0.16, model: true }
  };
  const DIFFICULTY_KEYS = ['depth', 'sims', 'timeMs', 'blunder', 'candK', 'noise', 'memory', 'bluff', 'model'];

  // 各游戏覆盖（只写需要偏离基准的项；纯棋类用 depth/timeMs，牌类用 sims/blunder/bluff）
  // 注：五子棋没有搜索树，分档靠 getBestMove 里的 weak/strong 分支（快速只算单点、强力加"对手最强回应"评估），
  // depth 参数对五子棋不参与运算，故不再写覆盖项（基准 depth 1/2/3 保持占位即可）。
  const DIFFICULTY_OVERRIDES = {
    xiangqi: { depth: { fast: 2, normal: 3, strong: 4 }, timeMs: { fast: 450, normal: 800, strong: 1800 }, qdepth: { fast: 1, normal: 4, strong: 6 } },
    jungle: { depth: { fast: 2, normal: 4, strong: 5 }, timeMs: { fast: 250, normal: 800, strong: 1500 } },
    chess: { depth: { fast: 2, normal: 3, strong: 4 }, timeMs: { fast: 400, normal: 900, strong: 1400 } },
    shogi: { depth: { fast: 1, normal: 2, strong: 3 }, timeMs: { fast: 400, normal: 900, strong: 1500 } },
    go: { sims: { fast: 0, normal: 0, strong: 40 }, timeMs: { fast: 150, normal: 400, strong: 1200 } },
    luzhanqi: { depth: { fast: 1, normal: 2, strong: 3 }, timeMs: { fast: 260, normal: 750, strong: 1700 } },
    othello: { depth: { fast: 1, normal: 3, strong: 5 }, timeMs: { fast: 120, normal: 500, strong: 1600 } },
    minesweeper: { hintLimit: { fast: -1, normal: 3, strong: 0 } },
    blackjack: { sims: { fast: 0, normal: 0, strong: 120 }, timeMs: { fast: 120, normal: 300, strong: 800 } },
    mahjong: { sims: { fast: 0, normal: 12, strong: 40 }, timeMs: { fast: 120, normal: 380, strong: 800 }, mctsIter: { fast: 0, normal: 600, strong: 2000 } },
    // 注：强力档蒙特卡洛改为"固定轮数、不看墙钟"（保证同一局面决策一致），
    // 因此把 sims 压到实测可接受的量（30 → 12），否则单步会长达数秒。
    doudizhu: { sims: { fast: 0, normal: 10, strong: 12 }, timeMs: { fast: 400, normal: 1100, strong: 1500 } },
    zjh: { sims: { fast: 0, normal: 200, strong: 600 }, timeMs: { fast: 150, normal: 600, strong: 1200 } },
    holdem: { sims: { fast: 60, normal: 260, strong: 600 }, timeMs: { fast: 200, normal: 700, strong: 1400 } },
    uno: { sims: { fast: 0, normal: 16, strong: 40 }, timeMs: { fast: 150, normal: 500, strong: 900 } },
    battleship: { sims: { fast: 0, normal: 0, strong: 0 }, timeMs: { fast: 60, normal: 120, strong: 200 } },
    lie: { sims: { fast: 0, normal: 0, strong: 6 }, timeMs: { fast: 150, normal: 400, strong: 600 } },
    ludo: { sims: { fast: 0, normal: 0, strong: 20 }, timeMs: { fast: 120, normal: 400, strong: 1000 } },
    richman: { sims: { fast: 0, normal: 0, strong: 12 }, timeMs: { fast: 150, normal: 500, strong: 1100 } },
    rps: { sims: { fast: 0, normal: 0, strong: 0 } },
    // 井字棋：depth 为极大极小搜索层数（1=只看一步、3=看三步、9=全盘完美）；
    // blunder 为"主动失误"概率（快速档经常随手下、强力档零失误）
    ttt: { depth: { fast: 1, normal: 3, strong: 9 }, blunder: { fast: 0.35, normal: 0.12, strong: 0 } }
  };

  function difficultyLevel(v) { return (v === 'fast' || v === 'strong') ? v : 'normal'; }

  // 取某个游戏某一档的完整参数表（基准 + 该游戏覆盖）
  function getDifficulty(gameKey, level) {
    const key = difficultyLevel(level);
    const out = {};
    for (const k of DIFFICULTY_KEYS) out[k] = DIFFICULTY[key][k];
    const ov = DIFFICULTY_OVERRIDES[gameKey] || {};
    for (const k of Object.keys(ov)) {
      const v = ov[k];
      out[k] = (v && typeof v === 'object' && !Array.isArray(v)) ? (v[key] !== undefined ? v[key] : v.normal) : v;
    }
    out.level = key;
    return out;
  }

  // 读实时难度：优先取玩家当前配置（改了立即生效），读不到再退回对局内缓存
  function liveAiLevel(configLoader, cachedLevel) {
    try {
      const cfg = configLoader && configLoader();
      if (cfg && (cfg.aiLevel === 'fast' || cfg.aiLevel === 'normal' || cfg.aiLevel === 'strong')) return cfg.aiLevel;
    } catch (e) { /* ignore */ }
    return difficultyLevel(cachedLevel);
  }

  // ========== 强力档确定性随机源 ==========
  // 牌类的蒙特卡洛模拟必须"同一局面 → 同一结果"，否则强力档同一局面两次决策可能不同。
  // 这里用"局面指纹"播种一个可复现的伪随机序列：强力档用播种随机源，其它档位仍用 Math.random。
  function diffHashStr(str) {
    let h = 2166136261 >>> 0;
    const s = String(str == null ? '' : str);
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
    return h >>> 0;
  }
  function makeSeededRng(seedStr) {
    let a = diffHashStr(seedStr) || 1;
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  // 强力档返回播种随机源；快速/标准返回 Math.random（允许随机）
  function pickRng(level, seedStr) {
    return difficultyLevel(level) === 'strong' ? makeSeededRng(seedStr) : Math.random;
  }

  // ========== 工具：根节点查找 ==========
  function getPhoneRoot() {
    const docs = [document, window.parent?.document, window.top?.document].filter(Boolean);
    for (const doc of docs) {
      try {
        const root = doc.getElementById('ubp-root');
        if (root && root.shadowRoot) return root;
      } catch (e) { /* ignore */ }
    }
    return null;
  }

  function getShadowRoot() {
    const root = getPhoneRoot();
    return root ? root.shadowRoot : null;
  }

  // ========== 瑟瑟灵感数据库与酒馆环境 API ==========
  function getAutoCardAPI() {
    try {
      const api = window.AutoCardUpdaterAPI || window.parent?.AutoCardUpdaterAPI || window.top?.AutoCardUpdaterAPI;
      if (api && typeof api.exportTableAsJson === 'function') return api;
      return null;
    } catch (e) { return null; }
  }

  function getTavernContext() {
    try {
      const sts = [window.SillyTavern, window.parent?.SillyTavern, window.TavernHelper?.SillyTavern, window.parent?.TavernHelper?.SillyTavern];
      for (const st of sts) {
        if (st && typeof st.getContext === 'function') {
          const c = st.getContext();
          if (c) return c;
        }
      }
      return null;
    } catch (e) { return null; }
  }

  // 验证字符串是否为有效图片路径
  function isRealImageUrl(url) {
    if (!url || typeof url !== 'string') return false;
    const s = url.trim().toLowerCase();
    if (s.startsWith('data:image/')) return true;
    if (s.startsWith('http://') || s.startsWith('https://')) return true;
    if (/\.(png|jpe?g|webp|gif|bmp|svg)($|[?#\s"'\)\]])/i.test(s)) return true;
    if (s.includes('user/images/') || s.includes('characters/') || s.includes('/characters/') || s.includes('thumbnails/') || s.includes('files/')) return true;
    return false;
  }

  // 清洗从各种来源提取出的纯净图片路径
  function cleanImageUrl(raw) {
    if (!raw || typeof raw !== 'string') return '';
    let str = raw.trim();
    if (!str || str === 'none' || str === 'null' || str === 'undefined' || str === '无' || str === '-') return '';
    const mdMatch = str.match(/!\[.*?\]\((.*?)\)/);
    if (mdMatch && mdMatch[1]) str = mdMatch[1].trim();
    const htmlMatch = str.match(/<img[^>]+src=["'](.*?)["']/i);
    if (htmlMatch && htmlMatch[1]) str = htmlMatch[1].trim();
    str = str.replace(/^["'\[(]+|["'\)\]]+$/g, '').trim();
    if (!isRealImageUrl(str)) return '';
    return str;
  }

  function resolveAvatarUrl(avatar) {
    const cleaned = cleanImageUrl(avatar);
    if (!cleaned) return '';
    if (cleaned.startsWith('http://') || cleaned.startsWith('https://') || cleaned.startsWith('data:')) {
      return cleaned;
    }
    let p = cleaned.replace(/^\.\//, '');
    if (p.startsWith('/')) return p;
    if (
      p.startsWith('user/') ||
      p.startsWith('characters/') ||
      p.startsWith('img/') ||
      p.startsWith('thumbnails/') ||
      p.startsWith('files/')
    ) {
      return `/${p}`;
    }
    if (p.toLowerCase().startsWith('user.') || p.toLowerCase().startsWith('user_')) {
      return `/${p}`;
    }
    if (/\.(png|jpe?g|webp|gif|bmp|svg)$/i.test(p)) {
      return `/characters/${encodeURIComponent(p)}`;
    }
    return '';
  }

  function normalizeCharName(str) {
    if (!str || typeof str !== 'string') return '';
    return str
      .replace(/\(.*?\)|（.*?）|\[.*?\]|【.*?】/g, '')
      .replace(/[\s_\-\/\\()（）\[\]【】|·:：]/g, '')
      .toLowerCase()
      .trim();
  }

  function isNameMatch(a, b) {
    if (!a || !b) return false;
    const na = normalizeCharName(a);
    const nb = normalizeCharName(b);
    if (!na || !nb) return false;
    return na === nb || na.includes(nb) || nb.includes(na);
  }

  // 日志归属判断：日志行以角色名开头，且名字后面必须是分隔符/空白。
  // 避免"小明"把"小明明"的日志行也算进自己的统计（旧实现只用 indexOf(name) === 0）。
  function logBelongsTo(line, name) {
    if (!line || !name) return false;
    const s = String(line);
    const n = String(name);
    if (!n || s.indexOf(n) !== 0) return false;
    const next = s.charAt(n.length);
    return !next || /[\s：:，,。！!？?、；;\-—]/.test(next);
  }

  // ========== 角色专属发言配色（同名角色恒定同色） ==========
  // 8 色板与 31 进制哈希取模算法，保证同一角色在任何游戏中颜色一致。
  const CHAR_COLOR_PALETTE = ['#5B8DEF', '#07C160', '#E6A23C', '#9B59B6', '#E67770', '#3AAFB9', '#C0629E', '#7B8A4A'];
  function getCharacterColor(name) {
    const s = String(name == null ? '' : name);
    if (!s) return '';
    let h = 0;
    for (let i = 0; i < s.length; i++) h = (31 * h + s.charCodeAt(i)) >>> 0;
    return CHAR_COLOR_PALETTE[h % CHAR_COLOR_PALETTE.length];
  }
  function getGamePlayerByPos(gameRef, pos) {
    if (!gameRef || !Array.isArray(gameRef.players) || pos == null) return null;
    return gameRef.players.find(p => p && p.position === pos) || null;
  }
  // 为同一局内所有角色分配互不相同的颜色：以名字哈希为起点，冲突时线性探测取下一色，
  // 保证「每个角色发言颜色不同」；同一局玩家顺序固定，结果恒定可复现。
  function buildDistinctColorMap(players) {
    const map = new Map();
    const used = new Set();
    const n = CHAR_COLOR_PALETTE.length;
    (Array.isArray(players) ? players : []).forEach(p => {
      const name = p && p.name;
      if (!name || map.has(name)) return;
      let h = 0;
      const s = String(name);
      for (let i = 0; i < s.length; i++) h = (31 * h + s.charCodeAt(i)) >>> 0;
      let idx = h % n;
      let guard = 0;
      while (used.has(idx) && guard < n) { idx = (idx + 1) % n; guard++; }
      used.add(idx);
      map.set(name, CHAR_COLOR_PALETTE[idx]);
    });
    return map;
  }
  // 依据号位取该座位角色的专属颜色（找不到则返回空串，由调用方回退）
  function getGamePlayerColorByPos(gameRef, pos) {
    const p = getGamePlayerByPos(gameRef, pos);
    if (!p) return '';
    if (gameRef && Array.isArray(gameRef.players) && gameRef.players.length) {
      const map = buildDistinctColorMap(gameRef.players);
      return map.get(p.name) || getCharacterColor(p.name);
    }
    return getCharacterColor(p.name);
  }
  // 半透明色（用于气泡底色/描边）：#RRGGBB + 两位十六进制透明度
  function charColorAlpha(color, alphaHex) {
    return color && /^#[0-9a-fA-F]{6}$/.test(color) ? color + (alphaHex || '1a') : color;
  }

  function getAvatarFromDOM(name) {
    if (!name) return '';
    const docs = [document, window.parent?.document, window.top?.document].filter(Boolean);
    for (const doc of docs) {
      try {
        const nodes = doc.querySelectorAll('.character_select, .group_member, .mes, [ch_name], [data-ch-name]');
        for (const node of nodes) {
          const chName = node.getAttribute('ch_name') || node.getAttribute('data-ch-name') || node.getAttribute('title') || node.querySelector('.ch_name')?.textContent?.trim();
          if (chName && isNameMatch(chName, name)) {
            const img = node.querySelector('.avatar img, img.avatar, img');
            if (img && img.src && !img.src.includes('default-avatar') && !img.src.endsWith('/')) {
              return img.src;
            }
          }
        }
      } catch (e) { /* ignore */ }
    }
    return '';
  }

  function getMainAvatarFromDOM() {
    const docs = [document, window.parent?.document, window.top?.document].filter(Boolean);
    for (const doc of docs) {
      try {
        const userMes = doc.querySelector('#chat .mes[is_user="true"] .avatar img, #chat .mes[is_user="true"] img.avatar');
        if (userMes && userMes.src) return userMes.src;
        const userIcon = doc.querySelector('#user_avatar img, #your_avatar img, .user_avatar img');
        if (userIcon && userIcon.src) return userIcon.src;
      } catch (e) { /* ignore */ }
    }
    return '';
  }

  function isAvatarHeader(h) {
    if (typeof h !== 'string') return false;
    const s = h.trim().toLowerCase().replace(/[\s_\-\/\\()（）\[\]【】]/g, '');
    return ['立绘', '头像', '立绘路径', '图片', 'avatar', 'portrait', '形象', '照片', 'pic', 'img', 'photo', '立绘图片', '形象立绘', '角色立绘', '角色头像', '卡面', '外貌立绘', '立绘url', '当前立绘'].some(k => s.includes(k));
  }

  function getCharacterAvatarByName(name) {
    if (!name) return '';
    const trimmedName = name.trim();

    const cus = getCustomCharacterByName(trimmedName);
    if (cus && cus.avatar) return resolveAvatarUrl(cus.avatar);

    const ovAvatar = getContactAvatarOverride(trimmedName);
    if (ovAvatar) return resolveAvatarUrl(ovAvatar);

    const domAvatar = getAvatarFromDOM(trimmedName);
    if (domAvatar) return resolveAvatarUrl(domAvatar);

    const api = getAutoCardAPI();
    if (api) {
      try {
        const allTables = api.exportTableAsJson();
        if (allTables && typeof allTables === 'object') {
          for (const key of Object.keys(allTables)) {
            const table = allTables[key];
            if (!table || !Array.isArray(table.content) || table.content.length < 2) continue;
            const rows = table.content;
            const header = rows[0];
            if (!Array.isArray(header)) continue;
            
            let nameIdx = header.findIndex(h => typeof h === 'string' && (h.includes('姓名') || h.includes('角色名') || h.includes('人物') || h.includes('名字') || h.includes('称呼') || h.includes('角色') || h.toLowerCase().includes('name')));
            if (nameIdx === -1) nameIdx = 0;
            const avatarIdx = header.findIndex(h => isAvatarHeader(h));
            
            for (let i = 1; i < rows.length; i++) {
              const row = rows[i];
              if (!Array.isArray(row)) continue;
              const rName = typeof row[nameIdx] === 'string' ? row[nameIdx].trim() : '';
              if (rName && isNameMatch(rName, trimmedName)) {
                if (avatarIdx !== -1 && typeof row[avatarIdx] === 'string' && row[avatarIdx].trim()) {
                  const parsed = resolveAvatarUrl(row[avatarIdx].trim());
                  if (parsed) return parsed;
                }
                for (let c = 0; c < row.length; c++) {
                  const val = typeof row[c] === 'string' ? row[c].trim() : '';
                  if (val && isRealImageUrl(val)) {
                    const parsed = resolveAvatarUrl(val);
                    if (parsed) return parsed;
                  }
                }
              }
            }
          }
        }
      } catch (e) { /* ignore */ }
    }

    const ctx = getTavernContext();
    const charPools = [
      ctx?.characters,
      window.characters,
      window.parent?.characters,
      window.top?.characters,
      window.SillyTavern?.characters,
      window.parent?.SillyTavern?.characters
    ].filter(arr => Array.isArray(arr));

    for (const pool of charPools) {
      const char = pool.find(c => c && (c.name || c.data?.name) && (isNameMatch(c.name, trimmedName) || isNameMatch(c.data?.name, trimmedName)));
      if (char) {
        const av = char.avatar || char.data?.avatar;
        if (av) return resolveAvatarUrl(av);
      }
    }
    return '';
  }

  function getMainCharAvatar() {
    const domUserAv = getMainAvatarFromDOM();
    if (domUserAv) return resolveAvatarUrl(domUserAv);

    try {
      const parentUr = window.parent?.Ur || window.Ur;
      if (typeof parentUr === 'function') {
        const u1 = parentUr('__protagonist__');
        if (u1) return resolveAvatarUrl(u1);
      }
    } catch (e) { /* ignore */ }

    const api = getAutoCardAPI();
    if (api) {
      try {
        const allTables = api.exportTableAsJson();
        if (allTables && typeof allTables === 'object') {
          const pTable = Object.values(allTables).find(t => t && (t.name === '主角信息表' || t.name === '主角表'));
          if (pTable && Array.isArray(pTable.content) && pTable.content.length >= 2) {
            const header = pTable.content[0];
            const avIdx = header.findIndex(h => isAvatarHeader(h));
            if (avIdx !== -1) {
              const raw = pTable.content[1][avIdx];
              if (typeof raw === 'string' && raw.trim()) return resolveAvatarUrl(raw.trim());
            }
          }
        }
      } catch (e) { /* ignore */ }
    }

    const ctx = getTavernContext();
    if (ctx) {
      if (typeof ctx.userAvatar === 'string' && ctx.userAvatar.trim()) return resolveAvatarUrl(ctx.userAvatar);
      if (ctx.user && typeof ctx.user.avatar === 'string' && ctx.user.avatar.trim()) return resolveAvatarUrl(ctx.user.avatar);
      if (Array.isArray(ctx.characters) && ctx.characters.length && ctx.characters[0]?.avatar) return resolveAvatarUrl(ctx.characters[0].avatar);
    }
    return '';
  }

  // ========== 自定义角色（用户在悬浮窗内自建角色，参与所有游戏与 AI 陪聊） ==========
  const CUSTOM_CHARS_KEY = 'thgame_custom_characters';

  function loadCustomCharacters() {
    try {
      const raw = localStorage.getItem(CUSTOM_CHARS_KEY);
      if (raw) {
        const arr = JSON.parse(raw);
        return Array.isArray(arr) ? arr.filter(c => c && typeof c.name === 'string' && c.name.trim()) : [];
      }
    } catch (e) { /* ignore */ }
    return [];
  }
  function saveCustomCharacters(list) {
    try { localStorage.setItem(CUSTOM_CHARS_KEY, JSON.stringify(Array.isArray(list) ? list : [])); } catch (e) { /* ignore */ }
  }
  function getCustomCharacterByName(name) {
    if (!name) return null;
    return loadCustomCharacters().find(c => c && isNameMatch(c.name, name)) || null;
  }

  // ========== AI 生成自定义角色：单独配置的请求 API + 世界书检索 ==========
  const CC_GEN_API_CONFIG_KEY = 'thgame_custom_char_gen_api_config';
  function loadCcGenApiConfig() {
    try {
      const raw = localStorage.getItem(CC_GEN_API_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (p && typeof p === 'object') return { apiUrl: String(p.apiUrl || ''), apiKey: String(p.apiKey || ''), model: String(p.model || '') };
      }
    } catch (e) { /* ignore */ }
    return { apiUrl: '', apiKey: '', model: '' };
  }
  function saveCcGenApiConfig(c) {
    try { localStorage.setItem(CC_GEN_API_CONFIG_KEY, JSON.stringify(c && typeof c === 'object' ? c : {})); } catch (e) { /* ignore */ }
  }

  // 检索所有世界书中「关键字/标题包含该角色名」的条目，拼成给 AI 的参考资料
  async function collectCharacterWorldbookContext(name) {
    const n = String(name || '').trim();
    const parts = [];
    if (!n) return parts;
    const th = __getTavernHelper__();
    if (!th || typeof th.getWorldbook !== 'function') return parts;
    let bookNames = [];
    try {
      if (typeof th.getWorldbookNames === 'function') {
        const all = th.getWorldbookNames();
        if (Array.isArray(all)) bookNames = bookNames.concat(all);
      }
    } catch (e) { /* ignore */ }
    try {
      if (typeof th.getCharWorldbookNames === 'function') {
        const cur = th.getCharWorldbookNames('current');
        if (cur) {
          if (typeof cur.primary === 'string' && cur.primary) bookNames.push(cur.primary);
          if (Array.isArray(cur.additional)) bookNames = bookNames.concat(cur.additional);
        }
      }
    } catch (e) { /* ignore */ }
    bookNames = bookNames.map(b => String(b || '')).filter(Boolean).filter((v, i, a) => a.indexOf(v) === i);
    const seen = new Set();
    for (const bn of bookNames) {
      let entries = [];
      try { entries = await th.getWorldbook(bn); } catch (e) { continue; }
      if (!Array.isArray(entries)) continue;
      for (const en of entries) {
        if (!en || en.enabled === false) continue;
        const keys = Array.isArray(en.keys) ? en.keys : (en.strategy && Array.isArray(en.strategy.keys) ? en.strategy.keys : []);
        const keyMatch = keys.some(k => String(k || '').includes(n));
        const title = String(en.comment || en.name || '');
        const titleMatch = title.includes(n);
        if (!keyMatch && !titleMatch) continue;
        const contentStr = String(en.content || '').trim();
        if (!contentStr) continue;
        const dedupKey = bn + '::' + title + '::' + contentStr.slice(0, 40);
        if (seen.has(dedupKey)) continue;
        seen.add(dedupKey);
        parts.push('【世界书：' + bn + ' · ' + (title || '(未命名条目)') + '】\n关键字：' + (keys.length ? keys.join('、') : '（无）') + '\n' + contentStr);
      }
    }
    return parts;
  }

  // 解析 AI 返回的 JSON（容错：去除代码块围栏 / 提取首个 JSON 对象）
  function parseGeneratedCharacterProfile(text, fallbackName) {
    let s = String(text == null ? '' : text);
    s = s.replace(/```json/gi, '').replace(/```/g, '').trim();
    let obj = null;
    const start = s.indexOf('{');
    const end = s.lastIndexOf('}');
    if (start >= 0 && end > start) {
      const slice = s.slice(start, end + 1);
      try { obj = JSON.parse(slice); } catch (e) {
        try { obj = JSON.parse(slice.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']')); } catch (e2) { obj = null; }
      }
    }
    if (!obj || typeof obj !== 'object') obj = {};
    const pick = (k) => (obj[k] == null ? '' : String(obj[k]).trim());
    return {
      name: pick('name') || String(fallbackName || '').trim(),
      gender: pick('gender'),
      age: pick('age'),
      identity: pick('identity'),
      personality: pick('personality'),
      languageStyle: pick('languageStyle') || pick('style') || pick('说话风格'),
      attitude: pick('attitude'),
      brief: pick('brief')
    };
  }

  // 请求 AI 生成角色档案：优先使用「单独配置」的 API，未配置则回退游戏 API / 酒馆助手
  async function generateCustomCharacterProfile(name) {
    const n = String(name || '').trim();
    if (!n) throw new Error('角色名字不能为空');
    const bookParts = await collectCharacterWorldbookContext(n);
    const worldContext = bookParts.length
      ? bookParts.join('\n\n').slice(0, 14000)
      : '（未在世界书中检索到与该角色名相关的条目，请根据角色名合理创作，不要编造与已知设定冲突的内容）';
    const sys = [
      '你是一名角色设定师。请根据用户提供的角色名字，以及下方在「世界书」中检索到的、包含该角色名关键词的条目内容，为这个角色补全用于「自定义角色工作台」的设定。',
      '优先依据世界书提供的资料进行归纳；世界书没提到的部分可以合理发挥，但不得与其冲突。',
      '必须严格只输出一个 JSON 对象，不要输出任何解释、Markdown 代码块或多余文字。JSON 结构如下：',
      '{"name":"角色名字","gender":"男 或 女 或 保密","age":"年龄，未知则留空字符串","identity":"身份/职业背景","personality":"性格特质","languageStyle":"说话风格与口癖","attitude":"对主角的态度与关系","brief":"一句话简介"}',
      '所有字段都使用简体中文，语言精炼，贴合角色名与世界观。'
    ].join('\n');
    const user = '角色名字：' + n + '\n\n【世界书检索到的相关资料】：\n' + worldContext;
    const ccApi = loadCcGenApiConfig();
    const config = (ccApi.apiUrl && String(ccApi.apiUrl).trim()) ? ccApi : resolveApiConfig();
    const raw = await apiChat([
      { role: 'system', content: sys },
      { role: 'user', content: user }
    ], config, { maxTokens: 1200, temperature: 0.85 });
    return parseGeneratedCharacterProfile(raw, n);
  }

  // 从资料库（重要角色表 / 恋爱对象表 / 人物关系表）汇总角色理解信息，供 AI 理解角色
  function getCharacterDatabaseContext(name) {
    if (!name) return '';
    const parts = [];
    const prof = getCharacterProfile(name) || {};
    if (prof.brief) parts.push('简介：' + prof.brief);
    if (prof.identity && prof.identity !== '牌友') parts.push('身份：' + prof.identity);
    if (prof.age) parts.push('年龄：' + prof.age);
    if (prof.appearance) parts.push('外貌：' + prof.appearance);
    if (prof.attitude) parts.push('对主角态度：' + prof.attitude);
    try {
      const rels = getAllCharacterRelations().filter(r => isNameMatch(r.a, name) || isNameMatch(r.b, name));
      if (rels.length) {
        parts.push('人物关系：' + rels.slice(0, 8).map(r => relationSentenceForName(r, name)).join('；'));
      }
    } catch (e) { /* ignore */ }
    return parts.join('；') || '';
  }

  // 深度解析角色资料（身份、性格、语言风格、对主角态度等，优先自定义角色 → 重要角色表/恋爱对象表 → 内置角色池）
  function getCharacterProfile(name) {
    const cus = getCustomCharacterByName(name);
    if (cus) {
      return {
        name: cus.name, gender: cus.gender || '', age: cus.age || '', identity: cus.identity || '',
        personality: cus.personality || '', languageStyle: cus.languageStyle || '', attitude: cus.attitude || '',
        brief: cus.brief || '', appearance: cus.appearance || '', avatar: cus.avatar || ''
      };
    }
    const api = getAutoCardAPI();
    if (!api) return null;
    try {
      const all = api.exportTableAsJson();
      if (!all || typeof all !== 'object') return null;
      const targetSheetNames = ['恋爱对象表', '重要角色表'];
      for (const key of Object.keys(all)) {
        if (!key.startsWith('sheet_')) continue;
        const table = all[key];
        if (!table || !Array.isArray(table.content)) continue;
        if (!targetSheetNames.includes(table.name)) continue;
        const rows = table.content;
        if (rows.length < 2) continue;
        const header = rows[0];
        if (!Array.isArray(header)) continue;
        let nameIdx = header.findIndex(h => typeof h === 'string' && (h.includes('姓名') || h.includes('角色名') || h.includes('人物') || h.includes('名字')));
        if (nameIdx === -1) nameIdx = 0;
        
        const findColVal = (row, candidates) => {
          for (const cand of candidates) {
            const idx = header.findIndex(h => typeof h === 'string' && h.includes(cand));
            if (idx !== -1 && row[idx]) return String(row[idx]).trim();
          }
          return '';
        };

        for (let i = 1; i < rows.length; i++) {
          const row = rows[i];
          if (!Array.isArray(row)) continue;
          const rName = typeof row[nameIdx] === 'string' ? row[nameIdx].trim() : '';
          if (rName && isNameMatch(rName, name)) {
            const profile = {
              name: rName,
              gender: findColVal(row, ['性别']),
              age: findColVal(row, ['年龄', '生日']),
              identity: findColVal(row, ['身份', '身份背景', '职业', '关系', '定位']),
              personality: findColVal(row, ['性格', '性格特征', '性格特点']),
              languageStyle: findColVal(row, ['语言风格', '语言风格和口癖', '说话方式', '口癖']),
              attitude: findColVal(row, ['对主角态度', '对主角的态度', '态度', '好感度态度']),
              brief: findColVal(row, ['一句话介绍', '简介', '描述', '介绍']),
              appearance: findColVal(row, ['外貌', '外貌特征'])
            };
            return profile;
          }
        }
      }
      return null;
    } catch (e) {
      return null;
    }
  }

  // 读取神数据库中的《人物关系表》
  function getCharacterRelationsFromDB() {
    const api = getAutoCardAPI();
    if (!api) return [];
    try {
      const all = api.exportTableAsJson();
      if (!all || typeof all !== 'object') return [];
      for (const key of Object.keys(all)) {
        if (!key.startsWith('sheet_')) continue;
        const table = all[key];
        if (!table || table.name !== '人物关系表' || !Array.isArray(table.content)) continue;
        const rows = table.content;
        if (rows.length < 2) continue;
        const header = rows[0];
        if (!Array.isArray(header)) continue;
        const idxA = header.findIndex(h => typeof h === 'string' && (h.includes('人物A') || h.includes('角色A') || h.includes('主体')));
        const idxB = header.findIndex(h => typeof h === 'string' && (h.includes('人物B') || h.includes('角色B') || h.includes('客体')));
        const idxType = header.findIndex(h => typeof h === 'string' && (h.includes('关系类型') || h.includes('关系') || h.includes('定位')));
        const idxState = header.findIndex(h => typeof h === 'string' && (h.includes('当前状态') || h.includes('状态') || h.includes('描述') || h.includes('细节')));
        
        const relations = [];
        for (let i = 1; i < rows.length; i++) {
          const row = rows[i];
          if (!Array.isArray(row)) continue;
          const a = idxA !== -1 && row[idxA] ? String(row[idxA]).trim() : '';
          const b = idxB !== -1 && row[idxB] ? String(row[idxB]).trim() : '';
          const type = idxType !== -1 && row[idxType] ? String(row[idxType]).trim() : '';
          const state = idxState !== -1 && row[idxState] ? String(row[idxState]).trim() : '';
          if (a && b) {
            relations.push({ a, b, type, state });
          }
        }
        return relations;
      }
    } catch (e) { /* ignore */ }
    return [];
  }

  // 读取好友及真实立绘、身份标注（优先自定义角色 → 重要角色表 → 恋爱对象表）
  function loadContactsWithAvatars() {
    const customContacts = loadCustomCharacters().map(c => ({ name: c.name, avatar: c.avatar || getContactAvatarOverride(c.name) || '', identity: c.identity || c.brief || '' }));
    const api = getAutoCardAPI();
    if (!api) {
      return { contacts: customContacts, error: null };
    }
    const contacts = [];
    try {
      const allTables = api.exportTableAsJson();
      if (!allTables || typeof allTables !== 'object') return { contacts: [], error: 'invalid' };
      const sheets = {};
      for (const key of Object.keys(allTables)) {
        if (key.startsWith('sheet_')) {
          const table = allTables[key];
          if (table && typeof table === 'object' && Array.isArray(table.content) && table.name) {
            sheets[table.name] = table;
          }
        }
      }
      const targetTables = ['重要角色表', '恋爱对象表'];
      const seen = new Set();
      
      const tableNamesToScan = Object.keys(sheets).filter(tName => {
        return targetTables.includes(tName);
      });

      for (const tableName of tableNamesToScan) {
        const table = sheets[tableName];
        if (!table) continue;
        const rows = table.content;
        if (!Array.isArray(rows)) continue;
        const header = rows[0];
        if (!Array.isArray(header)) continue;
        let nameIdx = header.findIndex(h => typeof h === 'string' && (h.includes('姓名') || h.includes('角色名') || h.includes('人物') || h.includes('名字') || h.includes('称呼') || h.includes('角色') || h.toLowerCase().includes('name')));
        if (nameIdx === -1) nameIdx = 0;
        const avatarIdx = header.findIndex(h => isAvatarHeader(h));
        
        for (let i = 1; i < rows.length; i++) {
          const row = rows[i];
          if (!Array.isArray(row)) continue;
          const name = row[nameIdx];
          if (typeof name === 'string' && name.trim() && !seen.has(name.trim())) {
            const trimmedName = name.trim();
            seen.add(trimmedName);
            const ovAvatar = getContactAvatarOverride(trimmedName);
            let avatar = ovAvatar
              ? resolveAvatarUrl(ovAvatar)
              : ((avatarIdx !== -1 && typeof row[avatarIdx] === 'string' && row[avatarIdx].trim()) ? resolveAvatarUrl(row[avatarIdx].trim()) : '');
            if (!avatar) {
              avatar = getCharacterAvatarByName(trimmedName);
            }
            
            const prof = getCharacterProfile(trimmedName);
            const idStr = prof?.identity || prof?.brief || '';
            contacts.push({ name: trimmedName, avatar: avatar, identity: idStr });
          }
        }
      }
            return { contacts: customContacts.concat(contacts), error: null };
    } catch (e) {
      return { contacts: customContacts.concat(contacts), error: contacts.length ? null : 'exception' };
    }
  }

