      }).join('；');

      const publicLogs = (finishedGame.history || []).filter(line => {
        return !line.includes('<thinking>') && !line.includes('<private>');
      }).slice(-25);

      // 主角胜负与完整座位底牌：供"对主角的历史出招统计"（getUserTendencyStats）读取。
      // 旧记录没有这两个字段，统计侧会跳过它们，避免把胜率错误地算成 0%。
      let userWon = null;
      try {
        const user = (finishedGame.players || []).find(p => p && p.isUser) || (finishedGame.players || [])[finishedGame.userIndex];
        if (user && user.role) {
          const wolfWin = finishedGame.winner === '狼人阵营';
          userWon = (user.role === '狼人') ? wolfWin : !wolfWin;
        }
      } catch (e) { userWon = null; }
      const playersSnapshot = (finishedGame.players || []).map(p => ({
        name: p.name, isUser: !!p.isUser, role: p.role, alive: !!p.alive
      }));

      const matchRecord = {
        timestamp: Date.now(),
        winner: finishedGame.winner,
        totalDays: finishedGame.day,
        rolesDistribution: playersOverview,
        summaryLog: publicLogs.join('\n'),
        ...(userWon === null ? {} : { userWon: userWon }),
        players: playersSnapshot
      };

      historyList.push(matchRecord);
      while (historyList.length > 3) {
        historyList.shift();
      }
      localStorage.setItem(MATCH_HISTORY_KEY, JSON.stringify(historyList));
    } catch (e) { /* ignore */ }
  }

  function getPastMatchesSummaryPrompt() {
    const list = loadPastMatchesHistory();
    if (!list || list.length === 0) return '';
    const sections = list.map((m, idx) => {
      return `【历史第 ${idx + 1} 场完整对局复盘记录】（获胜阵营: ${m.winner}，共进行 ${m.totalDays} 天）：\n- 场上各席位真实底牌：\n  ${m.rolesDistribution}\n- 该局核心公开发言与投票过程复盘：\n${m.summaryLog}`;
    });
    return `\n\n【过往最近3场完整对局记录（供AI洞悉其他玩家在不同对局中的说话风格、表水习惯、撒谎破绽、站边态度与历史恩怨）】：\n${sections.join('\n\n')}\n`;
  }

  // ============================================================
  // ========== 对局结果注入：角色卡世界书绿灯条目 ==========
  // 任意游戏结束后统一调用 onGameFinished()，由本模块维护对局记录并生成联动。
  // ============================================================

  const GENERIC_MATCH_HISTORY_KEY = 'werewolf_extension_generic_match_history';
  const POINTS_KEY = 'werewolf_extension_points';
  const SHOP_INVENTORY_KEY = 'werewolf_extension_shop_inventory';
  const DAILY_SIGNIN_KEY = 'werewolf_extension_daily_signin';
  const IDENTITY_CARD_TYPES = [
    { key: 'wolf', name: '狼人卡', role: '狼人', icon: '🐺', price: 5, color: '#F44336', desc: '开局指定身份为狼人，或用于邀请其他角色成为狼人队友' },
    { key: 'witch', name: '女巫卡', role: '女巫', icon: '🧪', price: 5, color: '#2196F3', desc: '开局指定身份为女巫（解药/毒药各一瓶）' },
    { key: 'seer', name: '预言家卡', role: '预言家', icon: '🔮', price: 5, color: '#8B5CF6', desc: '开局指定身份为预言家（每晚查验一人）' },
    { key: 'villager', name: '村民卡', role: '民', icon: '👤', price: 5, color: '#4CAF50', desc: '开局指定身份为村民（无技能，靠推理取胜）' },
    { key: 'hunter', name: '猎人卡', role: '猎人', icon: '🎯', price: 5, color: '#F97316', desc: '开局指定身份为猎人（9/12人场）：被投票放逐或被狼人夜杀出局时可开枪带走 1 人；被女巫毒死则无法开枪' },
    { key: 'guard', name: '守卫卡', role: '守卫', icon: '🛡️', price: 5, color: '#0EA5E9', desc: '开局指定身份为守卫（12人场专属）：每晚守护 1 人使其免疫狼刀，可自守，不能连续两晚守护同一人' }
  ];
  // 观战卡：狼人杀板子选择界面使用，邀请 6 位角色以上帝视角观战
  const SPECTATOR_CARD = { key: 'spectator', name: '观战卡', role: '', icon: '👁️', price: 10, color: '#0EA5E9', desc: '在狼人杀邀请角色界面勾选使用：邀请对应人数的角色开局，你以上帝视角观战，可看到所有身份与夜间行动' };
  const SHOP_ITEMS = IDENTITY_CARD_TYPES.concat([SPECTATOR_CARD]);

  // ========== 积分系统（除斗地主外：胜 +1 / 负 -1，可为负） ==========
  function loadPoints() {
    try {
      const raw = localStorage.getItem(POINTS_KEY);
      const n = raw === null ? 0 : parseInt(raw, 10);
      return Number.isFinite(n) ? n : 0;
    } catch (e) { return 0; }
  }
  function savePoints(n) {
    try { localStorage.setItem(POINTS_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
    return loadPoints();
  }
  function addPoints(delta) {
    const next = loadPoints() + (Math.round(Number(delta) || 0));
    savePoints(next);
    return next;
  }
  function pointsLabelHTML(extraStyle) {
    const p = loadPoints();
    return '<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:999px;background:rgba(245,158,11,0.14);border:1px solid rgba(245,158,11,0.5);font-size:11.5px;font-weight:600;color:#F59E0B;' + (extraStyle || '') + '">💎 积分 ' + p + '</span>';
  }

  // ========== 筹码系统（炸金花 / 21点 / 德州扑克 · 有筹码就能一直玩 + 积分联动） ==========
  const CHIPS_WALLET_KEY = 'werewolf_extension_chips_wallet';
  const CHIP_PER_POINT = 100;        // 汇率：1 积分 = 100 筹码（想改兑换比例只改这里）
  const ZJH_START_CHIPS = 300;       // 炸金花首次进入的启动筹码
  const ZJH_MIN_CHIPS = 5;           // 炸金花底注（低于它不能开局）
  const MJ_START_CHIPS = 300;        // 麻将首次进入的启动筹码（赌注结算用）
  const DDZ_START_CHIPS = 300;       // 斗地主首次进入的启动筹码（赌注结算用）
  const CHIP_GAME_NAMES = { zjh: '炸金花', blackjack: '21点', holdem: '德州扑克', mahjong: '麻将', doudizhu: '斗地主' };

  // 主角在这两个游戏的跨局筹码（null = 尚未加载，从钱包读取）
  let zjhBankroll = null;
  let thBankroll = null;

  function loadChipWallet() {
    const out = { zjh: 0, blackjack: 0, holdem: 0, mahjong: 0, doudizhu: 0, init: {} };
    try {
      const raw = localStorage.getItem(CHIPS_WALLET_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (p && typeof p === 'object') {
          out.init = (p.init && typeof p.init === 'object') ? p.init : {};
          for (const k of ['zjh', 'blackjack', 'holdem', 'mahjong', 'doudizhu']) {
            const v = parseInt(p[k], 10);
            out[k] = (Number.isFinite(v) && v > 0) ? v : 0;
          }
        }
      }
    } catch (e) { /* ignore */ }
    return out;
  }
  function saveChipWallet(w) {
    try {
      localStorage.setItem(CHIPS_WALLET_KEY, JSON.stringify({
        zjh: Math.max(0, Math.round(Number(w && w.zjh) || 0)),
        blackjack: Math.max(0, Math.round(Number(w && w.blackjack) || 0)),
        holdem: Math.max(0, Math.round(Number(w && w.holdem) || 0)),
        mahjong: Math.max(0, Math.round(Number(w && w.mahjong) || 0)),
        doudizhu: Math.max(0, Math.round(Number(w && w.doudizhu) || 0)),
        init: (w && w.init && typeof w.init === 'object') ? w.init : {}
      }));
    } catch (e) { /* ignore */ }
    return loadChipWallet();
  }
  function getChips(gameKey) { return loadChipWallet()[gameKey] || 0; }
  function setChips(gameKey, n) {
    const w = loadChipWallet();
    if (!(gameKey in w)) return 0;
    w[gameKey] = Math.max(0, Math.round(Number(n) || 0));
    saveChipWallet(w);
    return w[gameKey];
  }
  function addChips(gameKey, delta) { return setChips(gameKey, getChips(gameKey) + (Math.round(Number(delta) || 0))); }

  // 首次进入某游戏发一笔启动筹码（只发一次；输光后不再自动补，必须用积分兑换）
  function ensureStartChips(gameKey, startChips) {
    const w = loadChipWallet();
    if (!w.init[gameKey]) {
      w.init[gameKey] = true;
      if ((w[gameKey] || 0) <= 0) w[gameKey] = Math.max(0, Math.round(Number(startChips) || 0));
      saveChipWallet(w);
    }
    return w[gameKey] || 0;
  }

  // 当前该游戏「正在使用」的筹码：优先取对局内实时余额，其次取钱包
  function chipBankOf(gameKey) {
    if (gameKey === 'mahjong') return ensureStartChips('mahjong', MJ_START_CHIPS);
    if (gameKey === 'doudizhu') return ensureStartChips('doudizhu', DDZ_START_CHIPS);
    if (gameKey === 'zjh') {
      if (zjhBankroll === null || !Number.isFinite(zjhBankroll)) zjhBankroll = ensureStartChips('zjh', ZJH_START_CHIPS);
      return zjhBankroll;
    }
    if (gameKey === 'holdem') {
      if (thBankroll === null || !Number.isFinite(thBankroll)) thBankroll = ensureStartChips('holdem', TH_START_CHIPS);
      return thBankroll;
    }
    if (bjGame && bjGame.phase !== 'sessionEnd' && bjGame.phase !== 'idle') return bjGame.chips;
    return ensureStartChips('blackjack', loadBjConfig().chips);
  }

  // 钱包变化后同步到内存里的对局余额（保证买卖筹码后界面立刻正确）
  function syncChipBalance(gameKey) {
    const v = getChips(gameKey);
    if (gameKey === 'zjh') zjhBankroll = v;
    else if (gameKey === 'holdem') thBankroll = v;
    else if (gameKey === 'blackjack') {
      if (bjGame && bjGame.phase !== 'sessionEnd' && bjGame.phase !== 'idle') bjGame.chips = v;
    }
    return v;
  }

  // 积分 → 筹码
  function buyChipsWithPoints(gameKey, points) {
    const p = Math.max(1, Math.round(Number(points) || 1));
    const cur = loadPoints();
    if (cur < p) return { ok: false, msg: '积分不足（需要 ' + p + '，当前 ' + cur + '）' };
    addPoints(-p);
    const got = p * CHIP_PER_POINT;
    const total = addChips(gameKey, got);
    syncChipBalance(gameKey);
    return { ok: true, spent: p, got: got, total: total };
  }
  // 筹码 → 积分（每 CHIP_PER_POINT 筹码 = 1 积分，余数留在钱包）
  function cashOutChips(gameKey) {
    const chips = getChips(gameKey);
    const pts = Math.floor(chips / CHIP_PER_POINT);
    if (pts <= 0) return { ok: false, msg: '至少要有 ' + CHIP_PER_POINT + ' 筹码才能兑现（当前 ' + chips + '）' };
    setChips(gameKey, chips - pts * CHIP_PER_POINT);
    addPoints(pts);
    syncChipBalance(gameKey);
    return { ok: true, pts: pts, left: getChips(gameKey) };
  }

  function chipsLabelHTML(gameKey, extraStyle) {
    return '<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:999px;background:rgba(16,185,129,0.14);border:1px solid rgba(16,185,129,0.5);font-size:11.5px;font-weight:600;color:#10B981;' + (extraStyle || '') + '">🪙 筹码 ' + getChips(gameKey) + '</span>';
  }

  // 大厅里的「我的筹码」卡片（带兑换 / 兑现入口）
  function chipCardHTML(gameKey, minChips, tip) {
    const bank = chipBankOf(gameKey);
    const ok = bank >= minChips;
    return '' +
      '<div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:10px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;">' +
      '<span style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">🪙 我的筹码</span>' +
      '<span style="font-size:16px;font-weight:800;color:' + (ok ? '#10B981' : '#EF4444') + ';">' + bank + '</span></div>' +
      '<div style="font-size:11px;color:var(--ubp-text-3);margin-top:4px;line-height:1.5;">' +
      (tip ? tip + ' · ' : '') + '有筹码就能一直玩（对局保留日志与对话，点【退出】时统一结算回钱包）· 汇率 1 积分 = ' + CHIP_PER_POINT + ' 筹码</div>' +
      '<div style="display:flex;gap:6px;margin-top:8px;">' +
      '<button data-ubp-act="chip-exchange" data-chip-game="' + gameKey + '" class="ubp-btn" style="flex:1;padding:5px 0;font-size:12px;">💎 兑换 / 兑现筹码</button>' +
      '</div>' +
      (ok ? '' : '<div style="font-size:11.5px;color:#EF4444;margin-top:6px;">⚠️ 筹码不足 ' + minChips + '，请先用积分兑换筹码再开局</div>') +
      '</div>';
  }

  // 筹码兑换 / 兑现面板（三个游戏通用）
  function renderChipExchange(gameKey, onDone) {
    const old = sheet && sheet.querySelector('.chip-exchange-overlay');
    if (old) old.remove();
    const ov = document.createElement('div');
    ov.className = 'chip-exchange-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:72;background:rgba(0,0,0,0.72);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    const render = () => {
      const chips = getChips(gameKey);
      const pts = loadPoints();
      const gname = CHIP_GAME_NAMES[gameKey] || '游戏';
      const opts = [1, 5, 10, 50];
      ov.innerHTML =
        '<div style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:16px 14px;width:100%;max-width:310px;box-shadow:0 10px 28px rgba(0,0,0,0.55);">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">' +
        '<span style="font-size:15px;font-weight:700;color:var(--ubp-text);">🪙 ' + escapeHtml(gname) + ' · 筹码</span>' +
        '<button data-chip-act="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
        '<div style="display:flex;gap:6px;margin-bottom:9px;">' +
        '<div style="flex:1;background:var(--ubp-card-2);border-radius:9px;padding:7px 9px;text-align:center;">' +
        '<div style="font-size:10.5px;color:var(--ubp-text-3);">当前筹码</div>' +
        '<div style="font-size:16px;font-weight:800;color:#10B981;">' + chips + '</div></div>' +
        '<div style="flex:1;background:var(--ubp-card-2);border-radius:9px;padding:7px 9px;text-align:center;">' +
        '<div style="font-size:10.5px;color:var(--ubp-text-3);">我的积分</div>' +
        '<div style="font-size:16px;font-weight:800;color:#F59E0B;">' + pts + '</div></div></div>' +
        '<div style="font-size:11.5px;color:var(--ubp-text-2);line-height:1.6;margin-bottom:9px;">' +
        '汇率：<b style="color:#F59E0B;">1 积分 = ' + CHIP_PER_POINT + ' 筹码</b>；兑现时每 ' + CHIP_PER_POINT + ' 筹码 = 1 积分（余数留在钱包）。<br>有筹码就能一直玩，输光后需重新用积分兑换。</div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px;">' +
        opts.map(p => '<button data-chip-act="buy" data-points="' + p + '" class="ubp-btn" style="flex:1;min-width:64px;padding:7px 0;font-size:12px;' + (pts >= p ? '' : 'opacity:0.45;pointer-events:none;') + '">💎 ' + p + ' → ' + (p * CHIP_PER_POINT) + '</button>').join('') +
        '</div>' +
        '<div style="display:flex;gap:6px;">' +
        '<button data-chip-act="cashout" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12.5px;' + (chips >= CHIP_PER_POINT ? '' : 'opacity:0.45;pointer-events:none;') + '">🏦 兑现为积分</button>' +
        '<button data-chip-act="close" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:12.5px;background:#10B981;border:none;">完成</button>' +
        '</div></div>';
      ov.querySelectorAll('[data-chip-act]').forEach(el => {
        el.addEventListener('click', () => {
          const a = el.dataset.chipAct;
          if (a === 'close') { ov.remove(); if (typeof onDone === 'function') onDone(); return; }
          if (a === 'buy') {
            const r = buyChipsWithPoints(gameKey, parseInt(el.dataset.points, 10) || 1);
            if (!r.ok) { showToast('💎 ' + r.msg); return; }
            showToast('🪙 兑换成功：-' + r.spent + ' 积分，+' + r.got + ' 筹码（共 ' + r.total + '）');
            render();
            return;
          }
          if (a === 'cashout') {
            const r = cashOutChips(gameKey);
            if (!r.ok) { showToast('🏦 ' + r.msg); return; }
            showToast('🏦 兑现成功：+' + r.pts + ' 积分（剩余筹码 ' + r.left + '）');
            render();
            return;
          }
        });
      });
    };
    render();
    sheet.appendChild(ov);
  }

  // ========== 每日签到（按数据库当前时间判断新的一天） ==========
  function getStoryTimeText() {
    try {
      const api = getAutoCardAPI();
      if (api && typeof api.exportTableAsJson === 'function') {
        const all = api.exportTableAsJson();
        if (all && typeof all === 'object') {
          for (const key of Object.keys(all)) {
            const table = all[key];
            if (!table || !Array.isArray(table.content)) continue;
            if (String(table.name || '') !== '全局数据表') continue;
            const rows = table.content;
            if (rows.length < 2 || !Array.isArray(rows[0])) continue;
            const idx = rows[0].findIndex(h => String(h || '').includes('当前时间'));
            if (idx === -1) continue;
            for (let r = 1; r < rows.length; r++) {
              const v = rows[r] && rows[r][idx];
              if (v !== undefined && v !== null && String(v).trim()) return String(v).trim();
            }
          }
        }
      }
    } catch (e) { /* ignore */ }
    return '';
  }

  function getStoryDayKey() {
    const rawText = getStoryTimeText();
    if (rawText) {
      let m = rawText.match(/第\s*([0-9一二三四五六七八九十百千两]+)\s*[天日]/);
      if (m) return 'day:' + m[1];
      m = rawText.match(/(\d{4})\s*[年\/\.\-]\s*(\d{1,2})\s*[月\/\.\-]\s*(\d{1,2})/);
      if (m) return 'date:' + m[1] + '-' + parseInt(m[2], 10) + '-' + parseInt(m[3], 10);
      return 'raw:' + rawText.replace(/\s+/g, '').slice(0, 24);
    }
    const d = new Date();
    return 'real:' + d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate();
  }

  function isSignedInToday() {
    try { return localStorage.getItem(DAILY_SIGNIN_KEY) === getStoryDayKey(); } catch (e) { return false; }
  }

  function signInToday() {
    if (isSignedInToday()) return false;
    try { localStorage.setItem(DAILY_SIGNIN_KEY, getStoryDayKey()); } catch (e) { /* ignore */ }
    addPoints(10);
    return true;
  }

  function signInButtonHTML() {
    const signed = isSignedInToday();
    if (signed) {
      return '<button data-ubp-act="daily-signin" title="数据库时间进入新的一天后可再次签到" style="display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:999px;background:rgba(148,163,184,0.18);border:1px solid rgba(148,163,184,0.45);font-size:11.5px;font-weight:600;color:#94A3B8;cursor:default;">✅ 已签到</button>';
    }
    return '<button data-ubp-act="daily-signin" title="每日签到可获得 10 积分" style="display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:999px;background:rgba(16,185,129,0.16);border:1px solid rgba(16,185,129,0.55);font-size:11.5px;font-weight:700;color:#10B981;cursor:pointer;">📅 签到 +10</button>';
  }

  // ========== 积分商城库存（身份卡） ==========
  function loadShopInventory() {
    const inv = { wolf: 0, witch: 0, seer: 0, villager: 0, hunter: 0, guard: 0, spectator: 0 };
    try {
      const raw = localStorage.getItem(SHOP_INVENTORY_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed === 'object') {
          IDENTITY_CARD_TYPES.forEach(t => {
            const v = parseInt(parsed[t.key], 10);
            if (Number.isFinite(v) && v > 0) inv[t.key] = Math.min(99, v);
          });
          const sv = parseInt(parsed.spectator, 10);
          if (Number.isFinite(sv) && sv > 0) inv.spectator = Math.min(99, sv);
        }
      }
    } catch (e) { /* ignore */ }
    return inv;
  }
  function saveShopInventory(inv) {
    try { localStorage.setItem(SHOP_INVENTORY_KEY, JSON.stringify(inv || {})); } catch (e) { /* ignore */ }
    return loadShopInventory();
  }
  function addIdentityCard(key, count) {
    const inv = loadShopInventory();
    if (!(key in inv)) return inv;
    inv[key] = Math.max(0, Math.min(99, (inv[key] || 0) + (Math.round(Number(count) || 1))));
    return saveShopInventory(inv);
  }
  function consumeIdentityCard(key, count) {
    const inv = loadShopInventory();
    const need = Math.max(1, Math.round(Number(count) || 1));
    if (!(key in inv) || (inv[key] || 0) < need) return false;
    inv[key] = inv[key] - need;
    saveShopInventory(inv);
    return true;
  }

  // 触发世界书绿灯条目注入的关键词
  const WORLD_BOOK_KEYWORDS = ['游戏', '小游戏', '手机游戏', '游戏中心', '下棋', '对弈', '狼人杀', '谁是卧底', '剧本杀', '象棋', '五子棋', '斗兽棋', '国际象棋', '将棋', '石头剪刀布', '斗地主', '打牌', '欺诈酒馆', '欺诈', '吹牛', '左轮', '触发对局', '桌游', '飞行棋', '大富翁'];

  // 世界书绿灯条目唯一标识（写入 character_book 时用于定位/覆盖）
  const WORLD_BOOK_ENTRY_NAME = '小游戏对局记录';
  const WORLD_BOOK_ENTRY_COMMENT = '[酒馆悬浮窗游戏中心]小游戏对局记录';

  // 世界书绿灯条目固定 UID（用于 runtime worldInfo 注入与持久化定位）
  const WORLD_BOOK_ENTRY_UID = 1924763011;

  // ===== 狼人杀 / 谁是卧底「完整注入」专用对局记录世界书 =====
  // 开启「对局记录设置 → 狼人杀/谁是卧底对局完整注入」后：
  //   1. 该游戏的对局（含完整回放）写入这里配置的独立世界书，并自动绑定为当前角色的额外世界书；
  //   2. 不再注入【游戏】对局记录（角色卡绿灯条目 / [游戏]对局记录）。
  // 关闭后：仅停用专用世界书里的记录条目（不删除世界书），恢复向【游戏】对局记录注入精简结果。
  const DEDICATED_RECORD_BOOKS = {
    werewolf: { book: '狼人杀对局录入', entry: '狼人杀对局录入' },
    spy: { book: '谁是卧底对局录入', entry: '谁是卧底对局录入' }
  };

  // 所有游戏类型统一保留最近 3 场完整对局记录（含回放/高光/复盘/朋友圈）
  const DEDUCTION_GAME_TYPES = ['werewolf', 'spy', 'murder'];

  function isDeductionGame(gameType) {
    return DEDUCTION_GAME_TYPES.includes(gameType);
  }

  // 游戏类型展示顺序（已知类型在前，未知类型追加在后）
  const GAME_TYPE_ORDER = ['gomoku', 'xiangqi', 'jungle', 'chess', 'shogi', 'battleship', 'go', 'luzhanqi', 'othello', 'rps', 'ttt', 'minesweeper', 'blackjack', 'doudizhu', 'liar', 'ludo', 'richman', 'mahjong', 'zjh', 'holdem', 'uno', 'werewolf', 'spy', 'murder'];

  function normalizeHistoryLimits(store) {
    const out = {};
    for (const key of Object.keys(store || {})) {
      const list = Array.isArray(store[key]) ? store[key] : [];
      if (!list.length) continue;
      const max = 3;
      out[key] = list.slice(-max);
    }
    return out;
  }

  // ========== 通用对局历史存取（每种游戏单独留存最近 3 场） ==========
  function loadGenericMatchHistory() {
    try {
      const raw = localStorage.getItem(GENERIC_MATCH_HISTORY_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        // 新版：带版本号 { v:2, g:{ 游戏类型: [记录] } }（避免与 chess 等游戏类型键冲突导致误迁移）
        if (parsed && parsed.v === 2 && parsed.g && typeof parsed.g === 'object') {
          return normalizeHistoryLimits(parsed.g);
        }
        if (Array.isArray(parsed)) {
          // 兼容旧版扁平数组
          const store = {};
          parsed.forEach(m => { if (m && m.gameType) { (store[m.gameType] = store[m.gameType] || []).push(m); } });
          return normalizeHistoryLimits(store);
        }
        if (parsed && typeof parsed === 'object') {
          // 兼容旧版 { chess:[], deduction:[] }（分类值，非游戏类型）
          const store = {};
          (Array.isArray(parsed.chess) ? parsed.chess : []).forEach(m => { if (m && m.gameType) { (store[m.gameType] = store[m.gameType] || []).push(m); } });
          (Array.isArray(parsed.deduction) ? parsed.deduction : []).forEach(m => { if (m && m.gameType) { (store[m.gameType] = store[m.gameType] || []).push(m); } });
          return normalizeHistoryLimits(store);
        }
      }
    } catch (e) { /* ignore */ }
    return {};
  }

  function saveGenericMatchHistory(store) {
    try {
      localStorage.setItem(GENERIC_MATCH_HISTORY_KEY, JSON.stringify({ v: 2, g: normalizeHistoryLimits(store) }));
    } catch (e) { /* ignore */ }
  }

  // 记录一场对局（按游戏类型单独留存最近 3 场）
  function recordGenericMatch(match) {
    if (!match || !match.gameType) return;
    const store = loadGenericMatchHistory();
    const max = 3;
    const list = Array.isArray(store[match.gameType]) ? store[match.gameType] : [];
    list.push({ ...match, timestamp: match.timestamp || Date.now() });
    while (list.length > max) list.shift();
    store[match.gameType] = list;
    saveGenericMatchHistory(store);
    if (loadConfig().worldBookLink !== false) {
      syncWorldBookEntry();
    }
    // 狼人杀 / 谁是卧底开启「完整注入」时同步各自的专用世界书
    syncDedicatedRecordBooks();
  }

  // 回填/更新某场对局的附加字段（高光播报、赛后复盘、朋友圈等）
  function updateGenericMatchRecord(gameType, recordId, patch) {
    if (!gameType || !patch) return false;
    const store = loadGenericMatchHistory();
    const list = Array.isArray(store[gameType]) ? store[gameType] : [];
    let rec = null;
    if (recordId) rec = list.find(m => m && m.id === recordId) || null;
    if (!rec) rec = list[list.length - 1] || null;
    if (!rec) return false;
    Object.assign(rec, patch);
    store[gameType] = list;
    saveGenericMatchHistory(store);
    if (loadConfig().worldBookLink !== false) {
      syncWorldBookEntry();
    }
    // 狼人杀 / 谁是卧底开启「完整注入」时同步各自的专用世界书
    syncDedicatedRecordBooks();
    return true;
  }

  // 将回放日志格式化为可读文本（供世界书绿灯条目 / 对局记录界面读取）
  function formatReplayAsText(entries) {
    if (!Array.isArray(entries) || !entries.length) return '';
    const lines = [];
    for (const e of entries) {
      if (e == null) continue;
      const text = typeof e === 'object' ? (e.text || '') : String(e);
      const clean = String(text).replace(/<[^>]+>/g, '').replace(/\n+/g, ' ').trim();
      if (clean) lines.push(clean);
    }
    return lines.slice(-80).join('\n');
  }

  function getGameTypeDisplayName(gameType) {
    const typeNameMap = { gomoku: '五子棋', xiangqi: '象棋', jungle: '斗兽棋', chess: '国际象棋', shogi: '将棋', battleship: '海战棋', werewolf: '狼人杀', spy: '谁是卧底', rps: '石头剪刀布', murder: '剧本杀', doudizhu: '斗地主', liar: '欺诈酒馆', mahjong: '麻将', zjh: '炸金花', holdem: '德州扑克', uno: 'UNO', go: '围棋', luzhanqi: '军棋', othello: '黑白棋', minesweeper: '扫雷', blackjack: '21点', tetris: '俄罗斯方块', ttt: '井字棋', ludo: '飞行棋', richman: '大富翁' };
    return typeNameMap[gameType] || gameType || '桌游';
  }

  function listKnownGameTypes(store) {
    const keys = Object.keys(store || {}).filter(k => (store[k] || []).length > 0);
    const known = GAME_TYPE_ORDER.filter(k => keys.includes(k));
    const unknown = keys.filter(k => !GAME_TYPE_ORDER.includes(k)).sort();
    return known.concat(unknown);
  }

  // 生成世界书条目正文（供 AI 读取，只陈述胜负事实，不含情绪）
  // 狼人杀 / 谁是卧底：只注入「结果 + 详情」，不再注入全景复盘（回放仅供界面查看）
  const WORLD_BOOK_NO_REPLAY_TYPES = { werewolf: true, spy: true };
  function buildWorldBookContent() {
    const store = loadGenericMatchHistory();
    const types = listKnownGameTypes(store);
    if (!types.length) return '';
    // 开启「完整注入」的游戏不再写入本【游戏】对局记录，改由专用世界书承载；
    // 酒馆助手不可用（无法创建/绑定专用世界书）时保持原样兜底，避免记录凭空消失
    const th = getTavernHelperApi();
    const canDedicated = !!(th && typeof th.getWorldbookNames === 'function' && typeof th.createWorldbook === 'function'
      && typeof th.rebindCharWorldbooks === 'function' && typeof th.updateWorldbookWith === 'function'
      && typeof th.getWorldbook === 'function' && typeof th.createWorldbookEntries === 'function');
    const cfg = loadConfig();
    const skipFullInject = {
      werewolf: canDedicated && cfg.wolfFullInject === true,
      spy: canDedicated && cfg.spyFullInject === true
    };
    const MAX_LEN = 4000;
    const lines = [];
    for (const gameType of types) {
      if (skipFullInject[gameType]) continue;
      const list = store[gameType] || [];
      const title = getGameTypeDisplayName(gameType);
      list.forEach((m, i) => {
        const when = m.timestamp ? `（${new Date(m.timestamp).toLocaleString('zh-CN', { hour12: false })}）` : '';
        const result = m.result || '';
        const detail = m.detail || '';
        const points = (typeof m.pointsDelta === 'number' && m.pointsDelta !== 0)
          ? `\n  积分：${m.pointsDelta > 0 ? '+' : ''}${m.pointsDelta}${typeof m.pointsTotal === 'number' ? '（累计 ' + m.pointsTotal + '）' : ''}`
          : '';
        const replayText = (!WORLD_BOOK_NO_REPLAY_TYPES[gameType] && m.replay) ? String(m.replay).replace(/<[^>]+>/g, '').replace(/\n+/g, ' ').trim() : '';
        const replay = replayText ? `\n  对局回放：${replayText.slice(0, 600)}${replayText.length > 600 ? '…' : ''}` : '';
        lines.push(`【${title}第${i + 1}场】${result}${when}${detail ? '\n  ' + detail : ''}${points}${replay}`);
      });
    }
    let text = `以下为主角最近参与的小游戏对局胜负记录（由游戏系统自动记录，仅陈述客观结果，情感与反应由 AI 依据角色人设自行生成）：\n${lines.join('\n')}`;
    if (text.length > MAX_LEN) text = text.slice(0, MAX_LEN) + '\n…（更多历史对局详情请查看【对局记录】）';
    return text;
  }


  // 世界书条目结构（新版 SillyTavern：strategy / position / recursion 对象 + 兼容旧字段）
  function buildWorldBookEntry() {
    const content = buildWorldBookContent();
    const enabled = !!content;
    const strategies = { type: 'constant', keys: WORLD_BOOK_KEYWORDS.slice() };
    const position = { type: 'at_depth', depth: 0, role: 'system', order: 100 };
    const recursion = { prevent_incoming: true, prevent_outgoing: true, delay_until: null };
    return {
      uid: WORLD_BOOK_ENTRY_UID,
      name: WORLD_BOOK_ENTRY_NAME,
      comment: WORLD_BOOK_ENTRY_COMMENT,
      enabled: enabled,
      content: content,
      strategy: strategies,
      position: position,
      recursion: recursion,
      addMemo: true,
      triggers: [],
      // 兼容旧版字段
      key: WORLD_BOOK_KEYWORDS,
      keys: WORLD_BOOK_KEYWORDS.slice(),
      secondary_keys: [],
      constant: true,
      selective: false,
      disabled: !enabled,
      order: 100,
      disable: !enabled,
      exclude_recursion: false,
      prevent_recursion: false,
      delay_until_recursion: false,
      probability: 100,
      useProbability: true,
      depth: 4,
      group: '对局记录',
      group_override: false,
      group_weight: 100,
      global: false,
      caseSensitive: false,
      automation_id: '',
      role: 'system'
    };
  }

  // 获取当前激活角色名（多来源兜底）
  function getActiveCharacterName() {
    try {
      const sts = [window.SillyTavern, window.parent?.SillyTavern, window.TavernHelper?.SillyTavern, window.parent?.TavernHelper?.SillyTavern];
      for (const st of sts) {
        if (!st) continue;
        try {
          if (typeof st.name2 === 'function') { const n = st.name2(); if (n && n !== 'unified-statusbar') return n; }
          else if (typeof st.name2 === 'string' && st.name2 && st.name2 !== 'unified-statusbar') return st.name2;
        } catch (e) { /* ignore */ }
      }
      const ctx = getTavernContext();
      if (ctx) {
        if (typeof ctx.name2 === 'string' && ctx.name2) return ctx.name2;
        if (ctx.name2 && typeof ctx.name2 === 'function') { const n = ctx.name2(); if (n) return n; }
        if (Array.isArray(ctx.characters) && ctx.characters.length) {
          const cid = ctx.characterId;
          if ((typeof cid === 'number' || /^\d+$/.test(String(cid))) && Number(cid) >= 0 && Number(cid) < ctx.characters.length) {
            const c = ctx.characters[Number(cid)];
            if (c && typeof c.name === 'string') return c.name;
            if (c && typeof c.data?.name === 'string') return c.data.name;
          }
          const c0 = ctx.characters[0];
          if (c0 && typeof c0.name === 'string') return c0.name;
          if (c0 && typeof c0.data?.name === 'string') return c0.data.name;
        }
      }
    } catch (e) { /* ignore */ }
    return '';
  }

  // 定位/读取当前角色卡 (SillyTavern)
  function getCurrentCharacter() {
    try {
      const ctx = getTavernContext();
      if (!ctx) return { charData: null, ctx: null };
      const chars = Array.isArray(ctx.characters) ? ctx.characters : [];
      if (!chars.length) return { charData: null, ctx: null };

      let charData = null;
      const cid = ctx.characterId;
      if (typeof cid === 'number' || /^\d+$/.test(String(cid))) {
        const idx = Number(cid);
        if (idx >= 0 && idx < chars.length) charData = chars[idx];
      }
      if (!charData && (typeof cid === 'string' && cid)) {
        charData = chars.find(c => c && (c.name === cid || c.data?.name === cid));
      }
      if (!charData) {
        const nm = getActiveCharacterName();
        if (nm) charData = chars.find(c => c && (c.name === nm || c.data?.name === nm));
      }
      if (!charData) charData = chars[0] || null;

      return { charData, ctx };
    } catch (e) {
      return { charData: null, ctx: null };
    }
  }

  // ========== 「消息记录注入世界书」：把对局胜负详情写入角色主世界书 ==========
  // 是"读角色主世界书 → 有则 updateWorldbookWith / 无则 createWorldbookEntries"，
  // 这里用同一套酒馆助手接口写一条 [游戏]对局记录，清空时 deleteWorldbookEntries 硬删。
  const GAME_WB_ENTRY_NAME = '[游戏]对局记录';

  function getTavernHelperApi() {
    try {
      const cands = [window.TavernHelper, window.parent?.TavernHelper, window.top?.TavernHelper];
      for (const t of cands) {
        if (!t) continue;
        if (typeof t.getCharWorldbookNames === 'function' && typeof t.getWorldbook === 'function'
          && typeof t.createWorldbookEntries === 'function' && typeof t.updateWorldbookWith === 'function') return t;
      }
    } catch (e) { /* ignore */ }
    return null;
  }

  async function syncWorldBookEntryViaHelper(content) {
    const th = getTavernHelperApi();
    if (!th) return false;
    try {
      const names = th.getCharWorldbookNames('current');
      const book = (names && typeof names.primary === 'string' && names.primary) ? names.primary : '';
      if (!book) return false; // 角色未绑定主世界书：跳过（角色卡 character_book 通道仍然生效）
      const entries = await th.getWorldbook(book);
      if (!Array.isArray(entries)) return false;
      const found = entries.find(e => String(e?.name ?? e?.comment ?? '') === GAME_WB_ENTRY_NAME);
      if (!content) {
        if (found && typeof th.deleteWorldbookEntries === 'function') {
          await th.deleteWorldbookEntries(book, e => String(e?.name ?? e?.comment ?? '') === GAME_WB_ENTRY_NAME);
        }
        return true;
      }
      if (found) {
        if (String(found.content ?? '') !== content) {
          await th.updateWorldbookWith(book, list => (Array.isArray(list) ? list : []).map(e => String(e?.name ?? e?.comment ?? '') === GAME_WB_ENTRY_NAME ? { ...e, content: content } : e));
        }
        return true;
      }
      await th.createWorldbookEntries(book, [{
        name: GAME_WB_ENTRY_NAME,
        enabled: true,
        strategy: { type: 'constant', keys: WORLD_BOOK_KEYWORDS.slice(), keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
        position: { type: 'at_depth', role: 'system', depth: 0, order: 101 },
        recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
        content: content
      }], { render: 'immediate' });
      return true;
    } catch (e) {
      console.warn('[游戏扩展] 酒馆助手世界书注入失败（不影响角色卡通道）:', e);
      return false;
    }
  }
  // 写回当前角色卡世界书绿灯条目（持久化 + 运行时 worldInfo 立即注入）
  async function syncWorldBookEntry() {
    const cfg = loadConfig();
    if (cfg.worldBookLink === false) { removeWorldBookEntry(); return; }
    const { charData, ctx } = getCurrentCharacter();
    const entry = buildWorldBookEntry();
    const contentEmpty = !entry.content;

    if (charData) {
      try {
        const book = charData.data && typeof charData.data === 'object' ? charData.data : {};
        if (!book.character_book || typeof book.character_book !== 'object') {
          book.character_book = { entries: [], extensions: {} };
        }
        if (!Array.isArray(book.character_book.entries)) book.character_book.entries = [];

        const idx = book.character_book.entries.findIndex(e => e && (e.comment === WORLD_BOOK_ENTRY_COMMENT || e.uid === WORLD_BOOK_ENTRY_UID));
        if (idx === -1) {
          if (!contentEmpty) book.character_book.entries.push(entry);
        } else {
          if (contentEmpty) book.character_book.entries.splice(idx, 1);
          else book.character_book.entries[idx] = entry;
        }
      } catch (e) {
        console.warn('[游戏扩展] 写入角色卡 character_book 失败:', e);
      }
    }

    try {
      const charName = getActiveCharacterName();
      if (charName) {
        if (!ctx.worldInfo || typeof ctx.worldInfo !== 'object') ctx.worldInfo = {};
        if (!ctx.worldInfo[charName] || typeof ctx.worldInfo[charName] !== 'object') {
          ctx.worldInfo[charName] = { entries: {}, theirBias: [], mainBias: [] };
        }
        if (!ctx.worldInfo[charName].entries) ctx.worldInfo[charName].entries = {};
        if (contentEmpty) {
          delete ctx.worldInfo[charName].entries[String(WORLD_BOOK_ENTRY_UID)];
        } else {
          ctx.worldInfo[charName].entries[String(WORLD_BOOK_ENTRY_UID)] = entry;
        }
      }
    } catch (e) {
      console.warn('[游戏扩展] 运行时 worldInfo 注入失败:', e);
    }

    try {
      const sts = [window.SillyTavern, window.parent?.SillyTavern, window.TavernHelper?.SillyTavern, window.parent?.TavernHelper?.SillyTavern];
      for (const st of sts) {
        if (!st) continue;
        try {
          if (typeof st.saveCharacterDebounced === 'function') { st.saveCharacterDebounced(); break; }
        } catch (e) { /* ignore */ }
        try {
          if (typeof st.saveCharacter === 'function') { st.saveCharacter(); break; }
        } catch (e) { /* ignore */ }
      }
    } catch (e) { /* ignore */ }

    // 同步写入角色主世界书（「消息记录注入世界书」同一套接口）
    try { syncWorldBookEntryViaHelper(entry.content || ''); } catch (e) { /* ignore */ }
  }

  function removeWorldBookEntry() {
    try {
      const { charData, ctx } = getCurrentCharacter();
      if (charData && charData.data && charData.data.character_book && Array.isArray(charData.data.character_book.entries)) {
        const entries = charData.data.character_book.entries;
        let idx = entries.findIndex(e => e && (e.comment === WORLD_BOOK_ENTRY_COMMENT || e.uid === WORLD_BOOK_ENTRY_UID));
        while (idx !== -1) {
          entries.splice(idx, 1);
          idx = entries.findIndex(e => e && (e.comment === WORLD_BOOK_ENTRY_COMMENT || e.uid === WORLD_BOOK_ENTRY_UID));
        }
      }
      if (ctx && ctx.worldInfo) {
        const nm = getActiveCharacterName();
        if (nm && ctx.worldInfo[nm] && ctx.worldInfo[nm].entries) {
          delete ctx.worldInfo[nm].entries[String(WORLD_BOOK_ENTRY_UID)];
        }
      }
      const st = window.SillyTavern || window.parent?.SillyTavern;
      if (st && typeof st.saveCharacterDebounced === 'function') st.saveCharacterDebounced();
    } catch (e) { /* ignore */ }
    // 同步移除角色主世界书里的对局记录条目
    try { syncWorldBookEntryViaHelper(''); } catch (e) { /* ignore */ }
  }

  // ========== 狼人杀 / 谁是卧底「完整注入」专用世界书同步 ==========
  function isFullInjectEnabled(gameType) {
    const cfg = loadConfig();
    if (gameType === 'werewolf') return cfg.wolfFullInject === true;
    if (gameType === 'spy') return cfg.spyFullInject === true;
    return false;
  }

  // 专用世界书正文：完整胜负结果 + 座位底牌 + 完整回放（不做 600 字截断）
  function buildDedicatedRecordContent(gameType) {
    if (!isFullInjectEnabled(gameType)) return '';
    const store = loadGenericMatchHistory();
    const list = Array.isArray(store[gameType]) ? store[gameType] : [];
    if (!list.length) return '';
    const title = getGameTypeDisplayName(gameType);
    const lines = [];
    list.forEach((m, i) => {
      const when = m.timestamp ? `（${new Date(m.timestamp).toLocaleString('zh-CN', { hour12: false })}）` : '';
      const result = m.result || '';
      const detail = m.detail || '';
      const points = (typeof m.pointsDelta === 'number' && m.pointsDelta !== 0)
        ? `\n  积分：${m.pointsDelta > 0 ? '+' : ''}${m.pointsDelta}${typeof m.pointsTotal === 'number' ? '（累计 ' + m.pointsTotal + '）' : ''}`
        : '';
      const replayText = m.replay ? String(m.replay).replace(/<[^>]+>/g, '').replace(/\n{3,}/g, '\n\n').trim() : '';
      const replay = replayText ? `\n  【完整对局回放】\n${replayText}` : '';
      lines.push(`【${title}第${i + 1}场】${result}${when}${detail ? '\n  ' + detail : ''}${points}${replay}`);
    });
    let text = `以下为主角最近的${title}完整对局记录（由游戏系统自动记录，含完整对局过程：公开发言、投票与夜间行动，供 AI 了解历史对局细节）：\n${lines.join('\n')}`;
