    if (text.length > MAX_LEN) text = text.slice(0, MAX_LEN) + '\n…（更多完整对局详情请查看【对局记录】界面）';
    return text;
  }

  // 写入 / 更新 / 停用一条专用记录条目；content 为空表示关闭完整注入
  async function syncDedicatedRecordBook(gameType, content) {
    const meta = DEDICATED_RECORD_BOOKS[gameType];
    if (!meta) return false;
    const th = getTavernHelperApi();
    if (!th) return false;
    const bookName = meta.book;
    const matchEntry = e => String(e?.name ?? e?.comment ?? '') === meta.entry;
    try {
      let exists = false;
      if (typeof th.getWorldbookNames === 'function') {
        const all = th.getWorldbookNames();
        exists = Array.isArray(all) && all.some(n => String(n) === bookName);
      }

      // 关闭完整注入：不删除世界书，仅停用其中的记录条目（内容保留，下次开启即时刷新）
      if (!content) {
        if (!exists || typeof th.getWorldbook !== 'function' || typeof th.updateWorldbookWith !== 'function') return true;
        const entries = await th.getWorldbook(bookName);
        if (!Array.isArray(entries)) return true;
        const found = entries.find(matchEntry);
        if (found && found.enabled !== false) {
          await th.updateWorldbookWith(bookName, list => (Array.isArray(list) ? list : []).map(e => matchEntry(e) ? { ...e, enabled: false } : e));
        }
        return true;
      }

      if (!exists) {
        if (typeof th.createWorldbook !== 'function') return false;
        try { await th.createWorldbook(bookName); } catch (e) { /* 已存在或创建失败：继续尝试直接写入 */ }
      }

      // 自动绑定为当前角色的「额外世界书」，保证条目实际参与注入
      if (typeof th.getCharWorldbookNames === 'function' && typeof th.rebindCharWorldbooks === 'function') {
        try {
          const cur = th.getCharWorldbookNames('current');
          const primary = (cur && typeof cur.primary === 'string' && cur.primary) ? cur.primary : null;
          const additional = Array.isArray(cur && cur.additional) ? cur.additional.slice() : [];
          if (!additional.some(n => String(n) === bookName)) {
            additional.push(bookName);
            await th.rebindCharWorldbooks('current', { primary: primary, additional: additional });
          }
        } catch (e) { console.warn('[游戏扩展] 专用对局记录世界书绑定失败:', e); }
      }

      const entries = await th.getWorldbook(bookName);
      if (!Array.isArray(entries)) return false;
      const found = entries.find(matchEntry);
      if (found) {
        if (String(found.content ?? '') !== content || found.enabled === false) {
          await th.updateWorldbookWith(bookName, list => (Array.isArray(list) ? list : []).map(e => matchEntry(e) ? { ...e, content: content, enabled: true } : e));
        }
        return true;
      }
      await th.createWorldbookEntries(bookName, [{
        name: meta.entry,
        enabled: true,
        strategy: { type: 'constant', keys: WORLD_BOOK_KEYWORDS.slice(), keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
        position: { type: 'at_depth', role: 'system', depth: 0, order: 102 },
        recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
        content: content
      }], { render: 'immediate' });
      return true;
    } catch (e) {
      console.warn('[游戏扩展] 专用对局记录世界书写入失败（' + bookName + '）:', e);
      return false;
    }
  }

