  function __scanApiInObject__(obj, out, depth) {
    if (!obj || typeof obj !== 'object' || depth > 8) return;
    if (Array.isArray(obj)) {
      for (const item of obj) __scanApiInObject__(item, out, depth + 1);
      return;
    }
    const urlKeys = ['apiUrl', 'apiurl', 'apiUrlBase', 'api_base', 'apiBase', 'baseUrl', 'baseURL', 'base_url', 'url', 'endpoint', 'apiEndpoint'];
    const keyKeys = ['apiKey', 'apikey', 'api_key', 'key', 'apiKeyPlain', 'secretKey'];
    const modelKeys = ['model', 'modelName', 'model_name', 'modelId', 'model_id'];
    for (const k of Object.keys(obj)) {
      const v = obj[k];
      if (typeof v === 'string' && v.trim()) {
        if (!out.url && urlKeys.includes(k)) out.url = v.trim();
        else if (!out.key && keyKeys.includes(k)) out.key = v.trim();
        else if (!out.model && modelKeys.includes(k)) out.model = v.trim();
      }
    }
    if (out.url && out.key) return;
    for (const k of Object.keys(obj)) {
      const v = obj[k];
      if (v && typeof v === 'object') __scanApiInObject__(v, out, depth + 1);
      if (out.url && out.key) break;
    }
  }

