  // ---------- 胡牌判定 ----------
  function mjAllMeld(c, i) {
    let p = (i === undefined) ? 0 : i;
    while (p < 34 && c[p] === 0) p++;
    if (p === 34) return true;
    if (c[p] >= 3) { c[p] -= 3; const ok = mjAllMeld(c, p); c[p] += 3; if (ok) return true; }
    if (p < 27 && (p % 9) <= 6 && c[p + 1] > 0 && c[p + 2] > 0) {
