    if (i === 34) return 0;
    let best = 0, v;
    if (c[i] >= 3) { c[i] -= 3; v = 2 + mjDecompose(c); c[i] += 3; if (v > best) best = v; }
    if (i < 27 && (i % 9) <= 6 && c[i + 1] > 0 && c[i + 2] > 0) { c[i]--; c[i + 1]--; c[i + 2]--; v = 2 + mjDecompose(c); c[i]++; c[i + 1]++; c[i + 2]++; if (v > best) best = v; }
    if (c[i] >= 2) { c[i] -= 2; v = 1 + mjDecompose(c); c[i] += 2; if (v > best) best = v; }
    if (i < 27 && (i % 9) <= 7 && c[i + 1] > 0) { c[i]--; c[i + 1]--; v = 1 + mjDecompose(c); c[i]++; c[i + 1]++; if (v > best) best = v; }
    if (i < 27 && (i % 9) <= 6 && c[i + 2] > 0) { c[i]--; c[i + 2]--; v = 1 + mjDecompose(c); c[i]++; c[i + 2]++; if (v > best) best = v; }
    c[i]--; v = mjDecompose(c); c[i]++;
    if (v > best) best = v;
    return best;
  }
  function mjShanten(hand, meldCount) {
    meldCount = meldCount || 0;
