    const has = v => hand.indexOf(suit + v) !== -1;
    const out = [];
    if (r >= 2 && has(suit + r - 2) && has(suit + r - 1)) out.push({ tiles: [suit + r - 2, suit + r - 1, tile], a: suit + r - 2, b: suit + r - 1 });
    if (r >= 1 && r <= 7 && has(suit + r - 1) && has(suit + r + 1)) out.push({ tiles: [suit + r - 1, tile, suit + r + 1], a: suit + r - 1, b: suit + r + 1 });
    if (r <= 6 && has(suit + r + 1) && has(suit + r + 2)) out.push({ tiles: [tile, suit + r + 1, suit + r + 2], a: suit + r + 1, b: suit + r + 2 });
    return out;
  }
  function mjBestChiOption(hand, tile, meldCount) {
    const opts = mjChiOptions(hand, tile);
    let best = null, bestSh = 99;
    for (const o of opts) {
      const rest = mjRemoveNTiles(mjRemoveNTiles(hand, o.a, 1), o.b, 1);
      const sh = mjShanten(rest, (meldCount || 0) + 1); // 吃后副露 +1
      if (sh < bestSh) { bestSh = sh; best = o; }
    }
    return best;
  }

  // ---------- 对局构建 ----------
  function mjBuildGame(names) {
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    const cfg = loadMjConfig();
    const list = (names || []).map(n => String(n).trim()).filter(Boolean);
    const players = [];
    players.push({ seat: 0, name: '我', isUser: true, avatar: getMainCharAvatar() || '' });
    for (let i = 0; i < 3; i++) {
      const nm = list[i];
      const ct = nm ? contacts.find(c2 => c2 && isNameMatch(c2.name, nm)) : null;
      players.push({ seat: i + 1, name: nm || ('角色' + (i + 1)), isUser: false, avatar: (ct && ct.avatar) || (nm ? getCharacterAvatarByName(nm) : '') || '' });
    }
    return {
      session: Date.now() + '_' + Math.floor(Math.random() * 100000),
      players, hands: [[], [], [], []], melds: [[], [], [], []], discards: [[], [], [], []],
      version: cfg.version === '108' ? '108' : '136',
      wall: mjMakeWall(cfg.version === '108' ? '108' : '136'), dealer: Math.floor(Math.random() * 4), turn: 0, phase: 'idle',
      last: null, drawn: -1, winner: -1, winType: '', winTiles: [], paoSeat: -1,
      log: [], aiLevel: cfg.aiLevel || 'normal', pendingClaim: null, recorded: false,
      speeches: [], actionCount: 0, lastSpeechAt: 0, moneyDelta: 0,
      bet: Math.max(1, Math.round(Number(cfg.bet) || 10)),
      aiChat: cfg.aiChat !== false, speechInterval: cfg.speechInterval || 4
    };
  }
  function mjDeal(g) {
    for (let i = 0; i < 13; i++) for (let s = 0; s < 4; s++) g.hands[s].push(g.wall.shift());
    g.hands[g.dealer].push(g.wall.shift());
    for (let s = 0; s < 4; s++) g.hands[s] = mjSort(g.hands[s]);
    g.turn = g.dealer;
    g.phase = 'turn';
    g.log = [];
    mjLog(g, '🎲 对局开始：' + g.players[g.dealer].name + ' 坐庄，起手 ' + g.players[g.dealer].name + ' 14 张、其余 13 张，牌墙剩余 ' + g.wall.length + ' 张');
  }
  function mjStartHand(names) {
    mjGenCounter++;
    mjChatBusy = false;
    mj = mjBuildGame(names);
    mjDeal(mj);
    renderMjGameUI();
    if (!mj.players[mj.turn].isUser) mjScheduleAi(650);
    mjMaybeAutoSpeak('start', mj.dealer, true);
  }
  function mjScheduleAi(ms) {
    if (mjAiTimer) clearTimeout(mjAiTimer);
    const gen = mj && mj.session;
    mjAiTimer = setTimeout(() => {
