      if (mj && mj.session === gen && mj.phase === 'turn') mjAiTurn(mj);
    }, ms || 700);
  }

  // ---------- 麻将：角色 AI 陪聊（设置开启后调用配置的 AI） ----------
  function mjPushSpeech(seat, text) {
    const g = mj;
    if (!g || !text) return;
    g.speeches.push({ seat: seat, name: g.players[seat] ? g.players[seat].name : '角色', text: text });
    if (g.speeches.length > 30) g.speeches = g.speeches.slice(-30);
    if (typeof contactsVoiceAutoSpeak === 'function') contactsVoiceAutoSpeak(g.speeches.length ? g.speeches[g.speeches.length - 1].name : '', text);
  }


  function mjMaybeAutoSpeak(scene, seat, force) {
    const g = mj;
    if (!g || !g.aiChat) return;
    if (mjChatBusy) return;
    if (!force) {
      if (Date.now() - (g.lastSpeechAt || 0) < 7000) return;
      if (scene === 'discard') {
        if (g.actionCount % (g.speechInterval || 4) !== 0) return;
      }
    }
    let target = seat;
    if (target === undefined || target === null || target < 0 || !g.players[target] || g.players[target].isUser) {
      target = (function () { for (let i2 = 1; i2 < g.players.length; i2++) if (g.players[i2] && !g.players[i2].isUser) return i2; return undefined; })();
    }
    if (target === undefined) return;
    mjRequestSpeech(target, scene, null);
  }

  function mjRequestSpeech(seat, scene, userMsg) {
    const g = mj;
    if (!g || !g.aiChat) return;
    const p = g.players[seat];
    if (!p || p.isUser) return;
    const apiCfg = ensureAIBackend();
    if (!apiCfg) return;
    if (mjChatBusy) return;
