      '3. 要有活人感：可带情绪、开玩笑、抱怨、撒娇、炫耀或关心主角，严禁空洞复读。\n' +
      '4. 严禁使用括号、旁白、动作与心理描写，只输出角色说出口的话。\n' +
      '5. 【完整出字铁律】只输出：<lines>台词正文</lines>，不要多余文字；发言长度自然，可长可短，口语化；必须语义完整、自然收尾，严禁半句截断、严禁只输出标点或空白、严禁空回复。即使没有新话题，也要用一句完整的日常话接住主角刚才的行动。';

    const messages = [{ role: 'system', content: system }];
    if (userMsg) messages.push({ role: 'user', content: '【主角对你说】' + userMsg + '\n请以【' + p.name + '】的口吻回一句。' });
    else messages.push({ role: 'user', content: '请以【' + p.name + '】的口吻说一段完整的牌桌台词（发言长度自然，可长可短，口语化；必须语义完整、自然收尾，严禁半句截断）。' });

    mjChatBusy = true;
    g.lastSpeechAt = Date.now();
    apiChat(messages, apiCfg, { maxTokens: 1000, temperature: 0.95 }).then(res => {
      if (gen !== mjGenCounter || !mj || mj.session !== g.session) return;
      let clean = ensureCompleteLine(String(res || '').replace(/<lines>|<\/lines>/gi, '').replace(/[\"'「」]/g, '').trim());
      if (p.name) clean = clean.replace(new RegExp('^' + p.name + '[：:]\\s*'), '');
      if (!clean || clean.length < 4) return;
      if (!/[。！？…]$/.test(clean)) clean += '。';
      mjPushSpeech(seat, clean);
      mjRefreshSpeechBox();
    }).catch(() => { /* 静默失败，不影响对局 */ }).finally(() => {
      if (gen === mjGenCounter) mjChatBusy = false;
    });
  }

  function mjRefreshSpeechBox() {
    const el = sheet?.querySelector('#mj-speech-text');
    const container = sheet?.querySelector('#mj-speech-container');
    if (!el || !mj) return;
    el.innerHTML = mjRenderSpeechHTML();
    if (container) container.scrollTop = container.scrollHeight;
  }

  function mjRenderSpeechHTML() {
    const g = mj;
    if (!g) return '';
    const conv = (g.speeches || []).slice(-24);
    if (!conv.length) return '<span style="color:var(--ubp-text-3);">（牌桌上一片安静，大家都盯着手里的牌…）</span>';
    return conv.map(sp => chatSpeechRowHTML(sp.name, sp.text, sp.seat === 0)).join('');
  }

  function mjHandleUserChatSend() {
    const g = mj;
    if (!g || !g.aiChat) return;
    const input = sheet.querySelector('#mj-chat-input');
    if (!input) return;
    const msg = input.value.trim();
    if (!msg) return;
    input.value = '';
    g.speeches.push({ seat: 0, name: '我', text: msg });
    mjRefreshSpeechBox();
    let target = (g.phase === 'turn' && g.turn !== 0) ? g.turn : (g.last && g.last.seat !== 0 ? g.last.seat : 1);
    if (!g.players[target] || g.players[target].isUser) target = (function () { for (let i2 = 1; i2 < g.players.length; i2++) if (g.players[i2] && !g.players[i2].isUser) return i2; return undefined; })();
    if (target === undefined) return;
    mjRequestSpeech(target, 'user-chat', msg);
  }

  // ---------- 动作 ----------
  function mjConsumeLastDiscard(g) {
    if (!g || !g.last) return;
    const rv = g.discards[g.last.seat];
    const i = rv.lastIndexOf(g.last.tile);
    if (i !== -1) rv.splice(i, 1);
  }
  // 轮到我出牌时手牌才可点、才显示"轮到你"提示（旧代码多了个 "!"，整组 UI 判定全反）
  function mjDiscardClickable(g) { return !!g && g.phase === 'turn' && !!g.players[g.turn] && g.players[g.turn].isUser; }
  function mjDoDiscard(g, s, tile) {
    const hand = g.hands[s];
    const idx = hand.indexOf(tile);
    if (idx === -1) return;
    hand.splice(idx, 1);
    g.last = { seat: s, tile, passSet: new Set() };
    g.discards[s].push(tile);
    g.drawn = -1;
    g.phase = 'claim';
    g.pendingClaim = null;
    mjLog(g, g.players[s].name + ' 打出 ' + mjTileName(tile));
    g.actionCount++;
    renderMjGameUI();
    mjMaybeAutoSpeak('discard', s, false);
    mjResolveClaims(g);
  }
  function mjDoPeng(g, s, tile) {
    const hand = g.hands[s];
    let left = 2;
    for (let i = hand.length - 1; i >= 0 && left > 0; i--) { if (hand[i] === tile) { hand.splice(i, 1); left--; } }
    mjConsumeLastDiscard(g);
    g.melds[s].push({ type: 'peng', tiles: [tile, tile, tile], from: g.last.seat, hidden: false });
    mjLog(g, g.players[s].name + ' 碰 ' + mjTileName(tile));
    g.turn = s; g.phase = 'turn'; g.drawn = -1; g.pendingClaim = null;
    g.actionCount++;
    renderMjGameUI();
    mjMaybeAutoSpeak('peng', s, false);
    if (!g.players[s].isUser) mjScheduleAi(600);
  }
  function mjDoGang(g, s, tile, fromSeat) {
    const hand = g.hands[s];
    let left = 3;
    for (let i = hand.length - 1; i >= 0 && left > 0; i--) { if (hand[i] === tile) { hand.splice(i, 1); left--; } }
    mjConsumeLastDiscard(g);
    g.melds[s].push({ type: 'gang', tiles: [tile, tile, tile, tile], from: (fromSeat === undefined ? g.last.seat : fromSeat), hidden: false });
    mjLog(g, g.players[s].name + ' 杠 ' + mjTileName(tile));
    mjAfterGang(g, s);
  }
  function mjAfterGang(g, s) {
    g.actionCount++;
    mjMaybeAutoSpeak('gang', s, false);
    const t = mjKangDraw(g);
    if (t === -1) { mjDrawEnd(g); return; }
    g.hands[s].push(t);
    g.hands[s] = mjSort(g.hands[s]);
    g.turn = s; g.phase = 'turn'; g.drawn = t;
    mjLog(g, g.players[s].name + ' 杠后补牌');
    renderMjGameUI();
    if (!g.players[s].isUser) mjScheduleAi(600);
  }
  function mjDoAnkang(g, s, tile) {
    const hand = g.hands[s];
    let left = 4;
    for (let i = hand.length - 1; i >= 0 && left > 0; i--) { if (hand[i] === tile) { hand.splice(i, 1); left--; } }
    g.melds[s].push({ type: 'gang', tiles: [tile, tile, tile, tile], from: -1, hidden: true });
    mjLog(g, g.players[s].name + ' 暗杠 ' + mjTileName(tile));
    mjAfterGang(g, s);
  }
  function mjDoBuGang(g, s, tile) {
    const hand = g.hands[s];
    const idx = hand.indexOf(tile);
    if (idx === -1) return;
    hand.splice(idx, 1);
    const mi = g.melds[s].findIndex(m => m.type === 'peng' && m.tiles[0] === tile);
    if (mi === -1) { hand.push(tile); return; }
    g.melds[s][mi] = { type: 'gang', tiles: [tile, tile, tile, tile], from: g.melds[s][mi].from, hidden: false };
    mjLog(g, g.players[s].name + ' 补杠 ' + mjTileName(tile));
    mjAfterGang(g, s);
  }
  function mjDoChi(g, s, opt) {
    const hand = g.hands[s];
    let left = 1;
    for (let i = hand.length - 1; i >= 0 && left > 0; i--) { if (hand[i] === opt.a) { hand.splice(i, 1); left--; } }
    left = 1;
    for (let i = hand.length - 1; i >= 0 && left > 0; i--) { if (hand[i] === opt.b) { hand.splice(i, 1); left--; } }
    mjConsumeLastDiscard(g);
    g.melds[s].push({ type: 'chi', tiles: opt.tiles.slice(), from: g.last.seat, hidden: false });
    mjLog(g, g.players[s].name + ' 吃 ' + opt.tiles.map(mjTileName).join(''));
    g.turn = s; g.phase = 'turn'; g.drawn = -1; g.pendingClaim = null;
    g.actionCount++;
    renderMjGameUI();
    mjMaybeAutoSpeak('chi', s, false);
    if (!g.players[s].isUser) mjScheduleAi(600);
  }
  function mjComputeClaims(g, seat, tile) {
    const claims = [];
    for (let s = 0; s < 4; s++) {
      if (s === seat) continue;
      const hand = g.hands[s];
      if (mjCanWin(hand.concat([tile]), g.melds[s].length)) { claims.push({ seat: s, type: 'hu', tiles: [tile] }); continue; }
      const cnt = hand.filter(t => t === tile).length;
      if (cnt >= 3) claims.push({ seat: s, type: 'gang', tiles: [tile, tile, tile, tile] });
      else if (cnt >= 2) claims.push({ seat: s, type: 'peng', tiles: [tile, tile, tile] });
    }
    const ns = mjNext(g, seat);
    const opts = mjChiOptions(g.hands[ns], tile);
    if (opts.length) claims.push({ seat: ns, type: 'chi', tiles: opts[0].tiles, options: opts });
    // 优先级：胡 > 杠 > 碰 > 吃（同类取先出现的玩家）
    const pick = t => { for (const c of claims) if (c.type === t) return c; return null; };
    const order = [pick('hu'), pick('gang'), pick('peng'), pick('chi')].filter(Boolean);
    return order;
  }
  function mjResolveClaims(g) {
    const claims = mjComputeClaims(g, g.last.seat, g.last.tile);
    for (const claim of claims) {
      if (g.last.passSet.has(claim.seat)) continue;
      if (g.players[claim.seat].isUser) {
        g.pendingClaim = { claims: claims.filter(c2 => !g.last.passSet.has(c2.seat) || c2.type === 'hu') };
        renderMjGameUI();
        return;
      }
      const did = mjAiClaimDecide(g, claim);
      if (did) return;
      g.last.passSet.add(claim.seat);
    }
    g.phase = 'turn';
    mjAdvanceDraw(g, mjNext(g, g.last.seat));
  }
  function mjAdvanceDraw(g, s) {
    const t = mjDraw(g);
    if (t === -1) { mjDrawEnd(g); return; }
    g.turn = s; g.phase = 'turn'; g.drawn = t;
    g.hands[s].push(t);
    g.hands[s] = mjSort(g.hands[s]);
    mjLog(g, g.players[s].name + ' 摸牌');
    renderMjGameUI();
    if (!g.players[s].isUser) mjScheduleAi(620);
  }
  function mjDrawEnd(g) {
    mjLog(g, '牌墙已摸完，流局');
    g.winner = -1;
    g.moneyDelta = 0;
    g.phase = 'end';
    renderMjGameUI();
    mjMaybeAutoSpeak('end', -1, true);
    mjRecordFinish(g);
  }
  function mjWinWithClaim(g, s, winType, paoSeat) {
    if (paoSeat >= 0) {
      mjConsumeLastDiscard(g);
      // 点炮胡：把赢牌并入赢家手牌，保证全局牌数守恒
      g.hands[s].push(g.last.tile);
      g.hands[s] = mjSort(g.hands[s]);
    }
    g.winner = s;
    g.winType = winType;
    g.paoSeat = paoSeat;
    g.winTiles = g.hands[s].slice().sort((a, b) => a - b);
    g.phase = 'end';
    mjLog(g, g.players[s].name + (winType === '自摸' ? ' 自摸胡牌！' : ' 胡牌！(点炮：' + (paoSeat >= 0 ? g.players[paoSeat].name : '—') + ')'));
    mjSettleTreasury(g);
    renderMjGameUI();
    mjMaybeAutoSpeak('hu', s, true);
    mjRecordFinish(g);
  }
  // 🪙 麻将倍数（赌注结算用）：自摸 ×2 · 每个杠 ×2 · 七对 ×2 · 十三幺 ×4（可叠加）
  function mjWinMultiplier(g) {
    const w = g.winner;
    if (w < 0 || !g.players[w]) return 1;
    let mult = 1;
    if (g.winType === '自摸') mult *= 2;
    const melds = g.melds[w] || [];
    const gangs = melds.filter(m => m && m.type === 'gang').length;
    if (gangs > 0) mult *= Math.pow(2, gangs);
    if (!melds.length && g.hands[w]) {
      try {
        if (mjCanWinOrphans(g.hands[w], 0)) mult *= 4;
        else if (mjCanWinSeven(g.hands[w], 0)) mult *= 2;
      } catch (e) { /* ignore */ }
    }
    return mult;
  }
  // 🪙 麻将筹码结算：赌注 × 倍数；自摸每家付，点炮仅点炮者付；流局不变（每局结算一次）
  function mjSettleTreasury(g) {
    g.moneyDelta = 0;
    if (!g || g.winner < 0) return 0;
    const bet = Math.max(1, Math.round(Number(g.bet) || 10));
    const mult = mjWinMultiplier(g);
    const unit = bet * mult;
    const w = g.winner;
    let delta = 0, desc = '';
    if (w === 0) {
      if (g.winType === '自摸') { delta = unit * 3; desc = '自摸 ×' + mult + '：每家 ' + unit + '，共收 ' + delta; }
      else { delta = unit; desc = '点炮胡 ×' + mult + '：' + (g.paoSeat >= 0 ? g.players[g.paoSeat].name : '—') + ' 付 ' + unit; }
    } else if (g.winType === '自摸') { delta = -unit; desc = g.players[w].name + ' 自摸 ×' + mult + '：你付 ' + unit; }
    else if (g.paoSeat === 0) { delta = -unit; desc = '你点炮 ×' + mult + '：付 ' + unit; }
    else { delta = 0; desc = g.players[w].name + ' 胡牌（他人点炮），你无需支付'; }
    g.moneyDelta = delta;
    if (delta !== 0) {
      const total = addChips('mahjong', delta);
      showToast('🪙 筹码 ' + (delta > 0 ? '+' : '') + delta + '（赌注 ' + bet + ' × 倍数 ' + mult + '，现有 ' + total + '）');
      mjLog(g, '🪙 结算：' + desc + '（筹码 ' + (delta > 0 ? '+' : '') + delta + '）');
    } else {
      mjLog(g, '🪙 ' + desc);
    }
    return delta;
  }
  function mjRecordFinish(g) {
    if (g.recorded) return;
    g.recorded = true;
    try {
      const w = g.winner;
      const res = w >= 0
        ? (g.winType === '自摸' ? g.players[w].name + ' 自摸胡牌' : g.players[w].name + ' 胡牌（' + (g.paoSeat >= 0 ? g.players[g.paoSeat].name : '') + ' 点炮）')
        : '牌墙摸完，流局';
      onGameFinished({
        gameType: 'mahjong',
        userWon: w === 0 ? true : (w === -1 ? undefined : false),
        isDraw: w === -1,
        result: res + '；主角' + (w === 0 ? '胜' : w === -1 ? '流局' : '负') + (g.moneyDelta ? '（筹码 ' + (g.moneyDelta > 0 ? '+' : '') + g.moneyDelta + '）' : ''),
        detail: w >= 0 ? ('胡牌牌型：' + g.winTiles.map(mjTileName).join(' ') + ' · 倍数 ×' + mjWinMultiplier(g) + ' · 赌注 ' + Math.max(1, Math.round(Number(g.bet) || 10))) : '',
        players: g.players.map(p => ({ name: p.name, isUser: p.isUser, avatar: p.avatar || '' }))
      });
    } catch (e) { /* ignore */ }
  }

  // ---------- AI ----------
  function mjAnkangTile(hand) {
    const c = mjCounts(hand);
    for (let i = 0; i < 34; i++) if (c[i] === 4) return i;
    return -1;
  }
  function mjBuGangTile(g, s) {
    for (const m of g.melds[s]) {
      if (m.type === 'peng' && g.hands[s].indexOf(m.tiles[0]) !== -1) return m.tiles[0];
    }
    return -1;
  }
  function mjSeenCounts(g, hand) {
    const seen = new Array(34).fill(0);
    for (const t of (hand || [])) if (t >= 0 && t < 34) seen[t] = Math.min(4, seen[t] + 1);
    for (const r of (g.discards || [])) for (const t of r) if (t >= 0 && t < 34) seen[t] = Math.min(4, seen[t] + 1);
    for (let s2 = 0; s2 < 4; s2++) {
      for (const m of (g.melds[s2] || [])) for (const t of m.tiles) if (t >= 0 && t < 34) seen[t] = Math.min(4, seen[t] + 1);
    }
    return seen;
  }
  // 听牌张数：13 张手牌能胡的牌型 × 全场可见张数折算的剩余有效张数（快速档不算、标准档算、强力档优先好型）
  const MJ_WAIT_CACHE = new Map();
  const MJ_NO_WAIT = { kinds: 0, tiles: 0, bestLeft: 0 };
  function mjWaitKey(g, hand13, meldCount) {
    const disc = [];
    for (const r of (g.discards || [])) for (const t of r) disc.push(t);
    const mel = [];
    for (let s2 = 0; s2 < 4; s2++) for (const m of (g.melds[s2] || [])) for (const t of m.tiles) mel.push(t);
    return (meldCount || 0) + '|' + hand13.slice().sort((a, b) => a - b).join(',') + '|' + disc.sort((a, b) => a - b).join(',') + '|' + mel.sort((a, b) => a - b).join(',');
  }
  function mjWaitInfo(g, hand13, meldCount) {
    const key = mjWaitKey(g, hand13, meldCount);
    const hit = MJ_WAIT_CACHE.get(key);
    if (hit) return hit;
    const seen = mjSeenCounts(g, hand13);
    let kinds = 0, tiles = 0, bestLeft = 0;
    for (let t = 0; t < 34; t++) {
      if (seen[t] >= 4) continue;
      if (!mjCanWin(hand13.concat([t]), meldCount || 0)) continue;
      const left = 4 - seen[t];
      kinds++; tiles += left;
      if (left > bestLeft) bestLeft = left;
    }
    const info = { kinds: kinds, tiles: tiles, bestLeft: bestLeft };
    if (MJ_WAIT_CACHE.size >= 800) {
      let drop = 400;
      for (const k of MJ_WAIT_CACHE.keys()) { MJ_WAIT_CACHE.delete(k); if (--drop <= 0) break; }
    }
    MJ_WAIT_CACHE.set(key, info);
    return info;
  }
  function mjAiClaimDecide(g, claim) {
    const s = claim.seat;
    const lvl = liveAiLevel(loadMjConfig, g.aiLevel);
    g.aiLevel = lvl; // 回写缓存，保证"设置改了立即生效 + 下一局读到新值"
    if (claim.type === 'hu') { mjWinWithClaim(g, s, '点炮', g.last.seat); return true; }
    if (claim.type === 'gang') { mjDoGang(g, s, claim.tiles[0], g.last.seat); return true; }
    const hand = g.hands[s];
    const mc = g.melds[s].length;
    const cur = mjShanten(hand, mc);
    if (claim.type === 'peng') {
      const t = claim.tiles[0];
      const rest = mjRemoveNTiles(hand, t, 2);
      const after = mjShanten(rest, mc + 1); // 碰后副露 +1，否则向听比较失真（AI 会几乎不吃碰）
      if (after >= cur) return false;
      if (lvl !== 'fast') {
        const cnt = mjCounts(rest);
        let pairs = 0;
        for (let i = 0; i < 34; i++) if (cnt[i] >= 2) pairs++;
        if (pairs >= 4) return false;
      }
      mjDoPeng(g, s, t);
      return true;
    }
    if (claim.type === 'chi') {
      const opt = mjBestChiOption(hand, g.last.tile, mc);
      if (!opt) return false;
      const rest = mjRemoveNTiles(mjRemoveNTiles(hand, opt.a, 1), opt.b, 1);
      const after = mjShanten(rest, mc + 1); // 吃后副露 +1
      // 新手特征（刻意如此，不是条件写反）：快速档只要吃牌不增加向听就吃（见牌就吃、见鬼也吃）；
      // 标准/强力档要求向听确实改善、且改善后已进入 1 向听以内才吃。
      if (lvl === 'fast') {
        if (after <= cur) { mjDoChi(g, s, opt); return true; }
      } else if (after < cur && after <= 1) {
        mjDoChi(g, s, opt); return true;
      }
      g.last.passSet.add(s);
      return false;
    }
    return false;
  }
  function mjAiTurn(g) {
    if (!mj || mj !== g || g.phase !== 'turn') return;
    const s = g.turn;
    if (!g.players[s] || g.players[s].isUser) return;
    g.aiLevel = liveAiLevel(loadMjConfig, g.aiLevel); // 实时难度（设置改动立即生效）
    if (mjCanWin(g.hands[s], g.melds[s].length)) { mjWinWithClaim(g, s, '自摸', -1); return; }
    const ank = mjAnkangTile(g.hands[s]);
    if (ank >= 0) { mjDoAnkang(g, s, ank); return; }
    if (g.aiLevel !== 'fast') {
      const bg = mjBuGangTile(g, s);
      if (bg >= 0) { mjDoBuGang(g, s, bg); return; }
    }
    const tile = mjAiPickDiscard(g, s);
    mjDoDiscard(g, s, tile);
  }
  function mjAiPickDiscard(g, s) {
    const lvl = liveAiLevel(loadMjConfig, g.aiLevel);
    g.aiLevel = lvl;
    if (lvl === 'fast') return mjAiPickFast(g, s);
    if (lvl === 'strong') return mjAiPickStrong(g, s);
    return mjAiPickNormal(g, s);
  }
  function mjAiPickFast(g, s) {
    const hand = g.hands[s];
    const mc = g.melds[s].length;
    const D = getDifficulty('mahjong', liveAiLevel(loadMjConfig, g.aiLevel));
    const cands = mjUniqueTiles(hand);
    const scored = [];
    for (const t of cands) scored.push({ t: t, sh: mjShantenAfter(hand, t, mc) });
    scored.sort((a, b) => a.sh - b.sh);
    // 快速档同样要"像新手"：按难度中枢的失误率从次优候选池里挑（candK=4），
    // 而不是永远走最优——否则玩家只会觉得"它下得很快但一点错都不犯"。
    if (scored.length > 1 && Math.random() < D.blunder) {
      const pool = scored.slice(1, Math.max(2, Math.min(D.candK || 4, scored.length)));
      return pool[Math.floor(Math.random() * pool.length)].t;
    }
    return scored[0] ? scored[0].t : cands[0];
  }
  function mjAiDanger(g, tile, self) {
    let totalSeen = 0;
    for (const r of g.discards) for (const t of r) if (t === tile) totalSeen++;
    let d = 0;
    if (totalSeen === 0) d += (tile >= 27 ? 5 : 6);
    else d += (tile >= 27 ? 0 : Math.max(0, 4 - totalSeen * 2));
    if (tile < 27) {
      const r = tile % 9;
      if (r >= 2 && r <= 6) d += 4;
    }
    for (let p = 0; p < 4; p++) { // 0 号位玩家也是对手，不能漏
      if (p === self) continue; // 不能把 AI 自己的弃牌当成对手的弃牌
      const recent = g.discards[p].slice(-3);
      for (const t of recent) {
        if (t === tile) d -= 2;
        else if (t < 27 && tile < 27 && Math.floor(t / 9) === Math.floor(tile / 9) && Math.abs((t % 9) - (tile % 9)) === 1) d += 3;
      }
    }
    return d;
  }
  function mjAiOppThreat(g, self) {
    let threat = 0;
    for (let p = 0; p < 4; p++) { // 0 号位玩家也是对手，不能漏
      if (p === self) continue; // 同上：AI 自己不是对手
      const recent = g.discards[p].slice(-3);
      const mid = recent.filter(t => t < 27 && t % 9 >= 2 && t % 9 <= 6).length;
      if (mid >= 2 || g.melds[p].length >= 2) threat++;
    }
    return threat;
  }
  function mjAiPickNormal(g, s) {
    const hand = g.hands[s];
    const mc = g.melds[s].length;
    const cands = mjUniqueTiles(hand);
    const D = getDifficulty('mahjong', liveAiLevel(loadMjConfig, g.aiLevel));
    g.aiLevel = D.level;
    let minSh = 99;
    for (const t of cands) minSh = Math.min(minSh, mjShantenAfter(hand, t, mc));
    const threat = mjAiOppThreat(g, s);
    const defensive = threat >= 2;
    const allow = defensive ? minSh + (minSh <= 1 ? 1 : 0) : minSh;
    let best = null, bestScore = -Infinity;
    const scored = [];
    for (const t of cands) {
      const sh = mjShantenAfter(hand, t, mc);
      if (sh > allow) continue;
      // 标准档：计算听牌张数（剩余可见张数），并把它当作轻量加分
      // 性能：只在已听牌（minSh <= 0）时才算——没听牌时 34 种牌的 mjCanWin 递归纯属浪费
      const wait = (minSh <= 0) ? mjWaitInfo(g, mjRemoveNTiles(hand, t, 1), mc) : MJ_NO_WAIT;
      const danger = mjAiDanger(g, t, s);
      const score = (minSh - sh) * 40 + wait.tiles * 2 - danger + Math.random() * 0.6 * (D.noise || 0);
      scored.push({ t, score });
      if (score > bestScore) { bestScore = score; best = t; }
    }
    if (!scored.length) return cands[0];
    scored.sort((a, b) => b.score - a.score);
    // 主动失误：只从次优候选池挑（不会"有听不打"地自爆）
    if (scored.length > 1 && Math.random() < D.blunder) {
      const pool = scored.slice(1, Math.max(2, Math.min(D.candK, scored.length)));
      return pool[Math.floor(Math.random() * pool.length)].t;
    }
    return best;
  }
  function mjSimDiscard(st, s) {
    const hand = st.hands[s];
    if (!hand.length) return -1;
    const mc = st.melds ? st.melds[s] : 0;
    let best = hand[0], bestSh = 99;
    for (const t of mjUniqueTiles(hand)) {
      const sh = mjShantenAfter(hand, t, mc);
      if (sh < bestSh) { bestSh = sh; best = t; }
    }
    return best;
  }
  function mjMctsPlayout(g, s, tile) {
    const st = { hands: g.hands.map(h => h.slice()), wall: g.wall.slice(), discards: g.discards.map(d => d.slice()), melds: g.melds.map(m => m.length), turn: s };
    const h = st.hands[s];
    let idx = h.indexOf(tile);
    if (idx === -1) return 0;
    h.splice(idx, 1);
    st.discards[s].push(tile);
    st.turn = (s + 1) % 4;
    let steps = 0;
    while (st.wall.length && steps++ < 60) {
      const t = st.turn;
      const drawn = st.wall.shift();
      st.hands[t].push(drawn);
      st.hands[t].sort((a, b) => a - b);
      if (mjCanWin(st.hands[t], st.melds[t])) return t === s ? 1 : 0;
      const disc = mjSimDiscard(st, t);
      if (disc === -1) return 0;
      for (let o = 0; o < 4; o++) {
        if (o === t) continue;
        if (mjCanWin(st.hands[o].concat([disc]), st.melds[o])) {
          if (o === s) return 1;
          if (t === s) return -1.2;
          return 0;
        }
      }
      idx = st.hands[t].indexOf(disc);
      st.hands[t].splice(idx, 1);
      st.discards[t].push(disc);
      st.turn = (t + 1) % 4;
    }
    return 0;
  }
  function mjAiPickStrong(g, s) {
    const hand = g.hands[s];
    const mc = g.melds[s].length;
    const D = getDifficulty('mahjong', liveAiLevel(loadMjConfig, g.aiLevel));
    g.aiLevel = D.level;
    const cands = mjUniqueTiles(hand);
    let minSh = 99;
    for (const t of cands) minSh = Math.min(minSh, mjShantenAfter(hand, t, mc));
    // 强力档：算听牌张数（剩余可见张数）并优先好型（听牌张数多/听牌种类多的打法排前面）
    // 性能：同上，只在已听牌时才算（mjWaitInfo 内部另有按牌面指纹的缓存）
    const waitOf = new Map();
    for (const t of cands) waitOf.set(t, (minSh <= 0) ? mjWaitInfo(g, mjRemoveNTiles(hand, t, 1), mc) : MJ_NO_WAIT);
    let pool = cands.filter(t => mjShantenAfter(hand, t, mc) === minSh);
    pool.sort((a, b) => {
      const wa = waitOf.get(a) || { tiles: 0, kinds: 0 };
      const wb = waitOf.get(b) || { tiles: 0, kinds: 0 };
      return (wb.tiles - wa.tiles) || (wb.kinds - wa.kinds) || (a - b);
    });
    if (pool.length < 4) {
      const extra = cands.filter(t => mjShantenAfter(hand, t, mc) === minSh + 1 && pool.indexOf(t) === -1);
      extra.sort((a, b) => mjAiDanger(g, a, s) - mjAiDanger(g, b, s));
      for (const t of extra) if (pool.length < 4) pool.push(t);
    }
    if (!pool.length) pool = [cands[0]];
    const stats = pool.map(() => ({ w: 0, pao: 0, n: 0 }));
    // 蒙特卡洛迭代次数取自统一难度中枢（强力档 2000 次上限）。
    // 确定性铁律：强力档不能用墙钟决定迭代次数——同一局面两次跑出的迭代数不同 → 统计量不同 → 决策可能不同。
    // 改为固定迭代次数；playout 本身是确定性的（纯向听贪心，不含随机数），因此强力档结果可完全复现。
    // 性能：单次 playout 最多 60 步、每步要跑多组 mjCanWin/mjShanten 递归，400 次会到秒级；
    // 这里把固定迭代压到实测可接受量（按门内张数 12~14 缩放），budget 仍作为极端情况下的硬上限。
    const budget = D.timeMs || 380;
    const maxIter = D.mctsIter || 900;
    const fixedIter = D.level === 'strong' ? Math.min(maxIter, Math.max(80, 8 * hand.length)) : 0;
    const start = Date.now();
    let iter = 0;
    while (iter < maxIter && (fixedIter ? (iter < fixedIter && (Date.now() - start) < Math.max(budget * 2, 1200)) : (Date.now() - start) < budget)) {
      const ci = iter % pool.length;
      const r = mjMctsPlayout(g, s, pool[ci]);
      stats[ci].n++;
      if (r > 0.5) stats[ci].w++;
      else if (r < -0.5) stats[ci].pao++;
      iter++;
    }
    let best = 0, bestV = -Infinity;
    stats.forEach((st, i) => {
      const prior = (minSh - mjShantenAfter(hand, pool[i], mc)) * 0.18;
      const w = waitOf.get(pool[i]) || { tiles: 0 };
      const v = (st.n ? (st.w - 1.6 * st.pao) / st.n : -9) + prior + w.tiles * 0.02;
      if (v > bestV) { bestV = v; best = i; } // 并列时取靠前候选（好型优先），保证确定性
    });
    // 强力档必须确定性：不再做"6% 概率随机切到次优候选"（会破坏同一局面结果一致性）
    return pool[best];
  }

  // ---------- 大厅 / 邀请 / 设置 ----------
  // 🪙 麻将赌注卡片（大厅设置：每局按 赌注×倍数 结算筹码钱包）
  function mjBetCardHTML() {
    const cfg = loadMjConfig();
    const min = Math.max(1, Math.round(Number(cfg.bet) || 10));
    const bank = ensureStartChips('mahjong', MJ_START_CHIPS);
    const ok = bank >= min;
    return '<div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:11px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;">' +
      '<span style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">🪙 赌注（筹码结算）</span>' +
      '<span style="font-size:15px;font-weight:800;color:' + (ok ? '#10B981' : '#EF4444') + ';">' + bank + '</span></div>' +
      '<div style="display:flex;gap:6px;align-items:center;margin-top:8px;">' +
      '<input id="mj-bet-input" class="ubp-fieldinput" type="number" min="1" value="' + min + '" style="flex:1;padding:5px 8px;font-size:13px;">' +
      '<button data-mj-act="mj-bet-save" class="ubp-btn" style="padding:5px 12px;font-size:12.5px;background:#D97706;color:#fff;border:none;">保存赌注</button></div>' +
      '<div style="font-size:11px;color:var(--ubp-text-3);margin-top:6px;line-height:1.6;">每局按 <b>赌注 × 倍数</b> 结算筹码：自摸 ×2 · 每个杠 ×2 · 七对 ×2 · 十三幺 ×4（可叠加）；自摸时三家都付、点炮只由点炮者付，流局不变。当前筹码 ' + bank + (ok ? '' : '（不足赌注 ' + min + '，无法开局）') + '。</div></div>';
  }
