          ${av ? `<img src="${av}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:14px;">${escapeHtml(nm.slice(0, 1))}</span>`}
