        '<div style="display:flex;justify-content:flex-end;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-mj-act="mj-invite-confirm" class="ubp-btn primary" style="padding:6px 20px;font-size:13px;background:#D97706;border:none;border-radius:6px;">确认邀请</button></div>';
      ov.querySelectorAll('[data-mj-pick]').forEach(el => {
        el.addEventListener('click', () => {
