      ov.querySelector('#th-set-chat')?.addEventListener('change', (e) => {
        const cc = loadThConfig();
        cc.aiChat = e.target.checked;
        saveThConfig(cc);
        renderContent();
      });
      ov.querySelector('#th-set-interval')?.addEventListener('change', (e) => {
        const cc = loadThConfig();
        cc.speechInterval = parseInt(e.target.value) || 4;
        saveThConfig(cc);
      });
      ov.querySelector('#th-set-level')?.addEventListener('change', (e) => {
        const cc = loadThConfig();
        cc.aiLevel = e.target.value || 'normal';
        saveThConfig(cc);
      });
      ov.querySelector('[data-th-set="close"]')?.addEventListener('click', () => {
        ov.remove();
        renderTHLobby();
      });
    };
    renderContent();
    sheet.appendChild(ov);
  }

  // ---------- 牌桌 UI ----------
  function renderTHGameUI() {
    const g = thGame;
    if (!g) { renderTHLobby(); return; }
    const streetName = { preflop: '翻牌前 Preflop', flop: '翻牌圈 Flop', turn: '转牌圈 Turn', river: '河牌圈 River', showdown: '摊牌 Showdown', end: '本局结束' }[g.phase] || g.phase;
    const pot = thPot(g);
    const me = g.players[0];
    const isMyTurn = g.phase !== 'end' && g.turn === 0 && !me.folded && !me.allIn;
    const toCall = isMyTurn ? thToCall(g, 0) : 0;
    const canBet = g.currentBet === 0;

    const boardHTML = (g.board.length
      ? g.board.map(id => thCardHTML(id, { w: 36 })).join('') + (g.phase === 'end' || g.phase === 'showdown' ? '' : '')
      : '<span style="font-size:12px;color:var(--ubp-text-3);align-self:center;">公共牌待翻出…</span>');

    const holeRow = (p) => {
      if (!p) return '';
      const reveal = (p.seat === 0) || (g.phase === 'end' && !p.folded);
      const cards = reveal ? p.hole.map(id => thCardHTML(id, { w: 40 })).join('') : thCardBackHTML(40) + thCardBackHTML(40);
      return '<div style="display:flex;flex-direction:column;align-items:center;gap:2px;font-size:13px;font-weight:600;color:var(--ubp-text);">' +
        '<div style="display:flex;">' + cards + '</div>' +
        '<div style="font-size:10px;color:var(--ubp-text-3);">' + escapeHtml(p.name) + ' · 筹码 ' + p.stack + '</div></div>';
    };

    const oppRows = g.players.slice(1).map((p, i) => {
      const s = i + 1;
      const on = g.turn === s && g.phase !== 'end';
      const status = p.folded
        ? '🙅 已弃牌'
        : p.allIn ? '🔥 All-in' : (g.phase === 'end' ? (g.winnerDesc && g.winnerDesc.indexOf(p.name) >= 0 ? '🏆' : '—') : (on ? '🤔 思考中…' : '—'));
      return '<div style="display:flex;align-items:center;justify-content:space-between;gap:6px;padding:4px 8px;border-radius:8px;background:var(--ubp-card-2);border:1.5px solid ' + (on ? '#0F766E' : 'var(--ubp-line)') + ';flex:none;">' +
        '<div style="display:flex;align-items:center;gap:6px;min-width:0;">' + chatAvatarHTML(p.name, false, 26, p.avatar) +
        '<div style="min-width:0;"><div style="font-size:11.5px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(p.name) + (g.dealer === s ? ' <span style="color:#F59E0B;font-size:10px;">BTN</span>' : '') + (g.sbSeat === s ? ' <span style="font-size:9px;color:var(--ubp-text-3);">SB</span>' : '') + (g.bbSeat === s ? ' <span style="font-size:9px;color:var(--ubp-text-3);">BB</span>' : '') + '</div>' +
        '<div style="font-size:10px;color:var(--ubp-text-3);">' + status + ' · 筹码 ' + p.stack + (p.folded ? '' : ' · 🂠×2') + '</div></div></div>' +
        '</div>';
    }).join('');

    const logHTML = g.log.slice(-22).map(l => '<div style="margin:1px 0;font-size:11px;color:var(--ubp-text-2);">' + escapeHtml(l) + '</div>').join('');

    let actionHTML = '';
    if (isMyTurn) {
      const raiseMin = (g.currentBet || 0) + g.minRaise;
      const raisePotBet = (g.currentBet || 0) + pot;
      const btn = (t, a, style) => '<button data-th-act="' + a + '" class="ubp-btn" style="flex:1;min-width:70px;padding:7px 0;font-size:12.5px;border-radius:8px;' + style + '">' + t + '</button>';
      actionHTML = '<div style="display:flex;gap:6px;flex-wrap:wrap;flex:none;margin-top:6px;">' +
        btn('🙅 弃牌', 'th-fold', '') +
        btn(canBet ? '✅ 过牌' : ('✅ 跟注 ' + Math.min(toCall, me.stack)), 'th-call', 'background:#10B981;border:none;color:#fff;') +
        btn('⬆️ 加注 ' + Math.min(raiseMin, me.stack), 'th-raise-min', 'background:#0F766E;border:none;color:#fff;') +
        btn('💣 底池加注 ' + Math.min(raisePotBet, me.stack), 'th-raise-pot', 'background:#F59E0B;border:none;color:#fff;') +
        btn('🔥 All-in (' + me.stack + ')', 'th-allin', 'background:#EF4444;border:none;color:#fff;') +
        '</div>';
    } else if (g.phase !== 'end') {
      const tp = g.players[g.turn];
      actionHTML = '<div style="text-align:center;font-size:12px;color:var(--ubp-text-3);padding:6px 0;flex:none;">⏳ ' + escapeHtml(tp ? tp.name : '') + ' 正在思考…</div>';
    }

    const thChatHTML = g.aiChat ? `
      <style>
        #th-speech-container::-webkit-scrollbar { width: 5px; }
        #th-speech-container::-webkit-scrollbar-thumb { background: #0F766E; border-radius: 4px; }
      </style>
      <div id="th-speech-container" style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:8px;padding:6px 9px;margin-top:6px;height:76px;max-height:76px;overflow-y:scroll;scrollbar-width:thin;box-sizing:border-box;">
        <div id="th-speech-text" style="font-size:12px;line-height:1.5;word-break:break-word;">${thRenderSpeechHTML()}</div>
      </div>
      <div style="display:flex;gap:6px;margin-top:5px;">
        <input id="th-chat-input" class="ubp-fieldinput" type="text" placeholder="对牌桌上的角色说点什么…（如：这手牌你会跟吗）" style="flex:1;font-size:12px;padding:4px 8px;border-radius:6px;height:26px;">
        <button data-th-act="th-send-chat" class="ubp-btn primary" style="padding:0 10px;font-size:12px;height:26px;background:#0F766E;border:none;flex:none;">发送</button>
      </div>` : '';

    const endBtns = g.phase === 'end'
      ? '<div style="display:flex;gap:8px;flex:none;margin-top:8px;"><button data-th-act="th-rematch" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:13px;background:#0F766E;border:none;border-radius:8px;">▶ 继续（保留牌局 · 重新发牌）</button><button data-th-act="th-quit" class="ubp-btn" style="flex:1;padding:8px 0;font-size:13px;border-radius:8px;">🚪 退出（结算）</button></div>'
      : '';

    const phaseColor = g.phase === 'end' ? '#F59E0B' : '#0F766E';
    sheet.innerHTML = [
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex:none;">',
      '  <div style="display:flex;align-items:center;gap:7px;min-width:0;">',
      '    <button data-th-act="th-exit" style="background:none;border:none;font-size:16px;cursor:pointer;color:var(--ubp-text);flex:none;" title="返回牌桌大厅（自动保存进度）">←</button>',
      '    <span style="font-size:14.5px;font-weight:600;">🂡 德州扑克 · <span style="font-size:11px;color:' + phaseColor + ';">本场第 ' + ((g.sessionHands || 0) + 1) + ' 手 · ' + streetName + '</span></span>',
      '  </div>',
      '  <button data-th-act="th-quit" class="ubp-btn" style="padding:3px 10px;font-size:11.5px;flex:none;" title="退出牌桌：整场统一结算回筹码钱包并写入对局记录">🚪 退出</button>',
      '</div>',
      '<div style="display:flex;justify-content:center;align-items:center;gap:4px;font-size:11px;color:var(--ubp-text-2);flex:none;margin-bottom:2px;">底池 <b style="color:#F59E0B;">' + pot + '</b> · 盲注 ' + TH_SB + '/' + TH_BB + ' · 轮到 ' + escapeHtml(g.players[g.turn] ? g.players[g.turn].name : '—') + '</div>',
      '<div style="flex:none;margin-bottom:6px;"><div style="display:flex;flex-direction:column;gap:3px;">' + oppRows + '</div></div>',
      '<div style="display:flex;justify-content:center;flex-wrap:wrap;padding:6px;border-radius:8px;background:rgba(15,118,110,0.08);border:1.5px dashed rgba(15,118,110,0.45);flex:none;min-height:56px;align-items:center;">' + boardHTML + '</div>',
      '<div style="display:flex;justify-content:center;margin-top:6px;flex:none;">' + holeRow(me) + '</div>',
      '<div style="flex:1;min-height:44px;overflow-y:auto;background:var(--ubp-card-2);border-radius:8px;padding:6px 9px;border:1px solid var(--ubp-line);margin-top:6px;">' + (logHTML || '<div style="font-size:11px;color:var(--ubp-text-3);">牌局日志</div>') + '</div>',
      actionHTML,
      '<div style="flex:none;margin:4px 0 2px;">' + thChatHTML + '</div>',
      endBtns,
      '<div style="flex:none;font-size:9.5px;color:var(--ubp-text-3);margin-top:4px;line-height:1.5;border-top:1px solid var(--ubp-line);padding-top:4px;">任选 5 张（2 底牌 + 5 公共牌）比大小 · 牌型：皇家同花顺＞同花顺＞四条＞葫芦＞同花＞顺子＞三条＞两对＞一对＞高牌 · All-in 产生边池</div>'
    ].join('\n');

    const thChatInput = sheet.querySelector('#th-chat-input');
    if (thChatInput) {
      thChatInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') { e.preventDefault(); thHandleUserChatSend(); }
      });
    }
    scheduleThGameStateSave();
  }

// ========== 德州扑克：断点保存 / 恢复 ==========
  const TH_SAVE_KEY = 'werewolf_extension_th_saved_game';
  // 200ms 防抖：避免每次重绘都写 localStorage；退出/结束时仍立即落盘
  let thSaveTimer = null;
  function scheduleThGameStateSave() {
    if (thSaveTimer) clearTimeout(thSaveTimer);
    thSaveTimer = setTimeout(() => { thSaveTimer = null; if (thGame) saveThGameState(); }, 200);
  }
  function saveThGameState() {
    if (!thGame || thGame.phase === 'idle' || thGame.sessionFinalized) { clearSavedThGame(); return; }
    try {
      const g = thGame;
      const state = {
        session: g.session, players: g.players, contrib: g.contrib, board: g.board, deck: g.deck,
        startStack: (g.startStack !== undefined ? g.startStack : TH_START_CHIPS),
        dealer: g.dealer, sbSeat: g.sbSeat, bbSeat: g.bbSeat, phase: g.phase, turn: g.turn,
        currentBet: g.currentBet, minRaise: g.minRaise, lastRaiser: g.lastRaiser, needAct: g.needAct,
        log: g.log, aiLevel: g.aiLevel, aiChat: g.aiChat, speechInterval: g.speechInterval,
        speeches: g.speeches, actionCount: g.actionCount, recorded: g.recorded, showdown: g.showdown, winnerDesc: g.winnerDesc,
        sessionStartChips: g.sessionStartChips, sessionHands: g.sessionHands || 0, sessionWins: g.sessionWins || 0
      };
      localStorage.setItem(TH_SAVE_KEY, JSON.stringify(state));
    } catch (e) { /* ignore */ }
  }
  function clearSavedThGame() { try { localStorage.removeItem(TH_SAVE_KEY); } catch (e) { /* ignore */ } }
  function hasSavedThGame() {
    try {
      const raw = localStorage.getItem(TH_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && d.players && d.phase && d.phase !== 'idle');
    } catch (e) { return false; }
  }
  function resumeSavedThGame() {
    try {
      const raw = localStorage.getItem(TH_SAVE_KEY);
      if (!raw) { renderTHLobby(); return; }
      const d = JSON.parse(raw);
      thGenCounter++;
      thChatBusy = false;
      if (thAiTimer) { clearTimeout(thAiTimer); thAiTimer = null; }
      thGame = {
        session: d.session || (Date.now() + '_' + Math.floor(Math.random() * 100000)),
        players: d.players, contrib: d.contrib || (d.players || []).map(() => 0), board: d.board || [], deck: d.deck || [],
        startStack: (d.startStack !== undefined ? d.startStack : TH_START_CHIPS),
        dealer: d.dealer || 0, sbSeat: d.sbSeat || 0, bbSeat: d.bbSeat || 0, phase: d.phase,
        turn: d.turn || 0, currentBet: d.currentBet || 0, minRaise: d.minRaise || TH_BB,
        lastRaiser: (d.lastRaiser === undefined ? -1 : d.lastRaiser), needAct: d.needAct || [],
        log: d.log || [], aiLevel: d.aiLevel || 'normal', aiChat: d.aiChat !== false,
        speechInterval: d.speechInterval || 4, speeches: d.speeches || [], lastSpeechAt: 0,
        actionCount: d.actionCount || 0, recorded: !!d.recorded, showdown: !!d.showdown, winnerDesc: d.winnerDesc || '',
        sessionStartChips: Number.isFinite(d.sessionStartChips) ? d.sessionStartChips : ((d.players && d.players[0] && d.players[0].stack) || 0),
        sessionHands: d.sessionHands || 0, sessionWins: d.sessionWins || 0, sessionFinalized: false
      };
      thBankroll = Math.max(0, Math.round(Number(thGame.players[0] && thGame.players[0].stack) || 0));
      renderTHGameUI();
      showToast('🔖 已恢复进行中的德州扑克对局');
      if (thGame.phase !== 'end' && !thGame.players[thGame.turn].isUser && !thGame.players[thGame.turn].allIn && !thGame.players[thGame.turn].folded) thScheduleAi(800);
    } catch (e) {
      renderTHLobby();
    }
  }

  // ---------- 德州扑克操作分发 ----------
  function handleTHAction(act, target) {
    const g = thGame;
    if (act === 'th-open') {
      if (g && g.phase !== 'idle' && !g.sessionFinalized) renderTHGameUI();
      else if (hasSavedThGame()) resumeSavedThGame();
      else renderTHLobby();
      return;
    }
    if (act === 'th-back') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); renderCardLobby(); return; }
    if (act === 'th-settings') { renderTHSettings(); return; }
    if (act === 'th-send-chat') { thHandleUserChatSend(); return; }
    if (act === 'th-invite') { thInviteOverlay(); return; }
    if (act === 'th-invite-close') {
      const ov = sheet.querySelector('.th-invite-overlay');
      if (ov) ov.remove();
      return;
    }
    if (act === 'th-invite-confirm') {
      const ov = sheet.querySelector('.th-invite-overlay');
      if (ov) ov.remove();
      renderTHLobby();
      return;
    }
    if (act === 'th-start') {
      if (chipBankOf('holdem') < TH_BB) {
        showToast('🪙 筹码不足大盲，请先兑换筹码');
        renderChipExchange('holdem', () => renderTHLobby());
        return;
      }
      if (aiChatInviteGate({
        chatOn: loadThConfig().aiChat,
        invited: thInvites.filter(Boolean).length,
        label: '德州扑克',
        onInvite: () => thInviteOverlay(),
        onDisableAndStart: () => { const c2 = loadThConfig(); c2.aiChat = false; saveThConfig(c2); handleTHAction('th-start', null); }
      })) return;
      if (thGame && thGame.players && thGame.phase !== 'idle' && !thGame.sessionFinalized) {
        // 已有未结算的牌局：先按【退出】规则结算上一场，再开新场
        thFinalizeSession(thGame, {});
      } else if (hasSavedThGame()) {
        // 仅有历史存档（曾中途关闭）：先静默结算旧场筹码差，再开新场
        thSettleSavedAbandon();
        clearSavedThGame();
      }
      const n = thInvites.filter(Boolean).length;
      if (n < 3) showToast('🪑 入座 ' + n + '/3，其余席位由通用角色补位');
      thStartHand(thInvites.slice());
      return;
    }
    if (act === 'th-exit') {
      // ← 返回牌桌大厅：保存进度，不结算；稍后可点【继续对局】接着玩
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      if (thGame && thGame.players && thGame.phase !== 'idle' && !thGame.sessionFinalized) saveThGameState();
      else clearSavedThGame();
      if (thAiTimer) { clearTimeout(thAiTimer); thAiTimer = null; }
      thGenCounter++;
      thGame = null;
      renderTHLobby();
      return;
    }
    if (act === 'th-quit') {
      // 🚪 退出：整场统一结算回筹码钱包 + 写入对局记录（游戏结束与结算只在这里触发）
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
      if (thAiTimer) { clearTimeout(thAiTimer); thAiTimer = null; }
      thGenCounter++;
      thFinalizeSession(thGame, {});
      return;
    }
    if (act === 'th-resume') { resumeSavedThGame(); return; }
    if (act === 'th-discard') { thSettleSavedAbandon(); clearSavedThGame(); renderTHLobby(); showToast('🗑️ 已放弃进行中的德州扑克对局（筹码差已结算）'); return; }
    if (act === 'th-rematch') {
      // ▶ 继续：保留牌局日志与角色对话，只重新发牌；没筹码的角色离场（不再补发）
      const names = (g && g.players) ? g.players.slice(1).map(p => p.name) : thInvites.slice();
      if (aiChatInviteGate({
        chatOn: loadThConfig().aiChat,
        invited: names.filter(n2 => !isBuiltinPlayerName(n2)).length,
        label: '德州扑克',
        onInvite: () => renderTHLobby(),
        onDisableAndStart: () => { const c2 = loadThConfig(); c2.aiChat = false; saveThConfig(c2); handleTHAction('th-rematch', null); }
      })) return;
      if (thAiTimer) clearTimeout(thAiTimer);
      thStartHand(names, true);
      return;
    }
    if (!g || g.phase === 'end') return;
    if (g.turn !== 0 || g.players[0].folded || g.players[0].allIn) return;
    if (act === 'th-fold') { thDoFold(g, 0); return; }
    if (act === 'th-call') { thDoCall(g, 0); return; }
    if (act === 'th-raise-min') { thDoRaiseTo(g, 0, (g.currentBet || 0) + g.minRaise); return; }
    if (act === 'th-raise-pot') { thDoRaiseTo(g, 0, (g.currentBet || 0) + thPot(g)); return; }
    if (act === 'th-allin') {
      thDoRaiseTo(g, 0, g.players[0].betStreet + g.players[0].stack);
      return;
    }
  }

  // ========== UNO（108 张 / 4 色 / 功能牌 / UNO 口号 / 叠牌与特殊变体 / 三档 AI） ==========
  const UNO_CONFIG_KEY = 'werewolf_extension_uno_config';
  const UNO_SAVE_KEY = 'werewolf_extension_uno_saved_game';
  const UNO_COLORS = ['R', 'Y', 'B', 'G'];
  const UNO_COLOR_NAME = { R: '红', Y: '黄', B: '蓝', G: '绿', W: '黑' };
  const UNO_COLOR_HEX = { R: '#EF4444', Y: '#F59E0B', B: '#3B82F6', G: '#22C55E', W: '#1F2937' };
  const UNO_COLOR_SOFT = { R: 'rgba(239,68,68,0.16)', Y: 'rgba(245,158,11,0.16)', B: 'rgba(59,130,246,0.16)', G: 'rgba(34,197,94,0.16)', W: 'rgba(31,41,55,0.30)' };
  const UNO_TYPE_LABEL = { skip: '🚫 跳过', rev: '🔄 反转', '+2': '➕2', wild: '🌈 变色', w4: '➕4' };
  let unoGame = null;
  let unoInvites = [];
  let unoAiTimer = null;
  let unoChatBusy = false;
  let unoGenCounter = 0;
  let unoSaveTimer = null;

  function loadUnoConfig() {
    const def = { aiLevel: 'normal', aiChat: true, speechInterval: 4, stacking: true, seven: false, zero: false, plusAdd: false };
    try {
      const raw = localStorage.getItem(UNO_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (p && typeof p === 'object') {
          if (p.aiLevel === 'fast' || p.aiLevel === 'normal' || p.aiLevel === 'strong') def.aiLevel = p.aiLevel;
          if (typeof p.aiChat === 'boolean') def.aiChat = p.aiChat;
          if (Number.isFinite(Number(p.speechInterval)) && Number(p.speechInterval) >= 1) def.speechInterval = Number(p.speechInterval);
          if (typeof p.stacking === 'boolean') def.stacking = p.stacking;
          // 旧版合并开关 7&0 迁移为两个独立开关
          if (typeof p.sevenZero === 'boolean') { def.seven = p.sevenZero; def.zero = p.sevenZero; }
          if (typeof p.seven === 'boolean') def.seven = p.seven;
          if (typeof p.zero === 'boolean') def.zero = p.zero;
          if (typeof p.plusAdd === 'boolean') def.plusAdd = p.plusAdd;
        }
      }
    } catch (e) { /* ignore */ }
    return def;
  }
  function saveUnoConfig(c) { try { localStorage.setItem(UNO_CONFIG_KEY, JSON.stringify(c || {})); } catch (e) { /* ignore */ } }

  // 经典 108 张：每色 0×1、1~9×2、跳过/反转/+2 各×2；黑色 变色×4、+4×4
  function unoMakeDeck() {
    const deck = [];
    for (const c of UNO_COLORS) {
      deck.push({ c: c, t: '0' });
      for (let n = 1; n <= 9; n++) { deck.push({ c: c, t: String(n) }); deck.push({ c: c, t: String(n) }); }
      for (const t of ['skip', 'rev', '+2']) { deck.push({ c: c, t: t }); deck.push({ c: c, t: t }); }
    }
    for (let i = 0; i < 4; i++) { deck.push({ c: 'W', t: 'wild' }); deck.push({ c: 'W', t: 'w4' }); }
    return deck;
  }
  function unoShuffle(arr, rng) {
    const rand = rng || Math.random;
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; }
    return a;
  }
  function unoIsWild(card) { return !!card && card.c === 'W'; }
  function unoCardValue(card) {
    if (!card) return 0;
    if (unoIsWild(card)) return 50;
    if (card.t === 'skip' || card.t === 'rev' || card.t === '+2') return 20;
    return parseInt(card.t, 10) || 0;
  }
  function unoHandPoints(hand) { return (hand || []).reduce((s, c) => s + unoCardValue(c), 0); }
  function unoCardText(card) {
    if (!card) return '?';
    if (card.c === 'W') return UNO_TYPE_LABEL[card.t] || '万能牌';
    return UNO_COLOR_NAME[card.c] + ' ' + (UNO_TYPE_LABEL[card.t] || card.t);
  }
  // 出牌合法性：颜色同 / 数字或功能符号同 / 黑色随时可出
  function unoCanPlay(card, topCard, color, ctx) {
    if (!card) return false;
    if (unoIsWild(card)) return true;
    if (card.c === color) return true;
    if (topCard && !unoIsWild(topCard) && card.t === topCard.t) return true;
    return false;
  }
  function unoHasColor(hand, color) { return (hand || []).some(c => c && c.c === color); }
  // 罚牌窗口内可回应的牌：
  // · 叠牌变体：+2 只能接 +2、+4 只能接 +4（同类型累加罚牌）
  // · 加牌变体：+4 之后可以出「与 +4 指定颜色相同」的 +2
  function unoCanStack(g, card) {
    if (!card || !g.stackType) return false;
    if (g.stacking && card.t === g.stackType) return true;
    if (g.plusAdd && g.stackType === 'w4' && card.t === '+2' && card.c === g.currentColor) return true;
    return false;
  }
  function unoPlayableList(g, seat) {
    const p = g.players[seat];
    const top = g.discard[g.discard.length - 1];
    // 罚牌窗口：只能出可回应的叠牌（没有可回应的牌时由调用方直接结算罚牌）
    if ((g.drawStack || 0) > 0 && g.stackType) {
      return p.hand.map((card, idx) => ({ card: card, idx: idx })).filter(x => x.card && unoCanStack(g, x.card));
    }
    const ctx = { stacking: g.stacking, drawStack: g.drawStack || 0, stackType: g.stackType || null, hasColor: unoHasColor(p.hand, g.currentColor) };
    return p.hand.map((card, idx) => ({ card: card, idx: idx })).filter(x => unoCanPlay(x.card, top, g.currentColor, ctx));
  }
  // 玩家（座位 0）当前可出的牌
  function unoPlayableForUser(g) {
    return unoPlayableList(g, 0);
  }
  function unoSeatName(seat) { const p = unoGame && unoGame.players[seat]; return p ? p.name : '玩家'; }
  function unoSeatSaveName(saved, seat) {
    if (!saved || !saved.players || !saved.players[seat]) return '玩家';
    return saved.players[seat].name;
  }
  function unoNextSeat(g, seat, steps) {
    const n = (steps === undefined ? 1 : steps);
    return ((seat + g.dir * n) % g.players.length + g.players.length) % g.players.length;
  }

  // ---------- 开局 ----------
  function unoBuildGame(names) {
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    const cfg = loadUnoConfig();
    const list = (names || []).map(n => String(n).trim()).filter(Boolean);
    const players = [];
    players.push({ seat: 0, name: '我', isUser: true, avatar: getMainCharAvatar() || '', hand: [], saidUno: false });
    const npcCount = Math.max(1, Math.min(3, list.length || 1)); // 与欺诈酒馆一致：邀请几位就几位开局（一位都没邀请则补 1 位内置角色陪玩）
    for (let i = 0; i < npcCount; i++) {
      const nm = list[i];
      const ct = nm ? contacts.find(c2 => c2 && isNameMatch(c2.name, nm)) : null;
      players.push({ seat: i + 1, name: nm || ('牌友' + (i + 1)), isUser: false, avatar: (ct && ct.avatar) || (nm ? getCharacterAvatarByName(nm) : '') || '', hand: [], saidUno: false });
    }
    return {
      session: Date.now() + '_' + Math.floor(Math.random() * 100000),
      players: players, deck: [], discard: [], currentColor: 'R', turn: 0, dir: 1, dealer: 0,
      phase: 'playing', drawStack: 0, stackType: null, pendingColor: null, pendingUno: null, pendingZero: null,
      round: 1, winner: -1, log: [], history: [],
      actionCount: 0, userActions: 0, aiLevel: cfg.aiLevel, aiChat: cfg.aiChat !== false, speechInterval: cfg.speechInterval || 4,
      stacking: !!cfg.stacking, seven: !!cfg.seven, zero: !!cfg.zero, plusAdd: !!cfg.plusAdd,
      speeches: [], lastSpeechAt: 0, recorded: false
    };
  }
  function unoDrawToHand(g, seat, count) {
    const p = g.players[seat];
    let drawn = 0;
    for (let i = 0; i < count; i++) {
      if (!g.deck.length) {
        // 牌库用尽：洗回弃牌堆（保留顶牌）
        if (g.discard.length <= 1) break;
        const top = g.discard.pop();
        g.deck = unoShuffle(g.discard.splice(0, g.discard.length));
        g.discard = [top];
      }
      if (!g.deck.length) break;
      p.hand.push(g.deck.pop());
      drawn++;
    }
    return drawn;
  }
  function unoLog(g, text) {
    g.log.push(text);
    if (g.log.length > 120) g.log.splice(0, g.log.length - 120);
    if (g.history) g.history.push(text);
  }
  function unoStartMatch(names) {
    const cfg = loadUnoConfig();
    unoGenCounter++;
    unoChatBusy = false;
    unoGame = unoBuildGame(names);
    const g = unoGame;
    const deck = unoShuffle(unoMakeDeck());
    for (let i = 0; i < 7; i++) for (const p of g.players) p.hand.push(deck.pop());
    // 翻开起始牌：功能牌则重新换一张（按官方：若是 +4/变色直接换；这里功能牌一律重抽）
    let start = deck.pop();
    let guard = 0;
    while (start && (unoIsWild(start) || start.t === 'skip' || start.t === 'rev' || start.t === '+2') && guard++ < 30) {
      deck.unshift(start);
      start = deck.pop();
    }
    g.deck = deck;
    g.discard = [start];
    g.currentColor = start.c === 'W' ? 'R' : start.c;
    g.dealer = Math.floor(Math.random() * g.players.length);
    g.turn = unoNextSeat(g, g.dealer);
    g.phase = 'playing';
    unoLog(g, '🎴 UNO 开局：每人 7 张，起始牌【' + unoCardText(start) + '】，由 ' + unoSeatName(g.turn) + ' 先出（顺时针）。');
    renderUnoGameUI();
    if (!g.players[g.turn].isUser) unoScheduleAi(700);
    unoMaybeAutoSpeak('start', g.dealer, true);
  }
  // ---------- 出牌与结算 ----------
  function unoPlayCard(seat, idx, choseColor, isAi) {
    const g = unoGame;
    if (!g || g.phase !== 'playing') return false;
    const p = g.players[seat];
    const card = p.hand[idx];
    if (!card) return false;
    const playable = unoPlayableList(g, seat).some(x => x.idx === idx);
    if (!playable) return false;
    const topBefore = g.discard[g.discard.length - 1];
    p.hand.splice(idx, 1);
    g.discard.push(card);
    g.actionCount++;
    if (seat === 0) g.userActions = (g.userActions || 0) + 1;
    let color = card.c === 'W' ? (choseColor || 'R') : card.c;
    g.currentColor = color;
    unoLog(g, '▶ ' + p.name + ' 出【' + unoCardText(card) + (card.c === 'W' ? '（指定 ' + UNO_COLOR_NAME[color] + '色）' : '') + '】');
    const speechScene = card.t === 'skip' ? 'skip' : card.t === 'rev' ? 'reverse' : (card.t === '+2' || card.t === 'w4') ? 'plus' : 'play';
    unoMaybeAutoSpeak(speechScene, seat);

    // 剩余 1 张：进入"喊 UNO"窗口（5 秒内必须喊，超时算失败）
    if (p.hand.length === 1 && !p.saidUno) {
      g.pendingUno = { seat: seat, beforeSeat: unoNextSeat(g, seat), deadline: Date.now() + 5000 };
      if (!p.isUser && shouldAiCallUno(g, seat)) { p.saidUno = true; g.pendingUno = null; unoLog(g, '📣 ' + p.name + ' 喊了 UNO！'); }
      else if (p.isUser) {
        const gRef = g;
        setTimeout(() => {
          if (unoGame === gRef && gRef.pendingUno && gRef.pendingUno.seat === 0 && !gRef.players[0].saidUno && gRef.phase === 'playing') renderUnoGameUI();
        }, 5150);
      }
    } else if (p.hand.length !== 1) {
      p.saidUno = false;
    }

    if (!p.hand.length) { unoEndRound(g, seat); return true; }

    // 效果结算
    let skipNext = false;
    if (card.t === 'skip') {
      skipNext = true;
      unoLog(g, '🚫 ' + unoSeatName(unoNextSeat(g, seat)) + ' 被跳过。');
    } else if (card.t === 'rev') {
      if (g.players.length === 2) skipNext = true;
      else { g.dir = -g.dir; unoLog(g, '🔄 出牌方向反转（' + (g.dir === 1 ? '顺时针' : '逆时针') + '）。'); }
    } else if (card.t === '+2' || card.t === 'w4') {
      const add = card.t === '+2' ? 2 : 4;
      const stackKind = card.t === 'w4' ? 'w4' : '+2';
      const nextSeat = unoNextSeat(g, seat);
      const nextP = g.players[nextSeat];
      // 罚牌不再有质疑环节：下家如果有可回应的叠牌就继续累加，否则直接摸牌并跳过
      const canRespond = nextP && nextP.hand.some(c => unoCanStack({ stacking: g.stacking, plusAdd: g.plusAdd, stackType: stackKind, currentColor: g.currentColor }, c));
      const accumulated = ((g.drawStack || 0) > 0 && g.stackType === stackKind ? g.drawStack : 0) + add;
      if (canRespond) {
        if ((g.drawStack || 0) > 0 && g.stackType === stackKind) unoLog(g, '🧱 叠牌：罚牌累计到 ' + accumulated + ' 张。');
        else unoLog(g, (card.t === '+2' ? '➕2！' : '➕4！') + unoSeatName(nextSeat) + ' 可出' + (stackKind === 'w4' ? '+4' : '+2') + (g.plusAdd ? '（或指定颜色的 +2）' : '') + '叠牌，否则摸 ' + accumulated + ' 张并跳过。');
        g.drawStack = accumulated;
        g.stackType = stackKind;
        g.turn = nextSeat;
        saveUnoGameState();
        renderUnoGameUI();
        if (g.turn !== 0) unoScheduleAi(unoDelayFor(g));
        return true;
      }
      g.drawStack = 0; g.stackType = null;
      skipNext = true;
      const drawn = unoDrawToHand(g, nextSeat, accumulated);
      unoLog(g, '➕ ' + unoSeatName(nextSeat) + ' 摸 ' + drawn + ' 张并被跳过。');
    }

    // 7 变体：出 7 与随机一位玩家交换手牌
    if (g.seven && card.c !== 'W' && card.t === '7') {
      const others = g.players.filter(x => x.seat !== seat);
      const target = others[Math.floor(Math.random() * others.length)];
      const tmp = p.hand; p.hand = target.hand; target.hand = tmp;
      unoLog(g, '🔁 7 换牌：' + p.name + ' 与 ' + target.name + ' 交换了手牌。');
    }
    // 0 变体：全员必须喊 UNO，5 秒内没喊的罚摸 2 张
    if (g.zero && card.c !== 'W' && card.t === '0') {
      const pendingSeats = [];
      for (const x of g.players) {
        if (x.isUser) { pendingSeats.push(x.seat); continue; }
        if (shouldAiCallUno(g, x.seat)) unoLog(g, '📣 ' + x.name + ' 喊了 UNO！');
        else pendingSeats.push(x.seat);
      }
      if (pendingSeats.length) {
        unoStartZeroWindow(g, pendingSeats);
        unoLog(g, '📣 0 变体：全员必须喊 UNO！未在 5 秒内喊出的罚摸 2 张。');
      } else {
        unoLog(g, '📣 0 变体：全员都迅速喊出了 UNO！');
      }
    }

    g.turn = unoNextSeat(g, seat, skipNext ? 2 : 1);
    saveUnoGameState();
    renderUnoGameUI();
    if (g.turn !== 0) unoScheduleAi(unoDelayFor(g));
    return true;
  }
  function unoDelayFor(g) {
    // 玩家刚打到 1 张（还没喊 UNO）时，把下家行动推迟到 5 秒喊 UNO 窗口结束
    if (g.pendingUno && g.pendingUno.seat === 0 && g.pendingUno.deadline) {
      const remain = g.pendingUno.deadline - Date.now();
      return remain > 0 ? remain + 300 : 300;
    }
    return 760;
  }
  // 0 变体：开启 5 秒喊 UNO 窗口，超时未喊的玩家罚摸 2 张
  function unoStartZeroWindow(g, pendingSeats) {
    const win = { deadline: Date.now() + 5000, pendingSeats: pendingSeats.slice() };
    g.pendingZero = win;
    const gRef = g;
    setTimeout(() => {
      if (unoGame !== gRef || gRef.pendingZero !== win) return;
      const seats = win.pendingSeats || [];
      gRef.pendingZero = null;
      let failed = 0;
      for (const s of seats) {
        const x = gRef.players[s];
        if (!x) continue;
        const drawn = unoDrawToHand(gRef, s, 2);
        if (drawn) { failed++; unoLog(gRef, '⌛ ' + x.name + ' 没能在 5 秒内喊出 UNO，罚摸 ' + drawn + ' 张。'); }
      }
      if (failed && unoGame === gRef && gRef.phase === 'playing') renderUnoGameUI();
    }, 5150);
  }

  // 回合开始前处理：UNO 抓包 / 累积罚牌
  function unoBeginTurn(g, seat) {
    // 1) 抓没喊 UNO 的上家（下家行动之前）
    if (g.pendingUno && g.pendingUno.beforeSeat === seat) {
      const offender = g.players[g.pendingUno.seat];
      if (offender && offender.hand.length === 1 && !offender.saidUno) {
        if (offender.isUser) {
          // 玩家忘喊：由当前 AI 决定是否抓
          if (Math.random() < aiUnoCatchRate(g)) {
            const drawn = unoDrawToHand(g, offender.seat, 2);
            unoLog(g, '👀 ' + unoSeatName(seat) + ' 抓到你没喊 UNO！罚摸 ' + drawn + ' 张。');
            renderUnoGameUI();
          }
        } else {
          const drawn = unoDrawToHand(g, offender.seat, 2);
          unoLog(g, '👀 ' + unoSeatName(seat) + ' 抓到 ' + offender.name + ' 没喊 UNO，罚摸 ' + drawn + ' 张。');
          renderUnoGameUI();
        }
      }
      g.pendingUno = null;
    }
    // 2) 累积罚牌：没有可回应的叠牌就必须摸牌并跳过
    if ((g.drawStack || 0) > 0) {
      const p = g.players[seat];
      const hasResponse = p.hand.some(c => unoCanStack(g, c));
      if (!hasResponse) {
        const amt = g.drawStack;
        const drawn = unoDrawToHand(g, seat, amt);
        unoLog(g, '➕ ' + p.name + ' 没有可回应的牌，摸 ' + drawn + ' 张并被跳过（累计罚牌 ' + amt + '）。');
        g.drawStack = 0; g.stackType = null;
        if (seat === 0) showToast('😖 你被罚摸 ' + drawn + ' 张并跳过');
        g.turn = unoNextSeat(g, seat);
        saveUnoGameState();
        renderUnoGameUI();
        if (g.turn !== 0) unoScheduleAi(unoDelayFor(g));
        return false;
      }
    }
    return true;
  }
  function aiUnoCatchRate(g) {
    const lvl = difficultyLevel(g.aiLevel);
    return lvl === 'fast' ? 0.45 : (lvl === 'strong' ? 1 : 0.7);
  }
  function shouldAiCallUno(g, seat) {
    const lvl = difficultyLevel(g.aiLevel);
    if (lvl === 'fast') return Math.random() < 0.65; // 基础 AI 有时会忘记喊
    if (lvl === 'normal') return Math.random() < 0.95;
    return true; // 强力 AI 从不忘记
  }

  function unoEndRound(g, winnerSeat) {
    const winner = g.players[winnerSeat];
    g.winner = winnerSeat;
    g.phase = 'end';
    g.pendingUno = null;
    g.pendingZero = null;
    g.drawStack = 0; g.stackType = null;
    const detail = g.players.filter(p => p.seat !== winnerSeat).map(p => p.name + ' 剩 ' + p.hand.length + ' 张').join('；');
    unoLog(g, '🏆 ' + winner.name + ' 出光全部手牌，赢得本局！' + (detail ? '（' + detail + '）' : ''));
    if (!g.recorded) {
      g.recorded = true;
      onGameFinished({
        gameType: 'uno',
        result: 'UNO：' + winner.name + ' 出光手牌获胜',
        detail: detail || '本局无人剩牌',
        userWon: winnerSeat === 0,
        isDraw: false,
        players: g.players.map(p => ({ name: p.name, isUser: !!p.isUser, avatar: p.avatar || '' })),
        replay: (g.history || []).slice(-60).join('\n'),
        replayRich: (g.history || []).slice(-60).map(t => ({ type: 'public', text: t, authorPos: null }))
      });
    }
    saveUnoGameState();
    renderUnoGameUI();
    unoMaybeAutoSpeak('win', winnerSeat, true);
    setTimeout(() => { if (unoGame === g) renderUnoGameUI(); }, 30);
  }

  // ---------- AI ----------
  function unoScheduleAi(ms) {
    if (unoAiTimer) clearTimeout(unoAiTimer);
    const gen = unoGame && unoGame.session;
    const seat = unoGame ? unoGame.turn : -1;
    unoAiTimer = setTimeout(() => {
      unoAiTimer = null;
      if (unoGame && unoGame.session === gen && unoGame.turn === seat && unoGame.phase === 'playing' && !unoGame.players[seat].isUser) unoAiTurn(unoGame);
    }, ms || 760);
  }
  function unoAiTurn(g) {
    if (!unoGame || unoGame !== g || g.phase !== 'playing') return;
    const seat = g.turn;
    const p = g.players[seat];
    if (!p || p.isUser) return;
    g.aiLevel = liveAiLevel(loadUnoConfig, g.aiLevel);
    if (!unoBeginTurn(g, seat)) return; // 罚牌跳过 / 抓 UNO
    const playable = unoPlayableList(g, seat);
    if (!playable.length) {
      // 没有可出的牌：只能摸 1 张，摸牌后直接跳过回合（摸到的牌不能立刻打出）
      const drawn = unoDrawToHand(g, seat, 1);
      g.actionCount++;
      if (!drawn) unoLog(g, '⏭ ' + p.name + ' 无牌可出（牌库也空了），跳过。');
      else unoLog(g, '🖐 ' + p.name + ' 没有可出的牌，摸了一张并被跳过。');
      unoMaybeAutoSpeak('draw', seat);
      g.turn = unoNextSeat(g, seat);
      saveUnoGameState();
      renderUnoGameUI();
      if (g.turn !== 0) unoScheduleAi(unoDelayFor(g));
      return;
    }
    const choice = unoAiChoose(g, seat, playable);
    if (!choice) { g.turn = unoNextSeat(g, seat); saveUnoGameState(); renderUnoGameUI(); if (g.turn !== 0) unoScheduleAi(760); return; }
    const color = unoIsWild(choice.card) ? unoAiPickColor(g, seat) : null;
    if (!unoPlayCard(seat, choice.idx, color, true)) {
      // 兜底：决策与状态不一致时（理论上不该发生）绝不能原地卡死——摸 1 张并跳过回合
      const drawn = unoDrawToHand(g, seat, 1);
      unoLog(g, '⏭ ' + p.name + ' 无法出牌（兜底），摸 ' + drawn + ' 张并跳过。');
      g.turn = unoNextSeat(g, seat);
      saveUnoGameState();
      renderUnoGameUI();
      if (g.turn !== 0) unoScheduleAi(unoDelayFor(g));
    }
  }
  function unoAiPickColor(g, seat) {
    const p = g.players[seat];
    const counts = { R: 0, Y: 0, B: 0, G: 0 };
    for (const c of p.hand) if (c && c.c !== 'W') counts[c.c]++;
    const lvl = difficultyLevel(g.aiLevel);
    if (lvl === 'fast') {
      const ks = UNO_COLORS.slice().sort((a, b) => counts[b] - counts[a]);
      return Math.random() < 0.5 ? ks[0] : ks[Math.floor(Math.random() * ks.length)];
    }
    let best = 'R';
    for (const k of UNO_COLORS) if (counts[k] > counts[best]) best = k;
    return best;
  }
  function unoAiScoreCandidate(g, seat, item) {
    const p = g.players[seat];
    const card = item.card;
    const nextSeat = unoNextSeat(g, seat);
    const nextP = g.players[nextSeat];
    let s = 0;
    if (unoIsWild(card)) s -= 55;                                  // 基础倾向：保留万能牌
    if (card.t === 'skip' || card.t === 'rev' || card.t === '+2') s += 12;
    if (card.t === '+2' || card.t === 'w4') {
      if (nextP && nextP.hand.length <= 2) s += 45;                 // 压制快赢的对手
      if (nextP && nextP.hand.length >= 6) s -= 18;
    }
    s += unoCardValue(card) * 0.6;                                  // 优先甩掉大分牌
    const after = p.hand.filter((c, i) => i !== item.idx);
    const colors = { R: 0, Y: 0, B: 0, G: 0, W: 0 };
    for (const c of after) colors[c.c] = (colors[c.c] || 0) + 1;
    if (!unoIsWild(card)) s += (colors[card.c] || 0) * 1.5;         // 保留颜色多样性
    if (after.length === 1) s += 120;                               // 即将赢
    return s;
  }
  function unoAiChoose(g, seat, playable) {
    const D = getDifficulty('uno', g.aiLevel);
    const lvl = D.level;
    const scored = playable.map(x => ({ idx: x.idx, card: x.card, score: unoAiScoreCandidate(g, seat, x) })).sort((a, b) => b.score - a.score);
    if (!scored.length) return null;
    if (lvl === 'strong') {
      // 高级：蒙特卡洛预测（用局面指纹播种随机源，保证同一局面决策一致）
      const rng = pickRng('strong', 'uno|' + seat + '|' + g.turn + '|' + g.currentColor + '|' + g.discard.length + '|' + g.players.map(p => p.hand.length).join(',') + '|' + g.players[seat].hand.map(c => c.c + c.t).join(',') + '|' + (g.drawStack || 0) + '|' + (g.stackType || ''));
      const sims = Math.max(4, Math.min(60, D.sims || 40));
      let best = scored[0], bestV = -Infinity;
      for (const item of scored.slice(0, 4)) {
        const color = unoIsWild(item.card) ? unoAiPickColor(g, seat) : null;
        const wr = unoMcWinRate(g, seat, item.idx, color, sims, rng);
        const v = wr * 100 + item.score * 0.35;
        if (v > bestV) { bestV = v; best = item; }
      }
      return { idx: best.idx, card: best.card };
    }
    if (lvl === 'fast') {
      if (scored.length > 1 && Math.random() < D.blunder) {
        const pool = scored.slice(1, Math.max(2, Math.min(D.candK || 4, scored.length)));
        const pick = pool[Math.floor(Math.random() * pool.length)];
        return { idx: pick.idx, card: pick.card };
      }
      return { idx: scored[0].idx, card: scored[0].card };
    }
    // 标准：从次优池轻微失误
    if (scored.length > 1 && Math.random() < D.blunder) {
      const pool = scored.slice(1, Math.max(2, Math.min(D.candK || 2, scored.length)));
      const pick = pool[Math.floor(Math.random() * pool.length)];
      return { idx: pick.idx, card: pick.card };
    }
    return { idx: scored[0].idx, card: scored[0].card };
  }
  // 蒙特卡洛：把未知牌随机分配给其他人 + 牌库，用基础策略推演到本局结束
  function unoMcWinRate(g, seat, playIdx, color, sims, rng) {
    let wins = 0;
    for (let s = 0; s < sims; s++) {
      const sim = {
        players: g.players.map(p => ({ seat: p.seat, name: p.name, isUser: p.seat === seat, hand: p.seat === seat ? p.hand.slice() : [] })),
        deck: [], discard: g.discard.slice(), currentColor: g.currentColor, dir: g.dir, turn: g.turn,
        drawStack: g.drawStack || 0, stackType: g.stackType || null, phase: 'playing', stacking: g.stacking
      };
      // 未知牌池 = 牌库 + 其他玩家手牌（真实信息只用于抽样总量，具体归属随机）
      const unknown = g.deck.slice();
      for (const p of g.players) if (p.seat !== seat) unknown.push(...p.hand);
      const shuffled = unoShuffle(unknown, rng);
      let k = 0;
      for (const p of g.players) {
        if (p.seat === seat) continue;
        for (let i = 0; i < p.hand.length; i++) sim.players[p.seat].hand.push(shuffled[k++]);
      }
      sim.deck = shuffled.slice(k);
      // 先走我们这一手
      const topBefore = sim.discard[sim.discard.length - 1];
      const card = sim.players[seat].hand[playIdx];
      if (!card) continue;
      const hadColor = sim.players[seat].hand.some(c => c && c.c === sim.currentColor);
      sim.players[seat].hand.splice(playIdx, 1);
      sim.discard.push(card);
      if (unoIsWild(card)) sim.currentColor = color || 'R'; else sim.currentColor = card.c;
      const legalPlus4 = !hadColor;
      let skip = false;
      if (card.t === 'skip') skip = true;
      else if (card.t === 'rev') { if (sim.players.length === 2) skip = true; else sim.dir = -sim.dir; }
      else if (card.t === '+2' || card.t === 'w4') {
        const target = ((seat + sim.dir) % sim.players.length + sim.players.length) % sim.players.length;
        const amt = card.t === '+2' ? 2 : 4;
        for (let i = 0; i < amt; i++) { const c = sim.deck.pop(); if (c) sim.players[target].hand.push(c); }
        skip = true;
      }
      if (!sim.players[seat].hand.length) { wins++; continue; }
      sim.turn = ((seat + sim.dir * (skip ? 2 : 1)) % sim.players.length + sim.players.length) % sim.players.length;
      // 用基础策略把这一局推演完
      let guard = 0;
      let winnerSeat = -1;
      while (guard++ < 400) {
        const cur = sim.players[sim.turn];
        if (!cur) break;
        if (!cur.hand.length) { winnerSeat = sim.turn; break; }
        const top = sim.discard[sim.discard.length - 1];
        const ctx = { stacking: sim.stacking, drawStack: sim.drawStack || 0, stackType: sim.stackType || null, hasColor: unoHasColor(cur.hand, sim.currentColor) };
        const playable = cur.hand.map((c, i) => ({ c: c, i: i })).filter(x => unoCanPlay(x.c, top, sim.currentColor, ctx));
        let idx = -1;
        if (playable.length) {
          // 基础策略：先数字后功能、万能留最后
          playable.sort((a, b) => {
            const wa = unoIsWild(a.c) ? 1 : 0, wb = unoIsWild(b.c) ? 1 : 0;
            if (wa !== wb) return wa - wb;
            const aa = (a.c.t === 'skip' || a.c.t === 'rev' || a.c.t === '+2') ? 1 : 0;
            const bb = (b.c.t === 'skip' || b.c.t === 'rev' || b.c.t === '+2') ? 1 : 0;
            if (aa !== bb) return aa - bb;
            return unoCardValue(b.c) - unoCardValue(a.c);
          });
          idx = playable[0].i;
        }
        if (idx === -1) {
          if (sim.drawStack > 0) {
            const amt = sim.drawStack;
            for (let i = 0; i < amt; i++) { const c = sim.deck.pop(); if (c) cur.hand.push(c); }
            sim.drawStack = 0; sim.stackType = null;
            sim.turn = ((sim.turn + sim.dir) % sim.players.length + sim.players.length) % sim.players.length;
            continue;
          }
          const c = sim.deck.pop();
          if (c) cur.hand.push(c);
          sim.turn = ((sim.turn + sim.dir) % sim.players.length + sim.players.length) % sim.players.length;
          continue;
        }
        const cd = cur.hand[idx];
        cur.hand.splice(idx, 1);
        sim.discard.push(cd);
        if (unoIsWild(cd)) {
          const counts = { R: 0, Y: 0, B: 0, G: 0 };
          for (const cc of cur.hand) if (cc && cc.c !== 'W') counts[cc.c]++;
          let bestC = 'R';
          for (const kk of UNO_COLORS) if (counts[kk] > counts[bestC]) bestC = kk;
          sim.currentColor = bestC;
        } else sim.currentColor = cd.c;
        if (!cur.hand.length) { winnerSeat = sim.turn; break; }
        let sk = false;
        if (cd.t === 'skip') sk = true;
        else if (cd.t === 'rev') { if (sim.players.length === 2) sk = true; else sim.dir = -sim.dir; }
        else if (cd.t === '+2' || cd.t === 'w4') {
          const target = ((sim.turn + sim.dir) % sim.players.length + sim.players.length) % sim.players.length;
          const amt = cd.t === '+2' ? 2 : 4;
          for (let i = 0; i < amt; i++) { const cc2 = sim.deck.pop(); if (cc2) sim.players[target].hand.push(cc2); }
          sk = true;
        }
        sim.turn = ((sim.turn + sim.dir * (sk ? 2 : 1)) % sim.players.length + sim.players.length) % sim.players.length;
      }
      if (winnerSeat === seat) wins++;
    }
    return sims ? wins / sims : 0;
  }

  // ---------- 渲染 ----------
  function unoCardHTML(card, opts) {
    const o = opts || {};
    const bg = UNO_COLOR_HEX[card.c] || '#374151';
    const label = card.c === 'W' ? (card.t === 'w4' ? '+4' : '🌈') : (UNO_TYPE_LABEL[card.t] || card.t);
    const w = o.w || 46, h = o.h || 64;
    const fs = o.fs || 15;
    // 功能牌（如「🚫 跳过」「🔄 反转」）文字保持单行并自动缩小字号，
    // 保证一手牌里所有卡牌的文字都居中在同一列上。
    const labelFs = String(label).length >= 4 ? Math.max(10, fs - 4) : fs;
    return '<div style="width:' + w + 'px;height:' + h + 'px;border-radius:8px;background:' + bg + ';color:#fff;display:flex;align-items:center;justify-content:center;font-size:' + labelFs + 'px;font-weight:700;border:2px solid ' + (o.border || 'rgba(255,255,255,0.35)') + ';box-shadow:0 2px 6px rgba(0,0,0,0.35);white-space:nowrap;overflow:hidden;' + (o.extra || '') + '">' + label + '</div>';
  }
