      return '<div style="display:flex;flex-direction:column;align-items:center;gap:2px;min-width:64px;">' +
        '<div style="position:relative;border:2px solid ' + (isTurn ? '#E11D48' : 'transparent') + ';border-radius:50%;padding:1px;">' + chatAvatarHTML(p.name, false, 34) + '</div>' +
