        '<div style="font-size:10.5px;color:var(--ubp-text-3);">🂠 ' + p.hand.length + ' 张 ' + unoTag + '</div>' +
        '</div>';
    }).join('');
    const playableIdxs = new Set(unoPlayableForUser(g).map(x => x.idx));
    const myTurn = g.turn === 0 && g.phase === 'playing';
    const handHTML = me.hand.map((c, i) => {
      const can = playableIdxs.has(i) && myTurn;
      const extra = 'cursor:' + (can ? 'pointer' : 'not-allowed') + ';opacity:' + (can ? '1' : '0.55') + ';transform:' + (can ? 'translateY(-4px)' : 'none') + ';';
      return '<span data-uno-act="uno-play" data-idx="' + i + '" title="' + unoCardText(c) + '">' + unoCardHTML(c, { extra: extra }) + '</span>';
