    let target = (g.phase === 'playing' && g.turn !== 0) ? g.turn : (function () { for (let i2 = 1; i2 < g.players.length; i2++) if (g.players[i2] && !g.players[i2].isUser) return i2; return undefined; })();
    if (!g.players[target] || g.players[target].isUser) target = (function () { for (let i2 = 1; i2 < g.players.length; i2++) if (g.players[i2] && !g.players[i2].isUser) return i2; return undefined; })();
    if (target === undefined) return;
