  // ---------- 操作分发 ----------
  function handleUnoAction(act, target) {
    const g = unoGame;
    if (act === 'uno-open') {
      if (g && g.phase === 'playing') renderUnoGameUI();
      else if (hasSavedUnoGame()) resumeSavedUnoGame();
      else renderUnoLobby();
      return;
    }
    if (act === 'uno-back') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); renderTableGameLobby(); return; }
    if (act === 'uno-settings') { renderUnoSettings(); return; }
    if (act === 'uno-invite') { unoInviteOverlay(); return; }
    if (act === 'uno-invite-close') { const ov = sheet.querySelector('.uno-invite-overlay'); if (ov) ov.remove(); return; }
    if (act === 'uno-invite-confirm') { const ov = sheet.querySelector('.uno-invite-overlay'); if (ov) ov.remove(); renderUnoLobby(); return; }
    if (act === 'uno-start') {
      if (aiChatInviteGate({
        chatOn: loadUnoConfig().aiChat,
        invited: unoInvites.filter(Boolean).length,
        label: 'UNO',
        onInvite: () => unoInviteOverlay(),
        onDisableAndStart: () => { const c2 = loadUnoConfig(); c2.aiChat = false; saveUnoConfig(c2); handleUnoAction('uno-start', null); }
      })) return;
      const n = unoInvites.filter(Boolean).length;
      if (n < 3) showToast('🪑 入座 ' + n + '/3，其余席位由机器人补位');
      unoStartMatch(unoInvites.slice());
      return;
    }
    if (act === 'uno-exit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      if (g && g.phase === 'playing') saveUnoGameState();
      else clearSavedUnoGame();
      if (unoAiTimer) clearTimeout(unoAiTimer);
      unoGenCounter++;
      unoGame = null;
      renderUnoLobby();
      return;
    }
    if (act === 'uno-resume') { resumeSavedUnoGame(); return; }
    if (act === 'uno-discard') { clearSavedUnoGame(); renderUnoLobby(); showToast('🗑️ 已放弃进行中的 UNO 对局'); return; }
    // 设置项与"返回 UNO 大厅"必须放在"进行中对局"守卫之前：
    // 否则从大厅进入设置后，难度/变体/关闭按钮会被守卫直接 return 掉，全部失效。
    if (act === 'uno-set-level') {
      const lvl = target && target.dataset ? target.dataset.level : null;
      if (!lvl) return;
      const c = loadUnoConfig();
      c.aiLevel = lvl;
      saveUnoConfig(c);
      renderUnoSettings();
      showToast('🧠 UNO AI 难度已切换：' + (lvl === 'strong' ? '高级（蒙特卡洛）' : lvl === 'fast' ? '基础（新手）' : '进阶'));
      return;
    }
    if (act === 'uno-settings-done') { renderUnoLobby(); return; }
    if (act === 'uno-rematch') {
      const names = (g && g.players) ? g.players.slice(1).map(p => p.name).filter(n => n && n.indexOf('牌友') !== 0) : unoInvites.slice();
      if (aiChatInviteGate({
        chatOn: loadUnoConfig().aiChat,
        invited: names.filter(n2 => !isBuiltinPlayerName(n2)).length,
        label: 'UNO',
        onInvite: () => renderUnoLobby(),
        onDisableAndStart: () => { const c2 = loadUnoConfig(); c2.aiChat = false; saveUnoConfig(c2); handleUnoAction('uno-rematch', null); }
      })) return;
      if (unoAiTimer) clearTimeout(unoAiTimer);
      unoStartMatch(names.length >= 3 ? names.slice(0, 3) : names.concat(unoInvites.slice(0, 3)));
      return;
    }
    if (act === 'uno-send-chat') { unoHandleUserChatSend(); return; }
    if (!g || g.phase !== 'playing') return;
    if (act === 'uno-call') {
      const me = g.players[0];
      if (me.hand.length === 1 && !me.saidUno) {
        if (g.pendingUno && g.pendingUno.deadline && Date.now() > g.pendingUno.deadline) { showToast('⌛ 超过 5 秒，喊 UNO 失败！'); return; }
        me.saidUno = true;
        if (g.pendingUno && g.pendingUno.seat === 0) g.pendingUno = null;
        unoLog(g, '📣 你在 5 秒内喊了 UNO！');
        saveUnoGameState();
        renderUnoGameUI();
      }
      return;
    }
    if (act === 'uno-call-zero') {
      const pz = g.pendingZero;
      if (!pz || !(pz.pendingSeats || []).includes(0)) return;
      if (pz.deadline && Date.now() > pz.deadline) { showToast('⌛ 超过 5 秒，喊 UNO 失败！'); return; }
      pz.pendingSeats = pz.pendingSeats.filter(s => s !== 0);
      unoLog(g, '📣 你在 5 秒内喊了 UNO！');
      if (!pz.pendingSeats.length) g.pendingZero = null;
      saveUnoGameState();
      renderUnoGameUI();
      return;
    }
    if (act === 'uno-take-penalty') {
      if (g.turn !== 0 || (g.drawStack || 0) <= 0) return;
      if (!unoBeginTurn(g, 0)) return; // 无叠牌时会自动认罚并跳到下家
      const amt = g.drawStack;
      if ((g.drawStack || 0) > 0) { unoDrawToHand(g, 0, amt); unoLog(g, '😭 你认罚摸 ' + amt + ' 张并跳过。'); g.drawStack = 0; g.stackType = null; g.turn = unoNextSeat(g, 0); saveUnoGameState(); renderUnoGameUI(); if (g.turn !== 0) unoScheduleAi(unoDelayFor(g)); }
      return;
    }
    if (act === 'uno-color') {
      const color = target && target.dataset ? target.dataset.color : null;
      if (!color || !g.pendingColor) return;
      const idx = g.pendingColor.idx;
      g.pendingColor = null;
      if (!unoPlayCard(0, idx, color, false)) { showToast('❌ 这张牌现在不能出'); renderUnoGameUI(); }
      return;
    }
    if (g.turn !== 0) { showToast('⏳ 还没轮到你'); return; }
    if (act === 'uno-draw') {
      if (!unoBeginTurn(g, 0)) return;
      const playableBefore = unoPlayableList(g, 0).length > 0;
      if (playableBefore) { showToast('💡 你有能出的牌，也可以选择主动摸牌（摸牌后跳过回合）'); }
      const drawn = unoDrawToHand(g, 0, 1);
      g.actionCount++;
      g.userActions = (g.userActions || 0) + 1;
      if (!drawn) { showToast('牌库空了'); return; }
      unoLog(g, '🖐 你摸了一张牌，回合结束（摸牌后不能出牌）。');
      unoMaybeAutoSpeak('draw', 0);
      g.turn = unoNextSeat(g, 0);
      saveUnoGameState();
      renderUnoGameUI();
      if (g.turn !== 0) unoScheduleAi(unoDelayFor(g));
      return;
    }
    if (act === 'uno-play') {
      const idx = target && target.dataset ? parseInt(target.dataset.idx, 10) : -1;
      if (!(idx >= 0)) return;
      if (!unoBeginTurn(g, 0)) return;
      const playable = unoPlayableForUser(g);
      const item = playable.find(x => x.idx === idx);
      if (!item) { showToast('❌ 只能出与当前颜色/数字相同的牌，或黑色万能牌'); return; }
      if (unoIsWild(item.card)) {
        g.pendingColor = { idx: idx, card: item.card };
        renderUnoGameUI();
        showToast('🌈 请选择下一轮的颜色');
        return;
      }
      unoPlayCard(0, idx, null, false);
      return;
    }
  }

