  // ---------- 建议 AI（标准策略表 + 爆牌概率） ----------
  function bjBustProb(cards, shoe, level) {
    // 估算"再要一张就爆"的概率（强力档按剩余牌精算，标准档按剩余大牌比例近似，快速档不估算）
    const v = bjHandValue(cards).total;
    if (v >= 21) return 0;
    const need = 21 - v;
    if (level === 'fast') return 0;
    if (!shoe || !shoe.length) return 0;
    if (level === 'normal') {
      let high = 0;
      for (const c of shoe) { const val = c.r === 'A' ? 11 : (['J', 'Q', 'K', '10'].includes(c.r) ? 10 : parseInt(c.r, 10)); if (val > need) high++; }
      return high / shoe.length;
    }
    let bust = 0;
    for (const c of shoe) { const val = c.r === 'A' ? (v + 11 <= 21 ? 11 : 1) : (['J', 'Q', 'K', '10'].includes(c.r) ? 10 : parseInt(c.r, 10)); if (v + val > 21) bust++; }
    return bust / shoe.length;
  }
  function bjAdvise(hand, dealerUp, g, level) {
    const cards = hand.cards.filter(c => c && !c.hole);
    const v = bjHandValue(cards);
    const canDouble = cards.length === 2 && g.chips >= hand.bet;
    const canSplit = cards.length === 2 && bjHandValue([cards[0]]).total === bjHandValue([cards[1]]).total && g.chips >= hand.bet && g.hands.length < 3;
    const up = dealerUp ? (dealerUp.r === 'A' ? 11 : (['J', 'Q', 'K', '10'].includes(dealerUp.r) ? 10 : parseInt(dealerUp.r, 10))) : 0;
    if (canSplit && ['A', '8'].includes(cards[0].r)) return { act: 'split', why: '对子 ' + cards[0].r + ' 分牌更优（分 A 可各自追求 21，分 8 可摆脱 16 点）' };
    if (v.total >= 17 || (v.total >= 13 && up <= 6 && !v.soft)) {
      // 强力档：若爆牌概率仍很低且对手弱，可考虑加倍
      if (level === 'strong' && canDouble && v.total >= 10 && up <= 6) return { act: 'double', why: '你 ' + v.total + ' 点、庄家明牌弱（' + up + '），加倍期望收益更高' };
      return { act: 'stand', why: '你 ' + v.total + ' 点，' + (v.total >= 17 ? ' ≥17 应停牌' : '庄家明牌 ≤6 风险大，停牌等其爆牌') };
    }
    if (v.total <= 11) {
      if (canDouble && v.total === 11) return { act: 'double', why: '11 点加倍：下一张 10 点即 21，收益最大' };
      if (canDouble && level !== 'fast' && v.total === 10 && up <= 9) return { act: 'double', why: '10 点对庄家非强牌加倍更优' };
      return { act: 'hit', why: v.total + ' 点必叫（不会爆牌）' };
    }
    // 12~16：看庄家明牌
    if (up >= 7) return { act: 'hit', why: v.total + ' 点，庄家明牌强（' + up + '）必须叫牌' };
    return { act: 'stand', why: v.total + ' 点，庄家明牌弱（' + up + '），停牌等庄家爆' };
  }
  function bjCurrentAdvice() {
    const g = bjGame;
