    if (!g || g.phase !== 'play') return null;
    const h = g.hands.find(x => !x.done);
    if (!h) return null;
    const up = g.dealer && g.dealer[1] ? g.dealer[1] : null;
    const adv = bjAdvise(h, up, g, 'normal');
    const bp = bjBustProb(h.cards, g.shoe, 'normal');
