      hit: '主角刚向你要了一张牌',
      double: '主角选择了加倍',
      split: '主角选择了分牌',
      bust: '主角爆牌了',
      stand: '主角停牌了',
      insurance: '主角刚决定是否买保险',
      win: '主角赢了这一局',
      lose: '主角输了这一局',
      push: '这一局平手',
      'user-chat': '主角正在牌桌上对你说话，你需要回应主角'
    }[scene] || '牌桌上的闲聊时刻';
    const h0 = (g.hands && g.hands[0]) || null;
    const myHand = h0 ? h0.cards.map(bjCardText).join(' ') + '（' + bjHandValue(h0.cards).total + ' 点）' : '（尚未发牌）';
    const dealerUp = g.dealer && g.dealer[1] ? bjCardText(g.dealer[1]) : '（尚未发牌）';
    const recentEvents = (g.log || []).slice(-8).join('\n');
    const system = '你和主角正在玩一局《21点（黑杰克）》，你扮演【' + p.name + '】，是这桌的荷官，负责发牌和牌桌上的自然聊天。\n' +
      '【角色档案（来自小手机/神数据库）】\n' +
      '- 身份：' + (prof.identity || p.identity || '荷官') + '\n' +
