      '- 说话风格与口癖：' + (prof.languageStyle || '口语化') + '\n' +
      '- 对主角态度：' + (prof.attitude || '友好亲近') + '\n' +
      '【小手机内你们最近的微信聊天记录】\n' + (phoneCtx || '（暂无，按人物关系自然发挥）') + '\n\n' +
      '【' + p.name + ' 在小手机里的近期社交动态（朋友圈/贴吧/小红书）】\n' + (socialCtx || '（暂无）') + '\n\n' +
      '【牌局信息】\n' +
      '- 主角手牌：' + myHand + '\n' +
      '- 你的明牌：' + dealerUp + '\n' +
      '- 主角筹码：' + g.chips + ' · 本局赌注 ' + (h0 ? h0.bet : g.baseBet) + '\n' +
      '- 当前场景：' + sceneText + '\n' +
      '- 牌桌最近发生的事情（从旧到新）：\n' + (recentEvents || '（开局阶段）') + '\n' +
      '- 你上一句说过的话：' + (((g.speeches || []).slice(-1)[0] || {}).text || '（暂无）') + '\n\n' +
      '【台词要求】\n' +
      '1. 完全代入【' + p.name + '】的身份、性格、语言风格与对主角的态度，说出生动自然的真人台词。\n' +
      '2. 【重点】必须围绕牌桌刚才发生了什么来发言：发牌、点评主角的要牌/停牌/加倍/分牌、爆牌与输赢的打趣，或顺势聊你们在小手机微信/朋友圈里的互动。\n' +
      '3. 【铁律】绝对不允许透露自己的暗牌；按荷官的身份不可以作弊提示。\n' +
      '4. 严禁使用括号、旁白、动作与心理描写，只输出角色说出口的话。\n' +
      '5. 【完整出字铁律】只输出：<lines>台词正文</lines>，不要多余文字；发言长度自然，可长可短，口语化；必须语义完整、自然收尾，严禁半句截断、严禁空回复。';
    const messages = [{ role: 'system', content: system }];
    if (userMsg) messages.push({ role: 'user', content: '【主角对你说】' + userMsg + '\n请以【' + p.name + '】的口吻回一句。' });
    else messages.push({ role: 'user', content: '请以【' + p.name + '】的口吻说一段完整的牌桌台词（发言长度自然，可长可短，口语化；必须语义完整、自然收尾）。' });
    bjChatBusy = true;
    g.lastSpeechAt = Date.now();
    apiChat(messages, apiCfg, { maxTokens: 900, temperature: 0.95 }).then(res => {
      if (gen !== bjGenCounter || !bjGame || bjGame.session !== g.session) return;
      let clean = ensureCompleteLine(String(res || '').replace(/<lines>|<\/lines>/gi, '').replace(/["'「」]/g, '').trim());
      if (p.name) clean = clean.replace(new RegExp('^' + p.name + '[：:]\\s*'), '');
      if (!clean || clean.length < 4) return;
      if (!/[。！？…]$/.test(clean)) clean += '。';
      bjPushSpeech(1, clean);
      bjRefreshSpeechBox();
    }).catch(() => { /* 静默失败 */ }).finally(() => { if (gen === bjGenCounter) bjChatBusy = false; });
  }
  function bjRefreshSpeechBox() {
    const el = sheet?.querySelector('#bj-speech-text');
    const container = sheet?.querySelector('#bj-speech-container');
    if (!el || !bjGame) return;
    el.innerHTML = bjRenderSpeechHTML();
    if (container) container.scrollTop = container.scrollHeight;
  }
  function bjRenderSpeechHTML() {
    const g = bjGame;
    if (!g) return '';
    const conv = (g.speeches || []).slice(-24);
    if (!conv.length) return '<span style="color:var(--ubp-text-3);">（荷官正等着你下注…）</span>';
    return conv.map(sp => chatSpeechRowHTML(sp.name, sp.text, sp.seat === 0)).join('');
  }
  function bjHandleUserChatSend() {
    const g = bjGame;
    if (!g || g.aiChat === false) return;
    const input = sheet.querySelector('#bj-chat-input');
    if (!input) return;
    const msg = input.value.trim();
    if (!msg) return;
    input.value = '';
    g.speeches.push({ seat: 0, name: '我', text: msg });
    bjRefreshSpeechBox();
    bjRequestSpeech('user-chat', msg);
  }

  // ---------- 断点保存 ----------
  function bjSaveGame() {
    const g = bjGame;
    if (!g || g.phase === 'sessionEnd') { clearSavedBjGame(); return; }
    try {
      localStorage.setItem(BJ_SAVE_KEY, JSON.stringify({
        session: g.session, decks: g.decks, insuranceAllowed: g.insuranceAllowed,
        aiLevel: g.aiLevel, aiChat: g.aiChat !== false, speechInterval: g.speechInterval || 4,
        chips: g.chips, baseBet: g.baseBet, bet: g.bet,
        dealerChar: g.dealerChar, shoe: g.shoe, shoeIndex: g.shoeIndex, seenCards: g.seenCards || [], hands: g.hands, dealer: g.dealer,
        phase: g.phase, round: g.round, wins: g.wins, losses: g.losses, pushes: g.pushes, userActions: g.userActions || 0,
        insurance: g.insurance, insuranceOffered: g.insuranceOffered, insuranceTaken: g.insuranceTaken,
        log: g.log, history: g.history, speeches: g.speeches, netChips: g.netChips, recorded: g.recorded,
        sessionStartChips: Number.isFinite(g.sessionStartChips) ? g.sessionStartChips : g.chips
      }));
    } catch (e) { /* ignore */ }
  }
  function bjScheduleSave() {
    if (bjSaveTimer) clearTimeout(bjSaveTimer);
    bjSaveTimer = setTimeout(() => { bjSaveTimer = null; if (bjGame) bjSaveGame(); }, 200);
  }
  function clearSavedBjGame() { try { localStorage.removeItem(BJ_SAVE_KEY); } catch (e) { /* ignore */ } }
  function hasSavedBjGame() { try { const raw = localStorage.getItem(BJ_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && d.hands && d.phase && d.phase !== 'sessionEnd'); } catch (e) { return false; } }
  function bjResumeGame() {
    try {
      const raw = localStorage.getItem(BJ_SAVE_KEY);
      if (!raw) { renderBjLobby(); return; }
      const d = JSON.parse(raw);
      bjGenCounter++;
      bjChatBusy = false;
      if (bjAiTimer) { clearTimeout(bjAiTimer); bjAiTimer = null; }
      bjGame = {
        session: d.session || (Date.now() + '_' + Math.floor(Math.random() * 100000)),
        decks: d.decks || 4, insuranceAllowed: d.insuranceAllowed !== false,
        aiLevel: d.aiLevel || 'normal', aiChat: d.aiChat !== false, speechInterval: d.speechInterval || 4,
        chips: d.chips || 200, baseBet: d.baseBet || 10, bet: d.bet || 10,
        dealerChar: d.dealerChar || { name: '荷官', avatar: '', identity: '赌场荷官' },
        shoe: d.shoe || bjBuildShoe(4), shoeIndex: d.shoeIndex || 0, reshuffled: false, seenCards: d.seenCards || [],
        hands: d.hands || [], dealer: d.dealer || [], phase: d.phase || 'play', round: d.round || 1,
        wins: d.wins || 0, losses: d.losses || 0, pushes: d.pushes || 0, userActions: d.userActions || 0,
        insurance: d.insurance || 0, insuranceOffered: !!d.insuranceOffered, insuranceTaken: !!d.insuranceTaken,
        log: d.log || [], history: d.history || [], speeches: d.speeches || [], lastSpeechAt: 0,
