  // ---------- 渲染 ----------
  function bjCardHTML(card, opts) {
    const o = opts || {};
    if (!card) return '';
    const hidden = o.hidden || card.hole;
    const red = bjIsRed(card);
    return '<div style="width:' + (o.w || 46) + 'px;height:' + (o.h || 66) + 'px;border-radius:7px;background:' + (hidden ? 'repeating-linear-gradient(45deg,#1e3a8a,#1e3a8a 6px,#172554 6px,#172554 12px)' : '#F9FAFB') + ';border:1.5px solid ' + (hidden ? '#0f172a' : '#9CA3AF') + ';display:flex;align-items:center;justify-content:center;font-size:' + (o.fs || 17) + 'px;font-weight:700;color:' + (red ? '#DC2626' : '#111827') + ';box-shadow:0 2px 5px rgba(0,0,0,0.25);" title="' + (hidden ? '暗牌' : bjCardText(card)) + '">' + (hidden ? '' : bjCardText(card)) + '</div>';
  }
  function bjRender() {
