    } else if (g.phase === 'play') {
      actions = '<button data-bj-act="bj-hit" class="ubp-btn" style="flex:1;padding:7px;font-size:12.5px;background:#10B981;color:#fff;border:none;font-weight:700;">🃏 要牌</button>' +
        '<button data-bj-act="bj-stand" class="ubp-btn" style="flex:1;padding:7px;font-size:12.5px;">✋ 停牌</button>' +
        '<button data-bj-act="bj-double" class="ubp-btn" style="flex:1;padding:7px;font-size:12.5px;">💥 加倍</button>' +
