      '    <span style="font-size:14.5px;font-weight:600;">🎰 21点 · <span style="font-size:11px;color:var(--ubp-text-3);">第 ' + g.round + ' 局 · 牌靴 ' + g.decks + ' 副 · 剩 ' + (g.shoe ? g.shoe.length : 0) + ' 张</span></span>',
