      '<div id="bj-speech-container" style="max-height:96px;overflow-y:auto;background:rgba(0,0,0,0.14);border-radius:8px;padding:6px 8px;margin-top:6px;flex:none;"><div id="bj-speech-text">' + bjRenderSpeechHTML() + '</div></div>',
      '<div style="display:flex;gap:6px;margin-top:6px;flex:none;">',
      '  <input id="bj-chat-input" placeholder="对荷官说点什么…" style="flex:1;min-width:0;padding:7px 10px;border-radius:8px;border:1px solid var(--ubp-line);background:var(--ubp-card-2, #26262a);color:var(--ubp-text);font-size:12.5px;">',
      '  <button data-bj-act="bj-send-chat" class="ubp-btn" style="padding:7px 12px;font-size:12.5px;">发送</button>',
