  function handleBjAction(act, target) {
    const g = bjGame;
    if (act === 'bj-open') {
      if (g && g.phase !== 'sessionEnd') bjRender();
      else if (hasSavedBjGame()) bjResumeGame();
      else renderBjLobby();
      return;
    }
    if (act === 'bj-back') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); renderCardLobby(); return; }
    if (act === 'bj-invite') { bjInviteOverlay(); return; }
    if (act === 'bj-invite-close') { const ov = sheet.querySelector('.bj-invite-overlay'); if (ov) ov.remove(); return; }
    if (act === 'bj-invite-confirm') {
      const ov = sheet.querySelector('.bj-invite-overlay');
      if (ov) ov.remove();
      renderBjLobby();
      showToast('🪑 荷官已就位：' + (bjInvites[0] || '默认荷官'));
      return;
    }
    if (act === 'bj-settings') { renderBjSettings(); return; }
    if (act === 'bj-settings-done') { renderBjLobby(); return; }
    if (act === 'bj-start') {
      const cfgB = loadBjConfig();
      if (ensureStartChips('blackjack', cfgB.chips) < (cfgB.baseBet || 10)) {
        showToast('🪙 21点筹码不足底注，请先用积分兑换筹码');
        renderChipExchange('blackjack', () => renderBjLobby());
        return;
      }
      if (aiChatInviteGate({
        chatOn: cfgB.aiChat,
        invited: bjInvites.filter(Boolean).length,
        label: '21点',
        onInvite: () => bjInviteOverlay(),
        onDisableAndStart: () => { const c2 = loadBjConfig(); c2.aiChat = false; saveBjConfig(c2); handleBjAction('bj-start', null); }
      })) return;
      if (bjGame && bjGame.phase !== 'sessionEnd' && !bjGame.recorded && (bjGame.hands || []).length) {
        // 已有未结算的牌局：先按【退出】规则结算上一场，再开新场
        bjEndSession();
      } else if (hasSavedBjGame()) {
        // 仅有历史存档（曾中途关闭）：先静默结算旧场筹码差，再开新场
        bjSettleSavedAbandon();
        clearSavedBjGame();
      }
      bjNewGame(bjInvites.slice(0, 1));
      return;
    }
    if (act === 'bj-resume') { bjResumeGame(); return; }
    if (act === 'bj-discard') { bjSettleSavedAbandon(); clearSavedBjGame(); renderBjLobby(); showToast('🗑️ 已放弃进行中的 21 点对局（筹码差已结算）'); return; }
    if (act === 'bj-exit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      if (g && g.phase !== 'sessionEnd') bjSaveGame();
      else clearSavedBjGame();
      if (bjAiTimer) clearTimeout(bjAiTimer);
      bjGenCounter++;
      bjGame = null;
      renderBjLobby();
      return;
    }
    if (act === 'bj-restart') {
      const cfgR = loadBjConfig();
      if (ensureStartChips('blackjack', cfgR.chips) < (cfgR.baseBet || 10)) {
        showToast('🪙 21点筹码不足底注，请先用积分兑换筹码');
        renderChipExchange('blackjack', () => renderBjLobby());
        return;
      }
      const dealerInvited = (g && g.dealerChar && g.dealerChar.name && !isBuiltinPlayerName(g.dealerChar.name)) ? 1 : 0;
      if (aiChatInviteGate({
        chatOn: cfgR.aiChat,
        invited: dealerInvited,
        label: '21点',
        onInvite: () => renderBjLobby(),
        onDisableAndStart: () => { const c2 = loadBjConfig(); c2.aiChat = false; saveBjConfig(c2); handleBjAction('bj-restart', null); }
      })) return;
      bjNewGame(dealerInvited ? [g.dealerChar.name] : []);
      return;
    }
    if (act === 'bj-set-level') {
      const lvl = target && target.dataset ? target.dataset.level : null;
      if (!lvl) return;
      const c = loadBjConfig(); c.aiLevel = lvl; saveBjConfig(c);
      if (bjGame) bjGame.aiLevel = lvl;
      renderBjSettings();
      showToast('🧠 荷官难度已切换：' + bjDealerLevelName(lvl));
      return;
    }
    if (act === 'bj-send-chat') { bjHandleUserChatSend(); return; }
    if (act === 'bj-advise') { bjShowAdvice(); return; }
    if (!g) return;
    if (act === 'bj-hit') { bjUserHit(); return; }
    if (act === 'bj-stand') { bjUserStand(); return; }
    if (act === 'bj-double') { bjUserDouble(); return; }
    if (act === 'bj-split') { bjUserSplit(); return; }
    if (act === 'bj-insure') { bjUserInsurance(true); return; }
    if (act === 'bj-noinsure') { bjUserInsurance(false); return; }
    if (act === 'bj-next') { bjNextRound(); return; }
    if (act === 'bj-end') { bjEndSession(); return; }
  }
  // ========== 统一对局结束入口 ==========
  // matchInfo: { gameType, result, detail, players:[{name,isUser,avatar}], opponentName?, replay? }
  // 小游戏大厅（🕹️ 小游戏）里的休闲小游戏不写入【对局记录】：以后新增小游戏时，把它的 gameType 加进这里即可
  const MINI_GAME_NO_RECORD_TYPES = { minesweeper: true };
  function onGameFinished(matchInfo) {
    if (!matchInfo || !matchInfo.gameType) return;
    // 积分结算：斗地主按叫分，其余游戏胜 +1 / 负 -1（平局不变）
    try { applyMatchPoints(matchInfo); } catch (e) { /* ignore */ }
    // 小游戏大厅的休闲小游戏（扫雷等）：只结算积分，不写入对局记录（含以后新增的小游戏）
    if (MINI_GAME_NO_RECORD_TYPES[matchInfo.gameType]) return;
    const recordId = 'gm_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
    recordGenericMatch({
      id: recordId,
      gameType: matchInfo.gameType,
      result: matchInfo.result,
      detail: matchInfo.detail,
      replay: matchInfo.replay || '',
      replayRich: matchInfo.replayRich || null,
      players: matchInfo.players || [],
      spectators: Array.isArray(matchInfo.spectators) ? matchInfo.spectators : null,
      // 积分必须带入对局记录，否则世界书「积分」一栏永远是空串
      pointsDelta: matchInfo.pointsDelta,
      pointsTotal: matchInfo.pointsTotal
    });
    // 仅保留对局记录与积分结算
  }

