  function resumeCurrentPhase() {
    if (!game || isGameOver) return;
    if (game.nightToken === undefined) game.nightToken = 0;
    // 后台等待玩家遗言：重进时直接恢复遗言输入界面，不重跑其它流程
    if (typeof game.resolvingFinalWords === 'function') {
      showUserFinalWordsUI();
      return;
    }
    if (game.phase === 'night') {
      // 按夜晚子步骤续跑，避免重进后验人/刀人/用药整晚重跑
      const step = game.nightStep || 'guard';
      if (step === 'guard') stepGuardAction();
      else if (step === 'wolf') stepWolfAction();
      else if (step === 'witch') stepWitchAction();
      else if (step === 'end') finishNightAndStartDay();
      else runNightSequence();
    } else if (game.phase === 'day') {
      // PK 辩解阶段仍处于 day：恢复 PK 进度而不是重开白天发言
      if (game.isPkSpeaking && game.pkCandidates && game.pkCandidates.length) runNextPkSpeaker();
      else if (game.sheriffStage && game.sheriffStage !== 'done') resumeSheriffStage();
      else if (!game.dayAnnounced) afterSheriffElection(!!(game.sheriffPos && !game.sheriffBadgeTorn));
      else startSpeaking();
    } else if (game.phase === 'vote') {
      if (game.isPkVote) {
        startPkVote();
      } else {
        startVote();
      }
    }
  }

