  function addGameIcon() {
    const doc = getAppendDoc();
    if (!doc || !doc.body) return false;
    const vw = doc.defaultView || window;
    if (doc.getElementById('thgame-fab-root')) return true;
    fabRoot = document.createElement('div');
    fabRoot.id = 'thgame-fab-root';
    const savedFabPos = loadSavedPos(FAB_POS_KEY);
    const initLeft = savedFabPos ? savedFabPos.x : Math.max(4, (vw.innerWidth || window.innerWidth) - 72);
    const initTop = savedFabPos ? savedFabPos.y : Math.max(4, Math.round((vw.innerHeight || window.innerHeight) * (vw.innerWidth < 640 ? 0.70 : 0.74)));
    fabRoot.style.cssText = 'position:fixed;left:' + initLeft + 'px;top:' + initTop + 'px;z-index:2147483000;width:0;height:0;';
    fabRing = document.createElement('div');
    fabRing.id = 'thgame-fab-ring';
    fabRing.style.cssText = 'position:absolute;left:0;top:0;display:none;';
    const ITEM = 42;
    const GAP = 23;

    // 每次展开按按钮当前位置与屏幕空间自动布局：
    // ① 四周无阻挡 → 以按钮为中心围成一圈，并预留一个空位供后续新游戏图标扩展；
    // ② 被边缘阻挡 → 朝屏幕开阔方向扇形展开（在角落时限制在 90° 夹角内）；
    // ③ 空间过小 → 自动多圈/网格收缩。
    function layoutFabRing() {
      const vwW = vw.innerWidth || window.innerWidth || 1024;
      const vwH = vw.innerHeight || window.innerHeight || 768;
      const rect = fabRoot.getBoundingClientRect();
      const cx = rect.left;
      const cy = rect.top;
      const margin = 36;
      const n = FLOATING_GAMES.length;
      const items = Array.from(fabRing.querySelectorAll('.thgame-fab-item'));
      const Rmin = 54;
      const spacing = 50;
      const minStepDeg = (R) => 2 * Math.asin(Math.min(1, GAP / R)) * 180 / Math.PI;
      const capOf = (R, sp) => Math.max(1, Math.floor(sp * 2 / minStepDeg(R)) + 1);
      const putGrid = () => {
        const cols = Math.min(3, Math.max(2, Math.ceil(Math.sqrt(n))));
        const rows = Math.ceil(n / cols);
        const cell = ITEM + 8;
        const gridW = cols * cell;
        const gridH = rows * cell;
        let gx = (vwW - cx >= cx) ? cx + 22 : cx - 22 - gridW;
        let gy = (vwH - cy >= cy) ? cy + 22 : cy - 22 - gridH;
        gx = Math.max(8, Math.min(vwW - gridW - 8, gx));
        gy = Math.max(8, Math.min(vwH - gridH - 8, gy));
        items.forEach((el, i2) => {
          const col = i2 % cols;
          const row = Math.floor(i2 / cols);
          el.style.left = (gx + col * cell - cx) + 'px';
          el.style.top = (gy + row * cell - cy) + 'px';
        });
      };
      const minDist = Math.min(cx, vwW - cx, cy, vwH - cy) - margin;
      // ① 空间充足：从按钮边开始围成圆，内圈满了再向四周扩展（最外圈留一个扩展空位）
      if (minDist >= Rmin) {
        let remaining = n;
        let ringR = Rmin;
        const plans = [];
        while (remaining > 0 && ringR <= minDist) {
          const cap = Math.floor(360 / minStepDeg(ringR));
          if (remaining <= cap - 1) { plans.push({ R: ringR, take: remaining, gap: true }); remaining = 0; }
          else { plans.push({ R: ringR, take: cap, gap: false }); remaining -= cap; }
          ringR += spacing;
        }
        if (remaining === 0) {
          let idx = 0;
          for (const pl of plans) {
            const step = pl.gap ? 360 / (pl.take + 1) : 360 / pl.take;
            const start = 90 + (pl.gap ? step / 2 : 0);
            for (let i = 0; i < pl.take && idx < n; i++, idx++) {
              const rad = (start + i * step) * Math.PI / 180;
              const el = items[idx];
              if (!el) continue;
              el.style.left = (pl.R * Math.cos(rad) - ITEM / 2) + 'px';
              el.style.top = (pl.R * Math.sin(rad) - ITEM / 2) + 'px';
            }
          }
          return;
        }
      }
      // ② 被边缘阻挡：朝开阔方向扇形展开；角落固定 90° 夹角并沿对角线从按钮边向外扩展
      const left = cx < vwW / 2;
      const top = cy < vwH / 2;
      const corner = (Math.min(cx, vwW - cx) < 170) && (Math.min(cy, vwH - cy) < 170);
      let centerAng;
      if (corner) centerAng = top ? (left ? 45 : 135) : (left ? 315 : 225);
      else {
        const dx = vwW / 2 - cx;
        const dy = vwH / 2 - cy;
        if (Math.hypot(dx, dy) < 160) centerAng = (vwW - cx >= cx) ? 0 : 180;
        else centerAng = Math.atan2(dy, dx) * 180 / Math.PI;
      }
      let span = corner ? 45 : 52;
      const fits = (R, sp) => {
        for (const f of [0, 0.5, 1]) {
          const rad = (centerAng + (f - 0.5) * sp * 2) * Math.PI / 180;
          const x = cx + R * Math.cos(rad);
          const y = cy + R * Math.sin(rad);
          if (x < margin || x > vwW - margin || y < margin || y > vwH - margin) return false;
        }
        return true;
      };
      let rAvail = 190;
      while (rAvail > Rmin && !fits(rAvail, span)) rAvail -= 6;
      if (!fits(rAvail, span)) {
        for (const s2 of [38, 28, 18]) {
          span = Math.min(span, s2);
          rAvail = 190;
          while (rAvail > Rmin && !fits(rAvail, span)) rAvail -= 6;
          if (fits(rAvail, span)) break;
        }
      }
      if (rAvail < Rmin + 6) { putGrid(); return; }
      let remaining = n;
      let ringR = Rmin;
      let idx = 0;
      while (remaining > 0 && ringR <= rAvail + 0.5) {
        const cap = capOf(ringR, span);
        const take = Math.min(remaining, cap);
        const step = take > 1 ? (span * 2) / (take - 1) : 0;
        for (let i = 0; i < take && idx < n; i++, idx++) {
          const rad = (centerAng - span + i * step) * Math.PI / 180;
          const el = items[idx];
          if (!el) continue;
          el.style.left = (ringR * Math.cos(rad) - ITEM / 2) + 'px';
          el.style.top = (ringR * Math.sin(rad) - ITEM / 2) + 'px';
        }
        remaining -= take;
        ringR += spacing;
      }
      if (remaining > 0) putGrid();
    }

    FLOATING_GAMES.forEach((gItem) => {
      const item = document.createElement('div');
      item.className = 'thgame-fab-item';
      item.title = gItem.title;
      item.style.cssText = 'position:absolute;left:0;top:0;width:' + ITEM + 'px;height:' + ITEM + 'px;border-radius:50%;background:' + gItem.color + ';border:2px solid rgba(255,255,255,0.75);box-shadow:0 3px 10px rgba(0,0,0,0.45);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:18px;line-height:1;user-select:none;transition:transform 0.12s;overflow:visible;';
      item.textContent = gItem.icon;
      const label = document.createElement('div');
      label.textContent = gItem.title;
      label.style.cssText = 'position:absolute;left:50%;transform:translateX(-50%);top:' + (ITEM + 1) + 'px;font-size:9px;color:#ffffff;text-shadow:0 1px 4px rgba(0,0,0,0.9);white-space:nowrap;';
      item.appendChild(label);
      item.addEventListener('mouseenter', () => { item.style.transform = 'scale(1.14)'; });
      item.addEventListener('mouseleave', () => { item.style.transform = 'scale(1)'; });
      item.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        openGameFromFab(gItem.act);
      });
      fabRing.appendChild(item);
    });
    const fabBtn = document.createElement('button');
    fabBtn.className = 'thgame-fab-btn';
    fabBtn.title = '游戏大厅（可拖动）';
    fabBtn.style.cssText = 'position:absolute;left:-26px;top:-26px;width:52px;height:52px;border-radius:50%;border:2px solid rgba(255,255,255,0.85);background:radial-gradient(circle at 30% 30%, #a78bfa, #7c3aed 60%, #5b21b6);box-shadow:0 5px 14px rgba(0,0,0,0.55);cursor:grab;touch-action:none;display:flex;align-items:center;justify-content:center;font-size:24px;line-height:1;color:#fff;padding:0;animation:thgame-pulse 2.4s infinite;';
    fabBtn.textContent = '🕹️';
