    if (pickBtn && fileInput) {
      pickBtn.addEventListener('click', () => fileInput.click());
      fileInput.addEventListener('change', () => {
        const f = fileInput.files && fileInput.files[0];
        if (!f) return;
        showToast('🖼️ 正在处理照片…');
        ccReadImageFile(f, (dataUrl) => {
          if (dataUrl) { pendingAvatar = dataUrl; updatePreview(); showToast('✅ 照片已就绪，记得点保存'); }
          else showToast('⚠️ 照片读取失败，请换一张试试');
        });
        fileInput.value = '';
      });
    }
    const clearBtn = sheet.querySelector('#cc-clear-photo');
    if (clearBtn) {
      clearBtn.addEventListener('click', () => { pendingAvatar = ''; updatePreview(); });
    }
    // 手动清空名字 = 想要新建：退出编辑态，避免把新角色写回被编辑的那条
    const nameField = sheet.querySelector('#cc-name');
    if (nameField) nameField.addEventListener('input', () => { if (!nameField.value.trim()) editingIdx = -1; });
    if (nameField) nameField.addEventListener('input', refreshRelList);
    const relAddBtn = sheet.querySelector('#cc-rel-add');
    if (relAddBtn) relAddBtn.addEventListener('click', () => {
      const n = (sheet.querySelector('#cc-name')?.value || '').trim();
      if (!n) { showToast('⚠️ 请先给角色起个名字，再添加人物关系'); return; }
      openRelationEditor(n, refreshRelList);
    });
    const saveBtn = sheet.querySelector('#cc-save');
    if (saveBtn) {
      saveBtn.addEventListener('click', () => {
        const name = (sheet.querySelector('#cc-name')?.value || '').trim();
        if (!name) { showToast('⚠️ 请先给角色起个名字'); return; }
        const prof = {
          name,
          gender: sheet.querySelector('#cc-gender')?.value || '',
          age: (sheet.querySelector('#cc-age')?.value || '').trim(),
          identity: (sheet.querySelector('#cc-identity')?.value || '').trim(),
          personality: (sheet.querySelector('#cc-personality')?.value || '').trim(),
          languageStyle: (sheet.querySelector('#cc-style')?.value || '').trim(),
          attitude: (sheet.querySelector('#cc-attitude')?.value || '').trim(),
          brief: (sheet.querySelector('#cc-brief')?.value || '').trim(),
          avatar: pendingAvatar || ''
        };
        const arr = loadCustomCharacters();
        // 编辑态按索引精确更新（支持改名）；非编辑态才按"完全同名"覆盖；否则新建。
        // 旧代码用 isNameMatch 双向子串反查：改名会变成重复条目、新建相近名字会静默覆盖旧角色
        const exactIdx = arr.findIndex(c => c && c.name === name);
        if (editingIdx >= 0 && editingIdx < arr.length) arr[editingIdx] = prof;
        else if (exactIdx >= 0) arr[exactIdx] = prof;
        else arr.push(prof);
        saveCustomCharacters(arr);
        showToast('✅ 已保存自定义角色「' + name + '」，现在可以邀请 TA 入座啦');
        renderCustomCharacterManager();
      });
    }
    sheet.querySelectorAll('.cc-edit').forEach(btn => {
      btn.addEventListener('click', () => {
        const arr = loadCustomCharacters();
        const idx = parseInt(btn.dataset.idx, 10);
        const c = arr[idx];
        if (c) {
          editingIdx = idx; // 记录编辑目标，保存时精确定位（改名不再产生重复条目）
          fillForm(c);
          const t = sheet.querySelector('#cc-form-title');
          if (t) t.textContent = '✏️ 编辑角色：' + c.name;
        }
      });
    });
    sheet.querySelectorAll('.cc-del').forEach(btn => {
      btn.addEventListener('click', () => {
        const arr = loadCustomCharacters();
        const idx = parseInt(btn.dataset.idx, 10);
        const c = arr[idx];
        if (!c) return;
        arr.splice(idx, 1);
        saveCustomCharacters(arr);
        showToast('🗑️ 已删除自定义角色「' + c.name + '」');
        renderCustomCharacterManager();
      });
    });
  }

