  const MS_PRESETS = { fast: { rows: 9, cols: 9, mines: 10, name: '快速 · 9×9 / 10 雷' }, normal: { rows: 16, cols: 16, mines: 40, name: '标准 · 16×16 / 40 雷' }, strong: { rows: 16, cols: 30, mines: 99, name: '强力 · 16×30 / 99 雷' } };
  let msGame = null;
  let msTimer = null;
  let msFlagMode = false;

  function loadMsConfig() {
    const def = { aiLevel: 'fast', custom: null };
    try {
      const raw = localStorage.getItem(MS_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (p && (p.aiLevel === 'fast' || p.aiLevel === 'normal' || p.aiLevel === 'strong')) def.aiLevel = p.aiLevel;
        if (p && p.custom && Number(p.custom.rows) > 0 && Number(p.custom.cols) > 0) def.custom = { rows: Math.min(30, Number(p.custom.rows)), cols: Math.min(30, Number(p.custom.cols)), mines: Math.max(1, Number(p.custom.mines) || 10) };
      }
    } catch (e) { /* ignore */ }
    return def;
  }
  function saveMsConfig(c) { try { localStorage.setItem(MS_CONFIG_KEY, JSON.stringify(c || {})); } catch (e) { /* ignore */ } }
  // 提示能力分档（走统一难度中枢，缺项时用内置兜底）：-1 = 不限次，0 = 不提供
  function msHintLimit() {
    const cfg = loadMsConfig();
    const D = getDifficulty('minesweeper', cfg.aiLevel);
    const n = Number(D.hintLimit);
    return Number.isFinite(n) ? n : (cfg.aiLevel === 'fast' ? -1 : cfg.aiLevel === 'strong' ? 0 : 3);
  }

  function msNewGame() {
    const cfg = loadMsConfig();
    const preset = MS_PRESETS[cfg.aiLevel] || MS_PRESETS.fast;
    const p = cfg.custom || preset;
    const rows = p.rows, cols = p.cols, mines = Math.min(p.mines, rows * cols - 9);
    msGame = {
      session: Date.now() + '_' + Math.floor(Math.random() * 100000),
      rows: rows, cols: cols, mines: mines, level: cfg.aiLevel, presetName: cfg.custom ? ('自定义 · ' + rows + '×' + cols + ' / ' + mines + ' 雷') : preset.name,
      cells: Array.from({ length: rows }, () => Array.from({ length: cols }, () => ({ mine: false, open: false, flag: false, num: 0 }))),
      started: false, over: false, win: false, flags: 0, opened: 0, hintUsed: 0, elapsed: 0, startAt: 0
    };
    if (msTimer) { clearInterval(msTimer); msTimer = null; }
    msFlagMode = false;
    renderMinesweeper();
    showToast('💣 ' + msGame.presetName + '：第一次点击必定安全');
  }
  function msPlaceMines(sr, sc) {
    const g = msGame; let placed = 0;
    while (placed < g.mines) {
      const r = Math.floor(Math.random() * g.rows), c = Math.floor(Math.random() * g.cols);
      if (g.cells[r][c].mine) continue;
      if (Math.abs(r - sr) <= 1 && Math.abs(c - sc) <= 1) continue; // 首点 3×3 保证安全
      g.cells[r][c].mine = true; placed++;
    }
    for (let r = 0; r < g.rows; r++) for (let c = 0; c < g.cols; c++) {
      if (g.cells[r][c].mine) continue;
      let n = 0;
      for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
        const nr = r + dr, nc = c + dc;
        if (nr < 0 || nr >= g.rows || nc < 0 || nc >= g.cols) continue;
        if (g.cells[nr][nc].mine) n++;
      }
      g.cells[r][c].num = n;
    }
  }
  function msReveal(r, c) {
    const g = msGame;
    if (r < 0 || r >= g.rows || c < 0 || c >= g.cols) return;
    const cell = g.cells[r][c];
    if (cell.open || cell.flag) return;
    cell.open = true; g.opened++;
    if (cell.num === 0 && !cell.mine) {
      for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) if (dr || dc) msReveal(r + dr, c + dc);
    }
  }
  function msOpenCell(r, c) {
    const g = msGame;
    if (!g || g.over) return;
    const cell = g.cells[r][c];
    if (cell.flag || cell.open) return;
    if (!g.started) { g.started = true; g.startAt = Date.now(); msPlaceMines(r, c); msStartTimer(); }
    if (cell.mine) {
      cell.open = true;
      g.over = true; g.win = false;
      g.cells.forEach(row => row.forEach(x => { if (x.mine) x.open = true; }));
      msStopTimer();
      saveMsGame();
      renderMinesweeper();
      msRecord(false);
      showToast('💥 踩到雷了！');
      return;
    }
    msReveal(r, c);
    saveMsGame();
    if (g.opened >= g.rows * g.cols - g.mines) {
      g.over = true; g.win = true;
      g.cells.forEach(row => row.forEach(x => { if (x.mine) x.flag = true; }));
      g.flags = g.mines;
      msStopTimer();
      saveMsGame();
      renderMinesweeper();
      msRecord(true);
      showToast('🎉 全部排除，扫雷成功！用时 ' + g.elapsed + ' 秒');
      return;
    }
    renderMinesweeper();
  }
  function msToggleFlag(r, c) {
    const g = msGame;
    if (!g || g.over) return;
    const cell = g.cells[r][c];
    if (cell.open) return;
    cell.flag = !cell.flag;
    g.flags += cell.flag ? 1 : -1;
    saveMsGame();
    renderMinesweeper();
  }
  // 提示：快速档不限次、标准档 3 次、强力档不提供（改为"逻辑概率标记"）
  function msHint() {
    const g = msGame;
    if (!g || g.over) return;
    const limit = msHintLimit();
    if (limit === 0) {
      // 强力档：用约束推理标出"必是雷 / 必安全"的格子（100%/0% 概率）
      let marks = 0;
      for (let r = 0; r < g.rows; r++) for (let c = 0; c < g.cols; c++) {
        const cell = g.cells[r][c];
        if (cell.open || cell.flag) continue;
        let unknown = 0, minesAround = 0;
        for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
          const nr = r + dr, nc = c + dc;
          if (nr < 0 || nr >= g.rows || nc < 0 || nc >= g.cols) continue;
          const x = g.cells[nr][nc];
          if (x.open && x.num > 0) { minesAround = x.num; }
          if (!x.open && !x.flag) unknown++;
        }
        // 简化约束：若相邻已开数字格中"未开邻居数 == 其数字"，则本格必为雷
        let certainMine = false;
        for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
          const nr = r + dr, nc = c + dc;
          if (nr < 0 || nr >= g.rows || nc < 0 || nc >= g.cols) continue;
          const x = g.cells[nr][nc];
          if (!x.open || x.num === 0) continue;
          let un = 0, fl = 0;
          for (let ar = -1; ar <= 1; ar++) for (let ac = -1; ac <= 1; ac++) {
            const ar2 = nr + ar, ac2 = nc + ac;
            if (ar2 < 0 || ar2 >= g.rows || ac2 < 0 || ac2 >= g.cols) continue;
            const y = g.cells[ar2][ac2];
            if (!y.open && !y.flag) un++;
            if (y.flag) fl++;
          }
          if (un === x.num - fl) certainMine = true;
        }
        if (certainMine) { cell.flag = true; g.flags++; marks++; }
      }
      saveMsGame();
      renderMinesweeper();
      showToast(marks ? '🧠 逻辑推理：已标出 ' + marks + ' 个必定是雷的格子（0 概率格请自行判断）' : '🧠 当前局面没有 100% 确定的雷，请自行推算概率');
      return;
    }
    if (limit > 0 && g.hintUsed >= limit) { showToast('提示次数已用完（' + limit + ' 次）'); return; }
    for (let r = 0; r < g.rows; r++) for (let c = 0; c < g.cols; c++) {
      const cell = g.cells[r][c];
      if (!cell.open && !cell.flag && !cell.mine) {
        g.hintUsed++;
        showToast('💡 提示：' + (r + 1) + ' 行 ' + (c + 1) + ' 列是安全的' + (limit < 0 ? '（快速档不限次）' : '（剩余 ' + Math.max(0, limit - g.hintUsed) + ' 次）'));
        msOpenCell(r, c);
        return;
      }
    }
  }
  function msStartTimer() {
    if (msTimer) clearInterval(msTimer);
    msTimer = setInterval(() => { if (msGame && msGame.started && !msGame.over) { msGame.elapsed = Math.floor((Date.now() - msGame.startAt) / 1000); const el = sheet?.querySelector('#ms-timer'); if (el) el.textContent = msGame.elapsed + 's'; } }, 500);
  }
  function msStopTimer() { if (msTimer) { clearInterval(msTimer); msTimer = null; } }
  function msRecord(won) {
    if (!msGame || msGame.recorded) return;
