      onGameFinished({
        gameType: 'minesweeper',
        userWon: !!won,
        result: (won ? '扫雷成功：' : '踩雷失败：') + msGame.presetName,
        detail: '已开 ' + msGame.opened + '/' + (msGame.rows * msGame.cols - msGame.mines) + ' 格 · 用时 ' + msGame.elapsed + ' 秒 · 旗子 ' + msGame.flags + '/' + msGame.mines + (msGame.hintUsed ? ' · 提示 ' + msGame.hintUsed + ' 次' : ''),
        players: [{ name: '我', isUser: true, avatar: getMainCharAvatar() }]
      });
    } catch (e) { /* ignore */ }
  }
  function saveMsGame() {
    try {
      if (!msGame || msGame.over) { localStorage.removeItem(MS_SAVE_KEY); return; }
      localStorage.setItem(MS_SAVE_KEY, JSON.stringify(msGame));
    } catch (e) { /* ignore */ }
  }
  function hasSavedMsGame() { try { const raw = localStorage.getItem(MS_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && d.cells && !d.over); } catch (e) { return false; } }
  function resumeMsGame() {
    try {
      const raw = localStorage.getItem(MS_SAVE_KEY);
      if (!raw) { msNewGame(); return; }
      msGame = JSON.parse(raw);
      msGame.recorded = false;
      if (msGame.started && !msGame.over) { msGame.startAt = Date.now() - (msGame.elapsed || 0) * 1000; msStartTimer(); }
      renderMinesweeper();
