        grid += `<div data-ms-cell="${r},${c}" style="width:${cellSize}px;height:${cellSize}px;display:flex;align-items:center;justify-content:center;font-size:${fs}px;font-weight:700;color:${color || 'var(--ubp-text)'};background:${bg};border:1px solid var(--ubp-line);box-sizing:border-box;cursor:${cell.open || g.over ? 'default' : 'pointer'};user-select:none;border-radius:3px;">${txt}</div>`;
