          <span style="font-size:11.5px;color:var(--ubp-text-2);">💣 <b>${Math.max(0, g.mines - g.flags)}</b></span>
          <span id="ms-timer" style="font-size:11.5px;color:var(--ubp-text-2);">${g.elapsed}s</span>
          <button data-ubp-act="ms-difficulty" class="ubp-btn" style="padding:3px 8px;font-size:11.5px;">${g.level === 'fast' ? '快速' : g.level === 'normal' ? '标准' : '强力'}</button>
          <button data-ubp-act="ms-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏中心（不保存进度）">✕</button>
        </div>
      </div>
      <div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:6px;flex:none;line-height:1.5;">${g.presetName} · 左键${msFlagMode ? '插旗（插旗模式）' : '翻开'} / 右键（长按）插旗 · 提示：${hintLimit === 0 ? '无（强力档提供逻辑概率标记）' : hintLimit < 0 ? '不限次' : '剩 ' + Math.max(0, hintLimit - g.hintUsed) + ' 次'}${g.custom ? ' · 自定义' : ''}</div>
      <div style="flex:1;overflow:auto;display:flex;padding:4px 0;">
        <div id="ms-grid" style="margin:auto;border-radius:6px;overflow:hidden;background:#111827;padding:2px;">${grid}</div>
      </div>
      <div style="display:flex;gap:8px;margin-top:6px;flex:none;">
        <button data-ubp-act="ms-flag-mode" class="ubp-btn" style="flex:1;padding:7px;font-size:12.5px;${msFlagMode ? 'background:#10B981;color:#fff;border:none;font-weight:700;' : 'background:var(--ubp-card-2);border:1px solid var(--ubp-line);'}">🚩 ${msFlagMode ? '插旗中' : '插旗'}</button>
        <button data-ubp-act="ms-hint" class="ubp-btn" style="flex:1;padding:7px;font-size:12.5px;background:var(--ubp-card-2);border:1px solid var(--ubp-line);">${hintLimit === 0 ? '🧠 逻辑概率标记' : '💡 提示'}</button>
        <button data-ubp-act="ms-restart" class="ubp-btn" style="flex:1;padding:7px;font-size:12.5px;background:var(--ubp-card-2);border:1px solid var(--ubp-line);">🔄 重开</button>
        <button data-ubp-act="ms-settings" class="ubp-btn" style="flex:1;padding:7px;font-size:12.5px;background:#10B981;color:#fff;border:none;">⚙️ 难度 / 自定义</button>
      </div>
      ${g.over ? `<div style="margin-top:8px;padding:8px 10px;border-radius:8px;flex:none;text-align:center;font-size:13px;font-weight:600;background:${g.win ? 'rgba(16,185,129,0.15)' : 'rgba(239,68,68,0.15)'};color:${g.win ? '#10B981' : '#EF4444'};">${g.win ? '🎉 扫雷成功！用时 ' + g.elapsed + ' 秒' : '💥 踩雷失败'}　<button data-ubp-act="ms-restart" class="ubp-btn" style="padding:3px 10px;font-size:12px;margin-left:6px;">再来一局</button></div>` : ''}
    `;
    // 交互：左键翻开 / 右键（长按）插旗
    sheet.querySelectorAll('[data-ms-cell]').forEach(el => {
