  // ========== 俄罗斯方块 · AI 双人对战（左侧 AI / 右侧 我 · 垃圾行攻防） ==========
  const TETRIS_BATTLE_LEVEL_KEY = 'werewolf_extension_tetris_battle_level';
  const TB_GARBAGE_KEY = 'G';
  const TB_GARBAGE_COLOR = '#94A3B8';
  const TB_ATTACK_TABLE = { 1: 0, 2: 1, 3: 2, 4: 4 };
  // 三档 AI：简单=贪心（只看当前块）；普通=当前+下一块；困难=三块多步预判+进攻偏好
  const TB_LEVELS = {
    fast:   { key: 'fast',   name: '简单', gravityMs: 1000, aiStepMs: 340, blunder: 0.28, noise: 1.2, depth: 1, thinkMs: 30 },
    normal: { key: 'normal', name: '普通', gravityMs: 850,  aiStepMs: 210, blunder: 0.06, noise: 0.5, depth: 2, thinkMs: 60 },
    strong: { key: 'strong', name: '困难', gravityMs: 700,  aiStepMs: 110, blunder: 0.00, noise: 0.0, depth: 3, thinkMs: 90 }
  };
  let tetrisBattle = null;
  let tbPieceSeq = 0;
  let tbBattleTimer = null;

  function tbLevel() { try { const v = localStorage.getItem(TETRIS_BATTLE_LEVEL_KEY); return TB_LEVELS[v] ? v : 'normal'; } catch (e) { return 'normal'; } }
  function tbSetLevel(v) { try { localStorage.setItem(TETRIS_BATTLE_LEVEL_KEY, v); } catch (e) { /* ignore */ } }
  // 对战对手显示名：邀请角色后显示角色名（与石头剪刀布 / 井字棋一致），未邀请则显示 AI
  function tbOppName() { const t = tetrisBattle; return (t && t.opponent && t.opponent.name) ? t.opponent.name : 'AI'; }

  function tbNewSide(isAI) {
    return { isAI: !!isAI, board: tetrisEmptyBoard(), piece: null, queue: [], score: 0, lines: 0, pending: 0, milestone: 1000, boardVersion: 0, target: null, over: false };
  }
  // 7-bag 随机：每 7 个方块保证各出现一次，双方公平
  function tbFillQueue(side) {
    while (side.queue.length < 7) {
      const bag = TETRIS_KEYS.slice();
      for (let i = bag.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp; }
      for (const kk of bag) side.queue.push(kk);
    }
  }
  function tbCollideBoard(board, key, rot, px, py) {
    const shape = tetrisShapeOf(key, rot);
    for (let r = 0; r < shape.length; r++) {
      for (let c = 0; c < shape[r].length; c++) {
        if (!shape[r][c]) continue;
        const x = px + c, y = py + r;
        if (x < 0 || x >= TETRIS_COLS || y >= TETRIS_ROWS) return true;
        if (y >= 0 && board[y][x]) return true;
      }
    }
    return false;
  }
  function tbMovePiece(side, dx) {
    const p = side.piece;
    if (!p) return false;
    if (!tbCollideBoard(side.board, p.key, p.rot, p.x + dx, p.y)) { p.x += dx; return true; }
    return false;
  }
  function tbRotatePiece(side) {
    const p = side.piece;
    if (!p) return false;
    const nr = p.rot + 1;
    if (!tbCollideBoard(side.board, p.key, nr, p.x, p.y)) { p.rot = nr; return true; }
    if (!tbCollideBoard(side.board, p.key, nr, p.x - 1, p.y)) { p.rot = nr; p.x -= 1; return true; }
    if (!tbCollideBoard(side.board, p.key, nr, p.x + 1, p.y)) { p.rot = nr; p.x += 1; return true; }
    return false;
  }
  function tbSpawnPiece(side, other) {
    const t = tetrisBattle;
    if (!t || t.over) return;
    tbFillQueue(side);
    const key = side.queue.shift();
    tbFillQueue(side);
    const shape = tetrisShapeOf(key, 0);
    const px = Math.floor((TETRIS_COLS - shape[0].length) / 2);
    side.piece = { key: key, rot: 0, x: px, y: 0, id: ++tbPieceSeq };
    side.target = null;
    if (tbCollideBoard(side.board, key, 0, px, 0)) {
      side.piece = null;
      side.over = true;
      tbEndBattle(other, side.isAI ? tbOppName() + ' 的棋盘先堆到了顶部' : '你的棋盘先堆到了顶部');
    }
  }
  // 垃圾行：从底部升起一行，最右侧留一个空位；顶行被挤掉且非空即判负
  function tbPushGarbage(side, n) {
    const b = side.board;
    let overflow = false;
    for (let i = 0; i < n; i++) {
      if (b[0].some(c => !!c)) overflow = true;
      b.shift();
      const row = new Array(TETRIS_COLS).fill(TB_GARBAGE_KEY);
      row[TETRIS_COLS - 1] = '';
      b.push(row);
    }
    if (n > 0) side.boardVersion++;
    return !overflow;
  }
  // 删除自己最底下的一行垃圾行（上方方块顺势下落一格）
  function tbCleanseGarbage(side) {
    const b = side.board;
    for (let r = TETRIS_ROWS - 1; r >= 0; r--) {
      if (b[r].some(c => c === TB_GARBAGE_KEY)) {
        b.splice(r, 1);
        b.unshift(new Array(TETRIS_COLS).fill(''));
        side.boardVersion++;
        return true;
      }
    }
    return false;
  }
  function tbStepDown(side, other) {
    const t = tetrisBattle;
    if (!t || t.over) return false;
    const p = side.piece;
    if (!p) return false;
    if (!tbCollideBoard(side.board, p.key, p.rot, p.x, p.y + 1)) { p.y += 1; return true; }
    tbLockAndResolve(side, other);
    return false;
  }
  function tbLockAndResolve(side, other) {
    const t = tetrisBattle;
    if (!t || t.over || !side.piece) return;
    const p = side.piece;
    const shape = tetrisShapeOf(p.key, p.rot);
    for (let r = 0; r < shape.length; r++) {
      for (let c = 0; c < shape[r].length; c++) {
        if (!shape[r][c]) continue;
        const y = p.y + r, x = p.x + c;
        if (y >= 0 && y < TETRIS_ROWS && x >= 0 && x < TETRIS_COLS) side.board[y][x] = p.key;
      }
    }
    side.piece = null;
    side.target = null;
    // 1) 先把积压的垃圾行顶上来（顶到顶部即判负）
    if (side.pending > 0) {
      const ok = tbPushGarbage(side, side.pending);
      side.pending = 0;
      if (!ok) {
        side.over = true;
        tbEndBattle(other, side.isAI ? '垃圾行把 ' + tbOppName() + ' 的棋盘顶爆了' : '垃圾行把你的棋盘顶爆了');
        return;
      }
    }
    // 2) 消行
    let lines = 0;
    for (let r = TETRIS_ROWS - 1; r >= 0; r--) {
      if (side.board[r].every(c => !!c)) { side.board.splice(r, 1); side.board.unshift(new Array(TETRIS_COLS).fill('')); lines++; r++; }
    }
    // 3) 计分 + 按消行数给对手发垃圾行（消 1 行不发）
    if (lines > 0) {
      const table = { 1: 100, 2: 300, 3: 500, 4: 800 };
      side.lines += lines;
      side.score += (table[lines] || 800);
      const atk = TB_ATTACK_TABLE[lines] || 0;
      if (atk > 0) other.pending += atk;
    }
    // 4) 每累计 1000 分：给对手 +1 垃圾行，并删除自己一行垃圾行
    while (side.score >= side.milestone) {
      side.milestone += 1000;
      other.pending += 1;
      tbCleanseGarbage(side);
    }
    side.boardVersion++;
    // 5) 生成下一块
    tbSpawnPiece(side, other);
  }
  function tbEndBattle(winner, reason) {
    const t = tetrisBattle;
    if (!t || t.over) return;
    t.over = true;
    t.winner = winner || null;
    t.reason = reason || '';
    tbStopBattleTimer();
    tbRenderBattle();
  }

  // ---------- AI 评估（El-Tetris 权重 + 分档加成） ----------
  function tbHeights(board) {
    const hs = new Array(TETRIS_COLS).fill(0);
    for (let c = 0; c < TETRIS_COLS; c++) {
      for (let r = 0; r < TETRIS_ROWS; r++) {
        if (board[r][c]) { hs[c] = TETRIS_ROWS - r; break; }
      }
    }
    return hs;
  }
  function tbEvalBoard(board, linesCleared, landingY, lv) {
    const hs = tbHeights(board);
    let agg = 0, maxH = 0, holes = 0, rowTrans = 0, colTrans = 0, wells = 0;
    for (let c = 0; c < TETRIS_COLS; c++) {
      agg += hs[c];
      if (hs[c] > maxH) maxH = hs[c];
      let seen = false;
      for (let r = 0; r < TETRIS_ROWS; r++) {
        if (board[r][c]) seen = true;
        else if (seen) holes++;
      }
    }
    let bump = 0;
    for (let c = 0; c < TETRIS_COLS - 1; c++) bump += Math.abs(hs[c] - hs[c + 1]);
    for (let c = 0; c < TETRIS_COLS; c++) {
      const left = c === 0 ? TETRIS_ROWS : hs[c - 1];
      const right = c === TETRIS_COLS - 1 ? TETRIS_ROWS : hs[c + 1];
      const d = Math.min(left, right) - hs[c];
      if (d > 0) wells += d * (d + 1) / 2;
    }
    for (let r = 0; r < TETRIS_ROWS; r++) {
      let prev = true;
      for (let c = 0; c < TETRIS_COLS; c++) { const f = !!board[r][c]; if (f !== prev) { rowTrans++; prev = f; } }
      if (!prev) rowTrans++;
    }
    for (let c = 0; c < TETRIS_COLS; c++) {
      let prev = true;
      for (let r = 0; r < TETRIS_ROWS; r++) { const f = !!board[r][c]; if (f !== prev) { colTrans++; prev = f; } }
      if (!prev) colTrans++;
    }
    const landing = TETRIS_ROWS - (landingY || 0);
    let sc = -4.5 * landing + 3.42 * linesCleared - 3.22 * rowTrans - 9.35 * colTrans - 7.9 * holes - 3.39 * wells - 0.05 * agg - 0.4 * bump;
    if (lv && lv.depth >= 3) {
      sc += linesCleared * 1.6;
      if (linesCleared >= 4) sc += 6;
      if (maxH > 15) sc -= (maxH - 15) * 4;
    } else if (lv && lv.depth === 2) {
      if (linesCleared >= 4) sc += 3;
      if (maxH > 16) sc -= (maxH - 16) * 3;
    }
    return sc;
  }
  // 枚举某方块在棋盘上的所有可落位置（旋转去重）
  function tbEnumerate(board, key) {
    const shapes = TETRIS_SHAPES[key] || TETRIS_SHAPES.T;
    const uniqRots = [];
    const sigSet = new Set();
    for (let rot = 0; rot < shapes.length; rot++) {
      const sig = shapes[rot].map(row => row.join('')).join('/');
      if (!sigSet.has(sig)) { sigSet.add(sig); uniqRots.push(rot); }
    }
    const out = [];
    for (const rot of uniqRots) {
      const shape = shapes[rot];
      for (let x = -shape[0].length + 1; x < TETRIS_COLS; x++) {
        let ok = true;
        for (let r = 0; r < shape.length && ok; r++) {
          for (let c = 0; c < shape[r].length; c++) {
            if (!shape[r][c]) continue;
            const bx = x + c;
            if (bx < 0 || bx >= TETRIS_COLS) { ok = false; break; }
          }
        }
        if (!ok) continue;
        if (tbCollideBoard(board, key, rot, x, 0)) continue;
        let y = 0;
        while (!tbCollideBoard(board, key, rot, x, y + 1)) y++;
        out.push({ rot: rot, x: x, y: y });
      }
    }
    return out;
  }
  function tbLockSim(board, key, p) {
    const b = board.map(r => r.slice());
    const shape = tetrisShapeOf(key, p.rot);
    for (let r = 0; r < shape.length; r++) {
      for (let c = 0; c < shape[r].length; c++) {
        if (!shape[r][c]) continue;
        const y = p.y + r, x = p.x + c;
        if (y >= 0 && y < TETRIS_ROWS && x >= 0 && x < TETRIS_COLS) b[y][x] = key;
      }
    }
    let lines = 0;
    for (let r = TETRIS_ROWS - 1; r >= 0; r--) {
      if (b[r].every(c => !!c)) { b.splice(r, 1); b.unshift(new Array(TETRIS_COLS).fill('')); lines++; r++; }
    }
    return { board: b, lines: lines };
  }
  function tbRankPlacements(board, key, lv) {
    const out = [];
    for (const p of tbEnumerate(board, key)) {
      const sim = tbLockSim(board, key, p);
      out.push({ p: p, board: sim.board, sc: tbEvalBoard(sim.board, sim.lines, p.y, lv) });
    }
    out.sort((a, b) => b.sc - a.sc);
    return out;
  }
  function tbPickWithNoise(ranked, lv) {
    const top = ranked.slice(0, Math.min(6, ranked.length));
    if (lv.blunder > 0 && Math.random() < lv.blunder && top.length > 1) {
      return top[1 + Math.floor(Math.random() * (top.length - 1))].p;
    }
    if (lv.noise > 0) {
      const noisy = top.map(x => ({ p: x.p, sc: x.sc + (Math.random() - 0.5) * lv.noise * 5 }));
      noisy.sort((a, b) => b.sc - a.sc);
      return noisy[0].p;
    }
    return top[0].p;
  }
  function tbChoosePlacement(side, lv, deadline) {
    if (!side.piece) return null;
    const key = side.piece.key;
    const ranked = tbRankPlacements(side.board, key, lv);
    if (!ranked.length) return null;
    if (lv.depth <= 1) return tbPickWithNoise(ranked, lv);
    const nextKey = side.queue[0];
    const results = [];
    for (const r1 of ranked) {
      let sc = r1.sc;
      let board2 = r1.board;
      if (nextKey) {
        const ranked2 = tbRankPlacements(r1.board, nextKey, lv);
        if (ranked2.length) {
          sc += (lv.depth >= 3 ? 0.85 : 0.9) * ranked2[0].sc;
          board2 = ranked2[0].board;
        }
      }
      results.push({ p: r1.p, sc: sc, board2: board2 });
      if (lv.depth >= 3 && results.length >= 4 && Date.now() > deadline) break;
    }
    results.sort((a, b) => b.sc - a.sc);
    if (lv.depth >= 3 && side.queue[1]) {
      let best = null;
      for (const r2 of results.slice(0, 4)) {
        let sc = r2.sc;
        if (r2.board2) {
          const ranked3 = tbRankPlacements(r2.board2, side.queue[1], lv);
          if (ranked3.length) sc += 0.7 * ranked3[0].sc;
        }
        if (!best || sc > best.sc) best = { p: r2.p, sc: sc };
        if (Date.now() > deadline) break;
      }
      if (best) return best.p;
    }
    if (lv.blunder > 0 && Math.random() < lv.blunder && results.length > 1) return results[1].p;
    return results[0].p;
  }
  function tbAIStep(side, other) {
    const t = tetrisBattle;
    if (!t || t.over || side.over) return;
    const p = side.piece;
    if (!p) return;
    const lv = TB_LEVELS[t.level] || TB_LEVELS.normal;
    if (!side.target || side.target.pieceId !== p.id || side.target.version !== side.boardVersion) {
      side.target = { pieceId: p.id, version: side.boardVersion, p: tbChoosePlacement(side, lv, Date.now() + (lv.thinkMs || 60)), wiggle: 0 };
    }
    const goal = side.target.p;
    if (!goal) { tbStepDown(side, other); return; }
    if (p.rot !== goal.rot) {
      if (tbRotatePiece(side)) { side.target.wiggle = 0; return; }
      side.target.wiggle = (side.target.wiggle || 0) + 1;
      if (side.target.wiggle >= 3) { goal.rot = p.rot; side.target.wiggle = 0; }
      return;
    }
    if (p.x !== goal.x) {
      if (tbMovePiece(side, p.x < goal.x ? 1 : -1)) return;
      goal.x = p.x;
      return;
    }
    let moved = false;
    for (let i = 0; i < 3; i++) {
      if (tbCollideBoard(side.board, p.key, p.rot, p.x, p.y + 1)) break;
      p.y++; moved = true;
    }
    if (!moved) tbLockAndResolve(side, other);
  }

  // ---------- 对战渲染 ----------
  function tbCellSize() {
    let cell = 14;
    try {
      const vh = window.innerHeight || 640;
      const vw = window.innerWidth || 360;
      const byW = Math.floor((Math.min(vw, 560) - 60) / (TETRIS_COLS * 2));
      const byH = Math.floor((vh - 330) / TETRIS_ROWS);
      cell = Math.max(9, Math.min(20, Math.min(byW, byH)));
    } catch (e) { /* ignore */ }
    return cell;
  }
  function tbBoardHTML(side, cell) {
    const display = side.board.map(r => r.slice());
    if (side.piece && tetrisBattle && !tetrisBattle.over) {
      const shape = tetrisShapeOf(side.piece.key, side.piece.rot);
      for (let r = 0; r < shape.length; r++) {
        for (let c = 0; c < shape[r].length; c++) {
          if (!shape[r][c]) continue;
          const y = side.piece.y + r, x = side.piece.x + c;
          if (y >= 0 && y < TETRIS_ROWS && x >= 0 && x < TETRIS_COLS) display[y][x] = side.piece.key;
        }
      }
    }
    let html = '';
    for (let r = 0; r < TETRIS_ROWS; r++) {
      for (let c = 0; c < TETRIS_COLS; c++) {
        const k = display[r][c];
        const color = k ? (k === TB_GARBAGE_KEY ? TB_GARBAGE_COLOR : (TETRIS_COLORS[k] || '#fff')) : 'rgba(255,255,255,0.045)';
        html += '<div style="width:' + cell + 'px;height:' + cell + 'px;border-radius:2px;background:' + color + ';border:1px solid ' + (k ? 'rgba(255,255,255,0.22)' : 'rgba(255,255,255,0.05)') + ';box-sizing:border-box;"></div>';
      }
    }
    return html;
  }
  function tbNextHTML(side) {
    const key = side.queue && side.queue.length ? side.queue[0] : '';
    const shape = key ? tetrisShapeOf(key, 0) : [[1]];
    let mini = '';
    for (let r = 0; r < 2; r++) {
      for (let c = 0; c < 4; c++) {
        const on = !!(shape[r] && shape[r][c]);
        mini += '<div style="width:8px;height:8px;border-radius:2px;background:' + (on ? (TETRIS_COLORS[key] || '#fff') : 'transparent') + ';"></div>';
      }
    }
    return mini;
  }
  function tbStateHash() {
    const t = tetrisBattle;
    if (!t) return '';
    const s = (x) => {
      const p = x.piece;
      return [p ? p.key + p.rot + p.x + ',' + p.y + ',' + p.id : '-', x.score, x.lines, x.pending, x.boardVersion, x.queue.length ? x.queue[0] : ''].join('|');
    };
    return s(t.sides.ai) + '#' + s(t.sides.user) + (t.over ? '#O' : '');
  }
  function renderTetrisBattleUI() {
