    if (!t) { renderAIBattleLobby(); return; }
    const levelBtn = (key, label) => `<button data-ubp-act="tb-level" data-level="${key}" class="ubp-btn" style="padding:2px 7px;font-size:10.5px;${t.level === key ? 'background:#8B5CF6;border:none;color:#fff;font-weight:600;' : ''}">${label}</button>`;
