            <button data-ubp-act="tb-back" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);flex:none;" title="返回俄罗斯方块单机界面">←</button>
            <span style="font-size:14px;font-weight:700;color:var(--ubp-text);white-space:nowrap;">🧱 小游戏对战</span>
          </div>
          <div style="display:flex;gap:4px;align-items:center;flex:none;">
            <button data-ubp-act="tb-invite" class="ubp-btn" style="padding:2px 7px;font-size:10.5px;" title="邀请一位角色作为对手，显示其头像与名字">👥 邀请</button>
            ${levelBtn('fast', '简单')}${levelBtn('normal', '普通')}${levelBtn('strong', '困难')}
            <button data-ubp-act="tb-exit" class="ubp-btn" style="padding:3px 8px;font-size:11px;background:#EF4444;color:#fff;border:none;" title="退出对战并返回小游戏对战大厅">🚪</button>
