        <div style="flex:1;min-height:0;overflow:auto;display:flex;align-items:flex-start;justify-content:center;gap:8px;padding:2px 0;">
          ${sidePanel(t.sides.ai, aiLabelHTML, '#F87171')}
          ${sidePanel(t.sides.user, '😊 我', '#34D399')}
        </div>
        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:4px;max-width:250px;width:100%;margin:2px auto 0;flex:none;">
