          <button data-ubp-act="tb-down" class="ubp-btn" style="padding:5px 0;font-size:13px;background:var(--ubp-card-2);border:1px solid var(--ubp-line);" title="下落一格">↓</button>
          <button data-ubp-act="tb-right" class="ubp-btn" style="padding:5px 0;font-size:13px;background:var(--ubp-card-2);border:1px solid var(--ubp-line);" title="右移">→</button>
        </div>
        <div style="display:flex;gap:4px;max-width:250px;width:100%;margin:4px auto 2px;flex:none;">
          <button data-ubp-act="tb-hard" class="ubp-btn" style="flex:1;padding:5px 0;font-size:11.5px;background:#B45309;border:none;color:#fff;" title="直接落底">⤓ 硬降</button>
        </div>
        <div id="tb-overlay" style="position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,0.55);z-index:30;"></div>
      </div>
    `;
    tbRenderBattle();
  }
  function tbRenderBattle() {
    const t = tetrisBattle;
    if (!t) return;
    const cell = tbCellSize();
    const upd = (side, idp) => {
      const be = sheet && sheet.querySelector('#tb-' + idp + '-board');
      if (be) {
        be.style.gridTemplateColumns = 'repeat(' + TETRIS_COLS + ', ' + cell + 'px)';
        be.style.gridAutoRows = cell + 'px';
        be.innerHTML = tbBoardHTML(side, cell);
      }
      const ie = sheet && sheet.querySelector('#tb-' + idp + '-info');
      if (ie) ie.innerHTML = '得分 <b>' + side.score + '</b> · 消行 <b>' + side.lines + '</b>' + (side.pending ? ' · <b style="color:#EF4444;">垃圾 +' + side.pending + '</b>' : '');
      const ne = sheet && sheet.querySelector('#tb-' + idp + '-next');
      if (ne) ne.innerHTML = tbNextHTML(side);
    };
    upd(t.sides.ai, 'ai');
    upd(t.sides.user, 'user');
    const ov = sheet && sheet.querySelector('#tb-overlay');
    if (ov) {
      if (t.over) {
        const userWon = !!(t.winner && !t.winner.isAI);
        ov.style.display = 'flex';
        ov.innerHTML = '<div style="background:var(--ubp-card,#1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:18px 16px;text-align:center;max-width:260px;">' +
          '<div style="font-size:32px;margin-bottom:6px;">' + (userWon ? '🏆' : '💀') + '</div>' +
          '<div style="font-size:16px;font-weight:700;color:' + (userWon ? '#34D399' : '#F87171') + ';">' + (userWon ? '你赢了！' : '你输了') + '</div>' +
          '<div style="font-size:11px;color:var(--ubp-text-2);margin:6px 0 12px;line-height:1.5;">' + escapeHtml(t.reason || '') + '<br>得分 我 ' + t.sides.user.score + ' : ' + t.sides.ai.score + ' ' + escapeHtml(tbOppName()) + '</div>' +
          '<div style="display:flex;gap:6px;">' +
          '<button data-ubp-act="tb-again" class="ubp-btn primary" style="flex:1;padding:7px 0;font-size:12.5px;background:#8B5CF6;border:none;">🔄 再来一局</button>' +
          '<button data-ubp-act="tb-lobby" class="ubp-btn" style="flex:1;padding:7px 0;font-size:12.5px;">🏠 小游戏对战大厅</button>' +
