      const listHtml = contacts.map(c => {
        const isSelected = !chosenAI && c.name === chosenName;
        const av = c.avatar || getCharacterAvatarByName(c.name);
        return `
          <div data-tb-pick="${escapeAttr(c.name)}" style="display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:${isSelected ? 'rgba(139,92,246,0.15)' : 'var(--ubp-card-2, #26262a)'};border:1.5px solid ${isSelected ? '#8B5CF6' : 'var(--ubp-line)'};">
            <div style="width:40px;height:40px;border-radius:50%;background:#8B5CF6;overflow:hidden;flex-shrink:0;box-shadow:0 1px 4px rgba(0,0,0,0.2);">
              ${av ? `<img src="${escapeAttr(av)}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:15px;">${escapeHtml(c.name.slice(0, 1))}</span>`}
            </div>
            <div style="flex:1;min-width:0;">
              <div style="font-size:14px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(c.name)} ${isSelected ? '👑 (已选对手)' : ''}</div>
              ${c.identity ? `<div style="font-size:11.5px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;">${escapeHtml(c.identity)}</div>` : ''}
            </div>
          </div>
        `;
      }).join('');

      ov.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex:none;">
          <span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">👥 邀请对战对手</span>
          <button data-tb-invite="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
        </div>
        <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">请选择 1 位角色作为俄罗斯方块对战的对手（显示其头像与名字；选「电脑 AI」则恢复默认）：</div>
        <div style="flex:1;overflow-y:auto;padding-right:2px;margin-bottom:8px;">
          ${aiRow}
          ${listHtml || '<div style="font-size:12px;color:var(--ubp-text-3);">通讯录暂无角色，请确保神数据库已添加角色。</div>'}
