  // ========== 对局记录查看界面 ==========
  function renderRecordView() {
    const store = loadGenericMatchHistory();
    const types = listKnownGameTypes(store);

    const refreshIcon = `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 1 1-2.64-6.36"/><path d="M21 3v6h-6"/></svg>`;

    const renderEntry = (gameType, m, i) => {
      const title = getGameTypeDisplayName(gameType);
      const when = m.timestamp ? new Date(m.timestamp).toLocaleString('zh-CN', { hour12: false }) : '';
      const result = m.result || '';
      const detail = m.detail || '';
      const hasReplay = !!(m.replay || m.highlight || m.afterparty || m.moment);
      return `
        <div style="background:var(--ubp-card-2);border-radius:10px;padding:10px 12px;margin-bottom:8px;border:1px solid var(--ubp-line);">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">🎮 ${title} · 第${i + 1}场</span>
            <div style="display:flex;align-items:center;gap:6px;flex:none;">
              <span style="font-size:11px;color:var(--ubp-text-3);">${when}</span>
              <button data-ubp-act="record-delete" data-game="${gameType}" data-idx="${i}" style="background:none;border:none;cursor:pointer;color:#EF4444;font-size:15px;line-height:1;padding:2px;" title="删除该场对局记录">✕</button>
            </div>
          </div>
          <div style="font-size:12px;color:var(--ubp-text-2);margin-top:4px;line-height:1.5;">${escapeHtml(result)}</div>
          ${detail ? `<div style="font-size:11.5px;color:var(--ubp-text-2);margin-top:3px;line-height:1.4;">${escapeHtml(detail)}</div>` : ''}
          <div style="display:flex;justify-content:flex-end;margin-top:6px;">
            <button data-ubp-act="record-detail" data-game="${gameType}" data-idx="${i}" class="ubp-btn" style="padding:3px 12px;font-size:11.5px;${hasReplay ? '' : 'opacity:0.45;'}" ${hasReplay ? '' : 'disabled'}>📜 查看详情</button>
          </div>
        </div>
      `;
    };

    let body = '';
    for (const gameType of types) {
      const list = store[gameType] || [];
      const isDeduction = isDeductionGame(gameType);
      body += `<div style="font-size:13px;font-weight:600;color:var(--ubp-text);margin:8px 0 6px;">${isDeduction ? '🕵️' : '♟️'} ${getGameTypeDisplayName(gameType)}（最近 ${list.length} 场）</div>`;
      body += list.map((m, i) => renderEntry(gameType, m, i)).join('');
    }
    if (!body) body = `<div class="ubp-empty" style="padding:28px 0;text-align:center;">暂无对局记录，快去游戏中心开一局吧~</div>`;

    sheet.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex:none;">
