// 渲染赛后复盘群聊：按「名字：内容」分行，每行角色名使用该角色的专属配色
  // players 传入本局玩家时使用「局内互不相同」的配色表，避免撞色
    function renderReplayRichHTML(logs, playersSnapshot) {
    const snap = Array.isArray(playersSnapshot) ? playersSnapshot : [];
    const colorMap = buildDistinctColorMap(snap.map(p => ({ name: p && p.name })));
    const colorOfPos = (pos) => {
      const p = snap.find(x => x && x.position === pos);
      if (!p || !p.name) return '';
      return colorMap.get(p.name) || getCharacterColor(p.name) || '';
    };
    const isUserPos = (pos) => snap.some(x => x && x.isUser && x.position === pos);
    const list = Array.isArray(logs) ? logs : [];
    if (!list.length) return '<div class="ubp-empty" style="padding:20px 0;text-align:center;color:var(--ubp-text-3);">（本局暂无回放内容）</div>';
    return list.map(item => {
      if (!item || typeof item !== 'object') {
        return '<div style="color:#fff;margin:2px 0;">' + escapeHtml(stripLogTags(String(item == null ? '' : item))) + '</div>';
      }
      const textHTML = escapeHtml(stripLogTags(item.text || '')).replace(/\n/g, '<br>');
      const userLine = item.authorPos != null && isUserPos(item.authorPos);
      const cc = (!userLine && item.authorPos != null) ? colorOfPos(item.authorPos) : '';
      const authorName = (() => {
        if (item.authorPos == null) return '';
        const p = snap.find(x => x && x.position === item.authorPos);
        return p && p.name ? p.name : '';
      })();
      const authorAvatar = (() => {
        if (item.authorPos == null) return '';
        const p = snap.find(x => x && x.position === item.authorPos);
        return (p && p.avatar) ? p.avatar : '';
      })();
      const avatarHTML = authorName ? chatAvatarHTML(authorName, userLine, 24, authorAvatar) : '';
      const rowOpen = authorName ? '<div style="display:flex;align-items:flex-start;gap:6px;margin:4px 0;"><div style="flex:none;">' + avatarHTML + '</div><div style="flex:1;min-width:0;">' : '';
      const rowClose = authorName ? '</div></div>' : '';
      if (item.type === 'hidden') {
        const base = cc || '#FFD700';
        return rowOpen + '<div style="color:' + base + ';font-size:11px;background:' + (charColorAlpha(cc, '17') || 'rgba(255,215,0,0.1)') + ';border-left:3px solid ' + base + ';padding:4px 6px;border-radius:4px;">' + textHTML + '</div>' + rowClose;
      }
      if (item.type === 'wolf_private') {
        return rowOpen + '<div style="color:#C084FC;font-size:12px;background:rgba(168,85,247,0.12);padding:4px;border-radius:4px;">' + textHTML + '</div>' + rowClose;
      }
      if (item.type === 'user_private') {
        return rowOpen + '<div style="color:' + (item.color || '#FBBF24') + ';font-size:12px;font-weight:600;">' + textHTML + '</div>' + rowClose;
      }
      if (userLine) {
        return rowOpen + '<div style="color:#fff;font-size:12px;font-weight:600;border-left:3px solid rgba(255,255,255,0.55);padding-left:6px;">' + textHTML + '</div>' + rowClose;
      }
      if (cc) {
        return rowOpen + '<div style="color:' + cc + ';font-size:12px;font-weight:600;border-left:3px solid ' + charColorAlpha(cc, '99') + ';padding-left:6px;">' + textHTML + '</div>' + rowClose;
      }
      return '<div style="color:#fff;margin:2px 0;">' + textHTML + '</div>';
    }).join('');
  }

  // 旧版纯文本回放兜底渲染：按「名字：内容」匹配角色专属配色，主角发言白色
  function renderReplayTextColored(text, players) {
    const list = String(text || '').split(/\n+/);
    if (!list.length) return '';
    const colorMap = buildDistinctColorMap(players || []);
    return list.map(line => {
      const t = line.trim();
      if (!t) return '<div style="height:4px;"></div>';
      const m = t.match(/^(.{1,24}?)[：:]\s*([\s\S]*)$/);
      if (m) {
        const rawName = m[1].replace(/^\d+\s*号位\s*/, '').trim();
        const p = (players || []).find(x => x && x.name && isNameMatch(x.name, rawName));
        if (p) {
          const isUser = !!p.isUser;
          const col = isUser ? '#fff' : (colorMap.get(p.name) || getCharacterColor(p.name) || '');
          if (col) {
            return '<div style="color:' + col + ';margin:4px 0;font-size:12px;font-weight:600;border-left:3px solid ' + (isUser ? 'rgba(255,255,255,0.55)' : charColorAlpha(col, '99')) + ';padding-left:6px;">' + escapeHtml(t) + '</div>';
          }
        }
      }
      return '<div style="color:var(--ubp-text);margin:2px 0;">' + escapeHtml(t) + '</div>';
    }).join('');
  }

