        <span style="font-size:15px;font-weight:600;">📜 ${getGameTypeDisplayName(rec.gameType || gameType)} · 对局详情</span>
        <button data-ubp-act="close-record-detail" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
      </div>
      <div style="flex:none;font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;line-height:1.5;">
