      </div>
      <div id="record-detail-body" style="flex:1;overflow-y:auto;font-size:12px;line-height:1.6;background:var(--ubp-card-2);border-radius:8px;padding:8px;"></div>
    `;
    sheet.appendChild(ov);

    const bodyEl = ov.querySelector('#record-detail-body');
    const tabBtns = ov.querySelectorAll('.record-detail-tab');
    const renderTab = (key) => {
      tabBtns.forEach(b => {
        const on = b.dataset.tab === key;
        b.style.background = on ? 'var(--ubp-accent, #10B981)' : 'var(--ubp-card-2)';
        b.style.color = on ? '#fff' : 'var(--ubp-text)';
        b.style.borderColor = on ? 'transparent' : 'var(--ubp-line)';
      });
      if (rec.replayRich && Array.isArray(rec.replayRich.logs) && rec.replayRich.logs.length) {
        bodyEl.innerHTML = renderReplayRichHTML(rec.replayRich.logs, rec.replayRich.players);
