        bodyEl.innerHTML = renderReplayTextColored(replay, rec.players || []);
      } else {
        bodyEl.innerHTML = `<div style="white-space:pre-wrap;">${escapeHtml(replay || '（本局暂无回放内容）')}</div>`;
      }
      bodyEl.scrollTop = 0;
    };
    tabBtns.forEach(b => b.addEventListener('click', () => renderTab(b.dataset.tab)));
    renderTab('replay');
  }

