        <span style="flex:1;font-size:12.5px;color:var(--ubp-text);line-height:1.45;">👁️ 使用观战卡（剩余 ${inv0.spectator || 0} 张）：邀请 ${boardSize} 位角色开局，你以上帝视角观战全部内容</span>
      </label>
      <div id="invite-list" style="flex:1;overflow-y:auto;margin-bottom:4px;">${listHtml}</div>
      <div style="display:flex;justify-content:space-between;align-items:center;padding-top:6px;border-top:1px solid var(--ubp-line);flex-none;">
        <div style="font-size:12px;color:var(--ubp-text-2);">已选 <span id="invite-count" style="color:var(--ubp-accent,#8B5CF6);font-weight:bold;">0</span> / <span id="invite-max">${boardSize - 1}</span><span style="color:var(--ubp-text-3);">（不足时开局由内置角色补位）</span></div>
        <button data-ubp-act="confirm-invite" class="ubp-btn primary" style="padding:6px 18px;font-size:13px;border-radius:6px;min-width:96px;" disabled>确认邀请</button>
      </div>
    `;
    sheet.appendChild(ov);
    const checks = ov.querySelectorAll('.friend-check');
    const countSpan = ov.querySelector('#invite-count');
    const confirmBtn = ov.querySelector('[data-ubp-act="confirm-invite"]');
    const update = () => {
      need = spectatorMode ? boardSize : boardSize - 1;
      max = need;
      const checked = ov.querySelectorAll('.friend-check:checked');
      countSpan.textContent = checked.length;
      const maxEl = ov.querySelector('#invite-max');
      if (maxEl) maxEl.textContent = String(need);
      const needEl = ov.querySelector('#invite-need');
      if (needEl) needEl.textContent = String(need);
      confirmBtn.disabled = checked.length > need; // 允许不足：开局时由内置角色补位凑满人数
    };
    checks.forEach(cb => cb.addEventListener('change', () => {
      const checkedNow = ov.querySelectorAll('.friend-check:checked');
      if (cb.checked && checkedNow.length > need) {
        cb.checked = false;
        showToast('本局最多邀请 ' + need + ' 位角色（' + boardSize + ' 人场）');
      }
      update();
    }));
    const specToggle = ov.querySelector('#use-spectator-card');
    if (specToggle) {
      specToggle.addEventListener('change', () => {
        spectatorMode = !!specToggle.checked;
        if (spectatorMode && (loadShopInventory().spectator || 0) <= 0) {
          spectatorMode = false;
          specToggle.checked = false;
          showToast('观战卡不足，请到积分商城购买（5 积分/张）');
        } else if (spectatorMode) {
          showToast('👁️ 观战模式：请邀请 ' + boardSize + ' 位角色，开局后你以上帝视角观战');
        }
        update();
      });
    }
    ov.querySelector('[data-ubp-act="close-invite"]').addEventListener('click', () => ov.remove());
    confirmBtn.addEventListener('click', () => {
      const checked = ov.querySelectorAll('.friend-check:checked');
      const expectNeed = spectatorMode ? boardSize : boardSize - 1;
      const selectedNames = Array.from(checked).map(c => c.value);
      const allContacts = loadContactsWithAvatars().contacts || [];
      // 人数未达标：由内置角色（角色N）补位，凑满本局人数（观战模式补满全部席位）
      const wolfNeedFill = Math.max(0, expectNeed - selectedNames.length);
      if (wolfNeedFill > 0) {
        let gi = 1, added = 0;
        while (added < wolfNeedFill) {
          const g = '角色' + (gi++);
          if (selectedNames.indexOf(g) >= 0) continue;
          selectedNames.push(g); added++;
        }
        showToast('🪑 人数未达标，已由内置角色补位 ' + wolfNeedFill + ' 位（凑满 ' + boardSize + ' 人场）');
      }
      const selectedContacts = selectedNames.map(nm2 => allContacts.find(c => c && c.name === nm2) || { name: nm2, avatar: getCharacterAvatarByName(nm2) || '', identity: '' });
      const userAvatar = getMainCharAvatar();
      const players = [];
      if (spectatorMode) {
        if (!consumeIdentityCard('spectator', 1)) { showToast('观战卡不足，请到积分商城购买'); return; }
      } else {
        players.push({ name: '我', avatar: userAvatar, isUser: true });
      }
      selectedContacts.forEach(f => {
        const av = f.avatar || getCharacterAvatarByName(f.name);
        players.push({ name: f.name, avatar: av, isUser: false });
      });
      
      const positions = Array.from({ length: boardSize }, (_, i) => i + 1);
      for (let i = positions.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [positions[i], positions[j]] = [positions[j], positions[i]];
      }
      players.forEach((p, idx) => p.position = positions[idx]);
      players.sort((a, b) => a.position - b.position);

      currentGameSession++;
      game = {
        session: currentGameSession,
        boardSize: boardSize,
        identityCards: [],
        wolfTeammateNames: [],
        spectatorNames: [],
        spectatorMode: !!spectatorMode,
        players: players.map(p => ({
          ...p,
          avatar: p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name)),
          alive: true,
          role: null,
          votedFor: null,
          hasSpoken: false
        })),
        phase: 'idle',
        day: 0,
        currentSpeaker: 0,
        winner: null,
        history: [],
        historyEntries: [],
        userIndex: players.findIndex(p => p.isUser),
        nightResult: '',
        nightKill: null,
        nightDeaths: [],
        witchAction: null,
        witchMenu: false,
        witchMenuReturn: false,
        witchUsedAntidote: false,
        witchUsedPoison: false,
        witchSavedPos: null,
        guardProtectedPos: null,
        guardLastPos: null,
        lastWolfKillPos: 0,
        lastWolfKillDied: false,
        wolfMateChatDone: false,
        wolfMateChatText: '',
        dayAnnounced: false,
        sheriffLeadDone: false,
        sheriffPos: null,
        sheriffStage: '',
        sheriffDone: false,
        sheriffCandidates: [],
        sheriffWithdrawn: [],
        sheriffVotes: {},
        sheriffDirection: '',
        sheriffDirectionDay: 0,
        sheriffPkRound: 0,
        sheriffPkCandidates: [],
        sheriffPkQueue: [],
        sheriffPkIdx: 0,
        sheriffBadgeTorn: false,
        seerChecked: {},
        votes: {},
        replay: [],
        pickMode: null,
        pick: { idx: null },
        resolvingFinalWords: null,
        tactics: { ai: '', user: '', custom: '' },
        aiWolfTactics: null,
        simNightContext: '',
        isPkVote: false,
        pkCandidates: null,
        pkSpeakerQueue: [],
        pkCurrentSpeakerIdx: 0,
        isPkSpeaking: false
      };
      isGameOver = false;
      replayLogs = [];
      ov.remove();
      renderPositions();
    });
  }

  function renderPositions() {
    if (!game) return;
    // 6人场左右各 3；9人场左 5 / 右 4；12人场左右各 6（头像与间距收紧，保证一屏放得下）
    const compact = game.players.length > 6;
    const half = Math.ceil(game.players.length / 2);
    const left = game.players.slice(0, half);
    const right = game.players.slice(half);
    const AV = game.players.length >= 12 ? 44 : compact ? 50 : 64;

    const renderLeftPositionPlayer = (p) => {
      const avatar = p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name));
      if (!p.avatar && avatar) p.avatar = avatar;
      return `
        <div style="display:flex;flex-direction:row;align-items:center;justify-content:flex-start;gap:4px;margin:${compact ? 3 : 8}px 0;padding-left:0;">
          <div style="writing-mode:vertical-rl;text-orientation:mixed;font-size:12px;max-height:64px;color:var(--ubp-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;letter-spacing:1px;line-height:1.1;margin-left:0;">${p.name}</div>
          <div style="width:${AV}px;height:${AV}px;border-radius:10px;background:#4CAF50;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:${compact ? 15 : 18}px;color:#fff;font-weight:600;border:2px solid var(--ubp-line);flex-shrink:0;box-shadow:0 2px 6px rgba(0,0,0,0.2);position:relative;">
            ${avatar ? `<img src="${avatar}" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.style.display='none'; if(this.nextElementSibling) this.nextElementSibling.style.display='flex';"><span style="display:none;width:100%;height:100%;align-items:center;justify-content:center;">${p.position}</span>` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;">${p.position}</span>`}
          </div>
        </div>
      `;
    };

    const renderRightPositionPlayer = (p) => {
      const avatar = p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name));
      if (!p.avatar && avatar) p.avatar = avatar;
      return `
        <div style="display:flex;flex-direction:row;align-items:center;justify-content:flex-end;gap:4px;margin:${compact ? 3 : 8}px 0;padding-right:0;">
          <div style="width:${AV}px;height:${AV}px;border-radius:10px;background:#4CAF50;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:${compact ? 15 : 18}px;color:#fff;font-weight:600;border:2px solid var(--ubp-line);flex-shrink:0;box-shadow:0 2px 6px rgba(0,0,0,0.2);position:relative;">
            ${avatar ? `<img src="${avatar}" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.style.display='none'; if(this.nextElementSibling) this.nextElementSibling.style.display='flex';"><span style="display:none;width:100%;height:100%;align-items:center;justify-content:center;">${p.position}</span>` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;">${p.position}</span>`}
          </div>
          <div style="writing-mode:vertical-rl;text-orientation:mixed;font-size:12px;max-height:64px;color:var(--ubp-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;letter-spacing:1px;line-height:1.1;margin-right:0;">${p.name}</div>
        </div>
      `;
    };

    sheet.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex-none;">
        <span style="font-size:17px;font-weight:600;">📋 座位分配</span>
        <button data-ubp-act="back-board" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);">✕</button>
      </div>
      <div style="display:flex;justify-content:space-between;align-items:center;width:100%;padding:0;margin:16px 0;flex:1;box-sizing:border-box;">
        <div style="display:flex;flex-direction:column;gap:${compact ? 6 : 16}px;">${left.map(p => renderLeftPositionPlayer(p)).join('')}</div>
        <div style="display:flex;flex-direction:column;gap:${compact ? 6 : 16}px;">${right.map(p => renderRightPositionPlayer(p)).join('')}</div>
      </div>
      ${game.spectatorMode
        ? '<div style="margin-top:6px;flex:none;border-top:1px solid var(--ubp-line);padding-top:8px;text-align:center;font-size:11.5px;color:#0EA5E9;line-height:1.6;">👁️ 上帝视角观战模式<br>本局由 6 位角色自动对局，你可以看到所有身份与夜间行动。</div>'
        : '<div style="margin-top:6px;flex:none;border-top:1px solid var(--ubp-line);padding-top:8px;">' + renderIdentityCardPanel() + '</div>'}
      <div style="text-align:center;font-size:10.5px;color:var(--ubp-text-3);line-height:1.5;margin-top:6px;flex:none;">若有多余的见面角色的角色卡可使用多余身份卡邀请其他角色成为你的狼人队友</div>
      <div style="display:flex;justify-content:center;margin-top:6px;flex-none;">
        <button data-ubp-act="start-game" class="ubp-btn primary" style="padding:6px 24px;font-size:13px;border-radius:6px;min-width:130px;">🎯 开始游戏</button>
      </div>
    `;
  }

  // ========== 狼人杀：身份卡选择面板（座位分配页） ==========
  // 身份卡与当前板子的兼容判断：守卫仅12人场、猎人仅9/12人场，其余全板子通用
  function isCardAllowedForBoard(key) {
    const n = game ? (game.players || []).length : 6;
    if (key === 'guard') return n >= 12;
    if (key === 'hunter') return n >= 9;
    return true;
  }

  function renderIdentityCardPanel() {
    const inv = loadShopInventory();
    const picked = (game && game.identityCards) ? game.identityCards : [];
    const cards = IDENTITY_CARD_TYPES.map(t => {
      const owned = inv[t.key] || 0;
      const used = picked.filter(k => k === t.key).length;
      const sel = used > 0;
      const allowed = isCardAllowedForBoard(t.key);
      const gray = (owned <= 0 && !sel) || (!allowed && !sel);
      const count = owned;
      return '<div data-ubp-act="pick-identity-card" data-card="' + t.key + '" style="position:relative;flex:1;min-width:0;border:2px solid ' + (sel ? t.color : 'var(--ubp-line)') + ';border-radius:9px;padding:6px 3px 4px;text-align:center;cursor:' + (gray ? 'not-allowed' : 'pointer') + ';background:' + (sel ? t.color + '26' : 'var(--ubp-card-2)') + ';' + (gray ? 'filter:grayscale(100%);opacity:0.5;' : '') + (sel ? 'box-shadow:0 0 8px ' + t.color + '99;' : '') + '">' +
        '<div style="font-size:19px;line-height:1.1;">' + t.icon + '</div>' +
        '<div style="font-size:10px;font-weight:700;color:' + (gray ? 'var(--ubp-text-3)' : t.color) + ';margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + t.name.replace('卡', '') + '</div>' +
        '<div style="position:absolute;right:-4px;bottom:-4px;min-width:15px;height:15px;border-radius:999px;background:' + (count > 0 ? t.color : '#6b7280') + ';color:#fff;font-size:9.5px;font-weight:700;line-height:15px;text-align:center;padding:0 3px;box-sizing:border-box;">' + count + '</div>' +
        (sel ? '<div style="position:absolute;left:-4px;top:-4px;background:' + t.color + ';color:#fff;font-size:9px;border-radius:4px;padding:0 3px;line-height:13px;">已选' + (used > 1 ? ' ' + used : '') + '</div>' : '') +
        ((!allowed && !sel) ? '<div style="position:absolute;left:-4px;top:-4px;background:#6b7280;color:#fff;font-size:9px;border-radius:4px;padding:0 3px;line-height:13px;">无此身份</div>' : '') +
        '</div>';
    }).join('');
    const wolvesPicked = picked.filter(k => k === 'wolf').length;
    const hasNonWolf = picked.some(k => k !== 'wolf');
    const selfWolf = !hasNonWolf && wolvesPicked > 0;
    const mateSlots = Math.max(0, Math.min(1, wolvesPicked - (selfWolf ? 1 : 0)));
    const ownsWolf = (inv.wolf || 0) > 0;
    const teammates = (game && Array.isArray(game.wolfTeammateNames)) ? game.wolfTeammateNames : [];
    const mateRow = (ownsWolf || wolvesPicked > 0 || teammates.length) ? (
      '<div style="margin-top:7px;">' +
      '<div style="font-size:10.5px;color:var(--ubp-text-3);margin-bottom:4px;">🐺 多余狼人卡可邀请 ' + mateSlots + ' 位角色成为狼人队友' + (teammates.length ? '：<b style="color:#F44336;">' + teammates.map(n => escapeHtml(n)).join('、') + '</b>' : '') + '</div>' +
      '<button data-ubp-act="invite-wolf-teammate" class="ubp-btn" style="width:100%;padding:5px 0;font-size:11.5px;' + (mateSlots > 0 ? '' : 'opacity:0.5;') + '">🤝 邀请狼人队友（消耗多余狼人卡）</button>' +
      '</div>') : '';
    return '<div style="font-size:11px;font-weight:600;color:var(--ubp-text);margin-bottom:5px;">🎴 选择身份卡（可选）' +
      '<span style="font-weight:normal;color:var(--ubp-text-3);"> · 未持有为灰色，狼人卡可多选</span></div>' +
      '<div style="display:flex;gap:6px;">' + cards + '</div>' +
      '<div style="font-size:10px;color:var(--ubp-text-3);margin-top:5px;line-height:1.45;">选择后开局按所选身份卡分配你的身份，其余角色随机分配剩余身份；不选则所有人随机分配。</div>' +
      mateRow;
  }

  // 狼人队友邀请弹窗（消耗多余狼人卡，邀请角色成为狼人）
  function renderWolfTeammatePicker() {
    if (!game) return;
    const pickedCards = Array.isArray(game.identityCards) ? game.identityCards : [];
    const wolvesPicked = pickedCards.filter(k => k === 'wolf').length;
    const hasNonWolf = pickedCards.some(k => k !== 'wolf');
    const selfWolf = !hasNonWolf && wolvesPicked > 0;
    const already = game.wolfTeammateNames || [];
    const maxMates = Math.max(0, Math.min(1, wolvesPicked - (selfWolf ? 1 : 0)));
    if (maxMates <= 0) { showToast('请先在座位页勾选狼人卡：自己当狼人用 1 张，多余的才能邀请队友'); return; }
    // 只能从本局被邀请的角色（不含主角）中挑选狼人队友
    const contactMap = {};
    try {
      const result = loadContactsWithAvatars();
      ((result && result.contacts) || []).forEach(ct => { if (ct && ct.name) contactMap[ct.name] = ct; });
    } catch (e) { /* ignore */ }
    const candidates = (game.players || []).filter(p => p && !p.isUser).map(p => {
      const ct = contactMap[p.name] || {};
      return { name: p.name, avatar: p.avatar || ct.avatar || getCharacterAvatarByName(p.name) || '', identity: ct.identity || '' };
    });
    const ov = document.createElement('div');
    ov.className = 'wolf-teammate-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:62;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const renderContent = () => {
      const list = candidates.map(ct => {
        const on = already.some(n => isNameMatch(n, ct.name));
        const av = ct.avatar || getCharacterAvatarByName(ct.name);
        return '<div data-wolf-pick="' + escapeHtml(ct.name).replace(/"/g, '&quot;') + '" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:' + (on ? 'rgba(244,67,54,0.16)' : 'var(--ubp-card-2)') + ';border:1.5px solid ' + (on ? '#F44336' : 'var(--ubp-line)') + ';">' +
          '<div style="width:34px;height:34px;border-radius:50%;background:#F44336;overflow:hidden;flex-shrink:0;">' +
          (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:13px;">' + escapeHtml(ct.name.slice(0, 1)) + '</span>') + '</div>' +
          '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(ct.name) + '</div>' +
          (ct.identity ? '<div style="font-size:10.5px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;">' + escapeHtml(ct.identity) + '</div>' : '') + '</div>' +
          '<span style="font-size:15px;color:#F44336;flex-shrink:0;">' + (on ? '✅' : '○') + '</span></div>';
      }).join('');
      ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">' +
        '<span style="font-size:15px;font-weight:600;">🐺 邀请狼人队友（仅限本局受邀角色）</span>' +
        '<button data-wolf-act="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
        '<div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:8px;">已选 <b style="color:#F44336;">' + already.length + '</b> / ' + maxMates + ' 位（每邀请 1 位消耗 1 张多余狼人卡）</div>' +
        '<div style="flex:1;overflow-y:auto;margin-bottom:8px;">' + (list || '<div style="font-size:12px;color:var(--ubp-text-3);">本局没有可邀请的角色。</div>') + '</div>' +
        '<div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-wolf-act="confirm" class="ubp-btn primary" style="padding:6px 20px;font-size:13px;background:#F44336;border:none;border-radius:6px;">确认邀请</button></div>';
      ov.querySelectorAll('[data-wolf-pick]').forEach(el => {
        el.addEventListener('click', () => {
          const name = el.dataset.wolfPick;
          const i = already.findIndex(n => isNameMatch(n, name));
          if (i !== -1) already.splice(i, 1);
          else { if (already.length >= maxMates) { showToast('最多可邀请 ' + maxMates + ' 位（受多余狼人卡数量限制）'); return; } already.push(name); }
          game.wolfTeammateNames = already;
          renderContent();
        });
      });
      ov.querySelector('[data-wolf-act="close"]')?.addEventListener('click', () => { ov.remove(); renderPositions(); });
      ov.querySelector('[data-wolf-act="confirm"]')?.addEventListener('click', () => {
        game.wolfTeammateNames = already.slice();
        ov.remove();
        renderPositions();
        showToast(already.length ? ('🐺 已邀请 ' + already.join('、') + ' 作为狼人队友') : '已取消狼人队友邀请');
      });
    };
    renderContent();
    sheet.appendChild(ov);
  }



  function renderSpectatorPicker() {
    if (!game) return;
    const inv = loadShopInventory();
    if ((inv.spectator || 0) <= 0) { showToast('还没有【观战卡】，请到积分商城购买（5 积分/张）'); return; }
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    const playerNames = (game.players || []).map(p => p.name);
    const candidates = contacts.filter(ct => ct && ct.name && !playerNames.some(n => isNameMatch(n, ct.name)));
    if (!candidates.length) { showToast('通讯录没有可邀请的观战角色（需邀请 6 位参赛角色以外的角色）'); return; }
    const picked = Array.isArray(game.spectatorNames) ? game.spectatorNames.slice() : [];
    const MAX = 6;
    const ov = document.createElement('div');
    ov.className = 'spectator-picker-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:66;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const renderContent = () => {
      const list = candidates.map(ct => {
        const on = picked.some(n => isNameMatch(n, ct.name));
        const av = ct.avatar || getCharacterAvatarByName(ct.name);
        return '<div data-spec-pick="' + escapeHtml(ct.name).replace(/"/g, '&quot;') + '" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:' + (on ? 'rgba(14,165,233,0.16)' : 'var(--ubp-card-2)') + ';border:1.5px solid ' + (on ? '#0EA5E9' : 'var(--ubp-line)') + ';">' +
          '<div style="width:34px;height:34px;border-radius:50%;background:#0EA5E9;overflow:hidden;flex-shrink:0;">' +
          (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:13px;">' + escapeHtml(ct.name.slice(0, 1)) + '</span>') + '</div>' +
          '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(ct.name) + '</div>' +
          (ct.identity ? '<div style="font-size:10.5px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;">' + escapeHtml(ct.identity) + '</div>' : '') + '</div>' +
          '<span style="font-size:15px;color:#0EA5E9;flex-shrink:0;">' + (on ? '✅' : '○') + '</span></div>';
      }).join('');
      ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">' +
        '<span style="font-size:15px;font-weight:600;">👁️ 邀请观战角色（上帝视角）</span>' +
        '<button data-spec-act="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
        '<div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:8px;">已选 <b style="color:#0EA5E9;">' + picked.length + '</b> / ' + MAX + ' 位；消耗 1 张观战卡，观战角色可看到全场底牌与夜间行动。</div>' +
        '<div style="flex:1;overflow-y:auto;margin-bottom:8px;">' + list + '</div>' +
        '<div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-spec-act="confirm" class="ubp-btn primary" style="padding:6px 20px;font-size:13px;background:#0EA5E9;border:none;border-radius:6px;">确认邀请</button></div>';
      ov.querySelectorAll('[data-spec-pick]').forEach(el => {
        el.addEventListener('click', () => {
          const nm = el.dataset.specPick;
          const i = picked.findIndex(n => isNameMatch(n, nm));
          if (i !== -1) picked.splice(i, 1);
          else {
            if (picked.length >= MAX) { showToast('最多邀请 ' + MAX + ' 位观战角色'); return; }
            picked.push(nm);
          }
          renderContent();
        });
      });
      ov.querySelector('[data-spec-act="close"]')?.addEventListener('click', () => { ov.remove(); renderPositions(); });
      ov.querySelector('[data-spec-act="confirm"]')?.addEventListener('click', () => {
        if (!picked.length) { showToast('请至少选择 1 位观战角色'); return; }
        if (!consumeIdentityCard('spectator', 1)) { showToast('观战卡不足'); return; }
        game.spectatorNames = picked.slice();
        ov.remove();
        renderPositions();
        showToast('👁️ 已邀请 ' + picked.join('、') + ' 以上帝视角观战本局');
      });
    };
    renderContent();
    sheet.appendChild(ov);
  }

  // 对局中显示的观战席条
  function renderSpectatorStripHTML() {
    if (!game || !Array.isArray(game.spectatorNames) || !game.spectatorNames.length) return '';
    const avs = game.spectatorNames.map(nm => {
      const av = getCharacterAvatarByName(nm) || '';
      return '<span title="' + escapeHtml(nm) + '" style="display:inline-flex;width:22px;height:22px;border-radius:50%;overflow:hidden;background:#0EA5E9;border:1.5px solid rgba(14,165,233,0.7);flex:none;">' +
        (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-size:10px;font-weight:700;">' + escapeHtml(String(nm).slice(0, 1)) + '</span>') +
        '</span>';
    }).join('');
    return '<div style="display:flex;align-items:center;gap:6px;margin:0 0 5px;flex:none;overflow-x:auto;">' +
      '<button data-ubp-act="open-spectators" style="display:inline-flex;align-items:center;gap:4px;background:rgba(14,165,233,0.14);border:1px solid rgba(14,165,233,0.5);border-radius:999px;padding:2px 9px;font-size:11px;font-weight:600;color:#0EA5E9;cursor:pointer;flex:none;">👁️ 观战席</button>' +
      '<span style="display:inline-flex;align-items:center;gap:3px;flex:none;">' + avs + '</span>' +
