  // 上帝视角面板：观战角色可看到所有内容
  function showSpectatorPanel() {
    if (!game) return;
    const names = Array.isArray(game.spectatorNames) ? game.spectatorNames : [];
    if (!names.length) { showToast('本局没有观战角色（可在板子选择界面使用观战卡邀请）'); return; }
    const ov = document.createElement('div');
    ov.className = 'spectator-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:72;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const roleColor = (r) => r === '狼人' ? '#EF4444' : r === '预言家' ? '#8B5CF6' : r === '女巫' ? '#3B82F6' : '#10B981';
    const playerLines = (game.players || []).map(p => {
      return '<div style="display:flex;align-items:center;gap:6px;padding:4px 6px;border-radius:6px;background:var(--ubp-card-2);margin-bottom:4px;">' +
        chatAvatarHTML(p.name, !!p.isUser, 24) +
        '<span style="flex:1;min-width:0;font-size:12px;color:var(--ubp-text);">' + escapeHtml(p.position + '号位 ' + p.name) + (p.isUser ? '（主角）' : '') + '</span>' +
        '<span style="font-size:11.5px;font-weight:700;color:' + roleColor(p.role) + ';">' + escapeHtml(p.role || '未分配') + '</span>' +
        '<span style="font-size:11px;color:var(--ubp-text-3);flex:none;">' + (p.alive ? '存活' : '出局') + '</span></div>';
    }).join('');
    const specChips = names.map(nm => '<span style="display:inline-flex;align-items:center;gap:5px;margin:2px 6px 2px 0;padding:3px 8px;border-radius:999px;background:rgba(14,165,233,0.12);border:1px solid rgba(14,165,233,0.4);">' + chatAvatarHTML(nm, false, 22) + '<span style="font-size:11.5px;color:var(--ubp-text);">' + escapeHtml(nm) + '</span></span>').join('');
    const extra = [];
    if (game.nightResult) extra.push('昨夜结果：' + game.nightResult);
    if (game.nightKill && game.nightKill.name) extra.push('狼人刀口：' + game.nightKill.name);
    if (game.witchAction && typeof game.witchAction === 'string') extra.push('女巫行动：' + game.witchAction);
    const recent = (game.history || []).slice(-8).map(x => '<div style="font-size:11.5px;color:var(--ubp-text-2);line-height:1.45;margin-bottom:2px;">' + escapeHtml(stripLogTags(String(x))) + '</div>').join('');
    ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">' +
      '<span style="font-size:15px;font-weight:600;">👁️ 观战席 · 上帝视角</span>' +
      '<button data-spec-act="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
      '<div style="flex:1;overflow-y:auto;">' +
      '<div style="font-size:11.5px;font-weight:600;color:var(--ubp-text);margin-bottom:4px;">全体底牌</div>' + playerLines +
      (extra.length ? '<div style="font-size:11px;color:#0EA5E9;margin:6px 0;">' + extra.map(escapeHtml).join('<br>') + '</div>' : '') +
      '<div style="font-size:11.5px;font-weight:600;color:var(--ubp-text);margin:8px 0 4px;">最近进程</div>' + (recent || '<div style="font-size:11.5px;color:var(--ubp-text-3);">（开局阶段）</div>') +
      '<div style="font-size:11.5px;font-weight:600;color:var(--ubp-text);margin:8px 0 4px;">观战角色</div><div>' + specChips + '</div>' +
      '</div>' +
      '<div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
      '<button data-spec-act="comment" class="ubp-btn primary" style="padding:6px 16px;font-size:12.5px;background:#0EA5E9;border:none;border-radius:6px;">🎙️ 让观战席锐评</button></div>';
    ov.querySelector('[data-spec-act="close"]')?.addEventListener('click', () => { ov.remove(); });
    ov.querySelector('[data-spec-act="comment"]')?.addEventListener('click', () => { generateSpectatorComment(); });
    sheet.appendChild(ov);
