  // ========== AI 调用核心（全量 maxTokens 统一扩充至 3000） ==========
  // ========== 所有 AI 请求内置 5 秒 CD（按发起顺序排队，两次请求间隔至少 5 秒） ==========
  // 测试环境可用 window.__API_CD_MS__ = 0 关闭冷却
  let __apiCooldownUntil = 0;
  function __apiCooldownWait() {
    let cd = 5000;
    try { if (typeof window !== 'undefined' && typeof window.__API_CD_MS__ === 'number') cd = window.__API_CD_MS__; } catch (e) { /* ignore */ }
    if (cd <= 0) return Promise.resolve();
    const now = Date.now();
    const wait = Math.max(0, __apiCooldownUntil - now);
    __apiCooldownUntil = Math.max(now, __apiCooldownUntil) + cd;
    if (wait <= 0) return Promise.resolve();
    return new Promise(resolve => setTimeout(resolve, wait));
  }
  // 统一 AI 请求入口：先过 5 秒 CD 再真正发起请求
  function apiChat(messages, config, opts = {}) {
    return __apiCooldownWait().then(() => apiChatInner(messages, config, opts));
  }

  // ========== 酒馆助手原生生成通道 ==========
  function __getTavernHelper__() {
    try {
      if (window.TavernHelper) return window.TavernHelper;
      if (window.parent && window.parent.TavernHelper) return window.parent.TavernHelper;
    } catch (e) { /* ignore */ }
    return null;
  }
  function __hasTavernGenerate__() {
    const th = __getTavernHelper__();
    return !!(th && typeof th.generateRaw === 'function');
  }
  // 将 chat 消息映射为 generateRaw 的 ordered_prompts
  function __tavernGenerateRaw__(messages, opts) {
    const th = __getTavernHelper__();
    if (!th || typeof th.generateRaw !== 'function') {
      return Promise.reject(new Error('酒馆助手未提供 generateRaw'));
    }
    const sysParts = [];
    const userParts = [];
    for (const m of (Array.isArray(messages) ? messages : [])) {
      if (!m) continue;
      const content = String(m.content == null ? '' : m.content).trim();
      if (!content) continue;
      if (m.role === 'system') sysParts.push(content);
      else if (m.role === 'assistant') userParts.push('（你之前说过）' + content);
      else userParts.push(content);
    }
    const userInput = userParts.join('\n\n') || '（请根据以上设定继续）';
    const systemText = sysParts.join('\n\n');
    const ordered = [];
    if (systemText) ordered.push({ role: 'system', content: systemText });
    ordered.push('user_input');
    const req = {
      should_silence: true,
      user_input: userInput,
      ordered_prompts: ordered,
      max_chat_history: 0
    };
    return Promise.resolve(th.generateRaw(req)).then(t => {
      const out = String(t == null ? '' : t).trim();
      if (!out) throw new Error('AI返回了空内容');
      return out;
    });
  }
  // 是否具备可用的 AI 生成通道：自填 API 或酒馆助手 generateRaw
  function ensureAIBackend() {
    const apiCfg = resolveApiConfig();
    if (apiCfg && apiCfg.apiUrl && String(apiCfg.apiUrl).trim()) return apiCfg;
    if (__hasTavernGenerate__()) return apiCfg || { apiUrl: '', apiKey: '', model: '' };
    return null;
  }

  function apiChatInner(messages, config, opts = {}) {
    const hasCustom = !!(config && config.apiUrl && String(config.apiUrl).trim());
    if (!hasCustom) {
      if (__hasTavernGenerate__()) return __tavernGenerateRaw__(messages, opts);
      return Promise.reject(new Error('未配置API地址且酒馆助手不含 generateRaw'));
    }
    const url = config.apiUrl.replace(/\/+$/, '') + '/chat/completions';
    const payload = {
      model: config.model || 'gpt-3.5-turbo',
      messages,
      temperature: opts.temperature ?? 0.8,
      max_tokens: opts.maxTokens ?? 3000,
      stream: false
    };
    const timeout = opts.timeout ?? 65000;
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeout);
    return fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${config.apiKey}` },
      body: JSON.stringify(payload),
      signal: ctrl.signal
    }).then(res => {
      clearTimeout(timer);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    }).then(data => {
      const content = data.choices?.[0]?.message?.content || '';
      if (!content.trim()) throw new Error('AI返回了空内容');
      return content;
    }).catch(err => {
      clearTimeout(timer);
      // 仅在网络/超时类错误时回退酒馆助手原生通道；HTTP 错误（401/429/5xx）等直接抛给 UI，
      // 否则"API 配置错误"会被静默掩盖成"生成成功"，玩家永远看不到真正原因。
      const name = err && err.name;
      const isNetworkErr = name === 'AbortError' || name === 'TypeError';
      if (isNetworkErr && __hasTavernGenerate__()) return __tavernGenerateRaw__(messages, opts);
      throw err;
    });
  }

  function getPlayerPersonalityPrompt(player) {
    if (!player || player.isUser) return '';
