      if (prof.languageStyle) info += `- 说话习惯与语言口癖：${prof.languageStyle}\n`;
      if (prof.attitude) info += `- 【对主角（${userPos} 玩家本人）的态度与关系】：${prof.attitude}\n`;
      if (prof.brief) info += `- 人物简介：${prof.brief}\n`;
    } else {
      info += `- 基础设定：普通角色，以自然真人风格发挥。\n`;
    }

    if (game?.players) {
      // 狼人杀不做难度分档：始终提供本局人物关系
      info += getInterPersonalContext(player, game.players);
    }
    
    info += `【人设立场、互动与游戏本质法则】：\n1. 【这只是一个桌游聚会游戏】：所有玩家深刻明白被杀、被毒、被放逐出局【绝非真正死亡】，这只是游戏规则上的淘汰并暂停发言！出局时的反应是游戏中的自然情绪反应（懊恼、戏谑、认栽或复盘等），绝对不要表演生离死别惨剧！\n2. 【角色间的热烈互动】：发言不能只面向法官或单向对着主角，必须结合你与场上其他角色的人物关系、过往私聊与朋友圈动态进行【角色之间的互动交锋】！比如跟关系好的人抱团、吐槽损友、怀疑平时就不对付的人、接对方刚才的话题等。\n3. 【绝对忠于底牌目标】：在遵守人设和互动乐趣的前提下，你必须全力协助你的阵营获胜。好人必须帮好人抓狼，狼人必须帮狼队屠城。你绝不能违背狼人杀游戏规则去公然自爆投降或通敌！`;
    return info;
  }

  function getGamePublicOverview(player) {
    const plist = game.players.map(p => `${p.position}号位: ${p.name}（状态: ${p.alive ? '存活' : '已出局'}${(game.players.length >= 12 && game.sheriffPos === p.position && !game.sheriffBadgeTorn) ? '，警长🎖️' : ''}${p.isUser ? '，主角本人' : ''}）`).join('\n');
    const userPlayer = game.players[game.userIndex];
    let myRoleInfo = '';
    if (player) {
      myRoleInfo = `\n\n【你扮演的玩家席位】：${player.position}号位 ${player.name}\n【你的真实底牌】：${player.role}`;
      if (player.role === '狼人') {
        const mates = game.players.filter(p => p.role === '狼人' && p.position !== player.position);
        if (mates.length > 0) {
          myRoleInfo += `\n【你的狼队友】：${mates.map(m => `${m.position}号位 ${m.name}（${m.alive ? '存活' : '已出局'}）`).join('、')}`;
        } else {
          myRoleInfo += `\n【你的狼队友】：无（你是孤狼）`;
        }
        myRoleInfo += `\n（铁律：你仅知道狼队友是谁，场上好人阵营中谁是预言家、女巫、村民对你完全未知，严禁开天眼！必须通过白天的公开发言进行逻辑分析判断）`;
      } else {
        myRoleInfo += `\n（铁律：除你自己的身份外，你完全不知道场上任何其他人的真实底牌！严禁开天眼！只能依据公开发言进行推理）`;
      }
      myRoleInfo += getPlayerPersonalityPrompt(player);
      if (game.players.length >= 12) {
        const sheriffP = (game.sheriffPos && !game.sheriffBadgeTorn) ? game.players.find(p => p.position === game.sheriffPos) : null;
        if (sheriffP) {
          myRoleInfo += '\n【本局警长与警徽】：警长是 ' + sheriffP.position + '号位 ' + sheriffP.name + '（警长票计1.5票，并决定每天从警左/警右开始发言）' + (sheriffP.position === player.position ? '——正是你本人！请善用1.5票归票权与发言顺序决策权，你出局时还要决定警徽移交给谁或撕毁。' : '。警长出局时可把警徽移交给一名存活玩家或撕毁警徽（警徽没了就按普通规则从存活最小号位开始发言）。');
        } else {
          myRoleInfo += '\n【本局警长与警徽】：当前没有警长' + (game.sheriffBadgeTorn ? '（警徽已被撕毁）' : '（尚未竞选产生）。') + '警长拥有1.5票归票权。';
        }
      }
    }
    
    // 狼人杀不做难度分档：始终提供历史对局摘要 + 对主角的历史出招统计
    const pastMatchesPrompt = getPastMatchesSummaryPrompt() + getUserTendencyStats();
    const boardCount = (game.players || []).length;
    const boardDesc = boardCount >= 12
      ? '4狼人、4村民、1预言家、1女巫、1猎人、1守卫（守卫每晚守护1人使其免疫狼刀，可自守，不能连续两晚守护同一人；猎人被放逐或被夜杀出局时可开枪带走1人，被女巫毒死或作为最后一位神职出局时不能开枪）'
      : boardCount >= 9
        ? '3狼人、3村民、1预言家、1女巫、1猎人（猎人被放逐或被夜杀出局时可开枪带走1人，被女巫毒死或作为最后一位神职出局时不能开枪）'
        : '2狼人、2村民、1预言家、1女巫';
    const winRule = game.players.length >= 9
      ? '狼人需屠边：村民全部出局（屠民）或神职全部出局（屠神）即狼人获胜；猎人作为最后一位神职出局时无法开枪，遗言后直接结束游戏'
      : '狼人需屠城（好人阵营存活人数≤1即狼人获胜）';
    return `本局${boardCount}人狼人杀场上存活情况（玩家本人为 ${userPlayer ? `${userPlayer.position}号位 我` : '我'}）：\n${plist}\n规则：${boardDesc}。女巫仅首夜可以自救，其余夜晚中刀不可自救，一晚只用一瓶药。${winRule}。无警长。平票进入PK辩解与PK投票，二次平票直接进入夜晚。${myRoleInfo}${pastMatchesPrompt}`;
  }

  // 对主角的历史出招统计（本地代码算出来，作为纯文本喂给 LLM）
  // 注意：狼人杀 / 谁是卧底不做难度分档，这些信息始终全部提供给 LLM。
  function getUserTendencyStats() {
    try {
      const history = loadPastMatchesHistory();
      if (!history || !history.length) return '';
      const lines = [];
      let total = 0, wins = 0, asWolf = 0, wolfWins = 0;
      for (const m of history) {
        // 只统计带新字段（userWon / players）的记录：旧存量记录没有这两个字段，
        // 直接计入会把主角胜率错误地算成 0%（给 LLM 喂错误信息比不喂更糟）。
        if (!m || typeof m.userWon !== 'boolean' || !Array.isArray(m.players) || !m.players.length) continue;
        total++;
        const userWon = !!m.userWon;
        if (userWon) wins++;
        const userRole = m.players.find(p => p && p.isUser)?.role;
        if (userRole === '狼人') { asWolf++; if (userWon) wolfWins++; }
      }
      if (!total) return '';
      lines.push(`- 近 ${total} 场对局：主角胜率 ${Math.round((wins / total) * 100)}%`);
      if (asWolf) lines.push(`- 主角拿到狼人牌 ${asWolf} 次（其中获胜 ${wolfWins} 次）：当狼时更偏向隐藏与带节奏`);
      lines.push('- 请据此调整对主角的怀疑权重与话术（主角偏好被记录的弱点要重点针对）');
      return `\n【对主角的历史出招统计（本地统计，仅供参考）】：\n${lines.join('\n')}`;
    } catch (e) { return ''; }
  }

  function getPlayerHistoryContext(player) {
    if (!game) return '';
    // 狼人杀不做难度分档：始终提供全部历史发言（不再按难度截断）
    // 但长对局（多天多轮）会无上限膨胀，这里加一个"按字符数"的软上限，保留最近的部分。
    if (game.historyEntries && game.historyEntries.length > 0) {
      const lines = [];
      for (const entry of game.historyEntries) {
        if (entry.type === 'thought') {
          if (player && entry.authorPos === player.position) {
            lines.push(entry.text);
          }
        } else if (entry.type === 'wolf_private') {
          if (player && player.role === '狼人') {
            lines.push(entry.text);
          }
        } else if (entry.type === 'public') {
          lines.push(entry.text);
        }
      }
      return capTextByChars(lines.join('\n'), 6000);
    }
    if (!game.history) return '';
    return capTextByChars(game.history.map(line => line.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim()).filter(Boolean).join('\n'), 6000);
  }

  // 防全知：AI 角色能看到的私有信息只有「属于自己身份的系统内容」，
  // 其他玩家的身份、夜间行动与内心思考一律不可见（公开信息由历史记录提供）。
  function getPlayerIdentitySystemContext(player) {
    if (!player || !game) return '';
    if (player.role === '狼人') {
      const mates = game.players.filter(p => p.role === '狼人' && p.position !== player.position);
      return '\n【属于你（狼人）的系统信息】' + (mates.length
        ? '你的狼队友：' + mates.map(m => `${m.position}号位 ${m.name}（${m.alive ? '存活' : '已出局'}）`).join('、')
        : '你是孤狼，没有存活的狼队友') + '。\n（铁律：除自己的底牌与狼队友外，其他玩家的真实身份与夜间行动对你完全未知，严禁开天眼）';
    }
    if (player.role === '预言家') {
      const checks = Object.keys(game.seerChecked || {}).map(posStr => {
        const pos = parseInt(posStr, 10);
        const t = game.players.find(p => p.position === pos);
        return t ? `${t.position}号位 ${t.name}：${t.role === '狼人' ? '狼人（查杀）' : '好人（金水）'}` : '';
      }).filter(Boolean);
      return '\n【属于你（预言家）的系统信息 · 你的真实查验结果】\n' + (checks.length ? checks.join('\n') : '（暂无查验记录）') + '\n（这是只有你知道的私有信息，可用于推理；严禁在公开发言中直接使用未公开的其他信息）';
    }
    if (player.role === '女巫') {
      let s = '\n【属于你（女巫）的系统信息】解药' + (game.witchUsedAntidote ? '已用' : '未用') + '，毒药' + (game.witchUsedPoison ? '已用' : '未用') + '。';
      if (game.witchSavedPos) {
        const t = game.players.find(p => p.position === game.witchSavedPos);
        if (t) s += ' 你救下的银水是 ' + t.position + '号位 ' + t.name + '。';
      }
      return s + '\n（以上为只有你知道的私有信息，严禁开天眼使用其他未公开信息）';
    }
    if (player.role === '猎人') {
      const otherGodsAlive = game.players.some(p => p.alive && p.position !== player.position && (p.role === '预言家' || p.role === '女巫' || p.role === '守卫'));
      return '\n【属于你（猎人）的系统信息】你被投票放逐或被狼人夜杀出局时可以开枪带走 1 人；被女巫毒死则不能开枪；若你是场上最后一位神职，出局后本局立即结束、无法开枪。'
        + (otherGodsAlive ? '' : '（你目前已是场上最后一位神职）');
    }
    if (player.role === '守卫') {
      const lastT2 = game.guardLastPos ? game.players.find(p => p.position === game.guardLastPos) : null;
      return '\n【属于你（守卫）的系统信息】你每晚守护 1 人使其免疫狼刀；可以自守；不能连续两晚守护同一人。'
        + (lastT2 ? '你上一晚守护的是 ' + lastT2.position + '号位 ' + lastT2.name + '（今晚不可再守TA）。' : '你今晚没有连守限制。')
        + '\n（守护目标属于你的隐私，严禁通过公开发言暴露你的守护历史；只有你自己与法官知道守了谁）';
    }
    if (player.role === '民') {
      return '\n【属于你（村民）的系统信息】你没有夜间技能，只能依据公开发言与投票进行推理。';
    }
    return '';
  }

  // 告诉 AI 本轮白天的发言顺序（顺时针/逆时针），避免 AI 不清楚轮次方向
  function getSpeechOrderNoteForAI() {
    if (!game || game.phase !== 'day') return '';
    const cur = (game.players && game.currentSpeaker != null) ? game.players[game.currentSpeaker] : null;
    if (!cur) return '';
    const sheriffP = (game.sheriffPos && !game.sheriffBadgeTorn) ? game.players.find(p => p.position === game.sheriffPos) : null;
    const dir = (sheriffP && sheriffP.alive) ? game.sheriffDirection : game.speechDir;
    const txt = dir === 'right' ? '逆时针（号位递减）' : '顺时针（号位递增）';
    return '\n【本轮白天发言顺序】：从 ' + cur.position + '号位 ' + cur.name + ' 开始，按【' + txt + '】依次发言，你说完即轮到该方向的下一位存活玩家。';
  }
  // 警长竞选发言顺序说明（首位随机，其余按顺时针号位递增）
  function getSheriffSpeechOrderNote() {
    if (!game) return '';
    return '\n【警长竞选发言顺序】：首位随机抽取，其余上警玩家按【顺时针（号位递增）】依次发言。';
  }

  // 按字符数软上限裁剪文本（保留最近的部分），避免长对局把提示词撑爆
  function capTextByChars(text, maxChars) {
    const s = String(text == null ? '' : text);
    const max = Math.max(500, Number(maxChars) || 6000);
    if (s.length <= max) return s;
    return '…（更早的记录已省略，以下为最近 ' + max + ' 字）\n' + s.slice(-max);
  }

  // ========== 通用号位解析 / 守卫守护（12人场扩展） ==========
  const WOLF_CN_NUM = { '一': 1, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6, '七': 7, '八': 8, '九': 9, '十': 10, '十一': 11, '十二': 12 };
  function wolfPosFromStr(v) {
    if (v == null) return 0;
    const s = String(v).trim();
    if (/^\d+$/.test(s)) return parseInt(s, 10) || 0;
    return WOLF_CN_NUM[s] || 0;
  }
  // 从 AI 输出中解析 `TAG: [号位]`（支持 1~12 阿拉伯/中文数字；解析不到返回 -1）
  function parseWolfTargetPos(res, tag) {
    const m = String(res == null ? '' : res).match(new RegExp(tag + '[：:]\\s*[\\[【（(]?\\s*(\\d{1,2}|[一二三四五六七八九十]{1,3})\\s*[\\]】）)]?', 'i'));
    if (!m || !m[1]) return -1;
    return wolfPosFromStr(m[1]);
  }
  // 守卫守护：狼刀目标若被守护，当晚免疫（狼队与其他人不可见，仅隐藏记录）
  function applyGuardProtection() {
    if (!game || !game.nightKill) return false;
    if (game.guardProtectedPos !== game.nightKill.position) return false;
    const guard = game.players.find(p => p.role === '守卫');
    addHiddenThought('🛡️ 守卫成功守护了 ' + game.nightKill.position + '号位 ' + game.nightKill.name + '，狼刀被守护之力化解，今晚这一刀落空。', guard ? guard.position : 0);
    game.nightKill = null;
    return true;
  }

  // ========== 夜晚流程模拟 ==========
  function runNightSequence() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    stepGuardAction();
  }

  // 步骤 0：守卫行动（守护目标当晚免疫狼刀；可自守；不能连续两晚守护同一人；6/9人场自动跳过）
  function stepGuardAction(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const token = (game.nightToken = (game.nightToken || 0) + 1);
    game.nightStep = 'guard';
    game.guardProtectedPos = null;

    const guard = game.players.find(p => p.role === '守卫');
    if (!guard) { stepSeerAction(); return; }
    if (!guard.alive) {
      addHiddenThought('🛡️ 守卫已出局，本晚无人守护。', guard.position);
      setTimeout(() => { if (isSessionValid(session) && game.nightToken === token) stepSeerAction(); }, 700);
      return;
    }
    const validTargets = game.players.filter(p => p.alive && p.position !== game.guardLastPos);
    if (!validTargets.length) { stepSeerAction(); return; }

    if (guard.isUser) {
      addGameLog('🛡️ 守卫请行动');
      addGameLog('请点击玩家头像选择今晚守护目标（可自守，不能连续两晚守护同一人）', false);
      game.pickMode = 'guard';
      game.pick.idx = null;
      renderGameUI();
      setControlArea('');
      saveGameRecord();
      return;
    }

    addGameLog('⏳ AI 守卫正在思考守护目标...');
    const config = loadConfig();
    const overview = getGamePublicOverview(guard);
    const history = getPlayerHistoryContext(guard);
    const lastT = game.guardLastPos ? game.players.find(p => p.position === game.guardLastPos) : null;
    const lastGuardName = lastT ? (lastT.position + '号位 ' + lastT.name) : '无';
    const targetList = validTargets.map(p => p.position + '号位(' + p.name + (p.isUser ? '，主角本人' : '') + ')').join('、');

    const prompt = '你正在扮演第' + game.day + '天夜晚的守卫（' + guard.position + '号位 ' + guard.name + '）。' + overview + '\n\n【场上历史公开发言与公告】：\n' + history + '\n\n【守卫规则】：\n1. 每晚守护 1 名存活玩家（含自己），被守护者当晚免疫狼刀。\n2. 不能连续两晚守护同一人：你上一晚守护过 ' + lastGuardName + '（今晚不可再守TA）。\n3. 你守护过谁属于你的隐私，绝不能通过公开发言让别人反推出来。\n可选守护目标：' + targetList + '\n\n【守卫思考与守护决策指引】：\n1. 你完全不知道其他玩家的真实身份，必须结合白天发言、狼刀规律与逻辑推理，判断“今晚狼人最可能刀谁”，去守护这个最危险/最关键的人（例如明面上的神职、被抿出好身份的强玩家、或你自己认为会被刀的玩家）。\n2. 这是一场朋友间狼人杀桌游，结合人际关系与你的人设思考守护倾向。\n3. 在<thinking>中输出深度完整的思考思维链，在<GUARD_ACTION>中输出守护目标号位。\n\n格式必须为：\n<thinking>\n守卫思考内容...\n</thinking>\n<GUARD_ACTION>\nGUARD_PROTECT: [被守护玩家的号位数字]\n</GUARD_ACTION>';

    apiChat([
      { role: 'system', content: '你是狼人杀守卫。你只知道自己的身份与守护历史，必须结合公开发言推理狼队刀法，严禁开天眼。严格输出思考与守护格式。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000 }).then(res => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      const parsedG = parseWolfSpeechResponse(res);
      addHiddenThought(parsedG.thought || '正在推演今晚狼队最可能下刀的人，评估守护收益。', guard.position);
      const pos = parseWolfTargetPos(res, 'GUARD_PROTECT');
      let target = pos > 0 ? game.players.find(p => p.position === pos && p.alive) : null;
      if (target && target.position === game.guardLastPos) target = null;
      if (!target) target = validTargets[Math.floor(Math.random() * validTargets.length)];
      game.guardProtectedPos = target.position;
      game.guardLastPos = target.position;
      addHiddenThought('🛡️ 守卫守护了 ' + target.name + '（' + target.position + '号位），狼刀若命中TA将被化解。', guard.position);
      saveGameRecord();
      stepSeerAction();
    }).catch(err => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      handleAiFailure('AI守卫思考', err, (attemptNo || 1), (n) => stepGuardAction(n), () => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        const vt = game.players.filter(p => p.alive && p.position !== game.guardLastPos);
        if (!vt.length) { stepSeerAction(); return; }
        const t = vt[Math.floor(Math.random() * vt.length)];
        game.guardProtectedPos = t.position;
        game.guardLastPos = t.position;
        addHiddenThought('🛡️ 守卫守护了 ' + t.name + '（' + t.position + '号位），狼刀若命中TA将被化解。', guard.position);
        saveGameRecord();
        stepSeerAction();
      });
    });
  }

  // 步骤 1：预言家行动
  function stepSeerAction(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const token = (game.nightToken = (game.nightToken || 0) + 1);
    game.nightStep = 'seer';

    const seer = game.players.find(p => p.role === '预言家');
    if (seer && seer.isUser && seer.alive) {
      // 所有存活对手都已查验过时没有任何可点选目标：必须自动跳过，否则控制区为空、头像不可点，夜晚死锁
      const hasTarget = game.players.some(p => p.alive && !p.isUser && !game.seerChecked[p.position]);
      if (!hasTarget) {
        game.pickMode = null;
        addGameLog('🔮 所有存活玩家都已查验过，本晚无可查验目标，预言家跳过');
        saveGameRecord();
        setTimeout(() => { if (isSessionValid(session) && game.nightToken === token) stepWolfAction(); }, 700);
        return;
      }
      addGameLog('🔮 预言家请行动');
      addGameLog('请点击玩家头像选择查验目标', false);
      game.pickMode = 'seer';
      game.pick.idx = null;
      renderGameUI();
      setControlArea('');
      saveGameRecord();
      return;
    }
    
    addGameLog('⏳ AI 预言家正在思考查验目标...');
    if (!seer || !seer.alive) {
      setTimeout(() => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        stepWolfAction();
      }, 1500);
      return;
    }

    const config = loadConfig();
    const overview = getGamePublicOverview(seer);
    const history = getPlayerHistoryContext(seer);
    const aliveOthers = game.players.filter(p => p.alive && p.position !== seer.position).map(p => `${p.position}号位(${p.name})`).join('、');

    const checkedList = Object.keys(game.seerChecked).map(posStr => {
      const pos = parseInt(posStr);
      const target = game.players.find(p => p.position === pos);
      const isWolf = target && target.role === '狼人';
      const res = target ? (isWolf ? '狼人(查杀)' : '好人(金水)') : '未知';
      return `${pos}号位(${target ? target.name : ''}${target?.isUser ? '，主角本人' : ''})：${res}`;
    });
    const checkedInfo = checkedList.length > 0 ? `\n【你过往的查验结果】：\n${checkedList.join('\n')}` : '\n【你过往的查验结果】：今晚是第一夜，尚无查验历史';

    const prompt = `你正在扮演第${game.day}天夜晚的预言家（${seer.position}号位 ${seer.name}）。${overview}${checkedInfo}\n\n【场上历史公开发言与公告（你的过往<thinking>对你可见，其他玩家的思考对你不可见）】：\n${history}\n\n可选查验目标：${aliveOthers}\n\n【预言家思考与验人决策指引】：\n1. 除你已知查验的目标外，你对其他玩家的真实身份完全未知，严禁开天眼！结合白天发言疑点进行逻辑推理。\n2. 深刻明白这只是一场朋友间的狼人杀桌游，结合人际关系与微信聊天进行思考。\n3. 在<thinking>中必须输出深度完整的思考思维链，在<SEER_ACTION>中输出查验目标号位。\n\n格式必须为：\n<thinking>\n预言家思考内容...\n</thinking>\n<SEER_ACTION>\nSEER_CHECK: [被验玩家的号位数字]\n</SEER_ACTION>`;

    apiChat([
      { role: 'system', content: '你是狼人杀预言家。你只知道自己的身份和查验历史，结合游戏认知、角色性格与人际关系进行判断，严禁开天眼。严格输出思考与查验格式。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000 }).then(res => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      const mTh = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
      const thought = mTh ? mTh[1].trim() : res.replace(/<SEER_ACTION>[\s\S]*?<\/SEER_ACTION>/i, '').trim();
      addHiddenThought(thought || '正在推演场上身份并选择查验目标。', seer.position);
      let targetPos = parseWolfTargetPos(res, 'SEER_CHECK');
      if (targetPos < 0) targetPos = 0;
      if (!targetPos) {
        const others = game.players.filter(p => p.alive && p.position !== seer.position);
        if (others.length) targetPos = others[Math.floor(Math.random() * others.length)].position;
      }
      game.seerChecked[targetPos] = true;
      saveGameRecord();
      stepWolfAction();
    }).catch(err => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      handleAiFailure('AI预言家思考', err, (attemptNo || 1), (n) => stepSeerAction(n), () => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        const others = game.players.filter(p => p.alive && p.position !== seer.position);
        if (others.length) {
          const t = others[Math.floor(Math.random() * others.length)];
          game.seerChecked[t.position] = true;
          addHiddenThought('（AI调用失败，预言家随机选择了 ' + t.position + '号位 ' + t.name + ' 进行查验）', seer.position);
          addGameLog('🔮 预言家已完成查验', false);
        }
        saveGameRecord();
        stepWolfAction();
      });
    });
  }

  // 步骤 2：狼人行动
  function stepWolfAction(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const token = (game.nightToken = (game.nightToken || 0) + 1);
    game.nightStep = 'wolf';

    const wolves = game.players.filter(p => p.role === '狼人' && p.alive);
    if (wolves.length === 0) {
      game.nightKill = null;
      stepWitchAction();
      return;
    }
    const userWolf = wolves.find(p => p.isUser);
    if (userWolf) {
      // 后台继续：若狼队友密谋内容已生成过（玩家此前不在界面），直接恢复刀人操作界面，不重复调用 AI
      if (game.wolfMateChatDone) {
        const mate = game.players.find(p => p.role === '狼人' && !p.isUser && p.alive) || null;
        showWolfKillSelection(game.wolfMateChatText || '', mate);
        return;
      }
      initWolfTeamDiscussion();
      return;
    }
    const config = loadConfig();
    addGameLog('⏳ AI 狼人团队正在密谋刀人决策与战术部署...');
    const plist = game.players.map(p => `${p.position}号位: ${p.name}（状态: ${p.alive ? '存活' : '已出局'}${(game.players.length >= 12 && game.sheriffPos === p.position && !game.sheriffBadgeTorn) ? '，警长🎖️' : ''}${p.isUser ? '，主角本人' : ''}）`).join('\n');
    const leadWolf = wolves[0];
    const history = getPlayerHistoryContext(leadWolf);
    const wolvesPersona = wolves.map(w => `${w.position}号位 ${w.name}: ${getPlayerPersonalityPrompt(w)}`).join('\n');
    const wolfBoardDesc = game.players.length >= 12 ? '4狼人、4村民、1预言家、1女巫、1猎人、1守卫（守卫可能守护狼刀目标，导致空刀）' : game.players.length >= 9 ? '3狼人、3村民、1预言家、1女巫、1猎人' : '2狼人、2村民、1预言家、1女巫';
    const wolfWinRule = game.players.length >= 9 ? '狼人需屠边：村民全部出局（屠民）或神职全部出局（屠神）即获胜' : '狼人需屠城';

    const failedKillNote = getWolfFailedKillNote();
    const prompt = `你正在扮演第${game.day}天夜晚的狼人团队（存活狼人：${wolves.map(w => `${w.position}号位 ${w.name}`).join('、')}）。\n本局玩家列表：\n${plist}\n规则：${wolfBoardDesc}。女巫仅首夜可以自救，其余夜晚不可自救。${wolfWinRule}。${failedKillNote}\n\n【当前存活狼人的人设立场】：\n${wolvesPersona}\n\n【狼队视野限制与铁律】：\n1. 狼人仅知晓存活狼队友，好人具体身份完全未知！严禁开天眼！根据发言抿神。\n2. 这是一场熟人间狼人杀桌游，刀人淘汰只是游戏出局，在密谋中充分结合人际关系拉扯。\n3. 在<thinking>中输出心路分析；在<private>中输出密谋对话；在<WOLF_ACTION>中输出击杀号位。\n\n输出格式必须严格为：\n<thinking>\n${wolves.map(w => `【${w.position}号位 ${w.name} 密谋思考】：分析今晚要刀谁。`).join('\n')}\n</thinking>\n<private>\n🐺 [第${game.day}夜 狼队密谋] 带有角色人设口吻的商讨发言\n</private>\n<WOLF_ACTION>\nWOLF_KILL: [被刀玩家的号位数字]\nTACTIC_LEAP: [悍跳预言家的狼人号位，无填0]\nTACTIC_CHARGE: [冲锋狼人号位，无填0]\nTACTIC_HOOK: [倒钩狼人号位，无填0]\n</WOLF_ACTION>`;

    apiChat([
      { role: 'system', content: '你是狼人团队。在遵守底牌规则的基础上，必须忠实代入每个角色的性格、人设口癖及角色间情感态度。严禁开天眼。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000, timeout: 70000 }).then(res => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      const mTh = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
      const thought = mTh ? mTh[1].trim() : '';
      if (thought) addHiddenThought(thought, leadWolf.position);

      const mPriv = res.match(/<private>([\s\S]*?)<\/private>/i);
      const privMsg = mPriv ? mPriv[1].trim() : `🐺 [第${game.day}夜] 狼队已达成夜间刀人共识。`;
      addWolfPrivateLog(privMsg, leadWolf.position);
      
      {
        const normT = (v) => (v > 0 ? v : 0);
        game.aiWolfTactics = {
          leap: normT(parseWolfTargetPos(res, 'TACTIC_LEAP')),
          charge: normT(parseWolfTargetPos(res, 'TACTIC_CHARGE')),
          hook: normT(parseWolfTargetPos(res, 'TACTIC_HOOK'))
        };
      }

      let killPos = parseWolfTargetPos(res, 'WOLF_KILL');
      if (killPos < 0) killPos = 0;
      if (!killPos) {
        const aliveList = game.players.filter(p => p.alive);
        if (aliveList.length) killPos = aliveList[Math.floor(Math.random() * aliveList.length)].position;
      }
      game.nightKill = killPos > 0 ? game.players.find(p => p.position === killPos && p.alive) : null;
      game.lastWolfKillPos = killPos > 0 ? killPos : 0;
      game.lastWolfKillDied = false;
      applyGuardProtection();
      saveGameRecord();
      stepWitchAction();
    }).catch(err => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      handleAiFailure('AI狼队思考', err, (attemptNo || 1), (n) => stepWolfAction(n), () => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        const aliveList = game.players.filter(p => p.alive);
        const t = aliveList.length ? aliveList[Math.floor(Math.random() * aliveList.length)] : null;
        game.nightKill = t || null;
        game.lastWolfKillPos = t ? t.position : 0;
        game.lastWolfKillDied = false;
        addWolfPrivateLog('🐺 [狼队击杀指令] 因AI调用失败，狼队随机选择了 ' + (t ? (t.name + '（' + t.position + '号位）') : '空刀'), leadWolf.position);
        applyGuardProtection();
        saveGameRecord();
        stepWitchAction();
      });
    });
  }

  function initWolfTeamDiscussion(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const token = (game.nightToken = (game.nightToken || 0) + 1);
    game.nightStep = 'wolf';

    const wolfMate = game.players.find(p => p.role === '狼人' && !p.isUser && p.alive);
    const isFirstNight = (game.day === 1);
    if (wolfMate) {
      addGameLog(`⏳ 狼队友（${wolfMate.position}号位 ${wolfMate.name}）正在商讨夜间战术...`);
      setControlArea(`<div style="text-align:center;padding:6px;color:#fff;">狼队友 ${wolfMate.name} 正在商议中...</div>`);
      const config = loadConfig();
      const overview = getGamePublicOverview(wolfMate);
      const history = getPlayerHistoryContext(wolfMate);
      const prompt = `你正在扮演第${game.day}天夜晚的AI狼人（${wolfMate.position}号位 ${wolfMate.name}），你的狼队友正是玩家本人。${overview}\n历史记录：\n${history}${getWolfFailedKillNote()}\n\n【提示】：请完全代入你的身份人设、口癖以及对玩家的情感态度，在<thinking>中必须写出严密的战术思考，并在<private>中以你的专属口吻向玩家狼队友发起密谋建议（40~80字，口语化自然）：\n<thinking>内部战术思考</thinking>\n<private>对玩家狼队友的密谋密语</private>`;
      
      apiChat([
        { role: 'system', content: '你是狼人杀中的狼队友。必须完全代入角色性格、口吻和对主角的态度来和玩家进行狼队夜间密谋，必须包含thinking思考。' },
        { role: 'user', content: prompt }
      ], config, { maxTokens: 3000 }).then(res => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        let thought = '';
        let privSpeech = '';
        const mTh = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
        if (mTh) thought = mTh[1].trim();
        const mPr = res.match(/<private>([\s\S]*?)<\/private>/i);
        if (mPr) privSpeech = mPr[1].trim();
        else {
          const mSp = res.match(/<speech>([\s\S]*?)<\/speech>/i);
          if (mSp) privSpeech = mSp[1].trim();
          else privSpeech = res.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
        }
        privSpeech = privSpeech.replace(/【思考原因】/g, '').replace(/【公开发言】/g, '').replace(/<\/?thinking>/gi, '').replace(/<\/?private>/gi, '').replace(/<\/?speech>/gi, '').trim();
        if (!privSpeech) privSpeech = isFirstNight ? '今晚我们要怎么打配合？你打算跳预言家还是我来跳？' : '今晚怎么说，你觉得刀谁最稳？';
        if (!thought) thought = `今晚我和玩家队友必须统一刀口，并规划好白天各自的站边路线与发言分工。`;
        addHiddenThought(thought, wolfMate.position);
        addWolfPrivateLog(`[${wolfMate.position}号位 ${wolfMate.name}]: ${privSpeech}`, wolfMate.position);
        game.wolfMateChatDone = true;
        game.wolfMateChatText = privSpeech;
        saveGameRecord();
        renderWolfTacticsSelection(privSpeech, wolfMate);
      }).catch(err => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        handleAiFailure('AI狼队友思考', err, (attemptNo || 1), (n) => initWolfTeamDiscussion(n), () => {
          if (!isSessionValid(session) || game.nightToken !== token) return;
          const fbSpeech = '今晚怎么刀？我建议先刀威胁最大的，你定方向。';
          addWolfPrivateLog('[' + wolfMate.position + '号位 ' + wolfMate.name + ']: ' + fbSpeech, wolfMate.position);
          game.wolfMateChatDone = true;
          game.wolfMateChatText = fbSpeech;
          saveGameRecord();
          showWolfKillSelection(fbSpeech, wolfMate);
        });
      });
    } else {
      game.wolfMateChatDone = true;
      game.wolfMateChatText = '';
      saveGameRecord();
      renderWolfTacticsSelection('你是场上唯一存活的狼人，请规划发言战术并选择击杀目标。', null);
    }
  }

  // 按夜晚阶段选择狼人击杀界面（首夜战术选择 / 后续夜晚直接选刀）
  function showWolfKillSelection(speechText, wolfMate) {
    renderWolfTacticsSelection(speechText, wolfMate);
  }

  function renderWolfTacticsSelection(speechText, wolfMate) {
    const tacticTips = {
      '悍跳': '提醒AI在发言阶段跳预言家，和真预言家搏力度',
      '冲锋': '让AI在发言阶段坚定站边悍跳狼，使劲打站真预的好人，帮狼队冲票',
      '倒钩': '让AI在发言阶段表面上站边真预言家，假装打自己的狼队友，把自己包装成好人'
    };
    const userTacticTips = {
      '悍跳': '告诉AI自己会跳预言家，需要AI配合打冲锋或倒钩',
      '冲锋': '告诉AI自己会坚定冲锋，帮AI冲票',
      '倒钩': '告诉AI自己会表面站边好人倒钩，卖队友保自身'
    };

    game.tactics = { ai: '', user: '', custom: '' };

    setControlArea(`
      <div style="background:var(--ubp-card-2);padding:10px;border-radius:8px;">
        <div style="font-size:12px;font-weight:bold;color:#FFD700;margin-bottom:4px;">安排AI队友战术（单选）：</div>
        <div style="display:flex;gap:6px;margin-bottom:8px;">
          <button class="ubp-btn tactic-btn" data-type="ai" data-val="悍跳" title="${tacticTips['悍跳']}" style="flex:1;font-size:12px;padding:6px 0;">悍跳</button>
          <button class="ubp-btn tactic-btn" data-type="ai" data-val="冲锋" title="${tacticTips['冲锋']}" style="flex:1;font-size:12px;padding:6px 0;">冲锋</button>
          <button class="ubp-btn tactic-btn" data-type="ai" data-val="倒钩" title="${tacticTips['倒钩']}" style="flex:1;font-size:12px;padding:6px 0;">倒钩</button>
        </div>
        <div style="font-size:12px;font-weight:bold;color:#4CAF50;margin-bottom:4px;">安排我的战术（单选，不能与AI重复）：</div>
        <div style="display:flex;gap:6px;margin-bottom:8px;">
          <button class="ubp-btn tactic-btn" data-type="user" data-val="悍跳" title="${userTacticTips['悍跳']}" style="flex:1;font-size:12px;padding:6px 0;">悍跳</button>
          <button class="ubp-btn tactic-btn" data-type="user" data-val="冲锋" title="${userTacticTips['冲锋']}" style="flex:1;font-size:12px;padding:6px 0;">冲锋</button>
          <button class="ubp-btn tactic-btn" data-type="user" data-val="倒钩" title="${userTacticTips['倒钩']}" style="flex:1;font-size:12px;padding:6px 0;">倒钩</button>
        </div>
        <div style="display:flex;gap:6px;">
          <input id="wolf-custom-input" class="ubp-fieldinput" type="text" placeholder="补充具体战术细节或指令..." style="flex:1;">
          <button data-ubp-act="submit-wolf-tactics" class="ubp-btn primary" style="padding:0 12px;">确定战术并选择击杀目标</button>
        </div>
      </div>
    `);

    sheet?.querySelectorAll('.tactic-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const type = btn.dataset.type;
        const val = btn.dataset.val;
        const otherType = type === 'ai' ? 'user' : 'ai';
        if (game.tactics[otherType] === val) {
          showToast('AI战术与用户战术不能重复选择！');
          return;
        }
        if (game.tactics[type] === val) {
          game.tactics[type] = '';
        } else {
          game.tactics[type] = val;
        }
        sheet?.querySelectorAll('.tactic-btn').forEach(b => {
          const t = b.dataset.type;
          const v = b.dataset.val;
          if (game.tactics[t] === v) {
            b.style.borderColor = 'var(--ubp-accent)';
            b.style.background = 'rgba(139,92,246,0.2)';
          } else {
            b.style.borderColor = 'transparent';
            b.style.background = '';
          }
