  function renderWolfLaterNightSelection(speechText, wolfMate) {
    game.pickMode = 'wolf';
    game.pick.idx = null;
    renderGameUI();
    setControlArea(`
      <div style="background:var(--ubp-card-2);padding:10px;border-radius:8px;text-align:center;">
        <div style="font-size:12px;color:#C084FC;margin-bottom:6px;font-weight:600;">🐺 ${wolfMate ? `狼队友密谋建议："${speechText}"` : '独狼行动'}</div>
        <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">请点击上方玩家头像选择今晚击杀目标（可刀自己或队友），或直接跳过击杀</div>
        <button data-ubp-act="night-skip" class="ubp-btn" style="padding:6px 16px;">跳过击杀</button>
      </div>
    `);
  }

  // 步骤 3：女巫行动
  function stepWitchAction(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const token = (game.nightToken = (game.nightToken || 0) + 1);
    game.nightStep = 'witch';

    const witch = game.players.find(p => p.role === '女巫');
    if (witch && witch.isUser && witch.alive) {
      renderWitchUserInteraction();
      return;
    }

    addGameLog('⏳ AI 女巫正在思考用药决策...');
    if (!witch || !witch.alive) {
      setTimeout(() => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        finishNightAndStartDay();
      }, 1500);
      return;
    }

    const config = loadConfig();
    const overview = getGamePublicOverview(witch);
    const history = getPlayerHistoryContext(witch);
    const hasAntidote = !game.witchUsedAntidote;
    const hasPoison = !game.witchUsedPoison;
    const victim = game.nightKill;
    const isWitchVictim = victim && victim.position === witch.position;
    const victimInfo = hasAntidote ? (victim ? `${victim.position}号位 ${victim.name}` : '无人中刀') : '未知（解药已用，失去刀口视野）';
    const aliveAll = game.players.filter(p => p.alive).map(p => `${p.position}号位(${p.name})`).join('、');

    let specialVictimNote = '';
    if (victim && victim.isUser && hasAntidote) {
      specialVictimNote = `\n\n⚠️【重要提示：今晚中刀的是主角本人（${victim.position}号位 我）！】\n你对主角的身份与态度为：${witch.name} 对主角。若你深爱主角（如母亲、恋人、至亲），看到主角被刀必然情感泛滥、毫不犹豫必定选择使用解药救下TA！`;
    }
    if (isWitchVictim && hasAntidote && game.day === 1) {
      specialVictimNote += `\n\n🔥【紧急状况：你自己中刀！】本局规则：女巫首夜可以自救。你可以用解药自救（WITCH_SAVE: YES），也可以放弃自救保留解药。`;
    }
    if (isWitchVictim && game.day !== 1 && hasPoison) {
      specialVictimNote += `\n\n🔥🔥【紧急状况：你自己中刀出局！】本局规则：女巫仅首夜可以自救，后续夜晚中刀不可自救。你必须果决盲毒带人，从存活玩家中带走最有嫌疑的玩家！`;
    }

    const prompt = `你正在扮演第${game.day}天夜晚的女巫（${witch.position}号位 ${witch.name}）。${overview}\n\n【场上历史公开发言与公告】：\n${history}\n\n解药状态：${hasAntidote ? '可用' : '已用'}；毒药状态：${hasPoison ? '可用' : '已用'}\n今晚死者视野：${victimInfo}\n存活玩家可选：${aliveAll}${specialVictimNote}\n\n【女巫决策与人设融合铁律】：\n1. 你必须以女巫的身份服务好人阵营胜利，但你的用药心理与决断必须【深深烙印你的人设立场】！\n2. 这是一场桌游狼人杀，深知出局绝非真正死亡，用药结合人际关系与游戏逻辑思考。\n3. 必须包含完整的<thinking>推演，格式必须为：\n<thinking>\n女巫深度用药思考...\n</thinking>\n<WITCH_ACTION>\nWITCH_SAVE: [YES或NO]\nWITCH_POISON: [被毒玩家的号位数字，不用填0]\n</WITCH_ACTION>`;

    apiChat([
      { role: 'system', content: '你是狼人杀女巫。在尊重底牌规则下，必须严格遵从角色性格与情感态度来进行用药决断。严格输出思考与用药格式。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000 }).then(res => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      const mTh = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
      const thought = mTh ? mTh[1].trim() : res.replace(/<WITCH_ACTION>[\s\S]*?<\/WITCH_ACTION>/i, '').trim();
      addHiddenThought(thought || '正在分析今晚倒牌目标与用药性价比。', witch.position);

      const mSave = res.match(/WITCH_SAVE[：:]\s*[\[【（(]?\s*(YES|NO|是|否|救|不救)\s*[\]】）)]?/i);
      let isSaved = mSave && (mSave[1].toUpperCase() === 'YES' || mSave[1] === '是' || mSave[1] === '救');
      const canSaveKill = game.nightKill && (game.nightKill.position !== witch.position || game.day === 1);
      if (isSaved && hasAntidote && canSaveKill) { // 首夜可自救，其余夜晚不可自救
        game.witchUsedAntidote = true;
        game.witchSavedPos = game.nightKill.position;
        game.nightKill = null;
      }

      let poisonPos = parseWolfTargetPos(res, 'WITCH_POISON');
      if (poisonPos < 0) poisonPos = 0;

      if (isWitchVictim && hasPoison && poisonPos === 0 && game.nightKill && game.day !== 1) { // 后续夜晚不可自救 → 中刀当晚尽力盲毒带人
        const otherAlive = game.players.filter(p => p.alive && p.position !== witch.position);
        if (otherAlive.length > 0 && Math.random() < 0.9) {
          const mentioned = otherAlive.find(p => thought.includes(`${p.position}号`) || thought.includes(p.name));
          const chosen = mentioned || otherAlive[Math.floor(Math.random() * otherAlive.length)];
          poisonPos = chosen.position;
          addHiddenThought(`[女巫吃刀触发决绝盲毒带走 ${chosen.position}号位 ${chosen.name}]`, witch.position);
        }
      }

      if (hasPoison && poisonPos > 0) {
        let poisonedTarget = game.players.find(p => p.position === poisonPos && p.alive);
        if (poisonedTarget) {
          game.witchUsedPoison = true;
          poisonedTarget.alive = false;
          poisonedTarget.deathCause = 'poison';
          game.nightDeaths.push({ p: poisonedTarget, type: '毒杀' });
          renderGameUI();
        }
      }
      saveGameRecord();
      finishNightAndStartDay();
    }).catch(err => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      handleAiFailure('AI女巫思考', err, (attemptNo || 1), (n) => stepWitchAction(n), () => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        addHiddenThought('（AI调用失败，女巫本晚未使用任何药品）', witch.position);
        saveGameRecord();
        finishNightAndStartDay();
      });
    });
  }

  function renderWitchUserInteraction() {
    addGameLog('🧪 女巫请行动');
    addGameLog('请点击上方按钮进行操作', false);
    game.pickMode = null;
    game.pick.idx = null;
    renderGameUI();
    setControlArea('');
    showWitchMenu();
    saveGameRecord();
  }

  async function finishNightAndStartDay() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.nightStep = 'end'; // 夜晚流程已走完：恢复时不再重跑验人/刀人/用药
    game.nightToken = (game.nightToken || 0) + 1; // 使仍在途的旧夜晚回调失效

    if (game.nightKill && game.nightKill.alive) {
      game.nightKill.alive = false;
      game.nightKill.deathCause = 'kill';
      game.nightDeaths.push({ p: game.nightKill, type: '狼杀' });
      if (game.lastWolfKillPos && game.nightKill.position === game.lastWolfKillPos) game.lastWolfKillDied = true;
    }
    game.nightKill = null;

    if (game.nightDeaths.length) {
      const deadStrs = [...new Set(game.nightDeaths.map(d => `${d.p.name}（${d.p.position}号位）`))];
      game.nightResult = `昨夜，${deadStrs.join(' 和 ')} 死亡出局`;
    } else {
      game.nightResult = '昨夜是平安夜，无人死亡';
    }

    renderGameUI();
    saveGameRecord();

    // 警长出局：夜间出局的警长（含被毒）需要决定警徽移交或撕毁
    const nightDeadSheriff = (game.sheriffPos && !game.sheriffBadgeTorn)
      ? game.nightDeaths.map(d => d && d.p).find(p => p && p.position === game.sheriffPos)
      : null;
    if (nightDeadSheriff) {
      await resolveSheriffBadgeOnDeath(session, nightDeadSheriff);
      if (!isSessionValid(session)) return;
    }

    // 猎人技能：夜间出局的猎人（被毒死的除外）可以开枪带走 1 人
    await resolveHunterShots(session);
    if (!isSessionValid(session)) return;

    if (checkWin()) { endGame(); return; }
    startDay();
  }

  // ========== 游戏核心流程 ==========
  function startGame() {
    if (!game) return;
    const session = game.session;
    // 身份卡：按所选卡指定主角身份；多余狼人卡可邀请其他角色成为狼人；其余随机分配剩余身份
    const picked = Array.isArray(game.identityCards) ? game.identityCards.slice() : [];
    const mateNames = Array.isArray(game.wolfTeammateNames) ? game.wolfTeammateNames.slice() : [];
    const userIdx = (typeof game.userIndex === 'number' && game.userIndex >= 0) ? game.userIndex : -1;
    const wolfCardsRaw = picked.filter(k => k === 'wolf').length;
    const ownCardKey = picked.find(k => k !== 'wolf') || (wolfCardsRaw > 0 ? 'wolf' : null);
    const selfWolf = ownCardKey === 'wolf';
    // 狼人卡最多使用 2 张：自己 1 张 + 游戏对局中邀请的角色 1 张
    const wolfCards = selfWolf ? Math.min(2, wolfCardsRaw) : 0;
    const maxMates = Math.max(0, Math.min(1, wolfCards - (selfWolf ? 1 : 0)));
    const mateIdxList = [];
    for (const nm of mateNames) {
      if (mateIdxList.length >= maxMates) break;
      const idx = game.players.findIndex(p => !p.isUser && isNameMatch(p.name, nm));
      if (idx !== -1) mateIdxList.push(idx);
    }
    // 角色池：基础 2 狼 2 民 1 预言家 1 女巫；额外狼人卡把「民」优先替换成「狼人」
    // 角色池：6人场 2狼2民1预1女；9人场 3狼3民1预1女1猎人（身份卡可替换/追加）
    const boardN = (game.players || []).length;
    const pool = boardN >= 12
      ? ['狼人', '狼人', '狼人', '狼人', '民', '民', '民', '民', '预言家', '女巫', '猎人', '守卫']
      : boardN >= 9
        ? ['狼人', '狼人', '狼人', '民', '民', '民', '预言家', '女巫', '猎人']
        : ['狼人', '狼人', '民', '民', '预言家', '女巫'];
    const wolfNeed = (selfWolf ? 1 : 0) + mateIdxList.length;
    let wolfGuard = 0;
    while (pool.filter(r => r === '狼人').length < wolfNeed && wolfGuard++ < 8) {
      const vi = pool.indexOf('民');
      if (vi !== -1) { pool[vi] = '狼人'; continue; }
      break;
    }
    const takeRole = (role) => {
      const i = pool.indexOf(role);
      if (i === -1) return false;
      pool.splice(i, 1);
      return true;
    };
    const finalAssigned = {};
    const consumed = {};
    // 1) 主角选择的身份卡（非狼人卡；狼人卡见下）
    if (ownCardKey && userIdx >= 0) {
      const def = IDENTITY_CARD_TYPES.find(t => t.key === ownCardKey);
      if (def && takeRole(def.role)) {
        finalAssigned[userIdx] = def.role;
        consumed[ownCardKey] = (consumed[ownCardKey] || 0) + 1;
      }
    }
    // 2) 邀请的狼人队友（每消耗 1 张多余狼人卡）
    for (const idx of mateIdxList) {
      if (takeRole('狼人')) {
        finalAssigned[idx] = '狼人';
        consumed.wolf = (consumed.wolf || 0) + 1;
      }
    }
    // 3) 其余玩家随机分配剩余身份
    const restIdx = game.players.map((p, i) => i).filter(i => !(i in finalAssigned));
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    restIdx.forEach((idx, i) => { finalAssigned[idx] = pool[i] || '民'; });
    // 4) 消耗身份卡（主角所选卡 + 队友狼人卡）
    let consumeFailed = false;
    for (const key of Object.keys(consumed)) {
      if (!consumeIdentityCard(key, consumed[key])) consumeFailed = true;
    }
    if (consumeFailed) showToast('⚠️ 部分身份卡数量不足，已按现有卡牌开局');
    game.identityCards = [];
    game.wolfTeammateNames = [];
    game.players.forEach((p, idx) => {
      p.role = finalAssigned[idx] || '民';
      p.avatar = p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name));
    });
    game.day = 1;
    game.phase = 'night';
    game.replay = [];
    game.history = [];
    game.historyEntries = [];
    game.nightDeaths = [];
    game.witchSavedPos = null;
    game.guardProtectedPos = null;
    game.guardLastPos = null;
    game.lastWolfKillPos = 0;
    game.lastWolfKillDied = false;
    game.sheriffPos = null;
    game.sheriffStage = '';
    game.sheriffDone = false;
    game.sheriffCandidates = [];
    game.sheriffWithdrawn = [];
    game.sheriffVotes = {};
    game.sheriffDirection = '';
    game.sheriffBadgeTorn = false;
    game.isPkVote = false;
    game.pkCandidates = null;
    renderGameUI();
    
    const user = game.players[game.userIndex];
    if (user && user.isUser) {
      const cfgDesc = game.players.length >= 12 ? '4狼4民1预1女1猎1守' : game.players.length >= 9 ? '3狼3民1预1女1猎' : '2狼2民1预1女';
      addGameLog(`游戏开始，请确认自己的身份。场上配置：${cfgDesc} | 你的身份是：【${user.role}】`, false, null, '#EF4444');
    } else if (game.spectatorMode) {
      addGameLog('👁️ 你以上帝视角观战本局：全部身份与夜间行动均可见。', false, null, '#0EA5E9');
    }
    saveGameRecord();
    startNight();
  }

  function startNight() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.phase = 'night';
    game.nightKill = null;
    game.nightDeaths = [];
    game.witchAction = null;
    game.wolfMateChatDone = false;
    game.wolfMateChatText = '';
    game.guardProtectedPos = null;
    game.pickMode = null;
    game.pick = { idx: null };
    game.witchMenu = false;
    game.witchMenuReturn = false;
    game.isPkVote = false;
    game.pkCandidates = null;
    game.nightStep = 'guard'; // 夜晚从守卫开始（6/9人场无守卫会自动跳过）；恢复时按步骤续跑
    game.nightToken = (game.nightToken || 0) + 1;
    const statusEl = sheet?.querySelector('#game-status-text');
    if (statusEl) statusEl.textContent = `🐺 第${game.day}天 · 🌙 夜晚`;
    addGameLog(`🌙 第${game.day}天夜晚来临`, true);
    renderGameUI();
    saveGameRecord();
    runNightSequence();
  }

  // 天亮播报与首夜遗言（警长竞选结束后才公布死讯）
  async function announceDayAndDeaths() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.dayAnnounced = true;
    game.dawnDeaths = (game.nightDeaths || []).map(d => (d && d.p) ? d.p.position : 0).filter(Boolean);
    renderGameUI();
    addGameLog(`☀️ 第${game.day}天天亮，公告：${game.nightResult}`, true);
    saveGameRecord();
    const firstNightDeaths = game.day === 1 ? game.nightDeaths : [];
    if (firstNightDeaths.length) {
      addGameLog('💬 首夜出局玩家发表遗言：', true);
      for (const d of firstNightDeaths) {
        if (!isSessionValid(session)) return;
        await generateFinalWords(d.p);
      }
    }
    if (!isSessionValid(session)) return;
    game.nightDeaths = [];
  }

  // 警长竞选结束后的统一出口：先公布死讯（若尚未公布），再进入发言方向决定/正常发言
  function afterSheriffElection(goDirection) {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    const cont = () => {
      if (!isSessionValid(session) || game.phase !== 'day') return;
      if (goDirection && game.sheriffPos && !game.sheriffBadgeTorn) sheriffPickDirection();
      else beginDaySpeeches();
    };
    if (!game.dayAnnounced) {
      announceDayAndDeaths().then(() => {
        if (!isSessionValid(session) || game.phase !== 'day') return;
        cont();
      });
      return;
    }
    cont();
  }

  async function startDay() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.phase = 'day';
    game.pickMode = null;
    game.pick = { idx: null };
    game.witchMenu = false;
    game.witchMenuReturn = false;
    game.isPkVote = false;
    game.pkCandidates = null;
    game.dayAnnounced = false;
    hideActionPopup();
    const statusEl = sheet?.querySelector('#game-status-text');
    if (statusEl) statusEl.textContent = `🐺 第${game.day}天 · ☀️ 白天`;
    // 12人场首日：先进行警长竞选，竞选结束后才公布死讯
    if (game.day === 1 && game.players.length >= 12 && !game.sheriffDone && !game.sheriffPos && !game.sheriffBadgeTorn) {
      renderGameUI();
      saveGameRecord();
      startSheriffElection();
      return;
    }
    await announceDayAndDeaths();
    if (!isSessionValid(session)) return;
    beginDaySpeeches();
  }

  function beginDaySpeeches() {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    game.players.forEach(p => { p.hasSpoken = false; p.votedFor = null; });
    game.userDaySpeech = '';
    game.sheriffLeadDone = false;
    const sheriff = (game.sheriffPos && !game.sheriffBadgeTorn) ? game.players.find(p => p.position === game.sheriffPos) : null;
    if (sheriff && sheriff.alive && game.sheriffDirectionDay !== game.day) { sheriffPickDirection(); return; }
    let startIdx = -1;
    if (sheriff && sheriff.alive && game.sheriffDirection) {
      startIdx = sheriffNeighborStartIndex(sheriff.position, game.sheriffDirection);
      game.speechDir = '';
    } else {
      // 无警长：从当夜出局玩家之一的旁边开始，方向随机；平安夜则随机起点与方向
      const dayDir = Math.random() < 0.5 ? 'left' : 'right';
      const dayStep = dayDir === 'left' ? 1 : -1;
      const totalP = game.players.length;
      let anchorIdx = -1;
      const deadPositions = (game.dawnDeaths || []).filter(pos => game.players.some(x => x.position === pos));
      if (deadPositions.length) {
        const pos = deadPositions[Math.floor(Math.random() * deadPositions.length)];
        anchorIdx = game.players.findIndex(x => x.position === pos);
      } else {
        const aliveIdxs = game.players.map((p, i) => p.alive ? i : -1).filter(i => i >= 0);
        if (aliveIdxs.length) anchorIdx = aliveIdxs[Math.floor(Math.random() * aliveIdxs.length)];
      }
      if (anchorIdx >= 0) {
        for (let k = 1; k <= totalP; k++) {
          const idx = ((anchorIdx + dayStep * k) % totalP + totalP) % totalP;
          if (game.players[idx].alive) { startIdx = idx; break; }
        }
      }
      if (startIdx < 0) { startIdx = 0; while (startIdx < totalP && !game.players[startIdx].alive) startIdx++; }
      game.speechDir = dayDir;
    }
    if (startIdx < 0 || startIdx >= game.players.length) { endGame(); return; }
    game.currentSpeaker = startIdx;
    renderGameUI();
    const speechDirForLog = (sheriff && sheriff.alive && game.sheriffDirection) ? game.sheriffDirection : game.speechDir;
    const speechDirText = speechDirForLog === 'right' ? '逆时针（号位递减）' : '顺时针（号位递增）';
    const speechDirSource = (sheriff && sheriff.alive && game.sheriffDirection) ? '，警长决定从' + (game.sheriffDirection === 'left' ? '警左' : '警右') + '开始' : '';
    addGameLog(`💬 本轮从 ${game.players[game.currentSpeaker].position}号位 ${game.players[game.currentSpeaker].name} 开始，按【${speechDirText}】依次发言${speechDirSource}`, true);
    saveGameRecord();
    startSpeaking();
  }

  function startSpeaking() {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    const current = game.players[game.currentSpeaker];
    if (!current || !current.alive) { nextSpeaker(); return; }
    if (current.isUser) {
      setControlArea(`
        <div id="game-speak-area" style="display:flex;gap:4px;margin:6px 0;">
          <input id="game-speak-input" class="ubp-fieldinput" type="text" placeholder="输入你的发言..." style="flex:1;min-width:0;">
          <button data-ubp-act="game-speak" class="ubp-btn primary" style="padding:0 10px;">发言</button>
          <button data-ubp-act="game-speak-skip" class="ubp-btn" style="padding:0 10px;">跳过</button>
        </div>
      `);
      const input = sheet?.querySelector('#game-speak-input');
      if (input) input.focus();
    } else {
      setControlArea(`<div style="text-align:center;padding:6px;color:#fff;">${current.name} 正在思考...</div>`);
      generateAISpeech(current, () => {
        if (!isSessionValid(session) || game.phase !== 'day') return;
        current.hasSpoken = true;
        saveGameRecord();
        if (game.phase === 'day') nextSpeaker();
      });
    }
  }

  function nextSpeaker() {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    const area = sheet?.querySelector('#game-speak-area');
    if (area) area.style.display = 'none';
    const total = game.players.length;
    const sheriffOnBoard = (game.sheriffPos && !game.sheriffBadgeTorn) ? game.players.find(p => p.position === game.sheriffPos) : null;
    const dirNow = (sheriffOnBoard && sheriffOnBoard.alive) ? game.sheriffDirection : game.speechDir;
    const step = (dirNow === 'right') ? -1 : 1;
    let next = -1;
    for (let k = 1; k <= total; k++) {
      const idx = ((game.currentSpeaker + step * k) % total + total) % total;
      const cand = game.players[idx];
      if (cand && cand.alive && !cand.hasSpoken) { next = idx; break; }
    }
    if (next === -1) {
      addGameLog(`📢 发言结束，进入投票环节`, true);
      saveGameRecord();
      startVote();
    } else {
      game.currentSpeaker = next;
      saveGameRecord();
      startSpeaking();
    }
  }

  // ========== 狼人杀发言解析：严格区分「思考 / 公开发言」，公开发言里绝不允许残留隐蔽思考内容 ==========
  // 返回 { thought, speech }。兼容模型偷懒/截断导致的未闭合标签、旧版【思考原因】【公开发言】格式。
  function parseWolfSpeechResponse(res) {
    const raw = String(res == null ? '' : res);
    let thought = '';
    let speech = '';

    // 1) 思考：优先 <thinking>…</thinking>（闭合）；未闭合（多为输出被截断）则取到 <speech>/【公开发言】之前
    const mThought = raw.match(/<thinking>([\s\S]*?)<\/thinking>/i);
    if (mThought) {
      thought = mThought[1].trim();
    } else {
      const mAltThought = raw.match(/【思考原因】([\s\S]*?)(?=【公开发言】|<speech>|$)/i);
      if (mAltThought) thought = mAltThought[1].trim();
      else {
        const speechIdx = raw.search(/<speech>|【公开发言】/i);
        const openIdx = raw.search(/<thinking>/i);
        if (openIdx !== -1) {
          const endIdx = (speechIdx !== -1 && speechIdx > openIdx) ? speechIdx : raw.length;
          thought = raw.slice(openIdx, endIdx).replace(/<\/?thinking>/gi, '').replace(/<[^>]+>/g, '').trim();
        } else if (speechIdx > 0) {
          thought = raw.slice(0, speechIdx).replace(/<[^>]+>/g, '').trim();
        }
      }
    }

    // 2) 公开发言：优先 <speech>…</speech>；兼容【公开发言】；最后兜底为「原文剥离所有思考和私聊块」
    const mSpeech = raw.match(/<speech>([\s\S]*?)(?:<\/speech>|$)/i);
    if (mSpeech) {
      speech = mSpeech[1].trim();
    } else {
      const mAltSpeech = raw.match(/【公开发言】([\s\S]*?)$/i);
      if (mAltSpeech) {
        speech = mAltSpeech[1].trim();
      } else {
        speech = raw
          .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
          .replace(/<thinking>[\s\S]*$/gi, '')
          .replace(/<private>[\s\S]*?<\/private>/gi, '')
          .replace(/【思考原因】[\s\S]*?(?=【公开发言】|<speech>|$)/gi, '')
          .trim();
      }
    }

    // 3) 双重保险：公开发言里若混入了思考块/私聊块或裸标签，全部剜掉，防止泄露隐蔽思考
    speech = speech
      .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
      .replace(/<thinking>[\s\S]*$/gi, '')
      .replace(/<private>[\s\S]*?<\/private>/gi, '')
      .replace(/【思考原因】[\s\S]*?(?=【公开发言】|$)/gi, '')
      .replace(/<\/?(thinking|speech|private)>/gi, '')
      .replace(/【思考原因】|【公开发言】|【内心思考】|【隐蔽思考】/g, '')
      .replace(/[*_`~]/g, '')
      .trim();

    return { thought: thought, speech: speech };
  }

  // 公开发言完整收尾：输出被截断（半句/缺标点）时补一句自然结尾，避免半句话直接收尾
  function completeWolfSpeechLine(text, kind) {
    let s = String(text == null ? '' : text).trim();
    if (!s) return s;
    s = s.replace(/[，,、:：；;\-—…\s]+$/, '').trim();
    if (/[。！？!?…～~”"』」）)\]】]$/.test(s)) return s;
    const tail = kind === 'final'
      ? '，剩下的就交给你们继续推理了！'
      : kind === 'pk'
        ? '，请好人看清局势把票归对，别被狼人带节奏！'
        : '，这就是我目前看出来的疑点，后置位继续听发言。';
    return s + tail;
  }

  // ========== AI 发言生成 ==========
  function generateAISpeech(player, callback, attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;

    const config = loadConfig();
    const overview = getGamePublicOverview(player);
    const history = getPlayerHistoryContext(player);

    let tacticInstruction = '';
    if (player.role === '狼人') {
      if (game.tactics && (game.tactics.ai || game.tactics.user)) {
        tacticInstruction = `\n【狼队夜间商议战术要求】：\nAI狼队友战术是【${game.tactics.ai || '自由发挥'}】，玩家狼队友战术是【${game.tactics.user || '自由发挥'}】。用户战术指示：${game.tactics.custom || '无'}。\n你必须严格按照战术要求执行发言，不得擅自更改或违背。`;
      } else if (game.aiWolfTactics) {
        let roleTactic = '自由伪装配合';
        if (game.aiWolfTactics.leap === player.position) roleTactic = '悍跳预言家！报出假查验，攻击真预言家，全力争取好人信任！';
        else if (game.aiWolfTactics.charge === player.position) roleTactic = '冲锋站边！坚定支持悍跳狼队友，猛烈质疑真预言家，带节奏冲票！';
        else if (game.aiWolfTactics.hook === player.position) roleTactic = '倒钩好人！假意站边真预言家，通过表水和踩队友做高自身好人面！';
        tacticInstruction = `\n【狼队夜间商定的分工指引】：你的战术角色是【${roleTactic}】。请严格按分工进行公开发言。`;
      }
      const userWolfP = game.players[game.userIndex];
      if (userWolfP && userWolfP.role === '狼人' && !player.isUser && game.userDaySpeech) {
        tacticInstruction += `\n【狼队友（玩家本人）本轮公开发言中的战术指示】："${game.userDaySpeech}"\n（铁律：必须严格按玩家狼队友通过发言下达的战术指示行动与发言，不得违背或擅自更改）`;
      }
    } else if (player.role === '预言家') {
      const checkedDetails = Object.keys(game.seerChecked || {}).map(posStr => {
        const pos = parseInt(posStr);
        const target = game.players.find(p => p.position === pos);
        if (!target) return '';
        const isTargetWolf = target.role === '狼人';
        return `${target.position}号位 ${target.name}${target.isUser ? '（玩家主角本人）' : ''}：查验底牌真实为【${isTargetWolf ? '狼人（查杀）' : '好人（金水）'}】`;
      }).filter(Boolean);
      const seerRecordStr = checkedDetails.length > 0 ? checkedDetails.join('；') : '目前尚无查验历史';
      tacticInstruction = `\n【重要：你作为真预言家的夜间查验结果库】（此信息真实无误）：\n${seerRecordStr}\n【查验铁律】：如果上述查验结果表明某玩家为狼人，无论该玩家是否为主角（哪怕名字是“我”），TA也是货真价实的狼人！你在公开发言中若跳预言家报查验，必须明确如实通报该玩家为【狼人/查杀】，绝对严禁把拿了狼人牌的玩家错误称呼为好人或发金水！`;
    } else if (player.role === '女巫') {
      let witchInfo = `\n【你作为女巫的夜间用药情况】：解药${game.witchUsedAntidote ? '已用' : '未用'}，毒药${game.witchUsedPoison ? '已用' : '未用'}。`;
      if (game.witchSavedPos) {
        const savedP = game.players.find(p => p.position === game.witchSavedPos);
        if (savedP) witchInfo += `昨夜解药救下的是：${savedP.position}号位 ${savedP.name}（银水）。`;
      }
      tacticInstruction += witchInfo;
    }

    if (player.role === '守卫' || player.role === '猎人' || player.role === '民') tacticInstruction += getPlayerIdentitySystemContext(player);
    const wolfDayNote = (player.role === '狼人') ? getWolfFailedKillNote('day') : '';
    const prompt = `你正在扮演当前发言玩家：${player.position}号位 ${player.name}。\n你的真实身份是：${player.role}。\n${overview}${tacticInstruction}${getSpeechOrderNoteForAI()}\n\n【本局历史公开发言与思考记录】：\n${history}${wolfDayNote}\n\n【公开发言角色扮演与底牌指令】：\n1. 底牌原则：你必须尊重并全力为你所在的阵营（${player.role === '狼人' ? '狼人阵营' : '好人阵营'}）辩护和争取胜利，绝不公然放水认输！\n2. 人设要求：在<speech>中，必须【完全还原角色的说话语气、口癖、性格和神态】，用第一人称像真人一样说出口。积极与场上其他角色互动吐槽，结合你们的过往关系（见上文关系与社交记录）！\n3. 游戏认知：清楚这只是一场朋友间聚会的狼人杀推理桌游，严禁将游戏出局当成真实的死亡！\n4. 【核心强制铁律】：必须同时包含<thinking>思考</thinking>与<speech>公开发言</speech>两部分，严禁缺失思考内容！在<thinking>中必须详尽写出你作为${player.role}在此刻的心理推演、对场上谁可疑的研判与战术意图（逐条列出你对每位玩家发言的怀疑度与下一步战术）。【防全知铁律】只能使用自己的底牌、专属信息与公开信息推理，严禁开天眼提及任何未公开信息。\n5. 【公开发言完整性铁律】：公开发言必须是一段逻辑连贯、语意完整的表述，必须完整说完观点，闭合语义并自然收尾，严禁输出到一半戛然而止，绝对严禁以逗号或半句话直接结尾于</speech>！\n6. 【严格输出格式铁律】：只允许输出下面两个标签，且两个标签都必须【完整闭合】，标签前后不得有任何多余文字、解释或其它标签：\n<thinking>写出你作为${player.role}此刻的内部心理、角色间拉扯、为什么怀疑某人或如何演戏（必须有实质思考内容）</thinking>\n<speech>真正说出口的完整公开发言（口语化自然、长度自然可长可短，严禁包含动作描写或【公开发言】等标记，必须语义完整、自然收尾，严禁半句截断）</speech>\n严禁输出 <private>、<discussion> 等任何其它标签；严禁把 <thinking> 里的思考内容、心理活动或【思考原因】字样写进 <speech>；公开发言必须是完整收尾的一整段话。`;

    apiChat([
      { role: 'system', content: applyBoardIntro(config.prompt || DEFAULT_PROMPT) },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000, timeout: 70000 }).then(res => {
      if (!isSessionValid(session)) return;
      // 严格解析：思考归思考、公开发言归公开发言，兼容未闭合标签与旧格式
      const parsedSpeech = parseWolfSpeechResponse(res);
      let thought = parsedSpeech.thought;
      let speech = completeWolfSpeechLine(parsedSpeech.speech, 'day');

      if (!speech) speech = '我仔细听了前面的发言，觉得大家的疑点都不少，建议后置位多给些信息，我先过了。';

      if (!thought) {
        thought = `作为${player.position}号位（身份：${player.role}），我纵观前置位所有发言与当前局势：目前场上局势错综复杂，各位玩家表水与指控各执一词。我必须严守自身${player.role === '狼人' ? '狼队隐蔽伪装与引导抗推' : '好人阵营排狼坑'}立场，在公开发言中既要逻辑严谨、指出疑点，又要符合我的性格人设，不能露出破绽。`;
      }

      addHiddenThought(thought, player.position);
      addGameLog(`🗣️ ${player.name}（${player.position}号位）: <speech>${speech}</speech>`, true, player.position);
      saveGameRecord();
      callback();
    }).catch(err => {
      if (!isSessionValid(session)) return;
      handleAiFailure('发言生成', err, (attemptNo || 1), (n) => generateAISpeech(player, callback, n), () => {
        addHiddenThought('（发言连续5次生成失败，按默认内容处理）', player.position);
        addGameLog(`🗣️ ${player.name}（${player.position}号位）: <speech>我仔细听了前面的发言，觉得大家的疑点都不少，建议后置位多给些信息，我先过了。</speech>`, true, player.position);
        saveGameRecord();
        callback();
      });
    });
  }

  function showUserFinalWordsUI() {
    setControlArea(`
      <div style="font-weight:600;margin-bottom:6px;color:#fff;">💬 请发表你的遗言：</div>
      <div id="game-speak-area" style="display:flex;flex-direction:column;gap:8px;margin:6px 0;">
        <input id="game-speak-input" class="ubp-fieldinput" type="text" placeholder="输入你的遗言..." style="width:100%;">
        <button data-ubp-act="user-final-words" class="ubp-btn primary" style="width:100%;">发送遗言</button>
        <button data-ubp-act="user-final-words-skip" class="ubp-btn" style="width:100%;">跳过遗言</button>
      </div>
    `);
    const input = sheet?.querySelector('#game-speak-input');
    if (input) input.focus();
  }

  function generateFinalWords(player, attemptNo) {
    return new Promise((resolve) => {
      const session = game?.session;
      if (!isSessionValid(session)) { resolve(); return; }
      if (player.isUser) {
        game.resolvingFinalWords = resolve;
        showUserFinalWordsUI();
        return;
      }
      
      setControlArea(`<div style="text-align:center;padding:6px;color:#fff;">${player.name} 正在思考遗言...</div>`);
      
      const config = loadConfig();
      const overview = getGamePublicOverview(player);
      const history = getPlayerHistoryContext(player);
      const identityCtx = getPlayerIdentitySystemContext(player);
      const prompt = `你正在扮演刚出局的玩家发表出局遗言：${player.position}号位 ${player.name}，底牌是${player.role}。\n${overview}${identityCtx}\n\n【场上历史记录】：\n${history}\n\n【遗言核心要求】：\n1. 这只是一场聚会推理桌游，你只是在游戏中被刀/被毒/被投票淘汰出局、后续无法再发言了，【绝对不是真正死掉】！\n2. 严禁任何肉体死亡、流血、濒死断气或生离死别的沉重描写！\n3. 必须包含完整的<thinking>思考与<speech>公开发言，严禁缺失思考（【防全知铁律】只能依据公开信息与自己的底牌发言，严禁开天眼）！\n4. 请表现出真实桌游玩家出局后的态度（如懊悔、哭笑不得、吐槽凶手、给同伴打气或调侃某人），公开发言必须语意完整闭合，严禁半路截断（30-80字）；两个标签都必须完整闭合，只输出这两个标签，严禁输出任何其它标签，严禁把思考内容写进 <speech>：\n<thinking>遗言内部思考（深入复盘谁干掉了你或阵营后续）</thinking>\n<speech>符合性格的游戏出局完整公开发言</speech>`;

      apiChat([
        { role: 'system', content: '你是狼人杀出局玩家。清楚这只是桌游淘汰，严禁生离死别，必须输出思考与完整遗言。' },
        { role: 'user', content: prompt }
      ], config, { maxTokens: 3000 }).then(res => {
        if (!isSessionValid(session)) { resolve(); return; }
        const parsed = parseWolfSpeechResponse(res);
        let thought = parsed.thought;
        let speech = completeWolfSpeechLine(parsed.speech, 'final');
        if (!speech) speech = '没想到这一轮我被淘汰了，剩下的朋友们加油继续推理吧！';
        if (!thought) thought = `真没想到这么早就出局了，希望我的阵营同伴能看清局面赢下本局比赛。`;

        addHiddenThought(thought, player.position);
        addGameLog(`💬 ${player.name} 的遗言：<speech>${speech}</speech>`, true, player.position);
        setControlArea('');
        saveGameRecord();
        resolve();
      }).catch(err => {
        if (!isSessionValid(session)) { resolve(); return; }
        handleAiFailure('遗言生成', err, (attemptNo || 1), (n) => generateFinalWords(player, n).then(resolve), () => {
          addHiddenThought('（遗言连续5次生成失败，按默认内容处理）', player.position);
          addGameLog(`💬 ${player.name} 的遗言：<speech>没想到这一轮我被淘汰了，剩下的朋友们加油继续推理吧！</speech>`, true, player.position);
          saveGameRecord();
          setControlArea('');
          resolve();
        });
      });
    });
  }

  // ========== 投票环节 ==========
  // 有警长时：放逐投票前请求 AI 警长进行归票思考与归票发言（失败自动重试，最多 5 次）
  function generateSheriffVoteLead(callback, attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'vote') return;
    const sheriff = game.sheriffPos ? game.players.find(p => p.position === game.sheriffPos) : null;
    if (!sheriff || !sheriff.alive || game.sheriffBadgeTorn || sheriff.isUser) { if (typeof callback === 'function') callback(); return; }
    addGameLog('⏳ 警长 ' + sheriff.name + '（' + sheriff.position + '号位）正在思考归票...');
    const config = loadConfig();
    const overview = getGamePublicOverview(sheriff);
    const history = getPlayerHistoryContext(sheriff);
    const prompt = '现在是第' + game.day + '天的放逐投票环节，你是警长（' + sheriff.position + '号位 ' + sheriff.name + '），请在投票开始前发表归票发言：明确号召大家把票归给你认为最可疑的人（或说明你的投票倾向）。' + overview + getPlayerIdentitySystemContext(sheriff) + '\n\n【本局历史公开发言与公告】：\n' + history + '\n\n【警长归票发言要求】：\n1. 你是警长，拥有1.5票归票权，发言必须明确且有号召力：点出你最怀疑的号位与理由，号召好人跟你归票、不要分票。\n2. 【防全知铁律】只能依据自己的底牌与公开信息推理，严禁开天眼使用任何未公开信息。\n3. 必须输出完整<thinking>思考与完整<speech>发言，语义完整自然收尾，严禁半句截断：\n<thinking>归票思考（今天该归谁、怎么带动票型）</thinking>\n<speech>完整的警长归票发言（明确点名归票号位）</speech>';
    apiChat([
      { role: 'system', content: '你是狼人杀警长，正在发表归票发言。必须代入角色人设与底牌立场，严格输出思考与完整发言，严禁开天眼。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000 }).then(res => {
      if (!isSessionValid(session) || game.phase !== 'vote') return;
      const parsedL = parseWolfSpeechResponse(res);
      addHiddenThought(parsedL.thought || '正在思考今天的归票方向。', sheriff.position);
      const speech = completeWolfSpeechLine(parsedL.speech, 'day');
      addGameLog('🗣️ [警长归票] ' + sheriff.name + '（' + sheriff.position + '号位）: <speech>' + (speech || '请大家看清局势，跟我把票归到最可疑的号位，不要分票。') + '</speech>', true, sheriff.position);
      saveGameRecord();
      if (typeof callback === 'function') callback();
    }).catch(err => {
      if (!isSessionValid(session) || game.phase !== 'vote') return;
      handleAiFailure('警长归票发言', err, (attemptNo || 1), (n) => generateSheriffVoteLead(callback, n), () => {
        addHiddenThought('（归票发言连续5次生成失败，按默认归票处理）', sheriff.position);
        addGameLog('🗣️ [警长归票] ' + sheriff.name + '（' + sheriff.position + '号位）: <speech>请大家看清局势，跟我把票归到最可疑的号位，不要分票。</speech>', true, sheriff.position);
        saveGameRecord();
        if (typeof callback === 'function') callback();
      });
    });
  }

  function startVote() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.phase = 'vote';
    game.isPkVote = false;
    game.pkCandidates = null;
    game.pickMode = null;
    game.pick = { idx: null };
    const statusEl = sheet?.querySelector('#game-status-text');
    if (statusEl) statusEl.textContent = `🐺 第${game.day}天 · 🗳️ 投票`;
    const alive = game.players.filter(p => p.alive);
    if (alive.length <= 1) { endGame(); return; }
    saveGameRecord();
    const continuesVote = () => {
      if (!isSessionValid(session) || game.phase !== 'vote') return;
      const user = game.players[game.userIndex];
      if (user && user.alive) {
        addGameLog('🗳️ 投票环节：请点击玩家头像选择投票对象（可投自己或点击弃票）', false);
        game.pickMode = 'vote';
        game.pick.idx = null;
        renderGameUI();
        setControlArea('');
      } else {
        simulateAIVotes();
      }
    };
    // 有警长时：先请求 AI 警长进行归票思考并发表归票发言，再开始投票
    const leadSheriff = (game.sheriffPos && !game.sheriffBadgeTorn) ? game.players.find(p => p.position === game.sheriffPos) : null;
    if (leadSheriff && leadSheriff.alive && !leadSheriff.isUser && !game.sheriffLeadDone) {
      game.sheriffLeadDone = true;
      saveGameRecord();
      generateSheriffVoteLead(continuesVote);
      return;
    }
    continuesVote();
  }

  function startPkVote() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.phase = 'vote';
    game.isPkVote = true;
    game.pickMode = null;
    game.pick = { idx: null };
    // 进入 PK 决选投票：清空上一轮票型，避免平票玩家上一轮旧票被重复计入
    game.players.forEach(p => { if (p.alive) p.votedFor = null; });
    const statusEl = sheet?.querySelector('#game-status-text');
    if (statusEl) statusEl.textContent = `🐺 第${game.day}天 · 🗳️ PK投票`;
    
    const user = game.players[game.userIndex];
    const pkCands = game.pkCandidates || [];
    const isUserTied = user && user.alive && pkCands.some(cp => cp.position === user.position);
    // 除平票玩家外已无任何可投票的存活玩家：直接流票入夜，避免进度卡死
    const eligibleVoters = game.players.filter(p => p.alive && !pkCands.some(cp => cp.position === p.position));
    saveGameRecord();
    if (!eligibleVoters.length) {
      addGameLog('⚖️ 场上除平票玩家外已无可投票的存活玩家，本轮直接流票，无人出局。', true);
      setControlArea('');
      finishVote();
      return;
    }

    if (user && user.alive && !isUserTied) {
      addGameLog('🗳️ PK决选投票：平票玩家不可投票。请点击平票候选人头像进行投票，或选择弃票', false);
      game.pickMode = 'vote';
      game.pick.idx = null;
      renderGameUI();
      setControlArea('');
    } else {
      if (isUserTied) {
        addGameLog('⚖️ 你作为平票玩家，本轮失去投票权，等待其他玩家投票...', false);
      }
      renderGameUI();
      simulateAIVotes();
    }
  }

  // 统一分批规则：排除用户后的名单按人数对半；奇数时前一批多 1 位（同一批并行请求）
  function splitAiBatches(list) {
    const arr = (list || []).slice();
    const half = Math.ceil(arr.length / 2);
    return [arr.slice(0, half), arr.slice(half)];
  }
  // ========== 警长竞选环节（9/12人场 · 首日白天） ==========
  let sheriffBadgeResolver = null;
  function sheriffAliveVoters() {
    const cands = game.sheriffCandidates || [];
    return game.players.filter(p => p.alive && cands.indexOf(p.position) === -1);
  }
  function sheriffRemainingCandidates() {
    const cands = game.sheriffCandidates || [];
    const out = game.sheriffWithdrawn || [];
    return cands.filter(pos => out.indexOf(pos) === -1);
  }
  // 断点恢复：按警长竞选当前阶段续跑
  function resumeSheriffStage() {
    if (!game) return;
    const stage = game.sheriffStage;
    if (stage === 'signup') {
      const user = game.players[game.userIndex];
      if (user && user.alive && !game.sheriffUserSignDecided) {
        addGameLog('🚨 请继续选择是否上警竞选警长：', false);
        setControlArea('<div style="display:flex;gap:6px;justify-content:center;padding:6px;"><button data-ubp-act="sheriff-run" class="ubp-btn primary" style="padding:6px 18px;">🙋 上警</button><button data-ubp-act="sheriff-notrun" class="ubp-btn" style="padding:6px 18px;">不上警</button></div>');
        return;
      }
      askAiSheriffSignups();
    } else if (stage === 'speech') {
      if (game.sheriffSpeechIdx >= (game.sheriffSpeechQueue || []).length) { finishSheriffSpeeches(); return; }
      runNextSheriffSpeaker();
    } else if (stage === 'withdraw') {
      const user = game.players[game.userIndex];
      if (user && user.alive && (game.sheriffCandidates || []).indexOf(user.position) !== -1 && !game.sheriffUserWithdrawDecided) {
        addGameLog('🚨 请继续选择是否退水：', false);
        setControlArea('<div style="display:flex;gap:6px;justify-content:center;padding:6px;"><button data-ubp-act="sheriff-keep" class="ubp-btn primary" style="padding:6px 18px;">坚持竞选</button><button data-ubp-act="sheriff-withdraw" class="ubp-btn" style="padding:6px 18px;">💧 退水</button></div>');
        return;
      }
      runNextSheriffWithdraw();
    } else if (stage === 'pk') {
      if (game.sheriffPkIdx >= (game.sheriffPkQueue || []).length) { finishSheriffPkSpeeches(); return; }
      runNextSheriffPkSpeaker();
    } else if (stage === 'vote') {
      const user = game.players[game.userIndex];
      const isCand = user && (game.sheriffCandidates || []).indexOf(user.position) !== -1;
      if (user && user.alive && !isCand && !game.sheriffUserVoted) {
        addGameLog('🚨 请继续投出你的警长票：', false);
        game.pickMode = 'sheriffvote';
        game.pick = { idx: null };
        renderGameUI();
        setControlArea('');
        return;
      }
      askAiSheriffVotes();
    } else {
      beginDaySpeeches();
    }
  }

  function startSheriffElection() {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    game.sheriffStage = 'signup';
    game.sheriffCandidates = [];
    game.sheriffWithdrawn = [];
    game.sheriffVotes = {};
    game.sheriffDirection = '';
    game.sheriffDirectionDay = 0;
    game.sheriffPkRound = 0;
    game.sheriffPkCandidates = [];
    game.sheriffPkQueue = [];
    game.sheriffPkIdx = 0;
    game.sheriffBadgeTorn = false;
    game.sheriffPos = null;
    game.sheriffDone = false;
    game.sheriffSignDecided = [];
    game.sheriffWithdrawnDecided = [];
    game.sheriffUserWithdrawDecided = false;
    game.sheriffVotedDecided = [];
    game.sheriffSignQueue = [];
    game.sheriffSpeechQueue = [];
    game.sheriffSpeechIdx = 0;
    game.sheriffWithdrawQueue = [];
    game.sheriffWithdrawIdx = 0;
    game.sheriffVoterQueue = [];
    game.sheriffVoterIdx = 0;
    game.sheriffUserVoted = 0;
    game.sheriffUserSignDecided = false;
    game.pickMode = null;
    game.pick = { idx: null };
    addGameLog('🚨 警长竞选环节开始：想当警长的玩家请举手（上警），上警玩家将依次发表竞选发言，之后可以选择退水，未上警玩家投票选出警长（警长票计1.5票）。', true);
    saveGameRecord();
    renderGameUI();
    const user = game.players[game.userIndex];
    if (user && user.alive) {
      addGameLog('🚨 请选择你是否上警竞选警长：', false);
      setControlArea('<div style="display:flex;gap:6px;justify-content:center;padding:6px;"><button data-ubp-act="sheriff-run" class="ubp-btn primary" style="padding:6px 18px;">🙋 上警</button><button data-ubp-act="sheriff-notrun" class="ubp-btn" style="padding:6px 18px;">不上警</button></div>');
      return;
    }
    askAiSheriffSignups();
  }
  function askAiSheriffSignups() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'signup') return;
    const dec = game.sheriffSignDecided || (game.sheriffSignDecided = []);
    // 统一按人数分批：排除用户后的完整名单对半，奇数时前一批多 1 位；第一批全部处理完再处理第二批
    const eligible = game.players.filter(p => p.alive && !p.isUser);
    const halves = splitAiBatches(eligible);
    const firstPending = halves[0].filter(p => dec.indexOf(p.position) === -1);
    const secondPending = halves[1].filter(p => dec.indexOf(p.position) === -1);
    if (!firstPending.length && !secondPending.length) { finishSheriffSignup(); return; }
    const targets = firstPending.length ? firstPending : secondPending;
    setControlArea('<div style="text-align:center;padding:6px;color:#fff;">' + targets.map(p => p.name).join('、') + ' 正在思考是否上警...</div>');
    Promise.all(targets.map(p => askOneSheriffSignup(session, p, dec))).then(() => {
      if (!isSessionValid(session) || game.sheriffStage !== 'signup') return;
      askAiSheriffSignups();
    });
  }
  function askOneSheriffSignup(session, p, dec) {
    return new Promise(finish => {
      let attempts = 0;
      const applyResult = (res) => {
        if (!isSessionValid(session) || game.sheriffStage !== 'signup') { finish(); return; }
        const parsedS = parseWolfSpeechResponse(res);
        addHiddenThought(parsedS.thought || '正在权衡是否上警竞选警长。', p.position);
        const m = String(res || '').match(/SHERIFF_RUN[^A-Za-z]{0,8}(YES|NO|是|否|上警|不上警)/i);
        const yesRun = !!(m && /^(YES|是|上警)$/i.test(m[1]));
        if (dec.indexOf(p.position) === -1) dec.push(p.position);
        if (yesRun) {
          if (game.sheriffCandidates.indexOf(p.position) === -1) game.sheriffCandidates.push(p.position);
          addGameLog('🙋 ' + p.name + '（' + p.position + '号位）上警竞选警长！', true);
        } else {
          addGameLog('🙅 ' + p.name + '（' + p.position + '号位）选择不上警。', true);
        }
        saveGameRecord();
        renderGameUI();
        finish();
      };
      const applyDefault = () => {
        if (!isSessionValid(session) || game.sheriffStage !== 'signup') { finish(); return; }
        if (dec.indexOf(p.position) === -1) dec.push(p.position);
        addGameLog('🙅 ' + p.name + '（' + p.position + '号位）未能完成上警思考，按不上警处理。', true);
        saveGameRecord();
        renderGameUI();
        finish();
      };
      const attempt = () => {
        addGameLog('⏳ ' + p.name + '（' + p.position + '号位）正在思考要不要上警...');
        const config = loadConfig();
        const overview = getGamePublicOverview(p);
        const history = getPlayerHistoryContext(p);
        const identityCtx = getPlayerIdentitySystemContext(p);
        const prompt = '现在是第1天白天的警长竞选环节（上警报名阶段）。' + overview + identityCtx + '\n\n【场上历史公开发言与公告】：\n' + history + '\n\n【上警决策指引】：\n1. 警长拥有1.5票与决定发言顺序的权力，对阵营争夺非常关键。请结合你的底牌、角色人设与对局风格，认真权衡自己是否要上警竞选（例如预言家/强神职常考虑上警带节奏；狼人可考虑悍跳上警抢警徽；普通村民也可以上警挡刀或辅助；不想暴露身份可以不上警）。\n2. 【防全知铁律】只能依据自己的底牌与公开信息推理，严禁开天眼。\n3. 在<thinking>中输出完整的上警思考，在<SHERIFF_RUN>中明确写 YES（上警）或 NO（不上警）。\n\n输出格式必须为：\n<thinking>上警思考...</thinking>\n<SHERIFF_RUN>\nSHERIFF_RUN: [YES 或 NO]\n</SHERIFF_RUN>';
        apiChat([
          { role: 'system', content: '你是狼人杀玩家，正在决定是否上警竞选警长。必须代入角色人设与底牌立场进行思考，严格输出思考与报名格式，严禁开天眼。' },
          { role: 'user', content: prompt }
        ], config, { maxTokens: 3000 }).then(res => applyResult(res)).catch(err => {
          if (!isSessionValid(session) || game.sheriffStage !== 'signup') { finish(); return; }
          attempts += 1;
          handleAiFailure('AI上警思考（' + p.position + '号位 ' + p.name + '）', err, attempts, () => { attempt(); }, applyDefault);
        });
      };
      attempt();
    });
  }

  function finishSheriffSignup() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'signup') return;
    setControlArea('');
    const cands = game.sheriffCandidates || [];
    if (!cands.length) {
      addGameLog('🚨 无人上警，本局没有警长。', true);
      game.sheriffStage = 'done';
      game.sheriffDone = true;
      saveGameRecord();
      renderGameUI();
      afterSheriffElection(false);
      return;
    }
    if (cands.length === 1) {
      const only = game.players.find(p => p.position === cands[0]);
      game.sheriffPos = only.position;
      game.sheriffStage = 'done';
      game.sheriffDone = true;
