  function finishSheriffVote() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'vote') return;
    setControlArea('');
    const remaining = sheriffRemainingCandidates();
    let maxV = 0;
    remaining.forEach(pos => { const v = game.sheriffVotes[pos] || 0; if (v > maxV) maxV = v; });
    let tops = remaining.filter(pos => (game.sheriffVotes[pos] || 0) === maxV && maxV > 0);
    if (!tops.length) tops = remaining.slice();
    const voteStr = remaining.map(pos => { const t = game.players.find(x => x.position === pos); return (t ? t.name : pos + '号位') + ' ' + (game.sheriffVotes[pos] || 0) + '票'; }).join('、');
    // 平票：与放逐投票一致——平票角色先 PK 发言，其余玩家重新思考投票；再次平票则警徽流失
    if (tops.length > 1 && !game.sheriffPkRound) {
      game.sheriffPkRound = 1;
      game.sheriffPkCandidates = tops.slice();
      game.sheriffPkQueue = tops.slice();
      game.sheriffPkIdx = 0;
      game.sheriffStage = 'pk';
      addGameLog('🚨 警长选举平票（' + voteStr + '）：' + tops.map(pos => pos + '号位').join('、') + ' 进入平票 PK 发言环节！', true);
      saveGameRecord();
      renderGameUI();
      runNextSheriffPkSpeaker();
      return;
    }
    if (tops.length > 1 && game.sheriffPkRound) {
      addGameLog('🚨 PK投票再次平票（' + voteStr + '），警徽流失，本局没有警长。', true);
      game.sheriffPos = null;
      game.sheriffStage = 'done';
      game.sheriffDone = true;
      game.sheriffBadgeTorn = true;
      game.sheriffDirection = '';
      game.sheriffDirectionDay = 0;
      saveGameRecord();
      renderGameUI();
      afterSheriffElection(false);
      return;
    }
    const winnerPos = tops[0];
    const winner = game.players.find(p => p.position === winnerPos);
    game.sheriffPos = winnerPos;
    game.sheriffStage = 'done';
    game.sheriffDone = true;
    game.sheriffDirection = '';
    game.sheriffDirectionDay = 0;
    addGameLog('🚨 警长选举结果：' + voteStr + '。' + (winner ? winner.name + '（' + winnerPos + '号位）' : winnerPos + '号位') + ' 当选警长！🎖️', true);
    saveGameRecord();
    renderGameUI();
    afterSheriffElection(true);
  }
  // 警长决定每天从警左还是警右开始发言（决定一次并持续生效）
  function sheriffPickDirection(attemptNo) {
