      addHiddenThought(parsedO.thought || '正在决定发言方向。', sheriff.position);
      const m = String(res || '').match(/SHERIFF_ORDER[^A-Za-z]{0,8}(LEFT|RIGHT|左|右|警左|警右)/i);
      const dir = (m && /^(LEFT|左|警左)$/i.test(m[1])) ? 'left' : 'right';
      game.sheriffDirection = dir;
      game.sheriffDirectionDay = game.day;
      addGameLog('🚨 警长 ' + sheriff.name + ' 决定今天从' + (dir === 'left' ? '警左（号位递增）' : '警右（号位递减）') + '开始发言。', true);
      saveGameRecord();
      beginDaySpeeches();
    }).catch(err => {
      if (!isSessionValid(session) || game.phase !== 'day') return;
      handleAiFailure('AI警长方向思考', err, (attemptNo || 1), (n) => sheriffPickDirection(n), () => {
        if (!isSessionValid(session) || game.phase !== 'day') return;
        game.sheriffDirection = 'right';
        game.sheriffDirectionDay = game.day;
        addGameLog('🚨 AI警长方向思考失败，默认从警右开始发言。', true);
        saveGameRecord();
        beginDaySpeeches();
      });
    });
  }
  // 警长出局：AI 思考移交警徽或撕毁警徽（用户在 UI 中选择）
  function sheriffNeighborStartIndex(sheriffPos, dir) {
    const n = game.players.length;
    const step = dir === 'left' ? 1 : -1;
    for (let i = 1; i <= n; i++) {
      const pos = ((sheriffPos - 1 + step * i) % n + n) % n + 1;
      const p = game.players.find(x => x.position === pos);
      if (p && p.alive) return game.players.indexOf(p);
    }
    return -1;
  }
  async function resolveSheriffBadgeOnDeath(session, dead) {
    if (!game || !dead) return;
    if (game.sheriffPos !== dead.position || game.sheriffBadgeTorn) return;
    const stage = game.sheriffStage || 'done';
    if (stage === 'signup' || stage === 'speech' || stage === 'withdraw' || stage === 'vote') return; // 竞选期阶段暂不处理
    const alive = game.players.filter(p => p.alive);
    if (!alive.length) { game.sheriffPos = null; game.sheriffBadgeTorn = true; return; }
    addGameLog('🚨 ' + dead.name + '（' + dead.position + '号位）作为警长出局，需要决定把警徽移交给谁，或者撕毁警徽。', true);
    let decision = null;
    if (dead.isUser) {
      if (game.isUser) { /* noop */ }
      const choice = await sheriffUserBadgePick(session, dead);
      if (!isSessionValid(session)) return;
      decision = choice;
    } else {
      decision = await aiSheriffBadgeDecide(session, dead);
      if (!isSessionValid(session)) return;
    }
    if (decision && decision.tear) {
      game.sheriffPos = null;
      game.sheriffBadgeTorn = true;
      addGameLog('🚨 警徽被撕毁，本局不再有警长；之后按普通规则（存活最小号位）决定发言顺序。', true);
    } else if (decision && decision.pos) {
      const t = game.players.find(p => p.position === decision.pos && p.alive);
      if (t) {
        game.sheriffPos = t.position;
        game.sheriffDirection = '';
        game.sheriffDirectionDay = 0;
        addGameLog('🚨 警徽移交给了 ' + t.name + '（' + t.position + '号位），TA 成为新的警长！🎖️', true);
      } else {
        game.sheriffPos = null;
        game.sheriffBadgeTorn = true;
        addGameLog('🚨 由于没有合适的移交对象，警徽被撕毁，本局不再有警长。', true);
      }
    } else {
      game.sheriffPos = null;
      game.sheriffBadgeTorn = true;
      addGameLog('🚨 警徽被撕毁，本局不再有警长。', true);
    }
    saveGameRecord();
    renderGameUI();
  }
  function sheriffUserBadgePick(session, sheriff) {
    return new Promise(resolve => {
      sheriffBadgeResolver = resolve;
      addGameLog('🚨 请选择警徽移交给谁（点击头像后选择“移交”），或直接点击“撕毁警徽”：', false);
      game.pickMode = 'badge';
