        const res = String(res2 == null ? '' : res2);
        const mTh = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
        let thought = mTh ? mTh[1].trim() : res.replace(/<VOTE_ACTION>[\s\S]*?<\/VOTE_ACTION>/i, '').trim();

        let isSkip = false;
        let targetPos = 0;
        const actionBlock = res.match(/<VOTE_ACTION>([\s\S]*?)<\/VOTE_ACTION>/i);
        const textToSearch = actionBlock ? actionBlock[1] : res;

        if (/弃票|放弃|SKIP/i.test(textToSearch)) {
          isSkip = true;
        }

        const mVote = textToSearch.match(/VOTE[：:]\s*[\[【（(]?\s*(\d{1,2}|[一二三四五六七八九十]{1,3}|弃票|SKIP)\s*号?[\]】）)]?/i) || res.match(/VOTE[：:]\s*[\[【（(]?\s*(\d{1,2}|[一二三四五六七八九十]{1,3}|弃票|SKIP)\s*号?[\]】）)]?/i);
        if (mVote && mVote[1]) {
          const vStr = mVote[1];
          if (vStr === '0' || vStr === '弃票' || vStr.toUpperCase() === 'SKIP') {
            isSkip = true;
          } else {
            targetPos = cnNumMap[vStr] ?? parseInt(vStr) ?? 0;
          }
        }

        if (!isSkip && !targetPos) {
          const voteHint = textToSearch.match(/(?:投给|投票给|放逐|归票|票出|投死|投)\s*[\[【（(]?\s*(\d{1,2}|[一二三四五六七八九十]{1,3})\s*号?/i);
          if (voteHint && voteHint[1]) {
            targetPos = cnNumMap[voteHint[1]] ?? parseInt(voteHint[1]) ?? 0;
          }
        }

        if (isSkip || targetPos === 0) {
          p.votedFor = null;
        } else {
          let target = game.players.find(tp => tp.position === targetPos && tp.alive);
          if (isPk && target && !pkCandidates.some(cp => cp.position === target.position)) {
            target = null;
          }
          p.votedFor = target ? game.players.indexOf(target) : null;
        }

        if (!thought || thought.length < 35) {
          if (p.votedFor != null) { // != null 同时盖住 undefined（旧存档可能没有该字段）
            const tPlayer = game.players[p.votedFor];
            thought = `【${p.position}号位 ${p.name} 深度投票思考】：综合白天所有公开发言和场上逻辑漏洞，${tPlayer.position}号位 ${tPlayer.name} 的表水存在严重的自相矛盾与推卸嫌疑。站在我作为${p.role}的阵营胜利视角，投出${tPlayer.position}号位收益最大。因此，我明确决定投票给 ${tPlayer.position}号位 ${tPlayer.name}。`;
          } else {
            thought = `【${p.position}号位 ${p.name} 深度投票思考】：目前场上各方信息极其混沌，几位焦点牌的表水难辨真伪，若冒然跟票极可能误伤好人阵营关键神民或被狼人带节奏。因此，我经过谨慎权衡，决定本轮明确选择弃票避险。`;
          }
        }

        // 让思考内容与真实票型保持一致：以系统解析出的最终票型为准，替换模型自述的最终决断句
        {
          const finalTarget = (p.votedFor != null) ? game.players[p.votedFor] : null;
          const finalLine = finalTarget
            ? ('因此，我决定投票给 ' + finalTarget.position + '号位 ' + finalTarget.name + '。')
            : '因此，我决定选择弃票。';
          const decisionRe = /(?:因此|综上|所以|最终|总而言之|最后)[^\n。！？]{0,24}?我?[^\n。！？]{0,8}?决定[^\n。！？]{0,40}?(?:投票给|投给|放逐|归票|票出|弃票|选择弃票)[^\n。！？]*[。！？]?/g;
          let lastIdx = -1, mm;
          while ((mm = decisionRe.exec(thought)) !== null) { lastIdx = mm.index; }
          if (lastIdx >= 0) thought = (thought.slice(0, lastIdx).trim() + '\n' + finalLine).trim();
          else thought = thought + '\n' + finalLine;
        }

        if (stage1Thought) thought = stage1Thought + '\n' + thought;
        addHiddenThought(thought, p.position);
      };
      const voteTimeoutFallback = () => {
        if (!isSessionValid(session)) return;
        addHiddenThought(`[第${game.day}天 投票思考超时或网络波动，权衡局势选择弃票]`, p.position);
        p.votedFor = null;
      };
      const runAttempt = () => {
      // 6人场：一次调用完成思考+投票；9/12 人场：思考链分两次调取（第一步局势梳理，第二步投票决断）
      if (game.players.length < 9) {
        return apiChat([systemMsg, { role: 'user', content: prompt }], config, { maxTokens: 3000, timeout: 70000 }).then(res => { finishWith(res, ''); });
      }
      const stage1Prompt = '现在是第' + game.day + '天白天放逐投票环节的第一阶段（只做局势梳理，先不要给出投票决定）。' + pkRoundNote + '\n' + pOverview + pIdentity + '\n\n【本局历史公开发言与系统播报记录】：\n' + history + '\n\n【第一步·局势梳理要求】：\n1. 你的底牌是【' + p.role + '】。请详尽梳理当前场上局势：逐一盘点存活玩家的发言、表态与站边逻辑，指出谁最可疑、谁的逻辑不自洽，并给出你的怀疑度排序。\n2. 【防全知铁律】只能使用你自己的底牌与专属信息、系统公告与其他玩家的公开发言进行判断，严禁开天眼。\n3. 本阶段【不要做出投票决断】，只输出完整的局势分析思考链，格式：\n<thinking>\n[局势与发言破绽梳理（越详尽越好）]\n</thinking>';
      return apiChat([
        { role: 'system', content: `你是${p.position}号位${p.name}（身份：${p.role}）。现在是投票思考的第一阶段：只做详尽的局势梳理，暂不下投票结论。` },
        { role: 'user', content: stage1Prompt }
      ], config, { maxTokens: 3000, timeout: 70000 }).then(res1 => {
        if (!isSessionValid(session)) return;
        const t1 = (parseWolfSpeechResponse(res1).thought || String(res1 == null ? '' : res1).trim());
        const stage2Prompt = prompt + '\n\n【你在第一阶段完成的局势梳理（这是你已完成的思考前半段，请在其基础上继续推理）】：\n' + capTextByChars(t1, 2500) + '\n\n【第二步·投票决断】请基于上述梳理，继续输出决策部分的 <thinking>（承接第一步分析并给出最终权衡与决断）与 <VOTE_ACTION>。';
        return apiChat([
          { role: 'system', content: `你是${p.position}号位${p.name}（身份：${p.role}）。这是投票思考的第二阶段：基于你已完成的局势梳理给出最终投票决断，严禁空洞。` },
          { role: 'user', content: stage2Prompt }
        ], config, { maxTokens: 3000, timeout: 70000 }).then(res2 => { finishWith(res2, t1); }).catch(() => finishWith('', t1));
      });
      };
      return new Promise(finish => {
        let attempts = 0;
        const attempt = () => {
          runAttempt().then(() => finish()).catch(err => {
            if (!isSessionValid(session)) { finish(); return; }
            attempts += 1;
            handleAiFailure(p.position + '号位投票思考', err, attempts, () => { attempt(); }, () => { voteTimeoutFallback(); finish(); });
          });
        };
        attempt();
      });
    };

    const finishVotesAll = () => {
      if (!isSessionValid(session) || game.phase !== 'vote') return; // 自爆等已改阶段：丢弃在途投票，防止夜里执行放逐/连跑两夜
      setControlArea('');
      saveGameRecord();
      finishVote();
    };
    // 统一按人数分批：排除用户后的名单对半，奇数时前一批多 1 位（同一批并行）
    const waves = splitAiBatches(aliveAIs);
    const runWave = (voters, label) => {
      if (!voters.length) return Promise.resolve();
      setControlArea('<div style="text-align:center;padding:6px;color:#fff;">' + label + ' AI 玩家们正在深度推演思考投票或弃票中...</div>');
      return Promise.all(voters.map(p => makeVotePromise(p)));
    };
    runWave(waves[0], '第一批').then(() => {
      if (!isSessionValid(session) || game.phase !== 'vote') return;
      if (!waves[1].length) { finishVotesAll(); return; }
      runWave(waves[1], '第二批').then(finishVotesAll);
    });
  }

  function startPkSpeaking(tiedPlayers) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.isPkSpeaking = true;
    game.pkCandidates = tiedPlayers;
    game.pkSpeakerQueue = tiedPlayers.slice();
    game.pkCurrentSpeakerIdx = 0;
    saveGameRecord();
    runNextPkSpeaker();
  }

  function runNextPkSpeaker() {
    const session = game?.session;
    if (!isSessionValid(session) || !game.isPkSpeaking) return;
    
    if (game.pkCurrentSpeakerIdx >= game.pkSpeakerQueue.length) {
      game.isPkSpeaking = false;
      addGameLog(`📢 平票辩解发言结束，平票玩家（${game.pkCandidates.map(p => `${p.position}号位 ${p.name}`).join('、')}）失去本轮投票权，其余存活玩家重新思考进行投票或弃票！`, true);
      saveGameRecord();
      startPkVote();
      return;
    }

    const current = game.pkSpeakerQueue[game.pkCurrentSpeakerIdx];
    if (!current || !current.alive) {
      game.pkCurrentSpeakerIdx++;
      runNextPkSpeaker();
      return;
    }

    addGameLog(`💬 平票辩解：请 ${current.position}号位 ${current.name} 进行一轮发言辩解`, true);
    
    if (current.isUser) {
      setControlArea(`
        <div style="font-weight:600;font-size:12px;color:#FFD700;margin-bottom:4px;">⚖️ 你处于平票 PK 辩解中，请输入你的辩解发言：</div>
        <div id="game-speak-area" style="display:flex;gap:4px;margin:4px 0;">
          <input id="game-speak-input" class="ubp-fieldinput" type="text" placeholder="进行你的辩解发言..." style="flex:1;min-width:0;">
          <button data-ubp-act="game-pk-speak" class="ubp-btn primary" style="padding:0 10px;">发言</button>
          <button data-ubp-act="game-pk-speak-skip" class="ubp-btn" style="padding:0 10px;">跳过</button>
        </div>
      `);
      const input = sheet?.querySelector('#game-speak-input');
      if (input) input.focus();
    } else {
      setControlArea(`<div style="text-align:center;padding:6px;color:#fff;">${current.name} 正在思考平票辩解发言...</div>`);
      generateAIPkSpeech(current, () => {
        if (!isSessionValid(session) || !game.isPkSpeaking) return;
        game.pkCurrentSpeakerIdx++;
        saveGameRecord();
        runNextPkSpeaker();
      });
    }
  }

  function generateAIPkSpeech(player, callback, attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;

    const config = loadConfig();
    const overview = getGamePublicOverview(player);
    const history = getPlayerHistoryContext(player);
    const identityCtx = player.role === '预言家' ? '' : getPlayerIdentitySystemContext(player);
    const competitors = (game.pkCandidates || []).filter(p => p.position !== player.position).map(p => `${p.position}号位 ${p.name}`).join('、');

    let seerReminder = '';
    if (player.role === '预言家') {
      const checkedDetails = Object.keys(game.seerChecked || {}).map(posStr => {
        const pos = parseInt(posStr);
        const target = game.players.find(p => p.position === pos);
        if (!target) return '';
        const isTargetWolf = target.role === '狼人';
        return `${target.position}号位 ${target.name}${target.isUser ? '（玩家主角）' : ''}：【${isTargetWolf ? '狼人（查杀）' : '好人（金水）'}】`;
      }).filter(Boolean);
      if (checkedDetails.length > 0) {
        seerReminder = `\n【你是真预言家，夜间真实查验结果如下】：\n${checkedDetails.join('；')}\n（若查出某人为狼人，必须在PK辩解中坚决号召投出该狼人查杀，绝对不可反咬或误报好人）`;
      }
    }

    const wolfPkNote = (player.role === '狼人') ? getWolfFailedKillNote('day') : '';
    const prompt = `你正在扮演平票PK发言玩家：${player.position}号位 ${player.name}。\n你的底牌是：${player.role}。\n${overview}${seerReminder}${identityCtx}\n\n【场上历史公开发言与思考记录】：\n${history}${wolfPkNote}\n\n【平票PK辩解紧急要求】：\n1. 当前你与【${competitors}】得票相同陷入平票，现在是你的平票辩解发言回合！\n2. 你必须全力为自己争取好人信任，辩解自己的身份，并针对竞争对手【${competitors}】的发言漏洞和疑点进行猛烈反驳与质疑，号召其他未平票的玩家把票投给TA或弃票！\n3. 深刻明白这只是一场朋友间聚会的狼人杀推理桌游，严禁真实物理死亡或流血生离死别描写！按角色真实口吻、口癖与人际关系进行真人生动的桌游PK辩解。\n4. 【强制结构要求】：必须包含<thinking>与<speech>，严禁缺失思考推演！公开发言必须语义完整，严禁半句截断或提前闭合</speech>！\n5. 输出格式（两个标签必须完整闭合，只输出这两个标签，严禁输出任何其它标签，严禁把思考内容写进 <speech>）：\n<thinking>写出你作为${player.role}在此刻平票PK中的深层内部心理与辩解策略（严禁空置）</thinking>\n<speech>真正说出口的完整PK辩解发言（口语化自然、长度自然可长可短，严禁包含动作描写或【公开发言】等标记，必须语义完整、自然收尾，严禁半句截断）</speech>`;

    apiChat([
      { role: 'system', content: applyBoardIntro(config.prompt || DEFAULT_PROMPT) },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000, timeout: 70000 }).then(res => {
      if (!isSessionValid(session)) return;
      const parsedSpeech = parseWolfSpeechResponse(res);
      let thought = parsedSpeech.thought;
      let speech = completeWolfSpeechLine(parsedSpeech.speech, 'pk');
      if (!speech) speech = '我真的是好人，大家仔细看前置位的投票和发言，投我的问题很大，建议大家认清局势！';

      if (!thought) {
        thought = `现在我和${competitors}陷入平票PK，这轮表水至关重要。我必须针对对方发言的破绽进行致命打击，同时向场上其他持票好人真诚表水自证，绝不能被推出局。`;
      }

      addHiddenThought(thought, player.position);
      addGameLog(`🗣️ [PK辩解] ${player.name}（${player.position}号位）: <speech>${speech}</speech>`, true, player.position);
      saveGameRecord();
      callback();
    }).catch(err => {
      if (!isSessionValid(session)) return;
      handleAiFailure('PK辩解生成', err, (attemptNo || 1), (n) => generateAIPkSpeech(player, callback, n), () => {
        addHiddenThought('（PK辩解连续5次生成失败，按默认内容处理）', player.position);
        addGameLog(`🗣️ [PK辩解] ${player.name}（${player.position}号位）: <speech>我真的是好人，请大家看清楚局势把票归对，别被狼人带节奏。</speech>`, true, player.position);
        saveGameRecord();
        callback();
      });
    });
  }

  function endDayToNight() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.isPkVote = false;
    game.isPkSpeaking = false;
    game.pkCandidates = null;
    game.pkSpeakerQueue = [];
    game.players.forEach(p => p.votedFor = null);
    game.day++;
    game.nightDeaths = [];
    saveGameRecord();
    setTimeout(() => {
      if (!isSessionValid(session)) return;
      startNight();
    }, 600);
  }

  // 放逐结算核心：严格要求投票人数必须大于弃票人数才可能放逐出局
  async function finishVote() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    if (game.phase !== 'vote') return; // 只在投票阶段结算：狼人自爆等已切夜晚时必须丢弃
    let votedCount = 0;
    let skipCount = 0;

    game.players.forEach(p => {
      if (!p.alive) return;
      if (game.isPkVote && game.pkCandidates && game.pkCandidates.some(cp => cp.position === p.position)) {
        addGameLog(`🗳️ ${p.name}（${p.position}号位）平票玩家无投票权`, true);
        return;
      }
      if (p.votedFor != null) { // != null 同时盖住 undefined（旧存档可能没有该字段）
        votedCount++;
        const target = game.players[p.votedFor];
        const isSheriffVote = game.players.length >= 12 && game.sheriffPos === p.position && !game.sheriffBadgeTorn;
        addGameLog(`🗳️ ${p.name}（${p.position}号位）投给了 ${target.name}（${target.position}号位）${isSheriffVote ? '【警长1.5票】' : ''}`, true);
      } else {
        skipCount++;
        addGameLog(`🗳️ ${p.name}（${p.position}号位）弃票`, true);
      }
    });

    // 核心修复规则：只有有效投票数严格大于弃票数才能产生放逐；如果投票数 <= 弃票数，强制流票进夜
    if (votedCount <= skipCount) {
      if (game.isPkVote) {
        addGameLog(`⚖️ PK决选轮次有效投票人数（${votedCount}人）不大于弃票人数（${skipCount}人），本轮流票，无人出局，直接进入夜晚。`, true);
        endDayToNight();
      } else {
        addGameLog(`⚖️ 本轮有效投票人数（${votedCount}人）不大于弃票人数（${skipCount}人），放逐流票，无人出局，直接进入夜晚。`, true);
        endDayToNight();
      }
      return;
    }

    const votes = {};
    game.players.forEach(p => {
      if (!p.alive) return;
      if (game.isPkVote && (game.pkCandidates || []).some(cp => cp.position === p.position)) return; // PK 轮平票玩家无投票权，忽略其上一轮旧票
      if (p.votedFor != null) { // != null 同时盖住 undefined（旧存档可能没有该字段）
        const idx = p.votedFor;
        const weight = (game.players.length >= 12 && game.sheriffPos === p.position && !game.sheriffBadgeTorn) ? 1.5 : 1;
        votes[idx] = (votes[idx] || 0) + weight;
      }
    });

    let maxVotes = 0;
    let maxIndices = [];
    for (const [idxStr, count] of Object.entries(votes)) {
      const countNum = count;
      const idx = parseInt(idxStr);
      if (countNum > maxVotes) {
        maxVotes = countNum;
        maxIndices = [idx];
      } else if (countNum === maxVotes && maxVotes > 0) {
        maxIndices.push(idx);
      }
    }

    if (maxVotes === 0 || maxIndices.length === 0) {
      if (game.isPkVote) {
        addGameLog(`⚖️ PK轮次无人得票，本轮流票，无人出局，直接进入夜晚`, true);
        endDayToNight();
      } else {
        addGameLog(`⚖️ 今日无人得票，放逐流票，无人出局，直接进入夜晚`, true);
        endDayToNight();
      }
      return;
    }

    // 核心平票逻辑：在投票人数大于弃票人数的前提下，两人或多人平票且票数相同，进入平票发言辩解
    if (maxIndices.length > 1) {
      const tiedPlayers = maxIndices.map(idx => game.players[idx]);
      const tiedNames = tiedPlayers.map(p => `${p.position}号位 ${p.name}`).join('、');
      
      if (game.isPkVote) {
        addGameLog(`⚖️ PK投票再次平票（${tiedNames} 均为 ${maxVotes} 票）！二次平票，今日无人出局，直接进入夜晚。`, true);
        endDayToNight();
      } else {
        addGameLog(`⚖️ 出现平票！${tiedNames} 均为 ${maxVotes} 票（大于弃票数）。进入平票 PK 辩解环节！`, true);
        startPkSpeaking(tiedPlayers);
      }
      return;
    }

    // 产生唯一最高票出局者
    const eliminated = game.players[maxIndices[0]];
    if (eliminated && eliminated.alive) {
      eliminated.alive = false;
      eliminated.deathCause = 'vote';
      renderGameUI();
      addGameLog(`💀 ${eliminated.name}（${eliminated.position}号位）以 ${maxVotes} 票（有效投票 ${votedCount} 票 vs 弃票 ${skipCount} 票）被放逐出局`, true);
      saveGameRecord();
      await resolveSheriffBadgeOnDeath(session, eliminated);
      if (!isSessionValid(session)) return;
      await generateFinalWords(eliminated);
    }

    if (!isSessionValid(session)) return;
    renderGameUI();
    saveGameRecord();
    // 猎人技能：被放逐出局的猎人（被毒死的除外）可以开枪带走 1 人
    await resolveHunterShots(session);
    if (!isSessionValid(session)) return;
    if (checkWin()) { endGame(); return; }
    endDayToNight();
  }

  // ========== 猎人技能（除被女巫毒死外，出局时可开枪带走 1 人） ==========
  let hunterPickResolver = null;
  function hunterAliveTargets(hunter) {
    return (game ? game.players : []).filter(p => p.alive && p !== hunter);
  }
  function hunterAutoTarget(hunter) {
    const alive = hunterAliveTargets(hunter);
    if (!alive.length) return null;
    // AI 猎人：优先带走"投过自己"的人（报仇），否则随机挑一位存活玩家
    const voters = alive.filter(p => p.votedFor != null && game.players[p.votedFor] === hunter);
    const pool = voters.length ? voters : alive;
    return pool[Math.floor(Math.random() * pool.length)];
  }
  async function applyHunterShot(hunter, target) {
    if (!hunter || !target || !target.alive) return;
    const isDayShot = (game.phase === 'vote' || game.phase === 'day');
    target.alive = false;
    target.deathCause = 'shot';
    if (!isDayShot) game.nightDeaths.push({ p: target, type: '猎人枪杀' });
    addGameLog('🔫 ' + hunter.name + '（' + hunter.position + '号位）发动猎人技能，开枪带走了 ' + target.name + '（' + target.position + '号位）！', true);
    if (game.sheriffPos === target.position && !game.sheriffBadgeTorn) {
      await resolveSheriffBadgeOnDeath(game.session, target);
    }
    renderGameUI();
    saveGameRecord();
    if (isDayShot && isSessionValid(game.session)) {
      await generateFinalWords(target);
    }
  }
  function hunterUserPick(session, hunter) {
    return new Promise(resolve => {
      hunterPickResolver = resolve;
      setControlArea(
        '<div style="margin:4px 0;">' +
        '<div style="font-size:12px;color:#F97316;text-align:center;margin-bottom:6px;line-height:1.5;">🔫 你是猎人，出局时可以开枪带走 1 人<br><span style="font-size:11px;color:var(--ubp-text-3);">（被女巫毒死则无法开枪；本次为' + (hunter.deathCause === 'vote' ? '被放逐出局' : '夜间出局') + '）</span></div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:6px;justify-content:center;">' +
        hunterAliveTargets(hunter).map(p => '<button data-ubp-act="hunter-shoot" data-target-idx="' + game.players.indexOf(p) + '" class="ubp-btn" style="padding:5px 10px;font-size:12px;">' + p.position + '号 ' + escapeHtml(p.name) + '</button>').join('') +
        '<button data-ubp-act="hunter-no-shoot" class="ubp-btn" style="padding:5px 10px;font-size:12px;opacity:0.85;">不开枪</button>' +
        '</div></div>'
      );
    });
  }
  // AI 猎人开枪思考：达到开枪条件时调取 AI 判断该带走谁（失败自动回退默认策略）
  function aiHunterDecide(session, hunter, attemptNo) {
    return new Promise(resolve => {
      const fallback = () => {
        try { resolve(hunterAutoTarget(hunter) || null); } catch (e) { resolve(null); }
      };
      try {
        const alive = hunterAliveTargets(hunter);
        if (!alive.length) { resolve(null); return; }
        const config = loadConfig();
        setControlArea('<div style="text-align:center;padding:6px;color:#fff;">🎯 ' + hunter.name + ' 正在思考开枪带走谁...</div>');
        addGameLog('⏳ AI 猎人（' + hunter.position + '号位 ' + hunter.name + '）正在回忆整局局势，思考开枪目标...');
        const overview = getGamePublicOverview(hunter);
        const history = getPlayerHistoryContext(hunter);
        const targetList = alive.map(p => p.position + '号位(' + p.name + (p.isUser ? '，主角本人' : '') + ')').join('、');
        const cause = hunter.deathCause === 'vote' ? '刚刚被投票放逐出局' : '刚刚在夜晚被狼人刀出局';
        const prompt = '你正在扮演狼人杀中的猎人（' + hunter.position + '号位 ' + hunter.name + '），你' + cause + '，现在可以开枪带走 1 名存活玩家，也可以选择不开枪。' + overview + getPlayerIdentitySystemContext(hunter) + '\n\n【本局公开发言、公告与投票历史】：\n' + history + '\n\n可开枪目标：' + targetList + '\n\n【猎人开枪决策指引】：\n1. 你只能依据公开信息与你的角色认知推理，严禁开天眼！结合白天发言矛盾、投票行为（谁投过你、谁在保狼）与你的人设关系决定带走谁。\n2. 这是一场朋友间狼人杀桌游，开枪是游戏机制；若你判断无人足够可疑，可选择不开枪（HUNTER_SHOOT: 0）。\n3. 必须输出完整的<thinking>推演，然后严格按格式输出：\n<thinking>\n开枪思考...\n</thinking>\n<HUNTER_ACTION>\nHUNTER_SHOOT: [被带走玩家的号位数字，不开枪填0]\n</HUNTER_ACTION>';
        apiChat([
          { role: 'system', content: '你是狼人杀猎人。必须完全代入角色人设与口吻进行推理，结合公开信息锁定嫌疑最大的玩家，严格输出思考与开枪格式。' },
          { role: 'user', content: prompt }
        ], config, { maxTokens: 3000 }).then(res => {
          if (!isSessionValid(session)) { resolve(null); return; }
          const parsedH = parseWolfSpeechResponse(res);
          if (parsedH.thought) addHiddenThought(parsedH.thought, hunter.position);
          const pos = parseWolfTargetPos(res, 'HUNTER_SHOOT');
          let target = null;
          if (pos > 0) target = game.players.find(p => p.position === pos && p.alive) || null;
          if (pos === -1) target = hunterAutoTarget(hunter) || null;
          setControlArea('');
          resolve(target);
        }).catch(err => {
          setControlArea('');
          if (!isSessionValid(session)) { resolve(null); return; }
          handleAiFailure('AI猎人开枪思考', err, (attemptNo || 1), (n) => { aiHunterDecide(session, hunter, n).then(resolve); }, fallback);
        });
      } catch (e) { fallback(); }
    });
  }

  // 结算猎人开枪（支持链式：猎人打死猎人可继续开枪；被毒死的猎人不触发）
  async function resolveHunterShots(session) {
    if (!game) return;
    let guard = 0;
    while (guard++ < 12) {
      const hunter = game.players.find(p => !p.alive && p.role === '猎人' && !p.hunterShotDone && p.deathCause !== 'poison');
      if (!hunter) break;
      hunter.hunterShotDone = true;
      if (!isSessionValid(session)) return;
      const lastGod = !game.players.some(p => p.alive && (p.role === '预言家' || p.role === '女巫' || p.role === '猎人' || p.role === '守卫'));
      if (lastGod) {
        addGameLog('🔫 ' + hunter.name + '（' + hunter.position + '号位）作为场上最后一位神职出局，无法开枪带走任何人。', true);
        continue;
      }
      const alive = hunterAliveTargets(hunter);
      if (!alive.length) { addGameLog('🔫 ' + hunter.name + ' 想开枪，但场上已无可带走的玩家。', true); continue; }
      if (hunter.isUser) {
        const idx = await hunterUserPick(session, hunter);
        if (!isSessionValid(session)) return;
        setControlArea('');
        if (idx === -1) { addGameLog('🔫 你选择不开枪。', true); saveGameRecord(); continue; }
        await applyHunterShot(hunter, game.players[idx]);
      } else {
        const decided = await aiHunterDecide(session, hunter);
        if (!isSessionValid(session)) return;
        if (decided) await applyHunterShot(hunter, decided);
        else addGameLog('🔫 ' + hunter.name + ' 思考后选择不开枪带走任何人。', true);
      }
      if (!isSessionValid(session)) return;
    }
    renderGameUI();
    saveGameRecord();
  }

  // ========== 胜负判定与终局记录 ==========
  function checkWin() {
    if (!game) return false;
    const alive = game.players.filter(p => p.alive);
    const wolves = alive.filter(p => p.role === '狼人');
    const good = alive.filter(p => p.role !== '狼人');
    if (wolves.length === 0) { game.winner = '好人阵营'; return true; }
    if (game.players.length >= 9) {
      // 9 人场：屠边——村民全部出局（屠民）或神职全部出局（屠神）即狼人获胜
      const villagersAlive = alive.some(p => p.role === '民');
      const godsAlive = alive.some(p => p.role === '预言家' || p.role === '女巫' || p.role === '猎人' || p.role === '守卫');
      if (!villagersAlive || !godsAlive) { game.winner = '狼人阵营'; return true; }
    } else if (good.length <= 1) {
      game.winner = '狼人阵营'; return true;
    }
    return false;
  }

  function endGame() {
    if (isGameOver) return;
    isGameOver = true;
    game.phase = 'end';
    game.pickMode = null;
    hideActionPopup();
    renderGameUI();
    addGameLog(`🏆 游戏结束，${game.winner}获胜！`, true);
    game.players.forEach(p => {
      addGameLog(`  ${p.name}（${p.position}号位）→ ${p.role} ${p.alive ? '存活' : '已出局'}`, true);
    });
    replayLogs = (game.replay || []).slice();
    replayPlayersSnapshot = (game.players || []).map(p => ({
      position: p.position, name: p.name, isUser: !!p.isUser,
      avatar: p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name)) || ''
    }));
    recordFinishedMatchToHistory(game);
    // ===== 注入：狼人杀对局结果 → 世界书绿灯条目 =====
    try {
      const user = game.players[game.userIndex];
      const isSpectatorGame = !!game.spectatorMode;
      const isUserWon = user ? ((user.role === '狼人' && game.winner === '狼人阵营') || (user.role !== '狼人' && game.winner === '好人阵营')) : false;
      const detailLines = game.players.map(p => `${p.position}号位 ${p.name}${p.isUser ? '（主角）' : ''}：底牌【${p.role}】，${p.alive ? '存活' : '出局'}`).join('；');
      onGameFinished({
        gameType: 'werewolf',
        userWon: isSpectatorGame ? undefined : isUserWon,
        result: isSpectatorGame ? `${game.winner}获胜（你以上帝视角观战）` : `${game.winner}获胜（主角${isUserWon ? '胜' : '负'}）`,
        detail: detailLines,
        replay: formatReplayAsText(replayLogs),
        replayRich: { logs: replayLogs, players: replayPlayersSnapshot },
        spectators: isSpectatorGame ? ['上帝视角·你'] : (game.spectatorNames || []).slice(),
        players: game.players.map(p => ({ name: p.name, isUser: p.isUser, avatar: p.avatar || '' }))
      });
    } catch (e) { /* ignore */ }
    clearSavedGame();
    setControlArea(`
      <div style="display:flex;gap:8px;">
        <button data-ubp-act="exit-game" class="ubp-btn" style="flex:1;">返回板子</button>
        <button data-ubp-act="restart-game" class="ubp-btn primary" style="flex:1;">再来一局</button>
        <button data-ubp-act="show-replay" class="ubp-btn" style="flex:1;">📜 回放</button>
      </div>
      <div style="display:flex;gap:8px;margin-top:8px;">
        <button data-ubp-act="open-discussion" class="ubp-btn" style="flex:1;background:#8B5CF6;border:none;color:#fff;font-weight:600;">💬 对局讨论</button>
      </div>
    `);
  }

  function showReplay() {
    if (!replayLogs.length) {
      showToast('没有游戏记录');
      return;
    }
    const replayRef = { players: replayPlayersSnapshot || [] };
    // 显示层剥离标签后再转义，杜绝把日志原文当 HTML 注入
    const lineHTML = (text) => escapeHtml(stripLogTags(text)).replace(/\n/g, '<br>');
    const html = replayLogs.map(item => {
      if (typeof item === 'object') {
        const cc = (item.authorPos != null) ? getGamePlayerColorByPos(replayRef, item.authorPos) : '';
        if (item.type === 'hidden') {
          const base = cc || '#FFD700';
          return `<div style="color:${base};margin:4px 0;font-size:11px;background:${charColorAlpha(cc, '17') || 'rgba(255,215,0,0.1)'};border-left:3px solid ${base};padding:4px 6px;border-radius:4px;">${lineHTML(item.text)}</div>`;
        }
        if (item.type === 'wolf_private') {
          return `<div style="color:#C084FC;margin:4px 0;font-size:12px;background:rgba(168,85,247,0.12);padding:4px;border-radius:4px;">${lineHTML(item.text)}</div>`;
        }
        if (item.type === 'user_private') {
          return `<div style="color:${item.color || '#EF4444'};margin:4px 0;font-size:12px;font-weight:600;">${lineHTML(item.text)}</div>`;
        }
        const isUserLine = item.authorPos != null && (replayPlayersSnapshot || []).some(p => p && p.isUser && p.position === item.authorPos);
        if (isUserLine) {
          return `<div style="color:#fff;margin:4px 0;font-size:12px;font-weight:600;border-left:3px solid rgba(255,255,255,0.55);padding-left:6px;">${lineHTML(item.text)}</div>`;
        }
        if (cc) {
          return `<div style="color:${cc};margin:4px 0;font-size:12px;font-weight:600;border-left:3px solid ${charColorAlpha(cc, '99')};padding-left:6px;">${lineHTML(item.text)}</div>`;
        }
      }
      const text = typeof item === 'object' ? item.text : item;
      return `<div style="color:#fff;margin:2px 0;">${lineHTML(text)}</div>`;
    }).join('');
    const ov = document.createElement('div');
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="display:flex;justify-content:space-between;margin-bottom:8px;flex-none;">
        <span style="font-size:15px;font-weight:600;">📜 游戏全景复盘与隐藏思考</span>
        <button data-ubp-act="close-replay" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
      </div>
      <div style="flex:1;overflow-y:auto;font-size:12px;line-height:1.6;background:var(--ubp-card-2);border-radius:8px;padding:8px;">${html}</div>
    `;
    sheet.appendChild(ov);
    ov.querySelector('[data-ubp-act="close-replay"]').addEventListener('click', () => ov.remove());
  }

  // ========== 对局讨论（终局后：主角可主动发言，AI 读取全量对局记录生成多位角色的讨论内容） ==========
  function getWolfDiscussionState() {
    const session = game ? game.session : 0;
    if (!wolfDiscussion || wolfDiscussion.session !== session) {
      wolfDiscussion = { session: session, messages: [], busy: false };
    }
    return wolfDiscussion;
  }

  // 全量对局记录 → 讨论用文本（终局后底牌公开：公开发言、投票、夜间行动与隐蔽思考全部可读）
  function buildWolfDiscussionReplayText() {
    if (!game) return '';
    const list = Array.isArray(game.replay) ? game.replay : [];
    const lines = [];
    for (const item of list) {
      if (item == null) continue;
      const raw = typeof item === 'object' ? (item.text || '') : String(item);
      const text = stripLogTags(raw).replace(/\s+/g, ' ').trim();
      if (!text) continue;
      const pos = (typeof item === 'object' && item.authorPos != null) ? item.authorPos : null;
      const p = pos != null ? getGamePlayerByPos(game, pos) : null;
      const prefix = (p && text.slice(0, 14).indexOf(p.name) === -1) ? p.name + '：' : '';
      lines.push(prefix + text);
    }
    return capTextByChars(lines.join('\n'), 9000);
  }

  function renderWolfDiscussionLog() {
    const box = sheet?.querySelector('#wolf-discussion-log');
    if (!box) return;
    const st = getWolfDiscussionState();
    const rows = st.messages.map(m => {
      if (m.role === 'system') {
        return '<div style="margin:5px 0;font-size:11.5px;color:var(--ubp-text-3);text-align:center;line-height:1.5;">' + escapeHtml(m.text) + '</div>';
      }
      if (m.role === 'user') {
        return '<div style="display:flex;align-items:flex-start;gap:6px;margin:6px 0;">' + chatAvatarHTML('我', true, 24) +
          '<div style="flex:1;min-width:0;background:rgba(139,92,246,0.16);border-radius:7px;padding:4px 8px;"><b style="color:#fff;font-size:11.5px;">我：</b><span style="color:var(--ubp-text);font-size:12px;white-space:pre-wrap;">' + escapeHtml(m.text) + '</span></div></div>';
      }
      const color = m.pos != null ? (getGamePlayerColorByPos(game, m.pos) || '#8B5CF6') : (getCharacterColor(m.name) || '#8B5CF6');
      return '<div style="display:flex;align-items:flex-start;gap:6px;margin:6px 0;">' + chatAvatarHTML(m.name, false, 24) +
        '<div style="flex:1;min-width:0;background:' + (charColorAlpha(color, '14') || 'transparent') + ';border-radius:7px;padding:4px 8px;"><b style="color:' + color + ';font-size:11.5px;">' + escapeHtml(m.name) + '：</b><span style="color:var(--ubp-text);font-size:12px;white-space:pre-wrap;">' + escapeHtml(m.text) + '</span></div></div>';
    }).join('');
    const thinking = st.busy ? '<div style="margin:6px 0;font-size:11.5px;color:var(--ubp-text-3);text-align:center;">💭 角色们正在复盘打字…</div>' : '';
    box.innerHTML = rows + thinking;
    box.scrollTop = box.scrollHeight;
  }

  function focusWolfDiscussionInput() {
    const inp = sheet?.querySelector('#wolf-discussion-input');
    if (inp) { try { inp.focus(); } catch (e) { /* ignore */ } }
  }

  function openGameDiscussion() {
    if (!game) return;
    if (game.phase !== 'end') { showToast('对局结束后才能开启讨论'); return; }
    const old = sheet?.querySelector('.wolf-discussion-overlay');
    if (old) old.remove();
    const st = getWolfDiscussionState();
    if (!st.messages.length) {
      st.messages.push({ role: 'system', text: '对局已结束，所有底牌都已公开。直接发送你的想法开聊，或点【让角色们开聊】先听大家复盘。' });
    }
    const ov = document.createElement('div');
    ov.className = 'wolf-discussion-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;flex:none;">
        <span style="font-size:15px;font-weight:600;">💬 对局讨论</span>
        <button data-ubp-act="close-discussion" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
      </div>
      <div style="display:flex;gap:6px;margin:6px 0;flex:none;">
        <button data-ubp-act="discussion-start" class="ubp-btn" style="flex:1;padding:5px 0;font-size:12px;background:rgba(139,92,246,0.16);border:1px solid rgba(139,92,246,0.5);color:#C4B5FD;">🎬 让角色们开聊</button>
      </div>
      <div id="wolf-discussion-log" style="flex:1;min-height:0;overflow-y:auto;background:var(--ubp-card-2);border-radius:10px;padding:8px;font-size:12px;line-height:1.55;margin-bottom:8px;"></div>
      <div style="display:flex;gap:6px;flex:none;">
        <input id="wolf-discussion-input" class="ubp-fieldinput" type="text" placeholder="说说你对这局的看法..." style="flex:1;min-width:0;font-size:12.5px;">
        <button data-ubp-act="discussion-send" class="ubp-btn primary" style="padding:0 12px;">发送</button>
      </div>
    `;
    sheet.appendChild(ov);
    ov.querySelector('[data-ubp-act="close-discussion"]')?.addEventListener('click', () => ov.remove());
    if (sheet) sheet.scrollTop = 0;
    const input = ov.querySelector('#wolf-discussion-input');
    if (input) {
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          const text = input.value.trim();
          if (!text) return;
          if (sendWolfDiscussion(text) === false) return; // 生成中：保留已输入内容
          input.value = '';
        }
      });
    }
    renderWolfDiscussionLog();
  }

  // 解析 AI 讨论输出：支持【角色名】内容 与 角色名：内容 两种行格式
  function parseWolfDiscussionResponse(res) {
    const out = [];
    if (!game) return out;
    const aiPlayers = (game.players || []).filter(p => p && !p.isUser);
    let body = String(res == null ? '' : res).trim();
    const block = body.match(/<discussion>([\s\S]*?)<\/discussion>/i);
    if (block) body = block[1];
    body = stripLogTags(body).replace(/<\/?discussion>/gi, '').trim();
    const findPlayer = (raw) => {
      const nm = String(raw || '').replace(/^\d+\s*号位\s*/, '').trim();
      if (!nm) return null;
      return aiPlayers.find(p => isNameMatch(p.name, nm)) || null;
    };
    for (const line of body.split(/\n+/)) {
      const t = line.trim();
      if (!t) continue;
      let m = t.match(/^【([^】]{1,24})】\s*([\s\S]*)$/);
      if (!m) m = t.match(/^([^：:]{1,24})[：:]\s*([\s\S]*)$/);
      if (m) {
        const p = findPlayer(m[1]);
        const text = ensureCompleteLine(m[2].trim());
        if (p && text) {
          out.push({ role: 'ai', pos: p.position, name: p.name, text: text });
          continue;
        }
      }
      if (out.length) {
        const last = out[out.length - 1];
        last.text = ensureCompleteLine(last.text + ' ' + t);
      } else {
        const text = ensureCompleteLine(t);
        if (text) out.push({ role: 'system', text: text });
      }
    }
    return out;
  }

  function sendWolfDiscussion(userMsg, isRetry) {
    if (!game || game.phase !== 'end') return false;
    const st = getWolfDiscussionState();
    if (st.busy) { showToast('角色们还在讨论，请稍等'); return false; }
    const text = String(userMsg == null ? '' : userMsg).trim();
    if (!isRetry) {
      if (text) {
        st.messages.push({ role: 'user', text: text });
      } else if (st.messages.some(m => m.role === 'ai')) {
        st.messages.push({ role: 'system', text: '（你示意角色们继续聊）' });
      }
    }
    st.busy = true;
    renderWolfDiscussionLog();

    // 主角发言中点名的角色：优先让被点名角色出场并首先回话
    const normForMatch = (s) => String(s == null ? '' : s).replace(/[\s_\-/\\()（）\[\]【】|·:：,.，。！!？?;；、"'“”‘’]/g, '').toLowerCase();
    const mentioned = [];
    if (text) {
      const normText = normForMatch(text);
      for (const p of game.players.filter(x => !x.isUser)) {
        const nm = normForMatch(p.name);
        if (nm && normText.indexOf(nm) !== -1) mentioned.push(p);
      }
    }

    const rolesText = game.players.map(p =>
      `${p.position}号位 ${p.name}${p.isUser ? '（主角本人）' : ''}：底牌【${p.role || '未知'}】，${p.alive ? '存活' : '出局'}`
    ).join('\n');
    const personaText = game.players.filter(p => !p.isUser).map(p => {
      const prof = getCharacterProfile(p.name) || {};
      const bits = [
        prof.identity ? '身份：' + prof.identity : '',
        prof.personality ? '性格：' + prof.personality : '',
        prof.languageStyle ? '口癖：' + prof.languageStyle : '',
        prof.attitude ? '对主角态度：' + prof.attitude : ''
      ].filter(Boolean);
      return `- ${p.position}号位 ${p.name}（底牌：${p.role || '未知'}）：${bits.join('；') || '熟络的朋友，按自然性格与口吻发挥'}`;
    }).join('\n');
    const replayText = buildWolfDiscussionReplayText();
    const historyMsgs = st.messages.filter(m => m.role === 'user' || m.role === 'ai');
    if (text && historyMsgs.length && historyMsgs[historyMsgs.length - 1].role === 'user') historyMsgs.pop();
    const historyText = historyMsgs
      .slice(-24)
      .map(m => (m.role === 'user' ? '我：' : m.name + '：') + m.text)
      .join('\n');
    const hasUserSeat = game.players.some(p => p.isUser);
    const mentionedNames = mentioned.map(p => p.name);
    const rule1 = mentionedNames.length
      ? `1. 主角本条发言点名提到了：${mentionedNames.map(n => '【' + n + '】').join('、')}。必须让${mentionedNames.length > 1 ? '这些角色全部' : '该角色'}发言，且【${mentionedNames[0]}】必须放在第一位、第一个开口，正面回应主角的话（解释、接梗、反驳、爆料、甩锅均可）；剩余名额（总计 3~4 位）再补 1~2 位其他相关角色。`
      : `1. 从上面的角色中挑选 3~4 位（${hasUserSeat ? '不要挑选主角"我"，' : ''}挑选与本局话题最相关或互动最有梗的角色）依次发言，必须完美代入各自的性格、口癖、身份与立场。`;

    const prompt = [
      '你正在主持一场狼人杀桌游赛后的「对局讨论」环节。本局已经结束，所有底牌公开，大家围坐在一起轻松复盘闲聊（游戏出局只是桌游淘汰，绝不是真实死亡，禁止任何流血、生离死别等描写）。',
      `【本局结果】${game.winner || '已结束'}获胜`,
      `【全体底牌与结局】\n${rolesText}`,
      `【可发言角色的性格档案】\n${personaText}`,
      `【本局完整对局记录（公开流程 + 夜间行动 + 各方思考，按时间顺序）】\n${replayText || '（本局记录较短）'}`,
      historyText ? `【此前的讨论记录】\n${historyText}` : '',
      text ? `【主角（我）刚刚说】\n${text}` : '【说明】主角让角色们先聊聊这局的复盘。',
      [
        '【讨论要求】',
        rule1,
        '2. 必须紧扣本局真实对局记录复盘：谁刀/毒/投了谁、谁查了谁、谁悍跳、谁带崩票、谁被忽悠、谁操作漂亮、谁嘴硬不服等，可以互相调侃、甩锅、互吹、吐槽、翻旧账。',
        '3. ' + (text ? '角色们要正面回应主角的话，并结合对局记录与主角互动（可以夸、怼、解释、辩解、爆料）。' : '围绕本局结果与高光/拉胯瞬间展开讨论，角色之间要你来我往地互动，不要只说客套话。'),
        '4. 每段发言口语化、长度自然，必须语义完整、自然收尾，严禁半句截断；严禁动作、表情、旁白与括号描写。',
        '5. 严格输出格式（只输出这个标签块，不要多余文字；【角色名】必须与角色列表中的名字完全一致）：',
        '<discussion>',
        '【角色名】该角色说的话',
        '【角色名】该角色说的话',
        '</discussion>'
      ].join('\n')
    ].filter(Boolean).join('\n\n');

    apiChat([
      { role: 'system', content: '你是熟人桌游局的赛后讨论主持人兼角色扮演者，需要严格依据对局记录，用多位角色的口吻生成真实的赛后复盘讨论。' },
      { role: 'user', content: prompt }
    ], resolveApiConfig(), { maxTokens: 2200, timeout: 70000, temperature: 0.9 }).then(res => {
      if (!game || game.phase !== 'end' || st.session !== game.session) return;
      const msgs = parseWolfDiscussionResponse(res);
      if (msgs.length) {
        msgs.forEach(m => {
          st.messages.push(m);
          if (m.role === 'ai' && m.name && typeof contactsVoiceAutoSpeak === 'function') contactsVoiceAutoSpeak(m.name, m.text);
        });
      } else {
        const fallbackText = ensureCompleteLine(stripLogTags(res));
        if (fallbackText) {
          const aiPlayers = game.players.filter(p => !p.isUser);
          const fp = aiPlayers.length ? aiPlayers[Math.floor(Math.random() * aiPlayers.length)] : null;
          st.messages.push(fp
            ? { role: 'ai', pos: fp.position, name: fp.name, text: fallbackText }
            : { role: 'system', text: fallbackText });
        }
      }
      st.busy = false;
      renderWolfDiscussionLog();
      focusWolfDiscussionInput();
    }).catch(err => {
      if (!game || game.phase !== 'end' || st.session !== game.session) return;
      st.busy = false;
      renderWolfDiscussionLog();
      focusWolfDiscussionInput();
      const reason = (err && err.message) ? err.message : '未知错误';
      showToast('讨论生成失败：' + reason + '，点击重试', () => sendWolfDiscussion(text, true));
    });
    return true;
  }

  // ========== 事件处理分发 ==========
  function handleAction(act, target) {
    if (act === 'chip-exchange') {
      const gk = (target && target.dataset && target.dataset.chipGame) ? target.dataset.chipGame : 'zjh';
      renderChipExchange(gk, () => {
        if (gk === 'zjh') { if (zjh && zjh.phase === 'end') renderZjhGameUI(); else renderZjhLobby(); }
        else if (gk === 'holdem') { if (thGame && thGame.phase === 'end') renderTHGameUI(); else renderTHLobby(); }
        else { if (bjGame && bjGame.phase !== 'sessionEnd' && bjGame.phase !== 'idle') bjRender(); else renderBjLobby(); }
      });
      return;
    }
    if (act === 'hunter-shoot' || act === 'hunter-no-shoot') {
