      renderTableGameLobby();
      return;
    }
    if (act === 'tablegame-lie') { handleLieAction('lie-open', null); return; }
    if (act === 'tablegame-ludo') { handleLudoAction('ludo-open', null); return; }
    if (act === 'tablegame-rm') { handleRmAction('rm-open', null); return; }
    if (act === 'tablegame-uno') { handleUnoAction('uno-open', null); return; }
    if (act === 'tablegame-wolf') { if (hasSavedGame()) { resumeSavedGame(); } else { renderBoard(); } return; }
    if (act === 'tablegame-spy') { if (hasSavedSpyGame()) { resumeSavedSpyGame(); } else { renderSpyBoard(); } return; }
    if (act === 'go-card') {
      renderCardLobby();
      return;
    }
    if (act === 'go-minigame') {
      renderMiniGameLobby();
      return;
    }
