      return;
    }
    if (act === 'close-custom-char') {
      renderSetup();
      return;
    }
    if (act === 'open-theme-picker') {
      renderThemePicker();
      return;
    }
    if (act === 'close-theme-picker') {
      renderSetup();
      return;
    }
    if (act === 'pick-theme') {
      const tid = target && target.dataset ? target.dataset.theme : '';
      if (tid) {
        saveHallTheme(tid);
        const th = HALL_THEMES.find(x => x.id === tid);
        showToast('🎨 已切换风格：' + (th ? th.name : tid));
        if (overlay && th && th.vars) {
          overlay.style.setProperty('--ubp-bg', th.vars.bg);
          overlay.style.setProperty('--ubp-card', th.vars.card);
          overlay.style.setProperty('--ubp-card-2', th.vars.card2);
          overlay.style.setProperty('--ubp-line', th.vars.line);
          overlay.style.setProperty('--ubp-accent', th.vars.accent);
        }
      }
      renderSetup();
      return;
    }
    if (act === 'card-back-center') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      renderSetup();
      return;
    }
    if (act === 'card-ddz') {
      if (hasSavedDDZGame()) resumeSavedDDZGame();
      else renderDDZLobby();
      return;
    }
    if (act === 'card-mj') {
      handleMjAction('mj-open', null);
      return;
    }
    if (act === 'card-zjh') {
      handleZjhAction('zjh-open', null);
      return;
    }
    if (act === 'card-holdem') {
      handleTHAction('th-open', null);
      return;
    }
    if (act === 'card-uno') {
      handleUnoAction('uno-open', null);
      return;
    }
    if (act === 'card-blackjack') {
      handleBjAction('bj-open', null);
      return;
    }
    if (act === 'mini-back-center') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      // 离开时若扫雷对局仍在进行：先快照进度并停表，避免后台计时器常驻、重进后用时被拉长
      if (msGame && msGame.started && !msGame.over) { saveMsGame(); msStopTimer(); }
      if (memoryGame) { stopMemoryTimer(); }
      renderSetup();
      return;
    }
    if (act === 'mini-mines') {
      if (hasSavedMsGame()) resumeMsGame();
      else msNewGame();
      return;
    }
    if (act === 'ms-back') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
      const msSavable = !!(msGame && !msGame.over && msGame.started);
      if (msSavable) saveMsGame();
      msStopTimer();
      renderMiniGameLobby();
      showToast(msSavable ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
      return;
    }
    if (act === 'ms-quit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
      try { localStorage.removeItem(MS_SAVE_KEY); } catch (e) { /* ignore */ }
      msStopTimer();
      msGame = null;
      renderSetup();
      showToast('🚪 已结束本局扫雷');
      return;
    }
    if (act === 'ms-restart') { msNewGame(); return; }
    if (act === 'ms-flag-mode') { if (msGame && !msGame.over) { msFlagMode = !msFlagMode; renderMinesweeper(); } return; }
    if (act === 'ms-hint') { msHint(); return; }
    if (act === 'ms-settings' || act === 'ms-difficulty') { msDifficultyOverlay(); return; }
    if (act === 'ms-apply-custom') {
      const rr = parseInt((sheet.querySelector('#ms-c-rows') || {}).value, 10);
      const cc = parseInt((sheet.querySelector('#ms-c-cols') || {}).value, 10);
      const mm = parseInt((sheet.querySelector('#ms-c-mines') || {}).value, 10);
      if (!(rr >= 5 && rr <= 30 && cc >= 5 && cc <= 30 && mm >= 1)) { showToast('❌ 自定义参数不合法（行/列 5~30，雷 ≥1）'); return; }
      const c = loadMsConfig(); c.custom = { rows: rr, cols: cc, mines: mm }; saveMsConfig(c);
      const ov = sheet.querySelector('.ms-settings-overlay'); if (ov) ov.remove();
      msNewGame();
      return;
    }
    if (act === 'ms-clear-custom') {
      const c = loadMsConfig(); c.custom = null; saveMsConfig(c);
      const ov = sheet.querySelector('.ms-settings-overlay'); if (ov) ov.remove();
      showToast('已清除自定义雷区，回到预设难度');
      msNewGame();
      return;
    }
    if (act === 'mini-llk') {
      if (hasSavedLLKGame()) resumeLLKGame();
      else startLLKGame(6, 6);
      return;
    }
    if (act === 'mini-xxl') {
      if (hasSavedXXLGame()) resumeXXLGame();
      else startXXLGame();
      return;
    }
    if (act === 'mini-memory') {
