    }
    if (act === 'mini-jump') { if (jumpHasSave()) jumpResumeGame(); else jumpOpenGame(); return; }
    if (act === 'jump-restart') { jumpOpenGame(); return; }
    if (act === 'jump-quit') { jumpQuitToCenter(); return; }
    if (act === 'jump-exit') { jumpExitToLobby(); return; }
    if (act === 'jump-continue') { jumpContinue(); return; }
    if (act === 'mini-2048') { if (g2048HasSave()) g2048ResumeGame(); else g2048OpenGame(); return; }
    if (act === 'g2048-restart') { g2048OpenGame(); return; }
    if (act === 'g2048-quit') { g2048QuitToCenter(); return; }
    if (act === 'g2048-exit') { g2048ExitToLobby(); return; }
    if (act === 'g2048-continue') { g2048Continue(); return; }
    if (act === 'mini-suika') { if (suikaHasSave()) suikaResumeGame(); else suikaOpenGame(); return; }
    if (act === 'suika-restart') { suikaOpenGame(); return; }
    if (act === 'suika-quit') { suikaQuitToCenter(); return; }
    if (act === 'mini-snake') { if (snakeHasSave()) snakeResumeGame(); else snakeOpenGame(); return; }
    if (act === 'snake-restart') { snakeOpenGame(); return; }
    if (act === 'snake-wrap-toggle') { snakeToggleWrap(); return; }
    if (act === 'snake-accel-toggle') { snakeToggleAccel(); return; }
    if (act === 'snake-exit') { snakeExitToLobby(); return; }
    if (act === 'snake-quit') { snakeQuitToCenter(); return; }
    if (act === 'mini-pac') { if (pacHasSave()) pacResumeGame(); else pacOpenGame(); return; }
    if (act === 'pac-restart') { pacOpenGame(); return; }
    if (act === 'pac-exit') { pacExitToLobby(); return; }
    if (act === 'pac-quit') { pacQuitToCenter(); return; }
    if (act === 'mini-dino') { if (dinoHasSave()) dinoResumeGame(); else dinoOpenGame(); return; }
    if (act === 'dino-restart') { dinoOpenGame(); return; }
    if (act === 'dino-exit') { dinoExitToLobby(); return; }
    if (act === 'dino-quit') { dinoQuitToCenter(); return; }
    if (act === 'suika-exit') { suikaExitToLobby(); return; }
    if (act === 'suika-continue') { suikaContinue(); return; }
    if (act === 'memory-back') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); const memSaved = saveMemoryGame(); memoryStop(); renderMiniGameLobby(); showToast(memSaved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅'); return; }
    if (act === 'memory-quit') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); clearMemorySave(); memoryStop(); renderSetup(); showToast('🚪 已结束本局记忆翻牌'); return; }
    if (act === 'memory-new') { memoryNewGame(); return; }
    if (act === 'memory-settings') { renderMemorySettings(); return; }
    if (act === 'memory-tile') {
      const idx = parseInt(target.dataset.idx, 10);
      if (Number.isFinite(idx)) handleMemoryCardClick(idx);
      return;
    }
    if (act === 'mini-tetris') { if (hasSavedTetrisGame()) resumeTetrisGame(); else startTetrisGame(); return; }
    if (act === 'tetris-back') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); saveTetrisGame(); tetrisStop(); tetrisGame = null; renderAIBattleLobby(); showToast('🔖 已保存进度，下次进入可继续'); return; }
    if (act === 'tetris-quit') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); clearTetrisSave(); tetrisStop(); tetrisGame = null; renderSetup(); showToast('🚪 已结束本局俄罗斯方块'); return; }
    if (act === 'tetris-exit') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); clearTetrisSave(); tetrisStop(); tetrisGame = null; renderAIBattleLobby(); return; }
    if (act === 'tetris-left') { tetrisMove(-1); return; }
    if (act === 'tetris-right') { tetrisMove(1); return; }
    if (act === 'tetris-down') { tetrisSoftDrop(); return; }
    if (act === 'tetris-rotate') { tetrisRotate(); return; }
    if (act === 'tetris-hard') { tetrisHardDrop(); return; }
    if (act === 'tetris-restart') { startTetrisGame(); return; }
    if (act === 'tetris-pause') {
      const tg = tetrisGame;
      if (!tg) return;
      if (tg.phase === 'play') { tg.phase = 'paused'; tetrisStop(); }
      else if (tg.phase === 'paused') { tg.phase = 'play'; tetrisResetTimer(); }
      tetrisRender();
