      if (memoryGame) stopMemoryTimer();
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 关闭游戏面板：清空排队语音并切断在读语音
      if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
      return;
    }
    if (act === 'save-api') {
