          const cfg = loadConfig(); cfg.model = model; saveConfig(cfg);
          const container = sheet.querySelector('#model-list-container');
          if (container) { container.style.display = 'none'; container.innerHTML = ''; }
          const status = sheet.querySelector('#model-status');
          if (status) status.textContent = `✅ 已选择模型: ${model}`;
        }
      }
      return;
    }
if (act === 'go-board') {
      if (hasSavedGame()) {
        resumeSavedGame();
        return;
      }
      renderBoard();
      return;
    }
    if (act === 'go-spy') {
      if (hasSavedSpyGame()) {
        resumeSavedSpyGame();
        return;
      }
      renderSpyBoard();
      return;
    }
    if (act === 'go-contacts' || act.indexOf('contacts-') === 0) {
      handleContactsAction(act, target);
      return;
    }
    if (act === 'go-record') {
      renderRecordView();
      return;
    }
    if (act === 'go-shop') {
      renderShop();
      return;
    }
    if (act === 'close-shop') {
