    }
    if (act === 'daily-signin') {
      if (isSignedInToday()) { showToast('今天已经签到过了，等数据库时间进入新的一天后再来吧'); return; }
      signInToday();
      renderSetup();
      showToast('📅 签到成功！积分 +10（当前 ' + loadPoints() + '）');
      return;
    }
    if (act === 'shop-buy') {
      const key = target.dataset.card || '';
      const def = SHOP_ITEMS.find(t => t.key === key); // 必须查 SHOP_ITEMS：观战卡不在 IDENTITY_CARD_TYPES 里，旧代码导致购买观战卡静默失败
      if (!def) return;
      const cur = loadPoints();
      if (cur < def.price) { showToast('💎 积分不足（需要 ' + def.price + ' 积分，当前 ' + cur + '）'); return; }
      addPoints(-def.price);
      addIdentityCard(key, 1);
      renderShop();
      showToast('✅ 购买成功：' + def.name + ' ×1（剩余 ' + loadPoints() + ' 积分）');
      return;
    }
    if (act === 'go-rps') {
      if (hasSavedRps()) resumeRps(); else startRPSGame();
      return;
    }
    if (act === 'go-ttt') {
      if (hasSavedTtt()) resumeTtt(); else startTTTGame();
      return;
    }
    if (act === 'go-aibattle') {
      renderAIBattleLobby();
      return;
    }
    if (act === 'tetris-battle') {
      startTetrisBattle();
      return;
    }
    if (act === 'tb-back') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); tbBackToSingle(); return; }
    if (act === 'tb-exit' || act === 'tb-lobby') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); tbQuitToLobby(); return; }
    if (act === 'tb-again') { startTetrisBattle(tetrisBattle && tetrisBattle.opponent ? tetrisBattle.opponent.name : undefined); return; }
    if (act === 'tb-invite') { renderTBBattleInviteOverlay(); return; }
    if (act === 'tb-level') {
      const lv = (target && target.dataset) ? target.dataset.level : '';
      if (TB_LEVELS[lv]) {
        tbSetLevel(lv);
        if (tetrisBattle) { tetrisBattle.level = lv; tetrisBattle.sides.ai.target = null; }
        renderTetrisBattleUI();
        showToast('🤖 AI难度已切换：' + TB_LEVELS[lv].name);
      }
      return;
    }
