        game.nightDeaths.push({ p: target, type: '毒杀' });
        renderGameUI();
        addGameLog(`🧪 你使用了毒药${target.isUser ? '毒杀了自己' : `，毒杀了 ${target.name}（${target.position}号位）`}`, false);
      }
      game.pick.idx = null;
      game.pickMode = null;
      game.witchMenu = false;
      hideActionPopup();
      saveGameRecord();
      finishNightAndStartDay();
      return;
    }
    if (act === 'night-skip') {
      if (game.phase === 'night' && game.players[game.userIndex]?.role === '狼人' && game.nightStep === 'wolf') { game.lastWolfKillPos = 0; game.lastWolfKillDied = false; }
      game.pick.idx = null;
      game.pickMode = null;
      game.witchMenu = false;
      hideActionPopup();
      saveGameRecord();
      if (game.phase === 'night' && game.players[game.userIndex]?.role === '女巫') {
        finishNightAndStartDay();
      } else if (game.phase === 'night' && game.players[game.userIndex]?.role === '守卫') {
        stepSeerAction();
      } else if (game.phase === 'night' && game.players[game.userIndex]?.role === '预言家') {
        stepWolfAction();
      } else {
        stepWitchAction();
      }
      return;
    }
    if (act === 'wolf-boom') {
      const session = game?.session;
      if (!isSessionValid(session)) return;
      const user = game.players[game.userIndex];
      if (!user || !user.alive || user.role !== '狼人' || (game.phase !== 'day' && game.phase !== 'vote')) return;
      const doWolfBoom = () => {
        if (!isSessionValid(session)) return;
        const u = game.players[game.userIndex];
        addGameLog(`💥 ${u.name}（${u.position}号位）自爆！白天立刻结束，直接入夜。`, true);
        u.alive = false;
        if (game.sheriffPos === u.position && !game.sheriffBadgeTorn) { resolveSheriffBadgeOnDeath(game.session, u); }
        setControlArea('');
        hideActionPopup();
        const speakArea = sheet?.querySelector('#game-speak-area');
        if (speakArea) speakArea.remove();
        renderGameUI();
        saveGameRecord();
        if (checkWin()) { endGame(); return; }
        game.phase = 'night';
        game.pickMode = null;
        game.isPkVote = false;
        game.isPkSpeaking = false;
        game.pkCandidates = null;
        const statusEl = sheet?.querySelector('#game-status-text');
        if (statusEl) statusEl.textContent = `🐺 第${game.day}天 · 💥 自爆入夜`;
        game.players.forEach(p => p.votedFor = null);
        game.day++;
        game.nightDeaths = [];
        saveGameRecord();
        setTimeout(() => {
          if (!isSessionValid(session)) return;
          startNight();
        }, 600);
      };
      // 狼人自爆时，若首日死讯尚未公布（例如警长竞选期间），先公布死讯再入夜
      if (!game.dayAnnounced) { announceDayAndDeaths().then(doWolfBoom); return; }
      doWolfBoom();
      return;
    }
    if (act === 'restart-game') {
      if (!game) return;
      const players = game.players;
      players.forEach(p => {
        p.alive = true;
        p.role = null;
        p.votedFor = null;
        p.hasSpoken = false;
        p.avatar = p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name));
      });
      currentGameSession++;
      game = {
        session: currentGameSession,
        boardSize: players.length,
        identityCards: [],
        wolfTeammateNames: [],
        spectatorNames: (game && Array.isArray(game.spectatorNames)) ? game.spectatorNames.slice() : [],
        spectatorMode: !!(game && game.spectatorMode),
        players: players,
        phase: 'idle',
        day: 0,
        currentSpeaker: 0,
        winner: null,
        history: [],
        historyEntries: [],
        userIndex: game.userIndex,
        nightResult: '',
        nightKill: null,
        nightDeaths: [],
        witchAction: null,
        witchMenu: false,
        witchMenuReturn: false,
        witchUsedAntidote: false,
        witchUsedPoison: false,
        witchSavedPos: null,
        guardProtectedPos: null,
        guardLastPos: null,
        lastWolfKillPos: 0,
        lastWolfKillDied: false,
        wolfMateChatDone: false,
        wolfMateChatText: '',
        dayAnnounced: false,
        sheriffLeadDone: false,
        sheriffPos: null,
        sheriffStage: '',
        sheriffDone: false,
        sheriffCandidates: [],
        sheriffWithdrawn: [],
        sheriffVotes: {},
        sheriffDirection: '',
        sheriffDirectionDay: 0,
        sheriffPkRound: 0,
        sheriffPkCandidates: [],
        sheriffPkQueue: [],
        sheriffPkIdx: 0,
        sheriffBadgeTorn: false,
        seerChecked: {},
        votes: {},
        replay: [],
        pickMode: null,
        pick: { idx: null },
        resolvingFinalWords: null,
        tactics: { ai: '', user: '', custom: '' },
        aiWolfTactics: null,
        simNightContext: '',
        isPkVote: false,
        pkCandidates: null,
        pkSpeakerQueue: [],
        pkCurrentSpeakerIdx: 0,
        isPkSpeaking: false
      };
      isGameOver = false;
      replayLogs = [];
      clearSavedGame();
      startGame();
      return;
    }
    if (act === 'exit-game') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      currentGameSession++;
      game = null;
      isGameOver = true;
      clearSavedGame();
      hideActionPopup();
      renderBoard();
      return;
    }
    if (act === 'wolf-back-board') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      // ← 返回板子页：保留存档并中止当前异步流程，稍后可【继续对局】
      saveGameRecord();
      currentGameSession++;
      game = null;
      isGameOver = true;
      hideActionPopup();
      renderBoard();
      showToast('🔖 已返回板子页，对局进度已保存');
      return;
    }
    if (act === 'discard-saved-game') {
      clearSavedGame();
      hideActionPopup();
      renderBoard();
      showToast('🗑️ 已放弃进行中的狼人杀对局');
      return;
    }
    if (act === 'show-replay') {
      showReplay();
      return;
    }
    if (act === 'open-discussion') {
      openGameDiscussion();
      return;
    }
    if (act === 'close-discussion') {
      const dOv = sheet?.querySelector('.wolf-discussion-overlay');
      if (dOv) dOv.remove();
      return;
    }
    if (act === 'discussion-send') {
      const dInput = sheet?.querySelector('#wolf-discussion-input');
      const dText = dInput ? dInput.value.trim() : '';
      if (!dText) { showToast('请先输入你想说的话'); return; }
      if (sendWolfDiscussion(dText) === false) return; // 生成中：保留已输入内容
      if (dInput) dInput.value = '';
      return;
    }
    if (act === 'discussion-start') {
      sendWolfDiscussion('');
      return;
    }
  }

  // ========== 加载模型列表 ==========
  async function loadModelList() {
    const urlInput = sheet.querySelector('#game-api-url');
    const keyInput = sheet.querySelector('#game-api-key');
    const statusEl = sheet.querySelector('#model-status');
    const container = sheet.querySelector('#model-list-container');
    if (!urlInput || !keyInput || !statusEl || !container) return;
    const apiUrl = urlInput.value.trim();
    const apiKey = keyInput.value.trim();
    if (!apiUrl) { statusEl.textContent = '⚠️ 请先填写 API 地址'; return; }
    statusEl.textContent = '⏳ 加载模型列表中...';
    container.style.display = 'none';
    container.innerHTML = '';
    const endpoints = [apiUrl.replace(/\/+$/, '') + '/v1/models', apiUrl.replace(/\/+$/, '') + '/models'];
    let models = [];
    for (const url of endpoints) {
      try {
        const resp = await fetch(url, { headers: apiKey ? { 'Authorization': `Bearer ${apiKey}` } : {} });
        if (!resp.ok) continue;
        const data = await resp.json();
        if (data && data.data && Array.isArray(data.data)) {
          models = data.data.map(item => item.id).filter(id => typeof id === 'string');
          break;
        } else if (data && Array.isArray(data.models)) {
          models = data.models.map(item => item.id).filter(id => typeof id === 'string');
          break;
        }
      } catch (e) { /* ignore */ }
    }
    if (models.length === 0) { statusEl.textContent = '❌ 未能获取模型列表，请检查 API 地址和密钥'; return; }
    statusEl.textContent = `✅ 找到 ${models.length} 个模型，点击选择`;
    container.style.display = 'block';
    container.innerHTML = models.map(m => `
      <div data-ubp-act="select-model" data-model="${m}" style="padding:6px 8px;border-bottom:1px solid var(--ubp-line);cursor:pointer;font-size:13px;border-radius:4px;" onmouseover="this.style.background='var(--ubp-card-2)'" onmouseout="this.style.background='transparent'">${m}</div>
    `).join('');
  }






