  function loadBoardConfig() {
    try {
      const raw = localStorage.getItem(BOARD_CONFIG_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (typeof parsed.aiCompanion !== 'boolean') parsed.aiCompanion = true;
        if (!parsed.speechInterval) parsed.speechInterval = 3;
        if (!parsed.aiLevel) parsed.aiLevel = 'normal';
        return parsed;
      }
    } catch (e) { /* ignore */ }
    return {
      aiCompanion: true,
      speechInterval: 3,
      opponentName: '',
      aiLevel: 'normal'
    };
  }

  function saveBoardConfig(cfg) {
    try {
      localStorage.setItem(BOARD_CONFIG_KEY, JSON.stringify(cfg));
    } catch (e) { /* ignore */ }
