  function saveBoardGameState() {
    if (boardGame && boardGame.gameType === 'luzhanqi') {
      const e = boardGame.engine;
      if (!e) { clearSavedBoardGame('luzhanqi'); return; }
      // 对局已结束的不留档；布阵阶段与对局阶段都保留（退出后可继续）
      if (e.phase === 'play' && e.winner) { clearSavedBoardGame('luzhanqi'); return; }
      try {
        const state = {
          gameType: 'luzhanqi',
          lzq: e.serialize(),
          aiCompanion: boardGame.aiCompanion,
          speechInterval: boardGame.speechInterval,
          aiLevel: boardGame.aiLevel || 'normal',
          opponent: boardGame.opponent,
          userMoves: boardGame.userMoves,
          lastSpeech: boardGame.lastSpeech,
          isUserFirst: boardGame.isUserFirst,
          softenPlayCount: boardGame.softenPlayCount,
          conversation: boardGame.conversation,
          turn: e.turn,
          winner: e.winner,
          history: e.history
        };
        localStorage.setItem(boardSaveKeyFor(state.gameType), JSON.stringify(state));
      } catch (err) { /* ignore */ }
      return;
    }
    if (boardGame && boardGame.gameType === 'battleship') {
      const e = boardGame.engine;
      if (!e || e.winner) { clearSavedBoardGame('battleship'); return; }
      try {
        const state = {
          gameType: 'battleship',
          board: e.playerBoard,
          turn: e.turn,
          history: e.history,
          winner: e.winner,
          aiCompanion: boardGame.aiCompanion,
          speechInterval: boardGame.speechInterval,
          aiLevel: boardGame.aiLevel || 'normal',
          opponent: boardGame.opponent,
          userMoves: boardGame.userMoves,
          lastSpeech: boardGame.lastSpeech,
          isUserFirst: boardGame.isUserFirst,
          softenPlayCount: boardGame.softenPlayCount,
          conversation: boardGame.conversation,
          bs: bsSerializeBattleship(e),
          bsSelectedSkills: bsUI ? bsUI.selectedSkills.slice() : [],
          bsOri: bsUI ? bsUI.ori : 'H',
          bsActiveShip: bsUI ? bsUI.activeShip : null
        };
        localStorage.setItem(boardSaveKeyFor(state.gameType), JSON.stringify(state));
      } catch (err) { /* ignore */ }
      return;
    }
    if (!boardGame || !boardGame.gameType || !boardGame.engine || (boardGame.engine.winner !== 0 && boardGame.engine.winner !== null)) {
      clearSavedBoardGame(boardGame && boardGame.gameType ? boardGame.gameType : undefined);
      return;
    }
    try {
      const state = {
        gameType: boardGame.gameType,
        board: boardGame.engine.board,
        turn: boardGame.engine.turn,
        history: boardGame.engine.history,
        winner: boardGame.engine.winner,
        castling: boardGame.engine.castling,
