        koPoint: boardGame.engine.koPoint,
        passes: boardGame.engine.passes,
        captures: boardGame.engine.captures,
        aiCompanion: boardGame.aiCompanion,
        speechInterval: boardGame.speechInterval,
        aiLevel: boardGame.aiLevel || 'normal',
        opponent: boardGame.opponent,
        userMoves: boardGame.userMoves,
        lastSpeech: boardGame.lastSpeech,
        isUserFirst: boardGame.isUserFirst,
        softenPlayCount: boardGame.softenPlayCount,
        conversation: boardGame.conversation
      };
      localStorage.setItem(boardSaveKeyFor(state.gameType), JSON.stringify(state));
    } catch (e) { /* ignore */ }
  }

  function clearSavedBoardGame(type) {
    try {
      if (type) {
        localStorage.removeItem(boardSaveKeyFor(type));
        // 旧版单槽存档：仅当它属于该棋类（或记录不完整）时才清除，避免误删其他棋类的进度
        try {
          const rawL = localStorage.getItem(BOARD_SAVE_KEY);
          if (rawL) {
            const d = JSON.parse(rawL);
            if (!d || !d.gameType || d.gameType === type) localStorage.removeItem(BOARD_SAVE_KEY);
          }
        } catch (e2) { localStorage.removeItem(BOARD_SAVE_KEY); }
      } else {
        boardSaveTypes().forEach(t => localStorage.removeItem(boardSaveKeyFor(t)));
        localStorage.removeItem(BOARD_SAVE_KEY);
      }
    } catch (e) { /* ignore */ }
  }

  function hasSavedBoardGame() {
    return !!findSavedBoardGame();
  }

  // ===== 分棋类存档：每个棋类各留一份"进行中对局"（大厅只在对应棋子旁标注 🔖 进行中） =====
  function boardSaveTypes() { return ['gomoku', 'xiangqi', 'jungle', 'chess', 'shogi', 'go', 'luzhanqi', 'othello', 'battleship']; }
  function boardSaveKeyFor(type) { return BOARD_SAVE_KEY + '_' + type; }
  // 读取某棋类的进行中存档（不传 type 则任意棋类；兼容旧版单槽存档并顺手迁移）
  function findSavedBoardGame(type) {
    // 单个存档损坏不影响其他棋类的读取
    const parseOk = (raw) => { try { return JSON.parse(raw); } catch (e2) { return null; } };
    const valid = (d) => !!(d && d.gameType && (!type || d.gameType === type) && (d.winner === 0 || d.winner === null));
    try {
      const keys = type ? [boardSaveKeyFor(type)] : boardSaveTypes().map(boardSaveKeyFor);
      for (const k of keys) {
        const raw = localStorage.getItem(k);
        if (!raw) continue;
        const d = parseOk(raw);
        if (valid(d)) return d;
      }
      const rawL = localStorage.getItem(BOARD_SAVE_KEY); // 旧版单槽存档
      if (rawL) {
        const d = parseOk(rawL);
        if (valid(d)) return d;
      }
    } catch (e) { /* ignore */ }
    return null;
  }

  // ========== 游戏引擎实现 ==========

  // 置换表写入：搜索被时间截断时不写入（半截分值会污染表造成错误剪枝），
  // 且只有"新搜索深度不浅于已有条目"时才覆盖。
  function boardTTStore(engine, hash, depth, score, move, flag) {
    if (!engine || !engine.tt || engine.searchAborted) return;
    const old = engine.tt.get(hash);
    if (old && old.depth > depth) return;
    engine.tt.set(hash, { depth, score, move, flag });
  }

  // 1. 五子棋引擎 (15x15 启发式估值)
  class GomokuEngine {
    constructor(size = 15) {
      this.size = size;
      this.board = Array(size * size).fill(0); // 0=空, 1=黑, 2=白
      this.history = [];
      this.turn = 1; // 1=黑, 2=白
      this.winner = 0; // 0=进行中, 1=黑胜, 2=白胜, 3=平局
    }
    get(r, c) {
      if (r < 0 || r >= this.size || c < 0 || c >= this.size) return -1;
      return this.board[r * this.size + c];
    }
    set(r, c, val) {
      this.board[r * this.size + c] = val;
    }
    makeMove(r, c, player = this.turn) {
      if (this.winner !== 0 || this.get(r, c) !== 0) return false;
      this.set(r, c, player);
      this.history.push({ r, c, player });
      const lineLen = this.checkWin(r, c, player);
      if (lineLen === 5) {
        this.winner = player;
      } else if (lineLen > 5) {
        // 长连禁手：连成 6 子及以上判负（对手获胜）——文案已在大厅规则里写明
        this.winner = player === 1 ? 2 : 1;
      } else if (this.history.length === this.size * this.size) {
        this.winner = 3;
      } else {
        this.turn = this.turn === 1 ? 2 : 1;
      }
      return true;
    }
    undo() {
      if (!this.history.length) return false;
      const last = this.history.pop();
      this.set(last.r, last.c, 0);
      this.winner = 0;
      this.turn = last.player;
      return true;
    }
    checkWin(r, c, p) {
      const dirs = [[0, 1], [1, 0], [1, 1], [1, -1]];
      let best = 0;
      for (const [dr, dc] of dirs) {
        let count = 1;
        for (let i = 1; i < this.size; i++) {
          if (this.get(r + dr * i, c + dc * i) === p) count++; else break;
        }
        for (let i = 1; i < this.size; i++) {
          if (this.get(r - dr * i, c - dc * i) === p) count++; else break;
        }
        if (count > best) best = count;
      }
      return best;
    }
    getBestMove(aiPlayer = 2, soften = false, level = 'normal') {
      const humanPlayer = aiPlayer === 1 ? 2 : 1;
      if (this.history.length === 0) {
        return { r: 7, c: 7 };
      }
      // 统一难度中枢：快速只看单点成型分（不懂防守）、标准看攻防、强力额外算"对手最强反击"
      const D = getDifficulty('gomoku', level);
      const weak = D.level === 'fast';
      const strong = D.level === 'strong';
      let scoredMoves = [];
      const candidates = new Set();
      for (let r = 0; r < this.size; r++) {
        for (let c = 0; c < this.size; c++) {
          if (this.get(r, c) !== 0) {
            for (let dr = -2; dr <= 2; dr++) {
              for (let dc = -2; dc <= 2; dc++) {
                const nr = r + dr, nc = c + dc;
                if (this.get(nr, nc) === 0) candidates.add(nr * this.size + nc);
              }
            }
          }
        }
      }
      for (const idx of candidates) {
        const r = Math.floor(idx / this.size);
        const c = idx % this.size;
        const attackScore = this.evaluatePoint(r, c, aiPlayer, weak);
        let defenseScore = this.evaluatePoint(r, c, humanPlayer, weak);
        // 快速档只挡"立刻连成四"的点，其它防守看不见
        if (weak && defenseScore < 1500) defenseScore = 0;
        let score = weak ? (attackScore * 1.05 + defenseScore * 0.5) : (attackScore * 1.15 + defenseScore);
        // 强力档：落子后再评估"对手最强一手"的分，用 我得分 - 对手回应分 排序
        if (strong && score < 100000) {
          this.set(r, c, aiPlayer);
          const oppBest = this.bestPointScore(humanPlayer, aiPlayer, false);
          this.set(r, c, 0);
          score -= oppBest * 1.05;
        }
        scoredMoves.push({ r, c, score });
      }
      scoredMoves.sort((a, b) => b.score - a.score);
      if (!scoredMoves.length) return { r: 7, c: 7 };

      // 让让我（soften）：只有快速/标准档会手软，强力档必须始终走最优（确定性）
      if (soften && level !== 'strong' && scoredMoves.length > 2 && scoredMoves[0].score < 50000) {
        const pickIdx = Math.floor(Math.random() * Math.min(3, scoredMoves.length - 1)) + 1;
        return scoredMoves[pickIdx];
      }
      // 难度：必胜手绝不失误；快速更随性、标准偶尔手软、强力始终最优
      if (scoredMoves[0].score >= 100000) return scoredMoves[0];
      // 主动失误：只从次优候选池（candK）里挑，绝不随机到"全部合法招"
      if (level !== 'strong' && scoredMoves.length > 1) {
        if (Math.random() < D.blunder) {
          const pool = scoredMoves.slice(1, Math.max(2, Math.min(D.candK, scoredMoves.length)));
          return pool[Math.floor(Math.random() * pool.length)];
        }
      }
      return scoredMoves[0];
    }
    // 某一方在候选点里的最高单点分（强力档用于"对手最强反击"评估）
    bestPointScore(p, opponent, weak) {
      let best = 0;
      for (let r = 0; r < this.size; r++) {
        for (let c = 0; c < this.size; c++) {
          if (this.get(r, c) !== 0) continue;
          let near = false;
          for (let dr = -2; dr <= 2 && !near; dr++) {
            for (let dc = -2; dc <= 2; dc++) {
              if (this.get(r + dr, c + dc) === p || this.get(r + dr, c + dc) === opponent) { near = true; break; }
            }
          }
          if (!near) continue;
          const s = this.evaluatePoint(r, c, p, weak);
