    evaluatePoint(r, c, p, weak = false) {
      const dirs = [[0, 1], [1, 0], [1, 1], [1, -1]];
      let total = 0;
      for (const [dr, dc] of dirs) {
        let count = 1, openEnds = 0;
        let i = 1;
        // 扫描上限放到 10：必须能识别"长连（6 子及以上）"，否则把 6 连误判成 5 连会给错分
        while (i < 10 && this.get(r + dr * i, c + dc * i) === p) { count++; i++; }
        if (this.get(r + dr * i, c + dc * i) === 0) openEnds++;
        let j = 1;
        while (j < 10 && this.get(r - dr * j, c - dc * j) === p) { count++; j++; }
        if (this.get(r - dr * j, c - dc * j) === 0) openEnds++;

        if (count === 5) total += 100000;
        else if (count > 5) total -= 60000; // 长连禁手：6 子及以上判负，AI 也要避免下成长连
        else if (count === 4) total += openEnds === 2 ? 10000 : 1500;
        else if (count === 3) total += weak ? (openEnds === 2 ? 150 : 120) : (openEnds === 2 ? 1000 : 150); // 快速档把双活三当普通活三看
        else if (count === 2) total += openEnds === 2 ? 100 : 15;
        else if (count === 1 && openEnds === 2) total += 5;
      }
      return total;
    }
  }

  // 2. 中国象棋引擎 (极小极大 + α-β 剪枝 + MVV-LVA + 置换表 + 杀手启发 + 精细评估)
