            if (c >= 2 && c <= 6) val += 20;
          }
          if (type === 'R') {
            let openFile = true;
            for (let rr = 0; rr < 10; rr++) {
              if (rr !== r && this.board[rr][c]) { openFile = false; break; }
            }
            if (openFile) val += 35; // 通路车
