          }
          if (type === 'K') {
            if (c >= 3 && c <= 5) val += 20;
          }
          if (type === 'A' || type === 'B') {
            const inPalace = (isRed ? r >= 7 : r <= 2) && (c >= 3 && c <= 5);
            if (inPalace) val += 25; // 九宫内防守价值
          }

          if (isMyPiece) {
