            if (np && ((color === 'R' && this.isRed(np)) || (color === 'B' && this.isBlack(np)))) guardCount++;
          }
        }
        if (guardCount === 0) score -= 200;
        else if (guardCount === 1) score -= 60;
      }

      return score;
    }
    alphabeta(depth, alpha, beta, isMaximizing, color, startTime, maxTime) {
      if (startTime != null && maxTime != null && Date.now() - startTime > maxTime) { this.searchAborted = true; return this.evaluateBoard(color); }
      const origAlpha = alpha, origBeta = beta;
      const hash = this.getBoardHash();
