            this.killerMoves[depth].unshift(m);
            if (this.killerMoves[depth].length > 2) this.killerMoves[depth].pop();
            break;
          }
        }
        // 边界标记必须用"进入函数时的原始窗口"判断：alpha/beta 在循环里已被更新，
        // 用更新后的值判断会让最大化分支恒为 upper、最小化分支恒为 lower，永远存不到 exact。
        const flag = maxEval <= origAlpha ? 'upper' : maxEval >= origBeta ? 'lower' : 'exact';
        boardTTStore(this, hash, depth, maxEval, bestMove, flag);
        return maxEval;
      } else {
        let minEval = Infinity;
