  // 海战棋回合是链式 setTimeout；统一登记，退出/重开时清除，避免 engine 置空后回调抛 TypeError
  function bsScheduleTurn(fn, ms) {
    if (bsTurnTimer) { clearTimeout(bsTurnTimer); bsTurnTimer = null; }
    bsTurnTimer = setTimeout(() => { bsTurnTimer = null; fn(); }, ms);
