  class BattleshipEngine {
    constructor() {
      this.size = 10;
      this.playerBoard = new Array(100).fill(0);
      this.aiBoard = new Array(100).fill(0);
      this.playerShips = [];
      this.aiShips = [];
      this.playerAttacks = new Array(100).fill(-1); // -1 未攻击, 0 脱靶, 1 命中（攻击敌方海域记录）
      this.aiAttacks = new Array(100).fill(-1); // AI 攻击我方海域记录
      this.playerBlocked = new Array(100).fill(false); // 我导弹封锁敌方海域格
      this.aiBlocked = new Array(100).fill(false); // AI 导弹封锁我方海域格
      this.playerRemain = { carrier: 1, battleship: 1, cruiser: 1, destroyer: 3, submarine: 3 };
      this.aiRemain = { carrier: 1, battleship: 1, cruiser: 1, destroyer: 3, submarine: 3 };
      this.playerSkills = [];
      this.aiSkills = [];
      this.playerSkillUsed = {};
      this.aiSkillUsed = {};
      this.playerScanned = [];
      this.aiScanned = [];
      this.playerSmoke = [];
      this.aiSmoke = [];
      this.aiJammer = 0; // 我方干扰后，AI 下一次普通炮击随机
      this.playerJammer = 0; // AI 干扰后，我方下一次普通炮击随机
      this.turn = 'P';
      this.winner = null; // 'P' | 'A'
      this.phase = 'setup'; // 'setup' | 'battle'
      this.history = [];
      this.log = [];
    }
    allShipsPlaced(whose) {
      const r = whose === 'P' ? this.playerRemain : this.aiRemain;
      return Object.keys(r).every(k => r[k] <= 0);
    }
    allShipsSunk(whose) {
      const ships = whose === 'P' ? this.playerShips : this.aiShips;
      return ships.length > 0 && ships.every(s => s.hits.every(h => h === true));
    }
  }

  function bsSerializeBattleship(e) {
    return {
      phase: e.phase,
      playerBoard: e.playerBoard,
