    e.aiBoard = s.aiBoard || e.aiBoard;
    e.playerShips = s.playerShips || [];
    e.aiShips = s.aiShips || [];
    e.playerAttacks = s.playerAttacks || e.playerAttacks;
    e.aiAttacks = s.aiAttacks || e.aiAttacks;
