    e.aiSunkSizes = s.aiSunkSizes || [];
    e.playerBlocked = s.playerBlocked || e.playerBlocked;
    e.aiBlocked = s.aiBlocked || e.aiBlocked;
    e.playerRemain = s.playerRemain || e.playerRemain;
