  function bsShipCellIndices(r, c, size, ori) {
    const arr = [];
    const half = Math.floor(size / 2);
    for (let i = 0; i < size; i++) {
      const off = i - half;
      const rr = ori === 'H' ? r : r + off;
      const cc = ori === 'H' ? c + off : c;
      if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) return null;
      arr.push(rr * 10 + cc);
    }
    return arr;
  }

  function bsPickRandomSkills(n) {
    n = n || 3;
    const ids = BS_SKILL_DEFS.map(s => s.id);
    for (let i = ids.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      const t = ids[i]; ids[i] = ids[j]; ids[j] = t;
    }
    return ids.slice(0, n);
  }

  function bsRandomPlaceShips(whose) {
    const e = boardGame.engine;
    const board = whose === 'P' ? e.playerBoard : e.aiBoard;
    const ships = whose === 'P' ? e.playerShips : e.aiShips;
    const remain = whose === 'P' ? e.playerRemain : e.aiRemain;
    const defs = BS_SHIP_DEFS.slice().sort(() => Math.random() - 0.5);
    for (const def of defs) {
      let placed = 0;
      let guard = 0;
      while (placed < def.count && guard++ < 5000) {
        const ori = Math.random() < 0.5 ? 'H' : 'V';
        const r = Math.floor(Math.random() * 10);
        const c = Math.floor(Math.random() * 10);
        const cells = bsShipCellIndices(r, c, def.size, ori);
        if (!cells) continue;
        if (!cells.every(idx => board[idx] === 0)) continue;
        cells.forEach(idx => board[idx] = 1);
        ships.push({ defId: def.id, name: def.name, size: def.size, cells: cells.slice(), hits: cells.map(() => false) });
        placed++;
      }
    }
  }

  function bsApplyShotOn(whose, idx) {
    const e = boardGame.engine;
    const board = whose === 'A' ? e.aiBoard : e.playerBoard;
    const ships = whose === 'A' ? e.aiShips : e.playerShips;
    if (board[idx] !== 1) return { hit: false, sunk: false, shipName: '', shipSize: 0 };
    for (const s of ships) {
      const k = s.cells.indexOf(idx);
      if (k >= 0) {
        if (!s.hits[k]) s.hits[k] = true;
        // 舰种与尺寸属于公开信息（游戏中会公告"击沉了你的【航空母舰】"），供 AI 消歧使用
        return { hit: true, sunk: s.hits.every(h => h), shipName: s.name, shipSize: s.size };
      }
    }
    return { hit: false, sunk: false, shipName: '', shipSize: 0 };
  }

  function bsIdxInSmoke(idx, list) {
    const r = Math.floor(idx / 10), c = idx % 10;
    return list.some(s => r >= s.r0 && r <= s.r0 + 2 && c >= s.c0 && c <= s.c0 + 2);
  }

  function bsOppShort() {
    return (boardGame.opponent && boardGame.opponent.name) || '对手';
  }

  const BS_FX_CSS = `
    <style>
      @keyframes bsSpin { to { transform: rotate(360deg); } }
      @keyframes bsBoom { 0%{transform:scale(.3);opacity:0;} 40%{transform:scale(1.25);opacity:1;} 100%{transform:scale(1.7);opacity:0;} }
      @keyframes bsJam { 0%{transform:scale(.7);opacity:0;} 35%{opacity:1;transform:scale(1.15);} 100%{transform:scale(1.5);opacity:0;} }
      @keyframes bsFlyTop { 0%{top:-16px;} 100%{top:calc(100% - 40px);} }
      @keyframes bsHit { 0%{transform:scale(1);box-shadow:0 0 0 0 rgba(239,68,68,.95);background:#FEE2E2;} 40%{transform:scale(1.45);box-shadow:0 0 16px 8px rgba(239,68,68,.95);background:#FCA5A5;} 100%{transform:scale(1);box-shadow:0 0 0 0 rgba(239,68,68,0);} }
      @keyframes bsMiss { 0%{box-shadow:0 0 0 0 rgba(255,255,255,.95);background:#FFFFFF;} 50%{box-shadow:0 0 14px 8px rgba(255,255,255,.9);} 100%{box-shadow:0 0 0 0 rgba(255,255,255,0);} }
      @keyframes bsFrame { 0%,100%{box-shadow:inset 0 0 0 2px rgba(16,185,129,0);} 50%{box-shadow:inset 0 0 0 2px rgba(16,185,129,.95);background:rgba(16,185,129,.22);} }
      @keyframes bsBlock { 0%,100%{box-shadow:inset 0 0 0 2px rgba(100,116,139,0);} 50%{box-shadow:inset 0 0 0 2px rgba(100,116,139,.95);} }
      @keyframes bsSmoke { 0%{box-shadow:inset 0 0 20px 12px rgba(156,163,175,.9);opacity:.9;} 100%{box-shadow:inset 0 0 0 0 rgba(156,163,175,0);opacity:0;} }
      .bs-fx-hit { animation: bsHit .65s ease-out forwards; position: relative; z-index: 6; }
      .bs-fx-miss { animation: bsMiss .65s ease-out forwards; position: relative; z-index: 6; }
      .bs-fx-frame { animation: bsFrame .8s ease-in-out 2 forwards; position: relative; z-index: 6; }
      .bs-fx-block { animation: bsBlock .8s ease-in-out 2 forwards; position: relative; z-index: 6; }
      .bs-fx-smoke { animation: bsSmoke .9s ease-out forwards; position: relative; z-index: 6; }
      .bs-fx-plane { position: absolute; left: 0; top: -16px; width: 100%; text-align: center; animation: bsFlyTop .75s linear forwards; font-size: 22px; line-height: 1; }
    </style>`;

  function bsFxCellEl(board, r, c) {
    const grid = sheet && sheet.querySelector('#bs-grid-' + board);
    if (!grid) return null;
    return grid.querySelector('[data-bs-cell="' + r + '-' + c + '"]');
  }

  function bsApplyCellFx(board, cells) {
    cells.forEach(o => {
      const el = bsFxCellEl(board, o.r, o.c);
      if (el) { el.classList.remove('bs-fx-hit', 'bs-fx-miss', 'bs-fx-frame', 'bs-fx-block', 'bs-fx-smoke'); void el.offsetWidth; el.classList.add(o.cls); }
    });
  }

  function bsOverlay(html, style, dur) {
    if (!sheet) return; // sheet 失效时静默跳过特效，绝不能把 bsResolving 卡在 true
    const ov = document.createElement('div');
    ov.style.cssText = 'position:absolute;z-index:60;pointer-events:none;' + style;
    ov.innerHTML = html;
    sheet.appendChild(ov);
    setTimeout(() => { try { ov.remove(); } catch (e) {} }, dur || 900);
  }

  function bsFxBoardRect(board) {
    const grid = sheet && sheet.querySelector('#bs-grid-' + board);
    if (!grid) return null;
    const gr = grid.getBoundingClientRect();
    const sr = sheet.getBoundingClientRect();
    return { left: gr.left - sr.left, top: gr.top - sr.top, width: gr.width, height: gr.height };
  }

  function bsFxCellCenter(board, r, c) {
    const el = bsFxCellEl(board, r, c);
    if (!el) return null;
    const er = el.getBoundingClientRect();
    const sr = sheet.getBoundingClientRect();
    return { x: er.left + er.width / 2 - sr.left, y: er.top + er.height / 2 - sr.top, w: er.width };
  }

  function bsFxColumnRect(board, c) {
    const grid = sheet && sheet.querySelector('#bs-grid-' + board);
    const el = bsFxCellEl(board, 0, c);
    if (!grid || !el) return null;
    const gr = grid.getBoundingClientRect();
    const er = el.getBoundingClientRect();
    const sr = sheet.getBoundingClientRect();
    return { centerX: er.left + er.width / 2 - sr.left, top: gr.top - sr.top, height: gr.height, width: er.width };
  }

  function bsBoomOverlay(board, r, c) {
    const p = bsFxCellCenter(board, r, c);
    if (!p) return;
    bsOverlay('<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:26px;line-height:1;text-shadow:0 0 10px rgba(239,68,68,.9);animation:bsBoom .55s ease-out forwards;">💥</div>', 'left:' + (p.x - p.w / 2) + 'px;top:' + (p.y - p.w / 2) + 'px;width:' + p.w + 'px;height:' + p.w + 'px;', 600);
  }

  function bsRadarOverlay(board, r, c) {
    const p = bsFxCellCenter(board, r, c);
    if (!p) return;
    const d = p.w * 3.2;
    bsOverlay('<div style="width:100%;height:100%;border-radius:50%;background:conic-gradient(from 0deg, rgba(16,185,129,.55) 0deg 45deg, rgba(16,185,129,.12) 45deg 70deg, transparent 70deg 360deg);border:2px solid rgba(16,185,129,.8);animation:bsSpin 1s linear infinite;display:flex;align-items:center;justify-content:center;color:rgba(16,185,129,.9);font-size:20px;">📡</div>', 'left:' + (p.x - d / 2) + 'px;top:' + (p.y - d / 2) + 'px;width:' + d + 'px;height:' + d + 'px;', 1000);
  }

  function bsReconOverlay(board, c) {
    const col = bsFxColumnRect(board, c);
    if (!col) return;
    bsOverlay('<div class="bs-fx-plane">🛩️</div>', 'left:' + (col.centerX - col.width / 2) + 'px;top:' + col.top + 'px;width:' + col.width + 'px;height:' + col.height + 'px;overflow:hidden;', 850);
  }

  function bsJammerOverlay() {
    bsOverlay('<div style="font-size:52px;line-height:1;filter:drop-shadow(0 0 14px #F59E0B);text-align:center;animation:bsJam .9s ease-out forwards;">📶</div>', 'left:50%;top:42%;transform:translate(-50%,-50%);width:80px;height:80px;', 950);
  }

  function bsPlayFx(fx) {
    if (!fx) return;
    switch (fx.type) {
      case 'shot': {
        const r = Math.floor(fx.idx / 10), c = fx.idx % 10;
        bsApplyCellFx(fx.board, [{ r, c, cls: fx.hit ? 'bs-fx-hit' : 'bs-fx-miss' }]);
        if (fx.hit) bsBoomOverlay(fx.board, r, c);
        break;
      }
      case 'depth': {
        const cells = (fx.shots || []).map(s => { const r = Math.floor(s.idx / 10), c = s.idx % 10; return { r, c, cls: s.hit ? 'bs-fx-hit' : 'bs-fx-miss' }; });
        bsApplyCellFx(fx.board, cells);
        break;
      }
      case 'missile': {
        const r = Math.floor(fx.idx / 10), c = fx.idx % 10;
        bsApplyCellFx(fx.board, [{ r, c, cls: fx.hit ? 'bs-fx-hit' : 'bs-fx-miss' }]);
        if (fx.hit) bsBoomOverlay(fx.board, r, c);
        if (fx.blocked && fx.blocked.length) {
          bsApplyCellFx(fx.board, fx.blocked.map(idx => { const rr = Math.floor(idx / 10), cc = idx % 10; return { r: rr, c: cc, cls: 'bs-fx-block' }; }));
        }
        break;
      }
      case 'radar': {
        const cs = [];
        for (let rr = fx.r0; rr <= fx.r0 + 2; rr++) for (let cc = fx.c0; cc <= fx.c0 + 2; cc++) cs.push({ r: rr, c: cc, cls: 'bs-fx-frame' });
        bsApplyCellFx(fx.board, cs);
        bsRadarOverlay(fx.board, fx.r0 + 1, fx.c0 + 1);
        break;
      }
      case 'recon': {
        const cs = [];
        for (let rr = 0; rr < 10; rr++) cs.push({ r: rr, c: fx.c, cls: 'bs-fx-frame' });
        bsApplyCellFx(fx.board, cs);
        bsReconOverlay(fx.board, fx.c);
        break;
      }
      case 'smoke': {
        const cs = [];
        for (let rr = fx.r0; rr <= fx.r0 + 2; rr++) for (let cc = fx.c0; cc <= fx.c0 + 2; cc++) cs.push({ r: rr, c: cc, cls: 'bs-fx-smoke' });
        bsApplyCellFx(fx.board, cs);
        break;
      }
      case 'jammer': {
        bsJammerOverlay();
        break;
      }
    }
  }

  function bsResolvePlayerAction(fx) {
    const e = boardGame && boardGame.engine;
    if (!e) { bsResolving = false; return; }
    bsResolving = true;
    try { renderBattleshipBattle(); bsPlayFx(fx); } catch (err) { console.warn('[游戏扩展][海战棋] 特效渲染异常：', err); }
    if (e.allShipsSunk('A')) { e.winner = 'P'; clearSavedBoardGame('battleship'); bsResolving = false; bsEndGame(); return; }
    bsScheduleTurn(() => { bsResolving = false; bsEndPlayerTurn(); }, 820);
  }

  function bsResolveAIAction(fx) {
    const e = boardGame && boardGame.engine;
    if (!e) { bsResolving = false; return; }
    bsResolving = true;
    try { renderBattleshipBattle(); bsPlayFx(fx); } catch (err) { console.warn('[游戏扩展][海战棋] 特效渲染异常：', err); }
    if (e.allShipsSunk('P')) { e.winner = 'A'; clearSavedBoardGame('battleship'); bsResolving = false; bsEndGame(); return; }
    bsScheduleTurn(() => { bsResolving = false; bsEndAITurn(); }, 820);
  }

  // ========== 技能实现 ==========
  function bsSkillRadar(who, r, c) {
    const e = boardGame.engine;
    const r0 = r - 1, c0 = c - 1;
    if (r0 < 0 || c0 < 0 || r0 + 2 > 9 || c0 + 2 > 9) { if (who === 'P') showToast('3×3 区域不能超出棋盘边界'); return { ok: false }; }
    const scanned = who === 'P' ? e.playerScanned : e.aiScanned;
    if (scanned.some(s => s.r0 === r0 && s.c0 === c0)) { if (who === 'P') showToast('不能重复扫描同一区域'); return { ok: false }; }
    scanned.push({ r0, c0 });
    const board = who === 'P' ? e.aiBoard : e.playerBoard;
    const smoke = who === 'P' ? e.aiSmoke : e.playerSmoke;
    let count = 0;
    for (let rr = r0; rr <= r0 + 2; rr++) for (let cc = c0; cc <= c0 + 2; cc++) {
      const idx = rr * 10 + cc;
      if (board[idx] !== 1) continue;
      if (bsIdxInSmoke(idx, smoke)) continue;
      count++;
    }
    e.history.push({ who, kind: 'radar', r0, c0, count });
    if (who === 'P') {
      e.log.push('你的雷达扫描完成：该区域共有 ' + count + ' 个船体格子。');
      e.log.push(bsOppShort() + '：哼，居然动用雷达探查我的海域，可惜只能知道数量，休想锁定我的船！');
    } else {
      e.log.push(bsOppShort() + ' 使用雷达扫描了你的海域…');
    }
    return { ok: true, fx: { type: 'radar', board: who === 'P' ? 'enemy' : 'own', r0, c0 } };
  }

  function bsSkillRecon(who, r, c) {
    const e = boardGame.engine;
    const board = who === 'P' ? e.aiBoard : e.playerBoard;
    const smoke = who === 'P' ? e.aiSmoke : e.playerSmoke;
    let count = 0;
    for (let i = 0; i < 10; i++) {
      const idx = i * 10 + c;
      if (board[idx] === 1 && !bsIdxInSmoke(idx, smoke)) count++;
    }
    const label = String.fromCharCode(65 + c) + ' 列';
    e.history.push({ who, kind: 'recon', c, count });
    if (who === 'P') {
      e.log.push('侦察机侦查完成：' + label + '共有 ' + count + ' 个船体格子。');
    } else {
      e.log.push(bsOppShort() + ' 派出侦察机，侦查了' + label + '。');
    }
    return { ok: true, fx: { type: 'recon', board: who === 'P' ? 'enemy' : 'own', c } };
  }

  function bsSkillDepth(who, r, c) {
    const e = boardGame.engine;
    const isPlayer = who === 'P';
    const attacks = isPlayer ? e.playerAttacks : e.aiAttacks;
    const blocked = isPlayer ? e.playerBlocked : e.aiBlocked;
    const target = isPlayer ? 'A' : 'P';
    let hits = 0, sunkShip = '';
    const shots = [];
    for (const d of BS_DIRS) {
      const rr = r + d[0], cc = c + d[1];
      if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) continue;
      const idx = rr * 10 + cc;
      if (attacks[idx] !== -1 || blocked[idx]) continue;
      const res = bsApplyShotOn(target, idx);
      attacks[idx] = res.hit ? 1 : 0;
      if (res.hit) hits++;
      if (res.sunk) sunkShip = res.shipName;
      if (res.sunk && !isPlayer) bsAIRecordSunk(e, idx, res.shipSize); // 深水炸弹击沉也要记入公开情报
      shots.push({ idx, hit: res.hit });
      e.history.push({ who, kind: 'depth', r: rr, c: cc, hit: res.hit, sunk: res.sunk });
    }
    if (isPlayer) {
      e.log.push('你投下深水炸弹（十字4格）：命中 ' + hits + ' 格' + (sunkShip ? '，击沉【' + sunkShip + '】！' : '。'));
    } else {
      e.log.push(bsOppShort() + ' 投下深水炸弹：命中 ' + hits + ' 格' + (sunkShip ? '，击沉你的【' + sunkShip + '】！' : '。'));
    }
    return { ok: true, fx: { type: 'depth', board: who === 'P' ? 'enemy' : 'own', shots } };
  }

  function bsSkillMissile(who, r, c) {
    const e = boardGame.engine;
    const isPlayer = who === 'P';
    const attacks = isPlayer ? e.playerAttacks : e.aiAttacks;
    const blocked = isPlayer ? e.playerBlocked : e.aiBlocked;
    const idx = r * 10 + c;
    if (attacks[idx] !== -1 || blocked[idx]) { if (isPlayer) showToast(blocked[idx] ? '该格已被封锁' : '该格已攻击过'); return { ok: false }; } // 封锁格同样不允许落点
    const res = bsApplyShotOn(isPlayer ? 'A' : 'P', idx);
    attacks[idx] = res.hit ? 1 : 0;
    if (res.sunk && !isPlayer) bsAIRecordSunk(e, idx, res.shipSize); // 导弹击沉也要记入公开情报
    const blockList = [];
    for (const d of BS_DIRS) {
      const rr = r + d[0], cc = c + d[1];
      if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) continue;
      const n = rr * 10 + cc;
      if (attacks[n] === -1) { blocked[n] = true; blockList.push(n); }
    }
    e.history.push({ who, kind: 'missile', r, c, hit: res.hit, sunk: res.sunk });
    if (isPlayer) {
      e.log.push('你发射导弹：' + (res.hit ? '命中' + (res.sunk ? '，击沉【' + res.shipName + '】！' : '！') : '脱靶。') + ' 并封锁了周围未探测格。');
    } else {
      e.log.push(bsOppShort() + ' 发射导弹：' + (res.hit ? '命中' + (res.sunk ? '，击沉你的【' + res.shipName + '】！' : '！') : '脱靶。'));
    }
    return { ok: true, fx: { type: 'missile', board: who === 'P' ? 'enemy' : 'own', idx, hit: res.hit, blocked: blockList } };
  }

  function bsSkillJammer(who) {
    const e = boardGame.engine;
    if (who === 'P') {
      e.aiJammer++;
      e.log.push('你释放电子干扰，对手下一次炮击将被随机化！');
    } else {
      e.playerJammer++;
      e.log.push(bsOppShort() + ' 释放电子干扰，你的下一次炮击将被随机化！');
    }
    e.history.push({ who, kind: 'jammer' });
    return { ok: true, fx: { type: 'jammer' } };
  }

  function bsSkillSmoke(who, r, c) {
    const e = boardGame.engine;
    const r0 = r - 1, c0 = c - 1;
    if (r0 < 0 || c0 < 0 || r0 + 2 > 9 || c0 + 2 > 9) { if (who === 'P') showToast('3×3 区域不能超出棋盘边界'); return { ok: false }; }
    const list = who === 'P' ? e.playerSmoke : e.aiSmoke;
    list.push({ r0, c0 });
    e.history.push({ who, kind: 'smoke', r0, c0 });
    if (who === 'P') { e.log.push('你释放烟幕弹，隐藏己方 3×3 区域（仅防侦查）。'); }
    else { e.log.push(bsOppShort() + ' 释放了烟幕弹。'); }
    return { ok: true, fx: who === 'P' ? { type: 'smoke', board: 'own', r0, c0 } : null };
  }

  // ========== 玩家动作 ==========
  function bsPlayerShoot(idx) {
    const e = boardGame.engine;
    if (e.turn !== 'P' || e.winner) return;
    if (e.playerAttacks[idx] !== -1 || e.playerBlocked[idx]) { showToast('该坐标不能重复射击'); return; }
    let finalIdx = idx;
    let jammed = false;
    if (e.playerJammer > 0) {
      e.playerJammer--;
      jammed = true;
      finalIdx = bsRandomUnshotCell(e.playerAttacks, e.playerBlocked);
      if (finalIdx < 0) { e.turn = 'A'; renderBattleshipBattle(); return; }
    }
    const r = Math.floor(finalIdx / 10), c = finalIdx % 10;
    const res = bsApplyShotOn('A', finalIdx);
    e.playerAttacks[finalIdx] = res.hit ? 1 : 0;
    e.history.push({ who: 'P', kind: 'shot', r, c, hit: res.hit, sunk: res.sunk });
    if (jammed) e.log.push('⚡ 电子干扰生效：你的炮击被随机引导到了 ' + bsCoordName(r, c) + '。');
    if (res.sunk) e.log.push('命中 ' + bsCoordName(r, c) + '，击沉了对方的【' + res.shipName + '】！');
    else if (res.hit) e.log.push('炮击 ' + bsCoordName(r, c) + '：命中！');
    else e.log.push('炮击 ' + bsCoordName(r, c) + '：未命中。');
    bsResolvePlayerAction({ type: 'shot', board: 'enemy', idx: finalIdx, hit: res.hit });
  }

  function bsExecutePlayerSkill(skillId, r, c) {
    const e = boardGame.engine;
    if (e.playerSkillUsed[skillId] || e.turn !== 'P') return;
    let res = { ok: false };
    if (skillId === 'radar') res = bsSkillRadar('P', r, c);
    else if (skillId === 'recon') res = bsSkillRecon('P', r, c);
    else if (skillId === 'depth') res = bsSkillDepth('P', r, c);
    else if (skillId === 'missile') res = bsSkillMissile('P', r, c);
    else if (skillId === 'jammer') res = bsSkillJammer('P');
    else if (skillId === 'smoke') res = bsSkillSmoke('P', r, c);
    if (!res.ok) return;
    e.playerSkillUsed[skillId] = true;
    bsUI.armedSkill = null;
    bsResolvePlayerAction(res.fx);
  }

  function bsEndPlayerTurn() {
    const e = boardGame && boardGame.engine;
    if (!e) { bsResolving = false; return; }
    if (e.allShipsSunk('A')) { e.winner = 'P'; clearSavedBoardGame('battleship'); bsEndGame(); return; }
    e.turn = 'A';
    boardGame.isThinking = true;
    saveBoardGameState();
    renderBattleshipBattle();
    bsScheduleTurn(() => bsAITurn(), 650);
  }

  function bsEndAITurn() {
    const e = boardGame && boardGame.engine;
    if (!e) return; // 对局已退出（engine 置空）：挂起回调直接放弃
    if (e.allShipsSunk('P')) { e.winner = 'A'; clearSavedBoardGame('battleship'); bsEndGame(); return; }
    e.turn = 'P';
    boardGame.isThinking = false;
    saveBoardGameState();
    renderBattleshipBattle();
  }

  function bsRandomUnshotCell(attacks, blocked) {
    const cands = [];
    for (let i = 0; i < 100; i++) if (attacks[i] === -1 && !blocked[i]) cands.push(i);
    if (!cands.length) return -1;
    return cands[Math.floor(Math.random() * cands.length)];
  }

  function bsAiLevel() {
    // 优先读实时配置：玩家在设置里改难度后立即生效（读不到再退回对局内缓存）
    return liveAiLevel(loadBoardConfig, (boardGame && boardGame.aiLevel) || 'normal');
  }

  // ===== 海战棋公开情报（禁止开天眼） =====
  // AI 规则上只能知道：打过哪些格（aiAttacks：-1 未知 / 0 脱靶 / 1 命中）、封锁格、以及"哪条船被击沉"。
  // 旧实现直接读 e.playerShips（玩家真实船位）来判断"哪些命中属于未沉船"＝开天眼，
  // 这里改为按"击沉事件"累积：击沉瞬间用上下左右连通把该船全部命中格标记为已沉，尺寸取连通格数。
  function bsAIEnsureIntel(e) {
    if (!e.aiSunkCells || typeof e.aiSunkCells !== 'object') e.aiSunkCells = {};
    if (!Array.isArray(e.aiSunkSizes)) e.aiSunkSizes = [];
    return e;
  }
  function bsAIRecordSunk(e, hitIdx, size) {
    bsAIEnsureIntel(e);
    const known = Math.round(Number(size) || 0); // 已知击沉舰船尺寸（公开信息）；未知则退回连通推断
    // 收集连通命中格（不含已标记沉没的格子）
    const comp = [];
    const seen = new Set();
    const stack = [hitIdx];
    while (stack.length) {
      const idx = stack.pop();
      if (seen.has(idx) || e.aiSunkCells[idx]) continue;
      seen.add(idx);
      comp.push(idx);
      const r = Math.floor(idx / 10), c = idx % 10;
      for (const d of BS_DIRS) {
        const rr = r + d[0], cc = c + d[1];
        if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) continue;
        const n = rr * 10 + cc;
        if (e.aiAttacks[n] === 1 && !e.aiSunkCells[n] && !seen.has(n)) stack.push(n);
      }
    }
    let mark = comp;
    if (known > 0) {
      // 两船贴在一起时，连通块会把邻船的命中格也吞进来。
      // 用公开的击沉舰船尺寸消歧：优先取"穿过击沉点、长度恰为 size 的连续直线"（真实沉船必然共线），
      // 这样邻船的命中格不会被误标为已沉，AI 也不会漏掉本船的其他格。
      mark = null;
      if (comp.length === known) mark = comp;
      else if (comp.length > known) mark = bsAISunkLine(e, hitIdx, known, comp);
      if (!mark) {
        // 兜底：取距击沉点最近的 known 格，绝不多标
        const dist = (i) => Math.abs(Math.floor(i / 10) - Math.floor(hitIdx / 10)) + Math.abs(i % 10 - hitIdx % 10);
        mark = comp.slice().sort((a, b) => (dist(a) - dist(b)) || (a - b)).slice(0, known);
      }
    }
    for (const idx of mark) e.aiSunkCells[idx] = true;
    if (mark.length) e.aiSunkSizes.push(known > 0 ? known : mark.length);
  }
  // 在击沉点所在的行/列上，找长度恰为 size、全部命中且未沉、且包含击沉点的连续窗口。
  // 候选多个（两船贴在一起）时：优先选"标记后剩余命中格连通分量最少"的窗口，其次离击沉点最近，最后取起点最小（确定性）。
  function bsAISunkLine(e, hitIdx, size, comp) {
    const r0 = Math.floor(hitIdx / 10), c0 = hitIdx % 10;
    const cands = [];
    for (const d of [[0, 1], [1, 0]]) {
      let back = 0;
      while (true) {
        const r = r0 - d[0] * (back + 1), c = c0 - d[1] * (back + 1);
        if (r < 0 || r >= 10 || c < 0 || c >= 10) break;
        const n = r * 10 + c;
        if (e.aiAttacks[n] !== 1 || e.aiSunkCells[n]) break;
        back++;
      }
      let fwd = 0;
      while (true) {
        const r = r0 + d[0] * (fwd + 1), c = c0 + d[1] * (fwd + 1);
        if (r < 0 || r >= 10 || c < 0 || c >= 10) break;
        const n = r * 10 + c;
        if (e.aiAttacks[n] !== 1 || e.aiSunkCells[n]) break;
        fwd++;
      }
      // 只枚举"包含击沉点（偏移 0）"的窗口：start ∈ [-back, 0] 且窗口末端不超过前向链尾
      for (let start = -back; start <= 0 && start + size - 1 <= fwd; start++) {
        const cells = [];
        for (let k = 0; k < size; k++) {
          const r = r0 + d[0] * (start + k), c = c0 + d[1] * (start + k);
          cells.push(r * 10 + c);
        }
        cands.push(cells);
      }
    }
    if (!cands.length) return null;
    const dist = (i) => Math.abs(Math.floor(i / 10) - r0) + Math.abs(i % 10 - c0);
    const leftoverComps = (cells) => {
      const marked = new Set(cells);
      const rest = comp.filter(i => !marked.has(i));
      const seen = new Set();
      let groups = 0;
      for (const start of rest) {
        if (seen.has(start)) continue;
        groups++;
        const st = [start];
        while (st.length) {
          const cur = st.pop();
          if (seen.has(cur) || marked.has(cur)) continue;
          seen.add(cur);
          const r = Math.floor(cur / 10), c = cur % 10;
          for (const dd of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
            const rr = r + dd[0], cc = c + dd[1];
            if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) continue;
            const n = rr * 10 + cc;
            if (!marked.has(n) && comp.indexOf(n) !== -1 && !seen.has(n)) st.push(n);
          }
        }
      }
      return groups;
    };
    cands.sort((a, b) => {
      const ga = leftoverComps(a), gb = leftoverComps(b);
      if (ga !== gb) return ga - gb;
      const da = a.reduce((n, i) => n + dist(i), 0), db = b.reduce((n, i) => n + dist(i), 0);
      if (da !== db) return da - db;
      return a[0] - b[0];
    });
    return cands[0];
  }
  // 尚未击沉的命中格（AI 的唯一合法追击依据）
  function bsAIUnsunkHitCells(e) {
    bsAIEnsureIntel(e);
    const out = [];
    for (let i = 0; i < 100; i++) if (e.aiAttacks[i] === 1 && !e.aiSunkCells[i]) out.push(i);
    return out;
  }
  // 剩余舰船尺寸（由 BS_SHIP_DEFS 减去"已确认击沉"的尺寸得到，不再读玩家船位）
  function bsAIRemainingShipSizes(e) {
    bsAIEnsureIntel(e);
    const sizes = [];
    for (const def of BS_SHIP_DEFS) for (let i = 0; i < (def.count || 1); i++) sizes.push(def.size);
    for (const sz of e.aiSunkSizes) {
      const i = sizes.indexOf(sz);
      if (i !== -1) sizes.splice(i, 1);
    }
    return sizes;
  }

  // 强力：按剩余舰船尺寸做"排列枚举"概率密度选点。
  // 关键修正：只统计"不与已知脱靶格冲突、且必须覆盖所有已知命中格"的合法摆放，
  // 否则会把不可能的位置算进去、把可能的位置漏掉（旧算法既没排除脱靶格，也没锁定命中格）。
  function bsAIDensityShot() {
    const e = boardGame.engine;
    const sizes = bsAIRemainingShipSizes(e);
    const hitCells = bsAIUnsunkHitCells(e);
    const scores = new Array(100).fill(0);
    for (const size of sizes) {
      for (const dir of [[0, 1], [1, 0]]) {
        for (let r = 0; r < 10; r++) {
          for (let c = 0; c < 10; c++) {
            const cells = [];
            let ok = true;
            for (let k = 0; k < size; k++) {
              const rr = r + dir[0] * k, cc = c + dir[1] * k;
              if (rr > 9 || cc > 9) { ok = false; break; }
              const idx = rr * 10 + cc;
              if (e.aiAttacks[idx] === 0 || e.aiBlocked[idx]) { ok = false; break; } // 已脱靶/已封锁的格必须剔除
              cells.push(idx);
            }
            if (!ok) continue;
            // 若已有命中格，摆放必须覆盖至少一个命中格（否则与已知情报矛盾）
            if (hitCells.length) {
              let covers = false;
              for (const h of hitCells) if (cells.indexOf(h) !== -1) { covers = true; break; }
              if (!covers) continue;
            }
            for (const idx of cells) scores[idx] += 1;
          }
        }
      }
    }
    // 另外：命中格周围的"不确定区域"额外加权，便于把已受伤的船打沉
    for (const h of hitCells) {
      const r = Math.floor(h / 10), c = h % 10;
      for (const d of BS_DIRS) {
        const rr = r + d[0], cc = c + d[1];
        if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) continue;
        const n = rr * 10 + cc;
        if (e.aiAttacks[n] === -1 && !e.aiBlocked[n]) scores[n] += 6;
      }
    }
    let best = -1, bestScore = -1;
    for (let i = 0; i < 100; i++) {
      if (e.aiAttacks[i] !== -1 || e.aiBlocked[i]) continue;
      // 强力档确定性：并列时取坐标最小者，不加随机抖动
      if (scores[i] > bestScore) { bestScore = scores[i]; best = i; }
    }
    return best >= 0 ? best : bsRandomUnshotCell(e.aiAttacks, e.aiBlocked);
  }

  function bsAIChooseShot(forcedRandom) {
    const e = boardGame.engine;
    const level = bsAiLevel();
    if (forcedRandom) return bsRandomUnshotCell(e.aiAttacks, e.aiBlocked);
    const hunt = [];
    // 追击只用公开情报：尚未击沉的命中格 + 其相邻未探格
    for (const ci of bsAIUnsunkHitCells(e)) {
      const r = Math.floor(ci / 10), c = ci % 10;
      for (const d of BS_DIRS) {
        const rr = r + d[0], cc = c + d[1];
        if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) continue;
        const n = rr * 10 + cc;
        if (e.aiAttacks[n] === -1 && !e.aiBlocked[n]) hunt.push(n);
      }
    }
    if (hunt.length) {
      const uniq = Array.from(new Set(hunt));
      // 快速档：只有 50% 概率追击相邻格，而且只追 1 格就放弃（新手"打一枪换一个地方"）
      if (level === 'fast') {
        if (Math.random() < 0.5) return bsRandomUnshotCell(e.aiAttacks, e.aiBlocked);
        return uniq[Math.floor(Math.random() * uniq.length)];
      }
      // 强力档确定性：优先追"与最多未沉命中格相邻"的格，并列取坐标最小（不加随机）
      if (level === 'strong') {
        const unsunk = bsAIUnsunkHitCells(e);
        let best = uniq[0], bestAdj = -1;
        for (const n of uniq) {
          const rr0 = Math.floor(n / 10), cc0 = n % 10;
          let adj = 0;
          for (const d of BS_DIRS) {
            const rr = rr0 + d[0], cc = cc0 + d[1];
            if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) continue;
            if (unsunk.indexOf(rr * 10 + cc) !== -1) adj++;
          }
          if (adj > bestAdj || (adj === bestAdj && n < best)) { bestAdj = adj; best = n; }
        }
        return best;
      }
      return uniq[Math.floor(Math.random() * uniq.length)];
    }
    if (level === 'fast') return bsRandomUnshotCell(e.aiAttacks, e.aiBlocked);
    if (level === 'strong') return bsAIDensityShot();
    const cands = [];
    for (let i = 0; i < 100; i++) {
      if (e.aiAttacks[i] !== -1 || e.aiBlocked[i]) continue;
      const r = Math.floor(i / 10), c = i % 10;
      if ((r + c) % 2 === 0) cands.push(i);
    }
    if (!cands.length) return bsRandomUnshotCell(e.aiAttacks, e.aiBlocked);
    return cands[Math.floor(Math.random() * cands.length)];
  }

  function bsAIShoot(forcedRandom) {
    const e = boardGame.engine;
    const idx = bsAIChooseShot(forcedRandom);
    if (idx < 0) { bsEndAITurn(); return; }
    const r = Math.floor(idx / 10), c = idx % 10;
    const res = bsApplyShotOn('P', idx);
    e.aiAttacks[idx] = res.hit ? 1 : 0;
    if (res.sunk) bsAIRecordSunk(e, idx, res.shipSize); // 记入公开情报：该船已沉（尺寸+占用格）
    e.history.push({ who: 'A', kind: 'shot', r, c, hit: res.hit, sunk: res.sunk });
    if (res.sunk) e.log.push(bsOppShort() + ' 炮击 ' + bsCoordName(r, c) + '，击沉了你的【' + res.shipName + '】！');
    else if (res.hit) e.log.push(bsOppShort() + ' 炮击 ' + bsCoordName(r, c) + '：命中！');
    else e.log.push(bsOppShort() + ' 炮击 ' + bsCoordName(r, c) + '：未命中。');
    bsResolveAIAction({ type: 'shot', board: 'own', idx, hit: res.hit });
  }

  function bsAIUseSkill(usable) {
    const e = boardGame.engine;
    const lvl = bsAiLevel();
    const hasHitNotSunk = bsAIUnsunkHitCells(e).length > 0; // 公开情报：还有未击沉的命中格
    // 强力档技能使用顺序有策略：有"未击沉且已命中"的敌舰时优先深水炸弹/导弹（补刀沉船）
    let order = usable.slice();
    if (lvl === 'strong') {
      const pri = { depth: 0, missile: 1, radar: 2, recon: 3, jammer: 4, smoke: 5 };
      order.sort((a, b) => (pri[a] === undefined ? 9 : pri[a]) - (pri[b] === undefined ? 9 : pri[b]));
      if (hasHitNotSunk) {
        const finish = order.filter(id => id === 'depth' || id === 'missile');
        if (finish.length) order = finish;
      }
    }
    const weighted = [];
    for (const id of order) {
      let w = 1;
      if (hasHitNotSunk && (id === 'depth' || id === 'missile')) w = 4;
      else if (id === 'radar' || id === 'recon') w = 2;
      else if (id === 'jammer' || id === 'smoke') w = 1;
      for (let i = 0; i < w; i++) weighted.push(id);
    }
    // 强力档确定性：直接取策略排序后的首选技能；其它档位按权重随机
    const pick = lvl === 'strong' ? order[0] : weighted[Math.floor(Math.random() * weighted.length)];
    let res = { ok: false };
    // 强力档：补刀技能要有准头——以"未击沉的命中格"相邻的未探格为目标（已命中格不能再作为落点：
    // 导弹对已攻击格会直接 ok:false 白跑一次），否则"优先深水炸弹/导弹"的排序没有任何战术收益。
    // 其它档位沿用随机落点。
    const aimTargets = [];
    const unsunkHits = lvl === 'strong' ? bsAIUnsunkHitCells(e) : [];
    if (lvl === 'strong') {
      for (const ci of unsunkHits) {
        const rr0 = Math.floor(ci / 10), cc0 = ci % 10;
        for (const d of BS_DIRS) {
          const rr = rr0 + d[0], cc = cc0 + d[1];
          if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) continue;
          const n = rr * 10 + cc;
          if (e.aiAttacks[n] !== -1 || e.aiBlocked[n]) continue;
          if (aimTargets.indexOf(n) === -1) aimTargets.push(n);
        }
      }
    }
    let aim = -1;
    if (aimTargets.length) {
      if (lvl === 'strong') {
        // 确定性：优先"与最多未沉命中格相邻"的落点，并列取坐标最小
        let best = aimTargets[0], bestAdj = -1;
        for (const n of aimTargets) {
          const rr0 = Math.floor(n / 10), cc0 = n % 10;
          let adj = 0;
          for (const d of BS_DIRS) {
            const rr = rr0 + d[0], cc = cc0 + d[1];
            if (rr < 0 || rr >= 10 || cc < 0 || cc >= 10) continue;
            if (unsunkHits.indexOf(rr * 10 + cc) !== -1) adj++;
          }
          if (adj > bestAdj || (adj === bestAdj && n < best)) { bestAdj = adj; best = n; }
        }
        aim = best;
      } else {
        aim = aimTargets[Math.floor(Math.random() * aimTargets.length)];
      }
    }
    let r = aim >= 0 ? Math.floor(aim / 10) : Math.floor(Math.random() * 10);
    let c = aim >= 0 ? (aim % 10) : Math.floor(Math.random() * 10);
    if (pick === 'radar') {
      r = 1 + Math.floor(Math.random() * 8); c = 1 + Math.floor(Math.random() * 8);
      if (lvl === 'strong') {
        // 确定性：选尚未扫描、且 3×3 内未探格最多的区域，并列取最靠前
        let bestR = 1, bestC = 1, bestScore = -1;
        for (let rr = 1; rr <= 8; rr++) {
          for (let cc = 1; cc <= 8; cc++) {
            if (e.aiScanned.some(s2 => s2 && s2.r0 === rr - 1 && s2.c0 === cc - 1)) continue;
            let un = 0;
            for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
              const n = (rr + dr) * 10 + (cc + dc);
              if (e.aiAttacks[n] === -1 && !e.aiBlocked[n]) un++;
            }
            if (un > bestScore) { bestScore = un; bestR = rr; bestC = cc; }
          }
        }
        r = bestR; c = bestC;
      }
      res = bsSkillRadar('A', r, c);
    }
    else if (pick === 'recon') {
      if (lvl === 'strong' && aim < 0) {
        // 确定性：选未探格最多的一列
        let bestC = 0, bestScore = -1;
        for (let cc = 0; cc < 10; cc++) {
          let un = 0;
          for (let rr = 0; rr < 10; rr++) {
            const n = rr * 10 + cc;
            if (e.aiAttacks[n] === -1 && !e.aiBlocked[n]) un++;
          }
          if (un > bestScore) { bestScore = un; bestC = cc; }
        }
        c = bestC;
      }
      res = bsSkillRecon('A', r, c);
    }
    else if (pick === 'depth') { res = bsSkillDepth('A', r, c); }
    else if (pick === 'missile') { res = bsSkillMissile('A', r, c); }
    else if (pick === 'jammer') { res = bsSkillJammer('A'); }
    else if (pick === 'smoke') {
      r = 1 + Math.floor(Math.random() * 8); c = 1 + Math.floor(Math.random() * 8);
      if (lvl === 'strong') {
        // 确定性：烟幕盖住"己方（AI）船体格子"最多的 3×3 区域（隐藏自家海域）；旧代码看的是 playerBoard：
        // 既盖不到自己的船（技能白放），又等于偷看玩家船位
        let bestR = 4, bestC = 4, bestScore = -1;
        for (let rr = 1; rr <= 8; rr++) {
          for (let cc = 1; cc <= 8; cc++) {
            let cnt = 0;
            for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
              if (e.aiBoard[(rr + dr) * 10 + (cc + dc)] === 1) cnt++;
            }
            if (cnt > bestScore) { bestScore = cnt; bestR = rr; bestC = cc; }
          }
        }
        r = bestR; c = bestC;
      }
      res = bsSkillSmoke('A', r, c);
    }
    if (!res.ok) { e.log.push(bsOppShort() + ' 的技能未能生效，改为普通炮击。'); bsAIShoot(false); return; }
    e.aiSkillUsed[pick] = true;
    bsResolveAIAction(res.fx);
  }

  function bsAITurn() {
    const e = boardGame && boardGame.engine;
    boardGame.isThinking = false;
    if (!e || e.winner || e.turn !== 'A') { if (e) renderBattleshipBattle(); return; } // 退出后 engine 为 null，不能直接读 e.winner
    if (e.aiJammer > 0) {
      e.aiJammer--;
      e.log.push('你的电子干扰生效：对手本次炮击被迫随机射击！');
      bsAIShoot(true);
    } else {
      const usable = e.aiSkills.filter(s => !e.aiSkillUsed[s]);
      const lvl = bsAiLevel();
      // 技能释放概率分档：快速 0.2 / 标准 0.5 / 强力 0.85
      const skillP = lvl === 'fast' ? 0.2 : lvl === 'strong' ? 0.85 : 0.5;
      if (usable.length && Math.random() < skillP) bsAIUseSkill(usable);
      else bsAIShoot(false);
    }
  }

  function bsEndGame() {
    const e = boardGame && boardGame.engine;
    boardGame.isThinking = false;
    if (!e) return; // 引擎已置空（中途退出）：不再弹结算
    e.log.push('对局结束！');
    renderBattleshipBattle();
    showBattleshipGameOverModal(e.winner === 'P');
  }

  // ========== 主渲染入口 ==========
  function renderBattleship() {
    const e = boardGame.engine;
    if (!(e instanceof BattleshipEngine)) return;
    if (e.phase === 'setup') { renderBattleshipSetup(); return; }
    renderBattleshipBattle();
  }

  function bsCellHtml(kind, r, c) {
    const e = boardGame.engine;
    const idx = r * 10 + c;
    let bg = BS_WATER, inner = '', color = '#fff';
    if (kind === 'enemy') {
      const att = e.playerAttacks[idx];
      const blocked = e.playerBlocked[idx];
      if (att === 1) { bg = '#EF4444'; inner = '✕'; }
      else if (att === 0) { bg = '#FFFFFF'; inner = '○'; color = '#94A3B8'; }
      else if (blocked) { bg = '#64748B'; inner = '·'; }
    } else {
      const ship = e.playerBoard[idx] === 1;
      const att = e.aiAttacks[idx];
      if (att === 1) { bg = '#EF4444'; inner = '✕'; }
      else if (att === 0) { bg = '#FFFFFF'; inner = '○'; color = '#94A3B8'; }
      else if (ship) { bg = '#3B82F6'; }
    }
    const isSmokeTarget = kind === 'own' && bsUI.armedSkill === 'smoke' && e.turn === 'P' && !e.winner;
    const clickable = (kind === 'enemy' && e.turn === 'P' && !e.winner && e.playerAttacks[idx] === -1 && !e.playerBlocked[idx]) || isSmokeTarget;
    return `<div data-bs-cell="${r}-${c}" data-bs-board="${kind}" style="grid-column:${c + 2};grid-row:${r + 2};min-width:0;min-height:0;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:bold;background:${bg};color:${color};border-radius:1px;cursor:${clickable ? 'pointer' : 'default'};">${inner}</div>`;
  }

  function bsBuildBattleBoard(kind) {
    let s = `<div style="grid-column:1;grid-row:1;display:flex;align-items:center;justify-content:center;"></div>`;
    for (let c = 0; c < 10; c++) s += `<div style="grid-column:${c + 2};grid-row:1;display:flex;align-items:center;justify-content:center;font-size:11px;color:var(--ubp-text-3);">${String.fromCharCode(65 + c)}</div>`;
    for (let r = 0; r < 10; r++) {
      s += `<div style="grid-column:1;grid-row:${r + 2};display:flex;align-items:center;justify-content:center;font-size:11px;color:var(--ubp-text-3);">${r + 1}</div>`;
      for (let c = 0; c < 10; c++) s += bsCellHtml(kind, r, c);
    }
    return `<div id="bs-grid-${kind}" style="display:grid;grid-template-columns:22px repeat(10,1fr);grid-template-rows:22px repeat(10,1fr);grid-gap:1px;width:100%;max-width:380px;aspect-ratio:1/1;background:${BS_BOARD_BG};border:1px solid var(--ubp-line);border-radius:6px;box-sizing:border-box;">${s}</div>`;
  }

  function bsSkillButtonHtml(def, used, armed) {
    const style = used ? 'opacity:0.35;' : (armed ? 'box-shadow:0 0 8px 2px #10B981;' : '');
    return `<button data-bs-skillbtn="${def.id}" title="${def.name}：${def.desc}" style="flex:1;padding:5px 2px;background:var(--ubp-card-2);border:1.5px solid ${armed ? '#10B981' : 'var(--ubp-line)'};border-radius:8px;display:flex;flex-direction:column;align-items:center;gap:2px;cursor:${used ? 'default' : 'pointer'};${style}">
      <span style="font-size:20px;line-height:1;">${def.icon}</span>
      <span style="font-size:10px;color:var(--ubp-text);">${def.name}</span>
      ${used ? '<span style="font-size:9px;color:var(--ubp-text-3);">已用</span>' : ''}
    </button>`;
  }

  function bsInstructionText() {
    const e = boardGame.engine;
    if (e.winner) return '对局已结束';
    if (e.turn !== 'P') return '对方正在行动…';
    if (!bsUI.armedSkill) return '点击敌棋盘开炮（每回合 1 炮或 1 个技能）';
    if (bsUI.armedSkill === 'smoke') return '烟幕弹：请点击己方棋盘 3×3 中心格';
    if (bsUI.armedSkill === 'jammer') return '电子干扰：已就绪，立即释放';
    if (bsUI.armedSkill === 'recon') return '侦察机：点击敌棋盘，扫描该列';
    const def = BS_SKILL_DEFS.find(s => s.id === bsUI.armedSkill);
    return def ? (def.name + '：请点击敌棋盘目标格') : '';
  }

  function renderBattleshipBattle() {
    const e = boardGame.engine;
    if (!e || e.phase === 'setup') { renderBattleshipSetup(); return; }
    const opp = boardGame.opponent;
    const oppAvatar = opp && opp.avatar ? opp.avatar : '';
    const isUserTurn = e.turn === 'P';
    const isThinking = !isUserTurn && !e.winner;
    const statusText = e.winner ? (e.winner === 'P' ? '🎉 你获胜了！' : '😢 对方获胜！') : (isUserTurn ? '👉 你的回合' : '🤔 对方思考中…');
    const statusColor = e.winner ? (e.winner === 'P' ? '#10B981' : '#EF4444') : (isUserTurn ? '#10B981' : '#F59E0B');

    const enemyHtml = bsBuildBattleBoard('enemy');
    const ownHtml = bsBuildBattleBoard('own');
    const skillBar = e.playerSkills.map(id => {
      const def = BS_SKILL_DEFS.find(s => s.id === id);
      if (!def) return '';
      return bsSkillButtonHtml(def, !!e.playerSkillUsed[id], bsUI.armedSkill === id);
    }).join('');
    const logHtml = (e.log || []).slice(-8).map(l => '<div>' + escapeHtml(l) + '</div>').join('');

    sheet.innerHTML = `
      ${BS_FX_CSS}
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex:none;">
        <div style="display:flex;align-items:center;gap:8px;">
          <button data-bg-act="exit-to-lobby" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);flex:none;" title="返回对弈大厅（保留进度）">←</button>
          <div style="width:32px;height:32px;border-radius:50%;border:2px solid ${isThinking ? '#F59E0B' : '#10B981'};overflow:hidden;background:#10B981;flex-shrink:0;display:flex;align-items:center;justify-content:center;">
            ${oppAvatar ? `<img src="${oppAvatar}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="color:#fff;font-weight:bold;">${(opp ? opp.name : 'AI').slice(0, 1)}</span>`}
          </div>
          <div>
            <div style="font-size:13px;font-weight:bold;color:var(--ubp-text);">${opp ? opp.name : '对手'}</div>
            <div style="font-size:11px;color:var(--ubp-text-3);">海战棋 · ${opp && opp.identity ? opp.identity : (boardGame.aiCompanion ? '对弈角色' : '电脑AI')}</div>
          </div>
        </div>
        <button data-bg-act="quit-board-game" class="ubp-btn" style="padding:3px 8px;font-size:11.5px;" title="结束本局并清空该棋类进行中的进度">退出</button>
      </div>

      <div style="flex:1;overflow-y:auto;min-height:0;padding-right:2px;">
        <div id="bs-log" style="background:var(--ubp-card-2);border:1px solid var(--ubp-line);border-radius:8px;padding:6px 8px;margin-bottom:6px;font-size:11.5px;color:var(--ubp-text);max-height:70px;overflow-y:auto;line-height:1.5;">${logHtml}</div>
        <div style="text-align:center;color:var(--ubp-text-2);font-size:11px;margin-bottom:3px;">⬆ 敌方海域（你的攻击记录）</div>
        ${enemyHtml}
        <div id="bs-instruction" style="text-align:center;font-size:11px;color:var(--ubp-accent,#10B981);margin:6px 0 2px;">${bsInstructionText()}</div>
        <div style="text-align:center;color:var(--ubp-text-2);font-size:11px;margin-bottom:3px;">⬇ 己方海域（你的舰船部署）</div>
        ${ownHtml}
      </div>

      <div style="display:flex;gap:6px;margin-top:6px;flex:none;">${skillBar}</div>
      <div style="display:flex;align-items:center;justify-content:space-between;margin-top:6px;flex:none;padding-top:4px;border-top:1px solid var(--ubp-line);">
        <div style="font-size:12px;font-weight:bold;color:var(--ubp-text);">我</div>
        <div style="font-size:12px;font-weight:600;color:${statusColor};">${statusText}</div>
      </div>
    `;
    bsBindBattleEvents();
    const logEl = sheet.querySelector('#bs-log');
    if (logEl) logEl.scrollTop = logEl.scrollHeight;
  }

  function bsOnCellClick(r, c, boardKind) {
    const e = boardGame.engine;
    if (bsResolving || e.winner || e.turn !== 'P') return;
    if (bsUI.armedSkill) {
      if (bsUI.armedSkill === 'smoke' && boardKind !== 'own') { showToast('请点击己方棋盘'); return; }
      if (bsUI.armedSkill !== 'smoke' && boardKind !== 'enemy') { showToast('请点击敌棋盘'); return; }
      bsExecutePlayerSkill(bsUI.armedSkill, r, c);
      return;
    }
    if (boardKind !== 'enemy') return;
    const idx = r * 10 + c;
    if (e.playerAttacks[idx] !== -1 || e.playerBlocked[idx]) { showToast('该坐标不能重复射击'); return; }
    bsPlayerShoot(idx);
  }

  function bsOnSkillButtonClick(skillId) {
    const e = boardGame.engine;
    if (bsResolving || e.playerSkillUsed[skillId] || e.turn !== 'P' || e.winner) return;
    if (skillId === 'jammer') { bsExecutePlayerSkill('jammer', -1, -1); return; }
    if (bsUI.armedSkill === skillId) bsUI.armedSkill = null;
    else { bsUI.armedSkill = skillId; }
    renderBattleshipBattle();
  }

  function bsBindBattleEvents() {
    sheet.querySelectorAll('[data-bs-cell]').forEach(cell => {
      const parts = cell.dataset.bsCell.split('-');
      const r = parseInt(parts[0], 10), c = parseInt(parts[1], 10);
      const boardKind = cell.dataset.bsBoard;
      cell.addEventListener('click', () => bsOnCellClick(r, c, boardKind));
    });
    sheet.querySelectorAll('[data-bs-skillbtn]').forEach(btn => {
      btn.addEventListener('click', () => bsOnSkillButtonClick(btn.dataset.bsSkillbtn));
    });
    bsBindSkillTips('[data-bs-skillbtn]');
  }

  // ========== 部署界面 ==========
  function bsBuildSetupBoard() {
    const e = boardGame.engine;
    let s = `<div style="grid-column:1;grid-row:1;display:flex;align-items:center;justify-content:center;"></div>`;
    for (let c = 0; c < 10; c++) s += `<div style="grid-column:${c + 2};grid-row:1;display:flex;align-items:center;justify-content:center;font-size:11px;color:var(--ubp-text-3);">${String.fromCharCode(65 + c)}</div>`;
    for (let r = 0; r < 10; r++) {
      s += `<div style="grid-column:1;grid-row:${r + 2};display:flex;align-items:center;justify-content:center;font-size:11px;color:var(--ubp-text-3);">${r + 1}</div>`;
      for (let c = 0; c < 10; c++) {
        const idx = r * 10 + c;
        const ship = e.playerBoard[idx] === 1;
        s += `<div data-bs-cell="${r}-${c}" data-bs-board="own" style="grid-column:${c + 2};grid-row:${r + 2};min-width:0;min-height:0;display:flex;align-items:center;justify-content:center;background:${ship ? '#3B82F6' : BS_WATER};border-radius:1px;cursor:${bsUI.activeShip ? 'pointer' : 'default'};"></div>`;
      }
    }
    return `<div style="display:grid;grid-template-columns:22px repeat(10,1fr);grid-template-rows:22px repeat(10,1fr);grid-gap:1px;width:100%;max-width:380px;aspect-ratio:1/1;background:${BS_BOARD_BG};border:1px solid var(--ubp-line);border-radius:6px;box-sizing:border-box;">${s}</div>`;
  }

  function renderBattleshipSetup() {
    const e = boardGame.engine;
    if (!e || e.phase !== 'setup') return;
    const trayHtml = BS_SHIP_DEFS.map(def => {
      const remain = e.playerRemain[def.id];
      const armed = bsUI.activeShip === def.id;
      const ori = armed ? bsUI.ori : 'H';
      const placed = def.count - remain;
      let squares = '';
      for (let i = 0; i < def.size; i++) squares += `<span style="width:13px;height:13px;background:${remain <= 0 ? '#6B7280' : '#3B82F6'};border:1px solid #1d4ed8;border-radius:2px;display:inline-block;flex-shrink:0;"></span>`;
      return `<div class="bs-tray-ship" data-bs-ship="${def.id}" style="display:flex;flex-direction:column;align-items:center;gap:2px;padding:5px 7px;background:var(--ubp-card-2);border:1.5px solid ${armed ? '#10B981' : 'var(--ubp-line)'};border-radius:8px;cursor:pointer;touch-action:none;flex-shrink:0;${armed ? 'box-shadow:0 0 8px #10B981;' : ''}">
        <div style="display:flex;flex-direction:${ori === 'H' ? 'row' : 'column'};gap:1px;">${squares}</div>
        <div style="font-size:10px;color:var(--ubp-text);line-height:1;">${def.name}</div>
        <div style="font-size:13px;font-weight:bold;color:${remain > 0 ? '#10B981' : '#6B7280'};">${remain}</div>
        <button class="bs-undo-ship" data-bs-undo="${def.id}" style="margin-top:2px;padding:2px 8px;font-size:10px;line-height:1.4;border-radius:6px;border:1px solid ${placed > 0 ? '#F59E0B' : 'var(--ubp-line)'};background:${placed > 0 ? 'rgba(245,158,11,.15)' : 'transparent'};color:${placed > 0 ? '#F59E0B' : 'var(--ubp-text-3)'};cursor:${placed > 0 ? 'pointer' : 'default'};${placed > 0 ? '' : 'opacity:0.45;'}">↩ 撤回</button>
      </div>`;
    }).join('');

    const boardHtml = bsBuildSetupBoard();

    const skillHtml = BS_SKILL_DEFS.map(def => {
      const sel = bsUI.selectedSkills.includes(def.id);
      const full = bsUI.selectedSkills.length >= 3 && !sel;
      return `<div class="bs-skill" data-bs-skill="${def.id}" title="${def.name}：${def.desc}" style="flex:1;max-width:56px;display:flex;flex-direction:column;align-items:center;gap:1px;padding:4px 2px;background:var(--ubp-card-2);border:1.5px solid ${sel ? '#10B981' : 'var(--ubp-line)'};border-radius:8px;cursor:pointer;${full ? 'opacity:0.35;' : ''}${sel ? 'box-shadow:0 0 8px #10B981;' : ''}">
        <span style="font-size:22px;line-height:1;">${def.icon}</span>
        <span style="font-size:9px;color:var(--ubp-text);">${def.name}</span>
        ${sel ? '<span style="font-size:9px;color:#10B981;">✓</span>' : ''}
      </div>`;
    }).join('');

    sheet.innerHTML = `
      <style>
        @keyframes bsBlink { 0%,100% { opacity:1; } 50% { opacity:0.25; } }
        .bs-blink { animation: bsBlink 1.1s infinite; }
      </style>
      <div style="display:flex;justify-content:space-between;align-items:center;flex:none;margin-bottom:4px;">
        <button data-bg-act="exit-to-lobby" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">←</button>
        <span style="font-size:15px;font-weight:bold;color:var(--ubp-text);">⚓ 海战棋 · 舰船部署</span>
        <span style="width:24px;"></span>
      </div>
      <div class="bs-blink" style="flex:none;text-align:center;font-size:12px;font-weight:bold;color:#F59E0B;">🛠️ 对方正在放置船只…</div>
      <div style="flex:none;text-align:center;font-size:10.5px;color:var(--ubp-text-2);line-height:1.4;">点击船只选中，再点击棋盘放置 · 再次点击船只按中间格旋转</div>
      <div style="flex:none;display:flex;gap:4px;justify-content:flex-start;overflow-x:auto;padding:4px 0;margin:2px 0;">${trayHtml}</div>
      <div style="flex:1;min-height:0;display:flex;align-items:center;justify-content:center;margin:2px 0;overflow:auto;">
        ${boardHtml}
      </div>
      <div style="flex:none;font-size:10px;color:var(--ubp-text-2);text-align:center;margin-bottom:2px;">选择 3 个技能（已选 ${bsUI.selectedSkills.length}/3，悬停/长按看介绍）</div>
      <div style="flex:none;display:flex;gap:5px;justify-content:center;margin-bottom:6px;">${skillHtml}</div>
      <button data-bg-act="bs-start" class="ubp-btn primary" style="flex:none;width:100%;padding:9px;background:#10B981;font-size:14px;font-weight:600;border-radius:8px;">⚓ 开始游戏</button>
    `;
    bsBindSetupEvents();
  }

  function bsOnSetupCellClick(r, c) {
    const e = boardGame.engine;
    if (e.phase !== 'setup') return;
    if (!bsUI.activeShip) return;
    bsPlaceActive(r, c);
  }

  function bsPlaceActive(r, c) {
    const e = boardGame.engine;
    const def = BS_SHIP_DEFS.find(d => d.id === bsUI.activeShip);
    if (!def) return;
    if (e.playerRemain[def.id] <= 0) { showToast('该船只已全部摆放完毕'); return; }
    const cells = bsShipCellIndices(r, c, def.size, bsUI.ori);
    const valid = cells && cells.every(idx => e.playerBoard[idx] === 0);
    if (!valid) { bsFlashInvalid(r, c, def.size); return; }
    cells.forEach(idx => e.playerBoard[idx] = 1);
    e.playerShips.push({ defId: def.id, name: def.name, size: def.size, cells: cells.slice(), hits: cells.map(() => false) });
    e.playerRemain[def.id]--;
    if (e.playerRemain[def.id] <= 0) bsUI.activeShip = null;
    saveBoardGameState();
    renderBattleshipSetup();
  }

  function bsUndoShip(defId) {
    const e = boardGame.engine;
    for (let i = e.playerShips.length - 1; i >= 0; i--) {
      if (e.playerShips[i].defId !== defId) continue;
      const ship = e.playerShips[i];
      ship.cells.forEach(idx => e.playerBoard[idx] = 0);
      e.playerShips.splice(i, 1);
      e.playerRemain[defId] = (e.playerRemain[defId] || 0) + 1;
      break;
    }
    saveBoardGameState();
    renderBattleshipSetup();
  }

  function bsFlashInvalid(r, c, size) {
    const cells = bsShipCellIndices(r, c, size, bsUI.ori);
    showToast('🚫 不可放置');
    if (cells) {
      cells.forEach(idx => {
        const rr = Math.floor(idx / 10), cc = idx % 10;
        const cell = sheet.querySelector('[data-bs-cell="' + rr + '-' + cc + '"]');
        if (cell) { cell.style.background = '#EF4444'; setTimeout(() => { if (boardGame.engine) { const ship = boardGame.engine.playerBoard[idx] === 1; cell.style.background = ship ? '#3B82F6' : BS_WATER; } }, 450); }
      });
    }
  }

  function bsToggleSkill(id) {
    const idx = bsUI.selectedSkills.indexOf(id);
    if (idx >= 0) bsUI.selectedSkills.splice(idx, 1);
    else {
      if (bsUI.selectedSkills.length >= 3) { showToast('技能最多选择 3 个'); return; }
      bsUI.selectedSkills.push(id);
    }
    saveBoardGameState();
    renderBattleshipSetup();
  }

  function bsClickTrayShip(id) {
    const e = boardGame.engine;
    if (e.playerRemain[id] <= 0) return;
    if (bsUI.activeShip !== id) { bsUI.activeShip = id; bsUI.ori = 'H'; }
    else { bsUI.ori = bsUI.ori === 'H' ? 'V' : 'H'; }
    renderBattleshipSetup();
  }

  function bsCellFromPoint(clientX, clientY) {
    const sr = getShadowRoot();
    let el = null;
    try { if (sr && sr.elementFromPoint) el = sr.elementFromPoint(clientX, clientY); } catch (e) {}
    if (!el) { try { el = document.elementFromPoint(clientX, clientY); } catch (e) {} }
    if (!el || !el.closest) return null;
    const cell = el.closest('[data-bs-cell]');
    if (!cell) return null;
    const parts = cell.dataset.bsCell.split('-');
    return { r: parseInt(parts[0], 10), c: parseInt(parts[1], 10) };
  }

  function bsClearSetupPreview() {
    const e = boardGame.engine;
    if (!e) return;
    for (let i = 0; i < 100; i++) {
      const r = Math.floor(i / 10), c = i % 10;
      const cell = sheet.querySelector('[data-bs-cell="' + r + '-' + c + '"]');
      if (cell) { const ship = e.playerBoard[i] === 1; cell.style.background = ship ? '#3B82F6' : BS_WATER; }
    }
  }

  function bsSetupPreviewDrag(r, c) {
    const e = boardGame.engine;
    bsClearSetupPreview();
    if (r < 0 || !bsUI.drag) { if (bsUI.ghost) bsUI.ghost.style.outline = '2px solid #EF4444'; return; }
    const def = BS_SHIP_DEFS.find(d => d.id === bsUI.drag);
    if (!def) return;
    const cells = bsShipCellIndices(r, c, def.size, bsUI.ori);
    const valid = cells && cells.every(idx => e.playerBoard[idx] === 0);
    if (bsUI.ghost) bsUI.ghost.style.outline = valid ? '2px solid #10B981' : '2px solid #EF4444';
    if (cells) {
      cells.forEach(idx => {
        const rr = Math.floor(idx / 10), cc = idx % 10;
        const cell = sheet.querySelector('[data-bs-cell="' + rr + '-' + cc + '"]');
        if (cell) cell.style.background = valid ? 'rgba(16,185,129,0.55)' : '#EF4444';
      });
    }
  }

  function bsSetupPreview(r, c) {
    const e = boardGame.engine;
    if (!bsUI.activeShip) return;
    const def = BS_SHIP_DEFS.find(d => d.id === bsUI.activeShip);
    if (!def) return;
    bsClearSetupPreview();
    const cells = bsShipCellIndices(r, c, def.size, bsUI.ori);
    if (!cells) return;
    const valid = cells.every(idx => e.playerBoard[idx] === 0);
    cells.forEach(idx => {
      const rr = Math.floor(idx / 10), cc = idx % 10;
      const cell = sheet.querySelector('[data-bs-cell="' + rr + '-' + cc + '"]');
      if (cell) cell.style.background = valid ? 'rgba(16,185,129,0.55)' : '#EF4444';
    });
  }

  function bsTrayPointerDown(id, ev) {
    const e = boardGame.engine;
    if (e.playerRemain[id] <= 0) return;
    bsUI.drag = id;
    bsUI.startX = ev.clientX; bsUI.startY = ev.clientY;
    bsUI.moved = false;
    const def = BS_SHIP_DEFS.find(d => d.id === id);
    const ghost = document.createElement('div');
    ghost.style.cssText = 'position:fixed;z-index:200;pointer-events:none;left:' + ev.clientX + 'px;top:' + ev.clientY + 'px;background:rgba(59,130,246,0.95);border:1px solid #1d4ed8;border-radius:4px;padding:3px;';
    let sq = '';
    for (let i = 0; i < def.size; i++) sq += '<span style="width:13px;height:13px;background:#3B82F6;display:inline-block;border-radius:1px;"></span>';
    ghost.innerHTML = '<div style="display:flex;flex-direction:' + (bsUI.ori === 'H' ? 'row' : 'column') + ';gap:1px;">' + sq + '</div>';
    document.body.appendChild(ghost);
    bsUI.ghost = ghost;

    const onMove = (ev2) => {
      if (Math.abs(ev2.clientX - bsUI.startX) + Math.abs(ev2.clientY - bsUI.startY) > 6) bsUI.moved = true;
      if (bsUI.ghost) { bsUI.ghost.style.left = ev2.clientX + 'px'; bsUI.ghost.style.top = ev2.clientY + 'px'; }
      const cell = bsCellFromPoint(ev2.clientX, ev2.clientY);
      bsSetupPreviewDrag(cell ? cell.r : -1, cell ? cell.c : -1);
    };
    const onUp = (ev2) => {
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerup', onUp);
      document.removeEventListener('pointercancel', onUp);
      if (bsUI.ghost) { bsUI.ghost.remove(); bsUI.ghost = null; }
      bsClearSetupPreview();
      if (bsUI.moved) {
        const cell = bsCellFromPoint(ev2.clientX, ev2.clientY);
        if (cell) { bsPlaceActive(cell.r, cell.c); bsUI.suppressClick = true; }
        // 拖拽结束后浏览器不会把 click 派发到船卡，suppressClick 会一直残留并吞掉下一次点击：
        // 下一帧自动清除（同步派发的 click 仍能命中上面的消费分支）
        setTimeout(() => { bsUI.suppressClick = false; }, 0);
      }
      bsUI.drag = null;
    };
    document.addEventListener('pointermove', onMove);
    document.addEventListener('pointerup', onUp);
    document.addEventListener('pointercancel', onUp);
  }

  function bsBindSetupEvents() {
    sheet.querySelectorAll('[data-bs-cell]').forEach(cell => {
      const parts = cell.dataset.bsCell.split('-');
      const r = parseInt(parts[0], 10), c = parseInt(parts[1], 10);
      cell.addEventListener('click', () => bsOnSetupCellClick(r, c));
      cell.addEventListener('pointerenter', () => bsSetupPreview(r, c));
      cell.addEventListener('pointerleave', () => { if (!bsUI.drag) bsClearSetupPreview(); });
    });
    sheet.querySelectorAll('.bs-skill').forEach(el => {
      el.addEventListener('click', () => bsToggleSkill(el.dataset.bsSkill));
    });
    sheet.querySelectorAll('.bs-tray-ship').forEach(el => {
      el.addEventListener('click', () => {
        if (bsUI.suppressClick) { bsUI.suppressClick = false; return; }
        bsClickTrayShip(el.dataset.bsShip);
      });
      el.addEventListener('pointerdown', (ev) => bsTrayPointerDown(el.dataset.bsShip, ev));
    });
    sheet.querySelectorAll('.bs-undo-ship').forEach(btn => {
      btn.addEventListener('pointerdown', (ev) => ev.stopPropagation());
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        const def = BS_SHIP_DEFS.find(d => d.id === btn.dataset.bsUndo);
        const placed = def ? (def.count - ((boardGame.engine && boardGame.engine.playerRemain[def.id]) || 0)) : 0;
        if (placed > 0) bsUndoShip(btn.dataset.bsUndo);
      });
    });
    bsBindSkillTips('.bs-skill');
  }

  function bsStartBattle() {
    const e = boardGame.engine;
    if (!e || e.phase !== 'setup') return;
    if (e.playerRemain && Object.keys(e.playerRemain).some(k => e.playerRemain[k] > 0)) {
      showToast('检测到您还有船只未摆放完，请摆放完再开始游戏');
      return;
    }
    if (bsUI.selectedSkills.length < 3) {
      showToast('请先选择 3 个技能再开始游戏');
      return;
    }
    e.playerSkills = bsUI.selectedSkills.slice();
    e.aiSkills = bsPickRandomSkills(3);
    e.phase = 'battle';
    e.turn = Math.random() < 0.5 ? 'P' : 'A';
    bsUI.armedSkill = null;
    bsUI.reconMode = 'row';
    e.log = [];
    if (e.turn === 'P') e.log.push('对局开始！你率先行动，点击敌棋盘开炮或使用技能。');
    else e.log.push('对局开始！对手率先行动。');
    saveBoardGameState();
    renderBattleshipBattle();
    if (e.turn === 'A') {
      boardGame.isThinking = true;
      renderBattleshipBattle();
      setTimeout(() => bsAITurn(), 650);
    }
  }

  // ========== 技能提示（悬停/长按） ==========
  function bsBindSkillTips(sel) {
    sheet.querySelectorAll(sel).forEach(el => {
      const id = el.dataset.bsSkill || el.dataset.bsSkillbtn;
      const def = BS_SKILL_DEFS.find(s => s.id === id);
      if (!def) return;
      el.addEventListener('pointerdown', () => {
        bsTipTimer = setTimeout(() => { bsTipTimer = null; bsShowSkillTip(def, el); }, 450);
      });
      const cancel = () => { if (bsTipTimer) { clearTimeout(bsTipTimer); bsTipTimer = null; } bsHideSkillTip(); };
      el.addEventListener('pointerup', cancel);
      el.addEventListener('pointercancel', cancel);
      el.addEventListener('pointerleave', cancel);
    });
  }

  function bsShowSkillTip(def, el) {
    bsHideSkillTip();
    const tip = document.createElement('div');
    // 下移到技能按钮下方，确保提示不会遮住技能本身
    const tipW = 210;
    let tipLeft = 8, tipTop = 0;
    try {
      const rect = el.getBoundingClientRect();
      const vw = window.innerWidth || 360;
      const vh = window.innerHeight || 640;
      tipLeft = Math.max(8, Math.min(vw - tipW - 8, rect.left + rect.width / 2 - tipW / 2));
      tipTop = rect.bottom + 8;
      if (tipTop + 92 > vh) tipTop = Math.max(8, rect.top - 100);
    } catch (e) { /* ignore */ }
    tip.style.cssText = 'position:fixed;left:' + tipLeft + 'px;top:' + tipTop + 'px;z-index:300;background:rgba(0,0,0,0.92);color:#fff;border-radius:8px;padding:8px 10px;font-size:11.5px;line-height:1.5;width:' + tipW + 'px;box-sizing:border-box;pointer-events:none;';
    tip.innerHTML = '<b>' + def.icon + ' ' + def.name + '</b><div style="margin-top:2px;color:#d1d5db;">' + def.desc + '</div>';
    document.body.appendChild(tip);
    bsUI.tip = tip;
  }

  function bsHideSkillTip() {
    if (bsUI && bsUI.tip) { try { bsUI.tip.remove(); } catch (e) {} bsUI.tip = null; }
  }

