  // 统一取色工具：用户/电脑执子颜色按游戏类型区分
  function getBoardUserColor() {
    if (boardGame.gameType === 'chess') return 'W';
    if (boardGame.gameType === 'shogi') return 'S';
    if (boardGame.gameType === 'go') return 'B';
    if (boardGame.gameType === 'othello') return 'B';
    return 'R';
  }
  function getBoardAIColor() {
    if (boardGame.gameType === 'shogi') return 'G';
    if (boardGame.gameType === 'go') return 'W';
    if (boardGame.gameType === 'othello') return 'W';
    return 'B';
  }
  function boardGameTitle(type) {
    const map = { gomoku: '五子棋', xiangqi: '中国象棋', jungle: '斗兽棋', chess: '国际象棋', shogi: '将棋', battleship: '海战棋', go: '围棋', luzhanqi: '军棋', othello: '黑白棋' };
    return map[type] || '棋局';
  }

  // ========== UI 渲染与控制 ==========

// ========== 围棋（9 路 · 中国规则数子 · 三档 AI） ==========
  // 规则：黑先白后，气尽提子，禁止自杀，简单劫（单子提单子）禁一手，双方连续弃一手即终局，
  // 终局按"子 + 围空"数子判定胜负；支持认输。玩家执黑（下方），AI 执白。
  class GoEngine {
    constructor(size = 9) {
      this.size = size;
      this.board = Array.from({ length: size }, () => new Array(size).fill(0));
      this.turn = 'B';
      this.captures = { B: 0, W: 0 };
      this.koPoint = null;
      this.passes = 0;
      this.history = [];
      this.winner = null;
      this.scoreInfo = null;
      this.resigned = null;
    }
    idx(r, c) { return r >= 0 && r < this.size && c >= 0 && c < this.size; }
    get(r, c) { return this.idx(r, c) ? this.board[r][c] : null; }
    set(r, c, v) { if (this.idx(r, c)) this.board[r][c] = v; }
    opposite(color) { return color === 'B' ? 'W' : 'B'; }
    key(r, c) { return r * this.size + c; }
    group(r, c) {
      const color = this.board[r][c];
      if (!color) return { stones: [], liberties: [] };
      const seen = new Set(); const stones = []; const libs = new Set();
      const stack = [[r, c]];
      while (stack.length) {
        const [rr, cc] = stack.pop();
        const k = this.key(rr, cc);
        if (seen.has(k)) continue;
        seen.add(k); stones.push(k);
        for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const nr = rr + dr, nc = cc + dc;
          if (!this.idx(nr, nc)) continue;
          const v = this.board[nr][nc];
          if (v === 0) libs.add(this.key(nr, nc));
          else if (v === color) stack.push([nr, nc]);
        }
      }
      return { stones: stones, liberties: Array.from(libs) };
    }
    // 试下（纯模拟，绝不改变棋盘）：返回 { ok, captured(提子数), capturedCoords, ownLibs, ko }
    simulate(r, c, color) {
      if (!this.idx(r, c) || this.board[r][c] !== 0) return { ok: false };
      if (this.koPoint && this.koPoint.r === r && this.koPoint.c === c) return { ok: false, ko: true };
      const opp = this.opposite(color);
      this.board[r][c] = color;
      const removed = [];
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr, nc = c + dc;
        if (!this.idx(nr, nc) || this.board[nr][nc] !== opp) continue;
        const g = this.group(nr, nc);
        if (!g.liberties.length) for (const k of g.stones) removed.push(k);
      }
      for (const k of removed) this.board[Math.floor(k / this.size)][k % this.size] = 0;
      let ownLibs = 0;
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr, nc = c + dc;
        if (!this.idx(nr, nc)) continue;
        if (this.board[nr][nc] === 0) ownLibs++;
      }
      const ownGroupLibs = this.group(r, c).liberties.length;
      const isSuicide = ownGroupLibs === 0;
      let ko = null;
      if (removed.length === 1 && ownGroupLibs === 1) ko = { r: Math.floor(removed[0] / this.size), c: removed[0] % this.size };
      // 还原棋盘
      this.board[r][c] = 0;
      for (const k of removed) this.board[Math.floor(k / this.size)][k % this.size] = opp;
      if (isSuicide) return { ok: false, suicide: true };
      return { ok: true, captured: removed.length, capturedCoords: removed, ownLibs: ownGroupLibs, ko: ko };
    }
    makeMove(r, c, color) {
      const me = color || this.turn;
      const res = this.simulate(r, c, me);
      if (!res.ok) return false;
      const opp = this.opposite(me);
      this.board[r][c] = me;
      for (const k of res.capturedCoords) this.board[Math.floor(k / this.size)][k % this.size] = 0;
      this.captures[me] += res.captured;
      this.koPoint = res.ko;
      this.history.push({ r: r, c: c, color: me, captured: res.capturedCoords, ko: res.ko, passBefore: this.passes });
      this.passes = 0;
      this.turn = opp;
      return true;
    }
    pass(color) {
      const me = color || this.turn;
      this.history.push({ pass: true, color: me, ko: this.koPoint, passBefore: this.passes });
      this.koPoint = null;
      this.passes++;
      this.turn = this.opposite(me);
      if (this.passes >= 2) this.finish();
      return true;
    }
    resign(color) { this.resigned = color; this.winner = this.opposite(color); this.scoreInfo = null; }
    undo() {
      const h = this.history.pop();
      if (!h) return false;
      this.turn = h.color;
      this.koPoint = h.ko || null;
      this.passes = h.passBefore || 0;
      if (!h.pass) {
        this.board[h.r][h.c] = 0;
        if (Array.isArray(h.captured)) for (const k of h.captured) this.board[Math.floor(k / this.size)][k % this.size] = this.opposite(h.color);
      }
      this.winner = null;
      this.scoreInfo = null;
      this.resigned = null;
      return true;
    }
    // 中国规则数子：子 + 只被单色包围的空点
    score() {
      let b = 0, w = 0;
      for (let r = 0; r < this.size; r++) for (let c = 0; c < this.size; c++) {
        if (this.board[r][c] === 'B') b++;
        else if (this.board[r][c] === 'W') w++;
      }
      const seen = new Set();
      for (let r = 0; r < this.size; r++) for (let c = 0; c < this.size; c++) {
        if (this.board[r][c] !== 0 || seen.has(this.key(r, c))) continue;
        const region = []; const borders = new Set();
        const stack = [[r, c]];
        while (stack.length) {
          const [rr, cc] = stack.pop();
          const k = this.key(rr, cc);
          if (seen.has(k)) continue;
          seen.add(k); region.push(k);
          for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
            const nr = rr + dr, nc = cc + dc;
            if (!this.idx(nr, nc)) continue;
            const v = this.board[nr][nc];
            if (v === 0) stack.push([nr, nc]); else borders.add(v);
          }
        }
        if (borders.size === 1) { if (borders.has('B')) b += region.length; else w += region.length; }
      }
      return { B: b, W: w };
    }
    finish() {
      this.scoreInfo = this.score();
      if (this.scoreInfo.B > this.scoreInfo.W) this.winner = 'B';
      else if (this.scoreInfo.W > this.scoreInfo.B) this.winner = 'W';
      else this.winner = 'draw';
    }
    stoneCount() { let n = 0; for (const row of this.board) for (const v of row) if (v) n++; return n; }
    // 眼：四正交邻点全是己方 → 不填自己的眼（避免自毁）
    isEye(r, c, color) {
      let mine = 0;
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr, nc = c + dc;
        if (this.idx(nr, nc) && this.board[nr][nc] === color) mine++;
      }
      return mine === 4;
    }
    legalMoves(color) {
      const out = [];
      for (let r = 0; r < this.size; r++) for (let c = 0; c < this.size; c++) {
        if (this.board[r][c] !== 0) continue;
        if (this.isEye(r, c, color)) continue;
        const res = this.simulate(r, c, color);
        if (res.ok) out.push({ r: r, c: c, captured: res.captured });
      }
      return out;
    }
    adjCount(r, c, color) {
      let n = 0;
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr, nc = c + dc;
        if (this.idx(nr, nc) && this.board[nr][nc] === color) n++;
      }
      return n;
    }
    // 落子后对"邻接敌方组"的威胁：其中敌方组的剩余气数最小值
    atariThreat(r, c, color) {
      const opp = this.opposite(color);
      const res = this.simulate(r, c, color);
      if (!res.ok) return 0;
      this.board[r][c] = color;
      for (const k of (res.capturedCoords || [])) this.board[Math.floor(k / this.size)][k % this.size] = 0;
      const seen = new Set(); let worst = 99;
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr, nc = c + dc;
        if (!this.idx(nr, nc) || this.board[nr][nc] !== opp) continue;
        const g = this.group(nr, nc);
        if (seen.has(g.stones[0])) continue;
        seen.add(g.stones[0]);
        worst = Math.min(worst, g.liberties.length);
      }
      this.board[r][c] = 0;
      for (const k of (res.capturedCoords || [])) this.board[Math.floor(k / this.size)][k % this.size] = opp;
      return worst === 1 ? 1 : 0;
    }
    // 救活自己被打吃的组：本手是否让某"只剩 1 气"的己方组恢复气
    saveOwnAtari(r, c, color) {
      const before = [];
      for (let rr = 0; rr < this.size; rr++) for (let cc = 0; cc < this.size; cc++) {
        if (this.board[rr][cc] !== color) continue;
        const k = this.key(rr, cc);
        if (before.some(x => x.stones.includes(k))) continue;
        const g = this.group(rr, cc);
        if (g.liberties.length === 1 && g.liberties[0] === this.key(r, c)) before.push(g);
      }
      if (!before.length) return 0;
      const res = this.simulate(r, c, color);
      if (!res.ok) return 0;
      this.board[r][c] = color;
      for (const k of (res.capturedCoords || [])) this.board[Math.floor(k / this.size)][k % this.size] = 0;
      let saved = 0;
      for (const g of before) if (this.group(Math.floor(g.stones[0] / this.size), g.stones[0] % this.size).liberties.length > 1) saved++;
      this.board[r][c] = 0;
      for (const k of (res.capturedCoords || [])) this.board[Math.floor(k / this.size)][k % this.size] = this.opposite(color);
      return saved;
    }
    boardString() { return this.board.map(row => row.map(v => v || '.').join('')).join('|'); }
    aiScoreMove(r, c, color, level) {
      const res = this.simulate(r, c, color);
      if (!res.ok) return -Infinity;
      let s = 0;
      s += res.captured * 140;                 // 提子优先
      s += this.saveOwnAtari(r, c, color) * 90; // 救己方被打吃
      s += this.atariThreat(r, c, color) * 45;  // 打吃对方
      if (res.ownLibs === 1) s -= 300;          // 自紧气（送吃）
      else if (res.ownLibs === 2) s -= 30;
      else s += Math.min(6, res.ownLibs) * 6;
      s += this.adjCount(r, c, color) * 4;
      const edge = Math.min(r, c, this.size - 1 - r, this.size - 1 - c);
      const opening = this.stoneCount() < 6;
      if (opening) s += edge === 2 ? 30 : edge === 3 ? 22 : edge === 1 ? 8 : 0;
      else s += (edge === 2 || edge === 3) ? 10 : (edge === 0 ? -8 : 0);
      if (!opening && this.adjCount(r, c, color) === 0 && this.adjCount(r, c, this.opposite(color)) === 0) s -= 14;
      if (level === 'normal' || level === 'strong') {
        // 进阶/高级：更看重"连接与安全"，远离对方厚势
        if (res.ownLibs >= 4) s += 12;
      }
      return s;
    }
    cloneSim() {
      const sim = new GoEngine(this.size);
      sim.board = this.board.map(row => row.slice());
      sim.turn = this.turn;
      sim.captures = { B: this.captures.B, W: this.captures.W };
      sim.koPoint = this.koPoint ? { r: this.koPoint.r, c: this.koPoint.c } : null;
      sim.passes = this.passes;
      return sim;
    }
    // 随机推演：双方随机合法落子（不填眼），两次弃手或步数上限后数子；返回"我是否赢"
    mcRollout(color, firstMove, rng) {
      const sim = this.cloneSim();
      sim.makeMove(firstMove.r, firstMove.c, color);
      if (sim.winner) return sim.winner === color;
      let guard = 0;
      let passStreak = sim.passes;
      while (guard++ < 120 && passStreak < 2) {
        const me = sim.turn;
        const moves = sim.legalMoves(me);
        if (!moves.length) { sim.pass(me); passStreak++; continue; }
        const pick = moves[Math.floor(rng() * moves.length)];
        sim.makeMove(pick.r, pick.c, me);
        passStreak = sim.passes;
      }
      if (!sim.winner) sim.finish();
      if (sim.winner === 'draw') return false;
      return sim.winner === color;
    }
    getBestMove(color, soften, level) {
      const D = getDifficulty('go', level);
      const moves = this.legalMoves(color);
      if (!moves.length) return { pass: true };
      const cands = moves.map(m => ({ r: m.r, c: m.c, sc: this.aiScoreMove(m.r, m.c, color, level) }));
      cands.sort((a, b) => b.sc - a.sc);
      // 收官判断：对手已弃一手且自己也没有明显收益时跟着弃一手（否则可能永远下不完）；全是亏手也弃一手
      if (this.passes >= 1 && cands[0].sc < 10) return { pass: true };
      if (cands[0].sc < -20) return { pass: true };
      if (soften) { const pool = cands.slice(0, Math.min(8, cands.length)); return pool[Math.floor(Math.random() * pool.length)]; }
      if (D.level === 'fast') {
        if (cands.length > 1 && Math.random() < D.blunder) {
          const pool = cands.slice(1, Math.max(2, Math.min(D.candK || 4, cands.length)));
          return pool[Math.floor(Math.random() * pool.length)];
        }
        return cands[0];
      }
      if (D.level === 'normal') {
        if (cands.length > 1 && Math.random() < D.blunder) {
          const pool = cands.slice(1, Math.max(2, Math.min(D.candK || 2, cands.length)));
          return pool[Math.floor(Math.random() * pool.length)];
        }
        return cands[0];
      }
      // 高级：蒙特卡洛（局面指纹播种 → 同一局面决策可复现）
      const rng = pickRng('strong', 'go|' + color + '|' + this.boardString() + '|' + this.turn + '|' + this.passes);
      const sims = Math.max(6, Math.min(60, D.sims || 40));
      let best = cands[0], bestV = -Infinity;
      for (const m of cands.slice(0, 6)) {
        let wins = 0;
        for (let i = 0; i < sims; i++) wins += this.mcRollout(color, m, rng) ? 1 : 0;
        const v = (wins / sims) + m.sc * 0.004;
        if (v > bestV) { bestV = v; best = m; }
      }
      return best;
    }
  }

  // 渲染 9 路围棋盘（交点落子，玩家执黑）
  function renderSvgGo(container) {
    const engine = boardGame.engine;
    const size = engine.size;
    const boardPixelSize = 300;
    const margin = 18;
    const gridWidth = boardPixelSize - 2 * margin;
    const step = gridWidth / (size - 1);
    const stoneR = Math.max(9, step * 0.46);
    let svg = `<svg viewBox="0 0 ${boardPixelSize} ${boardPixelSize}" width="100%" height="100%" style="display:block;user-select:none;max-height:300px;">`;
    svg += `<rect x="0" y="0" width="${boardPixelSize}" height="${boardPixelSize}" rx="8" fill="#E6C280" stroke="#78350F" stroke-width="3"/>`;
    for (let i = 0; i < size; i++) {
      const p = margin + i * step;
      svg += `<line x1="${margin}" y1="${p}" x2="${boardPixelSize - margin}" y2="${p}" stroke="#78350F" stroke-width="1"/>`;
      svg += `<line x1="${p}" y1="${margin}" x2="${p}" y2="${boardPixelSize - margin}" stroke="#78350F" stroke-width="1"/>`;
    }
    const stars = size === 9 ? [[2, 2], [2, 6], [6, 2], [6, 6], [4, 4]] : [[3, 3], [3, size - 4], [size - 4, 3], [size - 4, size - 4]];
    for (const [r, c] of stars) svg += `<circle cx="${margin + c * step}" cy="${margin + r * step}" r="2.6" fill="#78350F"/>`;
    const last = engine.history.length ? engine.history[engine.history.length - 1] : null;
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        const val = engine.get(r, c);
        const cx = margin + c * step, cy = margin + r * step;
        const isLast = last && !last.pass && last.r === r && last.c === c;
        if (val === 'B' || val === 'W') {
          const fill = val === 'B' ? '#111827' : '#F9FAFB';
          const stroke = val === 'B' ? '#000' : '#9CA3AF';
          svg += `<g pointer-events="none"><circle cx="${cx + 1}" cy="${cy + 1.5}" r="${stoneR}" fill="rgba(0,0,0,0.35)"/><circle cx="${cx}" cy="${cy}" r="${stoneR}" fill="${fill}" stroke="${stroke}" stroke-width="0.8"/><circle cx="${cx - stoneR / 3}" cy="${cy - stoneR / 3}" r="${stoneR / 3}" fill="rgba(255,255,255,${val === 'B' ? 0.18 : 0.6})"/>${isLast ? `<circle cx="${cx}" cy="${cy}" r="2.2" fill="#EF4444"/>` : ''}</g>`;
        }
        const clickable = val === 0 && engine.turn === 'B' && !engine.winner && !boardGame.isThinking;
        svg += `<rect data-bg-cell="${r},${c}" x="${cx - step / 2}" y="${cy - step / 2}" width="${step}" height="${step}" fill="transparent" style="cursor:${clickable ? 'pointer' : 'default'};"/>`;
      }
    }
    svg += `</svg>`;
    const cap = engine.captures || { B: 0, W: 0 };
    let info = `黑(我) 提子 ${cap.B} · 白(AI) 提子 ${cap.W} · 手数 ${engine.history.filter(h => !h.pass).length}`;
    if (engine.winner) {
      if (engine.resigned) info = '🏳️ ' + (engine.resigned === 'B' ? '你认输，白方（AI）获胜' : 'AI 认输，你获胜');
      else if (engine.scoreInfo) info = `终局数子：黑 ${engine.scoreInfo.B} 子 · 白 ${engine.scoreInfo.W} 子` + (engine.winner === 'draw' ? '（和棋）' : engine.winner === 'B' ? '（你获胜）' : '（AI 获胜）');
    } else if (engine.passes > 0) {
      info += ' · 有一方弃了一手';
    }
    container.innerHTML = `<div style="width:100%;display:flex;flex-direction:column;align-items:center;gap:4px;"><div style="font-size:11.5px;color:var(--ubp-text-2);text-align:center;">${info}</div>${svg}</div>`;
    container.querySelectorAll('[data-bg-cell]').forEach(el => {
      el.addEventListener('click', () => {
        if (boardGame.isThinking || engine.winner) return;
        if (engine.turn !== 'B') return;
        const [r, c] = el.dataset.bgCell.split(',').map(Number);
        const okGo = engine.makeMove(r, c, 'B');
        if (!okGo) { showToast('❌ 这手不合法（自杀 / 劫争 / 已有子）'); return; }
        boardGame.userMoves++;
        saveBoardGameState();
        renderBoardGameUI();
        triggerAISpeechCheck();
        if (!engine.winner) scheduleBoardAIMove('go', 350);
      });
    });
  }

  function goUserPass() {
    const engine = boardGame?.engine;
    if (!engine || engine.winner || boardGame.isThinking || engine.turn !== 'B') return;
    engine.pass('B');
    showToast('🙅 你选择了弃一手（双方连续弃手即终局数子）');
    saveBoardGameState();
    renderBoardGameUI();
    if (!engine.winner) scheduleBoardAIMove('go', 400);
  }

  function goUserResign() {
    const engine = boardGame?.engine;
    if (!engine || engine.winner) return;
    engine.resign('B');
    saveBoardGameState();
    renderBoardGameUI();
  }
