          <div data-bg-pick-opp="${escapeAttr(c.name)}" style="display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:${isSelected ? 'rgba(16,185,129,0.15)' : 'var(--ubp-card-2, #26262a)'};border:1.5px solid ${isSelected ? '#10B981' : 'var(--ubp-line)'};">
