      }).join('');

      ov.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex-none;">
          <span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">👥 邀请对弈角色</span>
          <button data-bg-act="close-invite-modal" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
        </div>
        <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">请选择 1 位角色与你执子对弈：</div>
        <div style="flex:1;overflow-y:auto;padding-right:2px;margin-bottom:8px;">
          ${oppListHtml || '<div style="font-size:12px;color:var(--ubp-text-3);">暂无可用角色（请先在大厅工作台创建自定义角色，或安装数据库本体），请确保神数据库已添加角色。</div>'}
        </div>
        <div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex-none;">
          <button data-bg-act="confirm-invite-modal" class="ubp-btn primary" style="padding:6px 20px;background:#10B981;font-size:13px;border-radius:6px;">确认邀请</button>
        </div>
      `;

      ov.querySelectorAll('[data-bg-pick-opp]').forEach(el => {
        el.addEventListener('click', () => {
          opponentName = el.dataset.bgPickOpp;
          renderInviteContent();
        });
      });

      ov.querySelector('[data-bg-act="close-invite-modal"]')?.addEventListener('click', () => ov.remove());
