  // ========== AI 落子统一调度 (避免撤销/切换对局时残留定时器) ==========
  let boardAITimer = null;

  function performBoardAIMove(type) {
    if (!boardGame || !boardGame.engine) return;
    const engine = boardGame.engine;
    if (engine.winner) { boardGame.isThinking = false; return; }
    // 实时难度：读当前配置（玩家改了设置立即生效），并回写对局缓存保证下一局读到新值
    boardGame.aiLevel = liveAiLevel(loadBoardConfig, boardGame.aiLevel);
    const level = boardGame.aiLevel;
    // 让让我：强力档不手软；softenPlayCount 每走一步消耗 1（旧代码只加不减，说一次"让让我"整局都在放水）
    const soften = boardGame.softenPlayCount > 0 && level !== 'strong';
    if (soften) boardGame.softenPlayCount = Math.max(0, boardGame.softenPlayCount - 1);
    if (type === 'go') {
      const m = engine.getBestMove('W', soften, level);
      if (m && m.pass) engine.pass('W');
      else if (m) engine.makeMove(m.r, m.c, 'W');
    } else if (type === 'gomoku') {
      const m = engine.getBestMove(2, soften, level);
      if (m) engine.makeMove(m.r, m.c, 2);
    } else if (type === 'luzhanqi') {
      const m = engine.getBestMove(getBoardAIColor(), soften, level);
      if (!m) { boardGame.isThinking = false; return; }
      engine.makeMove(m.fromR, m.fromC, m.toR, m.toC);
      lzqNotifyBattle();
    } else if (type === 'othello') {
      const m = engine.getBestMove(getBoardAIColor(), soften, level);
      if (!m) {
        // AI 无合法落子 → 跳过（引擎内部处理"双方都无法落子"的终局）
        if (engine.passTurn()) {
          boardGame.isThinking = false;
          saveBoardGameState();
          renderBoardGameUI();
          if (engine.winner) showToast('⏭️ 双方均无子可落，对局结束', null, 2400);
          else showToast('🤔 对方无子可落，跳过，轮到你继续', null, 2400);
        } else {
          boardGame.isThinking = false;
        }
        return;
      }
      engine.makeMove(m.r, m.c);
    } else {
      const m = engine.getBestMove(getBoardAIColor(), soften, level);
      if (!m) { boardGame.isThinking = false; return; }
      if (type === 'chess' || type === 'shogi') {
        engine.executeMove(m);
      } else {
        engine.makeMove(m.fromR, m.fromC, m.toR, m.toC);
      }
    }
    boardGame.isThinking = false;
    saveBoardGameState();
    renderBoardGameUI();
  }

  function scheduleBoardAIMove(type, delay) {
    if (boardAITimer) { clearTimeout(boardAITimer); boardAITimer = null; }
    boardGame.isThinking = true;
    renderBoardGameUI();
    boardAITimer = setTimeout(() => {
      boardAITimer = null;
      performBoardAIMove(type);
    }, delay);
  }

  // ========== 启动新棋局 (玩家永远在下方执子，随机决定先手) ==========
  // 有该棋类的进行中对局 → 直接回到之前的进度
  function resumeBoardGameIfSaved(type) {
    const d = findSavedBoardGame(type);
    if (!d) return false;
    resumeSavedBoardGame(type);
    showToast('🔖 已回到上次进行中的对局进度', null, 2600);
    return true;
  }

  function startNewBoardGame(type) {
    clearSavedBoardGame(type); // 开新局：只作废该棋类的进行中存档（其他棋类的进度保留）
    const cfg = loadBoardConfig();
    const result = loadContactsWithAvatars();
    const contacts = result?.contacts || [];

    bsClearTurnTimer(); // 若上一局海战棋还挂着 AI 回调，开局前先清掉，避免串场

    // 随机先手 (50% 玩家先手, 50% AI先手)
    const isUserFirst = Math.random() < 0.5;

    boardGame.gameType = type;
    boardGame.aiCompanion = cfg.aiCompanion;
    boardGame.speechInterval = cfg.speechInterval || 3;
    boardGame.aiLevel = cfg.aiLevel || 'normal';
    boardGame.userMoves = 0;
    boardGame.lastSpeech = '';
    boardGame.isThinking = false;
    boardGame.isGeneratingSpeech = false;
    boardGame.isUserFirst = isUserFirst;
    boardGame.softenPlayCount = 0;
    boardGame.conversation = [];
    boardGame.selectedPos = null;
    boardGame.validMoves = [];
    boardGame.selectedDropPiece = null;
    boardGame.validDrops = [];
    boardGame.pendingPromotion = null;
    boardGame.lzqSelectedPiece = null;
    lzqBoardScrollTop = -1;
    boardGame.isReviewingDefeat = false;
    boardGame.resultRecorded = false;
    boardGenCounter++;

    // 引擎初始化
    if (type === 'gomoku') boardGame.engine = new GomokuEngine(15);
    else if (type === 'xiangqi') boardGame.engine = new XiangqiEngine();
    else if (type === 'jungle') boardGame.engine = new JungleEngine();
    else if (type === 'chess') boardGame.engine = new ChessEngine();
    else if (type === 'shogi') boardGame.engine = new ShogiEngine();
    else if (type === 'battleship') boardGame.engine = new BattleshipEngine();
    else if (type === 'go') boardGame.engine = new GoEngine(9);
    else if (type === 'luzhanqi') boardGame.engine = new LuzhanqiEngine();
    else if (type === 'othello') boardGame.engine = new OthelloEngine();

    if (cfg.aiCompanion) {
      let oppContact = contacts.find(c => isNameMatch(c.name, cfg.opponentName)) || contacts[0];
      if (!oppContact) oppContact = { name: '棋圣', avatar: '', identity: '隐世高手' };
      boardGame.opponent = {
        name: oppContact.name,
        avatar: oppContact.avatar || getCharacterAvatarByName(oppContact.name),
        identity: oppContact.identity || ''
      };
      boardGame.lastSpeech = `请多指教！今天就让我们好好下一局${boardGameTitle(type)}吧~`;
    } else {
      boardGame.opponent = { name: '电脑AI', avatar: '', identity: '棋力大师' };
      boardGame.lastSpeech = '';
    }

    if (type === 'luzhanqi') {
      boardGame.engine.beginSetup(); // 军棋：先布阵，再选明局/暗局开战
      boardGame.lzqSelectedPiece = null;
      lzqBoardScrollTop = -1;
      renderLuzhanqiSetup();
      return;
    }

    if (type === 'battleship') {
      bsRandomPlaceShips('A');
      bsUI = { ori: 'H', activeShip: null, selectedSkills: [], armedSkill: null, reconMode: 'row', drag: null, moved: false, startX: 0, startY: 0, ghost: null, tip: null, suppressClick: false };
      bsHideSkillTip();
      renderBattleshipSetup();
      return;
    }

    if (type === 'othello') {
      boardGame.isUserFirst = true; // 黑白棋：黑方（玩家）固定先行
      boardGame.engine.turn = 'B';
    }

    saveBoardGameState();
    renderBoardGameUI();

    const oppName = boardGame.opponent?.name || '电脑AI';
    const toastMsg = isUserFirst ? '🎲 随机先手：【我】先行执子！' : `🎲 随机先手：【${oppName}】先行执子！`;
    showToast(toastMsg); // 旧代码传空回调 → 永不自动消失，挡住底部按钮

    // 规则统一：玩家永远执下方棋子 (五子棋黑1 / 象棋红'R' / 斗兽棋红'R' / 国际象棋白'W'/ 将棋先手'S')
    // 若 AI 先手，由上方棋子 (五子棋白2 / 象棋黑'B' / 斗兽棋蓝'B' / 国际象棋黑'B' / 将棋后手'G') 先行走子！
    if (!isUserFirst) {
      if (type === 'gomoku') boardGame.engine.turn = 2;
      else boardGame.engine.turn = getBoardAIColor();
      scheduleBoardAIMove(type, 500);
    }
  }

  function resumeSavedBoardGame(type) {
    try {
      const data = findSavedBoardGame(type || undefined);
      if (!data) { renderBoardLobby(); return; }
      try { localStorage.setItem(boardSaveKeyFor(data.gameType), JSON.stringify(data)); localStorage.removeItem(BOARD_SAVE_KEY); } catch (e2) { /* 旧档顺手迁移 */ }

      boardGame.gameType = data.gameType;
      boardGame.aiCompanion = data.aiCompanion;
      boardGame.speechInterval = data.speechInterval || 3;
      boardGame.aiLevel = data.aiLevel || 'normal';
      boardGame.userMoves = data.userMoves || 0;
      boardGame.lastSpeech = data.lastSpeech || '';
      boardGame.isUserFirst = typeof data.isUserFirst === 'boolean' ? data.isUserFirst : true;
      boardGame.softenPlayCount = data.softenPlayCount || 0;
      boardGame.conversation = data.conversation || [];
      boardGame.opponent = data.opponent;
      boardGenCounter++;
      boardGame.isThinking = false;
      boardGame.selectedPos = null;
      boardGame.validMoves = [];
      boardGame.selectedDropPiece = null;
      boardGame.validDrops = [];
      boardGame.pendingPromotion = null;

      if (data.gameType === 'luzhanqi') {
        boardGame.gameType = 'luzhanqi';
        boardGame.engine = LuzhanqiEngine.deserialize(data.lzq || {});
        boardGame.lzqSelectedPiece = null;
        boardGame.selectedPos = null;
        boardGame.validMoves = [];
        boardGame.isThinking = false;
        if (boardGame.engine.phase === 'setup') {
          renderLuzhanqiSetup();
        } else {
          renderBoardGameUI();
          const lzqE = boardGame.engine;
          if (!lzqE.winner && lzqE.turn === getBoardAIColor()) scheduleBoardAIMove('luzhanqi', 600);
        }
        return;
      }

      if (data.gameType === 'gomoku') {
        boardGame.engine = new GomokuEngine(15);
        boardGame.engine.board = data.board;
        boardGame.engine.history = data.history || [];
        boardGame.engine.turn = data.turn || 1;
        boardGame.engine.winner = data.winner || 0;
      } else if (data.gameType === 'xiangqi') {
        boardGame.engine = new XiangqiEngine();
        boardGame.engine.board = data.board;
        boardGame.engine.history = data.history || [];
        boardGame.engine.turn = data.turn || 'R';
        boardGame.engine.winner = data.winner || null;
      } else if (data.gameType === 'jungle') {
        boardGame.engine = new JungleEngine();
        boardGame.engine.board = data.board;
        boardGame.engine.history = data.history || [];
        boardGame.engine.turn = data.turn || 'R';
        boardGame.engine.winner = data.winner || null;
      } else if (data.gameType === 'chess') {
        boardGame.engine = new ChessEngine();
        boardGame.engine.board = data.board;
        boardGame.engine.history = data.history || [];
        boardGame.engine.turn = data.turn || 'W';
        boardGame.engine.winner = data.winner || null;
        if (data.castling) boardGame.engine.castling = data.castling;
        if (data.enPassantTarget) boardGame.engine.enPassantTarget = data.enPassantTarget;
      } else if (data.gameType === 'shogi') {
        boardGame.engine = new ShogiEngine();
        boardGame.engine.board = data.board;
        boardGame.engine.history = data.history || [];
        boardGame.engine.turn = data.turn || 'S';
        boardGame.engine.winner = data.winner || null;
        if (data.hand) boardGame.engine.hand = data.hand;
      } else if (data.gameType === 'battleship') {
        boardGame.engine = new BattleshipEngine();
        if (data.bs) bsHydrateBattleship(boardGame.engine, data.bs);
        boardGame.engine.turn = data.turn || 'P';
        boardGame.engine.winner = data.winner || null;
        boardGame.engine.history = data.history || [];
        bsUI = {
          ori: data.bsOri || 'H',
          activeShip: data.bsActiveShip || null,
          selectedSkills: data.bsSelectedSkills || [],
          armedSkill: null, reconMode: 'row', drag: null, moved: false,
          startX: 0, startY: 0, ghost: null, tip: null, suppressClick: false
        };
        if (boardGame.engine.phase === 'setup') { renderBattleshipSetup(); }
        else {
          renderBattleshipBattle();
          if (boardGame.engine.turn === 'A' && !boardGame.engine.winner) {
            boardGame.isThinking = true;
            renderBattleshipBattle();
            bsScheduleTurn(() => bsAITurn(), 650); // 纳入统一回合定时器，退出/重开可清理
          }
        }
        return;
      }

      if (data.gameType === 'othello') {
        // 黑白棋断点恢复
        boardGame.engine = OthelloEngine.deserialize(data);
      }

      if (data.gameType === 'go') {
        // 围棋断点恢复（此前缺失该分支，导致返回后无法回到进行中的棋局）
        boardGame.engine = new GoEngine(9);
        boardGame.engine.board = data.board || boardGame.engine.board;
        boardGame.engine.turn = data.turn || 'B';
        boardGame.engine.history = data.history || [];
        boardGame.engine.winner = data.winner || null;
        boardGame.engine.captures = data.captures || boardGame.engine.captures;
        boardGame.engine.koPoint = data.koPoint || null;
        boardGame.engine.passes = data.passes || 0;
      }

      renderBoardGameUI();
      // 存档可能正落在 AI 回合（玩家落子后立即写档）：恢复后必须补一次 AI 调度，否则无人走子卡死
      const bsNoWinner = boardGame.engine && (boardGame.engine.winner === null || boardGame.engine.winner === 0);
      const bsAiColor = data.gameType === 'gomoku' ? 2 : getBoardAIColor();
      if (bsNoWinner && boardGame.engine.turn === bsAiColor) scheduleBoardAIMove(data.gameType, 500);
    } catch (e) {
      console.error('[恢复对弈失败]', e);
      clearSavedBoardGame(type || undefined);
      renderBoardLobby();
    }
  }

  // ========== 棋局界面渲染 ==========
  function renderBoardGameUI() {
    if (!boardGame || !boardGame.engine) {
      renderBoardLobby();
      return;
    }

    if (boardGame.gameType === 'battleship') { renderBattleship(); return; }
    if (boardGame.gameType === 'luzhanqi' && boardGame.engine && boardGame.engine.phase === 'setup') { renderLuzhanqiSetup(); return; }

    const { gameType, engine, opponent, aiCompanion, lastSpeech, isThinking, isUserFirst } = boardGame;
    const userAvatar = getMainCharAvatar();
    const oppAvatar = opponent?.avatar || '';

    const gameTitle = boardGameTitle(gameType);

    detectBoardGameEnd();

    // 判断胜负
    let isWinner = false;
    let isDraw = false;
    let isUserWon = false;
    if (engine.winner !== 0 && engine.winner !== null) {
      isWinner = true;
      if (gameType === 'gomoku') {
        if (engine.winner === 3) isDraw = true;
        else isUserWon = engine.winner === 1; // 玩家始终是 1 (黑)
      } else {
        if (engine.winner === 'draw') isDraw = true;
        else isUserWon = engine.winner === getBoardUserColor();
      }
    }

        let statusText = isThinking ? '🤔 对方思考中...' : '👉 你的回合';
    if (boardGame.isReviewingDefeat) {
      statusText = '⏪ 失败环节回放（点击下方【刚刚的不算】可直接撤回重走）';
    } else if (isWinner) {
      statusText = isDraw ? '🤝 双方平局！' : isUserWon ? '🎉 你获胜了！' : '😢 对方获胜！';
    }
    if (gameType === 'luzhanqi') statusText = (engine.mode === 'dark' ? '🀄 暗局 · ' : '🎴 明局 · ') + statusText;
    if (gameType === 'othello' && !isWinner) statusText = '⚫' + engine.count('B') + ' · ⚪' + engine.count('W') + ' · ' + statusText;

    // 渲染主框架
    sheet.innerHTML = `
      <!-- 顶部信息栏 -->
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex-none;">
        <div style="display:flex;align-items:center;gap:8px;">
          <button data-bg-act="exit-to-lobby" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);flex:none;" title="返回对弈大厅">←</button>
          <div style="width:36px;height:36px;border-radius:50%;border:2px solid ${isThinking ? '#F59E0B' : '#10B981'};overflow:hidden;background:#10B981;flex-shrink:0;">
            ${oppAvatar ? `<img src="${oppAvatar}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;">${(opponent?.name || 'AI').slice(0,1)}</span>`}
          </div>
          <div>
            <div style="font-size:13.5px;font-weight:bold;color:var(--ubp-text);">${opponent?.name || '对手'}</div>
            <div style="font-size:11px;color:var(--ubp-text-3);">${gameTitle} · ${opponent?.identity || (aiCompanion ? '对弈角色' : '电脑AI')}</div>
          </div>
        </div>
        <div style="display:flex;gap:4px;">
          <button data-bg-act="quit-board-game" class="ubp-btn" style="padding:3px 8px;font-size:11.5px;" title="结束本局并清空该棋类进行中的进度">退出</button>
        </div>
      </div>

      <!-- 扩大的角色对话卡片 (本局所有发言均保留，可滚动查看) -->
      ${aiCompanion ? `
        <style>
          #bg-speech-container::-webkit-scrollbar { width: 5px; }
          #bg-speech-container::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); border-radius: 4px; }
          #bg-speech-container::-webkit-scrollbar-thumb { background: #10B981; border-radius: 4px; }
        </style>
        <div id="bg-speech-container" style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:8px;padding:8px 10px;margin-bottom:6px;box-shadow:0 2px 6px rgba(0,0,0,0.15);flex:none;height:96px;max-height:96px;overflow-y:scroll;scrollbar-width:thin;scrollbar-color:#10B981 rgba(0,0,0,0.2);box-sizing:border-box;">
          <div id="bg-speech-text" style="font-size:12.5px;color:var(--ubp-text);line-height:1.5;word-break:break-word;">
            ${renderConversationHTML()}
          </div>
        </div>
        <!-- 用户直接发言框 -->
        <div style="display:flex;gap:6px;margin-bottom:6px;flex-none;">
          <input id="bg-user-chat-input" class="ubp-fieldinput" type="text" placeholder="对${opponent?.name || 'TA'}说点什么... (如: 让让我嘛/这步厉害)" style="flex:1;font-size:12px;padding:4px 8px;border-radius:6px;height:26px;">
          <button data-bg-act="send-user-chat" class="ubp-btn primary" style="padding:0 10px;font-size:12px;height:26px;background:#10B981;flex-none;">发送</button>
        </div>
      ` : ''}

      <!-- 中间扩大棋盘区 -->
      <div style="display:flex;align-items:center;justify-content:center;flex:1;min-height:0;margin:2px 0;">
        <div id="bg-board-container" style="width:100%;max-width:315px;display:flex;align-items:center;justify-content:center;overflow:hidden;">
          <!-- SVG 棋盘挂载于此 -->
        </div>
      </div>

      <!-- 底部玩家状态区 -->
      <div style="display:flex;align-items:center;justify-content:space-between;margin-top:4px;padding-top:4px;border-top:1px solid var(--ubp-line);flex-none;">
        <div style="display:flex;align-items:center;gap:8px;">
          <div style="width:32px;height:32px;border-radius:50%;border:2px solid #8B5CF6;overflow:hidden;background:#8B5CF6;flex-shrink:0;">
            ${userAvatar ? `<img src="${userAvatar}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;">我</span>`}
          </div>
          <div>
            <div style="font-size:12.5px;font-weight:bold;color:var(--ubp-text);">我 (${isUserFirst ? '先手' : '后手'})</div>
            <div style="font-size:11.5px;font-weight:600;color:${isWinner ? '#10B981' : isThinking ? '#F59E0B' : 'var(--ubp-accent, #10B981)'};">${statusText}</div>
          </div>
        </div>
      </div>

      <!-- 将军提示 (红色，3秒自动隐藏) -->
      <div id="bg-check-notice" style="display:none;position:absolute;right:14px;bottom:72px;z-index:65;background:#EF4444;color:#fff;font-weight:bold;font-size:15px;padding:6px 16px;border-radius:6px;box-shadow:0 3px 10px rgba(0,0,0,0.55);letter-spacing:3px;">将军！</div>

      <!-- 底部操作按钮栏 -->
      <div style="display:flex;gap:8px;margin-top:6px;flex:none;">
        <button data-bg-act="undo-move" class="ubp-btn" style="flex:1;padding:6px;font-size:12px;background:var(--ubp-card-2);border:1px solid var(--ubp-line);">
          ↩️ 刚刚的不算
        </button>
        ${gameType === 'go' ? '<button data-bg-act="go-pass" class="ubp-btn" style="flex:1;padding:6px;font-size:12px;background:var(--ubp-card-2);border:1px solid var(--ubp-line);">🙅 弃一手</button><button data-bg-act="go-resign" class="ubp-btn" style="flex:1;padding:6px;font-size:12px;background:#EF4444;color:#fff;border:none;">🏳️ 认输</button>' : ''}
        <button data-bg-act="flip-table" class="ubp-btn" style="flex:1;padding:6px;font-size:12px;background:#EF4444;color:#fff;border:none;">
          💥 我要掀桌子
        </button>
      </div>
    `;

    // 绑定用户输入回车发送
    const chatInput = sheet.querySelector('#bg-user-chat-input');
    if (chatInput) {
      chatInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          handleUserChatSend();
        }
      });
    }

    // 挂载 SVG 棋盘
    const container = sheet.querySelector('#bg-board-container');
    if (container) {
      if (gameType === 'gomoku') renderSvgGomoku(container);
      else if (gameType === 'xiangqi') renderSvgXiangqi(container);
      else if (gameType === 'jungle') renderSvgJungle(container);
      else if (gameType === 'chess') renderSvgChess(container);
      else if (gameType === 'shogi') renderSvgShogi(container);
      else if (gameType === 'go') renderSvgGo(container);
      else if (gameType === 'luzhanqi') renderSvgLuzhanqi(container);
      else if (gameType === 'othello') renderSvgOthello(container);
    }

    // 将军提示（红色弹出，3 秒后自动隐藏）：象棋/国际象棋/将棋
    if ((gameType === 'xiangqi' || gameType === 'chess' || gameType === 'shogi') && typeof engine.isInCheck === 'function' && engine.winner === null && engine.isInCheck(engine.turn)) {
      showCheckNotice();
    }

    // 若胜利且不在失败回放复盘中，弹出结算悬浮窗
    if (isWinner && !boardGame.isReviewingDefeat) {
      showBoardGameOverModal(isUserWon, isDraw);
    }
  }

  // 统一终局检测：将死/困毙/逼和/无子可动
  function detectBoardGameEnd() {
    const engine = boardGame?.engine;
    if (!engine || engine.winner) return;
    const type = boardGame.gameType;
    if (type === 'gomoku') return;
    if (type === 'go') return;
    if (type === 'luzhanqi' && (!engine.phase || engine.phase !== 'play')) return;
    if (typeof engine.getAllMoves !== 'function') return;
    let noMoves = false;
    try { noMoves = engine.getAllMoves(engine.turn).length === 0; } catch (e) { return; }
    if (!noMoves) return;
    if (type === 'xiangqi' || type === 'jungle') {
      engine.winner = engine.turn === 'R' ? 'B' : 'R';
    } else if (type === 'chess') {
      // 国际象棋：被将死判负，无子可动为逼和
      if (typeof engine.isInCheck === 'function' && engine.isInCheck(engine.turn)) {
        engine.winner = engine.turn === 'W' ? 'B' : 'W';
      } else {
        engine.winner = 'draw';
      }
    } else if (type === 'shogi') {
      // 将棋：无逼和，无子可动直接判负
      engine.winner = engine.turn === 'S' ? 'G' : 'S';
    } else if (type === 'luzhanqi') {
      // 军棋：无子可走判负（对方获胜）
      engine.winner = engine.turn === 'R' ? 'B' : 'R';
    }
  }

  // 1. 渲染 SVG 五子棋盘
  function renderSvgGomoku(container) {
    const size = 15;
    const engine = boardGame.engine;
    const boardPixelSize = 300;
    const margin = 16;
    const gridWidth = boardPixelSize - 2 * margin;
    const step = gridWidth / (size - 1);

    let svg = `<svg viewBox="0 0 ${boardPixelSize} ${boardPixelSize}" width="100%" height="100%" style="display:block;user-select:none;max-height:300px;">`;
    svg += `<rect x="0" y="0" width="${boardPixelSize}" height="${boardPixelSize}" rx="8" fill="#E6C280" stroke="#78350F" stroke-width="3"/>`;

    for (let i = 0; i < size; i++) {
      const p = margin + i * step;
      svg += `<line x1="${margin}" y1="${p}" x2="${boardPixelSize - margin}" y2="${p}" stroke="#78350F" stroke-width="1.2"/>`;
      svg += `<line x1="${p}" y1="${margin}" x2="${p}" y2="${boardPixelSize - margin}" stroke="#78350F" stroke-width="1.2"/>`;
    }

    const starIndices = [[7, 7], [3, 3], [3, 11], [11, 3], [11, 11]];
    for (const [r, c] of starIndices) {
      svg += `<circle cx="${margin + c * step}" cy="${margin + r * step}" r="2.8" fill="#78350F"/>`;
    }

    const lastMove = engine.history.length ? engine.history[engine.history.length - 1] : null;
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        const val = engine.get(r, c);
        const cx = margin + c * step;
        const cy = margin + r * step;
        const isLast = lastMove && lastMove.r === r && lastMove.c === c;

        if (val === 1) { // 黑子 (玩家)
          svg += `
            <g pointer-events="none">
              <circle cx="${cx + 1}" cy="${cy + 1.5}" r="8" fill="rgba(0,0,0,0.4)"/>
              <circle cx="${cx}" cy="${cy}" r="8" fill="#111827"/>
              <circle cx="${cx - 2.5}" cy="${cy - 2.5}" r="2.5" fill="rgba(255,255,255,0.2)"/>
              ${isLast ? `<circle cx="${cx}" cy="${cy}" r="2" fill="#EF4444"/>` : ''}
            </g>
          `;
        } else if (val === 2) { // 白子 (AI)
          svg += `
            <g pointer-events="none">
              <circle cx="${cx + 1}" cy="${cy + 1.5}" r="8" fill="rgba(0,0,0,0.3)"/>
              <circle cx="${cx}" cy="${cy}" r="8" fill="#F9FAFB" stroke="#9CA3AF" stroke-width="0.8"/>
              <circle cx="${cx - 2.5}" cy="${cy - 2.5}" r="2.5" fill="rgba(255,255,255,0.6)"/>
              ${isLast ? `<circle cx="${cx}" cy="${cy}" r="2" fill="#EF4444"/>` : ''}
            </g>
          `;
        }

        svg += `<rect data-bg-cell="${r},${c}" x="${cx - step/2}" y="${cy - step/2}" width="${step}" height="${step}" fill="transparent" style="cursor:${val === 0 && !engine.winner && !boardGame.isThinking ? 'pointer' : 'default'};"/>`;
      }
    }

    svg += `</svg>`;
    container.innerHTML = svg;

    container.querySelectorAll('[data-bg-cell]').forEach(el => {
      el.addEventListener('click', () => {
        if (boardGame.isThinking || engine.winner) return;
        const [r, c] = el.dataset.bgCell.split(',').map(Number);
        const userPlayer = 1; // 玩家永远是 1 (黑)
        const aiPlayer = 2;   // AI 永远是 2 (白)

        if (engine.turn !== userPlayer) return;

        if (engine.makeMove(r, c, userPlayer)) {
          boardGame.userMoves++;
          saveBoardGameState();
          renderBoardGameUI();
          triggerAISpeechCheck();

          if (!engine.winner) {
            scheduleBoardAIMove('gomoku', 350);
          }
        }
      });
    });
  }

  // 2. 渲染 SVG 中国象棋棋盘
  function renderSvgXiangqi(container) {
    const engine = boardGame.engine;
    const selected = boardGame.selectedPos;
    const validMoves = boardGame.validMoves || [];
    const width = 295, height = 325;
    const marginX = 18, marginY = 16;
    const stepX = (width - 2 * marginX) / 8;
    const stepY = (height - 2 * marginY) / 9;

    let svg = `<svg viewBox="0 0 ${width} ${height}" width="100%" height="100%" style="display:block;user-select:none;max-height:325px;">`;
    svg += `<rect x="0" y="0" width="${width}" height="${height}" rx="8" fill="#FDE68A" stroke="#78350F" stroke-width="3"/>`;

    for (let r = 0; r < 10; r++) {
      const y = marginY + r * stepY;
      svg += `<line x1="${marginX}" y1="${y}" x2="${width - marginX}" y2="${y}" stroke="#78350F" stroke-width="1.2"/>`;
    }

    for (let c = 0; c < 9; c++) {
      const x = marginX + c * stepX;
      if (c === 0 || c === 8) {
        svg += `<line x1="${x}" y1="${marginY}" x2="${x}" y2="${height - marginY}" stroke="#78350F" stroke-width="1.5"/>`;
      } else {
        svg += `<line x1="${x}" y1="${marginY}" x2="${x}" y2="${marginY + 4 * stepY}" stroke="#78350F" stroke-width="1.2"/>`;
        svg += `<line x1="${x}" y1="${marginY + 5 * stepY}" x2="${x}" y2="${height - marginY}" stroke="#78350F" stroke-width="1.2"/>`;
      }
    }

    const riverY = marginY + 4.5 * stepY;
    svg += `<text x="${marginX + 1.5 * stepX}" y="${riverY + 4.5}" font-size="13" font-weight="bold" fill="#92400E" text-anchor="middle" font-family="serif">楚 河</text>`;
    svg += `<text x="${marginX + 6.5 * stepX}" y="${riverY + 4.5}" font-size="13" font-weight="bold" fill="#92400E" text-anchor="middle" font-family="serif">漢 界</text>`;

