          svg += `
            <g pointer-events="none">
              <circle cx="${cx + 1}" cy="${cy + 1.5}" r="${radius}" fill="rgba(0,0,0,0.3)"/>
              <circle cx="${cx}" cy="${cy}" r="${radius}" fill="${isRed ? '#FEF2F2' : '#F3F4F6'}" stroke="${isRed ? '#DC2626' : '#1F2937'}" stroke-width="1.6"/>
              <circle cx="${cx}" cy="${cy}" r="${radius - 2.5}" fill="none" stroke="${isRed ? 'rgba(220,38,38,0.25)' : 'rgba(31,41,55,0.25)'}" stroke-width="0.8"/>
              <text x="${cx}" y="${cy + 4.5}" font-size="12" font-weight="bold" fill="${isRed ? '#DC2626' : '#111827'}" text-anchor="middle" font-family="sans-serif">${charMap[p] || p}</text>
              ${isSelected ? `<circle cx="${cx}" cy="${cy}" r="${radius + 3}" fill="none" stroke="#10B981" stroke-width="2.5" stroke-dasharray="4,2"/>` : ''}
            </g>
          `;
        }

        if (isValidTarget) {
          svg += `<circle cx="${cx}" cy="${cy}" r="5" fill="#10B981" opacity="0.85" pointer-events="none"/>`;
        }

        svg += `<rect data-xq-pos="${r},${c}" x="${cx - stepX/2}" y="${cy - stepY/2}" width="${stepX}" height="${stepY}" fill="transparent" style="cursor:pointer;"/>`;
      }
    }

    svg += `</svg>`;
    container.innerHTML = svg;

    container.querySelectorAll('[data-xq-pos]').forEach(el => {
      el.addEventListener('click', () => {
        if (boardGame.isThinking || engine.winner) return;
        const [r, c] = el.dataset.xqPos.split(',').map(Number);
        const p = engine.board[r][c];
        const userColor = 'R';
        const aiColor = 'B';

        if (selected) {
          const [fr, fc] = selected;
          if (fr === r && fc === c) {
            boardGame.selectedPos = null;
            boardGame.validMoves = [];
            renderBoardGameUI();
            return;
          }
          if (validMoves.some(([tr, tc]) => tr === r && tc === c)) {
            engine.makeMove(fr, fc, r, c);
            boardGame.selectedPos = null;
            boardGame.validMoves = [];
            boardGame.userMoves++;
            saveBoardGameState();
            renderBoardGameUI();
            triggerAISpeechCheck();

            if (!engine.winner && engine.turn === aiColor) {
              scheduleBoardAIMove('xiangqi', 300);
            }
            return;
          }
        }

        if (p && engine.isRed(p) && engine.turn === userColor) {
          boardGame.selectedPos = [r, c];
          boardGame.validMoves = engine.getLegalMoves(r, c);
          renderBoardGameUI();
        } else {
          boardGame.selectedPos = null;
          boardGame.validMoves = [];
          renderBoardGameUI();
        }
      });
    });
  }

  // 3. 渲染 SVG 斗兽棋盘 (草坪绿/河浅蓝/陷阱红/穴黄色)
  function renderSvgJungle(container) {
