    };

    for (let r = 0; r < 9; r++) {
      for (let c = 0; c < 7; c++) {
        const x = marginX + c * stepX;
        const y = marginY + r * stepY;
        const isRiver = engine.isRiver(r, c);
        const isTrap = engine.isTrap(r, c);
