              <circle cx="${cx}" cy="${cy}" r="${radius}" fill="${isRed ? '#DC2626' : '#059669'}" stroke="#FFFFFF" stroke-width="1.6"/>
              <text x="${cx}" y="${cy + 1.5}" font-size="11.5" font-weight="bold" fill="#FFFFFF" text-anchor="middle" font-family="sans-serif">${nameMap[p] || p}</text>
              <text x="${cx}" y="${cy + 9}" font-size="7.5" font-weight="bold" fill="rgba(255,255,255,0.85)" text-anchor="middle">${rank}</text>
              ${isSelected ? `<circle cx="${cx}" cy="${cy}" r="${radius + 3}" fill="none" stroke="#10B981" stroke-width="2.5" stroke-dasharray="4,2"/>` : ''}
            </g>
          `;
