        const userColor = 'R';
        const aiColor = 'B';

        if (selected) {
          const [fr, fc] = selected;
          if (fr === r && fc === c) {
            boardGame.selectedPos = null;
            boardGame.validMoves = [];
            renderBoardGameUI();
            return;
          }
          if (validMoves.some(([tr, tc]) => tr === r && tc === c)) {
            engine.makeMove(fr, fc, r, c);
            boardGame.selectedPos = null;
            boardGame.validMoves = [];
            boardGame.userMoves++;
            saveBoardGameState();
            renderBoardGameUI();
            triggerAISpeechCheck();

            if (!engine.winner && engine.turn === aiColor) {
              scheduleBoardAIMove('jungle', 300);
            }
            return;
          }
        }

        if (p && p === p.toUpperCase() && engine.turn === userColor) {
          boardGame.selectedPos = [r, c];
          boardGame.validMoves = engine.getLegalMoves(r, c);
          renderBoardGameUI();
        } else {
          boardGame.selectedPos = null;
          boardGame.validMoves = [];
          renderBoardGameUI();
        }
      });
    });
  }

  // 4. 渲染 SVG 国际象棋棋盘 (8×8 黑白格 + Unicode 棋子)
  function renderSvgChess(container) {
    const engine = boardGame.engine;
    const selected = boardGame.selectedPos;
    const validMoves = boardGame.validMoves || [];
    const size = 8;
    const boardPixelSize = 300;
    const margin = 14;
    const step = (boardPixelSize - 2 * margin) / size;

    const unicode = {
      K: '♔', Q: '♕', R: '♖', B: '♗', N: '♘', P: '♙',
      k: '♚', q: '♛', r: '♜', b: '♝', n: '♞', p: '♟'
    };

    let svg = `<svg viewBox="0 0 ${boardPixelSize} ${boardPixelSize}" width="100%" height="100%" style="display:block;user-select:none;max-height:300px;">`;
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        const x = margin + c * step;
        const y = margin + r * step;
        const light = (r + c) % 2 === 0;
        svg += `<rect x="${x}" y="${y}" width="${step}" height="${step}" fill="${light ? '#F0D9B5' : '#B58863'}"/>`;
      }
    }
    svg += `<rect x="${margin - 2}" y="${margin - 2}" width="${boardPixelSize - 2 * margin + 4}" height="${boardPixelSize - 2 * margin + 4}" fill="none" stroke="#5B4636" stroke-width="3"/>`;
    const files = 'abcdefgh';
    for (let c = 0; c < 8; c++) {
      svg += `<text x="${margin + c * step + step / 2}" y="${boardPixelSize - 2}" font-size="9" fill="#5B4636" text-anchor="middle" font-family="sans-serif">${files[c]}</text>`;
      svg += `<text x="${margin - 5}" y="${margin + (7 - c) * step + step / 2 + 3}" font-size="9" fill="#5B4636" text-anchor="middle" font-family="sans-serif">${c + 1}</text>`;
    }

    const lastMove = engine.history.length ? engine.history[engine.history.length - 1] : null;
    for (let r = 0; r < 8; r++) {
      for (let c = 0; c < 8; c++) {
        const p = engine.board[r][c];
        const cx = margin + c * step + step / 2;
        const cy = margin + r * step + step / 2;
        const isSelected = selected && selected[0] === r && selected[1] === c;
        const isValidTarget = validMoves.some(m => m.toR === r && m.toC === c);
        const isLast = lastMove && ((lastMove.toR === r && lastMove.toC === c) || (lastMove.fromR === r && lastMove.fromC === c));
        if (isLast) svg += `<rect x="${margin + c * step + 1}" y="${margin + r * step + 1}" width="${step - 2}" height="${step - 2}" fill="rgba(255,213,0,0.4)"/>`;
        if (isSelected) svg += `<rect x="${margin + c * step + 1}" y="${margin + r * step + 1}" width="${step - 2}" height="${step - 2}" fill="rgba(16,185,129,0.45)"/>`;
        if (p) {
          const isWhite = engine.isWhite(p);
          svg += `<text x="${cx}" y="${cy + step * 0.32}" font-size="${step * 0.78}" text-anchor="middle" font-family="sans-serif" style="pointer-events:none;fill:${isWhite ? '#FFFFFF' : '#1F2937'};stroke:${isWhite ? '#374151' : '#000000'};stroke-width:0.7;">${unicode[p] || p.toUpperCase()}</text>`;
        }
        if (isValidTarget) {
          if (engine.board[r][c]) svg += `<circle cx="${cx}" cy="${cy}" r="${step * 0.46}" fill="none" stroke="#10B981" stroke-width="3"/>`;
          else svg += `<circle cx="${cx}" cy="${cy}" r="${step * 0.2}" fill="#10B981" opacity="0.85"/>`;
        }
        svg += `<rect data-chess-pos="${r},${c}" x="${margin + c * step}" y="${margin + r * step}" width="${step}" height="${step}" fill="transparent" style="cursor:pointer;"/>`;
      }
    }
    svg += `</svg>`;
    container.innerHTML = svg;

    container.querySelectorAll('[data-chess-pos]').forEach(el => {
      el.addEventListener('click', () => {
        if (boardGame.isThinking || engine.winner) return;
        const [r, c] = el.dataset.chessPos.split(',').map(Number);
        const p = engine.board[r][c];
        const userColor = 'W';
        const aiColor = 'B';

        if (selected) {
          const [fr, fc] = selected;
          if (fr === r && fc === c) {
            boardGame.selectedPos = null;
            boardGame.validMoves = [];
            renderBoardGameUI();
            return;
          }
          const mv = validMoves.find(m => m.toR === r && m.toC === c);
          if (mv) {
            engine.executeMove(mv);
            boardGame.selectedPos = null;
            boardGame.validMoves = [];
            boardGame.userMoves++;
            saveBoardGameState();
            renderBoardGameUI();
            triggerAISpeechCheck();
            if (!engine.winner && engine.turn === aiColor) {
              scheduleBoardAIMove('chess', 300);
            }
            return;
          }
        }

        if (p && engine.isWhite(p) && engine.turn === userColor) {
          boardGame.selectedPos = [r, c];
          boardGame.validMoves = engine.getLegalMoves(r, c);
          renderBoardGameUI();
        } else {
          boardGame.selectedPos = null;
          boardGame.validMoves = [];
          renderBoardGameUI();
        }
      });
    });
  }

  // 5. 渲染 SVG 将棋棋盘 (9×9 · 持驹台 + 打入 + 升变特殊按钮)
  function renderSvgShogi(container) {
    const engine = boardGame.engine;
    const selected = boardGame.selectedPos;
    const validMoves = boardGame.validMoves || [];
    const dropPiece = boardGame.selectedDropPiece;
    const validDrops = boardGame.validDrops || [];
    const pending = boardGame.pendingPromotion;

    const charMap = {
      K: '玉', k: '王',
      R: '飛', B: '角', G: '金', S: '銀', N: '桂', L: '香', P: '歩',
      D: '龍', H: '馬', M: '全', E: '圭', Y: '杏', T: 'と',
      r: '飛', b: '角', g: '金', s: '銀', n: '桂', l: '香', p: '歩',
      d: '龍', h: '馬', m: '全', e: '圭', y: '杏', t: 'と'
    };
    const handLabel = { R: '飛', B: '角', G: '金', S: '銀', N: '桂', L: '香', P: '歩' };
    const handOrder = ['R', 'B', 'G', 'S', 'N', 'L', 'P'];

    const width = 284, height = 284;
    const margin = 10;
    const step = (width - 2 * margin) / 9;

    const pentagon = (R) => `M 0 ${-R} L ${R * 0.92} ${-R * 0.08} L ${R * 0.55} ${R} L ${-R * 0.55} ${R} L ${-R * 0.92} ${-R * 0.08} Z`;

    let svg = `<svg viewBox="0 0 ${width} ${height}" width="100%" height="100%" style="display:block;user-select:none;max-height:284px;">`;
    svg += `<rect x="0" y="0" width="${width}" height="${height}" rx="6" fill="#EFE0BC" stroke="#8A5A24" stroke-width="2.5"/>`;
    for (let i = 0; i <= 9; i++) {
      const p = margin + i * step;
      svg += `<line x1="${margin}" y1="${p}" x2="${width - margin}" y2="${p}" stroke="#8A5A24" stroke-width="1"/>`;
      svg += `<line x1="${p}" y1="${margin}" x2="${p}" y2="${height - margin}" stroke="#8A5A24" stroke-width="1"/>`;
    }
    svg += `<rect x="${margin}" y="${margin}" width="${width - 2 * margin}" height="${height - 2 * margin}" fill="none" stroke="#5B3A1A" stroke-width="2"/>`;

    const lastMove = engine.history.length ? engine.history[engine.history.length - 1] : null;
    for (let r = 0; r < 9; r++) {
      for (let c = 0; c < 9; c++) {
        const p = engine.board[r][c];
        const cx = margin + c * step + step / 2;
        const cy = margin + r * step + step / 2;
        const isSelected = selected && selected[0] === r && selected[1] === c;
        const isValidTarget = validMoves.some(m => m.toR === r && m.toC === c);
        const isValidDrop = dropPiece && validDrops.some(m => m.toR === r && m.toC === c);
        const isLast = lastMove && lastMove.toR === r && lastMove.toC === c;

        if (isLast) svg += `<rect x="${margin + c * step + 1}" y="${margin + r * step + 1}" width="${step - 2}" height="${step - 2}" fill="rgba(255,213,0,0.35)"/>`;

        if (p) {
          const isUser = p === p.toUpperCase();
          const promoted = ['D','H','M','E','Y','T','d','h','m','e','y','t'].indexOf(p) !== -1;
          const fill = isUser ? '#F9EBCB' : '#E8CC9E';
          const stroke = isUser ? '#B45309' : '#7C2D12';
          const textColor = promoted ? '#DC2626' : (isUser ? '#7C2D12' : '#431407');
          const rot = isUser ? 0 : 180;
          const R = step * 0.62;
          svg += `<g transform="translate(${cx},${cy}) rotate(${rot})">
            <path d="${pentagon(R)}" fill="${fill}" stroke="${stroke}" stroke-width="1.4"/>
            <text y="${R * 0.16}" font-size="${step * 0.5}" font-weight="bold" fill="${textColor}" text-anchor="middle" font-family="sans-serif" transform="rotate(${-rot})">${charMap[p] || p}</text>
            ${isSelected ? `<path d="${pentagon(R + 2.5)}" fill="none" stroke="#10B981" stroke-width="2.2" stroke-dasharray="4,2"/>` : ''}
          </g>`;
        }

        if (isValidTarget) {
          if (p) svg += `<circle cx="${cx}" cy="${cy}" r="${step * 0.46}" fill="none" stroke="#10B981" stroke-width="2.5"/>`;
          else svg += `<circle cx="${cx}" cy="${cy}" r="${step * 0.2}" fill="#10B981" opacity="0.85"/>`;
        }
        if (isValidDrop) {
          svg += `<circle cx="${cx}" cy="${cy}" r="${step * 0.22}" fill="none" stroke="#F59E0B" stroke-width="2.5"/>`;
        }
        svg += `<rect data-shogi-pos="${r},${c}" x="${margin + c * step}" y="${margin + r * step}" width="${step}" height="${step}" fill="transparent" style="cursor:pointer;"/>`;
      }
    }
    svg += `</svg>`;

    // AI 持驹台 (上方, 只读)
    let aiHandHtml = '';
    for (const k of handOrder) {
      const n = engine.hand.G[k] || 0;
      if (n > 0) aiHandHtml += `<div style="font-size:11px;padding:1px 5px;border-radius:4px;background:#E8CC9E;color:#431407;border:1px solid #7C2D12;line-height:1.2;">${handLabel[k]}×${n}</div>`;
    }
    // 用户持驹台 (下方, 可点击打入)
    let userHandHtml = '';
    for (const k of handOrder) {
      const n = engine.hand.S[k] || 0;
      if (n > 0) {
        const active = dropPiece === k;
        userHandHtml += `<div data-shogi-hand="${k}" style="font-size:12px;padding:2px 6px;border-radius:5px;background:${active ? '#10B981' : '#F9EBCB'};color:${active ? '#fff' : '#78350F'};border:1px solid ${active ? '#059669' : '#B45309'};line-height:1.2;cursor:pointer;font-weight:bold;">${handLabel[k]}×${n}</div>`;
      }
    }

    let promoBarHtml = '';
    if (pending) {
      promoBarHtml = `
        <div style="display:flex;gap:6px;margin-top:4px;flex-wrap:nowrap;">
          <button data-shogi-promote="1" class="ubp-btn" style="flex:1;padding:4px 0;font-size:11.5px;background:#10B981;color:#fff;border:none;border-radius:5px;">🔺 成る（升变）</button>
          <button data-shogi-promote="0" class="ubp-btn" style="flex:1;padding:4px 0;font-size:11.5px;border-radius:5px;">成らず（不升变）</button>
          <button data-shogi-cancel class="ubp-btn" style="padding:4px 8px;font-size:11.5px;border-radius:5px;">取消</button>
        </div>`;
    }

    container.innerHTML = `
      <div style="display:flex;flex-direction:column;align-items:center;width:100%;gap:3px;">
        <div style="display:flex;gap:3px;flex-wrap:wrap;justify-content:center;min-height:16px;">${aiHandHtml || '<span style="font-size:10px;color:var(--ubp-text-3);">后手持驹 · 空</span>'}</div>
        ${svg}
        <div style="display:flex;gap:3px;flex-wrap:wrap;justify-content:center;min-height:20px;">${userHandHtml || '<span style="font-size:10px;color:var(--ubp-text-3);">先手持驹 · 空（点击持驹可打入）</span>'}</div>
        ${promoBarHtml}
      </div>
    `;

    const userColor = 'S';
    const aiColor = 'G';

    container.querySelectorAll('[data-shogi-pos]').forEach(el => {
      el.addEventListener('click', () => {
        if (boardGame.isThinking || engine.winner) return;
        if (boardGame.pendingPromotion) return;
        const [r, c] = el.dataset.shogiPos.split(',').map(Number);
        const p = engine.board[r][c];

        // 打进模式
        if (dropPiece) {
          const dm = validDrops.find(m => m.toR === r && m.toC === c);
          if (!p && dm) {
            engine.makeDrop(dropPiece, r, c);
            boardGame.selectedDropPiece = null;
            boardGame.validDrops = [];
            afterShogiUserMove();
          }
          return;
        }

        if (selected) {
          const [fr, fc] = selected;
          if (fr === r && fc === c) {
            boardGame.selectedPos = null;
            boardGame.validMoves = [];
            renderBoardGameUI();
            return;
          }
          const matches = validMoves.filter(m => m.toR === r && m.toC === c);
          if (matches.length === 1) {
            engine.executeMove(matches[0]);
            boardGame.selectedPos = null;
            boardGame.validMoves = [];
            afterShogiUserMove();
          } else if (matches.length > 1) {
            boardGame.pendingPromotion = { fromR: fr, fromC: fc, toR: r, toC: c };
            boardGame.selectedPos = null;
            boardGame.validMoves = [];
            renderBoardGameUI();
          } else {
            // 点击的是其它己方棋子或空位：落到下方重新选子/取消选中
          }
          if (matches.length > 0) return;
        }

        if (p && p === p.toUpperCase() && engine.turn === userColor) {
          boardGame.selectedPos = [r, c];
          boardGame.validMoves = engine.getLegalMoves(r, c);
          renderBoardGameUI();
        } else {
          boardGame.selectedPos = null;
          boardGame.validMoves = [];
          renderBoardGameUI();
        }
      });
    });

    container.querySelectorAll('[data-shogi-hand]').forEach(el => {
      el.addEventListener('click', () => {
        if (boardGame.isThinking || engine.winner) return;
        if (boardGame.pendingPromotion) return;
        const k = el.dataset.shogiHand;
        if (!(engine.hand.S[k] > 0)) return;
        if (dropPiece === k) {
          boardGame.selectedDropPiece = null;
          boardGame.validDrops = [];
        } else {
          boardGame.selectedDropPiece = k;
          boardGame.validDrops = engine.getLegalDrops('S', k);
          boardGame.selectedPos = null;
          boardGame.validMoves = [];
        }
        renderBoardGameUI();
      });
    });

    container.querySelector('[data-shogi-promote="1"]')?.addEventListener('click', () => {
      if (!pending) return;
      engine.makeMove(pending.fromR, pending.fromC, pending.toR, pending.toC, true);
      boardGame.pendingPromotion = null;
      afterShogiUserMove();
    });
    container.querySelector('[data-shogi-promote="0"]')?.addEventListener('click', () => {
      if (!pending) return;
      engine.makeMove(pending.fromR, pending.fromC, pending.toR, pending.toC, false);
      boardGame.pendingPromotion = null;
      afterShogiUserMove();
    });
    container.querySelector('[data-shogi-cancel]')?.addEventListener('click', () => {
      boardGame.pendingPromotion = null;
      renderBoardGameUI();
    });

    function afterShogiUserMove() {
      boardGame.userMoves++;
      boardGame.selectedDropPiece = null;
      boardGame.validDrops = [];
      boardGame.pendingPromotion = null;
      saveBoardGameState();
      renderBoardGameUI();
      triggerAISpeechCheck();
      if (!engine.winner && engine.turn === aiColor) {
        scheduleBoardAIMove('shogi', 300);
      }
    }
  }

  // ========== 游戏结算弹窗 ==========
  function showBoardGameOverModal(isUserWon, isDraw) {
