        </div>
                <div style="display:flex;gap:6px;">
          <button data-bg-act="exit-to-lobby" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12px;">🚪 退出</button>
          <button data-bg-act="review-defeat" class="ubp-btn" style="flex:1.2;padding:8px 0;font-size:12px;background:#3B82F6;color:#fff;border:none;font-weight:600;">⏪ 失败回放</button>
          <button data-bg-act="rematch" class="ubp-btn primary" style="flex:1.2;padding:8px 0;font-size:12px;background:#10B981;border:none;font-weight:600;">🔄 再来一局</button>
