    };
    checks.forEach(cb => cb.addEventListener('change', update));
    ov.querySelector('[data-spy-act="close-invite"]').addEventListener('click', () => ov.remove());
    confirmBtn.addEventListener('click', () => {
      const checked = ov.querySelectorAll('.spy-friend-check:checked');
      const selectedNames = Array.from(checked).map(c => c.value);
      const allContacts = loadContactsWithAvatars().contacts || [];
      // 人数未达标：由内置角色（角色N）补位，凑满本局人数
      const spyNeedFill = Math.max(0, max - selectedNames.length);
      if (spyNeedFill > 0) {
        let gi = 1, added = 0;
        while (added < spyNeedFill) {
          const g = '角色' + (gi++);
          if (selectedNames.indexOf(g) >= 0) continue;
          selectedNames.push(g); added++;
        }
        showToast('🪑 人数未达标，已由内置角色补位 ' + spyNeedFill + ' 位（凑满 6 人局）');
      }
      const selectedContacts = selectedNames.map(nm2 => allContacts.find(c => c && c.name === nm2) || { name: nm2, avatar: getCharacterAvatarByName(nm2) || '', identity: '' });
