  function startSpyGame() {
    if (!spyGame) return;
    const session = spyGame.session;
    spyGame.phase = 'words';
    saveSpyGameRecord();
    spyGame.round = 1;
    spyGame.currentSpeaker = 0;
    spyGame.winner = null;
    spyGame.replay = [];
    spyGame.history = [];
    spyGame.historyEntries = [];
    spyGame.players.forEach(p => {
      p.alive = true;
      p.role = '平民';
      p.isSpy = false;
      p.word = '';
      p.hasSpoken = false;
      p.votedFor = null;
    });

    renderSpyGameUI();
    addSpyLog('🕵️ 谁是卧底开始！正在请求AI主持人生成词语与分配身份，请稍候...', false);
    setSpyControlArea('<div style="text-align:center;padding:8px;color:#F59E0B;font-size:13px;font-weight:bold;">⏳ AI主持人正在生成词语并悄悄分发给各位玩家...</div>');

    const config = loadConfig();
    const playerNames = spyGame.players.map(p => `${p.position}号位 ${p.name}${p.isUser ? '（人类玩家）' : ''}`).join('、');

    const hostPrompt = `你现在是【谁是卧底】的唯一主持人，本局一共6名玩家：1名人类玩家，5名AI玩家。
游戏规则严格遵守：
1. 总共6人，1个卧底，5个平民。平民共用同一个词语，卧底拿到词义相近但不同的词语。
2. 开局第一件事：先公布本局游戏的词语（**只告诉主持人自己，不要直接发给所有人！**），然后悄悄分配词：
平民词：________
卧底词：________
> 你要记住这两个词，全程保密，不能直接把词语展示给人类玩家。
3. 开局流程：
① 开场白，告诉大家本局是6人局，1卧底5平民。
② 依次私聊分发词语：给5个AI玩家和平民人类玩家分别发词（人类玩家只看到自己的词，看不到其他人的）。分发词语的时候，不要泄露其他人的词。
③ 全部玩家拿到词之后，按顺序轮流发言，每个人用一句话描述自己的词语，**禁止说出词语本身、禁止说字数，不能太直白暴露词汇**。
④ 一轮全部发言结束后，开启投票环节：所有人投票选出怀疑的卧底，得票最高者出局。平票则无人出局，直接进入下一轮描述。
⑤ 胜负判定：
- 平民胜利：卧底被投出去。
- 卧底胜利：场上剩余3人时卧底存活，卧底获胜。
4. 你的工作：
只担任主持人，负责控场、顺序管理、提醒规则、统计投票、宣布出局、判断游戏胜负。
AI玩家会自己发言描述、投票。你不要替AI玩家发言，不要提前剧透词语。
5. 词语要求：两个词必须是同类、高度相近，适合谁是卧底，不能差距太大。
6. 【排版与格式铁律】：生成的词语绝对不能包含任何Markdown符号（例如禁止使用加粗星号、斜体、下划线、反引号等符号）、禁止使用双引号或书名号，必须输出纯净的中文词语！例如：平民词：牛肉面 卧底词：拉面
示例参考：牛肉面 / 拉面；婚纱 / 头纱；粽子 / 汤圆。

现在直接开始本局游戏，先生成本局的平民词和卧底词，然后开始分发词语，你一定要告诉他们每个人的词语是什么。
示例参考：XXX为牛肉面；XXX为牛肉面；XXX为牛肉面；XXX为牛肉面；XXX为拉面；XXX为牛肉面`;

    const requestPrompt = `${hostPrompt}

【本局场上6位玩家名单】：
${playerNames}

请按照要求生成平民词、卧底词，并按照示例格式为上述6位玩家分配词语。请在输出中明确包含类似格式：
平民词：XXX
卧底词：YYY
分发词语：玩家1为XXX；玩家2为XXX；玩家3为YYY...（其中1人拿到卧底词，另外5人拿到平民词）`;

    apiChat([
      { role: 'system', content: '你是【谁是卧底】的唯一主持人。负责主持游戏、设定词语并分配给每个角色。' },
      { role: 'user', content: requestPrompt }
    ], config, { maxTokens: 2500, timeout: 65000, temperature: 0.85 }).then(res => {
      if (!isSpySessionValid(session)) return;
      parseAndAssignSpyWords(res);
    }).catch(err => {
      if (!isSpySessionValid(session)) return;
      showToast(`AI主持人生成词语失败: ${err.message}，点击重试`, () => startSpyGame());
    });
  }

  // 从主持人输出里抓词：允许 Markdown 加粗、中英文冒号、书名号/方括号包裹等写法
  function extractSpyWord(res, label) {
    const cleaned = String(res || '').replace(/[*_`~]/g, '');
    const re = new RegExp(label + '\\s*[：:＝=]?\\s*[【「\\[《]?\\s*([^\\n\\r，,；;。】」\\]》]+?)\\s*[】」\\]》]?\\s*(?=[\\n\\r]|$)');
    const m = cleaned.match(re);
    if (!m) return '';
    return cleanSpyWord(m[1]);
  }

  function parseAndAssignSpyWords(res) {
    let civWord = '';
    let spyWord = '';

    civWord = extractSpyWord(res, '平民词');
    spyWord = extractSpyWord(res, '卧底词');

    const playerWords = {};
    spyGame.players.forEach(p => {
      const escapedName = p.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const reg = new RegExp(`(?:${p.position}\\s*号位|${escapedName})[^\\n，,；;。]*?[为是:：=]\\s*[【「\\[]?([^\\n\\r，,；;。】\\]]+)[】\\]]?`, 'i');
      const m = String(res || '').replace(/[*_`~]/g, '').match(reg);
      if (m) {
        playerWords[p.position] = cleanSpyWord(m[1]);
      }
    });

    const assignedList = Object.values(playerWords);
    if ((!civWord || !spyWord) && assignedList.length >= 2) {
      const counts = {};
      assignedList.forEach(w => counts[w] = (counts[w] || 0) + 1);
      const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
      if (sorted.length >= 2) {
        if (!civWord) civWord = cleanSpyWord(sorted[0][0]);
        if (!spyWord) spyWord = cleanSpyWord(sorted[sorted.length - 1][0]);
      }
    }

    if (!civWord || !spyWord || civWord === spyWord) {
      const wordPairs = [
        ['牛肉面', '拉面'],
        ['婚纱', '头纱'],
        ['粽子', '汤圆'],
        ['吉他', '尤克里里'],
        ['麦克风', '话筒'],
        ['口红', '唇膏'],
        ['风扇', '空调'],
        ['眉毛', '睫毛'],
        ['纸巾', '手帕'],
        ['自行车', '电动车']
      ];
      const pair = wordPairs[Math.floor(Math.random() * wordPairs.length)];
      civWord = pair[0];
      spyWord = pair[1];
    }

    civWord = cleanSpyWord(civWord);
    spyWord = cleanSpyWord(spyWord);

    spyGame.civilianWord = civWord;
    spyGame.spyWord = spyWord;

    // 卧底身份由代码随机指定，不再依赖 LLM 输出"XX为YYY"的分配语句（LLM 的分配本来就不可靠，
    // 且不同玩家可能拿到矛盾词）。LLM 只负责生成词对，身份与发词由本地代码决定。
    const spyPos = spyGame.players[Math.floor(Math.random() * spyGame.players.length)].position;

    spyGame.players.forEach(p => {
      p.isSpy = (p.position === spyPos);
      p.role = p.isSpy ? '卧底' : '平民';
      p.word = p.isSpy ? spyWord : civWord;
    });

    const user = spyGame.players[spyGame.userIndex];

    addSpyHiddenThought(`[主持人分词] 平民词:【${civWord}】；卧底词:【${spyWord}】。卧底是: ${spyPos}号位 ${spyGame.players.find(p => p.isSpy)?.name}`, null);

    addSpyLog(`📢 【谁是卧底】游戏正式开始！本局为6人局（1卧底、5平民）。`, true);
    addSpyLog(`🤫 主持人已将词语悄悄私聊分发给每位玩家。拿到词后，请按顺序轮流用一句话描述自己的词语。`, true);

    addSpyLog(`🔑 你的词语是：【${user.word}】`, false, null, '#FBBF24');

    renderSpyGameUI();

    spyGame.phase = 'speak';
    spyGame.round = 1;
    saveSpyGameRecord();
    startSpySpeaking();
  }

  function startSpySpeaking() {
    const session = spyGame?.session;
    if (!isSpySessionValid(session)) return;

    spyGame.phase = 'speak';
    saveSpyGameRecord();
    spyGame.players.forEach(p => {
      p.hasSpoken = false;
      p.votedFor = null;
    });

    spyGame.currentSpeaker = 0;
    while (spyGame.currentSpeaker < spyGame.players.length && !spyGame.players[spyGame.currentSpeaker].alive) {
      spyGame.currentSpeaker++;
    }

    if (spyGame.currentSpeaker >= spyGame.players.length) {
      startSpyVote();
      return;
    }

    renderSpyGameUI();
    addSpyLog(`💬 从 ${spyGame.players[spyGame.currentSpeaker].position}号位 ${spyGame.players[spyGame.currentSpeaker].name} 开始发言描述`, true);
    runCurrentSpySpeaker();
  }

  function runCurrentSpySpeaker() {
    const session = spyGame?.session;
    if (!isSpySessionValid(session) || spyGame.phase !== 'speak') return;

    const current = spyGame.players[spyGame.currentSpeaker];
    if (!current || !current.alive) {
      nextSpySpeaker();
      return;
    }

    if (current.isUser) {
      setSpyControlArea(`
        <div id="spy-speak-box" style="background:rgba(245,158,11,0.1);padding:6px 10px;border-radius:8px;border:1px solid rgba(245,158,11,0.3);margin:4px 0;">
          <div style="color:#FBBF24;font-size:13px;font-weight:bold;margin-bottom:4px;">🔑 你的词语是：${escapeHtml(current.word)}</div>
          <div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:6px;">轮到你的发言回合，请用一句话描述（严禁透露词语本身及字数）：</div>
          <div style="display:flex;gap:4px;">
            <input id="spy-speak-input" class="ubp-fieldinput" type="text" placeholder="你的词语是【${escapeHtml(current.word)}】，请输入描述..." style="flex:1;min-width:0;">
            <button data-spy-act="speak" class="ubp-btn primary" style="padding:0 12px;background:#F59E0B;border:none;font-weight:600;">发言</button>
            <button data-spy-act="speak-skip" class="ubp-btn" style="padding:0 10px;">跳过</button>
          </div>
        </div>
      `);
      const input = sheet.querySelector('#spy-speak-input');
      if (input) {
        input.focus();
        input.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            handleSpyUserSpeak();
          }
        });
      }
    } else {
      setSpyControlArea(`<div style="text-align:center;padding:6px;color:#F59E0B;">${current.name}（${current.position}号位）正在构思描述发言...</div>`);
      generateSpyAISpeech(current, () => {
        if (!isSpySessionValid(session) || spyGame.phase !== 'speak') return;
        current.hasSpoken = true;
        nextSpySpeaker();
      });
    }
  }

  function nextSpySpeaker() {
    const session = spyGame?.session;
    if (!isSpySessionValid(session) || spyGame.phase !== 'speak') return;

    let next = spyGame.currentSpeaker + 1;
    while (next < spyGame.players.length && (!spyGame.players[next].alive || spyGame.players[next].hasSpoken)) {
      next++;
    }

    if (next >= spyGame.players.length) {
      addSpyLog(`📢 全员描述发言完毕，进入投票放逐环节！`, true);
      startSpyVote();
    } else {
      spyGame.currentSpeaker = next;
      runCurrentSpySpeaker();
    }
  }

  function handleSpyUserSpeak() {
    const input = sheet.querySelector('#spy-speak-input');
    if (!input) return;
    const text = input.value.trim();
    if (!text) return;
    const current = spyGame.players[spyGame.currentSpeaker];
    addSpyLog(`🗣️ ${current.name}（${current.position}号位）: <speech>${text}</speech>`, true, current.position);
    current.hasSpoken = true;
    input.value = '';
    setSpyControlArea('');
    nextSpySpeaker();
  }

  function handleSpyUserSpeakSkip() {
    const current = spyGame.players[spyGame.currentSpeaker];
    addSpyLog(`🗣️ ${current.name}（${current.position}号位）: <speech>这轮我先过，听听大家怎么说。</speech>`, true, current.position);
    current.hasSpoken = true;
    saveSpyGameRecord();
    setSpyControlArea('');
    nextSpySpeaker();
