  function getSpyPlayerPersonalityPrompt(player) {
    if (!player || player.isUser) return '';
    const prof = getCharacterProfile(player.name);
    let info = `\n【你扮演的角色生平与性格底色（必须完全融入此人设进行言行）】：\n- 姓名：${player.name}\n`;
    if (prof) {
      if (prof.identity) info += `- 身份背景：${prof.identity}\n`;
      if (prof.personality) info += `- 性格特质：${prof.personality}\n`;
      if (prof.languageStyle) info += `- 说话习惯与语言口癖：${prof.languageStyle}\n`;
      if (prof.attitude) info += `- 【对主角（玩家本人）的态度与关系】：${prof.attitude}\n`;
      if (prof.brief) info += `- 人物简介：${prof.brief}\n`;
    } else {
      info += `- 基础设定：普通角色，以自然真人风格发挥。\n`;
    }
    if (spyGame?.players) {
      // 谁是卧底不做难度分档：始终提供本局人物关系
      info += getInterPersonalContext(player, spyGame.players);
    }
    return info;
  }

  function generateSpyAISpeech(player, callback) {
    const session = spyGame?.session;
    if (!isSpySessionValid(session)) return;

    const config = loadConfig();
    const persona = getSpyPlayerPersonalityPrompt(player);

    // 谁是卧底不做难度分档：始终提供全部历史发言
    const allSpeeches = (spyGame.historyEntries || [])
      .filter(e => e.type === 'public' && e.text.includes('<speech>'))
      .map(e => e.text.replace(/<\/?speech>/g, ''));
    const roundSpeeches = allSpeeches.join('\n');

    const prompt = `【这是谁是卧底桌游小剧场】
你正在扮演：${player.position}号位 ${player.name}。
当前进行到：第${spyGame.round}轮公开发言描述。
你的词语是：【${player.word}】（注意：请深深刻在心里，绝对不能在发言中直接说出这个词或透露字数！）。

${persona}

【前面所有已经发言玩家的公开发言描述如下】：
${roundSpeeches ? roundSpeeches : '（你是本轮第一个发言的玩家，前面暂无发言）'}

【公开发言描述核心硬性要求】：
1. 【游戏本质认知】：这是朋友间的《谁是卧底》聚会桌游小剧场！发言要有熟人间互动感，自然流露你角色的性格口吻、说话风格与口癖。
2. 【严格保密】：严禁直接说出词语【${player.word}】本身，严禁透露词语字数，绝不能过于直白暴露词汇！
3. 【必须给出全新不同描述】：你已经知道了上面所有玩家说了什么，你【必须生成与上面所有人截然不同的描述】，从不同的用途、特征、感受、场景等角度进行一句话描述！
4. 【格式铁律】：必须包含<thinking>与<speech>两部分：
   - 在<thinking>中分析你的词语特性，并对比上面玩家的发言，构思一个完全不同的描述切入点；
   - 在<speech>中以第一人称角色口吻说出你的一句话描述（20~60字，口语化，语意完整收尾，严禁包含动作描写或引号）。

严格输出格式：
<thinking>
思考你的词语与前面玩家发言的差异，规划不一样的描述切入点
</thinking>
<speech>
真正说出口的一句话描述
</speech>`;

    apiChat([
      { role: 'system', content: '你是谁是卧底桌游玩家。严格忠于角色性格，根据自己的词语给出一句话描述，绝对不能说出词语本身，且必须与前置位玩家的描述角度截然不同。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 2000, timeout: 65000 }).then(res => {
      if (!isSpySessionValid(session)) return;
      let thought = '';
      let speech = '';

      const mThought = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
      if (mThought) {
        thought = mThought[1].trim();
      } else {
        const speechIdx = res.indexOf('<speech>');
        if (speechIdx > 0) {
          thought = res.slice(0, speechIdx).replace(/<[^>]+>/g, '').trim();
        }
      }

      const mSpeech = res.match(/<speech>([\s\S]*?)(?:<\/speech>|$)/i);
      if (mSpeech) {
        speech = mSpeech[1].trim();
      } else {
        speech = res.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
      }

      speech = speech.replace(/【思考原因】/g, '').replace(/【公开发言】/g, '').replace(/<\/?thinking>/gi, '').replace(/<\/?speech>/gi, '').trim();

      if (!speech) speech = '嗯……这个东西大家生活里挺常见的，后置位继续听听看。';
      if (!thought) thought = `我拿到的词语是${player.word}，我需要从一个不易被怀疑、又不同于其他人的角度做描述。`;

      addSpyHiddenThought(thought, player.position);
      addSpyLog(`🗣️ ${player.name}（${player.position}号位）: <speech>${speech}</speech>`, true, player.position);
      callback();
    }).catch(err => {
      if (!isSpySessionValid(session)) return;
      showToast(`AI描述失败: ${err.message}，点击重试`, () => generateSpyAISpeech(player, callback));
    });
  }

