    spyGame.phase = 'vote';
    saveSpyGameRecord();
    spyGame.pickMode = null;
    spyGame.pick = { idx: null };

    const statusEl = sheet?.querySelector('#spy-game-status-text');
    if (statusEl) statusEl.textContent = `🕵️ 谁是卧底 · 第 ${spyGame.round} 轮 · 🗳️ 投票`;

    const user = spyGame.players[spyGame.userIndex];
    if (user && user.alive) {
      addSpyLog('🗳️ 发言完毕，进入投票环节！请点击上方存活玩家头像投票，或点击下方弃票', false);
      spyGame.pickMode = 'vote';
