        </div>
      `);
    } else {
      simulateSpyAIVotes();
    }
  }

  function handleSpyPickAvatar(targetEl) {
    if (!spyGame || spyGame.phase !== 'vote' || !spyGame.pickMode) return;
    const user = spyGame.players[spyGame.userIndex];
    if (!user || !user.alive) return;
    const idx = parseInt(targetEl.dataset.targetIdx);
    const targetPlayer = spyGame.players[idx];
    if (!targetPlayer || !targetPlayer.alive) return;

    spyGame.pick.idx = (spyGame.pick.idx === idx) ? null : idx;
    renderSpyGameUI();
    if (spyGame.pick.idx === null) {
      hideSpyActionPopup();
