        <button data-spy-act="spy-vote" class="ubp-btn primary" style="background:#F59E0B;color:#fff;padding:5px 2px;font-size:11px;font-weight:600;border-radius:4px;min-height:26px;line-height:1;border:none;">确认投票</button>
        <button data-spy-act="vote-skip" class="ubp-btn" style="padding:4px 2px;font-size:11px;border-radius:4px;min-height:24px;line-height:1;">弃票</button>
