    const user = spyGame.players[spyGame.userIndex];
    if (!user || !user.alive) return;
    user.votedFor = null;
    saveSpyGameRecord();
    spyGame.pick.idx = null;
    spyGame.pickMode = null;
    hideSpyActionPopup();
    renderSpyGameUI();
