  function restartSpyGame() {
    if (!spyGame) return;
    const prevPlayers = spyGame.players;
    const positions = [1, 2, 3, 4, 5, 6];
    for (let i = positions.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [positions[i], positions[j]] = [positions[j], positions[i]];
    }

    prevPlayers.forEach((p, idx) => p.position = positions[idx]);
    prevPlayers.sort((a, b) => a.position - b.position);

    spySessionCounter++;
    spyGame = {
      session: spySessionCounter,
      players: prevPlayers.map(p => ({
        ...p,
        alive: true,
        role: '平民',
        isSpy: false,
        word: '',
        votedFor: null,
        hasSpoken: false
      })),
      phase: 'idle',
      round: 1,
      currentSpeaker: 0,
      winner: null,
      civilianWord: '',
      spyWord: '',
      userIndex: prevPlayers.findIndex(p => p.isUser),
      history: [],
      historyEntries: [],
      replay: [],
      pickMode: null,
      pick: { idx: null },
      votes: {}
    };
    spyIsGameOver = false;
    spyReplayLogs = [];
    startSpyGame();
  }

  function showSpyReplay() {
