        }
        if (item.type === 'user_private') {
          return `<div style="color:${item.color || '#FBBF24'};margin:4px 0;font-size:12px;font-weight:600;">${escapeHtml(stripLogTags(item.text)).replace(/\n/g, '<br>')}</div>`;
