  function setSpyControlArea(html) {
    const area = sheet?.querySelector('#spy-game-control-area');
    if (area) area.innerHTML = html;
  }

function addSpyLog(msg, isPublic = true, authorPos = null, customColor = null) {
    const explicitColor = customColor || null;
    // 公开发言按角色名恒定配色；系统公告仍用默认色
    const charColor = explicitColor ? '' : (authorPos != null ? getGamePlayerColorByPos(spyGame, authorPos) : '');
    const color = explicitColor || charColor || '#fff';
    const log = sheet?.querySelector('#spy-game-log');
    if (log) {
      const div = document.createElement('div');
      const speaker = (spyGame && authorPos != null) ? getGamePlayerByPos(spyGame, authorPos) : null;
      if (speaker && speaker.name) {
        div.style.display = 'flex';
        div.style.alignItems = 'flex-start';
        div.style.gap = '5px';
        const av = document.createElement('span');
        av.style.cssText = 'flex:none;margin-top:1px;';
        av.innerHTML = chatAvatarHTML(speaker.name, !!speaker.isUser, 20);
        const txt = document.createElement('span');
        txt.textContent = stripLogTags(msg); // 聊天区只显示正文，剥离 <speech>/<private>/<thinking>；存储仍保留原文
        txt.style.cssText = 'flex:1;min-width:0;word-break:break-word;';
        div.appendChild(av);
        div.appendChild(txt);
      } else {
        div.textContent = stripLogTags(msg);
      }
      div.style.color = color;
      if (explicitColor || charColor) div.style.fontWeight = '600';
      log.appendChild(div);
      log.scrollTop = log.scrollHeight;
    }
    // 语音朗读：公开发言里的 <speech> 台词 → 按角色配置音色朗读（用户本人发言不读）
    if (isPublic && authorPos != null && !explicitColor && msg.indexOf('<speech>') >= 0 && typeof contactsVoiceAutoSpeak === 'function') {
      const vSpeaker = (spyGame && authorPos != null) ? getGamePlayerByPos(spyGame, authorPos) : null;
      const vMatch = String(msg).match(/<speech>([\s\S]*?)<\/speech>/i);
      if (vSpeaker && vSpeaker.name && !vSpeaker.isUser && vMatch && vMatch[1].trim()) contactsVoiceAutoSpeak(vSpeaker.name, vMatch[1].trim());
    }
    if (spyGame) {
      const entryType = explicitColor ? 'user_private' : (isPublic ? 'public' : 'system_private');
      if (spyGame.replay) spyGame.replay.push({ type: entryType, text: msg, authorPos, color: explicitColor || undefined });
      if (isPublic) {
        if (!spyGame.historyEntries) spyGame.historyEntries = [];
        spyGame.historyEntries.push({ type: 'public', text: msg, authorPos, round: spyGame.round });
        spyGame.history.push(msg);
      }
      saveSpyGameRecord(); // 每条日志落地：重进时不会整轮重播（此前最新存档停留在轮次开始）
    }
  }

  function addSpyHiddenThought(thoughtText, authorPos = null) {
    if (spyGame) {
      if (spyGame.replay) {
        spyGame.replay.push({ type: 'hidden', text: `[思考推演] ${thoughtText}`, authorPos });
      }
      if (!spyGame.historyEntries) spyGame.historyEntries = [];
      spyGame.historyEntries.push({
        type: 'thought',
        authorPos: authorPos,
        round: spyGame.round,
        text: `<thinking>${thoughtText}</thinking>`
      });
    }
  }

  function getSpyPlayerHistoryContext(player) {
    if (!spyGame) return '';
    // 谁是卧底不做难度分档：始终提供全部历史发言（同样加按字符数的软上限，避免长局撑爆提示词）
    if (spyGame.historyEntries && spyGame.historyEntries.length > 0) {
      const lines = [];
      for (const entry of spyGame.historyEntries) {
        if (entry.type === 'thought') {
          if (player && entry.authorPos === player.position) {
            lines.push(entry.text);
          }
        } else if (entry.type === 'public') {
          lines.push(entry.text);
        }
      }
      return capTextByChars(lines.join('\n'), 6000);
    }
    if (!spyGame.history) return '';
    return capTextByChars(spyGame.history.join('\n'), 6000);
  }

  function handleSpyAction(act, target) {
    if (act === 'back-setup') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      renderSetup();
      return;
    }
    if (act === 'back-board') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      renderSetup();
      return;
    }
    if (act === 'spy-resume') {
      resumeSavedSpyGame();
      return;
    }
    if (act === 'spy-discard-saved') {
      clearSavedSpyGame();
      renderSpyBoard();
      showToast('🗑️ 已放弃进行中的谁是卧底对局');
      return;
    }
    if (act === 'spy-back-board') {
      // ← 返回座位页：保留存档并中止当前异步流程，稍后可【继续对局】
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开对局：清空排队语音并切断在读语音
      saveSpyGameRecord();
      spySessionCounter++;
      spyGame = null;
      spyIsGameOver = true;
      renderSpyBoard();
      showToast('🔖 已返回座位页，对局进度已保存');
      return;
    }
    if (act === 'invite-friends') {
      renderSpyInvite();
      return;
    }
    if (act === 'start-game') {
      startSpyGame();
      return;
    }
    if (act === 'speak') {
      handleSpyUserSpeak();
      return;
    }
    if (act === 'speak-skip') {
      handleSpyUserSpeakSkip();
      return;
    }
    if (act === 'pick-avatar') {
      handleSpyPickAvatar(target);
      return;
    }
    if (act === 'spy-vote') {
      handleSpyUserVote();
      return;
    }
    if (act === 'vote-skip') {
      handleSpyUserVoteSkip();
      return;
    }
    if (act === 'exit-game') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      const ov = sheet?.querySelector('.spy-gameover-overlay');
      if (ov) ov.remove();
      spySessionCounter++;
      spyGame = null;
      spyIsGameOver = true;
      clearSavedSpyGame();
      renderSpyBoard();
      return;
    }
    if (act === 'restart-game') {
      const ov = sheet?.querySelector('.spy-gameover-overlay');
      if (ov) ov.remove();
      clearSavedSpyGame();
      restartSpyGame();
      return;
    }
    if (act === 'show-replay') {
      showSpyReplay();
      return;
    }
    if (act === 'close-replay') {
      const r = sheet?.querySelector('.spy-replay-overlay');
      if (r) r.remove();
      return;
    }
  }


  // ============================================================
  // ========== 石头剪刀布 (三局两胜) ==========
  // ============================================================
  // ========== 石头剪刀布：难度设置（本地配置，独立于棋类难度） ==========
  const RPS_CONFIG_KEY = 'werewolf_extension_rps_config';
  const RPS_LEVEL_LABEL = { fast: '快速', normal: '标准', strong: '强力' };
  const RPS_LEVELS = [
    { key: 'fast', label: '快速', desc: '纯随机出拳，适合放松娱乐' },
    { key: 'normal', label: '标准', desc: '70% 随机 + 30% 反制你上一手' },
    { key: 'strong', label: '强力', desc: '统计你最近 10 手偏好与"输后是否变招"，专抓习惯' }
  ];
  function loadRpsConfig() {
    try {
      const raw = localStorage.getItem(RPS_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (p.aiLevel !== 'fast' && p.aiLevel !== 'normal' && p.aiLevel !== 'strong') p.aiLevel = 'normal';
        return p;
      }
    } catch (e) { /* ignore */ }
    return { aiLevel: 'normal' };
  }
  function saveRpsConfig(cfg) {
    try { localStorage.setItem(RPS_CONFIG_KEY, JSON.stringify(cfg)); } catch (e) { /* ignore */ }
  }
  // 当前猜拳难度（优先读玩家刚改的配置，保证"设置即生效"）
  function rpsAiLevel() {
    return liveAiLevel(loadRpsConfig, (rpsGame && rpsGame.aiLevel) || 'normal');
  }

  // 猜拳难度设置面板（⚙️）
  function renderRPSLevelOverlay() {
    const cur = rpsAiLevel();
    const ov = document.createElement('div');
    ov.className = 'rps-level-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:60;background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex:none;">
        <span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">🧠 猜拳对手难度</span>
        <button data-rps-level="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
      </div>
      <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">选择对手的"读心"强度（即时生效：本局下一步起就用新难度，重进游戏依然保留）：</div>
      <div style="flex:1;overflow-y:auto;padding-right:2px;">
        ${RPS_LEVELS.map(l => `
          <div data-rps-level-opt="${l.key}" style="display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:8px;margin-bottom:8px;cursor:pointer;background:${l.key === cur ? 'rgba(239,68,68,0.15)' : 'var(--ubp-card-2, #26262a)'};border:1.5px solid ${l.key === cur ? '#EF4444' : 'var(--ubp-line)'};">
            <div style="flex:1;min-width:0;">
              <div style="font-size:14px;font-weight:600;color:var(--ubp-text);">${l.label}${l.key === cur ? ' 👑（当前）' : ''}</div>
              <div style="font-size:11.5px;color:var(--ubp-text-3);margin-top:2px;">${l.desc}</div>
            </div>
          </div>`).join('')}
      </div>
      <div style="font-size:11px;color:var(--ubp-text-3);padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">提示：该设置仅影响石头剪刀布的对手强度，保存在本机。</div>
    `;
    ov.querySelectorAll('[data-rps-level-opt]').forEach(el => {
      el.addEventListener('click', () => {
        const lvl = el.dataset.rpsLevelOpt;
        const cfg = loadRpsConfig();
        cfg.aiLevel = lvl;
        saveRpsConfig(cfg);
        if (rpsGame) rpsGame.aiLevel = lvl;
        ov.remove();
        showToast('🧠 猜拳对手难度已切换为：' + (RPS_LEVEL_LABEL[lvl] || '标准') + '（立即生效）');
        renderRPSGameUI();
      });
    });
    ov.querySelector('[data-rps-level="close"]')?.addEventListener('click', () => ov.remove());
    sheet.appendChild(ov);
  }

  let rpsGame = null;
  let rpsRoundTimer = null;

  const RPS_HAND_EMOJI = { rock: '✊', paper: '✋', scissors: '✌️' };
  const RPS_HAND_NAME = { rock: '石头', paper: '布', scissors: '剪刀' };

  const RPS_SAVE_KEY = 'werewolf_extension_rps_save';
  function hasSavedRps() {
    try {
      const raw = localStorage.getItem(RPS_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && d.opponent && ((d.meScore | 0) + (d.oppScore | 0) > 0 || (d.round | 0) > 1));
    } catch (e) { return false; }
  }
  function clearRpsSave() { try { localStorage.removeItem(RPS_SAVE_KEY); } catch (e) { /* ignore */ } }
  function saveRps() {
    try {
      const g = rpsGame;
      if (!g || g.phase === 'ended') { clearRpsSave(); return false; }
      const reveal = g.phase === 'reveal'; // 已出拳等待下一局：折算为下一局 pick 状态保存
      localStorage.setItem(RPS_SAVE_KEY, JSON.stringify({
        v: 1, opponent: g.opponent, meScore: g.meScore | 0, oppScore: g.oppScore | 0,
        round: reveal ? (g.round | 0) + 1 : (g.round | 0), aiLevel: g.aiLevel, history: g.history || []
      }));
      return true;
    } catch (e) { return false; }
  }
  function resumeRps() {
    let d = null;
    try { const raw = localStorage.getItem(RPS_SAVE_KEY); d = raw ? JSON.parse(raw) : null; } catch (e) { d = null; }
    if (!d || !d.opponent) { startRPSGame(); return; }
    if (rpsRoundTimer) { clearTimeout(rpsRoundTimer); rpsRoundTimer = null; }
    rpsGame = {
      opponent: d.opponent,
      meScore: d.meScore | 0,
      oppScore: d.oppScore | 0,
      round: Math.max(1, d.round | 0),
      phase: 'pick',
      aiLevel: d.aiLevel || liveAiLevel(loadRpsConfig, 'normal'),
      myPick: null,
      oppPick: null,
      roundResult: null,
      winner: null,
      history: Array.isArray(d.history) ? d.history : []
    };
    renderRPSGameUI();
    showToast('🔖 已恢复进行中的石头剪刀布（比分 ' + rpsGame.meScore + ':' + rpsGame.oppScore + ' · 第 ' + rpsGame.round + ' 局）');
  }

  function startRPSGame(wantOpponentName) {
    clearRpsSave();
    if (rpsRoundTimer) { clearTimeout(rpsRoundTimer); rpsRoundTimer = null; }
    const result = loadContactsWithAvatars();
    const contacts = result?.contacts || [];
    // 指定对手（再来一局/重开）时沿用原对手，不再静默换成通讯录第一个人
    const first = (wantOpponentName && contacts.find(c => c.name === wantOpponentName)) || contacts[0];
    rpsGame = {
      opponent: first
        ? { name: first.name, avatar: first.avatar || getCharacterAvatarByName(first.name) || '', identity: first.identity || '' }
        : { name: '电脑', avatar: '', identity: '猜拳大师' },
      meScore: 0,
      oppScore: 0,
      round: 1,
      phase: 'pick', // pick | reveal | ended
      aiLevel: liveAiLevel(loadRpsConfig, 'normal'), // 对手强度由本游戏的"⚙️ 难度"设置决定
      myPick: null,
      oppPick: null,
      roundResult: null,
      winner: null,
      history: []
    };
    renderRPSGameUI();
  }

  function rpsJudge(my, opp) {
    if (my === opp) return 'tie';
    const winMap = { rock: 'scissors', scissors: 'paper', paper: 'rock' };
    return winMap[my] === opp ? 'win' : 'lose';
  }

  // 对手手势分档（难度由猜拳自己的"⚙️ 难度"设置决定，默认标准）：
  //   快速 = 纯随机；标准 = 70% 随机 + 30% 反制我上一手；
  //   强力 = 统计我最近 10 手频率 + 连输后变招检测，并保证同一局面结果确定（无随机数）。
  function rpsOpponentPick(myHistory) {
    const options = ['rock', 'paper', 'scissors'];
    const lvl = liveAiLevel(loadRpsConfig, (rpsGame && rpsGame.aiLevel) || 'normal');
    const counterOf = (h) => ({ rock: 'paper', paper: 'scissors', scissors: 'rock' }[h] || 'rock'); // 能赢 h 的手势
    const hist = (myHistory || []).filter(x => x && x.my);
    if (lvl === 'fast' || !hist.length) return options[Math.floor(Math.random() * options.length)];
    if (lvl === 'normal') {
      if (Math.random() < 0.3) return counterOf(hist[hist.length - 1].my);
      return options[Math.floor(Math.random() * options.length)];
    }
    const recent = hist.slice(-10);
    const count = { rock: 0, paper: 0, scissors: 0 };
    for (const h of recent) if (count[h.my] !== undefined) count[h.my]++;
    let fav = 'rock';
    for (const k of options) if (count[k] > count[fav]) fav = k;
    // 连输后是否爱变招：统计"输掉之后的下一手"与"输掉那手"不同的比例（>=50% 视为爱变招）
    let changed = 0, chances = 0;
    for (let i = 1; i < recent.length; i++) {
      if (recent[i - 1].result === 'lose') { chances++; if (recent[i].my !== recent[i - 1].my) changed++; }
    }
    const likesToChange = chances > 0 && (changed / chances) >= 0.5;
    if (likesToChange) {
      // 爱变招：改按"第二偏好"反制（确定性，无随机）
      const sorted = options.slice().sort((a, b) => count[b] - count[a] || options.indexOf(a) - options.indexOf(b));
      fav = sorted[1] || fav;
    }
    return counterOf(fav);
  }

  function handleRpsPick(hand) {
    if (!rpsGame || rpsGame.phase !== 'pick') return;
    const oppHand = rpsOpponentPick(rpsGame.history);
    rpsGame.myPick = hand;
    rpsGame.oppPick = oppHand;
    rpsGame.roundResult = rpsJudge(hand, oppHand);
    if (rpsGame.roundResult === 'win') rpsGame.meScore++;
    else if (rpsGame.roundResult === 'lose') rpsGame.oppScore++;
    rpsGame.history.push({ round: rpsGame.round, my: hand, opp: oppHand, result: rpsGame.roundResult });

    const finished = rpsGame.meScore >= 2 || rpsGame.oppScore >= 2;
    if (finished) {
      rpsGame.phase = 'ended';
      rpsGame.winner = rpsGame.meScore >= 2 ? 'me' : 'opp';
      clearRpsSave();
      renderRPSGameUI();
      recordRPSFinished();
    } else {
      rpsGame.phase = 'reveal';
      renderRPSGameUI();
      if (rpsRoundTimer) clearTimeout(rpsRoundTimer);
      rpsRoundTimer = setTimeout(() => {
        rpsRoundTimer = null;
        if (!rpsGame || rpsGame.phase !== 'reveal') return;
        rpsGame.round++;
        rpsGame.phase = 'pick';
        rpsGame.myPick = null;
        rpsGame.oppPick = null;
        rpsGame.roundResult = null;
        renderRPSGameUI();
      }, 1600);
    }
  }

  function recordRPSFinished() {
    try {
      const oppName = rpsGame.opponent?.name || '电脑';
      const isUserWon = rpsGame.winner === 'me';
      onGameFinished({
        gameType: 'rps',
        userWon: !!isUserWon,
        result: isUserWon ? `主角以 ${rpsGame.meScore}:${rpsGame.oppScore} 击败 ${oppName}` : `${oppName}以 ${rpsGame.oppScore}:${rpsGame.meScore} 击败主角`,
        detail: `三局两胜，最终比分 ${rpsGame.meScore} : ${rpsGame.oppScore}`,
        players: [
          { name: '我', isUser: true, avatar: getMainCharAvatar() },
          { name: oppName, isUser: false, avatar: rpsGame.opponent?.avatar || '' }
        ],
        opponentName: rpsGame.opponent?.name || null
      });
    } catch (e) { /* ignore */ }
  }

  function showRPSGameOverModal() {
    const isWon = rpsGame.winner === 'me';
    const oppName = rpsGame.opponent?.name || '电脑';
    const modal = document.createElement('div');
    modal.className = 'rps-gameover-overlay';
    modal.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    modal.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 25px rgba(0,0,0,0.5);">
        <div style="font-size:36px;margin-bottom:8px;">${isWon ? '🎉' : '💔'}</div>
        <div style="font-size:16.5px;font-weight:bold;color:${isWon ? '#10B981' : '#EF4444'};margin-bottom:6px;">${isWon ? '你赢了！' : '你输了…'}</div>
        <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:14px;">${escapeHtml(oppName)} · 最终比分 ${rpsGame.meScore} : ${rpsGame.oppScore}</div>
        <div style="display:flex;gap:8px;">
          <button data-rps-act="rps-exit" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12.5px;">🚪 退出</button>
          <button data-rps-act="rps-rematch" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:12.5px;background:#10B981;border:none;">🔄 再来一局</button>
        </div>
      </div>
    `;
    sheet.appendChild(modal);
  }

  function renderRPSGameUI() {
    if (!rpsGame) { renderSetup(); return; }
    const opp = rpsGame.opponent;
    const oppAvatar = opp.avatar || getCharacterAvatarByName(opp.name);
    const userAvatar = getMainCharAvatar();
    const isReveal = rpsGame.phase === 'reveal' || rpsGame.phase === 'ended';

    let centerHtml = '';
    if (isReveal && rpsGame.myPick && rpsGame.oppPick) {
      const rr = rpsGame.roundResult;
      const rrText = rr === 'win' ? '🎉 你赢了这一局！' : rr === 'lose' ? '😢 对方赢了这一局！' : '🤝 平局！';
      const rrColor = rr === 'win' ? '#10B981' : rr === 'lose' ? '#EF4444' : '#F59E0B';
      centerHtml = `
        <div style="text-align:center;padding:8px 0;">
          <div style="display:flex;justify-content:center;align-items:center;gap:16px;margin:6px 0;">
            <div style="text-align:center;">
              <div style="font-size:46px;line-height:1;">${RPS_HAND_EMOJI[rpsGame.myPick]}</div>
              <div style="font-size:11px;color:var(--ubp-text-2);margin-top:4px;">我 · ${RPS_HAND_NAME[rpsGame.myPick]}</div>
            </div>
            <div style="font-size:22px;font-weight:bold;color:var(--ubp-text-2);">VS</div>
            <div style="text-align:center;">
              <div style="font-size:46px;line-height:1;">${RPS_HAND_EMOJI[rpsGame.oppPick]}</div>
              <div style="font-size:11px;color:var(--ubp-text-2);margin-top:4px;">${escapeHtml(opp.name)} · ${RPS_HAND_NAME[rpsGame.oppPick]}</div>
            </div>
          </div>
          <div style="font-size:15px;font-weight:bold;color:${rrColor};margin-top:6px;">${rrText}</div>
        </div>
      `;
    } else {
      centerHtml = `
        <div style="text-align:center;padding:12px 0;color:var(--ubp-text-2);font-size:13px;line-height:1.7;">
          点击下方手势出招 · 三局两胜<br>
          <span style="font-size:12px;color:var(--ubp-text-3);">当前比分 ${rpsGame.meScore} : ${rpsGame.oppScore}</span>
        </div>
      `;
    }

    const statusText = rpsGame.phase === 'ended'
      ? (rpsGame.winner === 'me' ? '🎉 你赢啦！' : '😢 你输了…')
      : `第 ${rpsGame.round} 局 · 三局两胜`;

    const pickDisabled = rpsGame.phase !== 'pick' ? 'disabled' : '';

    sheet.innerHTML = `
      <style>
        @keyframes rps-jump { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-6px)} }
        .rps-jump { animation: rps-jump 0.5s infinite; display:inline-block; }
      </style>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">
        <div style="display:flex;align-items:center;gap:6px;min-width:0;">
          <button data-rps-act="rps-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);flex:none;" title="返回小游戏对战大厅">←</button>
          <button data-rps-act="rps-invite" class="ubp-btn" style="padding:3px 10px;font-size:12px;">👥 邀请角色</button>
          <button data-rps-act="rps-level" class="ubp-btn" style="padding:3px 10px;font-size:12px;" title="调整猜拳对手的 AI 难度">⚙️ 难度：${RPS_LEVEL_LABEL[rpsAiLevel()] || '标准'}</button>
        </div>
        <button data-rps-act="rps-close" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="关闭本局并返回游戏中心，下次进入即重新开局">✕</button>
      </div>

      <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;flex:none;">
        <div style="width:46px;height:46px;border-radius:50%;overflow:hidden;background:#10B981;flex-shrink:0;border:2px solid var(--ubp-line);">
          ${oppAvatar ? `<img src="${oppAvatar}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;">${opp.name.slice(0,1)}</span>`}
        </div>
        <div style="flex:1;min-width:0;">
          <div style="font-size:14px;font-weight:600;color:var(--ubp-text);">${escapeHtml(opp.name)}</div>
          <div style="font-size:11px;color:var(--ubp-text-3);">${escapeHtml(opp.identity || '对手')} · ${statusText}</div>
        </div>
        <div style="flex:none;font-size:16px;font-weight:bold;color:#F59E0B;white-space:nowrap;">
          <span class="rps-jump">石头</span><span class="rps-jump" style="animation-delay:0.15s;">...</span><span class="rps-jump" style="animation-delay:0.3s;">剪刀</span><span class="rps-jump" style="animation-delay:0.45s;">...</span><span class="rps-jump" style="animation-delay:0.6s;">布!</span>
        </div>
      </div>

      <div style="flex:1;display:flex;align-items:center;justify-content:center;min-height:0;">${centerHtml}</div>

      <div style="display:flex;align-items:center;justify-content:center;gap:8px;margin-top:6px;flex:none;">
        <div style="width:40px;height:40px;border-radius:50%;overflow:hidden;background:#8B5CF6;border:2px solid var(--ubp-line);flex-shrink:0;">
          ${userAvatar ? `<img src="${userAvatar}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;">我</span>`}
        </div>
        <span style="font-size:13px;font-weight:600;color:var(--ubp-text);">我</span>
      </div>

      <div style="display:flex;gap:10px;justify-content:center;margin-top:10px;flex:none;">
        <button data-rps-act="rps-pick" data-hand="rock" class="ubp-btn" style="width:64px;height:64px;font-size:32px;border-radius:14px;background:var(--ubp-card-2);border:2px solid var(--ubp-line);cursor:pointer;" ${pickDisabled}>✊</button>
        <button data-rps-act="rps-pick" data-hand="paper" class="ubp-btn" style="width:64px;height:64px;font-size:32px;border-radius:14px;background:var(--ubp-card-2);border:2px solid var(--ubp-line);cursor:pointer;" ${pickDisabled}>✋</button>
        <button data-rps-act="rps-pick" data-hand="scissors" class="ubp-btn" style="width:64px;height:64px;font-size:32px;border-radius:14px;background:var(--ubp-card-2);border:2px solid var(--ubp-line);cursor:pointer;" ${pickDisabled}>✌️</button>
      </div>
    `;

    if (rpsGame.phase === 'ended' && !rpsGame.__modalShown) {
      rpsGame.__modalShown = true;
      showRPSGameOverModal();
    }
  }

  function renderRPSInviteOverlay() {
