        <div style="flex:1;overflow-y:auto;padding-right:2px;margin-bottom:8px;">
          ${listHtml || '<div style="font-size:12px;color:var(--ubp-text-3);">暂无可用角色（请先在大厅工作台创建自定义角色，或安装数据库本体），请确保神数据库已添加角色。</div>'}
        </div>
        <div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">
          <button data-rps-invite="confirm" class="ubp-btn primary" style="padding:6px 20px;background:#EF4444;font-size:13px;border-radius:6px;">确认邀请</button>
        </div>
      `;

      ov.querySelectorAll('[data-rps-pick]').forEach(el => {
        el.addEventListener('click', () => {
          chosenName = el.dataset.rpsPick;
          renderContent();
        });
      });
      ov.querySelector('[data-rps-invite="close"]')?.addEventListener('click', () => ov.remove());
      ov.querySelector('[data-rps-invite="confirm"]')?.addEventListener('click', () => {
        if (chosenName) {
          const c = contacts.find(x => x.name === chosenName);
          if (c) {
            rpsGame.opponent = { name: c.name, avatar: c.avatar || getCharacterAvatarByName(c.name) || '', identity: c.identity || '' };
          }
        }
        ov.remove();
        renderRPSGameUI();
      });
    };

    renderContent();
    sheet.appendChild(ov);
  }

  function handleRpsAction(act, target) {
    if (act === 'rps-invite') {
      renderRPSInviteOverlay();
      return;
    }
    if (act === 'rps-level') {
      renderRPSLevelOverlay();
      return;
    }
    if (act === 'rps-exit' || act === 'rps-close') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      const modal = sheet?.querySelector('.rps-gameover-overlay');
      if (modal) modal.remove();
      if (rpsRoundTimer) { clearTimeout(rpsRoundTimer); rpsRoundTimer = null; }
      if (act === 'rps-close') {
        clearRpsSave(); // ✕：结束本局并返回游戏中心（不保存进度）
        rpsGame = null;
        renderSetup();
        showToast('🚪 已关闭本局石头剪刀布');
      } else {
        const saved = saveRps(); // ←：保存进度并返回小游戏对战大厅
        rpsGame = null;
        renderAIBattleLobby();
        showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏对战大厅');
      }
      return;
    }
    if (act === 'rps-rematch') {
      const modal = sheet?.querySelector('.rps-gameover-overlay');
      if (modal) modal.remove();
      startRPSGame(rpsGame && rpsGame.opponent ? rpsGame.opponent.name : undefined); // 保留当前对手
      return;
    }
    if (act === 'rps-pick') {
      const hand = target.dataset.hand || '';
      if (hand) handleRpsPick(hand);
      return;
    }
  }

  // ============================================================
  // ========== 井字棋 (3×3 · 一局定胜负) ==========
  // ============================================================
  // ========== 井字棋：难度设置（本地配置，独立于棋类难度） ==========
  const TTT_CONFIG_KEY = 'werewolf_extension_ttt_config';
  const TTT_LEVEL_LABEL = { fast: '快速', normal: '标准', strong: '强力' };
  const TTT_LEVELS = [
    { key: 'fast', label: '快速', desc: '只顾眼前：能直接赢才赢，经常随手乱下，适合放松娱乐' },
    { key: 'normal', label: '标准', desc: '会抢中心、堵三连、看三步杀招，偶尔失误' },
    { key: 'strong', label: '强力', desc: '满盘搜索的完美棋手：零失误，能做的只有逼平' }
  ];
  function loadTttConfig() {
    try {
      const raw = localStorage.getItem(TTT_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (p.aiLevel !== 'fast' && p.aiLevel !== 'normal' && p.aiLevel !== 'strong') p.aiLevel = 'normal';
        return p;
      }
    } catch (e) { /* ignore */ }
    return { aiLevel: 'normal' };
  }
  function saveTttConfig(cfg) {
    try { localStorage.setItem(TTT_CONFIG_KEY, JSON.stringify(cfg)); } catch (e) { /* ignore */ }
  }
  // 当前井字棋难度（优先读玩家刚改的配置，保证"设置即生效"）
  function tttAiLevel() {
    return liveAiLevel(loadTttConfig, (tttGame && tttGame.aiLevel) || 'normal');
  }

  // 井字棋难度设置面板（⚙️）
  function renderTTTLevelOverlay() {
    const cur = tttAiLevel();
    const ov = document.createElement('div');
    ov.className = 'ttt-level-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:60;background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex:none;">
        <span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">🧠 井字棋对手难度</span>
        <button data-ttt-level="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
      </div>
      <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">选择对手棋力（即时生效：下一手起就用新难度，重进游戏依然保留）：</div>
      <div style="flex:1;overflow-y:auto;padding-right:2px;">
        ${TTT_LEVELS.map(l => `
          <div data-ttt-level-opt="${l.key}" style="display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:8px;margin-bottom:8px;cursor:pointer;background:${l.key === cur ? 'rgba(14,165,233,0.15)' : 'var(--ubp-card-2, #26262a)'};border:1.5px solid ${l.key === cur ? '#0EA5E9' : 'var(--ubp-line)'};">
            <div style="flex:1;min-width:0;">
              <div style="font-size:14px;font-weight:600;color:var(--ubp-text);">${l.label}${l.key === cur ? ' 👑（当前）' : ''}</div>
              <div style="font-size:11.5px;color:var(--ubp-text-3);margin-top:2px;">${l.desc}</div>
            </div>
          </div>`).join('')}
      </div>
      <div style="font-size:11px;color:var(--ubp-text-3);padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">提示：该设置仅影响井字棋的对手强度，保存在本机。</div>
    `;
    ov.querySelectorAll('[data-ttt-level-opt]').forEach(el => {
      el.addEventListener('click', () => {
        const lvl = el.dataset.tttLevelOpt;
        const cfg = loadTttConfig();
        cfg.aiLevel = lvl;
        saveTttConfig(cfg);
        if (tttGame) tttGame.aiLevel = lvl;
        ov.remove();
        showToast('🧠 井字棋对手难度已切换为：' + (TTT_LEVEL_LABEL[lvl] || '标准') + '（立即生效）');
        renderTTTGameUI();
      });
    });
    ov.querySelector('[data-ttt-level="close"]')?.addEventListener('click', () => ov.remove());
    sheet.appendChild(ov);
  }

  let tttGame = null;
  let tttAiTimer = null;
  const TTT_ME = 1;   // 主角（✕ · 先手）
  const TTT_OPP = 2;  // 对手（◯ · 后手）
  const TTT_DRAW = 3;
  const TTT_LINES = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
  const TTT_POS_NAMES = ['左上', '上中', '右上', '左中', '中央', '右中', '左下', '下中', '右下'];

  function tttWinner(board) {
    for (const line of TTT_LINES) {
      const a = line[0], b = line[1], c = line[2];
      if (board[a] && board[a] === board[b] && board[b] === board[c]) return board[a];
    }
    return board.every(v => v) ? TTT_DRAW : 0;
  }
  function tttWinningLine(board) {
    for (const line of TTT_LINES) {
      const a = line[0], b = line[1], c = line[2];
      if (board[a] && board[a] === board[b] && board[b] === board[c]) return line;
    }
    return null;
  }
  function tttEmptyCells(board) {
    const out = [];
    for (let i = 0; i < 9; i++) if (!board[i]) out.push(i);
    return out;
  }
  // 极大极小：以对手（AI）视角打分，+10 赢 / -10 输 / 0 平；depth 为剩余搜索层数
  function tttMinimax(board, player, depth) {
    const w = tttWinner(board);
    if (w === TTT_DRAW) return 0;
    if (w) return w === TTT_OPP ? 10 : -10;
    if (depth <= 0) return 0;
    const empties = tttEmptyCells(board);
    let best = player === TTT_OPP ? -Infinity : Infinity;
    for (const i of empties) {
      board[i] = player;
      const s = tttMinimax(board, player === TTT_OPP ? TTT_ME : TTT_OPP, depth - 1);
      board[i] = 0;
      if (player === TTT_OPP) { if (s > best) best = s; }
      else if (s < best) best = s;
    }
    return best;
  }

  // 对手落子：快速=只看眼前+高频随手；标准=看三步+偶尔失误；强力=全盘搜索零失误
  // 分档参数统一取自难度中枢 getDifficulty('ttt', level)（depth / blunder / noise）
  function tttAiMove() {
    const g = tttGame;
    if (!g) return -1;
    const lvl = tttAiLevel();
    const D = getDifficulty('ttt', lvl);
    const board = g.board.slice();
    const empties = tttEmptyCells(board);
    if (!empties.length) return -1;
    const rng = pickRng(lvl, 'ttt|' + board.join('') + '|' + (g.moveCount || 0));
    const pick = arr => arr[Math.floor(rng() * arr.length)];
    // 主动失误：随机落子（仍保留"能直接赢就赢"的直觉），快速档最容易看到
    if (rng() < (D.blunder || 0)) {
      const winNow = empties.filter(i => {
        board[i] = TTT_OPP;
        const v = tttWinner(board) === TTT_OPP;
        board[i] = 0;
        return v;
      });
      return winNow.length ? winNow[0] : pick(empties);
    }
    const depth = Math.max(1, Math.min(9, D.depth || 1));
    let bestScore = -Infinity;
    let bestMoves = [];
    for (const i of empties) {
      board[i] = TTT_OPP;
      let sc = tttMinimax(board, TTT_ME, depth - 1);
      board[i] = 0;
      if (D.noise) sc += (rng() - 0.5) * D.noise;
      if (sc > bestScore + 1e-9) { bestScore = sc; bestMoves = [i]; }
      else if (Math.abs(sc - bestScore) <= 1e-9) bestMoves.push(i);
    }
    return pick(bestMoves);
  }

  // 先手随机分配：先手执 ✕、后手执 ◯
  function tttSymOf(seat, g) {
    const firstSeat = g.userFirst ? TTT_ME : TTT_OPP;
    return seat === firstSeat ? '✕' : '◯';
  }

  // 对手思考并落子（主角后手时开局也走这里）
  function tttScheduleAiMove(g, delay) {
    if (tttAiTimer) clearTimeout(tttAiTimer);
    const oppName = g.opponent?.name || '电脑';
    tttAiTimer = setTimeout(() => {
      tttAiTimer = null;
      if (tttGame !== g || g.phase !== 'play' || g.turn !== TTT_OPP) return;
      if (!sheet || !sheet.querySelector('[data-ttt-act="ttt-cell"]')) return; // 界面已切走则不落子
      const mv = tttAiMove();
      if (mv >= 0) {
        g.board[mv] = TTT_OPP;
        g.moveCount++;
        g.lastMove = mv;
        g.log.push(oppName + ' ' + tttSymOf(TTT_OPP, g) + ' → ' + (TTT_POS_NAMES[mv] || mv));
      }
      g.thinking = false;
      const w2 = tttWinner(g.board);
      if (w2) { tttFinish(w2); return; }
      g.turn = TTT_ME;
      renderTTTGameUI();
    }, delay);
  }

  const TTT_SAVE_KEY = 'werewolf_extension_ttt_save';
  function hasSavedTtt() {
    try {
      const raw = localStorage.getItem(TTT_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && Array.isArray(d.board) && d.board.length === 9 && d.phase === 'play' && (d.moveCount | 0) > 0);
    } catch (e) { return false; }
  }
  function clearTttSave() { try { localStorage.removeItem(TTT_SAVE_KEY); } catch (e) { /* ignore */ } }
  function saveTtt() {
    try {
      const g = tttGame;
      if (!g || g.phase === 'ended') { clearTttSave(); return false; }
      localStorage.setItem(TTT_SAVE_KEY, JSON.stringify({
        v: 1, phase: 'play', opponent: g.opponent, board: g.board, userFirst: !!g.userFirst, turn: g.turn,
        aiLevel: g.aiLevel, moveCount: g.moveCount | 0, lastMove: g.lastMove, log: g.log || []
      }));
      return true;
    } catch (e) { return false; }
  }
  function resumeTtt() {
    let d = null;
    try { const raw = localStorage.getItem(TTT_SAVE_KEY); d = raw ? JSON.parse(raw) : null; } catch (e) { d = null; }
    if (!d || !Array.isArray(d.board) || d.board.length !== 9) { startTTTGame(); return; }
    if (tttAiTimer) { clearTimeout(tttAiTimer); tttAiTimer = null; }
    tttGame = {
      opponent: d.opponent || { name: '电脑', avatar: '', identity: '井字棋棋手' },
      board: d.board.slice(0, 9),
      userFirst: !!d.userFirst,
      turn: d.turn === TTT_OPP ? TTT_OPP : TTT_ME,
      phase: 'play',
      winner: null,
      aiLevel: d.aiLevel || liveAiLevel(loadTttConfig, 'normal'),
      moveCount: d.moveCount | 0,
      lastMove: (d.lastMove === undefined ? -1 : d.lastMove),
      thinking: false,
      winLine: null,
      log: Array.isArray(d.log) ? d.log : []
    };
    renderTTTGameUI();
    showToast('🔖 已恢复进行中的井字棋（已落子 ' + tttGame.moveCount + ' 手）');
    if (tttGame.turn === TTT_OPP) {
      const delay = tttGame.aiLevel === 'fast' ? 320 : tttGame.aiLevel === 'strong' ? 640 : 480;
      tttScheduleAiMove(tttGame, delay);
    }
  }

  function startTTTGame(wantOpponentName) {
    clearTttSave();
    if (tttAiTimer) { clearTimeout(tttAiTimer); tttAiTimer = null; }
    const result = loadContactsWithAvatars();
    const contacts = result?.contacts || [];
    // 指定对手（再来一局/重开）时沿用原对手，不再静默换成通讯录第一个人
    const first = (wantOpponentName && contacts.find(c => c.name === wantOpponentName)) || contacts[0];
    const userFirst = Math.random() < 0.5; // 先手随机分配
    tttGame = {
      opponent: first
        ? { name: first.name, avatar: first.avatar || getCharacterAvatarByName(first.name) || '', identity: first.identity || '' }
        : { name: '电脑', avatar: '', identity: '井字棋棋手' },
      board: new Array(9).fill(0),
      userFirst: userFirst,
      turn: userFirst ? TTT_ME : TTT_OPP,
      phase: 'play', // play | ended
      winner: null, // me | opp | draw
      aiLevel: liveAiLevel(loadTttConfig, 'normal'), // 对手强度由本游戏的"⚙️ 难度"设置决定
      moveCount: 0,
      lastMove: -1,
      thinking: !userFirst,
      winLine: null,
      log: []
    };
    renderTTTGameUI();
    if (!userFirst) {
      const delay = tttGame.aiLevel === 'fast' ? 320 : tttGame.aiLevel === 'strong' ? 640 : 480;
      tttScheduleAiMove(tttGame, delay);
    }
  }

  function tttFinish(w) {
    const g = tttGame;
    if (!g || g.phase === 'ended') return;
    g.phase = 'ended';
    g.thinking = false;
    g.winLine = tttWinningLine(g.board);
    g.winner = w === TTT_ME ? 'me' : (w === TTT_OPP ? 'opp' : 'draw');
    clearTttSave();
    renderTTTGameUI();
    recordTTTFinished();
  }

  function handleTttCell(idx) {
    const g = tttGame;
    if (!g || g.phase !== 'play' || g.turn !== TTT_ME || g.thinking) return;
    if (!Number.isInteger(idx) || idx < 0 || idx > 8 || g.board[idx]) return;
    g.board[idx] = TTT_ME;
    g.moveCount++;
    g.lastMove = idx;
    g.log.push('主角 ' + tttSymOf(TTT_ME, g) + ' → ' + (TTT_POS_NAMES[idx] || idx));
    const w = tttWinner(g.board);
    if (w) { tttFinish(w); return; }
    g.turn = TTT_OPP;
    g.thinking = true;
    renderTTTGameUI();
    const delay = g.aiLevel === 'fast' ? 320 : g.aiLevel === 'strong' ? 640 : 480;
    tttScheduleAiMove(g, delay);
  }

  function recordTTTFinished() {
    try {
      const oppName = tttGame.opponent?.name || '电脑';
      const isDraw = tttGame.winner === 'draw';
      const isUserWon = tttGame.winner === 'me';
      onGameFinished({
        gameType: 'ttt',
        userWon: !isDraw && !!isUserWon,
        isDraw: isDraw,
        result: isDraw ? `主角与 ${oppName} 井字棋握手言和` : (isUserWon ? `主角在井字棋中击败 ${oppName}` : `${oppName}在井字棋中击败主角`),
        detail: `一局定胜负（先手随机）：主角执 ${tttSymOf(TTT_ME, tttGame)} ${tttGame.userFirst ? '先手' : '后手'}、${oppName}执 ${tttSymOf(TTT_OPP, tttGame)} ${tttGame.userFirst ? '后手' : '先手'}，共落子 ${tttGame.moveCount} 手（难度：${TTT_LEVEL_LABEL[tttGame.aiLevel] || '标准'}）`,
        replay: (tttGame.log || []).join('\n'),
        players: [
          { name: '我', isUser: true, avatar: getMainCharAvatar() },
          { name: oppName, isUser: false, avatar: tttGame.opponent?.avatar || '' }
        ],
        opponentName: tttGame.opponent?.name || null
      });
    } catch (e) { /* ignore */ }
  }

  function showTTTGameOverModal() {
    const g = tttGame;
    const isDraw = g.winner === 'draw';
    const isWon = g.winner === 'me';
    const oppName = g.opponent?.name || '电脑';
    const modal = document.createElement('div');
    modal.className = 'ttt-gameover-overlay';
    modal.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    modal.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 25px rgba(0,0,0,0.5);">
        <div style="font-size:36px;margin-bottom:8px;">${isDraw ? '🤝' : isWon ? '🎉' : '💔'}</div>
        <div style="font-size:16.5px;font-weight:bold;color:${isDraw ? '#F59E0B' : isWon ? '#10B981' : '#EF4444'};margin-bottom:6px;">${isDraw ? '平局！' : isWon ? '你赢了！' : '你输了…'}</div>
