        });
      });
      ov.querySelector('[data-ttt-invite="close"]')?.addEventListener('click', () => ov.remove());
      ov.querySelector('[data-ttt-invite="confirm"]')?.addEventListener('click', () => {
        if (chosenName) {
          const c = contacts.find(x => x.name === chosenName);
          if (c) {
