        return `
          <div data-ddz-pick="${escapeHtml(c.name).replace(/"/g, '&quot;')}" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:${isSelected ? 'rgba(220,38,38,0.15)' : 'var(--ubp-card-2, #26262a)'};border:1.5px solid ${isSelected ? '#DC2626' : 'var(--ubp-line)'};">
