      ov.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">
          <span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">👥 邀请 2 位角色入座</span>
          <button data-ddz-invite="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
        </div>
        <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">已选 <b style="color:#DC2626;">${chosen.length}</b> / 2 位（选满 2 位后点击确认即可入座开局）</div>
        <div style="flex:1;overflow-y:auto;padding-right:2px;margin-bottom:8px;">
          ${listHtml || '<div style="font-size:12px;color:var(--ubp-text-3);">暂无可用角色（请先在大厅工作台创建自定义角色，或安装数据库本体），请确保神数据库已添加角色。</div>'}
        </div>
        <div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">
          <button data-ddz-invite="confirm" class="ubp-btn primary" style="padding:6px 20px;background:${chosen.length === 2 ? '#DC2626' : '#6b7280'};font-size:13px;border-radius:6px;">确认邀请，进入对局</button>
        </div>
      `;

      ov.querySelectorAll('[data-ddz-pick]').forEach(el => {
        el.addEventListener('click', () => {
          const name = el.dataset.ddzPick;
          const idx = chosen.findIndex(n => isNameMatch(n, name));
          if (idx !== -1) chosen.splice(idx, 1);
          else {
            if (chosen.length >= 2) chosen.shift();
            chosen.push(name);
          }
          renderContent();
        });
      });
      ov.querySelector('[data-ddz-invite="close"]')?.addEventListener('click', () => {
        ov.remove();
