      ov.querySelector('[data-ddz-invite="confirm"]')?.addEventListener('click', () => {
        if (chosen.length !== 2) { showToast('请先选择 2 位角色'); return; }
        const c = loadDDZConfig();
        c.partnerNames = chosen.slice(0, 2);
        saveDDZConfig(c);
        ov.remove();
        if (typeof onConfirmed === 'function') onConfirmed(chosen.slice(0, 2));
        else renderDDZLobby();
      });
    };

    renderContent();
    sheet.appendChild(ov);
  }

