  // ========== 斗地主：操作分发 ==========
  function handleDDZAction(act, target) {
    if (act === 'ddz-open') {
      if (hasSavedDDZGame()) resumeSavedDDZGame();
      else renderDDZLobby();
      return;
    }
    if (act === 'ddz-back-center') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      renderCardLobby();
      return;
    }
    if (act === 'ddz-invite') {
      renderDDZInviteOverlay((names) => startDDZGame(names));
      return;
    }
    if (act === 'ddz-settings') {
      renderDDZSettings();
      return;
    }
    if (act === 'ddz-bet-save') {
      const inp = sheet.querySelector('#ddz-bet-input');
      const v = Math.max(1, Math.round(Number(inp && inp.value) || 10));
      const c = loadDDZConfig(); c.bet = v; saveDDZConfig(c);
      renderDDZLobby();
      showToast('🪙 斗地主赌注已设为 ' + v);
      return;
    }
    if (act === 'ddz-start') {
      const cfg = loadDDZConfig();
      const betS = Math.max(1, Math.round(Number(cfg.bet) || 10));
      if (ensureStartChips('doudizhu', DDZ_START_CHIPS) < betS) {
        showToast('🪙 斗地主筹码不足赌注 ' + betS + '，请先用积分兑换筹码');
        renderChipExchange('doudizhu', () => renderDDZLobby());
        return;
      }
      if (aiChatInviteGate({
        chatOn: cfg.aiChat,
        invited: (cfg.partnerNames || []).filter(Boolean).length,
        label: '斗地主',
        onInvite: () => renderDDZInviteOverlay((names) => startDDZGame(names)),
        onDisableAndStart: () => { const c2 = loadDDZConfig(); c2.aiChat = false; saveDDZConfig(c2); handleDDZAction('ddz-start', null); }
      })) return;
      startDDZGame(cfg.partnerNames);
      return;
    }
    if (act === 'ddz-resume') {
      resumeSavedDDZGame();
      return;
    }
    if (act === 'ddz-discard') {
      clearSavedDDZGame();
      renderDDZLobby();
      showToast('🗑️ 已放弃进行中的对局');
      return;
    }
    if (act === 'ddz-exit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      const modal = sheet?.querySelector('.ddz-result-overlay');
      if (modal) modal.remove();
      if (ddzAiTimer) { clearTimeout(ddzAiTimer); ddzAiTimer = null; }
      if (ddzBidTimer) { clearTimeout(ddzBidTimer); ddzBidTimer = null; }
      ddzChatBusy = false; // 退出时复位，避免残留的 busy 标志导致下一局角色不说话
      if (ddzGame) ddzGame.isThinking = false;
      if (ddzGame && ddzGame.phase !== 'ended') saveDDZGameState();
      else clearSavedDDZGame();
      renderDDZLobby();
      return;
    }
    if (act === 'ddz-rematch') {
      const cfgR = loadDDZConfig();
      const betR = Math.max(1, Math.round(Number(cfgR.bet) || 10));
      if (ensureStartChips('doudizhu', DDZ_START_CHIPS) < betR) {
        showToast('🪙 斗地主筹码不足赌注 ' + betR + '，请先用积分兑换筹码');
        renderChipExchange('doudizhu', () => { if (ddzGame && ddzGame.phase === 'ended') renderDDZGameUI(); else renderDDZLobby(); });
        return;
      }
      if (aiChatInviteGate({
        chatOn: cfgR.aiChat,
        invited: (cfgR.partnerNames || []).filter(Boolean).length,
        label: '斗地主',
        onInvite: () => renderDDZLobby(),
        onDisableAndStart: () => { const c2 = loadDDZConfig(); c2.aiChat = false; saveDDZConfig(c2); handleDDZAction('ddz-rematch', null); }
      })) return;
      const modal = sheet?.querySelector('.ddz-result-overlay');
      if (modal) modal.remove();
      startDDZGame();
      return;
    }
    if (act === 'ddz-card') {
      const g = ddzGame;
      if (!g || g.phase !== 'playing' || g.turn !== 0) return;
      const id = parseInt(target.dataset.card || '-1');
      if (isNaN(id) || id < 0) return;
      const sel = Array.isArray(g.selected) ? g.selected.slice() : [];
      const idx = sel.indexOf(id);
      if (idx === -1) sel.push(id);
      else sel.splice(idx, 1);
      g.selected = sel;
      g.hintIndex = -1;
      renderDDZGameUI();
      return;
    }
    if (act === 'ddz-bid') {
      const g = ddzGame;
      if (!g || g.phase !== 'bidding' || g.bid.turnSeat !== 0) return;
      const score = parseInt(target.dataset.score || '0');
      const safe = (isNaN(score) || score < 0 || score > 3) ? 0 : score;
      if (safe > 0 && safe <= g.bid.highest) { showToast('必须叫比当前更高的分或不叫'); return; }
      ddzDoBid(0, safe);
      return;
    }
    if (act === 'ddz-play') {
      const g = ddzGame;
      if (!g || g.phase !== 'playing' || g.turn !== 0) return;
      if (!g.selected || !g.selected.length) { showToast('请先点击选择要出的牌'); return; }
      ddzDoPlay(0, g.selected.slice(), false);
      return;
    }
    if (act === 'ddz-pass') {
      const g = ddzGame;
      if (!g || g.phase !== 'playing' || g.turn !== 0) return;
      ddzDoPass(0, false);
      return;
    }
    if (act === 'ddz-hint') {
      const g = ddzGame;
      if (!g || g.phase !== 'playing' || g.turn !== 0) return;
      const lastInfo = (g.lastPlay && g.lastSeat !== 0) ? g.lastPlay.info : null;
      const list = ddzHintMoves(g.hands[0], lastInfo);
      if (!list.length) { showToast('没有能管上的牌，只能选择不出'); return; }
      if (typeof g.hintIndex !== 'number' || g.hintIndex < -1 || g.hintIndex >= list.length - 1) g.hintIndex = -1;
      g.hintIndex = (g.hintIndex + 1) % list.length;
      g.selected = list[g.hintIndex].cards.slice();
      renderDDZGameUI();
      return;
    }
    if (act === 'ddz-send-chat') {
      ddzHandleUserChatSend();
      return;
    }
  }

// ============================================================
  // ========== 欺诈酒馆 (吹牛 · 左轮 · 2~4人) 引擎与规则 ==========
  // ============================================================
  // __LIE_ENGINE_BEGIN__

  const LIE_SAVE_KEY = 'werewolf_extension_lie_saved_game';
  const LIE_CONFIG_KEY = 'werewolf_extension_lie_config';

  const LIE_COLORS = ['red', 'yellow', 'blue'];
  const LIE_COLOR_LABEL = { red: '红', yellow: '黄', blue: '蓝', star: '万能' };
  const LIE_COLOR_HEX = { red: '#EF4444', yellow: '#F59E0B', blue: '#3B82F6', star: '#A855F7' };
  const LIE_HP = 2;
  const LIE_MAX_BASIC = 5;
  const LIE_MAX_ITEM = 3;
  // 牌库构成：每个颜色 6 张 + 2 张万能牌（共 20 张）
  const LIE_PER_COLOR = 6;
  const LIE_STAR_COUNT = 2;
  const LIE_DECK_TOTAL = LIE_COLORS.length * LIE_PER_COLOR + LIE_STAR_COUNT;
  const LIE_DECK_TRUE = LIE_PER_COLOR + LIE_STAR_COUNT;

  const LIE_ITEMS = {
    peek: { name: '偷看', icon: '👁️', desc: '查看任意一名玩家随机 2 张手牌' },
    check: { name: '检查', icon: '🔍', desc: '查看枪里下一颗子弹是实弹还是空弹' },
    steal: { name: '偷牌', icon: '🎴', desc: '偷走别人手里 1 张道具牌' },
    eject: { name: '弹出', icon: '🗑️', desc: '把枪里当前这颗子弹直接丢掉（实弹/空弹随机）' },
    convert: { name: '转换', icon: '🔄', desc: '翻转当前子弹状态（实弹↔空弹，持续到下家回合结束）' },
    double: { name: '连发', icon: '🔥', desc: '下一次开枪时多打 1 发（一次两枪）' },
    damage: { name: '伤害加倍', icon: '☠️', desc: '下一次开枪命中实弹直接扣 2 血' },
    reverse: { name: '反转', icon: '🔃', desc: '反转出牌顺序' }
  };
  const LIE_ITEM_KEYS = ['peek', 'check', 'steal', 'eject', 'convert', 'double', 'damage', 'reverse'];

  function lieShuffle(arr, rng) {
    const rand = typeof rng === 'function' ? rng : Math.random;
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; }
    return a;
  }
  function lieRnd(n, rng) { return Math.floor((typeof rng === 'function' ? rng : Math.random)() * n); }
  function lieRndPick(arr, rng) { return arr && arr.length ? arr[lieRnd(arr.length, rng)] : null; }

  function lieMakeBasicDeck(rng) {
    const d = [];
    for (const col of LIE_COLORS) for (let i = 0; i < LIE_PER_COLOR; i++) d.push({ kind: 'basic', color: col });
    for (let i = 0; i < LIE_STAR_COUNT; i++) d.push({ kind: 'basic', color: 'star' });
    return lieShuffle(d, rng);
  }
  function lieMakeItemDeck(rng) {
    const d = [];
    for (const k of LIE_ITEM_KEYS) for (let i = 0; i < 3; i++) d.push({ kind: 'item', item: k });
    return lieShuffle(d, rng);
  }
  function lieDrawBasic(st) {
    if (!Array.isArray(st.basicDeck) || !st.basicDeck.length) return null;
    return st.basicDeck.pop();
  }
  function lieDrawItem(st) {
    if (!Array.isArray(st.itemDeck)) st.itemDeck = lieMakeItemDeck();
    if (!st.itemDeck.length) st.itemDeck = lieMakeItemDeck();
    return st.itemDeck.pop();
  }
  // 每回合重新发牌：基础牌从全新牌库发放（每色 6 张 + 2 万能），道具牌补充至上限
  // st._rng 存在时（强力档蒙特卡洛推演）用播种随机源，保证推演可复现；真实对局无 _rng → Math.random
  function lieDealRound(st) {
    st.basicDeck = lieMakeBasicDeck(st && st._rng);
    st.itemDeck = lieMakeItemDeck(st && st._rng);
    st.playedCount = 0;
    st.lastPlay = null;
    lieAlivePlayers(st).forEach(p => {
      p.escaped = false;
      p.basic = [];
      let guard = 0;
      while (p.basic.length < LIE_MAX_BASIC && st.basicDeck.length && guard++ < 24) {
        const c = lieDrawBasic(st);
        if (!c) break;
        p.basic.push(c);
      }
      guard = 0;
      p.items = p.items || [];
      while (p.items.length < LIE_MAX_ITEM && guard++ < 24) p.items.push(lieDrawItem(st));
    });
  }
  function lieIsTrueCard(card, color) { return !!card && (card.color === color || card.color === 'star'); }
  function lieBasicLabel(card) { return card && card.color ? LIE_COLOR_LABEL[card.color] : '?'; }

  // ========== 左轮手枪 ==========
  function lieNewGun(rng) {
    const chambers = [];
    for (let i = 0; i < 3; i++) chambers.push(true);
    for (let i = 0; i < 3; i++) chambers.push(false);
    return { chambers: lieShuffle(chambers, rng), ptr: 0, liveLeft: 3, blankLeft: 3, override: null, fired: 0 };
  }
  function liePeekBullet(st) {
    const g = st.gun;
    if (g.override && g.ptr < g.chambers.length) return !!g.override.live;
    if (g.ptr >= g.chambers.length) return false;
    return !!g.chambers[g.ptr];
  }
  // 依据弹巢实际剩余（含转换覆盖）重算实弹/空弹数量，避免转换导致计数漂移
  function lieGunSync(st) {
    const g = st.gun;
    if (!Array.isArray(g.chambers) || !g.chambers.length) { g.liveLeft = 0; g.blankLeft = 0; return g; }
    let live = 0, blank = 0;
    for (let i = g.ptr; i < g.chambers.length; i++) {
      const v = (i === g.ptr && g.override) ? !!g.override.live : !!g.chambers[i];
      if (v) live++; else blank++;
    }
    g.liveLeft = live;
    g.blankLeft = blank;
    return g;
  }
  // 消耗/发射当前这颗子弹；返回 { live, reloaded }
  function lieConsumeBullet(st) {
    const g = st.gun;
    const live = liePeekBullet(st);
    g.ptr++;
    g.fired = (g.fired || 0) + 1;
    if (g.override) g.override = null;
    lieGunSync(st);
    if (g.liveLeft <= 0 || g.ptr >= g.chambers.length) {
      st.gun = lieNewGun(st && st._rng);
      return { live: live, reloaded: true };
    }
    return { live: live, reloaded: false };
  }

  // ========== 配置 ==========
  function loadLieConfig() {
    try {
      const raw = localStorage.getItem(LIE_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (typeof p.aiChat !== 'boolean') p.aiChat = true;
        if (!p.speechInterval) p.speechInterval = 4;
        if (!Array.isArray(p.partnerNames)) p.partnerNames = [];
        if (!p.aiLevel) p.aiLevel = 'normal';
        return p;
      }
    } catch (e) { /* ignore */ }
    return { aiChat: true, speechInterval: 4, partnerNames: [], aiLevel: 'normal' };
  }
  function saveLieConfig(cfg) {
    try { localStorage.setItem(LIE_CONFIG_KEY, JSON.stringify(cfg)); } catch (e) { /* ignore */ }
  }

  // ========== 对局状态 ==========
  function lieMakePlayer(seat, name, isUser, avatar, identity) {
    return {
      seat: seat, name: name, isUser: !!isUser, avatar: avatar || '', identity: identity || '牌友',
      hp: LIE_HP, alive: true, escaped: false, basic: [], items: [],
      effects: { doubleShot: false, doubleDamage: false },
      memo: { peek: {}, peekSeq: -1, bullet: null, bulletSeq: -1 },
      pub: { plays: 0, caught: 0, truthful: 0, challenges: 0, wins: 0, items: 0 },
      history: [],
      aiItemsThisTurn: 0
    };
  }

  function lieBuildPlayers(names) {
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    const players = [lieMakePlayer(0, '我', true, getMainCharAvatar(), '主角')];
    const want = Array.isArray(names) ? names.filter(Boolean).slice(0, 3) : [];
    const used = [];
    const count = Math.max(1, Math.min(3, want.length || 1));
    for (let i = 0; i < count; i++) {
      let c = null;
      const nm = want[i];
      if (nm) c = contacts.find(x => isNameMatch(x.name, nm)) || null;
      if (!c) c = contacts.find(x => !used.some(n => isNameMatch(n, x.name))) || null;
      if (c) {
        used.push(c.name);
        players.push(lieMakePlayer(i + 1, c.name, false, c.avatar || getCharacterAvatarByName(c.name) || '', c.identity || '牌友'));
      } else {
        players.push(lieMakePlayer(i + 1, '牌友' + (i + 1), false, '', '牌友'));
      }
    }
    return players;
  }

  function lieBuildGame(names) {
    const cfg = loadLieConfig();
    const players = lieBuildPlayers(names);
    const st = {
      createdAt: Date.now(),
      players: players,
      dir: 1,
      turnSeat: 0,
      turnSeq: 0,
      round: 0,
      targetColor: lieRndPick(LIE_COLORS),
      gun: lieNewGun(),
      basicDeck: [],
      itemDeck: lieMakeItemDeck(),
      playedCount: 0,
      lastPlay: null,
      phase: 'playing',
      winnerSeat: null,
      log: [],
      speeches: [],
      selected: [],
      itemMode: null,
      reveal: null,
      isThinking: false,
      actionCount: 0,
      turnsSinceChallenge: 0,
      aiChat: cfg.aiChat !== false,
      speechInterval: cfg.speechInterval || 4,
      aiLevel: cfg.aiLevel || 'normal',
      lastSpeechAt: 0,
      resultRecorded: false
    };
    // 首回合：随机目标颜色 + 每人 5 张基础牌（每色 6 张 + 2 万能）+ 3 张道具
    st.turnSeat = lieRnd(st.players.length);
    lieStartRound(st, st.turnSeat, true);
    return st;
  }

  // ========== 日志 ==========
  function lieLog(st, text, color, opts) {
    opts = opts || {};
    st.log.push({
      text: text,
      color: color || '',
      seat: (opts.seat === undefined ? null : opts.seat),
      secret: !!opts.secret,
      revealTo: (opts.revealTo === undefined ? null : opts.revealTo),
      kind: opts.kind || 'info',
      turnSeq: st.turnSeq
    });
    if (st.log.length > 240) st.log = st.log.slice(-240);
  }

  // ========== 回合与转向 ==========
  function lieAlivePlayers(st) { return st.players.filter(p => p && p.alive); }
  // 本回合仍在行动流程中的玩家（未逃离）
  function lieActivePlayers(st) { return st.players.filter(p => p && p.alive && !p.escaped); }
  function lieNextSeat(st, from) {
    const n = st.players.length;
    let s = from;
    for (let i = 0; i < n * 4 + 6; i++) {
      s = (s + (st.dir || 1) + n) % n;
      if (st.players[s] && st.players[s].alive && !st.players[s].escaped) return s;
    }
    return from;
  }
  // 规则：只剩 2 名未逃离玩家，且上家已出完所有手牌 → 下家只能质疑
  function lieMustChallenge(st, seat) {
    const lp = st.lastPlay;
    if (!lp || st.phase !== 'playing') return false;
    if (lp.seat === seat) return false;
    const prev = st.players[lp.seat];
    if (!prev || !prev.alive) return false;
    if ((prev.basic || []).length > 0) return false;
    return lieActivePlayers(st).length <= 2;
  }
  function lieStartTurn(st, seat) {
    const p = st.players[seat];
    st.turnSeat = seat;
    st.turnSeq++;
    st.selected = [];
    st.itemMode = null;
    st.reveal = null;
    if (!p || !p.alive) return;
    p.aiItemsThisTurn = 0;
    p.effects = p.effects || { doubleShot: false, doubleDamage: false };
    st.turnsSinceChallenge = (st.turnsSinceChallenge || 0) + 1;
    // 目标颜色在一整个回合内保持不变（开枪结算后才刷新）
    // 转换效果：持续到下家回合结束
    if (st.gun.override && st.turnSeq >= (st.gun.override.expireSeq || 0)) {
      st.gun.override = null;
      lieGunSync(st); // 必须重算实弹/空弹计数，否则界面与 AI 概率会停留在被翻转的旧值
    }
    st.round = st.round || 1;
  }
  // 开新回合：重新定目标颜色 + 重新发牌，由 firstSeat 开始出牌
  function lieStartRound(st, firstSeat, quiet) {
    st.round = (st.round || 0) + 1;
    st.targetColor = lieRndPick(LIE_COLORS, st._rng);
    lieDealRound(st);
    if (!quiet) lieLog(st, '🎯 第 ' + st.round + ' 回合开始 · 目标颜色【' + LIE_COLOR_LABEL[st.targetColor] + '】· 重新发牌（每色 ' + LIE_PER_COLOR + ' 张 + ' + LIE_STAR_COUNT + ' 张万能）', LIE_COLOR_HEX[st.targetColor], { kind: 'end' });
    let seat = (typeof firstSeat === 'number' && st.players[firstSeat] && st.players[firstSeat].alive) ? firstSeat : lieRnd(st.players.length, st._rng);
    const sp = st.players[seat];
    if (!sp || !sp.alive || sp.escaped) seat = lieNextSeat(st, seat);
    lieStartTurn(st, seat);
  }
  function lieAdvanceTurn(st, afterSeat) {
    const alive = lieAlivePlayers(st);
    if (alive.length <= 1) { lieEndGame(st, alive.length ? alive[0].seat : null); return; }
    if (!lieActivePlayers(st).length) { lieStartRound(st, lieNextSeat(st, afterSeat)); return; }
    lieStartTurn(st, lieNextSeat(st, afterSeat));
  }

  // ========== 出牌 ==========
  function lieDoPlay(st, seat, idxs) {
    const p = st.players[seat];
    if (!p || !p.alive || st.turnSeat !== seat || st.phase !== 'playing') return false;
    const uniq = [...new Set((idxs || []).filter(i => typeof i === 'number' && i >= 0 && i < p.basic.length))];
    if (uniq.length < 1) return false;
    const cards = uniq.map(i => p.basic[i]);
    if (cards.some(c => !c || c.kind !== 'basic')) return false;
    const rm = new Set(uniq);
    p.basic = p.basic.filter((c, i) => !rm.has(i));
    const claim = st.targetColor;
    const colors = cards.map(c => c.color);
    const lied = colors.some(c => c !== claim && c !== 'star');
    st.lastPlay = { seat: seat, cards: colors, claimColor: claim, count: colors.length, turnSeq: st.turnSeq, revealed: false, lied: null };
    p.pub.plays++;
    p.history.push({ type: 'play', count: colors.length, claimColor: claim, turnSeq: st.turnSeq, colors: colors, challenged: false, lied: null });
    st.actionCount++;
    st.playedCount = (st.playedCount || 0) + colors.length;
    const emptied = p.basic.length === 0;
    if (emptied) p.escaped = true;
    lieLog(st, p.name + ' 宣称打出 ' + colors.length + ' 张【' + LIE_COLOR_LABEL[claim] + '】' + (emptied ? '（已出完手牌 · 逃离本回合）' : ''), '#FFFFFF', { seat: seat, kind: 'play' });
    lieAdvanceTurn(st, seat);
    return true;
  }

  // ========== 质疑上家 ==========
  function lieCanChallenge(st, seat) {
    const lp = st.lastPlay;
    if (!lp || st.phase !== 'playing') return false;
    if (lp.seat === seat) return false;
    const prev = st.players[lp.seat];
    return !!(prev && prev.alive);
  }
  function lieDoChallenge(st, seat) {
    const p = st.players[seat];
    if (!p || !p.alive || st.turnSeat !== seat || st.phase !== 'playing') return false;
    if (!lieCanChallenge(st, seat)) return false;
    const lp = st.lastPlay;
    const prev = st.players[lp.seat];
    const lied = lp.cards.some(c => c !== lp.claimColor && c !== 'star');
    lp.revealed = true;
    lp.lied = lied;
    const h = prev.history.slice().reverse().find(x => x.type === 'play' && x.turnSeq === lp.turnSeq);
    if (h) { h.challenged = true; h.lied = lied; }
    p.pub.challenges++;
    if (lied) prev.pub.caught++; else prev.pub.truthful++;
    if (lied) p.pub.wins++;
    st.actionCount++;
    st.turnsSinceChallenge = 0;
    lieLog(st, p.name + ' 质疑 ' + prev.name + '！翻开牌：' + lp.cards.map(c => LIE_COLOR_LABEL[c]).join(' ') + '（目标色 ' + LIE_COLOR_LABEL[lp.claimColor] + '）→ ' + (lied ? prev.name + ' 说谎了' : prev.name + ' 没说谎'), lied ? '#10B981' : '#EF4444', { seat: seat, kind: 'challenge' });
    st.lastPlay = null;
    // 说谎 → 上家挨枪；没说谎 → 质疑者挨枪（开枪者为胜方）
    const shooter = lied ? p : prev;
    const victim = lied ? prev : p;
    const revealInfo = { seat: lp.seat, colors: lp.cards.slice(), claimColor: lp.claimColor, lied: lied, challenger: seat };
    lieResolveShot(st, shooter, victim, lied);
    // 开枪之后（无论空弹还是中弹，只要没死）：重定新回合目标颜色 + 重新发牌，
    // 并由「被质疑玩家的下一家」开始新一轮出牌
    if (st.phase === 'playing') lieStartRound(st, lieNextSeat(st, lp.seat));
    st.reveal = revealInfo; // 结算后再写入，避免被下一回合开始清空
    return true;
  }

  // ========== 开枪结算 ==========
  function lieResolveShot(st, shooter, victim, lied) {
    const shooterP = st.players[shooter.seat];
    const shots = (shooterP && shooterP.effects && shooterP.effects.doubleShot) ? 2 : 1;
    const dmg = (shooterP && shooterP.effects && shooterP.effects.doubleDamage) ? 2 : 1;
    if (shooterP && shooterP.effects) { shooterP.effects.doubleShot = false; shooterP.effects.doubleDamage = false; }
    if (shots > 1) lieLog(st, '🔥 ' + shooterP.name + ' 发动【连发】：本次连开两枪！', '#F59E0B', { kind: 'gun' });
    if (dmg > 1) lieLog(st, '☠️ ' + shooterP.name + ' 发动【伤害加倍】：命中实弹扣 2 血！', '#EF4444', { kind: 'gun' });
    let died = false;
    for (let i = 0; i < shots; i++) {
      if (!victim.alive) break;
      const res = lieConsumeBullet(st);
      if (res.live) {
        victim.hp -= dmg;
        lieLog(st, ' 实弹！' + victim.name + ' 扣 ' + dmg + ' 点血（剩余 ' + Math.max(0, victim.hp) + ' 点）', '#EF4444', { kind: 'gun' });
        if (victim.hp <= 0) {
          victim.hp = 0; victim.alive = false; died = true;
          lieLog(st, '☠️ ' + victim.name + ' 生命归零，出局！', '#EF4444', { kind: 'gun' });
          break;
        }
      } else {
        lieLog(st, '✨ 空弹，' + victim.name + ' 逃过一劫', '#10B981', { kind: 'gun' });
      }
      if (res.reloaded) lieLog(st, '🔫 枪内实弹打光，自动换上全新弹夹（3 实弹 / 3 空弹）', '#F59E0B', { kind: 'gun' });
    }
    const alive = lieAlivePlayers(st);
    if (alive.length <= 1) { lieEndGame(st, alive.length ? alive[0].seat : null); return; }
    // 开枪后的回合推进由 lieDoChallenge 负责（新回合从被质疑玩家的下一家开始）
  }

  // ========== 道具牌 ==========
  function lieUseItem(st, seat, itemIdx, targetSeat) {
    const p = st.players[seat];
    if (!p || !p.alive || st.phase !== 'playing') return { ok: false, msg: '现在不能使用道具' };
    if (st.turnSeat !== seat) return { ok: false, msg: '只能在自己回合使用道具' };
    const it = p.items[itemIdx];
    if (!it || it.kind !== 'item') return { ok: false, msg: '道具不存在' };
    const key = it.item;
    const def = LIE_ITEMS[key];
    if (!def) return { ok: false, msg: '道具无效' };
    const t = (typeof targetSeat === 'number') ? st.players[targetSeat] : null;
    const needTarget = (key === 'peek' || key === 'steal');
    if (needTarget && (!t || !t.alive || t.seat === p.seat)) return { ok: false, msg: '请选择一名其他玩家' };
    const consume = () => { p.items.splice(itemIdx, 1); p.pub.items++; };

    if (key === 'peek') {
      const n = Math.min(2, t.basic.length);
      const order = lieShuffle(t.basic.map((c, i) => i)).slice(0, n);
      const colors = order.map(i => t.basic[i].color);
      p.memo.peek[t.seat] = colors;
      p.memo.peekSeq = st.turnSeq;
      consume();
      lieLog(st, p.name + ' 使用了【偷看】，查看了 ' + t.name + ' 的 ' + colors.length + ' 张牌', '', { seat: seat, kind: 'item', secret: true, revealTo: seat });
      if (p.isUser) {
        st.reveal = { type: 'peek', target: t.name, colors: colors };
        lieLog(st, '👁️ 偷看结果：' + t.name + ' 手里有 ' + colors.map(c => LIE_COLOR_LABEL[c]).join('、'), '#A855F7', { secret: true, revealTo: 0, kind: 'item' });
      }
      return { ok: true, key: key, colors: colors };
    }
    if (key === 'check') {
      const live = liePeekBullet(st);
      p.memo.bullet = live;
      p.memo.bulletSeq = st.turnSeq;
      consume();
      lieLog(st, p.name + ' 使用了【检查】，看了枪里的下一颗子弹', '', { seat: seat, kind: 'item', secret: true, revealTo: seat });
      if (p.isUser) lieLog(st, '🔍 检查结果：下一颗是【' + (live ? '实弹' : '空弹') + '】', live ? '#EF4444' : '#10B981', { secret: true, revealTo: 0, kind: 'item' });
      return { ok: true, key: key, live: live };
    }
    if (key === 'steal') {
      if (!t.items || !t.items.length) return { ok: false, msg: t.name + ' 没有道具牌可偷' };
      const ti = lieRnd(t.items.length);
      const got = t.items.splice(ti, 1)[0];
      p.items.push(got);
      consume();
      lieLog(st, p.name + ' 使用了【偷牌】，偷走了 ' + t.name + ' 的一张道具牌', '', { seat: seat, kind: 'item' });
      if (p.isUser) lieLog(st, '🫳 偷到的道具：【' + (LIE_ITEMS[got.item] ? LIE_ITEMS[got.item].name : got.item) + '】', '#F59E0B', { secret: true, revealTo: 0, kind: 'item' });
      return { ok: true, key: key, item: got.item };
    }
    if (key === 'eject') {
      const res = lieConsumeBullet(st);
      consume();
      lieLog(st, p.name + ' 使用了【弹出】，丢掉了枪里当前这颗子弹（' + (res.live ? '实弹' : '空弹') + '）', '#F59E0B', { seat: seat, kind: 'item' });
      if (res.reloaded) lieLog(st, '🔫 枪内实弹打光，自动换上全新弹夹', '#F59E0B', { kind: 'gun' });
      return { ok: true, key: key, live: res.live };
    }
    if (key === 'convert') {
      const cur = liePeekBullet(st);
      st.gun.override = { live: !cur, bySeat: seat, expireSeq: st.turnSeq + 2 };
      lieGunSync(st);
      consume();
      lieLog(st, p.name + ' 使用了【转换】，把当前子弹翻转成了【' + (!cur ? '实弹' : '空弹') + '】（持续到下家回合结束）', '#8B5CF6', { seat: seat, kind: 'item', secret: true, revealTo: seat });
      if (p.isUser) lieLog(st, '🔄 转换后下一颗子弹为【' + (!cur ? '实弹' : '空弹') + '】', '#8B5CF6', { secret: true, revealTo: 0, kind: 'item' });
      return { ok: true, key: key, live: !cur };
    }
    if (key === 'double' || key === 'damage') {
      p.effects = p.effects || {};
      if (key === 'double') p.effects.doubleShot = true; else p.effects.doubleDamage = true;
      consume();
      lieLog(st, p.name + ' 使用了【' + def.name + '】，下一次开枪生效', '#F59E0B', { seat: seat, kind: 'item' });
      return { ok: true, key: key };
    }
    if (key === 'reverse') {
      st.dir = (st.dir || 1) * -1;
      consume();
      lieLog(st, p.name + ' 使用了【反转】，出牌顺序反转！', '#8B5CF6', { seat: seat, kind: 'item' });
      return { ok: true, key: key, dir: st.dir };
    }
    return { ok: false, msg: '未知道具' };
  }

  // ========== 结算 ==========
  function lieEndGame(st, winnerSeat) {
    st.phase = 'ended';
    st.winnerSeat = (winnerSeat === undefined ? null : winnerSeat);
    const w = (st.winnerSeat !== null && st.players[st.winnerSeat]) ? st.players[st.winnerSeat] : null;
    lieLog(st, w ? ('🏆 ' + w.name + ' 成为最后的幸存者，获得胜利！') : '🏆 本局结束', '#10B981', { kind: 'end' });
  }
  // ========== 欺诈酒馆 AI：状态记忆 + 概率阈值 + 道具逻辑 + 蒙特卡洛 ==========
  // AI 只使用「合法可见信息」：自己的手牌/道具、公开的血量/手牌数/出牌记录/道具使用、以及自己道具获得的私有情报。

  function lieAiAliveOpps(st, p) { return st.players.filter(x => x && x.alive && x.seat !== p.seat); }

  // 公开的“被抓说谎率”
  function liePublicLieRate(p) {
    if (!p || !p.pub || !p.pub.plays) return 0;
    return Math.max(0, Math.min(1, p.pub.caught / p.pub.plays));
  }
  // 对手的质疑倾向（0~1）：越高说明越爱质疑，AI 就越少吹牛
  function lieOppChallengeRate(st, p) {
    const opps = lieAiAliveOpps(st, p);
    let turns = 0, ch = 0;
    opps.forEach(o => { turns += Math.max(1, (o.pub && o.pub.plays) || 0); ch += (o.pub && o.pub.challenges) || 0; });
    if (!turns) return 0.3;
    return Math.max(0, Math.min(1, ch / turns));
  }
  // 目标色牌占比（含万能）：与牌库构成一致（每色 6 张 + 2 万能 = 8/20）
  const LIE_TRUE_CARD_P = LIE_DECK_TRUE / LIE_DECK_TOTAL;

  // 结合自己的手牌与场上已出牌数，推算未知牌中「可当目标色」的真实比例（AI 记牌）
  function lieAiTrueRate(st, p) {
    const myHand = (p.basic || []);
    let myTrue = 0;
    myHand.forEach(c => { if (lieIsTrueCard(c, st.targetColor)) myTrue++; });
    const unknown = Math.max(1, LIE_DECK_TOTAL - myHand.length - (st.playedCount || 0));
    const trueLeft = Math.max(0, LIE_DECK_TRUE - myTrue);
    return Math.max(0.05, Math.min(0.95, trueLeft / unknown));
  }
  // 一手 count 张牌里「至少藏了一张假牌」的概率（超几何近似）
  function lieAiLieChanceFromCards(st, p, count) {
    const myHand = (p.basic || []);
    let myTrue = 0;
    myHand.forEach(c => { if (lieIsTrueCard(c, st.targetColor)) myTrue++; });
    const unknown = Math.max(1, LIE_DECK_TOTAL - myHand.length - (st.playedCount || 0));
    const trueLeft = Math.max(0, LIE_DECK_TRUE - myTrue);
    let pAllTrue = 1;
    for (let i = 0; i < count; i++) pAllTrue *= Math.max(0, trueLeft - i) / Math.max(1, unknown - i);
    return Math.max(0, Math.min(1, 1 - pAllTrue));
  }

  // A. 估算上家说谎概率（0~1）
  function lieAiEstimateLie(st, p, lp) {
    if (!lp) return 0;
    const threat = st.players[lp.seat];
    if (!threat) return 0.4;
    // 记牌：按未知牌池推算出牌为假的概率
    let prob = lieAiLieChanceFromCards(st, p, lp.count);
    // 行为修正：公开说谎率高的更可能掺假，老实的可能真有牌
    prob = prob * 0.78 + liePublicLieRate(threat) * 0.22;
    const handNow = (threat.basic && threat.basic.length) || 0;
    const handBefore = handNow + lp.count;
    if (handBefore === lp.count && lp.count >= 2) prob += 0.06; // 最后一手梭哈，赌徒倾向
    if (lp.count >= 3) prob += 0.04;
    // 私有情报：偷看
    const peek = p.memo && p.memo.peek ? p.memo.peek[lp.seat] : null;
    if (peek && p.memo.peekSeq >= st.turnSeq - 1) {
      const knownTrue = peek.filter(c => c === lp.claimColor || c === 'star').length;
      if (lp.count >= 3 && knownTrue === 0 && peek.length >= 2) prob += 0.24;
      else if (knownTrue >= lp.count) prob -= 0.20;
      else if (knownTrue === 0 && peek.length >= 2) prob += 0.10;
    }
    // 上家血量很低 → 更可能博一把吹牛
    if (threat.hp <= 1) prob += 0.03;
    // 长时间没人质疑 → 越拖越可疑（同时保证对局能收束）
    prob += Math.min(0.30, (st.turnsSinceChallenge || 0) * 0.03);
    return Math.max(0.02, Math.min(0.97, prob));
  }

  // B. 估算下一颗子弹是实弹的概率
  function lieAiBulletRisk(st, p) {
    const g = st.gun;
    // 只有"自己释放的转换"才允许知道结果。别人释放【转换】后，子弹真实结果对 AI 属于未知信息，
    // 旧代码在这里直接读 g.override.live（真实值）= 开天眼，AI 会拿"必中实弹"去做决策。
    if (g.override) {
      if (g.override.bySeat === p.seat) return g.override.live ? 1 : 0;
      const live = g.liveLeft, blank = g.blankLeft;
      return (live + blank > 0) ? live / (live + blank) : 0.5;
    }
    if (p.memo && typeof p.memo.bullet === 'boolean' && p.memo.bulletSeq >= st.turnSeq - 1) {
      return p.memo.bullet ? 1 : 0; // 自己用【检查】看过的结果（超过 1 回合未刷新则视为过期）
    }
    const live = g.liveLeft, blank = g.blankLeft;
    if (live + blank <= 0) return 0.5;
    return live / (live + blank);
  }
  function lieAiBulletKnown(st, p) {
    const g = st.gun;
    if (g && g.override && g.override.bySeat !== p.seat) return false; // 别人的转换 = 未知
    return !!(p.memo && typeof p.memo.bullet === 'boolean' && p.memo.bulletSeq >= st.turnSeq - 1);
  }

  // A. 是否质疑上家
  function lieAiChallengeDecision(st, p, level) {
    const lvl = difficultyLevel(level);
    const D = getDifficulty('lie', lvl);
    const lp = st.lastPlay;
    const prob = lieAiEstimateLie(st, p, lp);
    const risk = lieAiBulletRisk(st, p);
    const threat = lp ? st.players[lp.seat] : null;
    const selfLow = p.hp <= 1;
    const threatLow = !!(threat && threat.hp <= 1);
    if (lieMustChallenge(st, p.seat)) return { challenge: true, prob: prob, risk: risk, forced: true };
    let d = false;
    if (prob > 0.85) d = true;
    else if (prob > 0.70 && risk < 0.45) d = true;
    else if (prob > 0.62 && risk === 0) d = true;
    else if (prob > 0.60 && risk <= 0.2) d = true;
    if (threatLow && prob > 0.55 && !selfLow) d = true;      // 上家残血，抓到直接淘汰
    if (selfLow) d = (prob > 0.90 && risk < 0.35);           // 自己 1 血：极度保守
    if (risk === 1 && !threatLow) d = prob > 0.88;           // 下一颗必是实弹
    // 上家已出完手牌逃离：只要还在场上，猜错照样他挨枪，值得抓
    if (threat && (threat.basic || []).length === 0 && prob > 0.55 && !selfLow) d = true;
    // 失误率分档（原来 fast 参数在实战里恒为 false，导致强力档也带 7% 随机反悔）
    if (Math.random() < D.blunder) d = !d;
    return { challenge: d, prob: prob, risk: risk };
  }

  // B. 出牌候选
  function lieAiPlayCandidates(st, p) {
    const target = st.targetColor;
    const hand = p.basic || [];
    const trues = [], fakes = [];
    hand.forEach((c, i) => { if (lieIsTrueCard(c, target)) trues.push(i); else fakes.push(i); });
    const out = [];
    if (trues.length) out.push({ idxs: trues.slice(0, 1), tag: 'true1' });
    if (trues.length >= 2) out.push({ idxs: trues.slice(0, 2), tag: 'true2' });
    if (trues.length >= 3) out.push({ idxs: trues.slice(0, 3), tag: 'true3' });
    if (trues.length && fakes.length) out.push({ idxs: [trues[0], fakes[0]], tag: 'mix2' });
    if (trues.length >= 2 && fakes.length) out.push({ idxs: [trues[0], trues[1], fakes[0]], tag: 'mix3' });
    if (trues.length >= 1 && fakes.length >= 2) out.push({ idxs: [trues[0], fakes[0], fakes[1]], tag: 'mix3b' });
    if (fakes.length) out.push({ idxs: [fakes[0]], tag: 'bluff1' });
    if (fakes.length >= 2) out.push({ idxs: fakes.slice(0, 2), tag: 'bluff2' });
    if (fakes.length >= 3) out.push({ idxs: fakes.slice(0, 3), tag: 'bluff3' });
    // 倾囊而出（一次出完所有手牌 → 本回合逃离）
    if (hand.length >= 2) out.push({ idxs: hand.map((c, i) => i), tag: 'allin' });
    // 大额混牌（4~6 张，吹牛施压）
    if (hand.length >= 4 && trues.length >= 1) {
      const mix = [trues[0]];
      for (let i = 0; i < fakes.length && mix.length < 4; i++) mix.push(fakes[i]);
      if (mix.length >= 4) out.push({ idxs: mix, tag: 'mix4' });
    }
    if (!out.length) out.push({ idxs: [0], tag: 'any' });
    return out;
  }

  // 出牌启发式评分（越高越好）
  function lieHeurScoreCandidate(st, p, cd, opts) {
    opts = opts || {};
    const noiseMul = opts.noise ? (opts.noise === true ? 1 : Number(opts.noise) || 0) : 0; // 噪声幅度受难度中枢 D.noise 控制
    if (cd.type === 'challenge') {
      const lp = st.lastPlay;
      const prob = lieAiEstimateLie(st, p, lp);
      const risk = lieAiBulletRisk(st, p);
      let s = prob * 100 - risk * 58;
      const threat = lp ? st.players[lp.seat] : null;
      if (threat && threat.hp <= 1 && prob > 0.5) s += 42;
      if (p.hp <= 1) s -= 65;
      if (noiseMul) s += (Math.random() - 0.5) * 14 * noiseMul;
      return s;
    }
    const idxs = cd.idxs || [];
    const cards = idxs.map(i => (p.basic || [])[i]).filter(Boolean);
    if (!cards.length) return -9999;
    const trues = cards.filter(c => lieIsTrueCard(c, st.targetColor)).length;
    const fakes = cards.length - trues;
    const oppCh = lieOppChallengeRate(st, p);
    const appetite = Math.max(0, Math.min(0.85, 0.5 - 0.34 * oppCh)) * (p.hp <= 1 ? 0.35 : 1);
    let s = trues * 21 - fakes * (12 + 55 * oppCh) + cards.length * 3;
    s -= trues * 5;                                  // 留一点真牌，别一次交光
    if (fakes > 0) s += appetite * 26;               // 混合策略：爱吹牛的倾向
    if (p.hp <= 1) s -= fakes * 22;                  // 残血保守
    // 出完手牌 = 本回合逃离，别人无法再让你挨枪
    const handSize = (p.basic || []).length;
    const empties = handSize > 0 && idxs.length >= handSize;
    if (empties) {
      s += 24;
      const active = lieActivePlayers(st).length;
      if (fakes === 0) s += (active <= 2 ? 30 : 10);          // 真牌逃离：质疑者必挨枪
      // 假牌逃离：惩罚与"对手质疑倾向"强绑定（对手越爱抓，越不敢一次吹完）
      else s -= (12 + 45 * oppCh + (active <= 2 ? 16 : 0)) + 45 * oppCh * oppCh;
    }
    // 快速档的新手特征：不敢大额吹牛（一次 4 张以上且掺假时额外重罚）
    if (opts.fast && fakes > 0 && cards.length >= 4) s -= 26;
    if (noiseMul) s += (Math.random() - 0.5) * 16 * noiseMul;
    return s;
  }

  // 快路径出牌（供蒙特卡洛推演使用，无噪声）
  function lieAiChoosePlay(st, p, fast, noNoise) {
    const cands = lieAiPlayCandidates(st, p);
    let best = cands[0], bs = -1e9;
    for (const c of cands) {
      const s = lieHeurScoreCandidate(st, p, { type: 'play', idxs: c.idxs }, { noise: !(fast || noNoise), fast: !!fast });
      if (s > bs) { bs = s; best = c; }
    }
    return best.idxs;
  }

  // C. 道具使用决策（返回 { idx, key, target } 或 null）
  function lieAiPickItemAction(st, p, pre, level, rng) {
    const lvl = difficultyLevel(level);
    const D = getDifficulty('lie', lvl);
    const rand = typeof rng === 'function' ? rng : Math.random; // 强力档传播种随机源，保证道具决策可复现
    const pickIdx = (arr) => (arr && arr.length ? arr[Math.floor(rand() * arr.length)] : null);
    // 道具使用积极性分档：快速档出手少（新手不会用道具），强力档更积极
    const itemGate = lvl === 'fast' ? 0.55 : (lvl === 'strong' ? 1.25 : 1.0);
    const items = (p.items || []).map((it, i) => ({ key: it.item, idx: i })).filter(x => LIE_ITEMS[x.key]);
    if (!items.length) return null;
    if (rand() > itemGate) return null;
    const find = k => items.find(x => x.key === k);
    const risk = lieAiBulletRisk(st, p);
    const known = lieAiBulletKnown(st, p);
    const threat = st.lastPlay ? st.players[st.lastPlay.seat] : null;
    const oppLow = st.players.some(x => x.alive && x.seat !== p.seat && x.hp <= 1);
    const riskySelf = p.hp <= 1 && risk >= 0.99;
    // 1) 保命：下一颗必是实弹且自己残血 → 弹出/转换
    if (riskySelf) {
      const e = find('eject') || find('convert');
      if (e) return { idx: e.idx, key: e.key };
    }
    // 2) 斩杀：打算质疑 + 对手残血 + 下一颗实弹 → 伤害加倍 / 连发
    if (pre && pre.challenge && oppLow && risk >= 0.99) {
      const d = find('damage'); if (d) return { idx: d.idx, key: 'damage' };
      const dbl = find('double'); if (dbl) return { idx: dbl.idx, key: 'double' };
    }
    // 3) 质疑前先检查子弹
    if (pre && pre.prob > 0.45 && !known) {
      const c = find('check'); if (c) return { idx: c.idx, key: 'check' };
    }
    // 4) 想质疑时先偷看上家
    if (pre && pre.prob > 0.4 && threat && threat.alive) {
      const peekedFresh = p.memo && p.memo.peek && p.memo.peek[threat.seat] !== undefined && p.memo.peekSeq >= st.turnSeq - 1;
      if (!peekedFresh) { const pk = find('peek'); if (pk) return { idx: pk.idx, key: 'peek', target: threat.seat }; }
    }
    // 5) 偷牌：偷有道具的对手（优先血少的）
    const steal = find('steal');
    if (steal) {
      const targets = lieAiAliveOpps(st, p).filter(x => x.items && x.items.length);
      if (targets.length && rand() < 0.35) {
        targets.sort((a, b) => a.hp - b.hp);
        return { idx: steal.idx, key: 'steal', target: targets[0].seat };
      }
    }
    // 6) 转换：自己危险时把实弹转空弹
    if (!riskySelf && p.hp <= 1 && risk >= 0.5 && risk < 0.99) {
      const cv = find('convert');
      if (cv && rand() < 0.5) return { idx: cv.idx, key: 'convert' };
    }
    // 7) 劣势反转顺序
    const rv = find('reverse');
    if (rv && rand() < 0.10) return { idx: rv.idx, key: 'reverse' };
    // 8) 真人不会一直囤道具：小概率随手用掉
    if (rand() < 0.06) {
      const r = pickIdx(items);
      if (r && r.key !== 'steal') return { idx: r.idx, key: r.key };
    }
    return null;
  }

  // ========== 蒙特卡洛（版本2）：确定化 + 启发式推演 ==========
  function lieCloneState(st) {
    return {
      players: st.players.map(p => ({
        seat: p.seat, name: p.name, isUser: false, avatar: '', identity: p.identity,
        hp: p.hp, alive: p.alive, escaped: !!p.escaped,
        basic: (p.basic || []).map(c => ({ kind: 'basic', color: c.color })),
        items: (p.items || []).map(c => ({ kind: 'item', item: c.item })),
        effects: { doubleShot: !!(p.effects && p.effects.doubleShot), doubleDamage: !!(p.effects && p.effects.doubleDamage) },
        memo: {
          peek: Object.assign({}, (p.memo && p.memo.peek) || {}),
          peekSeq: (p.memo && p.memo.peekSeq) || -1,
          bullet: (p.memo && typeof p.memo.bullet === 'boolean') ? p.memo.bullet : null,
          bulletSeq: (p.memo && p.memo.bulletSeq) || -1
        },
        pub: { plays: p.pub.plays, caught: p.pub.caught, truthful: p.pub.truthful, challenges: p.pub.challenges, wins: p.pub.wins, items: p.pub.items },
        history: (p.history || []).map(h => Object.assign({}, h)),
        aiItemsThisTurn: 0
      })),
      dir: st.dir, turnSeat: st.turnSeat, turnSeq: st.turnSeq, round: st.round, targetColor: st.targetColor, turnsSinceChallenge: st.turnsSinceChallenge || 0,
      gun: { chambers: [], ptr: 0, liveLeft: st.gun.liveLeft, blankLeft: st.gun.blankLeft, override: st.gun.override ? Object.assign({}, st.gun.override) : null, fired: st.gun.fired || 0 },
      basicDeck: [], itemDeck: lieMakeItemDeck(), playedCount: st.playedCount || 0,
      lastPlay: st.lastPlay ? { seat: st.lastPlay.seat, cards: (st.lastPlay.cards || []).slice(), claimColor: st.lastPlay.claimColor, count: st.lastPlay.count, turnSeq: st.lastPlay.turnSeq, revealed: false, lied: null } : null,
      phase: 'playing', winnerSeat: null, log: [], speeches: [], selected: [], itemMode: null, reveal: null,
      isThinking: false, actionCount: 0, aiChat: false, speechInterval: 999, aiLevel: 'fast', resultRecorded: true, lastSpeechAt: 0
    };
  }
  // 确定化：按公开信息随机重排弹巢，并为对手重抽手牌（数量一致）
  function lieDeterminize(st2, mySeat, rng) {
    const rand = typeof rng === 'function' ? rng : Math.random; // 强力档传播种随机源，保证同一局面推演可复现
    const n = st2.players.length;
    const chambers = [];
    for (let i = 0; i < st2.gun.liveLeft; i++) chambers.push(true);
    for (let i = 0; i < st2.gun.blankLeft; i++) chambers.push(false);
    while (chambers.length < 6) chambers.push(false);
    st2.gun.chambers = lieShuffle(chambers, rand);
    st2.gun.ptr = 0;
    lieGunSync(st2);
    for (const p of st2.players) {
      if (p.seat === mySeat || !p.alive) continue;
      const cnt = p.basic.length;
      p.basic = [];
      for (let i = 0; i < cnt; i++) {
        const r = rand();
        const color = r < 0.30 ? 'red' : r < 0.60 ? 'yellow' : r < 0.90 ? 'blue' : 'star';
        p.basic.push({ kind: 'basic', color: color });
      }
      const ic = p.items.length;
      p.items = [];
      for (let i = 0; i < ic; i++) p.items.push({ kind: 'item', item: lieRndPick(LIE_ITEM_KEYS, rand) });
    }
    return st2;
  }

  function lieRollout(st2, deadline, level) {
    let guard = 0;
    while (st2.phase === 'playing' && guard++ < 140) {
      const seat = st2.turnSeat;
      const p = st2.players[seat];
      if (!p || !p.alive || p.escaped) { lieAdvanceTurn(st2, seat); continue; }
      let done = false;
      const mustCh = lieMustChallenge(st2, seat);
      if (mustCh || lieCanChallenge(st2, seat)) {
        const d = mustCh ? { challenge: true } : lieAiChallengeDecision(st2, p, level || 'normal');
        if (d.challenge) { if (lieDoChallenge(st2, seat)) done = true; }
      }
      if (!done) {
        const idxs = lieAiChoosePlay(st2, p, true);
        if (!lieDoPlay(st2, seat, idxs)) {
          // 兜底：出第一张，避免卡死
          if (!lieDoPlay(st2, seat, [0])) lieAdvanceTurn(st2, seat);
        }
      }
      if (deadline && Date.now() > deadline) break;
    }
    if (st2.phase !== 'playing') return st2.winnerSeat;
    const alive = st2.players.filter(x => x.alive);
    if (alive.length === 1) return alive[0].seat;
    let best = alive[0] || null;
    for (const x of alive) if (x.hp > best.hp) best = x;
    return best ? best.seat : null;
  }

  // 主决策：质疑 or 出牌（可开启蒙特卡洛）
  function lieAiMainDecision(st, p, opts) {
    opts = opts || {};
    // 规则：上家已出完手牌且只剩 2 名未逃离玩家 → 只能质疑
    if (lieMustChallenge(st, p.seat)) return { type: 'challenge', tag: 'must', h: 999, score: 1e9 };
    const canCh = lieCanChallenge(st, p.seat);
    const candidates = [];
    if (canCh) candidates.push({ type: 'challenge' });
    for (const pl of lieAiPlayCandidates(st, p)) candidates.push({ type: 'play', idxs: pl.idxs, tag: pl.tag });
    if (!candidates.length) return null;
    const lvl = difficultyLevel(opts.level || (opts.fast ? 'fast' : 'normal'));
    const D = getDifficulty('lie', lvl);
    // 打分噪声：强力档关闭（确定性），幅度由难度中枢 D.noise 控制；快速档保留"新手"重罚
    for (const cd of candidates) cd.h = lieHeurScoreCandidate(st, p, cd, { noise: lvl !== 'strong' ? D.noise : 0, fast: lvl === 'fast' });
    if (opts.mc) {
      // 强力档：固定样本数，不用墙钟截断——同一局面负载不同会跑出不同样本数 → 决策漂移
      const fixed = lvl === 'strong';
      const deadline = Date.now() + (opts.budgetMs || 800);
      const maxSamples = opts.samples || 4;
      const rng = pickRng(lvl, 'lie-mc|' + st.turnSeat + '|' + st.turnSeq + '|' + st.targetColor + '|' +
        st.players.map(x => x.hp + ':' + (x.basic || []).length + ':' + (x.items || []).length + ':' + (x.alive ? 1 : 0) + ':' + (x.escaped ? 1 : 0)).join(',') + '|' +
        (st.lastPlay ? (st.lastPlay.seat + ':' + st.lastPlay.claimColor + ':' + st.lastPlay.count) : '-') + '|' + st.gun.liveLeft + ':' + st.gun.blankLeft);
      for (const cd of candidates) { cd.win = 0; cd.n = 0; }
      let guard = 0;
      let samplesDone = 0;
      while ((fixed ? samplesDone < maxSamples : Date.now() < deadline) && guard++ < maxSamples * candidates.length * 4) {
        for (const cd of candidates) {
          if (!fixed && Date.now() >= deadline) break;
          const st2 = lieDeterminize(lieCloneState(st), p.seat, rng);
          st2._rng = rng; // 推演中的重新发牌/换弹夹也用播种随机源
          const ok = cd.type === 'challenge' ? lieDoChallenge(st2, p.seat) : lieDoPlay(st2, p.seat, cd.idxs);
          cd.n++;
          if (!ok) continue;
          const w = lieRollout(st2, fixed ? 0 : deadline, lvl);
          if (w === p.seat) cd.win++;
        }
        samplesDone++;
      }
      for (const cd of candidates) {
        const wr = cd.n ? cd.win / cd.n : 0;
        cd.score = wr * 1000 + cd.h * 0.28;
      }
    } else {
      for (const cd of candidates) cd.score = cd.h;
    }
    candidates.sort((a, b) => b.score - a.score);
    return candidates[0];
  }

  // ========== 单个 AI 动作（道具 → 质疑 / 出牌） ==========
  function lieAiStep(st) {
    const p = st.players[st.turnSeat];
    if (!p || p.isUser || !p.alive || st.phase !== 'playing') return null;
    // 统一难度中枢：快速档失误率高、不开蒙特卡洛、不记牌；强力档才开蒙特卡洛 + 对手建模
    st.aiLevel = liveAiLevel(loadLieConfig, st.aiLevel);
    const D = getDifficulty('lie', st.aiLevel);
    const lvl = D.level;
    // 规则强制：上家已出完手牌且只剩 2 名未逃离玩家 → 只能质疑，禁止用道具
    if (lieMustChallenge(st, p.seat)) {
      if (lieDoChallenge(st, p.seat)) return 'challenge';
    }
    p.aiItemsThisTurn = p.aiItemsThisTurn || 0;
    const canCh = lieCanChallenge(st, p.seat);
    const pre = canCh ? lieAiChallengeDecision(st, p, lvl) : { challenge: false, prob: 0, risk: 0.5 };
    // 强力档：道具决策传播种随机源（同一局面/同一状态 → 同一道具选择），快速/标准继续用 Math.random
    const itemRng = pickRng(lvl, 'lie-item|' + st.turnSeq + '|' + p.seat + '|' + p.hp + '|' + (p.items || []).map(x => x.item).join(',') + '|' + st.gun.liveLeft + ':' + st.gun.blankLeft);
    if (p.aiItemsThisTurn < 2) {
      const itemAction = lieAiPickItemAction(st, p, pre, lvl, itemRng); // 道具使用概率分档（快速档更少用道具）
      if (itemAction) {
        const res = lieUseItem(st, p.seat, itemAction.idx, itemAction.target);
        if (res && res.ok) { p.aiItemsThisTurn++; return 'item'; }
        // 道具失败（例如没有目标）→ 移除该道具避免死循环
        if (res && !res.ok) { try { p.items.splice(itemAction.idx, 1); } catch (e) { /* ignore */ } return 'item'; }
      }
    }
    // 强力档：蒙特卡洛 + 对手建模（samples=6 / budget=600ms，取自难度中枢）
    const useMc = lvl === 'strong' && D.sims > 0;
    const decision = lieAiMainDecision(st, p, {
      mc: useMc,
      budgetMs: D.timeMs || 800,
      samples: D.sims || 4,
      fast: lvl === 'fast',
      level: lvl
    });
    if (decision && decision.type === 'challenge') { lieDoChallenge(st, p.seat); return 'challenge'; }
    const idxs = (decision && decision.idxs && decision.idxs.length) ? decision.idxs : lieAiChoosePlay(st, p, lvl === 'fast', lvl === 'strong');
    if (!lieDoPlay(st, p.seat, idxs)) {
      if (!lieDoPlay(st, p.seat, [0])) lieAdvanceTurn(st, p.seat);
      return 'play';
    }
    return 'play';
  }
  // __LIE_ENGINE_END__
// ========== 欺诈酒馆：实时存档 / 恢复 ==========
  let lieGame = null;
  let lieAiTimer = null;
  let lieGenCounter = 0;
  let lieChatBusy = false;

  function lieSaveState() {
    if (!lieGame || lieGame.phase === 'ended') { lieClearSaved(); return; }
    try {
      const st = lieGame;
      localStorage.setItem(LIE_SAVE_KEY, JSON.stringify({
        createdAt: st.createdAt, players: st.players, dir: st.dir, turnSeat: st.turnSeat, turnSeq: st.turnSeq,
        round: st.round, targetColor: st.targetColor, gun: st.gun, lastPlay: st.lastPlay, phase: st.phase,
        log: st.log, speeches: st.speeches, aiChat: st.aiChat, speechInterval: st.speechInterval,
        aiLevel: st.aiLevel, actionCount: st.actionCount, turnsSinceChallenge: st.turnsSinceChallenge,
        playedCount: st.playedCount || 0, winnerSeat: st.winnerSeat
      }));
    } catch (e) { /* ignore */ }
  }
  function lieClearSaved() { try { localStorage.removeItem(LIE_SAVE_KEY); } catch (e) { /* ignore */ } }
  function lieHasSaved() {
    try {
      const raw = localStorage.getItem(LIE_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && d.players && d.phase && d.phase !== 'ended');
    } catch (e) { return false; }
  }
  function lieResumeSaved() {
    try {
      const raw = localStorage.getItem(LIE_SAVE_KEY);
      if (!raw) { renderLieLobby(); return; }
      const d = JSON.parse(raw);
      lieGenCounter++;
      lieChatBusy = false; // 同 startLieGame：恢复对局时解锁聊天标志
      if (lieAiTimer) { clearTimeout(lieAiTimer); lieAiTimer = null; }
      lieGame = {
        createdAt: d.createdAt || Date.now(), players: d.players, dir: d.dir || 1, turnSeat: d.turnSeat || 0,
        turnSeq: d.turnSeq || 1, round: d.round || 1, targetColor: d.targetColor || 'red', gun: d.gun,
        basicDeck: [], itemDeck: lieMakeItemDeck(), playedCount: d.playedCount || 0, lastPlay: d.lastPlay || null,
        phase: d.phase || 'playing', winnerSeat: (d.winnerSeat === undefined ? null : d.winnerSeat),
        log: d.log || [], speeches: d.speeches || [], selected: [], itemMode: null, reveal: null,
        isThinking: false, actionCount: d.actionCount || 0, turnsSinceChallenge: d.turnsSinceChallenge || 0,
        aiChat: d.aiChat !== false, speechInterval: d.speechInterval || 4, aiLevel: d.aiLevel || 'normal',
        lastSpeechAt: 0, resultRecorded: false
      };
      lieGame.players.forEach(p => {
        p.aiItemsThisTurn = 0;
        p.escaped = !!p.escaped;
        p.items = p.items || [];
        p.basic = p.basic || [];
      });
      renderLieGameUI();
      lieAfterTurn(700);
      showToast(' 已恢复进行中的欺诈酒馆对局');
    } catch (e) { renderLieLobby(); }
  }

  // ========== 欺诈酒馆：启动与 AI 调度 ==========
  function startLieGame(names) {
    lieGenCounter++;
    lieChatBusy = false; // 必须复位：上一局赛后台词的请求 finally 因 gen 不符不会解锁，否则整局哑掉
    if (lieAiTimer) { clearTimeout(lieAiTimer); lieAiTimer = null; }
    lieGame = lieBuildGame(names);
    const cfg = loadLieConfig();
    cfg.partnerNames = lieGame.players.filter(p => !p.isUser).map(p => p.name);
    saveLieConfig(cfg);
    lieLog(lieGame, '🎬 新对局开始：' + lieGame.players.map(p => p.name).join('、') + ' 入座（2 血 · 每回合重新发牌：每色 ' + LIE_PER_COLOR + ' 张 + ' + LIE_STAR_COUNT + ' 张万能 + 3 道具 · 共用左轮）', '#8B5CF6', { kind: 'end' });
    lieLog(lieGame, '🎯 第 ' + lieGame.round + ' 回合开始 · 目标颜色【' + LIE_COLOR_LABEL[lieGame.targetColor] + '】· 重新发牌', LIE_COLOR_HEX[lieGame.targetColor], { kind: 'end' });
    lieSaveState();
    renderLieGameUI();
    lieAfterTurn(800);
  }

  function lieAfterTurn(delay) {
    if (!lieGame || lieGame.phase !== 'playing') return;
    const p = lieGame.players[lieGame.turnSeat];
    if (p && !p.isUser && p.alive) lieScheduleAi(delay || 750);
    else renderLieGameUI();
  }

  function lieScheduleAi(delay) {
    if (lieAiTimer) { clearTimeout(lieAiTimer); lieAiTimer = null; }
    if (!lieGame || lieGame.phase !== 'playing') return;
    const gen = lieGenCounter;
    lieGame.isThinking = true;
    renderLieGameUI();
    lieAiTimer = setTimeout(() => {
      lieAiTimer = null;
      if (!lieGame || gen !== lieGenCounter) return;
      lieGame.isThinking = false;
      lieAiTick();
    }, delay || 750);
  }

  function lieAiTick() {
    const st = lieGame;
    if (!st || st.phase !== 'playing') return;
    const before = st.turnSeat;
    let result = null;
    try { result = lieAiStep(st); } catch (e) { result = null; }
    if (result === null) { // 兜底：避免卡死
      if (st.lastPlay && lieCanChallenge(st, st.turnSeat)) lieDoChallenge(st, st.turnSeat);
      else if (!lieDoPlay(st, st.turnSeat, [0])) lieAdvanceTurn(st, st.turnSeat);
    }
    lieSaveState();
    renderLieGameUI();
    lieMaybeAutoSpeak(result === 'challenge' ? 'challenge' : result === 'item' ? 'item' : 'play', before);
    if (st.phase !== 'playing') { lieOnGameOver(); return; }
    if (st.turnSeat === before && result === 'item') { lieScheduleAi(650); return; }
    lieAfterTurn(750);
  }

  function lieOnGameOver() {
    if (!lieGame || lieGame.phase !== 'ended') return;
    if (lieAiTimer) { clearTimeout(lieAiTimer); lieAiTimer = null; }
    lieClearSaved();
    renderLieGameUI();
    renderLieResultModal();
    lieRecordFinished();
    lieMaybeAutoSpeak('end', lieGame.winnerSeat, true);
  }

  // ========== 欺诈酒馆：对局记录与联动 ==========
  function liePlayerResultLine() {
    const st = lieGame;
    const w = (st.winnerSeat !== null && st.players[st.winnerSeat]) ? st.players[st.winnerSeat] : null;
    if (!w) return '本局结束';
    const names = st.players.map(p => p.name + '（' + Math.max(0, p.hp) + '血' + (p.alive ? '' : '·出局') + '）').join('、');
    return w.name + ' 成为最后的幸存者获胜；存活情况：' + names;
  }
  function lieRecordFinished() {
    const st = lieGame;
    if (!st || st.resultRecorded) return;
    st.resultRecorded = true;
    try {
      const userWon = st.winnerSeat === 0;
      const replayText = st.log.map(e => e.text).filter(Boolean).slice(-90).join('\n');
      const detail = '玩家：' + st.players.map(p => p.name + (p.isUser ? '（主角）' : '')).join('、') +
        '；总回合 ' + (st.round || 1) + '；总行动 ' + (st.turnSeq || 0) + '；枪内已打出 ' + ((st.gun && st.gun.fired) || 0) + ' 发';
      onGameFinished({
        gameType: 'liar',
        userWon: !!userWon,
        result: liePlayerResultLine() + '；主角' + (userWon ? '获胜' : '落败'),
        detail: detail,
        replay: replayText,
        replayRich: {
          logs: st.log.map(e => ({ text: e.text, authorPos: (e.seat === null || e.seat === undefined) ? null : e.seat, type: 'public', color: e.color || '' })),
          players: st.players.map(p => ({
            position: p.seat, name: p.name, isUser: !!p.isUser,
            avatar: p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name)) || ''
          }))
        },
        players: st.players.map(p => ({ name: p.name, isUser: p.isUser, avatar: p.avatar || '' }))
      });
    } catch (e) { /* ignore */ }
  }

  // ========== 欺诈酒馆：角色 AI 陪聊 ==========
  function liePushSpeech(seat, text) {
    const st = lieGame;
    if (!st || !text) return;
    st.speeches.push({ seat: seat, name: lieSeatName(seat), text: text });
    if (st.speeches.length > 30) st.speeches = st.speeches.slice(-30);
    if (typeof contactsVoiceAutoSpeak === 'function') contactsVoiceAutoSpeak(st.speeches.length ? st.speeches[st.speeches.length - 1].name : '', text);
  }

  function lieSeatName(seat) {
    if (!lieGame || !lieGame.players[seat]) return '玩家';
    return lieGame.players[seat].name;
  }
  function lieSeatColor(seat) {
    const p = lieGame && lieGame.players[seat];
    return p ? (p.isUser ? '#FFFFFF' : getCharacterColor(p.name)) : '#8B5CF6';
  }
  function lieRecentLogText(limit) {
    const st = lieGame;
    if (!st) return '';
    return (st.log || []).filter(e => !e.secret || e.revealTo === 0).slice(-(limit || 12)).map(e => e.text).join('\n');
  }
  function lieMaybeAutoSpeak(scene, seat, force) {
    const st = lieGame;
    if (!st || !st.aiChat || lieChatBusy) return;
    if (!force) {
      if (Date.now() - (st.lastSpeechAt || 0) < 7000) return;
      if (st.actionCount % (st.speechInterval || 4) !== 0) return;
    }
    let target = seat;
    if (target === 0 || !st.players[target] || st.players[target].isUser || !st.players[target].alive) {
      const others = st.players.filter(p => !p.isUser && p.alive);
      target = others.length ? others[0].seat : null;
    }
    if (target === null) return;
    lieRequestSpeech(target, scene, null);
  }
  function lieExtractSpeech(res, name) {
    let clean = '';
    const m = res.match(/<lines>([\s\S]*?)<\/lines>/i);
    if (m) clean = m[1].trim(); else clean = String(res || '').trim();
    clean = clean.replace(/<lines>|<\/lines>/gi, '').replace(/[\"'「」]/g, '').trim();
    if (name) clean = clean.replace(new RegExp('^' + name + '[：:]\\s*'), '');
    return clean;
  }
  function lieRequestSpeech(seat, scene, userMsg) {
    const st = lieGame;
    if (!st || !st.aiChat) return;
    const p = st.players[seat];
    if (!p || p.isUser) return;
    const apiCfg = ensureAIBackend();
    if (!apiCfg) return;
    if (lieChatBusy) return;
    const gen = lieGenCounter;
    const prof = getCharacterProfile(p.name) || {};
    const phoneCtx = getCharacterWechatContext(p.name);
    const socialCtx = getCharacterSocialContext(p.name);
    const others = st.players.filter(x => x.seat !== seat).map(x => x.name + '（' + (x.alive ? Math.max(0, x.hp) + '血' : '已出局') + '）').join('、');
    const myHand = (p.basic || []).map(c => LIE_COLOR_LABEL[c.color]).join(' ');
    const myItems = (p.items || []).map(i => LIE_ITEMS[i.item] ? LIE_ITEMS[i.item].name : '').filter(Boolean).join('、') || '无';
    const sceneText = {
      play: '你刚打出了一手牌并宣称它们是目标颜色',
      challenge: '你刚刚质疑了上家的牌',
      item: '你刚使用了一张道具牌',
      end: '本局刚刚结束',
      'user-chat': '主角正在牌桌上对你说话，你需要回应主角',
      start: '牌局刚刚开始'
    }[scene] || '牌桌上的闲聊时刻';
    const system = '你和主角、其他好友正在玩《欺诈酒馆》——吹牛 + 左轮手枪的心理博弈桌游（每人 2 点生命，出牌可掺假，被拆穿或质疑失败就要挨枪）。你扮演【' + p.name + '】。\n' +
      '【角色档案（来自数据库本体的重要角色表/恋爱对象表）】\n' +
      '- 身份：' + (prof.identity || '好友') + '\n- 性格：' + (prof.personality || '自然活泼') + '\n' +
      '- 说话风格与口癖：' + (prof.languageStyle || '口语化') + '\n- 对主角态度：' + (prof.attitude || '友好亲近') + '\n' +
      (prof.brief ? ('- 简介：' + prof.brief + '\n') : '') +
      '【' + p.name + ' 的资料库档案与人物关系（重要角色表 / 恋爱对象表 / 人物关系表）】\n' + (phoneCtx || '（暂无，按资料库信息与人物关系自然发挥）') + '\n\n' +
      '【牌局信息】\n- 同局玩家：' + others + '\n- 你的状态：' + Math.max(0, p.hp) + ' 点生命，你的手牌：' + (myHand || '无') + '，你的道具：' + myItems + '\n' +
      '- 当前目标颜色：' + LIE_COLOR_LABEL[st.targetColor] + '；当前场景：' + sceneText + '\n' +
      '- 主角/其他人刚才做了什么（最近牌局进程，从旧到新）：\n' + (lieRecentLogText(10) || '（开局阶段）') + '\n' +
      '- 你上一句说过的话：' + (((st.speeches || []).filter(s => s.seat === seat).slice(-1)[0] || {}).text || '（还没说话）') + '\n\n' +
      '【台词要求】\n1. 完全代入角色人设与口癖，说出生动自然的真人台词：可以吹嘘、心虚、挑衅、装无辜、吐槽枪运、和主角互怼。\n' +
      '2. 【重点】必须围绕主角前面干了什么来发言：点评主角刚才的宣称/质疑/开枪，顺势聊到你们在资料库中的人设关系与过往故事，或说说之后想跟主角做什么、分享一件自己最近的事。\n' +
      '3. 要有活人感：带情绪、开玩笑、抱怨、撒娇、炫耀或关心主角，严禁空洞复读。\n' +
      '4. 严禁括号、旁白、动作与心理描写，只输出角色说出口的话。\n' +
      '5. 【完整出字铁律（参考狼人杀）】只输出：<lines>台词正文</lines>；发言长度自然，可长可短，口语化；必须语义完整、自然收尾，严禁半句截断、严禁只输出标点或空白、严禁空回复。即使没有新话题，也要用一句完整的日常话接住主角刚才的行动。';
    const messages = [{ role: 'system', content: system }];
    if (userMsg) messages.push({ role: 'user', content: '【主角对你说】' + userMsg + '\n请以【' + p.name + '】的口吻回一句。' });
    else messages.push({ role: 'user', content: '请以【' + p.name + '】的口吻说一段完整的牌桌台词（发言长度自然，可长可短，口语化；必须语义完整、自然收尾，严禁半句截断）。' });
    lieChatBusy = true;
    st.lastSpeechAt = Date.now();
    apiChat(messages, apiCfg, { maxTokens: 1000, temperature: 0.95 }).then(res => {
      if (gen !== lieGenCounter) return;
      let clean = ensureCompleteLine(lieExtractSpeech(res, p.name));
      if (!clean || clean.length < 4) return;
      if (!/[。！？…]$/.test(clean)) clean += '。';
      liePushSpeech(seat, clean);
      lieSaveState();
      lieRefreshSpeechBox();
    }).catch(() => { /* 静默 */ }).finally(() => { if (gen === lieGenCounter) lieChatBusy = false; });
  }
  function lieRenderSpeechHTML() {
    const st = lieGame;
    if (!st) return '';
    const conv = (st.speeches || []).slice(-24);
    if (!conv.length) return '<span style="color:var(--ubp-text-3);">（牌桌上一片安静，只有左轮的转轮声…）</span>';
    return conv.map(sp => chatSpeechRowHTML(sp.name, sp.text, sp.seat === 0)).join('');
  }
  function lieRefreshSpeechBox() {
    const el = sheet && sheet.querySelector('#lie-speech-text');
    if (!el) return;
    const box = sheet && sheet.querySelector('#lie-speech-container');
    const atBottom = !box || (box.scrollTop + box.clientHeight >= box.scrollHeight - 12);
    el.innerHTML = lieRenderSpeechHTML();
    if (box && atBottom) box.scrollTop = box.scrollHeight;
  }

  // 台词完整化：清理标签/引号/括号，确保以句末标点收尾（对齐狼人杀的「完整出字铁律」）
  function ensureCompleteLine(raw) {
    let s = String(raw == null ? '' : raw).trim();
    if (!s) return '';
    s = s.replace(/<lines>|<\/lines>/gi, '')
      .replace(/<speech>|<\/speech>/gi, '')
      .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
      .replace(/【思考原因】[\s\S]*?(?=【公开发言】|<speech>)/gi, '')
      .replace(/[*_`~]/g, '')
      .replace(/^[“”"'「」『』【】\s]+/, '')
      .replace(/[“”"'「」『』\s]+$/, '')
      .replace(/^[（(][^）)]{0,20}[）)]\s*/, '')
      .trim();
    if (!s) return '';
    // 不截断内容：仅当整段缺少句末标点时补一个句号，保证输出是完整的一整段话
    if (!/[。！？…!?～~]$/.test(s)) s += '。';
    return s.trim();
  }

  // 牌桌发言头像（角色发言左侧显示头像；主角显示「我」）
  function chatAvatarHTML(name, isUser, size, explicitAvatar) {
    const s = size || 26;
    const avatar = explicitAvatar || (isUser ? (getMainCharAvatar() || '') : (getCharacterAvatarByName(name) || ''));
    const color = isUser ? '#8B5CF6' : (getCharacterColor(name) || '#8B5CF6');
    const initial = isUser ? '我' : String(name || '?').slice(0, 1);
    return '<span style="display:inline-flex;width:' + s + 'px;height:' + s + 'px;border-radius:50%;overflow:hidden;background:' + color + ';flex:none;vertical-align:middle;">' +
      (avatar
        ? '<img src="' + avatar + '" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.style.display=\'none\'; if(this.nextElementSibling) this.nextElementSibling.style.display=\'flex\';"><span style="display:none;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-size:' + Math.round(s * 0.45) + 'px;font-weight:bold;">' + escapeHtml(initial) + '</span>'
        : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-size:' + Math.round(s * 0.45) + 'px;font-weight:bold;">' + escapeHtml(initial) + '</span>') +
      '</span>';
  }
  // 带头像的发言行（左头像 + 名字 + 内容）
  function chatSpeechRowHTML(name, text, isUser, opts) {
    opts = opts || {};
    const color = isUser ? '#fff' : (getCharacterColor(name) || 'var(--ubp-accent, #10B981)');
    const bubbleBg = isUser ? 'rgba(139,92,246,0.14)' : charColorAlpha(getCharacterColor(name), '14');
    return '<div style="display:flex;align-items:flex-start;gap:6px;margin:4px 0;line-height:1.5;">' +
      chatAvatarHTML(name, isUser, opts.avatarSize || 26) +
      '<div style="flex:1;min-width:0;background:' + (bubbleBg || 'transparent') + ';border-radius:7px;padding:3px 7px;">' +
      '<b style="color:' + color + ';font-size:11.5px;">' + escapeHtml(name) + (isUser ? '（我）' : '') + '：</b>' +
      '<span style="color:var(--ubp-text);font-size:11.5px;">' + escapeHtml(text) + '</span></div></div>';
  }

  // ========== 欺诈酒馆：牌面与棋盘 UI ==========
  function lieColorDotHTML(color, size) {
    const s = size || 12;
    return '<span style="display:inline-block;width:' + s + 'px;height:' + s + 'px;border-radius:50%;background:' + (LIE_COLOR_HEX[color] || '#888') + ';vertical-align:middle;"></span>';
  }
  function lieChipHTML(card, opts) {
    opts = opts || {};
    const color = card && card.color ? card.color : 'red';
    const sel = !!opts.selected;
    const label = LIE_COLOR_LABEL[color] || '?';
    const star = color === 'star';
    const w = opts.w || 46, h = opts.h || 62;
    const attrs = opts.interactive ? (' data-lie-act="lie-card" data-idx="' + opts.idx + '"') : '';
    return '<div' + attrs + ' style="position:relative;flex:0 0 ' + w + 'px;width:' + w + 'px;height:' + h + 'px;border-radius:7px;background:' + (sel ? 'rgba(255,255,255,0.22)' : 'var(--ubp-card, #26262a)') + ';border:2px solid ' + (sel ? '#fff' : (LIE_COLOR_HEX[color] || '#888')) + ';display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;cursor:' + (opts.interactive ? 'pointer' : 'default') + ';user-select:none;transform:' + (sel ? 'translateY(-6px)' : 'none') + ';transition:transform .12s;box-sizing:border-box;">' +
      (star ? '<span style="font-size:' + Math.round(w * 0.5) + 'px;line-height:1;">⭐</span>' : '<span style="font-size:' + Math.round(w * 0.46) + 'px;font-weight:bold;line-height:1;color:' + LIE_COLOR_HEX[color] + ';">' + label + '</span>') +
      '<span style="font-size:9.5px;color:var(--ubp-text-3);">' + (star ? '万能' : label + '色') + '</span></div>';
  }
  // 已打出的暗牌：牌面颜色与牌字颜色一致（按宣称的目标色着色）
  function lieCardBackHTML(w, h, color) {
    const ww = w || 34, hh = h || 46;
    const hex = LIE_COLOR_HEX[color] || '#888';
    const label = LIE_COLOR_LABEL[color] || '?';
    return '<div style="flex:0 0 ' + ww + 'px;width:' + ww + 'px;height:' + hh + 'px;border-radius:6px;background:' + hex + '2E;border:2px solid ' + hex + ';display:flex;align-items:center;justify-content:center;color:' + hex + ';font-weight:bold;font-size:' + Math.round(ww * 0.36) + 'px;box-sizing:border-box;">' + label + '</div>';
  }
  function lieItemChipHTML(item, idx, disabled) {
    const def = LIE_ITEMS[item && item.item] || { name: '?', icon: '' };
    return '<div data-lie-act="lie-item" data-idx="' + idx + '" style="display:inline-flex;align-items:center;gap:3px;padding:3px 7px;border-radius:6px;background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);font-size:11px;color:var(--ubp-text);cursor:' + (disabled ? 'default' : 'pointer') + ';opacity:' + (disabled ? '0.5' : '1') + ';white-space:nowrap;">' + def.icon + ' ' + def.name + '</div>';
  }
  function lieHpHTML(p) {
    let s = '';
    for (let i = 0; i < LIE_HP; i++) s += '<span style="font-size:11px;opacity:' + (i < p.hp ? '1' : '0.25') + ';">❤️</span>';
    return s;
  }
  function lieGunHTML() {
    const st = lieGame;
    const g = st.gun;
    let dots = '';
    for (let i = 0; i < 6; i++) {
      const used = i < g.ptr;
      const cur = i === g.ptr;
      let col = used ? '#374151' : '#6B7280';
      let border = '1px solid rgba(255,255,255,0.15)';
      if (cur) {
        // 不泄露下一颗真实弹种：仅自己使用【转换】时用紫色标记
        col = (g.override && g.override.bySeat === 0) ? '#8B5CF6' : '#9CA3AF';
        border = '2px solid #fff';
      }
      dots += '<span style="display:inline-block;width:11px;height:11px;border-radius:50%;background:' + col + ';margin-right:3px;border:' + border + ';box-sizing:border-box;"></span>';
    }
    return '<div style="display:flex;align-items:center;gap:6px;font-size:10.5px;color:#FFFFFF;">' +
      '<span>🔫</span>' + dots +
      '<span>枪内 实' + Math.max(0, g.liveLeft) + '/空' + Math.max(0, g.blankLeft) + '</span>' +
      '<span>（下一颗可用【检查】查看）</span></div>';
  }

  function liePlayersRowHTML() {
    const st = lieGame;
    const opps = st.players.filter(p => !p.isUser);
    return opps.map(p => {
      const isTurn = st.turnSeat === p.seat && st.phase === 'playing';
      const note = (p.history && p.history.length) ? p.history[p.history.length - 1] : null;
      let noteText = '';
      if (note) {
        if (note.challenged) noteText = note.lied ? '被抓说谎' : '被证明清白';
        else noteText = '宣称 ' + note.count + ' 张【' + LIE_COLOR_LABEL[note.claimColor] + '】';
      }
      if (p.alive && p.escaped) noteText = '🏃 已逃离本回合';
      const av = p.avatar || getCharacterAvatarByName(p.name);
      const color = getCharacterColor(p.name);
      return '<div style="flex:1;min-width:0;background:var(--ubp-card-2, #26262a);border:1.5px solid ' + (isTurn ? color : 'var(--ubp-line)') + ';border-radius:9px;padding:5px 6px;' + (p.alive ? '' : 'opacity:0.45;') + '">' +
        '<div style="display:flex;align-items:center;gap:5px;">' +
        '<div style="width:26px;height:26px;border-radius:50%;overflow:hidden;background:' + color + ';flex-shrink:0;">' +
        (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-size:12px;font-weight:bold;">' + escapeHtml(p.name.slice(0, 1)) + '</span>') + '</div>' +
        '<div style="flex:1;min-width:0;">' +
        '<div style="font-size:11.5px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(p.name) + (p.alive ? '' : ' · 出局') + (p.alive && p.escaped ? ' 🏃逃离' : '') + (isTurn ? ' ◀' : '') + '</div>' +
        '<div style="font-size:10px;">' + lieHpHTML(p) + '</div>' +
        '</div>' +
        '<div style="font-size:9.5px;color:var(--ubp-text-3);text-align:right;flex-shrink:0;">' + (p.basic ? p.basic.length : 0) + '<br>🎴' + (p.items ? p.items.length : 0) + '</div>' +
        '</div>' +
        (noteText ? '<div style="font-size:9.5px;color:var(--ubp-text-3);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(noteText) + '</div>' : '') +
        '</div>';
    }).join('');
  }
  function lieLogHTML() {
    const st = lieGame;
    const list = (st.log || []).filter(e => !e.secret || e.revealTo === 0).slice(-40);
    if (!list.length) return '<span style="color:var(--ubp-text-3);">牌局开始…</span>';
    return list.map(e => {
      const rowStyle = 'margin:2px 0;color:' + (e.color || 'var(--ubp-text-2)') + ';font-size:11.5px;line-height:1.45;';
      if (e.seat !== null && e.seat !== undefined && st.players[e.seat]) {
        const pl = st.players[e.seat];
        return '<div style="display:flex;align-items:flex-start;gap:5px;' + rowStyle + '">' +
          '<span style="flex:none;margin-top:1px;">' + chatAvatarHTML(pl.name, !!pl.isUser, 20) + '</span>' +
          '<span style="flex:1;min-width:0;word-break:break-word;">' + escapeHtml(e.text) + '</span></div>';
      }
      return '<div style="' + rowStyle + '">' + escapeHtml(e.text) + '</div>';
    }).join('');
  }
  function lieLastPlayHTML() {
    const st = lieGame;
    if (st.reveal) {
      const r = st.reveal;
      if (r.type === 'peek') {
        return '<div style="text-align:center;font-size:11.5px;color:#A855F7;">👁️ 你偷看到 ' + escapeHtml(r.target) + ' 的手牌：' + (r.colors || []).map(c => LIE_COLOR_LABEL[c]).join('、') + '</div>';
      }
      return '<div style="text-align:center;font-size:11.5px;color:' + (r.lied ? '#10B981' : '#EF4444') + ';">' +
        '翻开：' + (r.colors || []).map(c => LIE_COLOR_LABEL[c]).join(' ') + '（宣称 ' + LIE_COLOR_LABEL[r.claimColor] + '）→ ' + (r.lied ? '确实是谎话！' : '竟然是实话！') + '</div>';
    }
    const lp = st.lastPlay;
    if (!lp) return '<div style="text-align:center;font-size:11.5px;color:var(--ubp-text-3);">本回合没有可质疑的牌，必须出牌</div>';
    const lpEscaped = (st.players[lp.seat] && (st.players[lp.seat].basic || []).length === 0) ? '（已逃离）' : '';
    return '<div style="display:flex;flex-direction:column;align-items:center;gap:3px;">' +
      '<div style="font-size:11px;color:#FFFFFF;">' + escapeHtml(lieSeatName(lp.seat)) + ' 宣称打出 ' + lp.count + ' 张【' + LIE_COLOR_LABEL[lp.claimColor] + '】' + lpEscaped + '</div>' +
      '<div style="display:flex;gap:4px;">' + lp.cards.map(() => lieCardBackHTML(30, 40, lp.claimColor)).join('') + '</div></div>';
  }

  // ========== 欺诈酒馆：主界面 ==========
  function renderLieGameUI() {
    if (!lieGame) { renderLieLobby(); return; }
    const st = lieGame;
    const me = st.players[0];
    const myTurn = st.turnSeat === 0 && st.phase === 'playing' && me.alive;
    const canCh = myTurn && lieCanChallenge(st, 0);
    const mustCh = myTurn && lieMustChallenge(st, 0);
    const selCount = (st.selected || []).length;
    const targetHex = LIE_COLOR_HEX[st.targetColor] || '#888';

    let statusText = '';
    if (st.phase === 'ended') {
      statusText = st.winnerSeat === 0 ? '🎉 你活到了最后！' : ('💀 ' + escapeHtml(lieSeatName(st.winnerSeat)) + ' 成为最后的幸存者');
    } else if (!me.alive) statusText = '💀 你已出局，观战中…';
    else if (myTurn) {
      if (mustCh) statusText = '⚠️ 上家已出完手牌，你只能质疑！';
      else statusText = canCh ? '👉 轮到你：质疑上家 或 出牌（任意张数）' : '👉 轮到你出牌（任意张数）';
    } else if (me.escaped) statusText = '🏃 你已出完手牌（逃离本回合），等待结算…';
    else statusText = '⏳ 等待 ' + escapeHtml(lieSeatName(st.turnSeat)) + ' 行动…';

    const itemRow = (me.items || []).map((it, i) => lieItemChipHTML(it, i, !myTurn || mustCh)).join('');
    const handRow = (me.basic || []).map((c, i) => lieChipHTML(c, { idx: i, interactive: myTurn && !mustCh, selected: (st.selected || []).includes(i) })).join('');

    const actionHTML = (st.phase === 'ended')
      ? '<div style="display:flex;gap:6px;"><button data-lie-act="lie-exit" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12.5px;">🚪 退出牌桌</button><button data-lie-act="lie-rematch" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:12.5px;background:#7C3AED;"> 再来一局</button></div>'
      : '<div style="display:flex;gap:6px;">' +
        '<button data-lie-act="lie-challenge" class="ubp-btn primary" style="flex:1.15;padding:8px 0;font-size:12.5px;background:#EF4444;' + ((canCh || mustCh) ? '' : 'opacity:0.4;pointer-events:none;') + '"> 质疑上家' + (canCh ? '（' + LIE_COLOR_LABEL[st.lastPlay.claimColor] + '×' + st.lastPlay.count + '）' : '') + (mustCh ? '（必须）' : '') + '</button>' +
        '<button data-lie-act="lie-play" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:12.5px;background:#10B981;' + (myTurn && !mustCh && selCount >= 1 ? '' : 'opacity:0.4;pointer-events:none;') + '">🃏 出牌' + (selCount ? '（' + selCount + '）' : '') + '</button>' +
        '</div>';

    const chatHTML = st.aiChat ? (
      '<div id="lie-speech-container" style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:8px;padding:6px 9px;margin-top:5px;flex:none;height:96px;max-height:96px;overflow-y:auto;box-sizing:border-box;">' +
      '<div id="lie-speech-text" style="font-size:11.5px;line-height:1.5;word-break:break-word;">' + lieRenderSpeechHTML() + '</div></div>' +
      '<div style="display:flex;gap:6px;margin-top:5px;flex:none;">' +
      '<input id="lie-chat-input" class="ubp-fieldinput" type="text" placeholder="对牌桌上的角色说点什么…（如：你手抖了吧）" style="flex:1;font-size:12px;padding:4px 8px;border-radius:6px;height:26px;">' +
      '<button data-lie-act="lie-send-chat" class="ubp-btn primary" style="padding:0 10px;font-size:12px;height:26px;background:#7C3AED;flex:none;">发送</button></div>'
    ) : '';

    // 保留聊天/日志滚动位置：有新系统播报时不再跳到第一条消息
    const prevSpeechBox = sheet.querySelector('#lie-speech-container');
    const prevLogBox = sheet.querySelector('#lie-log-scroll');
    const speechAtBottom = !prevSpeechBox || (prevSpeechBox.scrollTop + prevSpeechBox.clientHeight >= prevSpeechBox.scrollHeight - 12);
    const speechScrollTop = prevSpeechBox ? prevSpeechBox.scrollTop : 0;
    const logAtBottom = !prevLogBox || (prevLogBox.scrollTop + prevLogBox.clientHeight >= prevLogBox.scrollHeight - 12);
    const logScrollTop = prevLogBox ? prevLogBox.scrollTop : 0;

    sheet.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;flex:none;">
        <div style="display:flex;align-items:center;gap:6px;">
          <button data-lie-act="lie-exit" style="background:none;border:none;font-size:16px;cursor:pointer;color:var(--ubp-text);" title="返回大厅">←</button>
          <span style="font-size:14.5px;font-weight:bold;color:var(--ubp-text);">🎭 欺诈酒馆</span>
        </div>
        <div style="display:flex;align-items:center;gap:7px;">
          <span style="font-size:11px;color:#FFFFFF;">第 ${st.round || 1} 回合</span>
          <span style="display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:999px;background:${targetHex}22;border:1.5px solid ${targetHex};font-size:11.5px;font-weight:600;color:${targetHex};">🎯 目标色：${LIE_COLOR_LABEL[st.targetColor]}</span>
        </div>
      </div>

      <div style="display:flex;gap:5px;flex:none;margin-bottom:5px;">${liePlayersRowHTML()}</div>

      <div style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:10px;padding:6px 8px;flex:none;margin-bottom:5px;">
        <div style="margin-bottom:4px;">${lieGunHTML()}</div>
        ${lieLastPlayHTML()}
        <div style="text-align:center;font-size:11.5px;font-weight:600;color:${myTurn ? '#10B981' : 'var(--ubp-text-2)'};margin-top:4px;">${statusText}</div>
      </div>

      <div style="flex:1;min-height:0;display:flex;flex-direction:column;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:0 2px;flex:none;">
          <span style="font-size:10.5px;color:var(--ubp-text-3);">牌局日志</span>
          <span style="font-size:10.5px;color:var(--ubp-text-3);">我 ${Math.max(0, me.hp)} 血 · 剩 ${(me.basic || []).length} 张</span>
        </div>
        <div id="lie-log-scroll" style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:8px;padding:5px 8px;height:78px;max-height:78px;overflow-y:auto;margin-top:3px;flex:none;">
          ${lieLogHTML()}
        </div>

        ${chatHTML}

        <div style="display:flex;align-items:center;justify-content:space-between;margin-top:6px;flex:none;">
          <span style="font-size:10.5px;color:var(--ubp-text-3);">我的手牌（点选任意张数）${me.alive ? (me.escaped ? ' · 🏃 已逃离' : '') : ' · 已出局'}</span>
          <span style="font-size:10px;color:var(--ubp-text-3);">${(me.items || []).length} 张道具</span>
        </div>
        <div style="display:flex;justify-content:center;gap:4px;padding:8px 0 4px;flex-wrap:wrap;flex:none;">${handRow || '<span style="font-size:11px;color:var(--ubp-text-3);">暂无手牌</span>'}</div>
        <div style="display:flex;flex-wrap:wrap;gap:4px;justify-content:center;flex:none;margin-bottom:4px;">${itemRow || '<span style="font-size:10.5px;color:var(--ubp-text-3);">（无道具）</span>'}</div>
      </div>

      <div style="margin-top:5px;flex:none;">${actionHTML}</div>
    `;

    // 恢复滚动：本来就在底部 → 自动跟随最新消息；否则保持原来的阅读位置
    const newSpeechBox = sheet.querySelector('#lie-speech-container');
    if (newSpeechBox) newSpeechBox.scrollTop = speechAtBottom ? newSpeechBox.scrollHeight : speechScrollTop;
    const newLogBox = sheet.querySelector('#lie-log-scroll');
    if (newLogBox) newLogBox.scrollTop = logAtBottom ? newLogBox.scrollHeight : logScrollTop;

    const input = sheet.querySelector('#lie-chat-input');
    if (input) input.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); lieHandleUserChat(); } });
  }

  function lieHandleUserChat() {
    const st = lieGame;
    if (!st || !st.aiChat) return;
    const input = sheet.querySelector('#lie-chat-input');
    if (!input) return;
    const msg = input.value.trim();
    if (!msg) return;
    input.value = '';
    st.speeches.push({ seat: 0, name: '我', text: msg });
    lieRefreshSpeechBox();
    const target = (st.turnSeat !== 0 && st.players[st.turnSeat] && !st.players[st.turnSeat].isUser) ? st.turnSeat
      : (st.players.find(p => !p.isUser && p.alive) || {}).seat;
    if (typeof target === 'number') lieRequestSpeech(target, 'user-chat', msg);
  }

  // ========== 欺诈酒馆：结算弹窗 ==========
  function renderLieResultModal() {
    const st = lieGame;
    if (!st || st.phase !== 'ended') return;
    const old = sheet.querySelector('.lie-result-overlay');
    if (old) old.remove();
    const userWon = st.winnerSeat === 0;
    const rows = st.players.map(p => {
      const color = p.isUser ? '#fff' : getCharacterColor(p.name);
      return '<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;color:' + (p.alive ? color : 'var(--ubp-text-3)') + ';">' +
        '<span>' + escapeHtml(p.name) + (p.isUser ? '（我）' : '') + '</span>' +
        '<span>' + (p.alive ? '存活 ❤️×' + Math.max(0, p.hp) : '出局') + ' · 出牌 ' + p.pub.plays + ' · 质疑 ' + p.pub.challenges + '</span></div>';
    }).join('');
    const modal = document.createElement('div');
    modal.className = 'lie-result-overlay';
    modal.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    modal.innerHTML = '<div style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:18px 15px;width:100%;max-width:300px;box-shadow:0 10px 25px rgba(0,0,0,0.5);">' +
      '<div style="text-align:center;font-size:34px;margin-bottom:4px;">' + (userWon ? '🏆' : '💀') + '</div>' +
      '<div style="text-align:center;font-size:16px;font-weight:bold;color:' + (userWon ? '#10B981' : '#EF4444') + ';margin-bottom:4px;">' + (userWon ? '你活到了最后！' : '你出局了…') + '</div>' +
      '<div style="text-align:center;font-size:11.5px;color:var(--ubp-text-2);margin-bottom:10px;">' + escapeHtml(liePlayerResultLine()) + '</div>' +
      '<div style="background:var(--ubp-card-2);border-radius:8px;padding:8px 10px;margin-bottom:10px;">' + rows +
      '<div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:6px;border-top:1px solid var(--ubp-line);padding-top:5px;">第 ' + (st.round || 1) + ' 回合 · 总行动 ' + (st.turnSeq || 0) + ' · 枪内已打出 ' + ((st.gun && st.gun.fired) || 0) + ' 发</div></div>' +
      '<div style="display:flex;gap:8px;"><button data-lie-act="lie-exit" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12.5px;">🚪 退出</button>' +
      '<button data-lie-act="lie-rematch" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:12.5px;background:#7C3AED;">🔄 再来一局</button></div></div>';
    sheet.appendChild(modal);
  }

  // ========== 欺诈酒馆：大厅 / 邀请 / 设置 ==========
  function renderLieLobby() {
    const cfg = loadLieConfig();
    const hasSaved = lieHasSaved();
    let savedInfo = null;
    if (hasSaved) { try { savedInfo = JSON.parse(localStorage.getItem(LIE_SAVE_KEY)); } catch (e) { /* ignore */ } }
    let banner = '';
    if (savedInfo && savedInfo.players) {
      banner = '<div style="background:var(--ubp-card-2, #2a2a30);border:1px solid var(--ubp-line);border-radius:10px;padding:10px 12px;margin-bottom:12px;display:flex;align-items:center;justify-content:space-between;">' +
        '<div style="min-width:0;"><div style="font-size:13px;font-weight:600;color:#7C3AED;">🔖 发现进行中的欺诈酒馆对局</div>' +
        '<div style="font-size:11.5px;color:var(--ubp-text-2);margin-top:2px;">玩家：' + escapeHtml((savedInfo.players || []).map(p => p.name).join('、')) + ' · 第 ' + (savedInfo.round || 1) + ' 回合</div></div>' +
        '<div style="display:flex;gap:6px;flex-shrink:0;"><button data-lie-act="lie-resume" class="ubp-btn primary" style="padding:4px 10px;font-size:12px;background:#7C3AED;">继续</button>' +
        '<button data-lie-act="lie-discard" class="ubp-btn" style="padding:4px 8px;font-size:12px;">放弃</button></div></div>';
    }
    const pn = (cfg.partnerNames || []).filter(Boolean);
    const slots = [0, 1, 2].map(i => {
      const nm = pn[i];
      if (!nm) return '<div style="flex:1;border:1.5px dashed var(--ubp-line);border-radius:8px;padding:8px 4px;text-align:center;font-size:11px;color:var(--ubp-text-3);">空位 ' + (i + 1) + '</div>';
      const av = getCharacterAvatarByName(nm);
      return '<div style="flex:1;border:1.5px solid #7C3AED;border-radius:8px;padding:5px 4px;text-align:center;background:rgba(124,58,237,0.10);">' +
        '<div style="width:28px;height:28px;border-radius:50%;overflow:hidden;background:#7C3AED;margin:0 auto 3px;">' +
        (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:12px;">' + escapeHtml(nm.slice(0, 1)) + '</span>') + '</div>' +
        '<div style="font-size:10.5px;color:var(--ubp-text);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(nm) + '</div></div>';
    }).join('');

    sheet.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex:none;">
        <div style="display:flex;align-items:center;gap:8px;">
          <button data-lie-act="lie-back-tablegame" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="返回桌游大厅">←</button>
          <span style="font-size:17px;font-weight:bold;color:var(--ubp-text);">🃏 欺诈酒馆 · 牌桌大厅</span>
        </div>
        <div style="display:flex;gap:6px;">
          <button data-lie-act="lie-settings" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="设置">⚙️</button>
          <button data-ubp-act="back-setup" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="返回游戏中心">✕</button>
        </div>
      </div>
      <div style="flex:1;overflow-y:auto;padding-right:2px;">
        ${banner}
        <div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:11px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span style="font-size:14px;font-weight:600;color:var(--ubp-text);">👥 邀请 1~3 位角色入座</span>
            <button data-lie-act="lie-invite" class="ubp-btn" style="padding:3px 10px;font-size:12px;">邀请角色</button>
          </div>
          <div style="display:flex;gap:6px;margin-top:9px;">${slots}</div>
          <div style="font-size:11px;color:var(--ubp-text-3);margin-top:7px;line-height:1.6;">① 点击【邀请角色】选择 1~3 位 → ② 点击【开始对局】入座。<br>欺诈酒馆：吹牛出牌 + 共用左轮，被拆穿或质疑失败就要挨枪，最后活着的人获胜。</div>
        </div>
        <div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:11px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <div style="min-width:0;margin-right:10px;">
              <div style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">💬 牌桌角色 AI 陪聊</div>
              <div style="font-size:11px;color:var(--ubp-text-3);margin-top:2px;line-height:1.45;">开启后角色会吹牛、挑衅、吐槽枪运（使用游戏中心配置的 AI）· AI 强度：${cfg.aiLevel === 'strong' ? '强力（蒙特卡洛）' : cfg.aiLevel === 'fast' ? '快速' : '标准'}</div>
            </div>
            <label style="position:relative;display:inline-block;width:42px;height:24px;cursor:pointer;flex:none;">
              <input type="checkbox" id="lie-chat-toggle" ${cfg.aiChat ? 'checked' : ''} style="opacity:0;width:0;height:0;">
              <span style="position:absolute;top:0;left:0;right:0;bottom:0;background:${cfg.aiChat ? '#7C3AED' : '#4b5563'};border-radius:24px;transition:0.3s;">
                <span style="position:absolute;height:18px;width:18px;left:${cfg.aiChat ? '21px' : '3px'};bottom:3px;background:#fff;border-radius:50%;transition:0.3s;"></span>
              </span>
            </label>
          </div>
        </div>
        <button data-lie-act="lie-start" class="ubp-btn primary" style="width:100%;padding:12px;font-size:14px;background:#7C3AED;border:none;margin-bottom:12px;">${pn.length ? '🎮 开始对局（我 + ' + escapeHtml(pn.join(' · ')) + '）' : '🎮 开始对局（未邀请将自动补位）'}</button>
        <details style="font-size:11px;color:var(--ubp-text-3);border-top:1px solid var(--ubp-line);padding-top:8px;">
          <summary style="cursor:pointer;">📖 玩法规则（点击展开）</summary>
          <div style="white-space:pre-wrap;font-size:11.5px;line-height:1.7;background:var(--ubp-card-2);padding:8px;border-radius:6px;margin-top:5px;color:var(--ubp-text-2);">【基础】每人 2 点生命，归零直接出局；每个回合重新发牌：每人 5 张基础牌（牌库共 20 张 = 红/黄/蓝各 6 张 + 2 张万能）+ 最多 3 张道具牌。
【目标颜色】每回合开局时刷新并固定一个目标颜色（红/黄/蓝），左上角可见；不管实际出的是什么牌，宣称的都是当前目标色；万能牌 ⭐ 可当作任意目标色。
【左轮】公用左轮 6 个弹槽，固定 3 实弹 + 3 空弹随机打乱；实弹打光自动换全新枪。中实弹扣 1 血，空弹无事。
【回合】轮到你时：① 质疑上家 或 ② 自己出牌（张数不限，可掺假吹牛，宣称全是目标色）。
【逃离】把手里所有牌出完即视为「逃离本回合」，本回合结束前不再参与质疑与出牌，也不会再被轮转到。
【强制质疑】当只剩 2 名未逃离玩家，且上家已出完所有手牌时，下家只能质疑（不能再出牌或用道具）。
【质疑】翻开上家刚打出的牌：上家说谎 → 上家挨枪；上家没说谎 → 你自己挨枪。
【开枪】不管空弹还是中弹，只要挨枪者没死：立即定新回合目标颜色、所有人重新发牌，并由「被质疑玩家的下一家」开始新一轮出牌。
【道具】（回合内自由使用，用完消失）
　👁️ 偷看：查看任意一名玩家随机 2 张手牌
　🔍 检查：查看枪里下一颗子弹是实弹还是空弹
　🫳 偷牌：偷走别人手里 1 张道具牌
　⏏️ 弹出：把枪里当前这颗子弹直接丢掉
　🔄 转换：翻转当前子弹状态（持续到下家回合结束）
　🔥 连发：下一次开枪多打 1 发
　☠️ 伤害加倍：下一次开枪命中实弹直接扣 2 血
　🔃 反转：反转出牌顺序
【胜负】生命归零淘汰，最后剩下的那名玩家获胜。</div>
        </details>
      </div>
    `;
    const toggle = sheet.querySelector('#lie-chat-toggle');
    if (toggle) toggle.addEventListener('change', () => { const c = loadLieConfig(); c.aiChat = toggle.checked; saveLieConfig(c); renderLieLobby(); });
  }

  function renderLieInviteOverlay(onConfirmed) {
    const cfg = loadLieConfig();
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    let chosen = (cfg.partnerNames || []).filter(n => n && contacts.some(c => isNameMatch(c.name, n))).slice(0, 3);
    if (!chosen.length) for (const c of contacts) { if (chosen.length >= 3) break; if (!chosen.some(n => isNameMatch(n, c.name))) chosen.push(c.name); }
    const ov = document.createElement('div');
    ov.className = 'lie-invite-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:60;background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const renderContent = () => {
      const listHtml = contacts.map(c => {
        const idx = chosen.findIndex(n => isNameMatch(n, c.name));
        const on = idx !== -1;
        const av = c.avatar || getCharacterAvatarByName(c.name);
        return '<div data-lie-pick="' + escapeHtml(c.name).replace(/"/g, '&quot;') + '" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:' + (on ? 'rgba(124,58,237,0.16)' : 'var(--ubp-card-2, #26262a)') + ';border:1.5px solid ' + (on ? '#7C3AED' : 'var(--ubp-line)') + ';">' +
          '<div style="width:36px;height:36px;border-radius:50%;background:#7C3AED;overflow:hidden;flex-shrink:0;">' +
          (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:14px;">' + escapeHtml(c.name.slice(0, 1)) + '</span>') + '</div>' +
          '<div style="flex:1;min-width:0;"><div style="font-size:13.5px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(c.name) + (on ? ' <span style="font-size:11px;color:#7C3AED;">(座位' + (idx + 1) + ')</span>' : '') + '</div>' +
          (c.identity ? '<div style="font-size:11px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;">' + escapeHtml(c.identity) + '</div>' : '') + '</div>' +
          '<span style="font-size:16px;color:#7C3AED;flex-shrink:0;">' + (on ? '✅' : '○') + '</span></div>';
      }).join('');
      ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">' +
        '<span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">👥 邀请角色入座（1~3 位）</span>' +
        '<button data-lie-invite="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
        '<div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">已选 <b style="color:#7C3AED;">' + chosen.length + '</b> / 3 位（含你共 ' + (chosen.length + 1) + ' 人对局）</div>' +
        '<div style="flex:1;overflow-y:auto;padding-right:2px;margin-bottom:8px;">' + (listHtml || '<div style="font-size:12px;color:var(--ubp-text-3);">暂无可用角色（请先在大厅工作台创建自定义角色，或安装数据库本体），请确保瑟瑟数据库已添加角色。</div>') + '</div>' +
        '<div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-lie-invite="confirm" class="ubp-btn primary" style="padding:6px 20px;background:' + (chosen.length ? '#7C3AED' : '#6b7280') + ';font-size:13px;border-radius:6px;">确认邀请</button></div>';
      ov.querySelectorAll('[data-lie-pick]').forEach(el => {
        el.addEventListener('click', () => {
          const name = el.dataset.liePick;
          const i = chosen.findIndex(n => isNameMatch(n, name));
          if (i !== -1) chosen.splice(i, 1);
          else { if (chosen.length >= 3) chosen.shift(); chosen.push(name); }
          renderContent();
        });
      });
      ov.querySelector('[data-lie-invite="close"]')?.addEventListener('click', () => ov.remove());
      ov.querySelector('[data-lie-invite="confirm"]')?.addEventListener('click', () => {
        if (!chosen.length) { showToast('请至少邀请 1 位角色'); return; }
        const c = loadLieConfig();
        c.partnerNames = chosen.slice(0, 3);
        saveLieConfig(c);
        ov.remove();
        if (typeof onConfirmed === 'function') onConfirmed(chosen.slice(0, 3));
        else renderLieLobby();
      });
    };
    renderContent();
    sheet.appendChild(ov);
  }

