    ov.className = 'lie-settings-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:60;background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const renderContent = () => {
      const c = loadLieConfig();
      ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex:none;">' +
