        '<div style="font-size:8.5px;color:var(--ubp-text-3);margin-top:3px;white-space:nowrap;">🏠' + base + ' ✈' + track + ' 🏁' + home + ' 💥' + (p.captured || 0) + '</div>' +
        '</div>';
    }).join('');
  }
  function ludoDiceFaceHTML(v) {
    if (!v) return '<span style="font-size:34px;line-height:1;opacity:.45;">🎲</span>';
    return '<span style="font-size:42px;line-height:1;color:' + (v === 6 ? '#F59E0B' : 'var(--ubp-text)') + ';">' + LUDO_DICE_FACES[v - 1] + '</span>' +
      '<span style="font-size:12px;font-weight:bold;color:var(--ubp-text-2);margin-left:2px;">' + v + '</span>';
  }
  function ludoDiceHTML(st) { return ludoDiceFaceHTML(st.dice); }
  function ludoMoveHint(st, seat, move) {
    const ev = ludoPreviewMove(st, seat, move);
    const parts = [];
    if (move.type === 'takeoff') parts.push('起飞');
    else {
      parts.push('前进 ' + st.dice + ' 格');
      if (move.bounced) parts.push('倒退 ' + (LUDO_FINISH - move.to) + ' 格');
      else if (move.to === LUDO_FINISH) parts.push('到达终点');
    }
    if (ev.flight) parts.push('🛫 飞行 12 格');
    if (ev.captures.length) parts.push('💥 撞子 ×' + ev.captures.length);
    return parts.join(' · ');
  }
  function ludoLogHTML() {
    const st = ludoGame;
    const list = (st.log || []).slice(-40);
    if (!list.length) return '<span style="color:var(--ubp-text-3);">棋局开始…</span>';
    return list.map(function (e) {
      const rowStyle = 'margin:2px 0;color:' + (e.color || 'var(--ubp-text-2)') + ';font-size:11px;line-height:1.45;';
      if (e.seat !== null && e.seat !== undefined && st.players[e.seat]) {
        const pl = st.players[e.seat];
        return '<div style="display:flex;align-items:flex-start;gap:5px;' + rowStyle + '">' +
          '<span style="flex:none;margin-top:1px;">' + chatAvatarHTML(pl.name, !!pl.isUser, 18) + '</span>' +
          '<span style="flex:1;min-width:0;word-break:break-word;">' + escapeHtml(e.text) + '</span></div>';
      }
      return '<div style="' + rowStyle + '">' + escapeHtml(e.text) + '</div>';
    }).join('');
  }

  // ========== 飞行棋：主界面 ==========
  function renderLudoGameUI() {
    if (!ludoGame) { renderLudoLobby(); return; }
    const st = ludoGame;
    const me = st.players[0];
    const isEnded = st.phase === 'ended';
    const myTurn = st.turnSeat === 0 && !isEnded;
    const winner = (st.winnerSeat !== null && st.winnerSeat !== undefined) ? st.players[st.winnerSeat] : null;
    const curP = st.players[st.turnSeat];
    let statusText = '';
    if (isEnded) statusText = winner ? (winner.isUser ? '🎉 你率先把 4 架飞机全部送入终点，获胜！' : '💔 ' + escapeHtml(winner.name) + ' 率先完成 4 架飞机，本局落败') : '本局结束';
    else if (myTurn) {
      if (st.phase === 'roll') statusText = '👉 轮到你：点击【掷骰子】' + (st.sixChain >= 1 ? '（已连掷 ' + st.sixChain + ' 次 6）' : '');
      else if (st.phase === 'select') statusText = '👉 点选高亮飞机 或 点击下方走法（点数 ' + st.dice + '）';
      else if (st.phase === 'moving') statusText = '✈️ 飞机移动中…';
      else statusText = '⏳ 结算中…';
    } else {
      statusText = st.phase === 'select' ? ('⏳ ' + escapeHtml(curP ? curP.name : '') + ' 正在选择飞机…') : ('⏳ 等待 ' + escapeHtml(curP ? curP.name : '') + ' 掷骰…');
    }
    const canRoll = myTurn && st.phase === 'roll' && !st.moving;
    const moveBtns = (myTurn && st.phase === 'select' && st.legalMoves && st.legalMoves.length) ? st.legalMoves.map(function (m, i) {
      return '<button data-ludo-act="ludo-move" data-idx="' + i + '" class="ubp-btn" style="padding:5px 9px;font-size:11.5px;border-radius:6px;">飞机' + (m.plane + 1) + ' · ' + ludoMoveHint(st, 0, m) + '</button>';
    }).join('') : '';
    const chatHTML = st.aiChat ? (
      '<div id="ludo-speech-container" style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:8px;padding:5px 9px;margin-top:5px;flex:none;height:88px;max-height:88px;overflow-y:auto;box-sizing:border-box;">' +
      '<div id="ludo-speech-text" style="font-size:11.5px;line-height:1.5;word-break:break-word;">' + ludoRenderSpeechHTML() + '</div></div>' +
      '<div style="display:flex;gap:6px;margin-top:5px;flex:none;">' +
      '<input id="ludo-chat-input" class="ubp-fieldinput" type="text" placeholder="对棋盘边的角色说点什么…（如：你的骰子是不是灌铅了）" style="flex:1;font-size:12px;padding:4px 8px;border-radius:6px;height:26px;">' +
      '<button data-ludo-act="ludo-send-chat" class="ubp-btn primary" style="padding:0 10px;font-size:12px;height:26px;background:#0EA5E9;flex:none;">发送</button></div>'
    ) : '';
    const prevSpeechBox = sheet.querySelector('#ludo-speech-container');
    const prevLogBox = sheet.querySelector('#ludo-log-scroll');
    const speechAtBottom = !prevSpeechBox || (prevSpeechBox.scrollTop + prevSpeechBox.clientHeight >= prevSpeechBox.scrollHeight - 12);
    const speechScrollTop = prevSpeechBox ? prevSpeechBox.scrollTop : 0;
    const logAtBottom = !prevLogBox || (prevLogBox.scrollTop + prevLogBox.clientHeight >= prevLogBox.scrollHeight - 12);
    const logScrollTop = prevLogBox ? prevLogBox.scrollTop : 0;
    const turnHex = curP ? LUDO_COLOR_HEX[curP.color] : '#888';

    sheet.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;flex:none;">
        <div style="display:flex;align-items:center;gap:6px;min-width:0;">
          <button data-ludo-act="ludo-exit" style="background:none;border:none;font-size:16px;cursor:pointer;color:var(--ubp-text);flex:none;" title="返回飞行棋大厅（自动保存）">←</button>
          <span style="font-size:14.5px;font-weight:bold;color:var(--ubp-text);white-space:nowrap;">✈️ 飞行棋</span>
        </div>
        <div style="display:flex;align-items:center;gap:6px;flex:none;">
          <span style="display:inline-flex;align-items:center;gap:4px;font-size:10.5px;color:var(--ubp-text-2);">我的颜色</span>
          <span style="display:inline-flex;align-items:center;gap:3px;padding:1px 7px;border-radius:999px;background:${LUDO_COLOR_HEX[me.color]}22;border:1.5px solid ${LUDO_COLOR_HEX[me.color]};font-size:10.5px;font-weight:600;color:${LUDO_COLOR_HEX[me.color]};">${LUDO_COLOR_LABEL[me.color]}</span>
        </div>
      </div>

      <div style="display:flex;gap:4px;flex:none;margin-bottom:5px;">${ludoPlayersRowHTML(st)}</div>

      <div style="width:100%;max-width:500px;margin:0 auto 6px;flex:none;">${ludoBoardHTML(st)}</div>

      <div style="display:flex;gap:9px;align-items:center;margin-bottom:6px;flex:none;background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:10px;padding:6px 9px;">
        <div id="ludo-dice-box" style="flex:none;width:52px;text-align:center;">${ludoDiceHTML(st)}</div>
        <div style="flex:1;min-width:0;">
          <div style="font-size:11.5px;font-weight:600;color:${myTurn && !isEnded ? '#22C55E' : 'var(--ubp-text-2)'};line-height:1.4;">${statusText}</div>
          <div style="display:flex;align-items:center;gap:6px;margin-top:5px;">
            <button data-ludo-act="ludo-roll" class="ubp-btn primary" style="padding:6px 14px;font-size:12.5px;background:#0EA5E9;border-radius:6px;${canRoll ? '' : 'opacity:0.45;pointer-events:none;'}">🎲 掷骰子</button>
            <span style="font-size:10px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">当前：<b style="color:${turnHex};">${escapeHtml(curP ? curP.name : '')}</b>（${curP ? LUDO_COLOR_LABEL[curP.color] : ''}色）</span>
          </div>
        </div>
      </div>

      ${moveBtns ? '<div style="display:flex;flex-wrap:wrap;gap:5px;margin-bottom:6px;flex:none;">' + moveBtns + '</div>' : ''}

      <div style="flex:none;display:flex;justify-content:space-between;align-items:center;padding:0 2px;">
        <span style="font-size:10.5px;color:var(--ubp-text-3);">棋局日志</span>
        <span style="font-size:10.5px;color:var(--ubp-text-3);">我：到达 ${ludoFinishedCount(me)}/4 · 击落 ${me.captured || 0}</span>
      </div>
      <div id="ludo-log-scroll" style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:8px;padding:5px 8px;height:72px;max-height:72px;overflow-y:auto;margin-top:3px;flex:none;">
        ${ludoLogHTML()}
      </div>

      ${chatHTML}
    `;

    const newSpeechBox = sheet.querySelector('#ludo-speech-container');
    if (newSpeechBox) newSpeechBox.scrollTop = speechAtBottom ? newSpeechBox.scrollHeight : speechScrollTop;
    const newLogBox = sheet.querySelector('#ludo-log-scroll');
    if (newLogBox) newLogBox.scrollTop = logAtBottom ? newLogBox.scrollHeight : logScrollTop;
    const input = sheet.querySelector('#ludo-chat-input');
    if (input) input.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); ludoHandleUserChat(); } });
  }

  // ========== 飞行棋：结算弹窗 ==========
  function renderLudoResultModal() {
    const st = ludoGame;
    if (!st || st.phase !== 'ended') return;
    const old = sheet.querySelector('.ludo-result-overlay');
    if (old) old.remove();
    const userWon = st.winnerSeat === 0;
    const rows = st.players.map(function (p) {
      const color = p.isUser ? '#fff' : getCharacterColor(p.name);
      const home = ludoFinishedCount(p);
      return '<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;color:' + (p.seat === st.winnerSeat ? '#22C55E' : color) + ';">' +
        '<span>' + escapeHtml(p.name) + '（' + LUDO_COLOR_LABEL[p.color] + '色）' + (p.seat === st.winnerSeat ? ' 🏆' : '') + '</span>' +
        '<span>到达 ' + home + '/4 · 击落 ' + (p.captured || 0) + '</span></div>';
    }).join('');
    const modal = document.createElement('div');
    modal.className = 'ludo-result-overlay';
    modal.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    modal.innerHTML = '<div style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:18px 15px;width:100%;max-width:300px;box-shadow:0 10px 25px rgba(0,0,0,0.5);">' +
      '<div style="text-align:center;font-size:34px;margin-bottom:4px;">' + (userWon ? '🏆' : '💔') + '</div>' +
      '<div style="text-align:center;font-size:16px;font-weight:bold;color:' + (userWon ? '#22C55E' : '#EF4444') + ';margin-bottom:4px;">' + (userWon ? '你赢了！4 架飞机全部到家' : '惜败！对手先完成 4 架飞机') + '</div>' +
      '<div style="text-align:center;font-size:11.5px;color:var(--ubp-text-2);margin-bottom:10px;">' + escapeHtml(ludoPlayerResultLine()) + '</div>' +
      '<div style="background:var(--ubp-card-2);border-radius:8px;padding:8px 10px;margin-bottom:10px;">' + rows +
      '<div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:6px;border-top:1px solid var(--ubp-line);padding-top:5px;">总行动 ' + (st.actionCount || 0) + ' 次 · 共击落 ' + st.players.reduce(function (a, p) { return a + (p.captured || 0); }, 0) + ' 架</div></div>' +
      '<div style="display:flex;gap:8px;"><button data-ludo-act="ludo-exit" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12.5px;">🚪 退出</button>' +
      '<button data-ludo-act="ludo-rematch" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:12.5px;background:#0EA5E9;">🔄 再来一局</button></div></div>';
    sheet.appendChild(modal);
  }

  // ========== 飞行棋：大厅 / 邀请 / 设置 ==========
  const LUDO_RULES_TEXT = '【基础配置】\n' +
    '1. 2~4 人，你先选一种颜色（红/黄/蓝/绿），其余每人分配一种颜色；每人 4 架飞机，初始全部停在己方停机坪。\n' +
    '2. 一颗六面骰，回合制，顺时针轮流；胜利条件：最先把 4 架飞机全部送入终点者获胜。\n' +
    '【回合流程】\n' +
    '1. 掷骰（1~6 随机）；掷出 6：可以把 1 架飞机从基地放到己方起飞点，并额外获得一次掷骰机会，可连续掷骰。\n' +
    '2. 不是 6：基地飞机不能起飞，只能移动已经在跑道上的飞机。\n' +
    '3. 选择一架合法飞机移动对应步数 → 结算落点效果（飞行、撞子）→ 掷出 6 继续掷，否则换下一位。\n' +
    '4. 可选：连续掷出 3 次 6，本次回合直接结束不能行动（默认开启，可在设置关闭）。\n' +
    '【飞行（跳格子）】\n' +
    '棋子停在同色虚线格：直接沿虚线飞到另一端同色格（前进 12 格），中间格子直接跳过；虚线终点若有敌方飞机，依然触发撞子。\n' +
    '【撞子】\n' +
    '移动结束落在普通格：该格敌方飞机直接打回基地；敌方多架叠子 → 全部回基地；落在己方颜色安全格：不能撞击别人；己方飞机可以叠在同一格（迭子），互不影响。\n' +
    '【归家通道】\n' +
    '绕棋盘外圈走完一整圈后进入己方颜色归家通道（5 格）；进入后不能飞行、不能撞人。终点必须刚好掷出剩余步数：点多要往回倒退（例：距终点 2 步掷出 4 → 前进 2 步到终点再后退 2 格）。\n' +
    '【可选规则（设置里切换）】\n' +
    '· 宽松终点：点数大于剩余步数也可直接进终点，不用后退。\n' +
    '· 起飞放宽：掷出 5 或 6 都可以起飞。\n' +
    '· 无三连 6 惩罚：可以无限连续掷 6。';

  function renderLudoLobby() {
