    if (hasSaved) { try { savedInfo = JSON.parse(localStorage.getItem(LUDO_SAVE_KEY)); } catch (e) { /* ignore */ } }
    let banner = '';
    if (savedInfo && savedInfo.players) {
      const turnP = savedInfo.players[savedInfo.turnSeat || 0] || {};
      banner = '<div style="background:var(--ubp-card-2, #2a2a30);border:1px solid var(--ubp-line);border-radius:10px;padding:10px 12px;margin-bottom:12px;display:flex;align-items:center;justify-content:space-between;">' +
        '<div style="min-width:0;"><div style="font-size:13px;font-weight:600;color:#0EA5E9;">🔖 发现进行中的飞行棋对局</div>' +
        '<div style="font-size:11.5px;color:var(--ubp-text-2);margin-top:2px;">玩家：' + escapeHtml((savedInfo.players || []).map(function (p) { return p.name; }).join('、')) + ' · 轮到 ' + escapeHtml(turnP.name || '?') + '</div></div>' +
        '<div style="display:flex;gap:6px;flex-shrink:0;"><button data-ludo-act="ludo-resume" class="ubp-btn primary" style="padding:4px 10px;font-size:12px;background:#0EA5E9;">继续</button>' +
