        (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:12px;">' + escapeHtml(nm.slice(0, 1)) + '</span>') + '</div>' +
        '<div style="font-size:10.5px;color:var(--ubp-text);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(nm) + '</div>' +
        '<div style="font-size:9px;color:' + hex + ';font-weight:600;">' + LUDO_COLOR_LABEL[assign[i + 1]] + '色</div></div>';
