        <div style="display:flex;align-items:center;gap:8px;min-width:0;">
          <button data-ludo-act="ludo-back-tablegame" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);flex:none;" title="返回桌游大厅">←</button>
          <span style="font-size:17px;font-weight:bold;color:var(--ubp-text);white-space:nowrap;">✈️ 飞行棋 · 对局大厅</span>
        </div>
        <div style="display:flex;gap:6px;flex:none;">
          <button data-ludo-act="ludo-settings" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="设置">⚙️</button>
          <button data-ubp-act="back-setup" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="返回游戏中心">✕</button>
