  // ========== 飞行棋：操作分发 ==========
  function handleLudoAction(act, target) {
    if (act === 'ludo-open') {
      if (ludoHasSaved()) ludoResumeSaved();
      else renderLudoLobby();
      return;
    }
    if (act === 'ludo-back-tablegame') { renderTableGameLobby(); return; }
    if (act === 'ludo-invite') { renderLudoInviteOverlay(function (names) { startLudoGame(names); }); return; }
    if (act === 'ludo-settings') { renderLudoSettings(); return; }
    if (act === 'ludo-start') {
      const cfg = loadLudoConfig();
      if (aiChatInviteGate({
        chatOn: cfg.aiChat,
        invited: (cfg.partnerNames || []).filter(Boolean).length,
        label: '飞行棋',
        onInvite: () => renderLudoInviteOverlay(function (names) { startLudoGame(names); }),
        onDisableAndStart: () => { const c2 = loadLudoConfig(); c2.aiChat = false; saveLudoConfig(c2); handleLudoAction('ludo-start', null); }
      })) return;
      startLudoGame(cfg.partnerNames);
      return;
    }
    if (act === 'ludo-resume') { ludoResumeSaved(); return; }
    if (act === 'ludo-discard') { ludoGenCounter++; ludoClearSaved(); renderLudoLobby(); showToast('🗑️ 已放弃进行中的飞行棋对局'); return; }
    if (act === 'ludo-pick-color') {
      const c = loadLudoConfig();
      if (target && target.dataset && LUDO_COLORS.indexOf(target.dataset.color) !== -1) c.userColor = target.dataset.color;
      saveLudoConfig(c);
      renderLudoLobby();
      return;
    }
    if (act === 'ludo-exit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      ludoGenCounter++; // 使进行中的动画/延时回调全部失效，避免退出后又弹回棋盘
      const modal = sheet.querySelector('.ludo-result-overlay');
      if (modal) modal.remove();
      if (ludoAiTimer) { clearTimeout(ludoAiTimer); ludoAiTimer = null; }
      ludoChatBusy = false;
      if (ludoGame) ludoGame.moving = false;
      if (ludoGame && ludoGame.phase !== 'ended') ludoSaveState(); else ludoClearSaved();
      renderLudoLobby();
      return;
    }
    if (act === 'ludo-rematch') {
      const modal = sheet.querySelector('.ludo-result-overlay');
      if (modal) modal.remove();
      const names = ludoGame ? ludoGame.players.filter(function (p) { return !p.isUser; }).map(function (p) { return p.name; }) : [];
      if (aiChatInviteGate({
        chatOn: loadLudoConfig().aiChat,
        invited: names.filter(n2 => !isBuiltinPlayerName(n2)).length,
        label: '飞行棋',
        onInvite: () => renderLudoLobby(),
        onDisableAndStart: () => { const c2 = loadLudoConfig(); c2.aiChat = false; saveLudoConfig(c2); handleLudoAction('ludo-rematch', null); }
      })) return;
      startLudoGame(names);
      return;
    }
    if (act === 'ludo-roll') {
      const st = ludoGame;
      if (!st || st.moving || st.phase !== 'roll' || st.turnSeat !== 0) return;
      const res = ludoRollFor(0);
      ludoAfterRoll(0, res);
      return;
    }
    if (act === 'ludo-move') {
      const st = ludoGame;
      if (!st || st.turnSeat !== 0 || st.phase !== 'select' || st.moving) return;
      const idx = parseInt(target.dataset.idx);
      const m = (st.legalMoves || [])[idx];
      if (!m) return;
      ludoExecuteMove(m);
      return;
    }
    if (act === 'ludo-plane') {
      const st = ludoGame;
      if (!st || st.turnSeat !== 0 || st.phase !== 'select' || st.moving) return;
      const pSeat = parseInt(target.dataset.seat);
      const pIdx = parseInt(target.dataset.idx);
      if (pSeat !== 0) { showToast('还没轮到你，或这不是你的飞机'); return; }
      const m = (st.legalMoves || []).find(function (x) { return x.plane === pIdx; });
      if (!m) { showToast('这架飞机现在不能移动'); return; }
      ludoExecuteMove(m);
      return;
    }
    if (act === 'ludo-send-chat') { ludoHandleUserChat(); return; }
  }
  // __LUDO_UI_END__




