  // ========== 配置 ==========
  function loadRmConfig() {
    const def = {
      aiChat: true, speechInterval: 4, partnerNames: [], aiLevel: 'normal',
      initialMoney: 100000, vehicle: 'car', winMode: 'bankrupt', roundLimit: 30, targetAsset: 400000, auction: true
    };
    try {
      const raw = localStorage.getItem(RM_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (typeof p.aiChat === 'boolean') def.aiChat = p.aiChat;
        if (p.speechInterval) def.speechInterval = parseInt(p.speechInterval) || 4;
        if (Array.isArray(p.partnerNames)) def.partnerNames = p.partnerNames.filter(Boolean).slice(0, 3);
        if (p.aiLevel === 'fast' || p.aiLevel === 'normal' || p.aiLevel === 'strong') def.aiLevel = p.aiLevel;
        if (p.initialMoney >= 50000 && p.initialMoney <= 300000) def.initialMoney = Math.round(p.initialMoney / 10000) * 10000;
        if (p.vehicle === 'walk' || p.vehicle === 'motor' || p.vehicle === 'car') def.vehicle = p.vehicle;
        if (p.winMode === 'bankrupt' || p.winMode === 'rounds' || p.winMode === 'target') def.winMode = p.winMode;
        if (p.roundLimit >= 10 && p.roundLimit <= 100) def.roundLimit = p.roundLimit;
        if (p.targetAsset >= 200000 && p.targetAsset <= 1000000) def.targetAsset = Math.round(p.targetAsset / 50000) * 50000;
        if (typeof p.auction === 'boolean') def.auction = p.auction;
      }
    } catch (e) { /* ignore */ }
    if (def.winMode === 'target' && def.targetAsset < def.initialMoney * 2) def.targetAsset = Math.min(1000000, Math.max(200000, def.initialMoney * 2));
    return def;
  }
