  // ========== 对局状态 ==========
  function rmMakePlayer(seat, name, isUser, avatar, identity) {
    return {
      seat: seat, name: name, isUser: !!isUser, avatar: avatar || '', identity: identity || '牌友',
      money: 0, deposit: 0, points: RM_BASE_POINTS,
      pos: 0, dir: 1,
      lands: [], cards: [], items: [], stocks: [0, 0, 0, 0, 0, 0],
