  function rmBuildPlayers(names) {
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    const players = [rmMakePlayer(0, '我', true, getMainCharAvatar(), '主角')];
    const want = Array.isArray(names) ? names.filter(Boolean).slice(0, 3) : [];
    const used = [];
    const count = Math.max(1, Math.min(3, want.length || 1)); // 与欺诈酒馆一致：邀请几位就几位开局（一位都没邀请则补 1 位内置角色陪玩）
    for (let i = 0; i < count; i++) {
      let c = null;
      const nm = want[i];
      if (nm) c = contacts.find(function (x) { return isNameMatch(x.name, nm); }) || null;
      if (!c) c = contacts.find(function (x) { return !used.some(function (n) { return isNameMatch(n, x.name); }); }) || null;
      if (c) { used.push(c.name); players.push(rmMakePlayer(i + 1, c.name, false, c.avatar || getCharacterAvatarByName(c.name) || '', c.identity || '牌友')); }
      else players.push(rmMakePlayer(i + 1, '牌友' + (i + 1), false, '', '牌友'));
    }
    return players;
  }
  function rmBuildGame(names) {
