  // ========== 基础工具 ==========
  function rmAlivePlayers(st) { return st.players.filter(function (p) { return p && !p.eliminated; }); }
  function rmNextAliveSeat(st, from) {
    const n = st.players.length;
    let s = from;
    for (let i = 0; i < n * 2 + 4; i++) {
      s = (s + 1) % n;
      if (st.players[s] && !st.players[s].eliminated) return s;
    }
    return from;
  }
  function rmFmtMoney(v) {
    const n = Math.round(v);
    if (Math.abs(n) >= 10000) return (n / 10000).toFixed(n % 10000 === 0 ? 0 : 1) + '万';
    return String(n);
  }
  function rmMoneyChangeText(v) { return (v >= 0 ? '+' : '-') + rmFmtMoney(Math.abs(v)); }
  function rmDistance(from, to, dir) {
    let d = (to - from + RM_MAP_LEN) % RM_MAP_LEN;
    if (dir === -1) d = (RM_MAP_LEN - d) % RM_MAP_LEN;
    return d;
  }
  function rmMoveCost(st, p, base) {
    let c = base;
    if (p.god && p.god.name === 'qiongshen') c *= 2;
    return Math.round(c);
  }
  function rmBadPenalty(st, p, base) {
    let c = base;
    if (p.god && p.god.name === 'qiongshen') c *= 2;
    if (p.god && p.god.name === 'sishen') c *= 2;
    return Math.round(c);
  }

  // ========== 资产估值 ==========
  function rmLandValue(st, i) {
    const cell = RM_MAP[i], land = st.lands[i];
    if (!cell || !land) return 0;
    if (cell.type === 'land') return cell.price + land.houses * Math.round(cell.price * 0.8);
    return cell.price + (land.build !== 'none' ? (RM_BIG_BUILDS[land.build].price || 0) : 0);
  }
  function rmStockValue(st, p) { let v = 0; for (let i = 0; i < st.stocks.length; i++) v += p.stocks[i] * st.stocks[i].price; return v; }
  function rmTotalAsset(st, p) {
    let v = p.money + p.deposit + rmStockValue(st, p);
    for (const i of p.lands) v += rmLandValue(st, i);
    for (const c of p.cards) v += (RM_CARDS[c] ? RM_CARDS[c].cost : 0);
    for (const it of p.items) v += (RM_ITEMS[it] ? RM_ITEMS[it].cost : 0);
    for (let i = 0; i < st.companies.length; i++) {
      const comp = st.companies[i];
      if (comp && comp.owner === p.seat) v += RM_MAP[i].price;
    }
    return Math.round(v);
  }

  // ========== 地块街组（连片评估用） ==========
  let RM_STREETS_CACHE = null;
  function rmStreets() {
    if (RM_STREETS_CACHE) return RM_STREETS_CACHE;
    const streets = [];
    let cur = [];
    for (let i = 1; i <= RM_MAP_LEN; i++) {
      const idx = i % RM_MAP_LEN;
      const cell = RM_MAP[idx];
      if (cell && (cell.type === 'land' || cell.type === 'bigland')) cur.push(idx);
      else { if (cur.length >= 2) streets.push(cur); cur = []; }
    }
    if (cur.length >= 2) {
      if (streets.length && (cur[0] === 1 || cur[cur.length - 1] === RM_MAP_LEN - 1)) {
        // 跨 0 点收尾：首段若也是地块则合并
        const first = streets[0];
        if (first[0] === 1) streets[0] = cur.concat(first);
        else streets.push(cur);
      } else streets.push(cur);
    }
    RM_STREETS_CACHE = streets.filter(function (s) { return s.length >= 2; });
    return RM_STREETS_CACHE;
  }
  function rmStreetOf(idx) {
    const streets = rmStreets();
    for (const s of streets) if (s.indexOf(idx) !== -1) return s;
    return [idx];
  }

  // ========== 落点评分（AI 用：无主地租金基数≈地租，已含 1 层） ==========
  function rmRent(st, i) {
    const cell = RM_MAP[i], land = st.lands[i];
    if (!cell || !land || land.owner < 0) return 0;
    let rent;
    if (cell.type === 'land') {
      rent = Math.round(cell.rent * rmHouseMult(Math.max(1, land.houses)));
      // 整条街加成：同一条街地块全归同一业主 → 租金 ×2
      const street = rmStreetOf(i);
      if (street.length >= 2 && street.every(function (x) { return st.lands[x] && st.lands[x].owner === land.owner; })) rent *= 2;
      return rent;
    }
    // 大商业地
    if (land.build === 'mall') return Math.round(cell.rent * rmHouseMult(5) * 3);
    if (land.build === 'hotel' || land.build === 'gas' || land.build === 'lab' || land.build === 'park') return 0;
    return Math.round(cell.rent * rmHouseMult(5));
  }

  // ========== 资金收支（自动破产变卖） ==========
  function rmCheckTargetWin(st) {
    if (st.winMode !== 'target' || (st.winnerSeat !== null && st.winnerSeat !== undefined)) return;
    for (const p of rmAlivePlayers(st)) {
      if (rmTotalAsset(st, p) >= st.targetAsset) { st.winnerSeat = p.seat; return; }
    }
  }
  function rmEarn(st, p, amount, why) {
    if (!p || p.eliminated || !amount) return;
    p.money += Math.round(amount);
    st.actionCount++;
    rmCheckTargetWin(st);
  }
  // 强制收费；返回 {paid, bankrupt}。ctx: {creditorSeat, kind, allowBankrupt:true}
  function rmCharge(st, p, amount, ctx) {
    ctx = ctx || {};
    amount = Math.max(0, Math.round(amount));
    if (!amount || p.eliminated) return { paid: 0, bankrupt: false };
    if (p.money < amount) rmRaiseCash(st, p, amount, ctx);
    const can = Math.min(p.money, amount);
    p.money -= can;
    st.actionCount++;
    if (ctx.creditorSeat !== undefined && ctx.creditorSeat !== null) {
      const cp = st.players[ctx.creditorSeat];
      if (cp && !cp.eliminated) cp.money += can;
    }
    if (can < amount) { rmGoBankrupt(st, p, ctx); return { paid: can, bankrupt: true }; }
    return { paid: can, bankrupt: false };
  }
  // 变卖资产凑钱：股票 → 卡片 → 道具 → 房屋 → 土地（75 折）
  function rmRaiseCash(st, p, need, ctx) {
    let guard = 0;
    while (p.money < need && guard++ < 60) {
      // 1) 卖股票（市值最高的先卖）
      let bi = -1, bv = 0;
      for (let i = 0; i < st.stocks.length; i++) {
        const v = p.stocks[i] * st.stocks[i].price;
        if (v > bv) { bv = v; bi = i; }
      }
      if (bi !== -1 && bv > 0) {
        const shares = p.stocks[bi];
        const cashNeed = need - p.money;
        const sellShares = Math.min(shares, Math.max(1, Math.ceil(cashNeed / st.stocks[bi].price)));
        p.stocks[bi] -= sellShares;
        p.money += sellShares * st.stocks[bi].price;
        rmLog(st, p.name + ' 被迫卖出 ' + st.stocks[bi].name + ' ×' + sellShares + '，套现 ' + rmFmtMoney(sellShares * st.stocks[bi].price), '#9CA3AF', { seat: p.seat, kind: 'money' });
        continue;
      }
      // 2) 卖卡片 / 道具（8 折）
      if (p.cards.length) {
        const c = p.cards.shift();
        const v = Math.round((RM_CARDS[c] ? RM_CARDS[c].cost : 10) * 0.8);
        p.money += v;
        rmLog(st, p.name + ' 被迫贱卖卡片【' + (RM_CARDS[c] ? RM_CARDS[c].name : c) + '】（+' + rmFmtMoney(v) + '）', '#9CA3AF', { seat: p.seat, kind: 'money' });
        continue;
      }
      if (p.items.length) {
        const it = p.items.shift();
        const v = Math.round((RM_ITEMS[it] ? RM_ITEMS[it].cost : 10) * 0.8);
        p.money += v;
        rmLog(st, p.name + ' 被迫贱卖道具【' + (RM_ITEMS[it] ? RM_ITEMS[it].name : it) + '】（+' + rmFmtMoney(v) + '）', '#9CA3AF', { seat: p.seat, kind: 'money' });
        continue;
      }
      // 3) 卖房屋（最便宜的先）
      let hi = -1, hv = Infinity;
      for (const i of p.lands) {
        const cell = RM_MAP[i], land = st.lands[i];
        if (cell.type === 'land' && land.houses > 0) {
          const v = Math.round(cell.price * 0.8);
          if (v < hv) { hv = v; hi = i; }
        }
      }
      if (hi !== -1) {
        const land = st.lands[hi];
        land.houses--;
        land.invested = Math.max(0, land.invested - Math.round(RM_MAP[hi].price * 0.8));
        p.money += Math.round(hv * 0.75);
        rmLog(st, p.name + ' 被迫拆掉【' + RM_MAP[hi].name + '】1 层房屋（+' + rmFmtMoney(hv * 0.75) + '）', '#9CA3AF', { seat: p.seat, kind: 'money' });
        continue;
      }
      // 4) 卖土地（最便宜的先）
      let li = -1, lv = Infinity;
      for (const i of p.lands) {
        const v = rmLandValue(st, i);
        if (v < lv) { lv = v; li = i; }
      }
      if (li !== -1) {
        const land = st.lands[li];
        const sell = Math.round(rmLandValue(st, li) * 0.75);
        land.owner = -1; land.houses = 0; land.build = 'none'; land.invested = 0; land.seized = false;
        p.lands.splice(p.lands.indexOf(li), 1);
        p.money += sell;
        rmLog(st, p.name + ' 被迫贱卖土地【' + RM_MAP[li].name + '】（+' + rmFmtMoney(sell) + '）', '#9CA3AF', { seat: p.seat, kind: 'money' });
        continue;
      }
      break; // 没东西可卖了
    }
  }
  // 破产结算：资产移交债主或拍卖释放
  function rmGoBankrupt(st, p, ctx) {
    ctx = ctx || {};
    p.eliminated = true;
    const creditor = (ctx.creditorSeat !== undefined && ctx.creditorSeat !== null) ? st.players[ctx.creditorSeat] : null;
    if (creditor && !creditor.eliminated) {
      // 土地移交债主（含房屋），现金剩余归债主
      for (const i of p.lands.slice()) {
        const land = st.lands[i];
        land.owner = creditor.seat;
        land.seized = false;
        creditor.lands.push(i);
      }
      creditor.money += Math.max(0, p.money);
      rmLog(st, '💀 ' + p.name + ' 破产出局！名下土地与现金全部移交债主 ' + creditor.name, '#EF4444', { seat: p.seat, kind: 'end' });
    } else {
      // 欠银行：土地全部释放为无主
      for (const i of p.lands.slice()) {
        const land = st.lands[i];
        land.owner = -1; land.houses = 0; land.build = 'none'; land.invested = 0; land.seized = false;
      }
      rmLog(st, '💀 ' + p.name + ' 破产出局！名下土地被银行收回重新待售', '#EF4444', { seat: p.seat, kind: 'end' });
    }
    p.lands = []; p.cards = []; p.items = []; p.stocks = p.stocks.map(function () { return 0; });
    p.money = 0; p.deposit = 0;
    // 清掉该玩家放的路障等地雷
    for (const k of Object.keys(st.cellEffects || {})) {
      st.cellEffects[k] = (st.cellEffects[k] || []).filter(function (e) { return e.bySeat !== p.seat; });
      if (!st.cellEffects[k].length) delete st.cellEffects[k];
    }
    // 胜负判定
    const alive = rmAlivePlayers(st);
    if (alive.length <= 1) st.winnerSeat = alive.length ? alive[0].seat : null;
  }
  function rmCheckGameEnd(st) {
    if (st.winnerSeat !== null && st.winnerSeat !== undefined) return;
    const alive = rmAlivePlayers(st);
    if (alive.length <= 1) { st.winnerSeat = alive.length ? alive[0].seat : null; return; }
    if (st.winMode === 'rounds' && st.round > st.roundLimit) {
      let best = null, bv = -1;
      for (const p of alive) { const v = rmTotalAsset(st, p); if (v > bv) { bv = v; best = p; } }
      st.winnerSeat = best ? best.seat : null;
      return;
    }
    rmCheckTargetWin(st);
  }

  // ========== 神明系统 ==========
  function rmGodAttach(st, p, godKey, source) {
    if (!RM_GODS[godKey] || p.eliminated) return;
    p.god = { name: godKey, turns: 2 + Math.floor(Math.random() * 2) }; // 2~3 回合
    rmLog(st, (RM_GODS[godKey].good ? '✨ ' : '🌩️ ') + p.name + ' 被【' + RM_GODS[godKey].name + '】附身 ' + p.god.turns + ' 回合（' + (source || '命运') + '）', RM_GODS[godKey].good ? '#F59E0B' : '#EF4444', { seat: p.seat, kind: 'god' });
  }
  function rmGodDismiss(st, p, why) {
    if (!p.god) return false;
    rmLog(st, '👋 ' + p.name + ' 送走了【' + RM_GODS[p.god.name].name + '】' + (why ? '（' + why + '）' : ''), '#9CA3AF', { seat: p.seat, kind: 'god' });
    p.god = null;
    return true;
  }
  function rmNearestGodCell(st, p) {
    let best = null, bd = Infinity;
    for (const k of Object.keys(st.boardGods || {})) {
      const cell = parseInt(k);
      const d = rmDistance(p.pos, cell, p.dir);
      if (d < bd) { bd = d; best = cell; }
    }
    return best;
  }

  // ========== 机会 / 命运 ==========
  function rmDrawCard(st, p) {
    const c = RM_CARD_KEYS[Math.floor(Math.random() * RM_CARD_KEYS.length)];
    if (p.cards.length < 8) { p.cards.push(c); return c; }
    return null;
  }
  function rmDrawItem(st, p) {
    const it = RM_ITEM_KEYS[Math.floor(Math.random() * RM_ITEM_KEYS.length)];
    if (p.items.length < 8) { p.items.push(it); return it; }
    return null;
  }
  function rmFortuneEvents(kind) {
    const good = [
      { text: '天降横财：获得 12000', run: function (st, p) { rmEarn(st, p, 12000); } },
      { text: '继承远方亲戚遗产：获得 30000', run: function (st, p) { rmEarn(st, p, 30000); } },
      { text: '存款利息：银行存款 +8%', run: function (st, p) { if (p.deposit > 0) { const v = Math.round(p.deposit * 0.08); p.deposit += v; } else rmEarn(st, p, 5000); } },
      { text: '遇到财神！', god: 'caishen' },
      { text: '遇到福神！', god: 'fushen' },
      { text: '土地公显灵！', god: 'tugong', rare: true },
      { text: '捡到一张随机卡片', run: function (st, p) { const c = rmDrawCard(st, p); if (c) rmLog(st, '🃏 ' + p.name + ' 获得卡片【' + RM_CARDS[c].name + '】', '#A855F7', { seat: p.seat, kind: 'card' }); } },
      { text: '捡到一个随机道具', run: function (st, p) { const it = rmDrawItem(st, p); if (it) rmLog(st, '🎁 ' + p.name + ' 获得道具【' + RM_ITEMS[it].name + '】', '#A855F7', { seat: p.seat, kind: 'item' }); } },
      { text: '股市飘红：随机一只股票大涨 18%', run: function (st, p) { const i = Math.floor(Math.random() * st.stocks.length); rmStockAdjust(st, i, 0.18); } },
      { text: '人缘爆棚：其他玩家各送你 4000 红包', run: function (st, p) { for (const op of rmAlivePlayers(st)) { if (op.seat !== p.seat) { const r = rmCharge(st, op, 4000, { kind: 'gift' }); p.money += r.paid; } } } }
    ];
    const bad = [
      { text: '钱包丢失：损失 8000', run: function (st, p) { rmCharge(st, p, rmBadPenalty(st, p, 8000), { kind: 'fortune' }); } },
      { text: '遭遇抢劫：损失 15000', run: function (st, p) { rmCharge(st, p, rmBadPenalty(st, p, 15000), { kind: 'fortune' }); } },
      { text: '税务稽查：按总资产 6% 罚款', run: function (st, p) { rmCharge(st, p, rmBadPenalty(st, p, rmTotalAsset(st, p) * 0.06), { kind: 'tax' }); } },
      { text: '地雷事故：损失 10000', run: function (st, p) { rmCharge(st, p, rmBadPenalty(st, p, 10000), { kind: 'fortune' }); } },
      { text: '股市暴跌：随机一只股票大跌 18%', run: function (st, p) { const i = Math.floor(Math.random() * st.stocks.length); rmStockAdjust(st, i, -0.18); } },
      { text: '遇到穷神…', god: 'qiongshen' },
      { text: '遇到衰神…', god: 'shuaishen' },
      { text: '遇到死神！！', god: 'sishen', rare: true },
      { text: '意外受伤：住院 2 回合', run: function (st, p) { rmHospitalize(st, p, 2, '命运'); } },
      { text: '被冤入狱：入狱 2 回合', run: function (st, p) { rmImprison(st, p, 2, '命运'); } }
    ];
    return kind === 'chance' ? { good: good, bad: bad } : { good: good, bad: bad };
  }
  function rmDrawFortune(st, p, kind) {
    const cellName = kind === 'chance' ? '机会' : '命运';
    const pool = rmFortuneEvents(kind);
    let badBias = 1;
    if (p.god && p.god.name === 'shuaishen') badBias = 3;
    const goodW = pool.good.length, badW = pool.bad.length * badBias;
    const total = goodW + badW;
    let r = Math.random() * total;
    let ev = null, isBad = false;
    if (r < goodW) ev = pool.good[Math.floor(r)];
    else { isBad = true; r -= goodW; ev = pool.bad[Math.floor(r / badBias)]; }
    if (ev.rare && Math.random() < 0.75) { // 稀有事件加权：75% 重抽
      r = Math.random() * (goodW + badW);
      ev = r < goodW ? pool.good[Math.floor(r)] : pool.bad[Math.floor((r - goodW) / badBias)];
      isBad = r >= goodW;
    }
    rmLog(st, '🎴 ' + p.name + ' 抽到【' + cellName + '】：' + ev.text, isBad ? '#EF4444' : '#22C55E', { seat: p.seat, kind: 'fortune' });
    if (ev.god) {
      st.boardGods[p.pos] = ev.god;
      rmGodAttach(st, p, ev.god, cellName);
      delete st.boardGods[p.pos];
    } else if (ev.run) {
      ev.run(st, p);
    }
  }

  // ========== 医院 / 监狱 ==========
  function rmHospitalize(st, p, turns, why) {
    if (p.eliminated) return;
    // 嫁祸卡：坏事转嫁
    if (rmTryDeflect(st, p, { type: 'hospital', turns: turns, why: why })) return;
    p.hospital = Math.max(p.hospital, turns);
    rmLog(st, '🏥 ' + p.name + ' 住院 ' + turns + ' 回合（' + (why || '') + '）', '#EF4444', { seat: p.seat, kind: 'status' });
  }
  function rmImprison(st, p, turns, why, bySeat) {
    if (p.eliminated) return;
    // 免罪卡
    const mi = p.cards.indexOf('mianzui');
    if (mi !== -1) {
      p.cards.splice(mi, 1);
      rmLog(st, '🛡️ ' + p.name + ' 使用【免罪卡】抵挡了入狱（' + (why || '') + '）', '#22C55E', { seat: p.seat, kind: 'card' });
      rmTryRevenge(st, p, bySeat);
      return;
    }
    if (rmTryDeflect(st, p, { type: 'prison', turns: turns, why: why, bySeat: bySeat })) return;
    p.prison = Math.max(p.prison, turns);
    rmLog(st, '🚓 ' + p.name + ' 入狱 ' + turns + ' 回合（' + (why || '') + '，期间不能收租金）', '#EF4444', { seat: p.seat, kind: 'status' });
    rmTryRevenge(st, p, bySeat);
  }
  function rmTryRevenge(st, victim, bySeat) {
    if (bySeat === undefined || bySeat === null || bySeat === victim.seat) return;
    const vi = victim.cards.indexOf('fuchou');
    if (vi === -1) return;
    const atk = st.players[bySeat];
    if (!atk || atk.eliminated) return;
    victim.cards.splice(vi, 1);
    if (atk.prison <= 0) {
      atk.prison = 2;
      rmLog(st, '🗡️ ' + victim.name + ' 触发【复仇卡】：' + atk.name + ' 一起入狱 2 回合！', '#EF4444', { seat: victim.seat, kind: 'card' });
    }
  }
  function rmTryDeflect(st, p, bad) {
    const ji = p.cards.indexOf('jiahuo');
    if (ji === -1) return false;
    // 转嫁给最富的其他存活玩家
    let target = null, bv = -1;
    for (const op of rmAlivePlayers(st)) {
      if (op.seat === p.seat) continue;
      const v = rmTotalAsset(st, op);
      if (v > bv) { bv = v; target = op; }
    }
    if (!target) return false;
    p.cards.splice(ji, 1);
    rmLog(st, '🎭 ' + p.name + ' 触发【嫁祸卡】：坏事转嫁给 ' + target.name + '！', '#F59E0B', { seat: p.seat, kind: 'card' });
    const saved = target.cards.indexOf('jiahuo');
    if (saved !== -1) target.cards.splice(saved, 1); // 防止无限转嫁链
    if (bad.type === 'hospital') { target.hospital = Math.max(target.hospital, bad.turns); rmLog(st, '🏥 ' + target.name + ' 被嫁祸住院 ' + bad.turns + ' 回合', '#EF4444', { seat: target.seat, kind: 'status' }); }
    else if (bad.type === 'prison') { target.prison = Math.max(target.prison, bad.turns); rmLog(st, '🚓 ' + target.name + ' 被嫁祸入狱 ' + bad.turns + ' 回合', '#EF4444', { seat: target.seat, kind: 'status' }); }
    else if (bad.type === 'money') { rmCharge(st, target, bad.amount, { kind: bad.why || 'deflect' }); }
    return true;
  }

  // ========== 股市 ==========
  function rmStockAdjust(st, i, pct, why) {
    const s = st.stocks[i];
    if (!s) return;
    const old = s.price;
    s.price = Math.max(20, Math.min(600, Math.round(s.price * (1 + pct))));
    rmLog(st, (pct >= 0 ? '📈 ' : '📉 ') + s.name + (why ? '（' + why + '）' : '') + '：' + old + ' → ' + s.price + '（' + (pct >= 0 ? '+' : '') + Math.round(pct * 100) + '%）', pct >= 0 ? '#22C55E' : '#EF4444', { kind: 'stock' });
  }
  function rmStockDrift(st) {
    for (let i = 0; i < st.stocks.length; i++) {
      const s = st.stocks[i];
      const drift = (Math.random() - 0.5) * 0.08;
      s.price = Math.max(20, Math.min(600, Math.round(s.price * (1 + drift))));
    }
  }
  function rmBuyStock(st, p, i, shares) {
    const s = st.stocks[i];
    const cost = s.price * shares;
    if (p.money < cost) return { ok: false, msg: '现金不足' };
    p.money -= cost; p.stocks[i] += shares;
    rmLog(st, '📊 ' + p.name + ' 买入 ' + s.name + ' ×' + shares + '（-' + rmFmtMoney(cost) + '）', '#0EA5E9', { seat: p.seat, kind: 'stock' });
    return { ok: true };
  }
  function rmSellStock(st, p, i, shares) {
    const s = st.stocks[i];
    shares = Math.min(shares, p.stocks[i]);
    if (!shares) return { ok: false, msg: '没有持仓' };
    p.stocks[i] -= shares;
    const gain = s.price * shares;
    p.money += gain;
    rmLog(st, '📊 ' + p.name + ' 卖出 ' + s.name + ' ×' + shares + '（+' + rmFmtMoney(gain) + '）', '#0EA5E9', { seat: p.seat, kind: 'stock' });
    rmCheckTargetWin(st);
    return { ok: true };
  }

  // ========== 公司 ==========
  function rmCompanyFee(st, i, payer) {
    const cell = RM_MAP[i], comp = st.companies[i];
    if (!comp || comp.owner < 0) return 0;
    const owner = st.players[comp.owner];
    if (!owner || owner.eliminated) return 0;
    if (owner.prison > 0) return 0;
    const seats = owner.lands.length; // 董事长地盘越多收费越狠
    return Math.round(cell.fee * (1 + 0.25 * Math.min(8, seats)));
  }
  // 每回合公司分红 + 研究所研发（回合轮转时调用）
  function rmRoundStartEffects(st) {
    for (let i = 0; i < st.companies.length; i++) {
      const comp = st.companies[i];
      if (!comp || comp.owner < 0) continue;
      const owner = st.players[comp.owner];
      if (!owner || owner.eliminated || owner.prison > 0) continue;
      const div = Math.round(RM_MAP[i].fee * 0.3);
      owner.money += div;
      rmLog(st, '🏢 ' + owner.name + ' 获得【' + RM_MAP[i].name + '】分红 +' + rmFmtMoney(div), '#22C55E', { seat: owner.seat, kind: 'money' });
    }
    for (let i = 0; i < RM_MAP_LEN; i++) {
      const cell = RM_MAP[i], land = st.lands[i];
      if (cell.type !== 'bigland' || !land || land.build !== 'lab' || land.owner < 0) continue;
      const owner = st.players[land.owner];
      if (!owner || owner.eliminated || owner.prison > 0 || owner.items.length >= 3) continue; // 研究所最多囤 3 个道具
      const it = rmDrawItem(st, owner);
      if (it) rmLog(st, '🔬 ' + owner.name + ' 的研究所研发出【' + RM_ITEMS[it].name + '】', '#A855F7', { seat: owner.seat, kind: 'item' });
    }
    rmStockDrift(st);
    // 银行存款利息（每轮 1%）
    for (const p of rmAlivePlayers(st)) {
      if (p.deposit > 0) p.deposit = Math.round(p.deposit * 1.01);
    }
  }

  // ========== 格子路过结算（每走 1 格调用；返回是否被路障拦停） ==========
  function rmCellPass(st, p, cell) {
    if (p.eliminated) return { stopped: false };
    // 起点奖金
    if (cell === 0) {
      let bonus = RM_START_BONUS;
      if (p.god && p.god.name === 'caishen') bonus *= 2;
      if (p.god && p.god.name === 'qiongshen') bonus = Math.round(bonus / 2);
      p.money += bonus;
      rmLog(st, '🏁 ' + p.name + ' 路过起点，领取奖金 +' + rmFmtMoney(bonus), '#22C55E', { seat: p.seat, kind: 'money' });
      rmCheckTargetWin(st);
    }
    // 空地财神捡钱
    const cellDef = RM_MAP[cell];
    if (cellDef && (cellDef.type === 'land' || cellDef.type === 'bigland') && st.lands[cell] && st.lands[cell].owner < 0 && p.god && p.god.name === 'caishen') {
      p.money += 1500;
      rmLog(st, '💰 财神显灵：' + p.name + ' 路过空地捡到 1500', '#F59E0B', { seat: p.seat, kind: 'god' });
    }
    // 掉落现金
    const mk = String(cell);
    if (st.cellMoney[mk] > 0) {
      let v = st.cellMoney[mk];
      if (p.god && p.god.name === 'caishen') v *= 2;
      if (p.god && p.god.name === 'qiongshen') v = Math.round(v / 2);
      p.money += v;
      rmLog(st, '💵 ' + p.name + ' 捡到地上现金 +' + rmFmtMoney(v), '#22C55E', { seat: p.seat, kind: 'money' });
      delete st.cellMoney[mk];
      rmCheckTargetWin(st);
    }
    // 格子道具效果
    const fx = (st.cellEffects[mk] || []).slice();
    for (const e of fx) {
      if (e.type === 'zhadan') {
        rmRemoveEffect(st, cell, e);
        rmExplode(st, cell, e.bySeat, p);
      } else if (e.type === 'dilei') {
        rmRemoveEffect(st, cell, e);
        const amt = rmBadPenalty(st, p, 10000);
        rmLog(st, '💣 ' + p.name + ' 踩到地雷！损失 ' + rmFmtMoney(amt) + ' 并住院 2 回合', '#EF4444', { seat: p.seat, kind: 'item' });
        rmCharge(st, p, amt, { kind: 'mine' });
        if (!p.eliminated) rmHospitalize(st, p, 2, '地雷炸伤');
      } else if (e.type === 'luzhang') {
        rmRemoveEffect(st, cell, e);
        rmLog(st, '🚧 ' + p.name + ' 踩到路障，被迫停下！', '#F59E0B', { seat: p.seat, kind: 'item' });
        return { stopped: true };
      }
    }
    return { stopped: false };
  }
  function rmRemoveEffect(st, cell, eff) {
    const mk = String(cell);
    st.cellEffects[mk] = (st.cellEffects[mk] || []).filter(function (x) { return x !== eff; });
    if (!st.cellEffects[mk].length) delete st.cellEffects[mk];
  }
  function rmExplode(st, centerCell, bySeat, trigger) {
    rmLog(st, '💥 炸弹在【' + RM_MAP[centerCell].name + '】爆炸！', '#EF4444', { seat: trigger ? trigger.seat : null, kind: 'item' });
    for (let d = -1; d <= 1; d++) {
      const idx = (centerCell + d + RM_MAP_LEN) % RM_MAP_LEN;
      const cell = RM_MAP[idx], land = st.lands[idx];
      if (!land) continue;
      if (cell.type === 'land' && land.houses > 0) {
        const lost = Math.min(2, land.houses);
        land.houses -= lost;
        rmLog(st, '　🏚️ 【' + cell.name + '】被炸毁 ' + lost + ' 层房屋（剩 ' + land.houses + ' 层）', '#EF4444', { kind: 'item' });
      } else if (cell.type === 'bigland' && land.build !== 'none') {
        rmLog(st, '　🏚️ 【' + cell.name + '】的【' + RM_BIG_BUILDS[land.build].name + '】被炸毁', '#EF4444', { kind: 'item' });
        land.build = 'none';
      }
    }
  }

  // ========== 骰子与移动 ==========
  function rmRollDice(st, p, count, remoteValue) {
    let dice = [];
    if (remoteValue) dice = [remoteValue];
    else if (p.turtleTurns > 0) dice = [1];
    else {
      const n = Math.max(1, Math.min(3, count || 1));
      for (let i = 0; i < n; i++) dice.push(1 + Math.floor(Math.random() * 6));
    }
    if (p.turtleTurns > 0) p.turtleTurns--;
    st.dice = dice;
    st.actionCount++;
    return dice;
  }
  // 移动全部步数并逐步结算路过效果；返回经过的格子序列（供动画）
  function rmMoveSteps(st, p, steps) {
    const path = [];
    for (let i = 0; i < steps; i++) {
      p.pos = (p.pos + p.dir + RM_MAP_LEN) % RM_MAP_LEN;
      path.push(p.pos);
      const r = rmCellPass(st, p, p.pos);
      if (r.stopped) break;
    }
    return path;
  }

  // ========== 落点结算（返回 pending 或 null） ==========
  function rmLandingResolve(st, p) {
    const idx = p.pos;
    const cell = RM_MAP[idx];
    if (!cell || p.eliminated) return null;
    // 大商业地的第二格：定位主格
    let landIdx = idx;
    if (cell.type === 'bigland' && cell.span === 2 && st.lands[idx] && st.lands[idx].owner === undefined) landIdx = idx;
    if (cell.type === 'land' || cell.type === 'bigland') return rmLandLanding(st, p, landIdx);
    switch (cell.type) {
      case 'start': return null;
      case 'chance': rmDrawFortune(st, p, 'chance'); return null;
      case 'destiny': rmDrawFortune(st, p, 'destiny'); return null;
      case 'bank': {
        if (p.money > 0) {
          p.deposit += p.money;
          rmLog(st, '🏦 ' + p.name + ' 把全部现金 ' + rmFmtMoney(p.money) + ' 存入银行（每轮 +1% 利息）', '#0EA5E9', { seat: p.seat, kind: 'money' });
          p.money = 0;
        } else rmLog(st, '🏦 ' + p.name + ' 路过银行，口袋空空', '#9CA3AF', { seat: p.seat, kind: 'money' });
        return null;
      }
      case 'tax': {
        const base = Math.round(rmTotalAsset(st, p) * 0.05 + 3000);
        const amt = rmMoveCost(st, p, base);
        rmLog(st, '🏛️ ' + p.name + ' 踩到税务局，缴税 -' + rmFmtMoney(amt), '#EF4444', { seat: p.seat, kind: 'money' });
        if (p.god && p.god.name === 'fushen') { rmLog(st, '🧧 福神显灵：' + p.name + ' 免除本次缴税', '#F59E0B', { seat: p.seat, kind: 'god' }); return null; }
        rmCharge(st, p, amt, { kind: 'tax' });
        return null;
      }
      case 'prison': rmLog(st, '🚔 ' + p.name + ' 路过监狱参观了一下', '#9CA3AF', { seat: p.seat, kind: 'info' }); return null;
      case 'hospital': rmLog(st, '🏥 ' + p.name + ' 路过医院，做了个免费体检', '#9CA3AF', { seat: p.seat, kind: 'info' }); return null;
      case 'shop': return { type: 'shop' };
      case 'stock': return { type: 'stock' };
      case 'company': {
        const comp = st.companies[idx];
        if (comp.owner < 0) return { type: 'companyBuy', cell: idx, price: cell.price };
        if (comp.owner === p.seat) return null;
        const fee = rmCompanyFee(st, idx, p);
        if (fee > 0) {
          if (p.god && p.god.name === 'caishen') { rmLog(st, '💰 财神显灵：' + p.name + ' 免交【' + cell.name + '】企业费', '#F59E0B', { seat: p.seat, kind: 'god' }); return null; }
          const amt = rmMoveCost(st, p, fee);
          rmLog(st, '🏢 ' + p.name + ' 踩到 ' + st.players[comp.owner].name + ' 的【' + cell.name + '】，支付企业费 -' + rmFmtMoney(amt), '#EF4444', { seat: p.seat, kind: 'money' });
          rmCharge(st, p, amt, { kind: 'company', creditorSeat: comp.owner });
        }
        return null;
      }
    }
    return null;
  }
  function rmLandLanding(st, p, idx) {
    const cell = RM_MAP[idx], land = st.lands[idx];
    if (land.owner < 0) {
      // 无主地：衰神不能买
      if (p.god && p.god.name === 'shuaishen') { rmLog(st, '🌧️ 衰神缠身：' + p.name + ' 不能买地', '#EF4444', { seat: p.seat, kind: 'god' }); return null; }
      return { type: 'buy', land: idx, price: cell.price };
    }
    if (land.owner === p.seat) {
      if (cell.type === 'land') {
        if (land.houses >= RM_MAX_HOUSES) return null;
        if (p.god && p.god.name === 'shuaishen') { rmLog(st, '🌧️ 衰神缠身：' + p.name + ' 不能盖房', '#EF4444', { seat: p.seat, kind: 'god' }); return null; }
        const cost = Math.round(cell.price * 0.8);
        return { type: 'upgrade', land: idx, cost: cost, houses: land.houses };
      }
      // 大商业地：未建特殊建筑 → 5 选 1
      if (cell.type === 'bigland' && land.build === 'none') return { type: 'bigBuild', land: idx };
      return null;
    }
    // 别人的地
    const owner = st.players[land.owner];
    if (!owner || owner.eliminated) return null;
    // 土地公：强制拿地
    if (p.god && p.god.name === 'tugong') {
      land.owner = p.seat;
      land.seized = false;
      p.lands.push(idx);
      const oi = owner.lands.indexOf(idx);
      if (oi !== -1) owner.lands.splice(oi, 1);
      rmLog(st, '⛰️ 土地公显灵！' + p.name + ' 把【' + cell.name + '】从 ' + owner.name + ' 手里直接抢走！', '#F59E0B', { seat: p.seat, kind: 'god' });
      return null;
    }
    // 财神：免租金
    if (p.god && p.god.name === 'caishen') { rmLog(st, '💰 财神显灵：' + p.name + ' 踩到 ' + owner.name + ' 的地但免交租金', '#F59E0B', { seat: p.seat, kind: 'god' }); return null; }
    // 主人在狱 / 死神缠身 / 被查封：不收租
    if (owner.prison > 0) { rmLog(st, '🚓 ' + owner.name + ' 正在坐牢，无法收租', '#9CA3AF', { seat: p.seat, kind: 'info' }); return null; }
    if (owner.god && owner.god.name === 'sishen') { rmLog(st, '💀 ' + owner.name + ' 被死神缠身，无法收租', '#9CA3AF', { seat: p.seat, kind: 'god' }); return null; }
    if (land.seized) { rmLog(st, '🚫 【' + cell.name + '】已被查封，本次免收租金', '#9CA3AF', { seat: p.seat, kind: 'info' }); land.seized = false; return null; }
    // 大商业地特殊建筑效果
    if (cell.type === 'bigland') {
      if (land.build === 'hotel') { rmHospitalize(st, p, 2, '住进黑店旅馆'); return null; }
      if (land.build === 'gas') {
        const amt = rmBadPenalty(st, p, 8000);
        rmLog(st, '⛽ ' + p.name + ' 踩到加油站，被强收服务费 -' + rmFmtMoney(amt), '#EF4444', { seat: p.seat, kind: 'money' });
        rmCharge(st, p, amt, { kind: 'gas', creditorSeat: land.owner });
        return null;
      }
      if (land.build === 'park') { rmLog(st, '🌳 ' + p.name + ' 在公园里逛了一圈，什么也没发生', '#22C55E', { seat: p.seat, kind: 'info' }); return null; }
      if (land.build === 'lab') { rmLog(st, '🔬 ' + p.name + ' 路过研究所，隔着玻璃看了看实验', '#9CA3AF', { seat: p.seat, kind: 'info' }); return null; }
    }
    // 普通租金
    let rent = rmRent(st, idx);
    if (!rent) return null;
    if (p.god && p.god.name === 'sishen') rent *= 2;
    rent = rmMoveCost(st, p, rent);
    const freeIdx = p.cards.indexOf('mianfei');
    return { type: 'rent', land: idx, amount: rent, creditorSeat: land.owner, canFree: freeIdx !== -1, freeIdx: freeIdx };
  }

  // ========== 落点选项的执行（买地/盖房/建商业/付租/买公司） ==========
  function rmDoBuyLand(st, p, idx) {
    const cell = RM_MAP[idx], land = st.lands[idx];
    if (land.owner !== -1 || p.money < cell.price) return { ok: false, msg: '无法购买' };
    const cost = rmMoveCost(st, p, cell.price);
    if (p.money < cost) return { ok: false, msg: '现金不足' };
    p.money -= cost;
    land.owner = p.seat;
    land.invested = cost;
    p.lands.push(idx);
    st.actionCount++;
    rmLog(st, '🏠 ' + p.name + ' 买下【' + cell.name + '】（-' + rmFmtMoney(cost) + '）', '#22C55E', { seat: p.seat, kind: 'money' });
    return { ok: true };
  }
  function rmDoUpgrade(st, p, idx) {
    const cell = RM_MAP[idx], land = st.lands[idx];
    if (land.owner !== p.seat || cell.type !== 'land' || land.houses >= RM_MAX_HOUSES) return { ok: false };
    const cost = rmMoveCost(st, p, Math.round(cell.price * 0.8));
    if (p.money < cost) return { ok: false, msg: '现金不足' };
    p.money -= cost;
    land.houses++;
    land.invested += cost;
    st.actionCount++;
    rmLog(st, '🏗️ ' + p.name + ' 把【' + cell.name + '】加盖到 ' + land.houses + ' 层（-' + rmFmtMoney(cost) + '）', '#22C55E', { seat: p.seat, kind: 'money' });
    return { ok: true };
  }
  function rmDoBigBuild(st, p, idx, buildKey) {
    const cell = RM_MAP[idx], land = st.lands[idx];
    const def = RM_BIG_BUILDS[buildKey];
    if (land.owner !== p.seat || cell.type !== 'bigland' || !def) return { ok: false };
    if (buildKey === 'none') return { ok: true };
    const cost = rmMoveCost(st, p, def.price);
    if (p.money < cost) return { ok: false, msg: '现金不足' };
    p.money -= cost;
    land.build = buildKey;
    land.invested += cost;
    st.actionCount++;
    rmLog(st, '🏙️ ' + p.name + ' 在【' + cell.name + '】建成【' + def.name + '】（-' + rmFmtMoney(cost) + '）', '#22C55E', { seat: p.seat, kind: 'money' });
    return { ok: true };
  }
  function rmDoCompanyBuy(st, p, idx) {
    const cell = RM_MAP[idx], comp = st.companies[idx];
    if (comp.owner !== -1) return { ok: false };
    const cost = rmMoveCost(st, p, cell.price);
    if (p.money < cost) return { ok: false, msg: '现金不足' };
    p.money -= cost;
    comp.owner = p.seat;
    comp.seats = 1;
    st.actionCount++;
    rmLog(st, '🏢 ' + p.name + ' 收购【' + cell.name + '】，成为董事长（-' + rmFmtMoney(cost) + '）', '#22C55E', { seat: p.seat, kind: 'money' });
    return { ok: true };
  }

  // ========== 拍卖（rmAuctionStart 就地重建，保证 lands 映射已按 40 格建立） ==========
  function rmAuctionStart(st, landIdx, opts) {
    opts = opts || {};
    const cell = RM_MAP[landIdx];
    const bidders = rmAlivePlayers(st).map(function (p) { return p.seat; });
    st.auction = {
      land: landIdx, bids: {}, passed: [], current: Math.round(cell.price * 0.5), highSeat: -1,
      minInc: Math.max(500, Math.round(cell.price * 0.05)),
      proceedsTo: (opts.proceedsTo === undefined ? -1 : opts.proceedsTo),
      bidders: bidders, turnIdx: 0, done: false, auto: !!opts.auto
    };
    rmLog(st, '🔨 【' + cell.name + '】开始拍卖！底价 ' + rmFmtMoney(st.auction.current) + (st.auction.proceedsTo >= 0 ? '（所得归 ' + st.players[st.auction.proceedsTo].name + '）' : '（归银行）'), '#F59E0B', { kind: 'auction' });
    return st.auction;
  }
  function rmAuctionBid(st, seat, amount) {
    const a = st.auction;
    if (!a || a.done) return { ok: false };
    const p = st.players[seat];
    if (!p || p.eliminated) return { ok: false };
    const need = Math.max(a.current + a.minInc, amount || 0);
    if (need > rmTotalAsset(st, p) * 0.9 + p.money) return { ok: false, msg: '资金不足' };
    if (p.money < need && a.auto === false) { /* 允许，成交时强制变卖 */ }
    a.current = need;
    a.highSeat = seat;
    rmLog(st, '🔨 ' + p.name + ' 出价 ' + rmFmtMoney(need), '#F59E0B', { seat: seat, kind: 'auction' });
    return { ok: true, price: need };
  }
  function rmAuctionPass(st, seat) {
    const a = st.auction;
    if (!a || a.done) return;
    if (a.passed.indexOf(seat) === -1) a.passed.push(seat);
    rmLog(st, '🔨 ' + st.players[seat].name + ' 放弃竞拍', '#9CA3AF', { seat: seat, kind: 'auction' });
  }
  function rmAuctionAliveBidders(st) {
    const a = st.auction;
    if (!a) return [];
    return a.bidders.filter(function (s) { return a.passed.indexOf(s) === -1 && !st.players[s].eliminated; });
  }
  function rmAuctionResolve(st) {
    const a = st.auction;
    if (!a || a.done) return null;
    a.done = true;
    const cell = RM_MAP[a.land], land = st.lands[a.land];
    if (a.highSeat < 0) {
      rmLog(st, '🔨 【' + cell.name + '】流拍，继续空置', '#9CA3AF', { kind: 'auction' });
      st.auction = null;
      return { sold: false };
    }
    const winner = st.players[a.highSeat];
    rmCharge(st, winner, a.current, { kind: 'auction' });
    if (!winner.eliminated) {
      land.owner = winner.seat;
      land.invested = a.current;
      if (winner.lands.indexOf(a.land) === -1) winner.lands.push(a.land);
    }
    if (a.proceedsTo >= 0 && st.players[a.proceedsTo] && !st.players[a.proceedsTo].eliminated) {
      st.players[a.proceedsTo].money += a.current;
    }
    rmLog(st, '🔨 ' + winner.name + ' 以 ' + rmFmtMoney(a.current) + ' 拍得【' + cell.name + '】！', '#22C55E', { seat: winner.seat, kind: 'auction' });
    st.auction = null;
    rmCheckGameEnd(st);
    return { sold: true, seat: winner.seat, price: a.current };
  }

  // ========== 道具使用 ==========
  function rmUseItem(st, p, itemIdx, opts) {
    opts = opts || {};
    const key = p.items[itemIdx];
    if (!key || !RM_ITEMS[key]) return { ok: false, msg: '道具不存在' };
    if (p.god && p.god.name === 'sishen') return { ok: false, msg: '死神缠身：道具全部失效' };
    const def = RM_ITEMS[key];
    if (key === 'remote') {
      const v = Math.max(1, Math.min(6, parseInt(opts.dice) || 0));
      if (!v) return { ok: false, msg: '请选择点数' };
      st.remoteDice = v;
      p.items.splice(itemIdx, 1);
      rmLog(st, '🎲 ' + p.name + ' 使用【遥控骰子】，下一步走 ' + v + ' 点', '#A855F7', { seat: p.seat, kind: 'item' });
      return { ok: true };
    }
    if (key === 'feidan') {
      const li = opts.land;
      const cell = RM_MAP[li], land = st.lands[li];
      if (!cell || !land || land.owner < 0 || land.owner === p.seat) return { ok: false, msg: '请选择对手的地' };
      if (cell.type === 'land' && land.houses > 0) { land.houses = 0; rmLog(st, '🚀 ' + p.name + ' 发射飞弹，夷平【' + cell.name + '】全部房屋！', '#EF4444', { seat: p.seat, kind: 'item' }); }
      else if (cell.type === 'bigland' && land.build !== 'none') { land.build = 'none'; rmLog(st, '🚀 ' + p.name + ' 发射飞弹，炸毁【' + cell.name + '】的特殊建筑！', '#EF4444', { seat: p.seat, kind: 'item' }); }
      else return { ok: false, msg: '那块地没有建筑可炸' };
      p.items.splice(itemIdx, 1);
      return { ok: true };
    }
    // 放置类：路障 / 地雷 / 炸弹
    const cell = (opts.cell === undefined ? p.pos : opts.cell);
    if (cell < 0 || cell >= RM_MAP_LEN) return { ok: false, msg: '无效的格子' };
    const mk = String(cell);
    st.cellEffects[mk] = st.cellEffects[mk] || [];
    st.cellEffects[mk].push({ type: key, bySeat: p.seat });
    p.items.splice(itemIdx, 1);
    rmLog(st, def.icon + ' ' + p.name + ' 在【' + RM_MAP[cell].name + '】放置了【' + def.name + '】', '#A855F7', { seat: p.seat, kind: 'item' });
    return { ok: true };
  }

  // ========== 卡片使用 ==========
  function rmCardNeedsTarget(key) { return RM_CARDS[key] ? RM_CARDS[key].target : 'none'; }
  function rmRichestOther(st, p) {
    let best = null, bv = -1;
    for (const op of rmAlivePlayers(st)) {
      if (op.seat === p.seat) continue;
      const v = rmTotalAsset(st, op);
      if (v > bv) { bv = v; best = op; }
    }
    return best;
  }
  function rmBestStreetOf(st, seat) {
    // 最值钱的一条街：按总投入排序
    const streets = rmStreets();
    let best = null, bv = -1;
    for (const s of streets) {
      let v = 0, owned = 0;
      for (const i of s) {
        const land = st.lands[i];
        if (land && land.owner === seat) { owned++; v += rmLandValue(st, i); }
      }
      if (owned > 0 && v > bv) { bv = v; best = s; }
    }
    return best;
  }
  function rmUseCard(st, p, cardIdx, opts) {
    opts = opts || {};
    const key = p.cards[cardIdx];
    if (!key || !RM_CARDS[key]) return { ok: false, msg: '卡片不存在' };
    const def = RM_CARDS[key];
    if (def.passive) return { ok: false, msg: '这是被动卡，会在关键时刻自动触发' };
    if (p.god && p.god.name === 'sishen') return { ok: false, msg: '死神缠身：卡片全部失效' };
    const consume = function () { p.cards.splice(cardIdx, 1); st.actionCount++; };
    switch (key) {
      case 'xianhai': {
        const t = st.players[opts.target];
        if (!t || t.eliminated || t.seat === p.seat) return { ok: false, msg: '请选择对手' };
        consume();
        rmImprison(st, t, 5, p.name + ' 的陷害卡', p.seat);
        return { ok: true };
      }
      case 'dongmian': {
        const t = st.players[opts.target];
        if (!t || t.eliminated || t.seat === p.seat) return { ok: false, msg: '请选择对手' };
        consume();
        t.hibernate = Math.max(t.hibernate, 2);
        rmLog(st, '❄️ ' + p.name + ' 使用【冬眠卡】：' + t.name + ' 休眠 2 回合', '#A855F7', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
      case 'guaishou': {
        const li = opts.land;
        const cell = RM_MAP[li], land = st.lands[li];
        if (!cell || !land || land.owner < 0 || land.owner === p.seat) return { ok: false, msg: '请选择对手的地' };
        if (cell.type === 'land' && land.houses > 0) { land.houses = 0; consume(); rmLog(st, '👹 ' + p.name + ' 放出怪兽，摧毁【' + cell.name + '】全部房屋！', '#EF4444', { seat: p.seat, kind: 'card' }); return { ok: true }; }
        if (cell.type === 'bigland' && land.build !== 'none') { land.build = 'none'; consume(); rmLog(st, '👹 ' + p.name + ' 放出怪兽，摧毁【' + cell.name + '】的特殊建筑！', '#EF4444', { seat: p.seat, kind: 'card' }); return { ok: true }; }
        return { ok: false, msg: '那块地上没有建筑' };
      }
      case 'emo': {
        const targetSeat = opts.target !== undefined ? opts.target : (rmRichestOther(st, p) || {}).seat;
        const street = rmBestStreetOf(st, targetSeat);
        if (!street) return { ok: false, msg: '对手没有像样的街' };
        consume();
        for (const i of street) {
          const land = st.lands[i];
          if (land && land.owner >= 0 && land.owner !== p.seat) {
            if (RM_MAP[i].type === 'land') land.houses = 0;
            if (RM_MAP[i].type === 'bigland') land.build = 'none';
          }
        }
        const victim = st.players[targetSeat];
        rmLog(st, '😈 ' + p.name + ' 打出【恶魔卡】：' + (victim ? victim.name : '对手') + ' 的一整条街被夷为平地！', '#EF4444', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
      case 'chafeng': {
        const street = rmBestStreetOf(st, opts.target !== undefined ? opts.target : (rmRichestOther(st, p) || {}).seat);
        if (!street) return { ok: false, msg: '对手没有像样的街' };
        const victimSeat = st.lands[street.find(function (i) { return st.lands[i].owner >= 0 && st.lands[i].owner !== p.seat; })].owner;
        const victim = st.players[victimSeat];
        const mi = victim ? victim.cards.indexOf('mianzui') : -1;
        if (mi !== -1) {
          victim.cards.splice(mi, 1);
          rmLog(st, '🛡️ ' + victim.name + ' 使用【免罪卡】抵挡了查封！', '#22C55E', { seat: victimSeat, kind: 'card' });
          consume();
          return { ok: true };
        }
        consume();
        for (const i of street) { if (st.lands[i].owner === victimSeat) st.lands[i].seized = true; }
        rmLog(st, '🚫 ' + p.name + ' 使用【查封卡】：' + victim.name + ' 的一整条街被查封，暂停收租！', '#EF4444', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
      case 'chashui': {
        const t = st.players[opts.target];
        if (!t || t.eliminated || t.seat === p.seat) return { ok: false, msg: '请选择对手' };
        consume();
        const amt = Math.round(rmTotalAsset(st, t) * 0.12);
        rmLog(st, '🧾 ' + p.name + ' 对 ' + t.name + ' 使用【查税卡】：补缴总资产 12%（-' + rmFmtMoney(amt) + '）', '#EF4444', { seat: p.seat, kind: 'card' });
        rmCharge(st, t, amt, { kind: 'tax' });
        return { ok: true };
      }
      case 'hong': case 'hei': {
        const i = opts.stock;
        if (i === undefined || !st.stocks[i]) return { ok: false, msg: '请选择股票' };
        consume();
        rmStockAdjust(st, i, key === 'hong' ? 0.18 : -0.18, p.name + ' 的' + def.name);
        return { ok: true };
      }
      case 'qiangduo': {
        const t = rmRichestOther(st, p);
        if (!t || !t.cards.length) return { ok: false, msg: '对手没有卡片可抢' };
        const ci = Math.floor(Math.random() * t.cards.length);
        const got = t.cards.splice(ci, 1)[0];
        if (p.cards.length < 8) p.cards.push(got);
        consume();
        rmLog(st, '🃏 ' + p.name + ' 使用【抢夺卡】，从 ' + t.name + ' 手里抢走【' + RM_CARDS[got].name + '】', '#A855F7', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
      case 'junfu': {
        consume();
        const alive = rmAlivePlayers(st);
        const total = alive.reduce(function (a, x) { return a + x.money; }, 0);
        const avg = Math.round(total / alive.length);
        for (const x of alive) x.money = avg;
        rmLog(st, '⚖️ ' + p.name + ' 打出【均富卡】：全场现金平分，每人 ' + rmFmtMoney(avg) + '！', '#F59E0B', { seat: p.seat, kind: 'card' });
        rmCheckGameEnd(st);
        return { ok: true };
      }
      case 'goudi': {
        const t = st.players[opts.target];
        if (!t || t.eliminated || t.seat === p.seat) return { ok: false, msg: '请选择对手' };
        const li = t.pos;
        const cell = RM_MAP[li], land = st.lands[li];
        if (!land || land.owner !== t.seat) return { ok: false, msg: t.name + ' 脚下不是自己的地' };
        const cost = rmLandValue(st, li);
        if (p.money < cost) return { ok: false, msg: '现金不足（需 ' + rmFmtMoney(cost) + '）' };
        consume();
        p.money -= cost;
        t.money += cost;
        land.owner = p.seat;
        p.lands.push(li);
        t.lands.splice(t.lands.indexOf(li), 1);
        rmLog(st, '📜 ' + p.name + ' 使用【购地卡】，强制以 ' + rmFmtMoney(cost) + ' 买下 ' + t.name + ' 脚下的【' + cell.name + '】', '#A855F7', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
      case 'paimai': {
        const t = st.players[opts.target];
        if (!t || t.eliminated || t.seat === p.seat || !t.lands.length) return { ok: false, msg: '请选择有土地的对手' };
        let li = t.lands[0], lv = -1;
        for (const i of t.lands) { const v = rmLandValue(st, i); if (v > lv) { lv = v; li = i; } }
        consume();
        const land = st.lands[li];
        land.owner = -1; land.houses = 0; land.build = 'none'; land.invested = 0;
        t.lands.splice(t.lands.indexOf(li), 1);
        rmLog(st, '🔨 ' + p.name + ' 使用【拍卖卡】，强制拍卖 ' + t.name + ' 的【' + RM_MAP[li].name + '】，所得归 ' + p.name + '！', '#A855F7', { seat: p.seat, kind: 'card' });
        rmAuctionStart(st, li, { proceedsTo: p.seat });
        return { ok: true, auction: true };
      }
      case 'tingliu': {
        const t = st.players[opts.target !== undefined ? opts.target : p.seat];
        if (!t || t.eliminated) return { ok: false, msg: '目标无效' };
        consume();
        t.stayNext = 1;
        rmLog(st, '🛑 ' + p.name + ' 使用【停留卡】：' + t.name + ' 下回合原地不动', '#A855F7', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
      case 'wugui': {
        const t = st.players[opts.target];
        if (!t || t.eliminated || t.seat === p.seat) return { ok: false, msg: '请选择对手' };
        consume();
        t.turtleTurns = Math.max(t.turtleTurns, 3);
        rmLog(st, '🐢 ' + p.name + ' 使用【乌龟卡】：' + t.name + ' 连续 3 回合只能走 1 步', '#A855F7', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
      case 'zhuanxiang': {
        const t = st.players[opts.target !== undefined ? opts.target : p.seat];
        if (!t || t.eliminated) return { ok: false, msg: '目标无效' };
        consume();
        t.dir = (t.dir || 1) * -1;
        rmLog(st, '🔄 ' + p.name + ' 使用【转向卡】：' + t.name + ' 的行进方向反转！', '#A855F7', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
      case 'tianshi': {
        const street = rmBestStreetOf(st, p.seat);
        if (!street) return { ok: false, msg: '你还没有连片的土地' };
        let okAny = false;
        for (const i of street) {
          const land = st.lands[i];
          if (land.owner === p.seat && RM_MAP[i].type === 'land' && land.houses < RM_MAX_HOUSES) { land.houses++; okAny = true; }
        }
        if (!okAny) return { ok: false, msg: '那条街的房屋已经盖满' };
        consume();
        rmLog(st, '😇 ' + p.name + ' 使用【天使卡】：自己一条街全部房屋 +1 层！', '#22C55E', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
      case 'mianfei': return { ok: false, msg: '免费卡在被收费时选择使用' };
      case 'qingshen': {
        consume();
        const gc = rmNearestGodCell(st, p);
        if (gc !== null && st.boardGods[gc]) {
          const g = st.boardGods[gc];
          delete st.boardGods[gc];
          rmGodAttach(st, p, g, '请神卡');
        } else {
          const g = RM_GOD_KEYS[Math.floor(Math.random() * 3)]; // 附近没有神明 → 请来随机正神
          rmGodAttach(st, p, g, '请神卡');
        }
        return { ok: true };
      }
      case 'songshen': {
        if (!p.god) return { ok: false, msg: '你身上没有神明' };
        consume();
        rmGodDismiss(st, p, '送神卡');
        return { ok: true };
      }
      case 'gaijian': {
        const li = opts.land;
        const cell = RM_MAP[li], land = st.lands[li];
        const bt = opts.buildType;
        if (!cell || cell.type !== 'bigland' || land.owner !== p.seat || land.build === 'none' || !RM_BIG_BUILDS[bt] || bt === 'none' || bt === land.build) return { ok: false, msg: '选择自己的已建成商业地与新建筑类型' };
        consume();
        land.build = bt;
        const r = rmCharge(st, p, 3000, { kind: 'rebuild' });
        rmLog(st, '🏗️ ' + p.name + ' 使用【改建卡】：【' + cell.name + '】改建为【' + RM_BIG_BUILDS[bt].name + '】', '#A855F7', { seat: p.seat, kind: 'card' });
        return { ok: true };
      }
    }
    return { ok: false, msg: '未实现卡片' };
  }

  // ========== 商店 ==========
  function rmBuyPoints(st, p, cash) {
    cash = Math.max(1000, Math.round(cash || 0));
    if (p.money < cash) return { ok: false, msg: '现金不足' };
    p.money -= cash;
    const pts = Math.round(cash / 100);
    p.points += pts;
    rmLog(st, '🛒 ' + p.name + ' 兑换 ' + pts + ' 点券（-' + rmFmtMoney(cash) + '）', '#22C55E', { seat: p.seat, kind: 'shop' });
    return { ok: true };
  }
  function rmShopBuyCard(st, p, key) {
    const def = RM_CARDS[key];
    if (!def) return { ok: false };
    if (p.points < def.cost) return { ok: false, msg: '点券不足' };
    if (p.cards.length >= 8) return { ok: false, msg: '卡片已满 8 张' };
    p.points -= def.cost;
    p.cards.push(key);
    rmLog(st, '🃏 ' + p.name + ' 购入卡片【' + def.name + '】（-' + def.cost + ' 点券）', '#A855F7', { seat: p.seat, kind: 'shop' });
    return { ok: true };
  }
  function rmShopBuyItem(st, p, key) {
    const def = RM_ITEMS[key];
    if (!def) return { ok: false };
    if (p.points < def.cost) return { ok: false, msg: '点券不足' };
    if (p.items.length >= 8) return { ok: false, msg: '道具已满 8 个' };
    p.points -= def.cost;
    p.items.push(key);
    rmLog(st, '🎁 ' + p.name + ' 购入道具【' + def.name + '】（-' + def.cost + ' 点券）', '#A855F7', { seat: p.seat, kind: 'shop' });
    return { ok: true };
  }

  // ========== 回合状态机（引擎层，供实战与推演共用） ==========
  // 回合开始状态结算：返回 'skip'（本回合不能行动）| 'act'
  function rmTurnStartStatus(st, p) {
    if (p.eliminated) return 'skip';
    // 神明计时
    if (p.god) {
      p.god.turns--;
      if (p.god.turns <= 0) rmGodDismiss(st, p, '时间到了自行离开');
    }
    if (p.devilTurns > 0) { p.devilTurns--; if (p.devilTurns <= 0) rmLog(st, '😈 ' + p.name + ' 的恶魔余波消散了', '#9CA3AF', { seat: p.seat, kind: 'status' }); }
    if (p.hospital > 0) {
      p.hospital--;
      if (p.hospital > 0) { rmLog(st, '🏥 ' + p.name + ' 还在住院（剩 ' + p.hospital + ' 回合），本回合不能行动', '#EF4444', { seat: p.seat, kind: 'status' }); return 'skip'; }
      rmLog(st, '🏥 ' + p.name + ' 出院了', '#22C55E', { seat: p.seat, kind: 'status' });
    }
    if (p.prison > 0) {
      p.prison--;
      if (p.prison > 0) { rmLog(st, '🚓 ' + p.name + ' 还在坐牢（剩 ' + p.prison + ' 回合），本回合不能行动', '#EF4444', { seat: p.seat, kind: 'status' }); return 'skip'; }
      rmLog(st, '🚓 ' + p.name + ' 刑满释放', '#22C55E', { seat: p.seat, kind: 'status' });
    }
    if (p.hibernate > 0) {
      p.hibernate--;
      rmLog(st, '❄️ ' + p.name + ' 正在冬眠（剩 ' + p.hibernate + ' 回合），本回合不能行动', '#EF4444', { seat: p.seat, kind: 'status' });
      return 'skip';
    }
    if (p.stayNext > 0) {
      p.stayNext = 0;
      rmLog(st, '🛑 ' + p.name + ' 被停留卡定住，本回合原地不动', '#F59E0B', { seat: p.seat, kind: 'status' });
      return 'skip';
    }
    return 'act';
  }
  // 回合结束：换下一位；座位号回落视为新一轮（回合数 +1，不受先手玩家破产影响）
  function rmEndTurnAdvance(st) {
    const cur = st.turnSeat;
    const next = rmNextAliveSeat(st, cur);
    if (next <= cur) {
      st.round++;
      rmRoundStartEffects(st);
      if (st.winMode === 'rounds') rmCheckGameEnd(st);
    }
    st.turnSeat = next;
    st.dice = null;
    st.pending = null;
    st.rolled = false;
    return next;
  }
  // __RM_ENGINE_END__
  // __RM_AI_BEGIN__
  // ========== 大富翁 AI：入门(随机) / 中级(贪心启发式) / 高级(落点预判 + 蒙特卡洛) ==========

  // 落点评分（越高越好；rent 为正=我收租，负=我要付钱）
  function rmAiCellScore(st, p, idx) {
    const cell = RM_MAP[idx];
    if (!cell) return 0;
    const mk = String(idx);
    let s = 0;
    if (st.cellMoney[mk] > 0) s += st.cellMoney[mk] / 4000;
    const fx = st.cellEffects[mk] || [];
    for (const e of fx) {
      if (e.bySeat === p.seat) continue;
      if (e.type === 'dilei') s -= 6;
      if (e.type === 'zhadan') s -= (st.lands[idx] && st.lands[idx].owner === p.seat ? 8 : 3);
      if (e.type === 'luzhang') s -= 1;
    }
    switch (cell.type) {
      case 'land': case 'bigland': {
        const land = st.lands[idx];
        if (land.owner < 0) {
          const afford = p.money > cell.price * 1.25;
          s += afford ? 5 + cell.price / 12000 : 1.5;
        } else if (land.owner === p.seat) {
          if (cell.type === 'land' && land.houses < RM_MAX_HOUSES && p.money > cell.price) s += 2.5;
          else if (cell.type === 'bigland' && land.build === 'none') s += 2;
          else s += 0.8;
        } else {
          const owner = st.players[land.owner];
          if (owner && !owner.eliminated && owner.prison <= 0 && !land.seized) {
            if (cell.type === 'bigland' && land.build === 'hotel') s -= 6;
            else if (cell.type === 'bigland' && land.build === 'gas') s -= 2.2;
            else if (cell.type === 'bigland' && land.build === 'park') s += 0.5;
            else s -= Math.min(6, rmRent(st, idx) / 2500);
          }
        }
        break;
      }
      case 'chance': case 'destiny': s += (p.god && (p.god.name === 'qiongshen' || p.god.name === 'sishen')) ? -1 : 0.6; break;
      case 'bank': s += p.money > 20000 ? 1.2 : -0.5; break;
      case 'tax': s -= 2; break;
      case 'prison': s += 0.1; break;
      case 'hospital': s += 0.1; break;
      case 'shop': s += p.points >= 40 ? 1.5 : 0.5; break;
      case 'stock': s += p.money > 30000 ? 1 : 0.3; break;
      case 'company': {
        const comp = st.companies[idx];
        if (comp.owner < 0) s += p.money > cell.price * 1.3 ? 4 : 0.5;
        else if (comp.owner === p.seat) s += 0.5;
        else s -= Math.min(4, rmCompanyFee(st, idx, p) / 4000);
        break;
      }
    }
    return s;
  }
  // 走 steps 步后的落点评分（考虑中途路过起点奖金与路上道具）
  function rmAiMoveScore(st, p, steps) {
    if (steps === 0) return -1;
    const landing = (p.pos + (p.dir || 1) * steps + RM_MAP_LEN * 4) % RM_MAP_LEN;
    let s = rmAiCellScore(st, p, landing);
    // 路过起点
    const passStart = (function () {
      let pos = p.pos, hit = false;
      for (let i = 0; i < steps; i++) { pos = (pos + (p.dir || 1) + RM_MAP_LEN) % RM_MAP_LEN; if (pos === 0) hit = true; }
      return hit;
    })();
    if (passStart) s += RM_START_BONUS / 3000;
    return s;
  }
  // 枚举骰子组合（n 颗骰子全部点数的概率分布）：返回 [{steps, prob}]
  function rmDiceOutcomes(n) {
    const cnt = {};
    const total = Math.pow(6, n);
    const rec = function (left, acc) {
      if (!left) { cnt[acc] = (cnt[acc] || 0) + 1; return; }
      for (let d = 1; d <= 6; d++) rec(left - 1, acc + d);
    };
    rec(n, 0);
    return Object.keys(cnt).map(function (k) { return { steps: parseInt(k), prob: cnt[k] / total }; });
  }
  function rmAiPickDiceCount(st, seat, level) {
    const p = st.players[seat];
    const opts = rmVehicleDice(st.vehicle);
    if (opts.length === 1 || p.turtleTurns > 0) return opts[0];
    if (difficultyLevel(level) === 'fast') return opts[Math.floor(Math.random() * opts.length)];
    let bestN = opts[0], bestS = -1e9;
    for (const n of opts) {
      const outcomes = rmDiceOutcomes(n);
      let ev = 0;
      for (const o of outcomes) ev += o.prob * rmAiMoveScore(st, p, o.steps);
      if (ev > bestS) { bestS = ev; bestN = n; }
    }
    return bestN;
  }
  // 遥控骰子值：选 1~6 中期望最好的步数
  function rmAiRemoteValue(st, seat) {
    const p = st.players[seat];
    let best = 1, bs = -1e9;
    for (let v = 1; v <= 6; v++) {
      const s = rmAiMoveScore(st, p, v);
      if (s > bs) { bs = s; best = v; }
    }
    return { value: best, score: bs };
  }

  // 对手下一步落点分布（高级 AI 的「蒙特卡洛预判」基础）：考虑其骰子数、乌龟卡、停留
  function rmPredictOpponentLanding(st, seat) {
    const p = st.players[seat];
    const dist = {};
    if (!p || p.eliminated || p.hospital > 0 || p.prison > 0 || p.hibernate > 0 || p.stayNext > 0) return dist;
    if (p.turtleTurns > 0) { dist[rmDistance(0, (p.pos + (p.dir || 1) + RM_MAP_LEN) % RM_MAP_LEN, 1)] = 1; return dist; }
    const opts = rmVehicleDice(st.vehicle);
    for (const n of opts) {
      const w = 1 / opts.length;
      for (const o of rmDiceOutcomes(n)) {
        const landing = (p.pos + (p.dir || 1) * o.steps + RM_MAP_LEN * 4) % RM_MAP_LEN;
        dist[landing] = (dist[landing] || 0) + o.prob * w;
      }
    }
    return dist;
  }
  // 高级 AI：在我的地上找对手最可能踩到的高租金格（放地雷/路障用）
  function rmBestTrapCell(st, me, level) {
    let best = null, bs = -1;
    for (const op of st.players) {
      if (!op || op.eliminated || op.seat === me.seat) continue;
      const dist = rmPredictOpponentLanding(st, op.seat);
      for (const k of Object.keys(dist)) {
        const idx = parseInt(k);
        const prob = dist[k];
        const cell = RM_MAP[idx];
        let v = prob * 10;
        if (cell && (cell.type === 'land' || cell.type === 'bigland') && st.lands[idx] && st.lands[idx].owner === me.seat) v += rmRent(st, idx) / 3000;
        // 别放自己脚下/即将踩到的格
        if (idx === me.pos) v -= 20;
        if (v > bs) { bs = v; best = idx; }
      }
    }
    return best;
  }

  // ========== 决策：pending 处理（买地/盖房/商业建筑/租金/公司/拍卖） ==========
  function rmAiCashReserve(st, p) {
    // 预留现金：防查税卡/高租金；约为总资产 10% + 场上最高租金（封顶 6 万）
    let maxRent = 0;
    for (let i = 0; i < RM_MAP_LEN; i++) {
      const land = st.lands[i];
      if (land && land.owner >= 0 && land.owner !== p.seat) maxRent = Math.max(maxRent, rmRent(st, i));
    }
    return Math.round(rmTotalAsset(st, p) * 0.10 + Math.min(maxRent, 60000));
  }
  function rmAiLandWant(st, p, idx, price, level) {
    // 买地意愿分：基础价/收入比 + 连片加成 + 卡位（挡对手连片）
    const cell = RM_MAP[idx];
    const baseRent = (cell.rent || 0) > 0 ? cell.rent : Math.max(1, rmRent(st, idx)); // 无主地用基础地租评估
    let s = cell.price / baseRent; // 回本回合代理（越小越好）
    let score = 10000 / (s * 1000); // 归一化
    const street = rmStreetOf(idx);
    let mine = 0, theirs = 0;
    for (const i of street) {
      const l = st.lands[i];
      if (l && l.owner === p.seat) mine++;
      else if (l && l.owner >= 0) theirs++;
    }
    if (mine >= 1) score += 0.35 * mine;       // 连片：自己已有 → 强烈想买
    if (theirs >= 2) score += 0.25;            // 卡位：阻止对手连片
    if (cell.type === 'bigland') score += 0.5; // 大地战略价值
    if (level === 'fast') score += (Math.random() - 0.5) * 0.6;
    return score;
  }
  function rmAiDecidePending(st, seat, level, pending) {
    const p = st.players[seat];
    const lvl = difficultyLevel(level);
    const reserve = rmAiCashReserve(st, p);
    if (!pending) return { act: 'none' };
    switch (pending.type) {
      case 'buy': {
        const want = rmAiLandWant(st, p, pending.land, pending.price, lvl);
        const afford = p.money - rmMoveCost(st, p, pending.price) >= reserve * 0.6;
        if (lvl === 'fast') return { act: Math.random() < 0.72 && p.money > pending.price ? 'buy' : 'decline' };
        return { act: (afford && want >= 0.8) ? 'buy' : 'decline' };
      }
      case 'upgrade': {
        const afford = p.money - pending.cost >= reserve;
        if (lvl === 'fast') return { act: Math.random() < 0.5 && p.money > pending.cost ? 'upgrade' : 'skip' };
        // 中级/高级：租金提升 > 成本/5 就盖（新倍率下 2 层即可回本）
        const cell = RM_MAP[pending.land], land = st.lands[pending.land];
        const nowR = Math.round(cell.rent * rmHouseMult(Math.max(1, land.houses)));
        const nextR = Math.round(cell.rent * rmHouseMult(land.houses + 1));
        return { act: (afford && (nextR - nowR) * 5 > pending.cost) ? 'upgrade' : 'skip' };
      }
      case 'bigBuild': {
        if (lvl === 'fast') {
          const keys = ['hotel', 'mall', 'gas', 'lab', 'park'];
          const k = keys[Math.floor(Math.random() * keys.length)];
          return { act: p.money > RM_BIG_BUILDS[k].price + reserve ? 'build' : 'skip', build: k };
        }
        // 强：优先研究所（生道具）；已有研究所则商场收租；对手常路过则旅馆
        const cell = RM_MAP[pending.land];
        let pick = 'mall';
        const myLabs = p.lands.filter(function (i) { return st.lands[i] && st.lands[i].build === 'lab'; }).length;
        if (myLabs === 0) pick = 'lab';
        else if (rmBestTrapCell(st, p, lvl) === pending.land) pick = 'hotel';
        else pick = 'mall';
        if (p.money < RM_BIG_BUILDS[pick].price + reserve) pick = p.money > RM_BIG_BUILDS.gas.price + reserve ? 'gas' : 'park';
        if (p.money < RM_BIG_BUILDS[pick].price + reserve * 0.6) return { act: 'skip' };
        return { act: 'build', build: pick };
      }
      case 'rent': {
        if (pending.canFree) {
          const useFree = lvl === 'fast' ? Math.random() < 0.4 : pending.amount >= 4000;
          if (useFree) return { act: 'freecard', freeIdx: pending.freeIdx };
        }
        return { act: 'pay' };
      }
      case 'companyBuy': {
        const afford = p.money - pending.price >= reserve;
        if (lvl === 'fast') return { act: Math.random() < 0.4 && p.money > pending.price ? 'buy' : 'decline' };
        return { act: afford ? 'buy' : 'decline' };
      }
      case 'shop': return { act: 'shop' }; // 上层走 rmAiShop
      case 'stock': return { act: 'stock' }; // 上层走 rmAiStock
    }
    return { act: 'none' };
  }

  // 拍卖 AI：返回最大可承受出价；0 = 不参与
  function rmAiAuctionMaxBid(st, seat, landIdx, level) {
    const p = st.players[seat];
    const cell = RM_MAP[landIdx];
    if (!cell || p.eliminated) return 0;
    const reserve = rmAiCashReserve(st, p);
    const lvl = difficultyLevel(level);
    let v = rmLandValue(st, landIdx);
    const want = rmAiLandWant(st, p, landIdx, cell.price, lvl);
    let cap = Math.round(v * (lvl === 'fast' ? 0.9 : 1.1 + want * 0.4));
    cap = Math.min(cap, Math.max(0, p.money - Math.round(reserve * 0.5)));
    if (lvl === 'fast') cap = Math.round(cap * (0.6 + Math.random() * 0.5));
    return Math.max(0, cap);
  }

  // ========== 决策：回合内卡片使用（贪心优先级 + 高级威胁预判） ==========
  function rmAiUseCard(st, seat, level) {
    const p = st.players[seat];
    if (!p.cards.length) return null;
    if (p.god && p.god.name === 'sishen') return null; // 死神：卡片失效
    const lvl = difficultyLevel(level);
    const myAsset = rmTotalAsset(st, p);
    let leader = null, lv = -1;
    for (const op of rmAlivePlayers(st)) {
      if (op.seat === p.seat) continue;
      const v = rmTotalAsset(st, op);
      if (v > lv) { lv = v; leader = op; }
    }
    const has = function (k) { return p.cards.indexOf(k); };
    // —— 送神卡：身上有衰/穷/死神立刻送 ——
    if (p.god && ['qiongshen', 'shuaishen', 'sishen'].indexOf(p.god.name) !== -1) {
      const i = has('songshen');
      if (i !== -1) return { cardIdx: i, opts: {}, prio: 100 };
    }
    const cands = [];
    const push = function (key, prio, opts) { const i = has(key); if (i !== -1) cands.push({ cardIdx: i, opts: opts || {}, prio: prio }); };
    if (leader) {
      const leaderAsset = lv;
      // 均富：我现金占比很低时翻盘
      if (leaderAsset > myAsset * 1.25 && rmAlivePlayers(st).length >= 3) push('junfu', lvl === 'fast' ? 30 : 88);
      // 查税：对手现金/资产高
      if (leaderAsset > myAsset * 1.05) push('chashui', lvl === 'fast' ? 40 : 82, { target: leader.seat });
      // 陷害/冬眠：打领头羊
      push('xianhai', lvl === 'fast' ? 35 : (leaderAsset > myAsset ? 78 : 55), { target: leader.seat });
      push('dongmian', lvl === 'fast' ? 30 : (leaderAsset > myAsset ? 66 : 45), { target: leader.seat });
      push('wugui', lvl === 'fast' ? 25 : 42, { target: leader.seat });
      // 怪兽：打对手最贵且房屋多的地
      let bestLand = -1, blv = 0;
      for (const op of rmAlivePlayers(st)) {
        if (op.seat === p.seat) continue;
        for (const i of op.lands) {
          const land = st.lands[i], cell = RM_MAP[i];
          const v = (cell.type === 'land' ? land.houses * 2 : 0) + (cell.type === 'bigland' && land.build !== 'none' ? 8 : 0) + cell.price / 10000;
          if (v > blv && (land.houses >= 2 || (cell.type === 'bigland' && land.build !== 'none'))) { blv = v; bestLand = i; }
        }
      }
      if (bestLand !== -1) push('guaishou', lvl === 'fast' ? 32 : 60 + blv, { land: bestLand });
      // 恶魔/查封：对手最值钱的街
      const anyStreet = rmBestStreetOf(st, leader.seat);
      if (anyStreet) {
        let sv = 0; for (const i of anyStreet) if (st.lands[i].owner === leader.seat) sv += rmLandValue(st, i);
        if (sv > 30000) push('emo', lvl === 'fast' ? 36 : 74);
        if (sv > 25000) push('chafeng', lvl === 'fast' ? 30 : 58);
      }
      // 拍卖卡：对手有贵地且我现金紧张
      if (leader.lands.length && p.money < myAsset * 0.3) push('paimai', lvl === 'fast' ? 28 : 52, { target: leader.seat });
      // 购地卡：对手脚下正好是自己的好地
      const gl = leader.pos;
      if (st.lands[gl] && st.lands[gl].owner === leader.seat && rmLandValue(st, gl) > 20000 && p.money > rmLandValue(st, gl)) push('goudi', lvl === 'fast' ? 26 : 50, { target: leader.seat });
      // 抢夺卡
      if (leader.cards.length >= 3) push('qiangduo', lvl === 'fast' ? 22 : 38);
      // 黑卡：对手重仓的股票砸盘；红卡：自己重仓的拉盘
      for (let si = 0; si < st.stocks.length; si++) {
        const oppShares = rmAlivePlayers(st).filter(function (x) { return x.seat !== p.seat; }).reduce(function (a, x) { return a + x.stocks[si]; }, 0);
        if (oppShares * st.stocks[si].price > 25000) push('hei', lvl === 'fast' ? 24 : 62, { stock: si });
        if (p.stocks[si] * st.stocks[si].price > 20000) push('hong', lvl === 'fast' ? 24 : 56, { stock: si });
      }
    }
    // 天使卡：我有连片且已有 2+ 层
    const myStreet = rmBestStreetOf(st, p.seat);
    if (myStreet) {
      let h = 0, n = 0;
      for (const i of myStreet) { const l = st.lands[i]; if (l.owner === p.seat && RM_MAP[i].type === 'land') { n++; h += l.houses; } }
      if (n >= 2 && h >= 2 && h < n * RM_MAX_HOUSES) push('tianshi', lvl === 'fast' ? 30 : 65);
    }
    // 改建卡：把公园/加油站改成研究所或商场
    for (const i of p.lands) {
      const l = st.lands[i], cell = RM_MAP[i];
      if (cell.type === 'bigland' && (l.build === 'park' || l.build === 'gas')) push('gaijian', 40, { land: i, buildType: 'lab' });
    }
    // 请神卡：中级以上留着防衰神；入门随便用
    if (!p.god && lvl === 'fast') push('qingshen', 15);
    // 停留卡：对手快踩到我的大地时
    const trap = rmBestTrapCell(st, p, lvl);
    if (trap !== null && st.lands[trap] && st.lands[trap].owner === p.seat && lvl !== 'fast') {
      const i2 = has('tingliu');
      if (i2 !== -1 && leader) cands.push({ cardIdx: i2, opts: { target: leader.seat }, prio: 46 });
    }
    // 转向卡：入门偶尔乱用
    if (lvl === 'fast') push('zhuanxiang', 8, { target: Math.random() < 0.5 ? p.seat : (leader ? leader.seat : p.seat) });
    if (!cands.length) return null;
    if (lvl === 'fast') return cands[Math.floor(Math.random() * cands.length)];
    cands.sort(function (a, b) { return b.prio - a.prio; });
    const top = cands[0];
    if (lvl === 'normal' && top.prio < 55) return null; // 中级：小价值不用，省着
    if (lvl === 'strong') {
      // 高级：蒙特卡洛验证卡片收益（小样本快速模拟「用 vs 不用」）
      if (top.prio < 50) return null;
      const gain = rmMcCardGain(st, seat, top, 10);
      if (gain <= 0) return null;
    }
    return top;
  }
  // 高级 AI 的蒙特卡洛：模拟使用卡片后一轮内的资产相对变化
  function rmMcCardGain(st, seat, plan, samples) {
    try {
      const base = rmMcSnapshotScore(st, seat, samples, null);
      const after = rmMcSnapshotScore(st, seat, samples, plan);
      return after - base;
    } catch (e) { return 1; } // 出错则放行
  }
  function rmMcSnapshotScore(st, seat, samples, plan) {
    let sum = 0;
    for (let s = 0; s < samples; s++) {
      const sim = rmCloneState(st);
      const sp = sim.players[seat];
      if (plan) {
        // 在克隆体上直接结算这张卡
        const idxInSim = sp.cards.indexOf(st.players[seat].cards[plan.cardIdx]);
        if (idxInSim !== -1) rmUseCard(sim, sp, idxInSim, plan.opts);
        if (sim.auction) { // 拍卖卡引起的拍卖：AI 快速竞价收尾
          let guard = 0;
          while (sim.auction && !sim.auction.done && guard++ < 20) {
            const a = sim.auction;
            const bidder = a.bidders[a.turnIdx % a.bidders.length];
            const cap = rmAiAuctionMaxBid(sim, bidder, a.land, 'normal');
            if (cap > a.current && sim.players[bidder].money > a.current + a.minInc) rmAuctionBid(sim, bidder, a.current + a.minInc);
            else rmAuctionPass(sim, bidder);
            a.turnIdx++;
            if (rmAuctionAliveBidders(sim).length <= 1 || (a.highSeat >= 0 && rmAuctionAliveBidders(sim).every(function (x) { return x === a.highSeat; }))) rmAuctionResolve(sim);
          }
          if (sim.auction) rmAuctionResolve(sim);
        }
      }
      // 快速推演 N 个随机回合（所有人走快棋策略）
      for (let r = 0; r < 8; r++) {
        const alive = rmAlivePlayers(sim);
        if (alive.length <= 1) break;
        const cur = sim.players[sim.turnSeat];
        if (!cur || cur.eliminated) { rmEndTurnAdvance(sim); continue; }
        const status = rmTurnStartStatus(sim, cur);
        if (status === 'act') {
          const dice = rmRollDice(sim, cur, rmVehicleDice(sim.vehicle)[0] || 1, 0);
          const steps = dice.reduce(function (a, b) { return a + b; }, 0);
          rmMoveSteps(sim, cur, steps);
          const pend = rmLandingResolve(sim, cur);
          rmAiResolvePendingInSim(sim, cur, pend);
          if (sim.auction) rmAuctionResolve(sim);
        }
        rmEndTurnAdvance(sim);
        if (sim.winnerSeat !== null && sim.winnerSeat !== undefined) break;
      }
      const me = sim.players[seat];
      const mine = me.eliminated ? 0 : rmTotalAsset(sim, me);
      let maxOpp = 0;
      for (const op of sim.players) if (!op.eliminated && op.seat !== seat) maxOpp = Math.max(maxOpp, rmTotalAsset(sim, op));
      sum += (mine - maxOpp);
    }
    return sum / samples;
  }
  // 推演内的 pending 快速处理（等价中级 AI 的保守版）
  function rmAiResolvePendingInSim(st, p, pending) {
    if (!pending) return;
    const reserve = rmAiCashReserve(st, p);
    switch (pending.type) {
      case 'buy': if (p.money - pending.price > reserve * 0.5 && rmAiLandWant(st, p, pending.land, pending.price, 'normal') >= 0.8) rmDoBuyLand(st, p, pending.land); break;
      case 'upgrade': if (p.money - pending.cost > reserve) rmDoUpgrade(st, p, pending.land); break;
      case 'bigBuild': { const pick = p.money > 35000 + reserve ? 'lab' : (p.money > 30000 + reserve ? 'mall' : null); if (pick) rmDoBigBuild(st, p, pending.land, pick); break; }
      case 'rent': {
        if (pending.canFree && pending.amount >= 5000) {
          p.cards.splice(pending.freeIdx, 1);
          rmLog(st, '🎟️ ' + p.name + ' 使用【免费卡】免付 ' + rmFmtMoney(pending.amount), '#22C55E', { seat: p.seat, kind: 'card' });
        } else {
          rmLog(st, '💸 ' + p.name + ' 向 ' + st.players[pending.creditorSeat].name + ' 支付租金 -' + rmFmtMoney(pending.amount) + '（' + RM_MAP[pending.land].name + '）', '#EF4444', { seat: p.seat, kind: 'money' });
          rmCharge(st, p, pending.amount, { kind: 'rent', creditorSeat: pending.creditorSeat });
        }
        break;
      }
      case 'companyBuy': if (p.money - pending.price > reserve) rmDoCompanyBuy(st, p, pending.cell); break;
      case 'shop': rmAiShop(st, p.seat, 'normal'); break;
      case 'stock': rmAiStock(st, p.seat, 'normal'); break;
    }
  }

  // ========== 决策：回合内道具使用（高级：按对手落点预判放雷） ==========
  function rmAiUseItem(st, seat, level) {
    const p = st.players[seat];
    if (!p.items.length) return null;
    if (p.god && p.god.name === 'sishen') return null;
    const lvl = difficultyLevel(level);
    if (lvl === 'fast') {
      if (Math.random() < 0.25 && p.items.length) {
        const i = Math.floor(Math.random() * p.items.length);
        const key = p.items[i];
        if (key === 'feidan') {
          // 找一块对手有建筑的地
          const opts = [];
          for (const op of st.players) if (!op.eliminated && op.seat !== seat) for (const li of op.lands) { const l = st.lands[li]; if (l.houses > 0 || l.build !== 'none') opts.push(li); }
          if (opts.length) return { itemIdx: i, opts: { land: opts[Math.floor(Math.random() * opts.length)] } };
        } else if (key !== 'remote') {
          return { itemIdx: i, opts: { cell: (p.pos + 1 + Math.floor(Math.random() * 6) + RM_MAP_LEN) % RM_MAP_LEN } };
        }
      }
      return null;
    }
    // 中/高级：地雷/路障放对手最可能落点（且最好是我的地，制造连锁伤害）
    const trap = rmBestTrapCell(st, p, lvl);
    const idxL = p.items.indexOf('dilei');
    if (idxL !== -1 && trap !== null) return { itemIdx: idxL, opts: { cell: trap } };
    const idxZ = p.items.indexOf('luzhang');
    if (idxZ !== -1 && trap !== null) return { itemIdx: idxZ, opts: { cell: trap } };
    // 炸弹：扔对手最值钱街中心
    let leader = null, lv = -1;
    for (const op of rmAlivePlayers(st)) { if (op.seat === p.seat) continue; const v = rmTotalAsset(st, op); if (v > lv) { lv = v; leader = op; } }
    const idxB = p.items.indexOf('zhadan');
    if (idxB !== -1 && leader) {
      const street = rmBestStreetOf(st, leader.seat);
      if (street) {
        let bestCell = -1, bv = -1;
        for (const i of street) { const l = st.lands[i]; if (l.owner === leader.seat) { const v = rmLandValue(st, i); if (v > bv) { bv = v; bestCell = i; } } }
        if (bestCell !== -1 && bv > 22000 && rmDistance(p.pos, bestCell, p.dir) > 3) return { itemIdx: idxB, opts: { cell: bestCell } };
      }
    }
    // 飞弹：炸对手最高房屋
    const idxF = p.items.indexOf('feidan');
    if (idxF !== -1) {
      let bl = -1, bv2 = 0;
      for (const op of st.players) {
        if (!op || op.eliminated || op.seat === seat) continue;
        for (const li of op.lands) {
          const l = st.lands[li], cell = RM_MAP[li];
          const v = l.houses + (l.build !== 'none' ? 6 : 0) + cell.price / 20000;
          if ((l.houses >= 3 || (l.build !== 'none' && l.build !== 'park')) && v > bv2) { bv2 = v; bl = li; }
        }
      }
      if (bl !== -1) return { itemIdx: idxF, opts: { land: bl } };
    }
    // 遥控骰子：在「下一步期望明显差于可选最好」时用（本回合未掷骰前由调度层调用）
    return null;
  }

  // ========== 决策：商店购物 ==========
  function rmAiShop(st, seat, level) {
    const p = st.players[seat];
    const lvl = difficultyLevel(level);
    const buys = [];
    // 先补点券（现金富裕时）
    if (p.money > 60000) { const spend = Math.min(p.money - 50000, 20000); rmBuyPoints(st, p, spend); }
    if (lvl === 'fast') {
      // 入门：随便买
      const all = RM_CARD_KEYS.concat(RM_ITEM_KEYS);
      for (let i = 0; i < 3; i++) {
        const k = all[Math.floor(Math.random() * all.length)];
        const def = RM_CARDS[k] || RM_ITEMS[k];
        if (def && p.points >= def.cost) {
          if (RM_CARDS[k]) rmShopBuyCard(st, p, k); else rmShopBuyItem(st, p, k);
        }
      }
      return;
    }
    // 中级/高级：优先进攻卡 + 防御被动
    const wantCards = ['chashui', 'xianhai', 'junfu', 'dongmian', 'guaishou', 'mianzui', 'jiahuo', 'fuchou', 'paimai', 'goudi', 'chafeng', 'tianshi', 'mianfei', 'songshen'];
    const wantItems = ['remote', 'dilei', 'feidan', 'luzhang', 'zhadan'];
    if (p.god && ['qiongshen', 'shuaishen', 'sishen'].indexOf(p.god.name) !== -1) {
      if (p.points >= RM_CARDS.songshen.cost) { rmShopBuyCard(st, p, 'songshen'); return; }
    }
    for (const k of wantCards) {
      if (p.cards.length >= 8) break;
      if (p.points >= RM_CARDS[k].cost && p.cards.filter(function (c) { return c === k; }).length < 2) { rmShopBuyCard(st, p, k); buys.push(k); }
      if (p.points < 60) break;
    }
    for (const k of wantItems) {
      if (p.items.length >= 8) break;
      if (p.points >= RM_ITEMS[k].cost && !p.items.includes(k)) { rmShopBuyItem(st, p, k); buys.push(k); }
      if (p.points < 50) break;
    }
  }

  // ========== 决策：股市 ==========
  function rmAiStock(st, seat, level) {
    const p = st.players[seat];
    const lvl = difficultyLevel(level);
    if (lvl === 'fast') {
      if (Math.random() < 0.5 && p.money > 30000) {
        const i = Math.floor(Math.random() * st.stocks.length);
        rmBuyStock(st, p, i, Math.max(1, Math.floor(Math.min(p.money - 20000, 20000) / st.stocks[i].price)));
      } else {
        const held = p.stocks.map(function (v, i) { return [v, i]; }).filter(function (x) { return x[0] > 0; });
        if (held.length && Math.random() < 0.6) {
          const h = held[Math.floor(Math.random() * held.length)];
          rmSellStock(st, p, h[1], Math.max(1, Math.floor(h[0] / 2)));
        }
      }
      return;
    }
    // 中/高级：低吸高抛 + 预留现金
    const reserve = rmAiCashReserve(st, p);
    // 先卖：涨幅过大的/超过仓位上限的/现金紧张的
    for (let i = 0; i < st.stocks.length; i++) {
      const held = p.stocks[i];
      if (!held) continue;
      const v = held * st.stocks[i].price;
      const total = rmTotalAsset(st, p);
      if (st.stocks[i].price >= 135 || v > total * 0.35 || p.money < reserve * 0.8) {
        rmSellStock(st, p, i, held);
      }
    }
    // 后买：价格偏低且现金宽裕（仓位上限：单股不超过总资产 15%，防止股市空转）
    const totalA = rmTotalAsset(st, p);
    if (p.money > reserve + 25000 && rmStockValue(st, p) < totalA * 0.25) {
      let bi = -1, bp = Infinity;
      for (let i = 0; i < st.stocks.length; i++) {
        if (st.stocks[i].price < bp) { bp = st.stocks[i].price; bi = i; }
      }
      if (bi !== -1 && bp <= 105 && p.stocks[bi] * st.stocks[bi].price < totalA * 0.15) {
        const spend = Math.min(p.money - reserve - 10000, 15000);
        if (spend > 0) rmBuyStock(st, p, bi, Math.max(1, Math.floor(spend / st.stocks[bi].price)));
      }
    }
  }
  // __RM_AI_END__
  // ========== 大富翁：实时存档 / 恢复 / 对局记录 / 陪聊 ==========
  let rmGame = null;
  let rmAiTimer = null;
  let rmGenCounter = 0;
  let rmChatBusy = false;

  function rmSaveState() {
    const st = rmGame;
    if (!st || st.phase === 'ended') { rmClearSaved(); return; }
    try {
      const data = JSON.parse(JSON.stringify(st));
      data.pending = st.pending;
      data.speeches = (st.speeches || []).slice(-30);
      data.log = (st.log || []).slice(-260);
      localStorage.setItem(RM_SAVE_KEY, JSON.stringify(data));
    } catch (e) { /* ignore */ }
  }
  function rmClearSaved() { try { localStorage.removeItem(RM_SAVE_KEY); } catch (e) { /* ignore */ } }
  function rmHasSaved() {
    try {
      const raw = localStorage.getItem(RM_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && Array.isArray(d.players) && d.players.length >= 2 && d.phase && d.phase !== 'ended');
    } catch (e) { return false; }
  }
  function rmResumeSaved() {
    try {
      const raw = localStorage.getItem(RM_SAVE_KEY);
      if (!raw) { renderRmLobby(); return; }
      const d = JSON.parse(raw);
      rmGenCounter++;
      rmChatBusy = false;
      if (rmAiTimer) { clearTimeout(rmAiTimer); rmAiTimer = null; }
      rmGame = d;
      rmGame.moving = false;
      rmGame.isThinking = false;
      rmGame.resultRecorded = false;
      rmGame.lastSpeechAt = 0;
      if (!rmGame.players[rmGame.turnSeat]) rmGame.turnSeat = 0;
      rmSaveState();
      renderRmGameUI();
      showToast('🏙️ 已恢复进行中的大富翁对局');
      const cur = rmGame.players[rmGame.turnSeat];
      if (rmGame.pending) { if (cur && !cur.isUser) rmAiHandlePending(); }
      else if (rmGame.rolled) {
        // 已掷骰/已结算：接着收尾（AI 继续用卡/结束回合），绝不重开回合，避免重复结算状态或让玩家二次掷骰
        if (cur && !cur.isUser) rmDelay(function () { rmAiPostUseAndEnd(rmGame.turnSeat); }, 700);
      }
      else if (rmGame.turnStarted === false || rmGame.turnStarted === undefined) { rmBeginTurn(); }
      else if (cur && !cur.isUser) rmScheduleAi(900);
    } catch (e) { renderRmLobby(); }
  }

  function startRmGame(names) {
    rmGenCounter++;
    rmChatBusy = false;
    if (rmAiTimer) { clearTimeout(rmAiTimer); rmAiTimer = null; }
    rmGame = rmBuildGame(names);
    const cfg = loadRmConfig();
    cfg.partnerNames = rmGame.players.filter(function (p) { return !p.isUser; }).map(function (p) { return p.name; });
    saveRmConfig(cfg);
    rmLog(rmGame, '🏙️ 新对局开始：' + rmGame.players.map(function (p) { return p.name + '（' + rmFmtMoney(rmGame.initialMoney) + '）'; }).join('、') + ' · ' + (rmGame.winMode === 'bankrupt' ? '破产制：撑到最后' : rmGame.winMode === 'rounds' ? '限时制 ' + rmGame.roundLimit + ' 回合' : '资产达标：' + rmFmtMoney(rmGame.targetAsset)), '#0EA5E9', { kind: 'end' });
    rmLog(rmGame, '🎲 ' + rmGame.players[rmGame.turnSeat].name + ' 先手', '#F59E0B', { kind: 'end' });
    rmSaveState();
    rmBeginTurn();
  }
  function rmDelay(fn, ms) {
    const gen = rmGenCounter;
    if (rmAiTimer) { clearTimeout(rmAiTimer); rmAiTimer = null; }
    rmAiTimer = setTimeout(function () {
      rmAiTimer = null;
      if (gen !== rmGenCounter || !rmGame) return;
      fn();
    }, ms || 600);
  }
  function rmScheduleAi(delay) {
    const st = rmGame;
    if (!st || st.phase === 'ended') return;
    const p = st.players[st.turnSeat];
    if (!p || p.isUser || p.eliminated) return;
    st.isThinking = true;
    const gen = rmGenCounter;
    if (rmAiTimer) { clearTimeout(rmAiTimer); rmAiTimer = null; }
    rmAiTimer = setTimeout(function () {
      rmAiTimer = null;
      if (gen !== rmGenCounter || !rmGame || rmGame.phase === 'ended') return;
      rmGame.isThinking = false;
      rmAiTick();
    }, delay || 800);
  }

  // ========== 回合流（用户与 AI 共用） ==========
  // 每回合统一入口：状态结算（住院/坐牢/冬眠/停留/神明计时）→ 掷骰阶段 → 调度 AI 或等待用户
  function rmBeginTurn() {
    const st = rmGame;
    if (!st || st.phase === 'ended') return;
    const seat = st.turnSeat;
    const p = st.players[seat];
    if (!p || p.eliminated) { rmDelay(function () { rmEndTurn(); }, 400); return; }
    st.turnStarted = true;
    st.rolled = false;
    st.remoteDice = 0;
    const status = rmTurnStartStatus(st, p);
    st.actionCount++;
    rmSaveState();
    renderRmGameUI();
    if (status === 'skip') {
      rmDelay(function () { rmEndTurn(); }, 900);
      return;
    }
    st.phase = 'roll';
    renderRmGameUI();
    rmMaybeAutoSpeak('turn', seat);
    if (!p.isUser) rmScheduleAi(900);
  }
  function rmEndTurn() {
    const st = rmGame;
    if (!st || st.phase === 'ended') return;
    st.pending = null;
    st.rolled = false;
    st.remoteDice = 0;
    st.turnStarted = false;
    rmCheckGameEnd(st);
    if (st.winnerSeat !== null && st.winnerSeat !== undefined) { rmOnGameOver(); return; }
    rmEndTurnAdvance(st);
    rmBeginTurn();
  }
  function rmRollAndMove(seat, n, remoteValue) {
    const st = rmGame;
    const p = st.players[seat];
    if (!st || !p || st.moving || st.phase !== 'roll' || st.rolled) return;
    st.moving = true;
    st.rolled = true;
    const dice = rmRollDice(st, p, n, remoteValue);
    const steps = dice.reduce(function (a, b) { return a + b; }, 0);
    rmLog(st, '🎲 ' + p.name + ' 掷出 ' + dice.join(' + ') + ' = ' + steps + ' 点' + (remoteValue ? '（遥控骰子）' : ''), '#F59E0B', { seat: seat, kind: 'roll' });
    rmSaveState();
    renderRmGameUI();
    rmRunTokenAnimation(seat, steps, function () {
      const pend = rmLandingResolve(st, p);
      st.pending = pend;
      st.moving = false;
      rmSaveState();
      renderRmGameUI();
      rmMaybeAutoSpeak('roll', seat);
      if (pend && !p.isUser) rmAiHandlePending();
      else if (!pend && !p.isUser) rmDelay(function () { rmAiPostUseAndEnd(seat); }, 650);
    });
  }
  // 棋子逐步动画
  function rmTokenEl(seat) {
    if (!sheet) return null;
    return sheet.querySelector('[data-rm-act="rm-token"][data-seat="' + seat + '"]');
  }
  function rmSetTokenEl(seat, pos) {
    const el = rmTokenEl(seat);
    if (!el || !rmGame || !rmGame.players[seat]) return;
    const pt = rmTokenXY(rmGame.players[seat], pos);
    el.style.left = pt.x + '%';
    el.style.top = pt.y + '%';
  }
  function rmRunTokenAnimation(seat, steps, done) {
    const st = rmGame;
    const gen = rmGenCounter;
    const p = st.players[seat];
    // 逻辑先行：rmMoveSteps 会按路障等效果提前停下，落点以实际移动结果为准
    const realPath = rmMoveSteps(st, p, steps);
    if (!rmTokenEl(seat)) { if (typeof done === 'function') done(); return; }
    let idx = 0;
    const tick = function () {
      if (gen !== rmGenCounter || !rmGame) return;
      if (idx >= realPath.length) { if (typeof done === 'function') done(); return; }
      rmSetTokenEl(seat, realPath[idx]);
      idx++;
      setTimeout(tick, 130);
    };
    setTimeout(tick, 60);
  }

  // ========== AI 回合执行 ==========
  function rmAiTick() {
    const st = rmGame;
    if (!st || st.phase === 'ended') return;
    const seat = st.turnSeat;
    const p = st.players[seat];
    if (!p || p.isUser || p.eliminated) { renderRmGameUI(); return; }
    st.aiLevel = liveAiLevel(loadRmConfig, st.aiLevel);
    const lvl = difficultyLevel(st.aiLevel);
    if (st.phase === 'roll') {
      if (st.rolled) { // 已掷过骰（动画/落点流程进行中），转由 pending/收尾链路接管
        const pend2 = st.pending;
        if (pend2 && !p.isUser) { rmAiHandlePending(); return; }
        if (!pend2 && !p.isUser) { rmDelay(function () { rmAiPostUseAndEnd(seat); }, 500); return; }
        return;
      }
      // 掷骰前：送神卡 / 遥控骰子（失败则照常掷骰，绝不原地重试）
      if (p.god && ['qiongshen', 'shuaishen'].indexOf(p.god.name) !== -1) {
        const si = p.cards.indexOf('songshen');
        if (si !== -1) {
          const rr = rmUseCard(st, p, si, {});
          if (rr && rr.ok) { rmSaveState(); renderRmGameUI(); rmScheduleAi(600); return; }
        }
      }
      const ri = p.items.indexOf('remote');
      if (ri !== -1 && p.turtleTurns <= 0) {
        const pick = rmAiRemoteValue(st, seat);
        const expBest = (function () {
          let m = -1e9;
          const opts = rmVehicleDice(st.vehicle);
          for (const n of opts) for (const o of rmDiceOutcomes(n)) m = Math.max(m, rmAiMoveScore(st, p, o.steps));
          return m;
        })();
        if (pick.score - expBest > 3) {
          const rr = rmUseItem(st, p, ri, { dice: pick.value });
          if (rr && rr.ok) { rmSaveState(); renderRmGameUI(); rmScheduleAi(600); return; }
        }
      }
      const n = rmAiPickDiceCount(st, seat, lvl);
      const rv = st.remoteDice; st.remoteDice = 0;
      rmRollAndMove(seat, n, rv);
      return;
    }
    if (st.phase === 'post') {
      rmAiPostUseAndEnd(seat);
      return;
    }
  }
  function rmAiHandlePending() {
    const st = rmGame;
    if (!st || !st.pending) return;
    const seat = st.turnSeat;
    const p = st.players[seat];
    const lvl = difficultyLevel(st.aiLevel);
    const pend = st.pending;
    const dec = rmAiDecidePending(st, seat, lvl, pend);
    if (pend.type === 'buy') {
      if (dec.act === 'buy') {
        const r = rmDoBuyLand(st, p, pend.land);
        if (!r.ok) showToast(r.msg || '购买失败');
      } else if (st.auctionEnabled) {
        rmAuctionStart(st, pend.land, { auto: true });
        rmAiRunAuctionAuto();
      } else {
        rmLog(st, '🔨 拍卖已关闭，【' + RM_MAP[pend.land].name + '】继续空置', '#9CA3AF', { kind: 'auction' });
      }
    } else if (pend.type === 'upgrade') {
      if (dec.act === 'upgrade') rmDoUpgrade(st, p, pend.land);
    } else if (pend.type === 'bigBuild') {
      if (dec.act === 'build') rmDoBigBuild(st, p, pend.land, dec.build);
    } else if (pend.type === 'rent') {
      if (dec.act === 'freecard') {
        p.cards.splice(dec.freeIdx, 1);
        rmLog(st, '🎟️ ' + p.name + ' 使用【免费卡】免付租金 ' + rmFmtMoney(pend.amount), '#22C55E', { seat: seat, kind: 'card' });
      } else {
        rmLog(st, '💸 ' + p.name + ' 向 ' + st.players[pend.creditorSeat].name + ' 支付租金 -' + rmFmtMoney(pend.amount) + '（' + RM_MAP[pend.land].name + ' ' + (st.lands[pend.land].houses || 0) + ' 层）', '#EF4444', { seat: seat, kind: 'money' });
        rmCharge(st, p, pend.amount, { kind: 'rent', creditorSeat: pend.creditorSeat });
      }
    } else if (pend.type === 'companyBuy') {
      if (dec.act === 'buy') rmDoCompanyBuy(st, p, pend.cell);
    } else if (pend.type === 'shop') {
      rmAiShop(st, seat, lvl);
    } else if (pend.type === 'stock') {
      rmAiStock(st, seat, lvl);
    }
    st.pending = null;
    rmSaveState();
    renderRmGameUI();
    rmDelay(function () { rmAiPostUseAndEnd(seat); }, 700);
  }
  function rmAiRunAuctionAuto() {
    const st = rmGame;
    let guard = 0;
    while (st && st.auction && !st.auction.done && guard++ < 50) {
      const a = st.auction;
      const bidder = a.bidders[a.turnIdx % a.bidders.length];
      a.turnIdx++;
      if (bidder === undefined || !st.players[bidder] || st.players[bidder].eliminated || a.passed.indexOf(bidder) !== -1) continue;
      const otherAlive = rmAuctionAliveBidders(st).filter(function (x) { return x !== a.highSeat; });
      if (a.highSeat >= 0 && otherAlive.length === 0) { rmAuctionResolve(st); break; }
      const lvl = difficultyLevel(st.players[bidder].isUser ? 'normal' : st.aiLevel);
      const cap = rmAiAuctionMaxBid(st, bidder, a.land, lvl);
      const next = a.current + a.minInc;
      if (a.highSeat !== bidder && cap >= next) rmAuctionBid(st, bidder, next);
      else rmAuctionPass(st, bidder);
    }
    if (st && st.auction && !st.auction.done) rmAuctionResolve(st);
    rmSaveState();
    renderRmGameUI();
  }
  function rmAiPostUseAndEnd(seat) {
    const st = rmGame;
    if (!st || st.phase === 'ended') return;
    const p = st.players[seat];
    if (!p || p.isUser) return;
    const lvl = difficultyLevel(st.aiLevel);
    // 每回合最多用一张卡 + 一个道具
    const card = rmAiUseCard(st, seat, lvl);
    if (card) {
      const r = rmUseCard(st, p, card.cardIdx, card.opts);
      if (r.ok) {
        rmSaveState(); renderRmGameUI();
        rmMaybeAutoSpeak('card', seat);
        if (r.auction) { rmAiRunAuctionAuto(); }
        rmDelay(function () { rmAiPostUseAndEnd(seat); }, 700);
        return;
      }
    }
    const item = rmAiUseItem(st, seat, lvl);
    if (item) {
      const r = rmUseItem(st, p, item.itemIdx, item.opts);
      if (r.ok) { rmSaveState(); renderRmGameUI(); }
    }
    rmDelay(function () { rmEndTurn(); }, 750);
  }
  function rmOnGameOver() {
    const st = rmGame;
    if (!st || (st.winnerSeat === null || st.winnerSeat === undefined)) return;
