    st.moving = false;
    if (rmAiTimer) { clearTimeout(rmAiTimer); rmAiTimer = null; }
    rmClearSaved();
    renderRmGameUI();
    renderRmResultModal();
    rmRecordFinished();
    rmMaybeAutoSpeak('end', st.winnerSeat, true);
  }

  // ========== 大富翁：对局记录与联动 ==========
  function rmPlayerResultLine() {
