      const userWon = st.winnerSeat === 0;
      const replayText = (st.log || []).map(function (e) { return e.text; }).filter(Boolean).slice(-100).join('\n');
      const detail = '玩家：' + st.players.map(function (p) { return p.name + (p.isUser ? '（主角）' : ''); }).join('、') +
        '；初始资金 ' + rmFmtMoney(st.initialMoney) + ' · ' + (st.winMode === 'bankrupt' ? '破产制' : st.winMode === 'rounds' ? '限时 ' + st.roundLimit + ' 回合' : '达标 ' + rmFmtMoney(st.targetAsset)) +
        '；进行了 ' + st.round + ' 回合 / ' + (st.actionCount || 0) + ' 次行动';
      onGameFinished({
        gameType: 'richman',
