        replayRich: {
          logs: (st.log || []).map(function (e) { return { text: e.text, authorPos: (e.seat === null || e.seat === undefined) ? null : e.seat, type: 'public', color: e.color || '' }; }),
          players: st.players.map(function (p) {
            return { position: p.seat, name: p.name, isUser: !!p.isUser, avatar: p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name)) || '' };
          })
        },
        players: st.players.map(function (p) { return { name: p.name, isUser: p.isUser, avatar: p.avatar || '' }; })
      });
    } catch (e) { /* ignore */ }
  }

  // ========== 大富翁：角色 AI 陪聊 ==========
  function rmPushSpeech(seat, text) {
