        const pl = st.players[e.seat];
        return '<div style="display:flex;align-items:flex-start;gap:5px;' + rowStyle + '">' +
          '<span style="flex:none;margin-top:1px;">' + chatAvatarHTML(pl.name, !!pl.isUser, 18) + '</span>' +
          '<span style="flex:1;min-width:0;word-break:break-word;">' + escapeHtml(e.text) + '</span></div>';
      }
      return '<div style="' + rowStyle + '">' + escapeHtml(e.text) + '</div>';
    }).join('');
  }

  // ========== 大富翁：主界面 ==========
  function renderRmGameUI() {
    if (!rmGame) { renderRmLobby(); return; }
    const st = rmGame;
    const me = st.players[0];
    const isEnded = st.phase === 'ended';
    const winner = (st.winnerSeat !== null && st.winnerSeat !== undefined) ? st.players[st.winnerSeat] : null;
    const curP = st.players[st.turnSeat];
    let statusText = '';
    if (isEnded) statusText = winner ? (winner.isUser ? '🎉 你赢了！' : '💔 ' + escapeHtml(winner.name) + ' 获胜') : '本局结束';
    else if (st.turnSeat === 0) {
      if (st.phase === 'roll') statusText = '👉 轮到你：选择骰子数量并掷骰';
      else if (st.pending) statusText = '👉 处理当前格子事件（见自己信息卡）';
      else if (st.moving) statusText = '🚶 移动中…';
      else statusText = '👉 回合内可用卡片/道具，然后点【结束回合】';
    } else statusText = '⏳ 等待 ' + escapeHtml(curP ? curP.name : '') + ' 行动…';

    const chatHTML = st.aiChat ? (
      '<div id="rm-speech-container" style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:8px;padding:5px 9px;margin-top:5px;flex:none;height:86px;max-height:86px;overflow-y:auto;box-sizing:border-box;">' +
      '<div id="rm-speech-text" style="font-size:11.5px;line-height:1.5;word-break:break-word;">' + rmRenderSpeechHTML() + '</div></div>' +
      '<div style="display:flex;gap:6px;margin-top:5px;flex:none;">' +
      '<input id="rm-chat-input" class="ubp-fieldinput" type="text" placeholder="对棋盘边的角色说点什么…（如：这条街我全要了）" style="flex:1;font-size:12px;padding:4px 8px;border-radius:6px;height:26px;">' +
      '<button data-rm-act="rm-send-chat" class="ubp-btn primary" style="padding:0 10px;font-size:12px;height:26px;background:#0EA5E9;flex:none;">发送</button></div>'
    ) : '';
    const prevSpeechBox = sheet.querySelector('#rm-speech-container');
    const prevLogBox = sheet.querySelector('#rm-log-scroll');
    const speechAtBottom = !prevSpeechBox || (prevSpeechBox.scrollTop + prevSpeechBox.clientHeight >= prevSpeechBox.scrollHeight - 12);
    const speechScrollTop = prevSpeechBox ? prevSpeechBox.scrollTop : 0;
    const logAtBottom = !prevLogBox || (prevLogBox.scrollTop + prevLogBox.clientHeight >= prevLogBox.scrollHeight - 12);
    const logScrollTop = prevLogBox ? prevLogBox.scrollTop : 0;

    sheet.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;flex:none;">
        <div style="display:flex;align-items:center;gap:6px;min-width:0;">
          <button data-rm-act="rm-exit" style="background:none;border:none;font-size:16px;cursor:pointer;color:var(--ubp-text);flex:none;" title="返回大富翁大厅（自动保存）">←</button>
          <span style="font-size:14.5px;font-weight:bold;color:var(--ubp-text);white-space:nowrap;">🏙️ 大富翁4</span>
        </div>
        <div style="display:flex;align-items:center;gap:5px;flex:none;">
          <button data-rm-act="rm-openstock" class="ubp-btn" style="padding:3px 8px;font-size:10.5px;">📈 股市</button>
          <button data-rm-act="rm-openshop" class="ubp-btn" style="padding:3px 8px;font-size:10.5px;">🛒 商店</button>
          <span style="font-size:10px;color:var(--ubp-text-3);">${st.vehicle === 'walk' ? '🚶步行' : st.vehicle === 'motor' ? '🏍️机车' : '🚗汽车'}</span>
        </div>
      </div>
      <div style="font-size:11.5px;font-weight:600;color:${st.turnSeat === 0 && !isEnded ? '#22C55E' : 'var(--ubp-text-2)'};margin-bottom:5px;flex:none;">${statusText}</div>
      <div style="width:100%;max-width:350px;margin:0 auto 6px;flex:none;">${rmBoardHTML(st)}</div>
      <div style="flex:none;max-height:150px;overflow-y:auto;padding-right:2px;">${st.players.map(function (p) { return rmPlayerRowHTML(st, p); }).join('')}</div>
      <div style="flex:none;margin:4px 0 3px;"><div style="font-size:10.5px;color:var(--ubp-text-3);padding:0 2px 3px;">我的卡片 / 道具（点按使用）</div>
        <div style="display:flex;flex-wrap:wrap;gap:4px;">${rmMyCardItemRowHTML(st, me)}</div></div>
      <div style="flex:none;display:flex;justify-content:space-between;align-items:center;padding:0 2px;">
        <span style="font-size:10.5px;color:var(--ubp-text-3);">棋局日志</span>
        <span style="font-size:10.5px;color:var(--ubp-text-3);">我：总资产 ${rmFmtMoney(rmTotalAsset(st, me))}</span>
      </div>
      <div id="rm-log-scroll" style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:8px;padding:5px 8px;height:70px;max-height:70px;overflow-y:auto;margin-top:3px;flex:none;">${rmLogHTML()}</div>
      ${chatHTML}
      ${!isEnded && st.turnSeat === 0 && st.phase === 'roll' && st.rolled && !st.moving && !st.pending ? '<div style="margin-top:6px;flex:none;"><button data-rm-act="rm-endturn" class="ubp-btn primary" style="width:100%;padding:9px 0;font-size:13px;background:#22C55E;">✅ 结束回合</button></div>' : ''}
    `;
    const newSpeechBox = sheet.querySelector('#rm-speech-container');
    if (newSpeechBox) newSpeechBox.scrollTop = speechAtBottom ? newSpeechBox.scrollHeight : speechScrollTop;
    const newLogBox = sheet.querySelector('#rm-log-scroll');
    if (newLogBox) newLogBox.scrollTop = logAtBottom ? newLogBox.scrollHeight : logScrollTop;
    const input = sheet.querySelector('#rm-chat-input');
    if (input) input.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); rmHandleUserChat(); } });
  }

  // ========== 大富翁：覆盖层（目标选择 / 商店 / 股市 / 拍卖 / 结算） ==========
  function rmOverlay(title, innerHTML, z) {
    const old = sheet.querySelector('.rm-ovl');
    if (old) old.remove();
    const ov = document.createElement('div');
    ov.className = 'rm-ovl';
    ov.style.cssText = 'position:absolute;inset:0;z-index:' + (z || 60) + ';background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex:none;">' +
      '<span style="font-size:15px;font-weight:bold;color:var(--ubp-text);">' + title + '</span>' +
      '<button data-rm-act="rm-ovl-close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
      '<div style="flex:1;overflow-y:auto;padding-right:2px;">' + innerHTML + '</div>';
    sheet.appendChild(ov);
    return ov;
  }
  // 目标选择：对手 / 对手地 / 自己地(大商业) / 股票 / 任意玩家 / 点数
  function renderRmTargetPicker(mode, cb, opts) {
    opts = opts || {};
    const st = rmGame;
    const me = st.players[0];
    let inner = '';
    const btn = function (dataAttrs, label, sub) {
      return '<div ' + dataAttrs + ' style="display:flex;justify-content:space-between;align-items:center;padding:9px 11px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);">' +
        '<span style="font-size:12.5px;color:var(--ubp-text);font-weight:600;">' + label + '</span>' +
        (sub ? '<span style="font-size:10.5px;color:var(--ubp-text-3);">' + sub + '</span>' : '') + '</div>';
    };
    if (mode === 'player') {
      inner = st.players.filter(function (p) { return p.seat !== 0 && !p.eliminated; }).map(function (p) {
        return btn('data-rm-pick="' + p.seat + '"', escapeHtml(p.name), '现金 ' + rmFmtMoney(p.money) + ' · 地 ' + p.lands.length);
      }).join('');
    } else if (mode === 'playerAny') {
      inner = st.players.filter(function (p) { return !p.eliminated; }).map(function (p) {
        return btn('data-rm-pick="' + p.seat + '"', escapeHtml(p.name) + (p.isUser ? '（我）' : ''), '现金 ' + rmFmtMoney(p.money));
      }).join('');
    } else if (mode === 'enemyLand') {
      const items = [];
      for (const p of st.players) {
        if (p.seat === 0 || p.eliminated) continue;
        for (const i of p.lands) {
          const land = st.lands[i], cell = RM_MAP[i];
          if (land.houses > 0 || (cell.type === 'bigland' && land.build !== 'none')) items.push({ i: i, p: p, v: rmLandValue(st, i) });
        }
      }
      items.sort(function (a, b) { return b.v - a.v; });
      inner = items.length ? items.map(function (x) {
        return btn('data-rm-pick="' + x.i + '"', '【' + RM_MAP[x.i].name + '】' + (st.lands[x.i].houses ? st.lands[x.i].houses + '层' : RM_BIG_BUILDS[st.lands[x.i].build].name), x.p.name + ' · 值 ' + rmFmtMoney(x.v));
      }).join('') : '<div style="font-size:12px;color:var(--ubp-text-3);">对手还没有可炸的建筑</div>';
    } else if (mode === 'myBigLand') {
      inner = me.lands.filter(function (i) { return RM_MAP[i].type === 'bigland' && st.lands[i].build !== 'none'; }).map(function (i) {
        return btn('data-rm-pick="' + i + '"', '【' + RM_MAP[i].name + '】' + RM_BIG_BUILDS[st.lands[i].build].name, '');
      }).join('') || '<div style="font-size:12px;color:var(--ubp-text-3);">你还没有已建成的商业地</div>';
    } else if (mode === 'bigType') {
      inner = Object.keys(RM_BIG_BUILDS).filter(function (k) { return k !== 'none'; }).map(function (k) {
        const b = RM_BIG_BUILDS[k];
        return btn('data-rm-pick="' + k + '"', b.icon + ' ' + b.name, b.desc);
      }).join('');
    } else if (mode === 'stock') {
      inner = st.stocks.map(function (s, i) {
        return btn('data-rm-pick="' + i + '"', s.name, '现价 ' + s.price + ' · 我持 ' + me.stocks[i]);
      }).join('');
    } else if (mode === 'dice') {
      inner = [1, 2, 3, 4, 5, 6].map(function (v) {
        return btn('data-rm-pick="' + v + '"', ['⚀', '⚁', '⚂', '⚃', '⚄', '⚅'][v - 1] + ' 走 ' + v + ' 步', '');
      }).join('');
    } else if (mode === 'placeCell') {
      // 放道具：给出前方 12 格候选
      const opts2 = [];
      for (let d = 1; d <= 12; d++) {
        const idx = (me.pos + d) % RM_MAP_LEN;
        opts2.push(idx);
      }
      inner = opts2.map(function (idx) {
        const land = st.lands[idx];
        const own = land && land.owner === 0 ? '（我的地）' : land && land.owner >= 0 ? '（' + st.players[land.owner].name + '的地）' : '';
        return btn('data-rm-pick="' + idx + '"', '第 ' + (idx + 1) + ' 格 · ' + RM_MAP[idx].name + own, '');
      }).join('');
    }
    const ov = rmOverlay(opts.title || '选择目标', inner + '<div style="display:flex;justify-content:flex-end;margin-top:4px;"><button data-rm-pick="-1" class="ubp-btn" style="padding:6px 16px;font-size:12px;">取消</button></div>');
    ov.querySelectorAll('[data-rm-pick]').forEach(function (el) {
      el.addEventListener('click', function () {
        const v = el.getAttribute('data-rm-pick');
        ov.remove();
        if (v !== '-1') cb(isNaN(parseInt(v)) ? v : parseInt(v));
      });
    });
  }
  // 商店
  function renderRmShop() {
    const st = rmGame;
    const me = st.players[0];
    const cardRows = RM_CARD_KEYS.map(function (k) {
      const d = RM_CARDS[k];
      return '<div style="display:flex;justify-content:space-between;align-items:center;padding:7px 9px;border-radius:8px;margin-bottom:5px;background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);">' +
        '<div style="flex:1;min-width:0;margin-right:8px;"><div style="font-size:12px;font-weight:600;color:var(--ubp-text);">' + d.icon + ' ' + d.name + '</div>' +
        '<div style="font-size:10px;color:var(--ubp-text-3);line-height:1.4;">' + d.desc + '</div></div>' +
        '<button data-rm-shop="card:' + k + '" class="ubp-btn primary" style="padding:4px 9px;font-size:11px;background:#A855F7;flex:none;' + (me.points < d.cost || me.cards.length >= 8 ? 'opacity:0.4;pointer-events:none;' : '') + '">' + d.cost + '券</button></div>';
    }).join('');
    const itemRows = RM_ITEM_KEYS.map(function (k) {
      const d = RM_ITEMS[k];
      return '<div style="display:flex;justify-content:space-between;align-items:center;padding:7px 9px;border-radius:8px;margin-bottom:5px;background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);">' +
        '<div style="flex:1;min-width:0;margin-right:8px;"><div style="font-size:12px;font-weight:600;color:var(--ubp-text);">' + d.icon + ' ' + d.name + '</div>' +
        '<div style="font-size:10px;color:var(--ubp-text-3);line-height:1.4;">' + d.desc + '</div></div>' +
        '<button data-rm-shop="item:' + k + '" class="ubp-btn primary" style="padding:4px 9px;font-size:11px;background:#EC4899;flex:none;' + (me.points < d.cost || me.items.length >= 8 ? 'opacity:0.4;pointer-events:none;' : '') + '">' + d.cost + '券</button></div>';
    }).join('');
    const inner = '<div style="background:var(--ubp-card-2);border-radius:10px;padding:10px 11px;margin-bottom:10px;border:1px solid var(--ubp-line);">' +
      '<div style="font-size:12.5px;font-weight:600;color:var(--ubp-text);">💵 现金 ' + rmFmtMoney(me.money) + ' · 🎟️ 点券 ' + me.points + '</div>' +
      '<div style="display:flex;gap:5px;margin-top:7px;">' + [5000, 10000, 20000].map(function (v) {
        return '<button data-rm-shop="points:' + v + '" class="ubp-btn" style="padding:4px 8px;font-size:10.5px;' + (me.money < v ? 'opacity:0.4;pointer-events:none;' : '') + '">兑 ' + (v / 100) + ' 券（' + rmFmtMoney(v) + '）</button>';
      }).join('') + '</div></div>' +
      '<div style="font-size:12px;font-weight:600;color:var(--ubp-text);margin:4px 2px 6px;">🃏 卡片（' + me.cards.length + '/8）</div>' + cardRows +
      '<div style="font-size:12px;font-weight:600;color:var(--ubp-text);margin:8px 2px 6px;">🎁 道具（' + me.items.length + '/8）</div>' + itemRows;
    const ov = rmOverlay('🛒 道具商店', inner);
    ov.querySelectorAll('[data-rm-shop]').forEach(function (el) {
      el.addEventListener('click', function () {
        const v = el.getAttribute('data-rm-shop');
        const me2 = rmGame.players[0];
        if (v.indexOf('points:') === 0) rmBuyPoints(rmGame, me2, parseInt(v.slice(7)));
        else if (v.indexOf('card:') === 0) { const r = rmShopBuyCard(rmGame, me2, v.slice(5)); if (!r.ok && r.msg) showToast(r.msg); }
        else if (v.indexOf('item:') === 0) { const r = rmShopBuyItem(rmGame, me2, v.slice(5)); if (!r.ok && r.msg) showToast(r.msg); }
        rmSaveState();
        ov.remove();
        renderRmShop();
        renderRmGameUIKeepOverlay('shop');
      });
    });
  }
  function renderRmGameUIKeepOverlay(kind) {
    renderRmGameUI();
    if (kind === 'shop') renderRmShop();
    else if (kind === 'stock') renderRmStock();
  }
  // 股市
  function renderRmStock() {
    const st = rmGame;
    const me = st.players[0];
    const rows = st.stocks.map(function (s, i) {
      const held = me.stocks[i];
      const v = held * s.price;
      return '<div style="display:flex;align-items:center;gap:6px;padding:8px 9px;border-radius:8px;margin-bottom:5px;background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);">' +
        '<div style="flex:1;min-width:0;"><div style="font-size:12px;font-weight:600;color:var(--ubp-text);">' + s.name + ' <b style="color:' + (s.price >= 100 ? '#22C55E' : '#EF4444') + ';">' + s.price + '</b></div>' +
        '<div style="font-size:10px;color:var(--ubp-text-3);">持有 ' + held + ' 股（' + rmFmtMoney(v) + '）</div></div>' +
        '<button data-rm-stock="buy:' + i + '" class="ubp-btn" style="padding:4px 8px;font-size:10.5px;' + (me.money < s.price * 10 ? 'opacity:0.4;pointer-events:none;' : '') + '">买 10</button>' +
        '<button data-rm-stock="sell:' + i + '" class="ubp-btn" style="padding:4px 8px;font-size:10.5px;' + (!held ? 'opacity:0.4;pointer-events:none;' : '') + '">卖 10</button>' +
        '<button data-rm-stock="sellall:' + i + '" class="ubp-btn" style="padding:4px 8px;font-size:10.5px;' + (!held ? 'opacity:0.4;pointer-events:none;' : '') + '">全卖</button></div>';
    }).join('');
    const inner = '<div style="font-size:11px;color:var(--ubp-text-3);margin-bottom:8px;line-height:1.6;">💵 现金 ' + rmFmtMoney(me.money) + ' · 📊 持仓 ' + rmFmtMoney(rmStockValue(st, me)) + '<br>股价每回合自动波动 ±4%；可用【红卡】拉涨、【黑卡】砸盘操纵对手持仓。</div>' + rows;
    const ov = rmOverlay('📈 证券交易所', inner);
    ov.querySelectorAll('[data-rm-stock]').forEach(function (el) {
      el.addEventListener('click', function () {
        const v = el.getAttribute('data-rm-stock');
        const i = parseInt(v.split(':')[1]);
        if (v.indexOf('buy:') === 0) rmBuyStock(rmGame, rmGame.players[0], i, 10);
        else if (v.indexOf('sellall:') === 0) rmSellStock(rmGame, rmGame.players[0], i, rmGame.players[0].stocks[i]);
        else if (v.indexOf('sell:') === 0) rmSellStock(rmGame, rmGame.players[0], i, 10);
        rmSaveState();
        ov.remove();
        renderRmGameUIKeepOverlay('stock');
      });
    });
  }
  // 用户拍卖界面
  function renderRmAuction() {
    const st = rmGame;
    if (!st.auction) return;
    const old = sheet.querySelector('.rm-auc');
    if (old) old.remove();
    const a = st.auction;
    const cell = RM_MAP[a.land];
    const ov = document.createElement('div');
    ov.className = 'rm-auc';
    ov.style.cssText = 'position:absolute;inset:0;z-index:65;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    ov.innerHTML = '<div style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:16px 14px;width:100%;max-width:300px;">' +
      '<div style="text-align:center;font-size:26px;margin-bottom:2px;">🔨</div>' +
      '<div style="text-align:center;font-size:14px;font-weight:bold;color:var(--ubp-text);">拍卖【' + cell.name + '】</div>' +
      '<div style="text-align:center;font-size:11px;color:var(--ubp-text-3);margin:4px 0 10px;">底价 ' + rmFmtMoney(Math.round(cell.price * 0.5)) + ' · 市场价 ' + rmFmtMoney(rmLandValue(st, a.land)) + '</div>' +
      '<div style="background:var(--ubp-card-2);border-radius:8px;padding:9px 11px;margin-bottom:10px;">' +
      '<div style="font-size:12px;color:var(--ubp-text);">当前最高：<b style="color:#F59E0B;">' + rmFmtMoney(a.current) + '</b>' + (a.highSeat >= 0 ? '（' + escapeHtml(st.players[a.highSeat].name) + '）' : '（无人出价）') + '</div>' +
      '<div style="font-size:10px;color:var(--ubp-text-3);margin-top:3px;">我的现金 ' + rmFmtMoney(st.players[0].money) + ' · 加价幅度 ≥' + rmFmtMoney(a.minInc) + '</div></div>' +
      '<div style="display:flex;flex-wrap:wrap;gap:5px;justify-content:center;margin-bottom:9px;">' +
      [1, 2, 4].map(function (m) { return '<button data-rm-auc="' + (a.current + a.minInc * m) + '" class="ubp-btn primary" style="padding:6px 10px;font-size:12px;background:#F59E0B;">出 ' + rmFmtMoney(a.current + a.minInc * m) + '</button>'; }).join('') +
      '<button data-rm-auc="pass" class="ubp-btn" style="padding:6px 12px;font-size:12px;">放弃</button></div>' +
      '<div style="font-size:9.5px;color:var(--ubp-text-3);text-align:center;">AI 对手正在自动竞价…</div></div>';
    sheet.appendChild(ov);
    ov.querySelectorAll('[data-rm-auc]').forEach(function (el) {
      el.addEventListener('click', function () {
        const v = el.getAttribute('data-rm-auc');
        if (v === 'pass') rmUserAuctionPass();
        else rmUserAuctionBid(parseInt(v));
      });
    });
  }
  function rmUserAuctionBid(amount) {
    const st = rmGame;
    if (!st.auction) return;
    if (amount > rmTotalAsset(st, st.players[0])) { showToast('你的总资产不够出这个价'); return; }
    const r = rmAuctionBid(st, 0, amount);
    if (!r.ok) { showToast(r.msg || '出价无效'); return; }
    rmRunAuctionLoop();
  }
  function rmUserAuctionPass() {
    const st = rmGame;
    if (!st.auction) return;
    rmAuctionPass(st, 0);
    rmRunAuctionLoop();
  }
  function rmRunAuctionLoop() {
    const st = rmGame;
    if (!st.auction) { renderRmGameUI(); return; }
    const gen = rmGenCounter;
    const a = st.auction;
    a.turnIdx++;
    const others = rmAuctionAliveBidders(st).filter(function (x) { return x !== 0; });
    const aliveAll = rmAuctionAliveBidders(st);
    if (aliveAll.length <= 1 || (a.highSeat >= 0 && aliveAll.every(function (x) { return x === a.highSeat; }))) {
      rmAuctionResolve(st);
      rmSaveState();
      renderRmGameUI();
      rmAfterUserPendingDone();
      return;
    }
    renderRmAuction();
    rmDelay(function () {
      if (gen !== rmGenCounter || !rmGame || !rmGame.auction) return;
      const a2 = rmGame.auction;
      const bidder = a2.bidders[a2.turnIdx % a2.bidders.length];
      if (bidder === 0) { renderRmAuction(); return; } // 等用户
      const p = st.players[bidder];
      if (!p || p.eliminated || a2.passed.indexOf(bidder) !== -1) { rmRunAuctionLoop(); return; }
      const cap = rmAiAuctionMaxBid(st, bidder, a2.land, difficultyLevel(st.aiLevel));
      const next = a2.current + a2.minInc;
      if (a2.highSeat !== bidder && cap >= next) rmAuctionBid(st, bidder, next);
      else rmAuctionPass(st, bidder);
      rmSaveState();
      rmRunAuctionLoop();
    }, 800);
  }
  // 用户处理完 pending / 拍卖后的收尾
  function rmAfterUserPendingDone() {
    const st = rmGame;
    if (!st || st.phase === 'ended') return;
    st.pending = null;
    rmSaveState();
    renderRmGameUI();
  }
