        '<div style="flex:1;overflow-y:auto;padding-right:2px;margin-bottom:8px;">' + (listHtml || '<div style="font-size:12px;color:var(--ubp-text-3);">通讯录暂无角色，请确保瑟瑟数据库已添加角色。</div>') + '</div>' +
        '<div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-rm-invite="confirm" class="ubp-btn primary" style="padding:6px 20px;background:' + (chosen.length ? '#0EA5E9' : '#6b7280') + ';font-size:13px;border-radius:6px;">确认邀请</button></div>';
      ov.querySelectorAll('[data-rm-pick-name]').forEach(function (el) {
        el.addEventListener('click', function () {
          const name = el.getAttribute('data-rm-pick-name');
          const i = chosen.findIndex(function (n) { return isNameMatch(n, name); });
          if (i !== -1) chosen.splice(i, 1);
          else { if (chosen.length >= 3) chosen.shift(); chosen.push(name); }
          renderContent();
        });
      });
      const closeBtn = ov.querySelector('[data-rm-invite="close"]');
      if (closeBtn) closeBtn.addEventListener('click', function () { ov.remove(); });
      const okBtn = ov.querySelector('[data-rm-invite="confirm"]');
      if (okBtn) okBtn.addEventListener('click', function () {
        if (!chosen.length) { showToast('请至少邀请 1 位角色'); return; }
        const c = loadRmConfig();
        c.partnerNames = chosen.slice(0, 3);
        saveRmConfig(c);
        ov.remove();
        if (typeof onConfirmed === 'function') onConfirmed(chosen.slice(0, 3));
        else renderRmLobby();
      });
    };
    renderContent();
    sheet.appendChild(ov);
  }

