        selRow('rm-set-level', '🧠 AI 智商强度', '入门＝随机乱玩；中级＝贪心买地盖楼 + 进攻卡 + 低吸高抛；强力＝落点蒙特卡洛预判（提前布雷/卡片博弈/预留现金防查税）。',
          '<option value="fast" ' + (c.aiLevel === 'fast' ? 'selected' : '') + '>入门</option>' +
          '<option value="normal" ' + (c.aiLevel === 'normal' ? 'selected' : '') + '>中级</option>' +
          '<option value="strong" ' + (c.aiLevel === 'strong' ? 'selected' : '') + '>强力</option>', c.aiLevel) +
