        selRow('rm-set-roundlimit', '⏱️ 限时制回合数', '仅在选择「限时制」胜利条件时生效。',
          [10, 20, 30, 40, 50, 60].map(function (v) { return '<option value="' + v + '" ' + (c.roundLimit === v ? 'selected' : '') + '>' + v + ' 回合</option>'; }).join(''), c.roundLimit) +
        selRow('rm-set-target', '🎯 资产达标金额', '仅在选择「资产达标」胜利条件时生效。',
          [200000, 300000, 400000, 500000, 600000, 800000, 1000000].map(function (v) { return '<option value="' + v + '" ' + (c.targetAsset === v ? 'selected' : '') + '>' + rmFmtMoney(v) + '</option>'; }).join(''), c.targetAsset) +
        '<div style="font-size:12px;font-weight:600;color:var(--ubp-text);margin:2px 2px 7px;">🎛 可选规则（在方框内打勾开启）</div>' +
        checkRow('rm-set-auction', '🔨 无主地自动拍卖', '玩家放弃购买的无主土地进入拍卖，价高者得（不勾选则跳过拍卖继续空置）。', c.auction) +
        '<div style="font-size:11px;color:var(--ubp-text-3);line-height:1.6;border-top:1px solid var(--ubp-line);padding-top:8px;">· 对局结束会写入「对局记录」并联动小手机微信/朋友圈。<br>· 中途退出会实时保存，下次进入对局大厅可继续。</div></div>';
      const bind = function (id, fn) { const el = ov.querySelector('#' + id); if (el) el.addEventListener('change', fn); };
      bind('rm-set-chat', function (e) { const cc = loadRmConfig(); cc.aiChat = e.target.checked; saveRmConfig(cc); renderContent(); });
      bind('rm-set-interval', function (e) { const cc = loadRmConfig(); cc.speechInterval = parseInt(e.target.value) || 4; saveRmConfig(cc); });
      bind('rm-set-level', function (e) { const cc = loadRmConfig(); cc.aiLevel = e.target.value || 'normal'; saveRmConfig(cc); });
      bind('rm-set-roundlimit', function (e) { const cc = loadRmConfig(); cc.roundLimit = parseInt(e.target.value) || 30; saveRmConfig(cc); });
      bind('rm-set-target', function (e) { const cc = loadRmConfig(); cc.targetAsset = parseInt(e.target.value) || 400000; saveRmConfig(cc); });
      bind('rm-set-auction', function (e) { const cc = loadRmConfig(); cc.auction = e.target.checked; saveRmConfig(cc); });
      const closeBtn = ov.querySelector('[data-rm-set="close"]');
      if (closeBtn) closeBtn.addEventListener('click', function () { ov.remove(); if (sheet.querySelector('#rm-chat-toggle')) renderRmLobby(); });
    };
    renderContent();
    sheet.appendChild(ov);
  }

  // ========== 大富翁：操作分发 ==========
  function rmUserUseCard(idx) {
    const st = rmGame;
    if (!st || st.turnSeat !== 0 || st.phase === 'ended' || st.moving || st.pending) { showToast('现在不能用卡片'); return; }
    const me = st.players[0];
    const key = me.cards[idx];
    const def = RM_CARDS[key];
    if (!def) return;
    if (def.passive) { showToast('【' + def.name + '】是被动卡，会在关键时刻自动触发'); return; }
    const t = def.target;
    const go = function (opts) {
      const r = rmUseCard(st, me, idx, opts);
      if (!r.ok) { showToast(r.msg || '使用失败'); return; }
      showToast(def.icon + ' 使用了【' + def.name + '】');
      rmMaybeAutoSpeak('card', 0);
      if (r.auction) { renderRmAuction(); rmRunAuctionLoop(); return; }
      rmSaveState();
      renderRmGameUI();
    };
    if (t === 'player') renderRmTargetPicker('player', function (v) { go({ target: v }); }, { title: def.icon + ' ' + def.name + ' · 选择对手' });
    else if (t === 'playerAny') renderRmTargetPicker('playerAny', function (v) { go({ target: v }); }, { title: def.icon + ' ' + def.name + ' · 选择目标' });
    else if (t === 'land') renderRmTargetPicker('enemyLand', function (v) { go({ land: v }); }, { title: def.icon + ' ' + def.name + ' · 选择对手的地' });
    else if (t === 'stock') renderRmTargetPicker('stock', function (v) { go({ stock: v }); }, { title: def.icon + ' ' + def.name + ' · 选择股票' });
    else if (t === 'street') {
      renderRmTargetPicker('player', function (v) { go({ target: v }); }, { title: def.icon + ' ' + def.name + ' · 选择对手（夷平其最值钱的街）' });
    }
    else if (t === 'bigType') {
      renderRmTargetPicker('myBigLand', function (li) {
        renderRmTargetPicker('bigType', function (bt) { go({ land: li, buildType: bt }); }, { title: '🏗️ 改建卡 · 选择新建筑' });
      }, { title: '🏗️ 改建卡 · 选择你的商业地' });
    }
    else go({});
  }
  function rmUserUseItem(idx) {
    const st = rmGame;
    if (!st || st.turnSeat !== 0 || st.phase === 'ended' || st.moving || st.pending) { showToast('现在不能用道具'); return; }
    const me = st.players[0];
    const key = me.items[idx];
    const def = RM_ITEMS[key];
    if (!def) return;
    const go = function (opts) {
      const r = rmUseItem(st, me, idx, opts);
      if (!r.ok) { showToast(r.msg || '使用失败'); return; }
      showToast(def.icon + ' 使用了【' + def.name + '】');
      rmSaveState();
      renderRmGameUI();
    };
    if (key === 'remote') {
      if (st.phase !== 'roll') { showToast('遥控骰子要在掷骰前使用'); return; }
      renderRmTargetPicker('dice', function (v) { go({ dice: v }); }, { title: '🎲 遥控骰子 · 选择点数' });
    } else if (key === 'feidan') {
      renderRmTargetPicker('enemyLand', function (v) { go({ land: v }); }, { title: '🚀 飞弹 · 选择要炸的地' });
    } else {
      renderRmTargetPicker('placeCell', function (v) { go({ cell: v }); }, { title: def.icon + ' ' + def.name + ' · 选择放置格子' });
    }
  }
  function rmUserPendingDone() {
    const st = rmGame;
    if (!st) return;
    st.pending = null;
    rmSaveState();
    renderRmGameUI();
  }
  function handleRmAction(act, target) {
    const st = rmGame;
    if (act === 'rm-open') {
      if (rmHasSaved()) rmResumeSaved();
      else renderRmLobby();
      return;
    }
    if (act === 'rm-back-tablegame') { renderTableGameLobby(); return; }
    if (act === 'rm-invite') { renderRmInviteOverlay(function (names) { startRmGame(names); }); return; }
    if (act === 'rm-settings') { renderRmSettings(); return; }
    if (act === 'rm-start') {
      const cfg = loadRmConfig();
      if (aiChatInviteGate({
        chatOn: cfg.aiChat,
        invited: (cfg.partnerNames || []).filter(Boolean).length,
        label: '大富翁',
        onInvite: () => renderRmInviteOverlay(function (names) { startRmGame(names); }),
        onDisableAndStart: () => { const c2 = loadRmConfig(); c2.aiChat = false; saveRmConfig(c2); handleRmAction('rm-start', null); }
      })) return;
      startRmGame(cfg.partnerNames);
      return;
    }
    if (act === 'rm-resume') { rmResumeSaved(); return; }
    if (act === 'rm-discard') { rmGenCounter++; rmClearSaved(); renderRmLobby(); showToast('🗑️ 已放弃进行中的大富翁对局'); return; }
    if (act === 'rm-pick-vehicle') {
      const c = loadRmConfig();
      if (target && target.dataset && target.dataset.vehicle) c.vehicle = target.dataset.vehicle;
      saveRmConfig(c); renderRmLobby(); return;
    }
    if (act === 'rm-pick-win') {
      const c = loadRmConfig();
      if (target && target.dataset && target.dataset.win) c.winMode = target.dataset.win;
      saveRmConfig(c); renderRmLobby(); return;
    }
    if (act === 'rm-exit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      rmGenCounter++;
      const modal = sheet.querySelector('.rm-result-overlay');
      if (modal) modal.remove();
      const auc = sheet.querySelector('.rm-auc'); if (auc) auc.remove();
      const ovl = sheet.querySelector('.rm-ovl'); if (ovl) ovl.remove();
      if (rmAiTimer) { clearTimeout(rmAiTimer); rmAiTimer = null; }
      rmChatBusy = false;
      if (rmGame) rmGame.moving = false;
      if (rmGame && rmGame.phase !== 'ended') rmSaveState(); else rmClearSaved();
      renderRmLobby();
      return;
    }
    if (act === 'rm-rematch') {
      const modal = sheet.querySelector('.rm-result-overlay');
      if (modal) modal.remove();
      const names = rmGame ? rmGame.players.filter(function (p) { return !p.isUser; }).map(function (p) { return p.name; }) : [];
      if (aiChatInviteGate({
        chatOn: loadRmConfig().aiChat,
        invited: names.filter(n2 => !isBuiltinPlayerName(n2)).length,
        label: '大富翁',
        onInvite: () => renderRmLobby(),
        onDisableAndStart: () => { const c2 = loadRmConfig(); c2.aiChat = false; saveRmConfig(c2); handleRmAction('rm-rematch', null); }
      })) return;
      startRmGame(names);
      return;
    }
    if (act === 'rm-roll') {
      if (!st || st.turnSeat !== 0 || st.phase !== 'roll' || st.moving || st.pending) return;
      const n = parseInt(target.dataset.count) || 1;
      const rv = st.remoteDice; st.remoteDice = 0;
      rmRollAndMove(0, n, rv);
      return;
    }
    if (act === 'rm-endturn') {
      if (!st || st.turnSeat !== 0 || st.phase !== 'roll' || st.moving || st.pending) { showToast('请先处理当前事件'); return; }
      if (!st.rolled) { showToast('本回合还没掷骰子'); return; }
      rmEndTurn();
      return;
    }
    if (act === 'rm-buy') {
      if (!st || st.turnSeat !== 0 || !st.pending || st.pending.type !== 'buy') return;
      const r = rmDoBuyLand(st, st.players[0], st.pending.land);
      if (!r.ok) { showToast(r.msg || '购买失败'); return; }
      rmUserPendingDone();
      return;
    }
    if (act === 'rm-decline') {
      if (!st || st.turnSeat !== 0 || !st.pending) return;
      if (st.pending.type === 'buy' && st.auctionEnabled) {
        const li = st.pending.land;
        rmAuctionStart(st, li, {});
        renderRmAuction();
        rmRunAuctionLoop();
        return;
      }
      rmUserPendingDone();
      return;
    }
    if (act === 'rm-upgrade') {
      if (!st || st.turnSeat !== 0 || !st.pending || st.pending.type !== 'upgrade') return;
      const r = rmDoUpgrade(st, st.players[0], st.pending.land);
      if (!r.ok) { showToast(r.msg || '盖房失败'); return; }
      rmUserPendingDone();
      return;
    }
    if (act === 'rm-bigbuild') {
      if (!st || st.turnSeat !== 0 || !st.pending || st.pending.type !== 'bigBuild') return;
      const bk = target.dataset.build;
      const r = rmDoBigBuild(st, st.players[0], st.pending.land, bk);
      if (!r.ok) { showToast(r.msg || '现金不足，无法建造'); return; }
      rmUserPendingDone();
      return;
    }
    if (act === 'rm-payrent') {
      if (!st || st.turnSeat !== 0 || !st.pending || st.pending.type !== 'rent') return;
      const pend = st.pending;
      rmLog(st, '💸 ' + st.players[0].name + ' 向 ' + st.players[pend.creditorSeat].name + ' 支付租金 -' + rmFmtMoney(pend.amount) + '（' + RM_MAP[pend.land].name + ' ' + (st.lands[pend.land].houses || 0) + ' 层）', '#EF4444', { seat: 0, kind: 'money' });
      rmCharge(st, st.players[0], pend.amount, { kind: 'rent', creditorSeat: pend.creditorSeat });
      if (st.winnerSeat !== null && st.winnerSeat !== undefined) { rmOnGameOver(); return; }
      rmUserPendingDone();
      return;
    }
    if (act === 'rm-freerent') {
      if (!st || st.turnSeat !== 0 || !st.pending || st.pending.type !== 'rent' || !st.pending.canFree) return;
      st.players[0].cards.splice(st.pending.freeIdx, 1);
      rmLog(st, '🎟️ 你使用【免费卡】免付租金 ' + rmFmtMoney(st.pending.amount), '#22C55E', { seat: 0, kind: 'card' });
      rmUserPendingDone();
      return;
    }
    if (act === 'rm-companybuy') {
      if (!st || st.turnSeat !== 0 || !st.pending || st.pending.type !== 'companyBuy') return;
      const r = rmDoCompanyBuy(st, st.players[0], st.pending.cell);
      if (!r.ok) { showToast(r.msg || '收购失败'); return; }
      rmUserPendingDone();
      return;
    }
    if (act === 'rm-card') { rmUserUseCard(parseInt(target.dataset.idx)); return; }
    if (act === 'rm-item') { rmUserUseItem(parseInt(target.dataset.idx)); return; }
    if (act === 'rm-openshop') { if (!st) return; if (st.pending && st.pending.type === 'shop') { rmUserPendingDone(); } renderRmShop(); return; }
    if (act === 'rm-openstock') { if (!st) return; if (st.pending && st.pending.type === 'stock') { rmUserPendingDone(); } renderRmStock(); return; }
    if (act === 'rm-ovl-close') { const ov = sheet.querySelector('.rm-ovl'); if (ov) ov.remove(); return; }
    if (act === 'rm-cell') {
      // 点地图格：查看详情（title 已有；给个 toast 详情）
      if (!st) return;
      const i = parseInt(target.dataset.cell);
      const cell = RM_MAP[i];
      if (!cell) return;
      const land = st.lands[i];
      if (cell.type === 'land' || cell.type === 'bigland') {
        const own = land.owner < 0 ? '无主' : st.players[land.owner].name;
        const extra = cell.type === 'land' ? ('房屋 ' + land.houses + ' 层 · 租金 ' + rmFmtMoney(rmRent(st, i))) : ('建筑：' + (land.build !== 'none' ? RM_BIG_BUILDS[land.build].name : '未建'));
        showToast('【' + cell.name + '】' + own + ' · 地价 ' + rmFmtMoney(cell.price) + ' · ' + extra);
      } else if (cell.type === 'company') {
        const comp = st.companies[i];
        showToast('【' + cell.name + '】' + (comp.owner >= 0 ? '董事长：' + st.players[comp.owner].name : '待收购 ' + rmFmtMoney(cell.price)));
      }
      return;
    }
    if (act === 'rm-send-chat') { rmHandleUserChat(); return; }
  }
  // __RM_UI_END__






  // ============================================================
  // ========== 连连看 (经典规则 · 2折线匹配 · 自动防死局 · 通关+1积分) ==========
  // ============================================================
  // __LLK_ENGINE_BEGIN__

  let llkGame = null;
  let llkTimer = null;
  let llkHintTimer = null;

  // 严格统一为动物图标（不含水果、蘑菇等其他图标）
  const LLK_EMOJIS = [
    '🐱', '🐶', '🐰', '🦊', '🐼', '🐨',
    '🐯', '🦁', '🐸', '🐵', '🐷', '🐮',
    '🦄', '🐥', '🐧', '🐻', '🐙', '🐹',
    '🐺', '🐑', '🐢', '🐬', '🦉', '🦋'
  ];

  // 检查两点之间是否为无障碍直线（不包含两端点）
  function isLLKLineClear(grid, r1, c1, r2, c2) {
    if (r1 === r2) {
      const minC = Math.min(c1, c2);
      const maxC = Math.max(c1, c2);
      for (let c = minC + 1; c < maxC; c++) {
        if (grid[r1][c] !== 0) return false;
      }
      return true;
    }
    if (c1 === c2) {
      const minR = Math.min(r1, r2);
      const maxR = Math.max(r1, r2);
      for (let r = minR + 1; r < maxR; r++) {
        if (grid[r][c1] !== 0) return false;
      }
      return true;
    }
    return false;
  }

  // 连连看核心寻路：最多 2 次转折（3 条线段）
  // grid 大小为 (rows + 2) x (cols + 2)，外围为 0（空道）
  function findLLKPath(grid, rows, cols, r1, c1, r2, c2) {
    if (r1 === r2 && c1 === c2) return null;
    if (!grid[r1] || !grid[r2]) return null;
    if (!grid[r1][c1] || grid[r1][c1] !== grid[r2][c2]) return null;

    const totalRows = rows + 2;
    const totalCols = cols + 2;
    const pStart = { r: r1, c: c1 };
    const pEnd = { r: r2, c: c2 };

    // 1. 直线连接（0 折）
    if (isLLKLineClear(grid, r1, c1, r2, c2)) {
      return [pStart, pEnd];
    }

    // 2. 一个拐点连接（1 折 / L型）
    // 拐角 1: (r1, c2)
    if (grid[r1][c2] === 0) {
      if (isLLKLineClear(grid, r1, c1, r1, c2) && isLLKLineClear(grid, r1, c2, r2, c2)) {
        return [pStart, { r: r1, c: c2 }, pEnd];
      }
    }
    // 拐角 2: (r2, c1)
    if (grid[r2][c1] === 0) {
      if (isLLKLineClear(grid, r1, c1, r2, c1) && isLLKLineClear(grid, r2, c1, r2, c2)) {
        return [pStart, { r: r2, c: c1 }, pEnd];
      }
    }

    // 3. 两个拐点连接（2 折 / Z型或U型，支持借用外围空道）
    let bestPath = null;
    let bestDist = Infinity;

    // 方案 A: 纵向扫描各列 c (0 到 cols + 1)
    for (let c = 0; c < totalCols; c++) {
      if (c === c1 || c === c2) continue;
      if (grid[r1][c] === 0 && grid[r2][c] === 0) {
        if (isLLKLineClear(grid, r1, c1, r1, c) &&
            isLLKLineClear(grid, r1, c, r2, c) &&
            isLLKLineClear(grid, r2, c, r2, c2)) {
          const dist = Math.abs(c - c1) + Math.abs(r1 - r2) + Math.abs(c2 - c);
          if (dist < bestDist) {
            bestDist = dist;
            bestPath = [pStart, { r: r1, c }, { r: r2, c }, pEnd];
          }
        }
      }
    }

    // 方案 B: 横向扫描各行 r (0 到 rows + 1)
    for (let r = 0; r < totalRows; r++) {
      if (r === r1 || r === r2) continue;
      if (grid[r][c1] === 0 && grid[r][c2] === 0) {
        if (isLLKLineClear(grid, r1, c1, r, c1) &&
            isLLKLineClear(grid, r, c1, r, c2) &&
            isLLKLineClear(grid, r, c2, r2, c2)) {
          const dist = Math.abs(r - r1) + Math.abs(c1 - c2) + Math.abs(r2 - r);
          if (dist < bestDist) {
            bestDist = dist;
            bestPath = [pStart, { r, c: c1 }, { r, c: c2 }, pEnd];
          }
        }
      }
    }

    return bestPath;
  }

  // 寻找场上任意一对可消除的棋子
  function findAnyLLKMove(grid, rows, cols) {
    const list = [];
    for (let r = 1; r <= rows; r++) {
      for (let c = 1; c <= cols; c++) {
        if (grid[r][c] !== 0) {
          list.push({ r, c, type: grid[r][c] });
        }
      }
    }
    for (let i = 0; i < list.length; i++) {
      for (let j = i + 1; j < list.length; j++) {
        if (list[i].type === list[j].type) {
          const path = findLLKPath(grid, rows, cols, list[i].r, list[i].c, list[j].r, list[j].c);
          if (path) {
            return { a: list[i], b: list[j], path };
          }
        }
      }
    }
    return null;
  }

  // 生成开局棋盘（确保有解）
  function generateSolvableLLKGrid(rows, cols) {
    const totalTiles = rows * cols;
    const numTypes = rows === 4 ? 4 : (rows === 8 ? 12 : 9);
    const tilesPerType = totalTiles / numTypes;

    for (let attempt = 0; attempt < 100; attempt++) {
      const symbols = [...LLK_EMOJIS].sort(() => Math.random() - 0.5).slice(0, numTypes);
      const tileList = [];
      for (const sym of symbols) {
        for (let k = 0; k < tilesPerType; k++) {
          tileList.push(sym);
        }
      }
      tileList.sort(() => Math.random() - 0.5);

      const grid = Array.from({ length: rows + 2 }, () => Array(cols + 2).fill(0));
      let idx = 0;
      for (let r = 1; r <= rows; r++) {
        for (let c = 1; c <= cols; c++) {
          grid[r][c] = tileList[idx++];
        }
      }

      if (findAnyLLKMove(grid, rows, cols)) {
        return grid;
      }
    }

    // 兜底（极小概率 100 次仍无解时直接配对摆放）
    const symbols = [...LLK_EMOJIS].slice(0, numTypes);
    const grid = Array.from({ length: rows + 2 }, () => Array(cols + 2).fill(0));
    let sIdx = 0;
    for (let r = 1; r <= rows; r++) {
      for (let c = 1; c <= cols; c += 2) {
        const sym = symbols[sIdx % symbols.length];
        grid[r][c] = sym;
        grid[r][c + 1] = sym;
        sIdx++;
      }
    }
    return grid;
  }

  // 重新排列剩余棋子（自动洗牌 / 手动洗牌）
  function shuffleLLKBoard(isAuto = false) {
    if (!llkGame || llkGame.isCompleted) return;
    const coords = [];
    const values = [];
    for (let r = 1; r <= llkGame.rows; r++) {
      for (let c = 1; c <= llkGame.cols; c++) {
        if (llkGame.grid[r][c] !== 0) {
          coords.push({ r, c });
          values.push(llkGame.grid[r][c]);
        }
      }
    }
    if (values.length <= 2) return;

    for (let attempt = 0; attempt < 50; attempt++) {
      values.sort(() => Math.random() - 0.5);
      for (let i = 0; i < coords.length; i++) {
        llkGame.grid[coords[i].r][coords[i].c] = values[i];
      }
      if (findAnyLLKMove(llkGame.grid, llkGame.rows, llkGame.cols)) {
        break;
      }
    }

    llkGame.selected = null;
    llkGame.hintTiles = null;
    renderLLKBoardGrid();
    showToast(isAuto ? '🔄 当前无可连棋子，已自动洗牌！' : '🔀 棋盘已重新排列！');
  }

  // 计时器控制
  function startLLKTimer() {
    stopLLKTimer();
    llkTimer = setInterval(() => {
      if (!llkGame || llkGame.isCompleted) {
        stopLLKTimer();
        return;
      }
      llkGame.elapsedSeconds++;
      const timerEl = sheet?.querySelector('#llk-timer-display');
      if (timerEl) {
        const m = Math.floor(llkGame.elapsedSeconds / 60).toString().padStart(2, '0');
        const s = (llkGame.elapsedSeconds % 60).toString().padStart(2, '0');
        timerEl.textContent = `⏱️ ${m}:${s}`;
      }
    }, 1000);
  }

  function stopLLKTimer() {
    if (llkTimer) {
      clearInterval(llkTimer);
      llkTimer = null;
    }
    if (llkHintTimer) {
      clearTimeout(llkHintTimer);
      llkHintTimer = null;
    }
  }

  // 启动连连看（直接开局，无须邀请，不写对局记录）
  const LLK_SAVE_KEY = 'werewolf_extension_llk_save';
  function hasSavedLLKGame() { try { const raw = localStorage.getItem(LLK_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && d.grid && !d.isCompleted); } catch (e) { return false; } }
  function clearLLKSave() { try { localStorage.removeItem(LLK_SAVE_KEY); } catch (e) { /* ignore */ } }
  function saveLLKGame() {
    try {
      if (!llkGame || llkGame.isCompleted) { clearLLKSave(); return false; }
      localStorage.setItem(LLK_SAVE_KEY, JSON.stringify({
        v: 1, rows: llkGame.rows, cols: llkGame.cols, grid: llkGame.grid,
        matchedPairs: llkGame.matchedPairs, totalPairs: llkGame.totalPairs,
        elapsedSeconds: llkGame.elapsedSeconds, hintsRemaining: llkGame.hintsRemaining,
        shufflesRemaining: llkGame.shufflesRemaining, isCompleted: false, rewardClaimed: llkGame.rewardClaimed
      }));
      return true;
    } catch (e) { return false; }
  }
  function resumeLLKGame() {
    let d = null;
    try { const raw = localStorage.getItem(LLK_SAVE_KEY); d = raw ? JSON.parse(raw) : null; } catch (e) { d = null; }
    if (!d || !d.grid) { startLLKGame(6, 6); return; }
    llkGame = {
      rows: d.rows, cols: d.cols, grid: d.grid, selected: null, hintTiles: null,
      matchedPairs: d.matchedPairs || 0, totalPairs: d.totalPairs || (d.rows * d.cols / 2),
      startTime: Date.now(), elapsedSeconds: d.elapsedSeconds || 0,
      hintsRemaining: (d.hintsRemaining === undefined ? 3 : d.hintsRemaining),
      shufflesRemaining: (d.shufflesRemaining === undefined ? 3 : d.shufflesRemaining),
      isCompleted: false, rewardClaimed: !!d.rewardClaimed, animating: false
    };
    renderLLKGameUI();
    startLLKTimer();
    showToast('🔖 已恢复进行中的连连看（已消 ' + llkGame.matchedPairs + '/' + llkGame.totalPairs + ' 对）');
  }

  function startLLKGame(diffRows = 6, diffCols = 6) {
    stopLLKTimer();
    const rows = diffRows;
    const cols = diffCols;
    const grid = generateSolvableLLKGrid(rows, cols);

    llkGame = {
      rows,
      cols,
      grid,
      selected: null,
      hintTiles: null,
      matchedPairs: 0,
      totalPairs: (rows * cols) / 2,
      startTime: Date.now(),
      elapsedSeconds: 0,
      hintsRemaining: 3,
      shufflesRemaining: 3,
      isCompleted: false,
      rewardClaimed: false,
      animating: false
    };

    renderLLKGameUI();
    startLLKTimer();
  }

  // 绘制折线连接 SVG
  function renderLLKLine(path) {
    const svg = sheet?.querySelector('#llk-line-svg');
    if (!svg || !path || path.length < 2 || !llkGame) return;

    const cols = llkGame.cols;
    const rows = llkGame.rows;
    const padding = cols === 4 ? 12 : 10;
    // 进阶模式是 8 行 × 6 列（startLLKGame(8, 6)），必须同时看 rows，否则永远命不中紧凑尺寸
    const compact = (rows === 8 || cols === 8);
    const gap = compact ? 3 : (cols === 4 ? 6 : 4);
    const tileSize = compact ? 30 : (cols === 4 ? 48 : 40);

    const getPt = (p) => {
      let x, y;
      if (p.c === 0) {
        x = padding / 2;
      } else if (p.c === cols + 1) {
        x = padding * 2 + cols * tileSize + (cols - 1) * gap - padding / 2;
      } else {
        x = padding + (p.c - 1) * (tileSize + gap) + tileSize / 2;
      }

      if (p.r === 0) {
        y = padding / 2;
      } else if (p.r === rows + 1) {
        y = padding * 2 + rows * tileSize + (rows - 1) * gap - padding / 2;
      } else {
        y = padding + (p.r - 1) * (tileSize + gap) + tileSize / 2;
      }
      return `${Math.round(x)},${Math.round(y)}`;
    };

    const pts = path.map(getPt).join(' ');
    svg.innerHTML = `<polyline points="${pts}" fill="none" stroke="#06B6D4" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" style="filter:drop-shadow(0 0 6px rgba(6,182,212,0.9));"/>`;
  }

  function clearLLKLine() {
    const svg = sheet?.querySelector('#llk-line-svg');
    if (svg) svg.innerHTML = '';
  }

  // 仅刷新棋盘格子 DOM
  function renderLLKBoardGrid() {
    const gridContainer = sheet?.querySelector('#llk-board-grid');
    if (!gridContainer || !llkGame) return;

    const { rows, cols, grid, selected, hintTiles } = llkGame;
    const compact = (rows === 8 || cols === 8); // 进阶 8×6 用紧凑尺寸（与 renderLLKGameUI/renderLLKLine 保持一致）
    const tileSize = compact ? 30 : (cols === 4 ? 48 : 40);
    const fontSize = compact ? 17 : (cols === 4 ? 26 : 22);

    let html = '';
    for (let r = 1; r <= rows; r++) {
      for (let c = 1; c <= cols; c++) {
        const val = grid[r][c];
        if (!val) {
          html += `<div style="visibility:hidden;pointer-events:none;width:${tileSize}px;height:${tileSize}px;"></div>`;
          continue;
        }
        const isSel = selected && selected.r === r && selected.c === c;
        const isHint = hintTiles && hintTiles.some(p => p.r === r && p.c === c);

        let borderStyle = 'border:1px solid var(--ubp-line);background:var(--ubp-card);';
        if (isSel) {
          borderStyle = 'border:2px solid #06B6D4;background:rgba(6,182,212,0.22);box-shadow:0 0 10px rgba(6,182,212,0.8);transform:scale(1.06);';
        } else if (isHint) {
          borderStyle = 'border:2px solid #F59E0B;background:rgba(245,158,11,0.22);box-shadow:0 0 10px rgba(245,158,11,0.8);animation:llk-pulse 0.8s infinite;';
        }

        html += `
          <button data-llk-act="llk-tile" data-r="${r}" data-c="${c}" class="llk-tile-btn" style="width:${tileSize}px;height:${tileSize}px;display:flex;align-items:center;justify-content:center;border-radius:8px;font-size:${fontSize}px;cursor:pointer;user-select:none;transition:transform 0.12s, box-shadow 0.12s;padding:0;${borderStyle}">
            ${val}
          </button>
        `;
      }
    }
    gridContainer.innerHTML = html;

    const progressEl = sheet?.querySelector('#llk-progress-display');
    if (progressEl) {
      progressEl.innerHTML = `已消: <b style="color:#06B6D4;">${llkGame.matchedPairs}</b> / ${llkGame.totalPairs} 对`;
    }
  }

  // 通关胜利处理（简单和经典模式不给积分，仅进阶模式给1积分；不写入对局记录）
  function handleLLKVictory() {
    if (!llkGame || llkGame.isCompleted) return;
    llkGame.isCompleted = true;
    clearLLKSave();
    stopLLKTimer();

    const isAdvMode = llkGame.rows === 8;
    if (isAdvMode) {
      if (!llkGame.rewardClaimed) {
        llkGame.rewardClaimed = true;
        addPoints(1);
        showToast('🎉 连连看进阶模式通关！获得 1 积分');
      }
    } else {
      showToast('🎉 连连看通关！简单/经典练习模式不发放积分');
    }

    const m = Math.floor(llkGame.elapsedSeconds / 60).toString().padStart(2, '0');
    const s = (llkGame.elapsedSeconds % 60).toString().padStart(2, '0');
    const timeStr = `${m}:${s}`;

    const rewardHtml = isAdvMode
      ? `<div style="display:inline-flex;align-items:center;gap:4px;padding:5px 14px;border-radius:999px;background:rgba(245,158,11,0.18);border:1px solid rgba(245,158,11,0.6);font-size:13px;font-weight:700;color:#F59E0B;margin-bottom:16px;">
          💎 获得 +1 积分（总积分: ${loadPoints()}）
        </div>`
      : `<div style="display:inline-flex;align-items:center;gap:4px;padding:5px 14px;border-radius:999px;background:rgba(148,163,184,0.15);border:1px solid rgba(148,163,184,0.4);font-size:12px;color:var(--ubp-text-2);margin-bottom:16px;">
          简单/经典模式练习无积分（进阶模式可得 1 积分）
        </div>`;

    const modal = document.createElement('div');
    modal.className = 'llk-victory-overlay';
    modal.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    modal.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #06B6D4;border-radius:14px;padding:22px 18px;width:100%;max-width:290px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:42px;margin-bottom:8px;">🎉</div>
        <div style="font-size:18px;font-weight:bold;color:#06B6D4;margin-bottom:6px;">连连看通关！</div>
        <div style="font-size:12.5px;color:var(--ubp-text-2);margin-bottom:8px;">耗时: ${timeStr} · 成功消除 ${llkGame.totalPairs} 对</div>
        ${rewardHtml}
        <div style="display:flex;gap:10px;">
          <button data-llk-act="llk-exit" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12.5px;">🚪 退出</button>
          <button data-llk-act="llk-restart" class="ubp-btn primary" style="flex:1.2;padding:8px 0;font-size:12.5px;background:#06B6D4;border:none;font-weight:600;">🔄 再来一局</button>
        </div>
      </div>
    `;
    sheet.appendChild(modal);
  }

  // 点击格子逻辑
  function handleLLKTileClick(r, c) {
    if (!llkGame || llkGame.isCompleted || llkGame.animating) return;
    if (llkGame.grid[r][c] === 0) return;

    if (llkGame.hintTiles) {
      llkGame.hintTiles = null;
      if (llkHintTimer) { clearTimeout(llkHintTimer); llkHintTimer = null; }
    }

    if (!llkGame.selected) {
      llkGame.selected = { r, c };
      renderLLKBoardGrid();
      return;
    }

    if (llkGame.selected.r === r && llkGame.selected.c === c) {
      llkGame.selected = null;
      renderLLKBoardGrid();
      return;
    }

    const prevR = llkGame.selected.r;
    const prevC = llkGame.selected.c;

    if (llkGame.grid[prevR][prevC] !== llkGame.grid[r][c]) {
      llkGame.selected = { r, c };
      renderLLKBoardGrid();
      return;
    }

    // 相同符号，尝试寻路连接
    const path = findLLKPath(llkGame.grid, llkGame.rows, llkGame.cols, prevR, prevC, r, c);
    if (!path) {
      // 无法连接，选中新点击的格子并轻微抖动
      const btn = sheet?.querySelector(`[data-llk-act="llk-tile"][data-r="${r}"][data-c="${c}"]`);
      if (btn) {
        btn.style.animation = 'llk-shake 0.3s';
        setTimeout(() => { if (btn) btn.style.animation = ''; }, 300);
      }
      llkGame.selected = { r, c };
      renderLLKBoardGrid();
      return;
    }

    // 成功连接：进入消除流程
    llkGame.animating = true;
    llkGame.selected = null;
    renderLLKLine(path);

    // 消除反馈动画
    const btn1 = sheet?.querySelector(`[data-llk-act="llk-tile"][data-r="${prevR}"][data-c="${prevC}"]`);
    const btn2 = sheet?.querySelector(`[data-llk-act="llk-tile"][data-r="${r}"][data-c="${c}"]`);
    if (btn1) {
      btn1.style.borderColor = '#06B6D4';
      btn1.style.background = 'rgba(6,182,212,0.4)';
      btn1.style.transform = 'scale(1.12)';
    }
    if (btn2) {
      btn2.style.borderColor = '#06B6D4';
      btn2.style.background = 'rgba(6,182,212,0.4)';
      btn2.style.transform = 'scale(1.12)';
    }

    const gameRef = llkGame;
    setTimeout(() => {
      // 期间可能已退出（llkGame=null）或重开（换成了新棋盘）：丢弃旧回调，避免操作新棋盘或空引用
      if (!llkGame || llkGame !== gameRef) return;
      clearLLKLine();
      llkGame.grid[prevR][prevC] = 0;
      llkGame.grid[r][c] = 0;
      llkGame.matchedPairs++;
      llkGame.animating = false;

      if (llkGame.matchedPairs >= llkGame.totalPairs) {
        renderLLKBoardGrid();
        handleLLKVictory();
      } else {
        renderLLKBoardGrid();
        // 检查是否死局，无路可走则自动洗牌
        if (!findAnyLLKMove(llkGame.grid, llkGame.rows, llkGame.cols)) {
          shuffleLLKBoard(true);
        }
      }
    }, 240);
  }

  // 提示功能
  function handleLLKHint() {
    if (!llkGame || llkGame.isCompleted || llkGame.animating) return;
    if (llkGame.hintsRemaining <= 0) {
      showToast('💡 提示次数已用完');
      return;
    }

    const move = findAnyLLKMove(llkGame.grid, llkGame.rows, llkGame.cols);
    if (!move) {
      shuffleLLKBoard(true);
      return;
    }

    llkGame.hintsRemaining--;
    llkGame.hintTiles = [move.a, move.b];
    llkGame.selected = null;
    renderLLKBoardGrid();

    const hintBtn = sheet?.querySelector('[data-llk-act="llk-hint"]');
    if (hintBtn) hintBtn.textContent = `💡 提示 (${llkGame.hintsRemaining})`;

    if (llkHintTimer) clearTimeout(llkHintTimer);
    llkHintTimer = setTimeout(() => {
      if (llkGame && llkGame.hintTiles) {
        llkGame.hintTiles = null;
        renderLLKBoardGrid();
      }
    }, 3000);
  }

  // 重排功能
  function handleLLKShuffle() {
    if (!llkGame || llkGame.isCompleted || llkGame.animating) return;
    if (llkGame.shufflesRemaining <= 0) {
      showToast('🔀 重排次数已用完');
      return;
    }
    llkGame.shufflesRemaining--;
    const shufBtn = sheet?.querySelector('[data-llk-act="llk-shuffle"]');
    if (shufBtn) shufBtn.textContent = `🔀 重排 (${llkGame.shufflesRemaining})`;
    shuffleLLKBoard(false);
  }

  // 渲染连连看主界面
  function renderLLKGameUI() {
    if (!llkGame) { renderMiniGameLobby(); return; }

    const { rows, cols, matchedPairs, totalPairs, elapsedSeconds, hintsRemaining, shufflesRemaining } = llkGame;
