            <button data-llk-act="llk-diff" data-diff="4" style="padding:2px 7px;font-size:11px;border-radius:5px;border:none;background:${rows===4?'#06B6D4':'transparent'};color:${rows===4?'#fff':'var(--ubp-text-2)'};cursor:pointer;">简单 4×4</button>
            <button data-llk-act="llk-diff" data-diff="6" style="padding:2px 7px;font-size:11px;border-radius:5px;border:none;background:${rows===6?'#06B6D4':'transparent'};color:${rows===6?'#fff':'var(--ubp-text-2)'};cursor:pointer;">经典 6×6</button>
            <button data-llk-act="llk-diff" data-diff="8" style="padding:2px 7px;font-size:11px;border-radius:5px;border:none;background:${rows===8?'#06B6D4':'transparent'};color:${rows===8?'#fff':'var(--ubp-text-2)'};cursor:pointer;" title="进阶模式通关可得 1 积分">进阶 8×6 (💎+1)</button>
          </div>
          <div id="llk-progress-display" style="font-size:11.5px;color:var(--ubp-text-2);">
