          </div>
        </div>

        <!-- 棋盘区域（留出四周空隙用于折线寻路） -->
        <div style="position:relative;flex:1;display:flex;align-items:center;justify-content:center;min-height:0;overflow:hidden;padding:4px 0;">
          <div id="llk-board-container" style="position:relative;display:inline-block;padding:${padding}px;background:var(--ubp-card-2);border-radius:12px;border:1px solid var(--ubp-line);box-shadow:inset 0 2px 8px rgba(0,0,0,0.2);">
            <svg id="llk-line-svg" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:30;overflow:visible;"></svg>
