  // 连连看事件分发
  function handleLLKAction(act, target) {
    if (act === 'llk-open') {
      startLLKGame(6, 6);
      return;
    }
    if (act === 'llk-exit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      const modal = sheet?.querySelector('.llk-victory-overlay');
      if (modal) modal.remove();
      const llkSaved = saveLLKGame();
      stopLLKTimer();
      llkGame = null;
      renderMiniGameLobby();
      showToast(llkSaved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
      return;
    }
    if (act === 'llk-quit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
      const modal = sheet?.querySelector('.llk-victory-overlay');
      if (modal) modal.remove();
      clearLLKSave();
      stopLLKTimer();
      llkGame = null;
      renderSetup();
      showToast('🚪 已结束本局连连看');
      return;
    }
    if (act === 'llk-restart') {
      const modal = sheet?.querySelector('.llk-victory-overlay');
      if (modal) modal.remove();
      const r = llkGame ? llkGame.rows : 6;
      const c = llkGame ? llkGame.cols : 6;
      startLLKGame(r, c);
      return;
    }
    if (act === 'llk-diff') {
      const modal = sheet?.querySelector('.llk-victory-overlay');
      if (modal) modal.remove();
      const diff = parseInt(target.dataset.diff || '6', 10);
      startLLKGame(diff, diff === 8 ? 6 : diff);
      return;
    }
    if (act === 'llk-tile') {
      const r = parseInt(target.dataset.r, 10);
      const c = parseInt(target.dataset.c, 10);
      if (Number.isFinite(r) && Number.isFinite(c)) {
        handleLLKTileClick(r, c);
      }
      return;
    }
    if (act === 'llk-hint') {
      handleLLKHint();
      return;
    }
    if (act === 'llk-shuffle') {
      handleLLKShuffle();
      return;
    }
  }
  // __LLK_ENGINE_END__

  // ============================================================
  // ========== 消消乐 (经典三消 · 水果图标 · 掉落消除 · 通关+1积分) ==========
  // ============================================================
  // __XXL_ENGINE_BEGIN__

  let xxlGame = null;
  let xxlHintTimer = null;

  // 严格统一为水果图标
  const XXL_FRUITS = ['🍎', '🍌', '🍇', '🍉', '🍓', '🍊'];
  const XXL_ROWS = 7;
  const XXL_COLS = 7;
  const XXL_TARGET_SCORE = 2000;
  const XXL_TOTAL_MOVES = 25;

  function createXXLTile(fruit, type = 'normal') {
    return { fruit, type };
  }

  function getRandomXXLFruit() {
    return XXL_FRUITS[Math.floor(Math.random() * XXL_FRUITS.length)];
  }

  function isXXLStripe(t) { return t && (t.type === 'h_stripe' || t.type === 'v_stripe'); }
  function isXXLBomb(t) { return t && t.type === 'bomb'; }
  function isXXLRainbow(t) { return t && t.type === 'rainbow'; }
  function isXXLSpecial(t) { return t && t.type !== 'normal'; }

  function canSwapXXLSpecials(t1, t2) {
    if (!t1 || !t2) return false;
    if (isXXLRainbow(t1) || isXXLRainbow(t2)) return true;
    if (isXXLSpecial(t1) && isXXLSpecial(t2)) return true;
    return false;
  }

  // 扫描全盘常规三消及特效合成（4连横/竖条纹、T/L型炸弹、5连彩虹球）
  function detectXXLMatchesAndSpecials(grid, swapFocus = null) {
    const hLines = [];
    const vLines = [];

    // 1. 横向连线
    for (let r = 0; r < XXL_ROWS; r++) {
      let len = 1;
      for (let c = 0; c < XXL_COLS; c++) {
        const cur = grid[r][c];
        const next = c < XXL_COLS - 1 ? grid[r][c + 1] : null;
        if (next && cur && cur.fruit !== '🌈' && cur.fruit === next.fruit) {
          len++;
        } else {
          if (len >= 3 && cur && cur.fruit !== '🌈') {
            const coords = [];
            for (let k = 0; k < len; k++) coords.push({ r, c: c - k });
            hLines.push({ fruit: cur.fruit, len, coords: coords.reverse(), dir: 'h' });
          }
          len = 1;
        }
      }
    }

    // 2. 纵向连线
    for (let c = 0; c < XXL_COLS; c++) {
      let len = 1;
      for (let r = 0; r < XXL_ROWS; r++) {
        const cur = grid[r][c];
        const next = r < XXL_ROWS - 1 ? grid[r + 1][c] : null;
        if (next && cur && cur.fruit !== '🌈' && cur.fruit === next.fruit) {
          len++;
        } else {
          if (len >= 3 && cur && cur.fruit !== '🌈') {
            const coords = [];
            for (let k = 0; k < len; k++) coords.push({ r: r - k, c });
            vLines.push({ fruit: cur.fruit, len, coords: coords.reverse(), dir: 'v' });
          }
          len = 1;
        }
      }
    }

    const initialElimCoords = [];
    const newSpecials = []; // { r, c, tile }
    const usedCoords = new Set();

    function pickFocus(coords) {
      if (swapFocus) {
        const found = coords.find(p => (p.r === swapFocus.r1 && p.c === swapFocus.c1) || (p.r === swapFocus.r2 && p.c === swapFocus.c2));
        if (found) return found;
      }
      return coords[Math.floor(coords.length / 2)];
    }

    // A. 5 连直线 -> 彩虹球
    for (const line of [...hLines, ...vLines]) {
      if (line.len >= 5) {
        const focus = pickFocus(line.coords);
        newSpecials.push({ r: focus.r, c: focus.c, tile: createXXLTile('🌈', 'rainbow') });
        for (const p of line.coords) {
          initialElimCoords.push(p);
          usedCoords.add(p.r + ',' + p.c);
        }
      }
    }

    // B. T 型 / L 型 5 连交叉 -> 炸弹
    for (const h of hLines) {
      if (h.len >= 5) continue;
      for (const v of vLines) {
        if (v.len >= 5) continue;
        if (h.fruit === v.fruit) {
          const inter = h.coords.find(hp => v.coords.some(vp => vp.r === hp.r && vp.c === hp.c));
          if (inter) {
            newSpecials.push({ r: inter.r, c: inter.c, tile: createXXLTile(h.fruit, 'bomb') });
            for (const p of [...h.coords, ...v.coords]) {
              initialElimCoords.push(p);
              usedCoords.add(p.r + ',' + p.c);
            }
          }
        }
      }
    }

    // C. 4 连直线 -> 横/竖条纹
    for (const line of [...hLines, ...vLines]) {
      if (line.len === 4) {
        const isUsed = line.coords.some(p => usedCoords.has(p.r + ',' + p.c));
        if (!isUsed) {
          const focus = pickFocus(line.coords);
          const type = line.dir === 'h' ? 'h_stripe' : 'v_stripe';
          newSpecials.push({ r: focus.r, c: focus.c, tile: createXXLTile(line.fruit, type) });
          for (const p of line.coords) {
            initialElimCoords.push(p);
            usedCoords.add(p.r + ',' + p.c);
          }
        }
      }
    }

    // D. 常规 3 连
    for (const line of [...hLines, ...vLines]) {
      if (line.len === 3) {
        for (const p of line.coords) {
          initialElimCoords.push(p);
        }
      }
    }

    if (initialElimCoords.length === 0 && newSpecials.length === 0) {
      return { hasMatch: false, elimMask: Array.from({ length: XXL_ROWS }, () => Array(XXL_COLS).fill(false)), newSpecials: [], count: 0 };
    }

    // 过滤掉生成新特效的格子坐标，使其不被消除
    const filteredElimCoords = initialElimCoords.filter(p => !newSpecials.some(sp => sp.r === p.r && sp.c === p.c));
    const exp = expandXXLEliminationsWithSpecials(grid, filteredElimCoords);

    return {
      hasMatch: exp.totalCount > 0 || newSpecials.length > 0,
      elimMask: exp.elimMask,
      newSpecials,
      count: exp.totalCount
    };
  }

  // 连带波及引爆所有被消除的特殊道具（队列扩散算法）
  function expandXXLEliminationsWithSpecials(grid, initialCoords) {
    const elimMask = Array.from({ length: XXL_ROWS }, () => Array(XXL_COLS).fill(false));
    const queue = [];
    const processed = new Set();

    for (const p of initialCoords) {
      if (p.r >= 0 && p.r < XXL_ROWS && p.c >= 0 && p.c < XXL_COLS) {
        elimMask[p.r][p.c] = true;
        const t = grid[p.r][p.c];
        if (t && t.type !== 'normal') {
          const key = p.r + ',' + p.c;
          if (!processed.has(key)) {
            processed.add(key);
            queue.push({ r: p.r, c: p.c, tile: t });
          }
        }
      }
    }

    while (queue.length > 0) {
      const item = queue.shift();
      const { r, c, tile } = item;
      const affected = [];

      if (tile.type === 'h_stripe') {
        // 横条纹：消除整行
        for (let col = 0; col < XXL_COLS; col++) affected.push({ r, c: col });
      } else if (tile.type === 'v_stripe') {
        // 竖条纹：消除整列
        for (let row = 0; row < XXL_ROWS; row++) affected.push({ r: row, c });
      } else if (tile.type === 'bomb') {
        // 炸弹：3×3 爆炸
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < XXL_ROWS && nc >= 0 && nc < XXL_COLS) {
              affected.push({ r: nr, c: nc });
            }
          }
        }
      } else if (tile.type === 'rainbow') {
        // 彩虹球：消除场上数量最多的水果
        const counts = {};
        for (let row = 0; row < XXL_ROWS; row++) {
          for (let col = 0; col < XXL_COLS; col++) {
            const f = grid[row][col]?.fruit;
            if (f && f !== '🌈') counts[f] = (counts[f] || 0) + 1;
          }
        }
        let topFruit = XXL_FRUITS[0], maxC = 0;
        for (const f of Object.keys(counts)) {
          if (counts[f] > maxC) { maxC = counts[f]; topFruit = f; }
        }
        for (let row = 0; row < XXL_ROWS; row++) {
          for (let col = 0; col < XXL_COLS; col++) {
            if (grid[row][col]?.fruit === topFruit) affected.push({ r: row, c: col });
          }
        }
      }

      for (const p of affected) {
        if (!elimMask[p.r][p.c]) {
          elimMask[p.r][p.c] = true;
          const subTile = grid[p.r][p.c];
          if (subTile && subTile.type !== 'normal') {
            const key = p.r + ',' + p.c;
            if (!processed.has(key)) {
              processed.add(key);
              queue.push({ r: p.r, c: p.c, tile: subTile });
            }
          }
        }
      }
    }

    let totalCount = 0;
    for (let r = 0; r < XXL_ROWS; r++) {
      for (let c = 0; c < XXL_COLS; c++) {
        if (elimMask[r][c]) totalCount++;
      }
    }
    return { elimMask, totalCount };
  }

  // 两个相邻特效互换组合大招处理
  function handleXXLSpecialComboSwap(grid, p1, p2) {
    const t1 = grid[p1.r][p1.c];
    const t2 = grid[p2.r][p2.c];
    if (!t1 || !t2) return null;

    const center = p2;
    const initialCoords = [];
    let description = '';
    let bonusScore = 200;

    // 1. 彩虹 + 彩虹：直接清空整个棋盘
    if (isXXLRainbow(t1) && isXXLRainbow(t2)) {
      description = '🌈🌈 双彩虹神级清屏！全屏清除！';
      bonusScore = 600;
      for (let r = 0; r < XXL_ROWS; r++) {
        for (let c = 0; c < XXL_COLS; c++) initialCoords.push({ r, c });
      }
      return { initialCoords, description, bonusScore };
    }

    // 2. 彩虹 + 条纹 / 炸弹 / 普通水果
    if (isXXLRainbow(t1) || isXXLRainbow(t2)) {
      const rainbowP = isXXLRainbow(t1) ? p1 : p2;
      const otherP = isXXLRainbow(t1) ? p2 : p1;
      const otherT = grid[otherP.r][otherP.c];

      let targetFruit = otherT.fruit;
      if (targetFruit === '🌈') targetFruit = XXL_FRUITS[0];

      // 条纹 + 彩虹：全场同色全部变成条纹并一次性引爆
      if (isXXLStripe(otherT)) {
        description = '⚡🌈 条纹彩虹全屏激光风暴！';
        bonusScore = 400;
        for (let r = 0; r < XXL_ROWS; r++) {
          for (let c = 0; c < XXL_COLS; c++) {
            if (grid[r][c]?.fruit === targetFruit) {
              grid[r][c].type = Math.random() < 0.5 ? 'h_stripe' : 'v_stripe';
              initialCoords.push({ r, c });
            }
          }
        }
        initialCoords.push(rainbowP);
        return { initialCoords, description, bonusScore };
      }

      // 爆炸 + 彩虹：全场同色全部变成爆炸特效并一次性引爆
      if (isXXLBomb(otherT)) {
        description = '💥🌈 炸弹彩虹全域连环引爆！';
        bonusScore = 450;
        for (let r = 0; r < XXL_ROWS; r++) {
          for (let c = 0; c < XXL_COLS; c++) {
            if (grid[r][c]?.fruit === targetFruit) {
              grid[r][c].type = 'bomb';
              initialCoords.push({ r, c });
            }
          }
        }
        initialCoords.push(rainbowP);
        return { initialCoords, description, bonusScore };
      }

      // 普通水果 + 彩虹：消除全场所有该颜色水果
      description = `🌈 彩虹爆发：消除全场【${targetFruit}】！`;
      bonusScore = 180;
      for (let r = 0; r < XXL_ROWS; r++) {
        for (let c = 0; c < XXL_COLS; c++) {
          if (grid[r][c]?.fruit === targetFruit) {
            initialCoords.push({ r, c });
          }
        }
      }
      initialCoords.push(rainbowP);
      return { initialCoords, description, bonusScore };
    }

    // 3. 条纹 + 爆炸：3条直线大范围十字清场（3行+3列）
    if ((isXXLStripe(t1) && isXXLBomb(t2)) || (isXXLBomb(t1) && isXXLStripe(t2))) {
      description = '⚡💥 巨型十字超级激光（3行×3列清场）！';
      bonusScore = 320;
      const cr = center.r, cc = center.c;
      for (let dr = -1; dr <= 1; dr++) {
        const r = cr + dr;
        if (r >= 0 && r < XXL_ROWS) {
          for (let c = 0; c < XXL_COLS; c++) initialCoords.push({ r, c });
        }
      }
      for (let dc = -1; dc <= 1; dc++) {
        const c = cc + dc;
        if (c >= 0 && c < XXL_COLS) {
          for (let r = 0; r < XXL_ROWS; r++) initialCoords.push({ r, c });
        }
      }
      return { initialCoords, description, bonusScore };
    }

    // 4. 爆炸 + 爆炸：5×5 超大范围连环爆炸
    if (isXXLBomb(t1) && isXXLBomb(t2)) {
      description = '💥💥 5×5 超级核弹连环爆炸！';
      bonusScore = 350;
      const cr = center.r, cc = center.c;
      for (let dr = -2; dr <= 2; dr++) {
        for (let dc = -2; dc <= 2; dc++) {
          const r = cr + dr, c = cc + dc;
          if (r >= 0 && r < XXL_ROWS && c >= 0 && c < XXL_COLS) initialCoords.push({ r, c });
        }
      }
      return { initialCoords, description, bonusScore };
    }

    // 5. 条纹 + 条纹：十字，一横一竖同时消除
    if (isXXLStripe(t1) && isXXLStripe(t2)) {
      description = '⚡⚡ 双条纹十字激光（整行+整列）！';
      bonusScore = 240;
      for (let c = 0; c < XXL_COLS; c++) initialCoords.push({ r: center.r, c });
      for (let r = 0; r < XXL_ROWS; r++) initialCoords.push({ r, c: center.c });
      return { initialCoords, description, bonusScore };
    }

    return null;
  }

  // 寻找场上任意一个可交换的有效移动
  function findAnyXXLMove(grid) {
    const dirs = [[0, 1], [1, 0]];
    for (let r = 0; r < XXL_ROWS; r++) {
      for (let c = 0; c < XXL_COLS; c++) {
        for (const [dr, dc] of dirs) {
          const nr = r + dr;
          const nc = c + dc;
          if (nr < XXL_ROWS && nc < XXL_COLS) {
            const t1 = grid[r][c];
            const t2 = grid[nr][nc];
            if (canSwapXXLSpecials(t1, t2)) {
              return { r1: r, c1: c, r2: nr, c2: nc };
            }
            // 试探交换
            grid[r][c] = t2;
            grid[nr][nc] = t1;
            const res = detectXXLMatchesAndSpecials(grid, { r1: r, c1: c, r2: nr, c2: nc });
            grid[r][c] = t1;
            grid[nr][nc] = t2;

            if (res.hasMatch) {
              return { r1: r, c1: c, r2: nr, c2: nc };
            }
          }
        }
      }
    }
    return null;
  }

  // 生成开局无匹配且必有解的棋盘
  function generateSolvableXXLGrid() {
    for (let loop = 0; loop < 100; loop++) {
      const grid = Array.from({ length: XXL_ROWS }, () => Array(XXL_COLS).fill(null));
      for (let r = 0; r < XXL_ROWS; r++) {
        for (let c = 0; c < XXL_COLS; c++) {
          let attempts = 0;
          let fruit;
          do {
            fruit = getRandomXXLFruit();
            attempts++;
            const matchH = c >= 2 && grid[r][c - 1]?.fruit === fruit && grid[r][c - 2]?.fruit === fruit;
            const matchV = r >= 2 && grid[r - 1][c]?.fruit === fruit && grid[r - 2][c]?.fruit === fruit;
            if (!matchH && !matchV) break;
          } while (attempts < 50);
          grid[r][c] = createXXLTile(fruit, 'normal');
        }
      }
      if (findAnyXXLMove(grid)) return grid;
    }
    return Array.from({ length: XXL_ROWS }, () => Array.from({ length: XXL_COLS }, () => createXXLTile(getRandomXXLFruit(), 'normal')));
  }

  // 下落与新生成水果（同时安放新合成的特效）
  function dropAndRefillXXL(grid, elimMask, newSpecials = []) {
    // 1. 先将新合成的特效安放在对应格子上
    for (const sp of newSpecials) {
      grid[sp.r][sp.c] = sp.tile;
    }
    // 2. 清除其他被消除的格子
    //    注意：连锁扩散（条纹扫整行/彩虹清同色）可能把"刚合成的特效格"再次标进 elimMask，
    //    必须保护这些格子，否则玩家刚合成的彩虹球/炸弹会被自己这一步清掉。
    const keep = new Set();
    for (const sp of newSpecials) keep.add(sp.r + ',' + sp.c);
    for (let r = 0; r < XXL_ROWS; r++) {
      for (let c = 0; c < XXL_COLS; c++) {
        if (elimMask[r][c] && !keep.has(r + ',' + c)) grid[r][c] = null;
      }
    }
    // 3. 纵向各列下落
    for (let c = 0; c < XXL_COLS; c++) {
      let writeRow = XXL_ROWS - 1;
      for (let r = XXL_ROWS - 1; r >= 0; r--) {
        if (grid[r][c] !== null) {
          grid[writeRow][c] = grid[r][c];
          if (writeRow !== r) grid[r][c] = null;
          writeRow--;
        }
      }
      // 4. 顶部补全新水果
      for (let r = writeRow; r >= 0; r--) {
        grid[r][c] = createXXLTile(getRandomXXLFruit(), 'normal');
      }
    }
  }

  // 重新洗牌
  function shuffleXXLBoard(isAuto = false) {
    if (!xxlGame || xxlGame.isCompleted) return;
    const allTiles = [];
    for (let r = 0; r < XXL_ROWS; r++) {
      for (let c = 0; c < XXL_COLS; c++) {
        allTiles.push(xxlGame.grid[r][c]);
      }
    }

    for (let attempt = 0; attempt < 50; attempt++) {
      allTiles.sort(() => Math.random() - 0.5);
      let idx = 0;
      for (let r = 0; r < XXL_ROWS; r++) {
        for (let c = 0; c < XXL_COLS; c++) {
          xxlGame.grid[r][c] = allTiles[idx++];
        }
      }
      const m = detectXXLMatchesAndSpecials(xxlGame.grid);
      if (!m.hasMatch && findAnyXXLMove(xxlGame.grid)) break;
    }

    xxlGame.selected = null;
    xxlGame.hintMove = null;
    renderXXLBoardGrid();
    showToast(isAuto ? '🔄 当前无可消除组合，已自动重新洗牌！' : '🔀 水果已重新排列！');
  }

  // 启动消消乐（直接进入游戏，无需邀请，不写对局记录）
  const XXL_SAVE_KEY = 'werewolf_extension_xxl_save';
  function hasSavedXXLGame() { try { const raw = localStorage.getItem(XXL_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && d.grid && !d.isCompleted); } catch (e) { return false; } }
  function clearXXLSave() { try { localStorage.removeItem(XXL_SAVE_KEY); } catch (e) { /* ignore */ } }
  function saveXXLGame() {
    try {
      if (!xxlGame || xxlGame.isCompleted) { clearXXLSave(); return false; }
      localStorage.setItem(XXL_SAVE_KEY, JSON.stringify({
        v: 1, grid: xxlGame.grid, score: xxlGame.score, targetScore: xxlGame.targetScore,
        nextRewardAt: xxlGame.nextRewardAt, movesLeft: xxlGame.movesLeft,
        hintsRemaining: xxlGame.hintsRemaining, shufflesRemaining: xxlGame.shufflesRemaining,
        isCompleted: false, rewardClaimed: xxlGame.rewardClaimed, combo: xxlGame.combo || 0
      }));
      return true;
    } catch (e) { return false; }
  }
  function resumeXXLGame() {
    let d = null;
    try { const raw = localStorage.getItem(XXL_SAVE_KEY); d = raw ? JSON.parse(raw) : null; } catch (e) { d = null; }
    if (!d || !d.grid) { startXXLGame(); return; }
    if (xxlHintTimer) { clearTimeout(xxlHintTimer); xxlHintTimer = null; }
    xxlGame = {
      grid: d.grid, selected: null, hintMove: null, score: d.score || 0,
      targetScore: d.targetScore || XXL_TARGET_SCORE, nextRewardAt: d.nextRewardAt || XXL_TARGET_SCORE,
      movesLeft: (d.movesLeft === undefined ? XXL_TOTAL_MOVES : d.movesLeft),
      hintsRemaining: (d.hintsRemaining === undefined ? 3 : d.hintsRemaining),
      shufflesRemaining: (d.shufflesRemaining === undefined ? 3 : d.shufflesRemaining),
      isCompleted: false, rewardClaimed: !!d.rewardClaimed, animating: false, combo: d.combo || 0
    };
    renderXXLGameUI();
    showToast('🔖 已恢复进行中的消消乐（得分 ' + xxlGame.score + '）');
  }

  function startXXLGame() {
    if (xxlHintTimer) { clearTimeout(xxlHintTimer); xxlHintTimer = null; }
    const grid = generateSolvableXXLGrid();

    xxlGame = {
      grid,
      selected: null, // { r, c }
      hintMove: null, // { r1, c1, r2, c2 }
      score: 0,
      targetScore: XXL_TARGET_SCORE,
      nextRewardAt: XXL_TARGET_SCORE * 2,
      movesLeft: XXL_TOTAL_MOVES,
      hintsRemaining: 3,
      shufflesRemaining: 3,
      isCompleted: false,
      rewardClaimed: false,
      animating: false,
      combo: 0
    };

    renderXXLGameUI();
  }

  // 渲染消消乐主界面
