  // 刷新消消乐棋盘格子（支持条纹、炸弹、彩虹等特效视觉与角标）
  function renderXXLBoardGrid() {
    const container = sheet?.querySelector('#xxl-board-grid');
    if (!container || !xxlGame) return;

    const { grid, selected, hintMove } = xxlGame;
    let html = '';

    for (let r = 0; r < XXL_ROWS; r++) {
      for (let c = 0; c < XXL_COLS; c++) {
        const val = grid[r][c];
        const isSel = selected && selected.r === r && selected.c === c;
        const isHint = hintMove && ((hintMove.r1 === r && hintMove.c1 === c) || (hintMove.r2 === r && hintMove.c2 === c));

        if (!val) {
          html += `<div style="width:38px;height:38px;border-radius:8px;background:var(--ubp-card-2);opacity:0.3;"></div>`;
          continue;
        }

        let borderStyle = 'border:1px solid var(--ubp-line);background:var(--ubp-card);';
        let specialBadge = '';
        let specialOverlay = '';
        let titleTip = '普通水果';

        if (val.type === 'h_stripe') {
          titleTip = '横条纹特效：消除整行';
          borderStyle = 'border:1.5px solid #38BDF8;background:rgba(56,189,248,0.22);box-shadow:inset 0 0 6px rgba(56,189,248,0.5);';
          specialOverlay = '<span style="position:absolute;inset:0;border-radius:7px;background:linear-gradient(180deg, transparent 40%, rgba(56,189,248,0.5) 45%, rgba(56,189,248,0.95) 50%, rgba(56,189,248,0.5) 55%, transparent 60%);pointer-events:none;"></span>';
          specialBadge = '<span style="position:absolute;bottom:0;right:1px;font-size:9px;line-height:1;color:#38BDF8;font-weight:bold;text-shadow:0 0 2px #000;">↔️</span>';
        } else if (val.type === 'v_stripe') {
          titleTip = '竖条纹特效：消除整列';
          borderStyle = 'border:1.5px solid #818CF8;background:rgba(129,140,248,0.22);box-shadow:inset 0 0 6px rgba(129,140,248,0.5);';
          specialOverlay = '<span style="position:absolute;inset:0;border-radius:7px;background:linear-gradient(90deg, transparent 40%, rgba(129,140,248,0.5) 45%, rgba(129,140,248,0.95) 50%, rgba(129,140,248,0.5) 55%, transparent 60%);pointer-events:none;"></span>';
          specialBadge = '<span style="position:absolute;bottom:0;right:1px;font-size:9px;line-height:1;color:#818CF8;font-weight:bold;text-shadow:0 0 2px #000;">↕️</span>';
        } else if (val.type === 'bomb') {
          titleTip = '爆炸特效：3×3九宫格大爆炸';
          borderStyle = 'border:1.5px solid #F59E0B;background:rgba(245,158,11,0.25);box-shadow:inset 0 0 8px rgba(245,158,11,0.6);';
          specialBadge = '<span style="position:absolute;bottom:0;right:1px;font-size:10px;line-height:1;color:#F59E0B;text-shadow:0 0 2px #000;">💣</span>';
        } else if (val.type === 'rainbow') {
          titleTip = '彩虹球：与任意水果互换消除全场同色！两两组合更强！';
          borderStyle = 'border:2px solid #EC4899;background:radial-gradient(circle, rgba(236,72,153,0.35), rgba(59,130,246,0.25));box-shadow:0 0 8px rgba(236,72,153,0.7);';
        }

        if (isSel) {
          borderStyle = 'border:2px solid #EC4899;background:rgba(236,72,153,0.35);box-shadow:0 0 10px rgba(236,72,153,0.9);transform:scale(1.08);';
        } else if (isHint) {
          borderStyle = 'border:2px solid #F59E0B;background:rgba(245,158,11,0.3);box-shadow:0 0 10px rgba(245,158,11,0.9);animation:xxl-pulse 0.8s infinite;';
        }

        const fruitHtml = val.type === 'rainbow'
          ? '<span style="font-size:24px;line-height:1;">🌈</span>'
          : `<span style="font-size:22px;line-height:1;">${val.fruit}</span>`;

        html += `
          <button data-xxl-act="xxl-tile" data-r="${r}" data-c="${c}" title="${titleTip}" style="width:38px;height:38px;display:flex;align-items:center;justify-content:center;position:relative;border-radius:8px;cursor:pointer;user-select:none;transition:transform 0.12s, box-shadow 0.12s;padding:0;${borderStyle}">
            ${fruitHtml}
            ${specialOverlay}
            ${specialBadge}
          </button>
        `;
      }
    }

    container.innerHTML = html;

    const scoreEl = sheet?.querySelector('#xxl-score-text');
    if (scoreEl) scoreEl.textContent = xxlGame.score;
    const movesEl = sheet?.querySelector('#xxl-moves-text');
    if (movesEl) {
      movesEl.textContent = xxlGame.movesLeft;
      movesEl.style.color = xxlGame.movesLeft <= 5 ? '#EF4444' : '#F59E0B';
    }
    const progEl = sheet?.querySelector('#xxl-progress-bar');
    if (progEl) {
      const pct = Math.min(100, Math.round((xxlGame.score / xxlGame.targetScore) * 100));
      progEl.style.width = `${pct}%`;
    }
  }

  // 连续奖励：通关后每再累计 2000 分 +1 积分
  function xxlCheckMilestones() {
    if (!xxlGame) return;
    while (xxlGame.score >= xxlGame.nextRewardAt) {
      xxlGame.nextRewardAt += 2000;
      addPoints(1);
      showToast('🎉 累计得分 ' + xxlGame.score + '！连续奖励 +1 积分（当前 ' + loadPoints() + '）');
    }
  }

  // 通关胜利处理（获得 1 积分，不写入对局记录；通过后可继续游玩，得分每累计 2000 分再 +1 积分）
  function handleXXLVictory() {
    if (!xxlGame || xxlGame.rewardClaimed) return;
    xxlGame.isCompleted = true;
    clearXXLSave();
    xxlGame.rewardClaimed = true;
    xxlGame.nextRewardAt = Math.max(xxlGame.nextRewardAt || 0, xxlGame.score + 2000);
