        </div>
        <div style="font-size:11px;color:var(--ubp-text-3);margin-bottom:14px;line-height:1.5;">还可继续游玩保留进度：之后每累计 <b style="color:#F59E0B;">2000</b> 分自动再 +1 积分</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;">
          <button data-xxl-act="xxl-exit" class="ubp-btn" style="flex:1;min-width:70px;padding:8px 0;font-size:12.5px;">🚪 退出</button>
          <button data-xxl-act="xxl-continue" class="ubp-btn primary" style="flex:1.3;min-width:96px;padding:8px 0;font-size:12.5px;background:#F59E0B;border:none;font-weight:600;">▶️ 继续游玩</button>
          <button data-xxl-act="xxl-restart" class="ubp-btn primary" style="flex:1.2;min-width:80px;padding:8px 0;font-size:12.5px;background:#EC4899;border:none;font-weight:600;">🔄 再来</button>
        </div>
      </div>
    `;
    sheet.appendChild(modal);
  }

  // 步数耗尽失败弹窗
  function handleXXLDefeat() {
    if (!xxlGame || xxlGame.isCompleted) return;
    xxlGame.isCompleted = true;
    clearXXLSave();

    const modal = document.createElement('div');
    modal.className = 'xxl-defeat-overlay';
    modal.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    modal.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:22px 18px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 25px rgba(0,0,0,0.6);animation:xxl-pop 0.3s ease-out;">
        <div style="font-size:40px;margin-bottom:8px;">💔</div>
        <div style="font-size:17px;font-weight:bold;color:#EF4444;margin-bottom:6px;">步数已用尽</div>
        <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:16px;">本次得分: ${xxlGame.score} / ${xxlGame.targetScore}，差一点就通关啦！</div>
        <div style="display:flex;gap:10px;">
          <button data-xxl-act="xxl-exit" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12.5px;">🚪 退出</button>
          <button data-xxl-act="xxl-restart" class="ubp-btn primary" style="flex:1.2;padding:8px 0;font-size:12.5px;background:#10B981;border:none;">🔄 再试一次</button>
        </div>
      </div>
    `;
    sheet.appendChild(modal);
  }

  // 核心交换与消除连击循环（支持双特效大招、单特效连锁与合成）
  function processXXLCascade(comboMultiplier = 1, swapFocus = null, comboBonusScore = 0) {
    if (!xxlGame) return;
    const gameRef = xxlGame; // 退出/重开会换掉全局引用，回调里据此丢弃过期动画
    const res = detectXXLMatchesAndSpecials(xxlGame.grid, swapFocus);
    if (!res.hasMatch && comboBonusScore === 0) {
      xxlGame.animating = false;
      renderXXLBoardGrid();

      // 判定是否达成通关目标
      if (xxlGame.score >= xxlGame.targetScore && !xxlGame.rewardClaimed) {
        // 通关只在首次结算；"继续游玩"后（rewardClaimed=true）不再拦截判负与死局洗牌
        handleXXLVictory();
        return;
      }
      // 判定步数是否用尽
      if (xxlGame.movesLeft <= 0) {
        handleXXLDefeat();
        return;
      }
      // 判定是否死局无解，自动洗牌
      if (!findAnyXXLMove(xxlGame.grid)) {
        shuffleXXLBoard(true);
      }
      return;
    }

    // 计算得分：消除水果数 * 10 * 连击倍率 + 组合大招加分 + 特效合成加分
    let specialSynthesisBonus = 0;
    for (const sp of res.newSpecials) {
      if (sp.tile.type === 'rainbow') specialSynthesisBonus += 100;
      else if (sp.tile.type === 'bomb') specialSynthesisBonus += 50;
      else if (sp.tile.type === 'h_stripe' || sp.tile.type === 'v_stripe') specialSynthesisBonus += 30;
    }

    const pts = Math.round(res.count * 10 * comboMultiplier) + comboBonusScore + specialSynthesisBonus;
    xxlGame.score += pts;
    xxlCheckMilestones();

    // 动画：被消除的水果缩小淡出
    for (let r = 0; r < XXL_ROWS; r++) {
      for (let c = 0; c < XXL_COLS; c++) {
        if (res.elimMask[r][c]) {
          const btn = sheet?.querySelector(`[data-xxl-act="xxl-tile"][data-r="${r}"][data-c="${c}"]`);
          if (btn) {
            btn.style.transform = 'scale(0.15)';
            btn.style.opacity = '0';
          }
        }
      }
    }

    // 掉落并新生成
    setTimeout(() => {
      if (xxlGame !== gameRef) return; // 期间已退出/重开：丢弃旧回调
      dropAndRefillXXL(xxlGame.grid, res.elimMask, res.newSpecials);
      renderXXLBoardGrid();
      // 递归处理连击（连锁时不带 swapFocus，自然在中间合成）
      setTimeout(() => {
        if (xxlGame !== gameRef) return;
        processXXLCascade(comboMultiplier + 0.5, null, 0);
      }, 170);
    }, 220);
  }

  // 点击水果格子交互
  function handleXXLTileClick(r, c) {
    if (!xxlGame || xxlGame.isCompleted || xxlGame.animating) return;

    if (xxlGame.hintMove) {
      xxlGame.hintMove = null;
      if (xxlHintTimer) { clearTimeout(xxlHintTimer); xxlHintTimer = null; }
    }

    if (!xxlGame.selected) {
      xxlGame.selected = { r, c };
      renderXXLBoardGrid();
      return;
    }

    if (xxlGame.selected.r === r && xxlGame.selected.c === c) {
      xxlGame.selected = null;
      renderXXLBoardGrid();
      return;
    }

    const prevR = xxlGame.selected.r;
    const prevC = xxlGame.selected.c;
    const isAdjacent = Math.abs(prevR - r) + Math.abs(prevC - c) === 1;

    if (!isAdjacent) {
      xxlGame.selected = { r, c };
      renderXXLBoardGrid();
      return;
    }

    // 1. 检查是否触发双特效互换组合大招（或彩虹球与任意水果互换）
    const t1 = xxlGame.grid[prevR][prevC];
    const t2 = xxlGame.grid[r][c];

    if (canSwapXXLSpecials(t1, t2)) {
      const combo = handleXXLSpecialComboSwap(xxlGame.grid, { r: prevR, c: prevC }, { r, c });
      if (combo) {
        // 必须先确认拿到 combo 再扣步数/上锁：否则未来新增特效组合返回 null 时，
        // animating 会永久为 true、movesLeft 白扣，之后所有点击被挡 → 棋盘卡死
        xxlGame.selected = null;
        xxlGame.movesLeft--;
        xxlGame.animating = true;
        showToast(combo.description);
        const exp = expandXXLEliminationsWithSpecials(xxlGame.grid, combo.initialCoords);

        // 高亮消除动画
        for (let row = 0; row < XXL_ROWS; row++) {
          for (let col = 0; col < XXL_COLS; col++) {
            if (exp.elimMask[row][col]) {
              const btn = sheet?.querySelector(`[data-xxl-act="xxl-tile"][data-r="${row}"][data-c="${col}"]`);
              if (btn) {
                btn.style.transform = 'scale(0.15)';
                btn.style.opacity = '0';
              }
            }
          }
        }

        xxlGame.score += Math.round(exp.totalCount * 12) + combo.bonusScore;
        xxlCheckMilestones(); // 大招得分同样要过里程碑（常规消除路径在 processXXLCascade 里调用），否则跨档奖励会被跳过

        const comboRef = xxlGame;
        setTimeout(() => {
          if (xxlGame !== comboRef) return; // 期间已退出/重开：丢弃旧回调
          dropAndRefillXXL(xxlGame.grid, exp.elimMask, []);
          renderXXLBoardGrid();
          setTimeout(() => {
            if (xxlGame !== comboRef) return;
            processXXLCascade(1.5, null, 0);
          }, 180);
        }, 250);
        return;
      }
    }

    // 2. 常规交换
    const tmp = xxlGame.grid[prevR][prevC];
    xxlGame.grid[prevR][prevC] = xxlGame.grid[r][c];
    xxlGame.grid[r][c] = tmp;

    const check = detectXXLMatchesAndSpecials(xxlGame.grid, { r1: prevR, c1: prevC, r2: r, c2: c });

    if (!check.hasMatch) {
      // 无效交换：换回并抖动
      xxlGame.grid[r][c] = xxlGame.grid[prevR][prevC];
      xxlGame.grid[prevR][prevC] = tmp;

      const btn1 = sheet?.querySelector(`[data-xxl-act="xxl-tile"][data-r="${prevR}"][data-c="${prevC}"]`);
      const btn2 = sheet?.querySelector(`[data-xxl-act="xxl-tile"][data-r="${r}"][data-c="${c}"]`);
      if (btn1) { btn1.style.animation = 'xxl-shake 0.3s'; setTimeout(() => { if (btn1) btn1.style.animation = ''; }, 300); }
      if (btn2) { btn2.style.animation = 'xxl-shake 0.3s'; setTimeout(() => { if (btn2) btn2.style.animation = ''; }, 300); }

      xxlGame.selected = { r, c };
      renderXXLBoardGrid();
      return;
    }

    // 有效交换：扣除步数并进入连击消除
    xxlGame.selected = null;
    xxlGame.movesLeft--;
    xxlGame.animating = true;
    renderXXLBoardGrid();

    processXXLCascade(1, { r1: prevR, c1: prevC, r2: r, c2: c }, 0);
  }

  // 提示功能
  function handleXXLHint() {
    if (!xxlGame || xxlGame.isCompleted || xxlGame.animating) return;
    if (xxlGame.hintsRemaining <= 0) {
      showToast('💡 提示次数已用完');
      return;
    }

    const move = findAnyXXLMove(xxlGame.grid);
    if (!move) {
      shuffleXXLBoard(true);
      return;
    }

    xxlGame.hintsRemaining--;
    xxlGame.hintMove = move;
    xxlGame.selected = null;
    renderXXLBoardGrid();

    const hintBtn = sheet?.querySelector('[data-xxl-act="xxl-hint"]');
    if (hintBtn) hintBtn.textContent = `💡 提示 (${xxlGame.hintsRemaining})`;

    if (xxlHintTimer) clearTimeout(xxlHintTimer);
    xxlHintTimer = setTimeout(() => {
      if (xxlGame && xxlGame.hintMove) {
        xxlGame.hintMove = null;
        renderXXLBoardGrid();
      }
    }, 3000);
  }

  // 重排功能
  function handleXXLShuffle() {
    if (!xxlGame || xxlGame.isCompleted || xxlGame.animating) return;
    if (xxlGame.shufflesRemaining <= 0) {
      showToast('🔀 重排次数已用完');
      return;
    }
    xxlGame.shufflesRemaining--;
    const shufBtn = sheet?.querySelector('[data-xxl-act="xxl-shuffle"]');
    if (shufBtn) shufBtn.textContent = `🔀 重排 (${xxlGame.shufflesRemaining})`;
    shuffleXXLBoard(false);
  }

  // 消消乐事件分发
  function handleXXLAction(act, target) {
    if (act === 'xxl-open') {
      startXXLGame();
      return;
    }
    if (act === 'xxl-exit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      sheet?.querySelector('.xxl-victory-overlay')?.remove();
      sheet?.querySelector('.xxl-defeat-overlay')?.remove();
      if (xxlHintTimer) { clearTimeout(xxlHintTimer); xxlHintTimer = null; }
      const xxlSaved = saveXXLGame();
      xxlGame = null;
      renderMiniGameLobby();
      showToast(xxlSaved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
      return;
    }
    if (act === 'xxl-quit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
      sheet?.querySelector('.xxl-victory-overlay')?.remove();
      sheet?.querySelector('.xxl-defeat-overlay')?.remove();
      if (xxlHintTimer) { clearTimeout(xxlHintTimer); xxlHintTimer = null; }
      clearXXLSave();
      xxlGame = null;
      renderSetup();
      showToast('🚪 已结束本局消消乐');
      return;
    }
    if (act === 'xxl-restart') {
      sheet?.querySelector('.xxl-victory-overlay')?.remove();
      sheet?.querySelector('.xxl-defeat-overlay')?.remove();
      startXXLGame();
      return;
    }
    if (act === 'xxl-continue') {
      sheet?.querySelector('.xxl-victory-overlay')?.remove();
      if (xxlGame) xxlGame.isCompleted = false;
      showToast('🎮 继续游玩！之后每累计 2000 分再 +1 积分');
      return;
    }
    if (act === 'xxl-tile') {
      const r = parseInt(target.dataset.r, 10);
      const c = parseInt(target.dataset.c, 10);
      if (Number.isFinite(r) && Number.isFinite(c)) {
        handleXXLTileClick(r, c);
      }
      return;
    }
    if (act === 'xxl-hint') {
      handleXXLHint();
      return;
    }
    if (act === 'xxl-shuffle') {
      handleXXLShuffle();
      return;
    }
  }
  // __XXL_ENGINE_END__

  // ============================================================
  // ========== 人物关系编辑（小游戏机专属：自定义人物关系 · 分类快捷选择 · 互逆自动适配） ==========
  // 记录结构：{ a, b, type, state } 表示「b 是 a 的 type」（例：a=小明, b=小红, type=妻子 → 小红是小明的妻子）。
  // 互逆适配：妻子↔丈夫、妈妈/爸爸→儿子/女儿、女儿/儿子→妈妈/爸爸、姐姐↔妹妹/弟弟 等自动生成；
  //           若 A 是 B 的妈妈，B 的页面会自动显示「B 是 A 的儿子/女儿」，无需手动再编辑。
  // 自定义关系会注入多人游戏的 AI 提示词（狼人杀/谁是卧底走 getInterPersonalContext，其余牌桌走 getCharacterDatabaseContext）。
  const CONTACT_RELATION_EDIT_SUPPORT = true;
  const CUSTOM_RELATIONS_KEY = 'thgame_custom_relations';

  const RELATION_CATEGORIES = [
    { id: 'spouse', name: '💞 配偶关系', types: ['妻子', '丈夫', '前妻', '前夫', '女朋友', '男朋友', '前女友', '前男友'] },
    { id: 'family', name: '👨‍👩‍👧 家庭关系', types: ['妈妈', '爸爸', '女儿', '儿子', '姐姐', '妹妹', '哥哥', '弟弟', '养女', '养子'] },
    { id: 'friend', name: '🤝 好友关系', types: ['闺蜜', '兄弟', '死党', '青梅竹马'] },
    { id: 'other', name: '🗂️ 其他关系', types: ['同学', '同事', '仇敌'] }
  ];

  function loadCustomRelations() {
    try {
      const raw = localStorage.getItem(CUSTOM_RELATIONS_KEY);
      if (raw) {
        const arr = JSON.parse(raw);
        if (Array.isArray(arr)) {
          return arr.filter(r => r && typeof r.a === 'string' && r.a.trim() && typeof r.b === 'string' && r.b.trim() && typeof r.type === 'string' && r.type.trim())
            .map(r => ({ a: r.a.trim(), b: r.b.trim(), type: r.type.trim(), state: typeof r.state === 'string' ? r.state.trim() : '' }));
        }
      }
    } catch (e) { /* ignore */ }
    return [];
  }
  function saveCustomRelations(list) {
    try { localStorage.setItem(CUSTOM_RELATIONS_KEY, JSON.stringify(Array.isArray(list) ? list : [])); } catch (e) { /* ignore */ }
  }

  // 合并「自定义关系」+「资料库人物关系表」；自定义在前，并附带 custom/idx 供界面识别与删除
  function getAllCharacterRelations() {
    const merged = [];
    const seen = new Set();
    const pushRel = (a, b, type, state, custom, idx) => {
      if (!a || !b || !type) return;
      const key = normalizeCharName(a) + '|' + normalizeCharName(b) + '|' + type;
      if (seen.has(key)) return;
      seen.add(key);
      merged.push({ a: String(a), b: String(b), type: String(type), state: state ? String(state) : '', custom: !!custom, idx: (idx == null ? -1 : idx) });
    };
    loadCustomRelations().forEach((r, i) => pushRel(r.a, r.b, r.type, r.state, true, i));
    try {
      for (const r of getCharacterRelationsFromDB()) pushRel(r.a, r.b, r.type, r.state, false, -1);
    } catch (e) { /* ignore */ }
    return merged;
  }

  function getRelationsForName(name) {
    if (!name) return [];
    return getAllCharacterRelations().filter(r => isNameMatch(r.a, name) || isNameMatch(r.b, name));
  }

  function guessCharacterGender(name) {
    try {
      const prof = getCharacterProfile(name) || {};
      const g = String(prof.gender || '');
      if (g.includes('男')) return 'male';
      if (g.includes('女')) return 'female';
    } catch (e) { /* ignore */ }
    return '';
  }

  // 互逆关系：b 是 a 的 type 时，a 相对 b 的关系（按 a 的性别自动选择称谓）
  function inverseRelationType(type, personForGender) {
    const t = String(type || '');
    const gender = guessCharacterGender(personForGender);
    const child = gender === 'male' ? '儿子' : (gender === 'female' ? '女儿' : '孩子');
    const parent = gender === 'male' ? '爸爸' : (gender === 'female' ? '妈妈' : '家长');
    const younger = gender === 'male' ? '弟弟' : (gender === 'female' ? '妹妹' : '手足');
    const elder = gender === 'male' ? '哥哥' : (gender === 'female' ? '姐姐' : '手足');
    switch (t) {
      case '妻子': return '丈夫';
      case '丈夫': return '妻子';
      case '前妻': return '前夫';
      case '前夫': return '前妻';
      case '女朋友': return '男朋友';
      case '男朋友': return '女朋友';
      case '前女友': return '前男友';
      case '前男友': return '前女友';
      case '妈妈': case '爸爸': return child;
      case '女儿': case '儿子': case '养女': case '养子': return parent;
      case '姐姐': case '哥哥': return younger;
      case '妹妹': case '弟弟': return elder;
      default: return t;
    }
  }

  // 页面视角的关系句子：明确「谁是谁的什么」，并按互逆映射自动适配
  function relationTextForName(r, name) {
    if (!r) return '';
    const type = r.type || '关系';
    const state = r.state ? '（' + r.state + '）' : '';
    if (isNameMatch(r.b, name)) return r.b + ' 是 ' + r.a + ' 的 ' + type + state;
    if (isNameMatch(r.a, name)) return r.a + ' 是 ' + r.b + ' 的 ' + inverseRelationType(type, r.a) + state;
    return r.b + ' 是 ' + r.a + ' 的 ' + type + state;
  }

  // AI 提示词用句子（同时点名双方，始终说明谁与谁是什么关系）
  function relationSentenceForName(r, name) {
    if (!r) return '';
    const type = r.type || '关系';
    const state = r.state ? '（' + r.state + '）' : '';
    if (!name || isNameMatch(r.a, name) || isNameMatch(r.b, name)) return r.b + ' 是 ' + r.a + ' 的 ' + type + state;
    return r.a + ' 与 ' + r.b + ' 是 ' + type + state;
  }

  function addCustomRelation(a, b, type, state) {
    if (!a || !b || !type) return false;
    const list = loadCustomRelations();
    const na = normalizeCharName(a), nb = normalizeCharName(b);
    const dup = list.some(r => normalizeCharName(r.a) === na && normalizeCharName(r.b) === nb && r.type === type);
    if (dup) return false;
    list.push({ a: a, b: b, type: type, state: state || '' });
    saveCustomRelations(list);
    return true;
  }

  function removeCustomRelationAt(idx) {
    const list = loadCustomRelations();
    const i = parseInt(idx, 10);
    if (!Number.isFinite(i) || i < 0 || i >= list.length) return null;
    const removed = list.splice(i, 1)[0];
    saveCustomRelations(list);
    return removed || null;
  }

  // 关系编辑面板：选择对象 + 关系方向 + 分类快捷类型 + 自定义关系 + 双方效果预览
