          '<button type="button" id="rel-dir-b" style="flex:1;padding:7px 4px;font-size:11.5px;border-radius:8px;cursor:pointer;border:1.5px solid var(--ubp-line);background:var(--ubp-card-2);color:var(--ubp-text);"></button>' +
        '</div>' +
