        '<div id="rel-preview" style="font-size:11.5px;color:var(--ubp-text-2);line-height:1.7;background:rgba(139,92,246,0.08);border:1px dashed var(--ubp-line);border-radius:10px;padding:8px 10px;margin-bottom:12px;">📌 选择对象与关系后，这里会预览双方页面显示的效果</div>' +
        '<div style="display:flex;gap:8px;">' +
