      dirA.style.background = direction === 'target_is_owner' ? 'rgba(139,92,246,0.18)' : 'var(--ubp-card-2)';
      dirB.style.borderColor = direction === 'owner_is_target' ? '#8B5CF6' : 'var(--ubp-line)';
