    ov.querySelector('#rel-custom').addEventListener('input', refreshPreview);
    ov.querySelector('#rel-cancel').addEventListener('click', () => ov.remove());
    ov.addEventListener('click', (e) => { if (e.target === ov) ov.remove(); });
    ov.querySelector('#rel-save').addEventListener('click', () => {
      const target = (ov.querySelector('#rel-target')?.value || '').trim();
