      const type = custom || selType;
      if (!target) { showToast('⚠️ 请选择关系对象'); return; }
      if (!type) { showToast('⚠️ 请选择分类快捷类型或填写自定义关系'); return; }
      const a = direction === 'target_is_owner' ? ownerName : target;
      const b = direction === 'target_is_owner' ? target : ownerName;
      if (!addCustomRelation(a, b, type, state)) { showToast('⚠️ 相同的关系已存在，无需重复添加'); return; }
      ov.remove();
      showToast('✅ 已添加关系：' + relationTextForName({ a: a, b: b, type: type, state: state }, ownerName));
      if (typeof onSaved === 'function') onSaved(ownerName);
