  // ========== 通讯录 · 角色头像编辑（小游戏机专属：本地照片裁剪压缩 + 头像覆盖表） ==========
  // 编辑结果：自定义角色直接写回其档案；数据库角色写入头像覆盖表，邀请列表与游戏展示统一生效。
  const CONTACT_AVATAR_EDIT_SUPPORT = true;
  const CONTACT_AVATARS_KEY = 'thgame_contact_avatars';

  function loadContactAvatarOverrides() {
    try {
      const raw = localStorage.getItem(CONTACT_AVATARS_KEY);
      if (raw) {
        const m = JSON.parse(raw);
        if (m && typeof m === 'object' && !Array.isArray(m)) return m;
      }
    } catch (e) { /* ignore */ }
    return {};
  }
  function saveContactAvatarOverrides(map) {
    try { localStorage.setItem(CONTACT_AVATARS_KEY, JSON.stringify(map && typeof map === 'object' ? map : {})); } catch (e) { /* ignore */ }
  }
  function getContactAvatarOverride(name) {
    if (!name) return '';
    const m = loadContactAvatarOverrides();
    return (m && typeof m[name] === 'string') ? m[name] : '';
  }
  function setContactAvatarOverride(name, avatar) {
    if (!name) return;
    const m = loadContactAvatarOverrides();
    if (avatar) m[name] = avatar; else delete m[name];
    saveContactAvatarOverrides(m);
