        '<div style="font-size:15px;font-weight:700;color:var(--ubp-text);margin-bottom:12px;">🖼️ 编辑头像 · ' + escapeHtml(name) + '</div>' +
        '<div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">' +
          '<div id="ct-av-preview" style="width:72px;height:72px;border-radius:50%;overflow:hidden;background:linear-gradient(135deg,#38bdf8,#8b5cf6);display:flex;align-items:center;justify-content:center;flex-shrink:0;">' + previewHTML() + '</div>' +
