        '<div style="display:flex;gap:8px;">' +
          '<button id="ct-av-cancel" class="ubp-btn" style="flex:1;padding:9px;font-size:12.5px;">取消</button>' +
          '<button id="ct-av-save" class="ubp-btn primary" style="flex:1.6;padding:9px;font-size:12.5px;background:#8B5CF6;border:none;color:#fff;font-weight:600;">💾 保存头像</button>' +
        '</div>' +
      '</div>';
    const refreshPreview = () => {
