      ccReadImageFile(f, (dataUrl) => {
        if (dataUrl) { pendingAvatar = dataUrl; refreshPreview(); showToast('✅ 照片已就绪，点保存生效'); }
        else showToast('⚠️ 照片读取失败，请换一张试试');
      });
