    });
    ov.querySelector('#ct-av-clear').addEventListener('click', () => { pendingAvatar = ''; refreshPreview(); });
    ov.querySelector('#ct-av-cancel').addEventListener('click', () => ov.remove());
    ov.addEventListener('click', (e) => { if (e.target === ov) ov.remove(); });
    ov.querySelector('#ct-av-save').addEventListener('click', () => {
      const urlVal = (ov.querySelector('#ct-av-urlinput')?.value || '').trim();
      if (urlVal) pendingAvatar = urlVal;
      const cus = getCustomCharacterByName(name);
      if (cus) {
        const arr = loadCustomCharacters();
        const idx = arr.findIndex(x => x && x.name === name);
        if (idx >= 0) { arr[idx].avatar = pendingAvatar || ''; saveCustomCharacters(arr); }
        setContactAvatarOverride(name, '');
      } else {
        setContactAvatarOverride(name, pendingAvatar || '');
