  // ========== 通讯录（查看录入的通讯录好友：资料 / 人物关系一屏浏览） ==========
  // 入口：游戏中心首页「对局记录」右侧的 📇 通讯录图标；
  // 数据来源：loadContactsWithAvatars()（瑟瑟数据库的恋爱对象表/重要角色表；小游戏机还含自定义角色）。
  // 小游戏机额外支持编辑角色头像与人物关系（见 CONTACT_AVATAR_EDIT_SUPPORT / CONTACT_RELATION_EDIT_SUPPORT）。
  // __CONTACTS_ENGINE_BEGIN__

  const CONTACTS_AVATAR_EDIT = (typeof CONTACT_AVATAR_EDIT_SUPPORT !== 'undefined') && CONTACT_AVATAR_EDIT_SUPPORT === true;
  const CONTACTS_RELATION_EDIT = (typeof CONTACT_RELATION_EDIT_SUPPORT !== 'undefined') && CONTACT_RELATION_EDIT_SUPPORT === true;
  let contactsBookFilter = '';

  // —— 语音配置（TTS）：API 地址 / 密钥 / 模型 + 音色池 + 角色音色快捷分配 ——
  // 存 localStorage（键 werewolf_extension_voice_config），供语音合成读取；首次打开自动带 8 条常见初始音色。
  const CONTACTS_VOICE_CONFIG_KEY = 'werewolf_extension_voice_config';
  const CONTACTS_VOICE_MODEL_PRESETS = [
    'gpt-4o-mini-tts', 'tts-1', 'tts-1-hd',
    'FunAudioLLM/CosyVoice2-0.5B', 'fishaudio/fish-speech-1.5',
    'speech-2.6-hd', 'speech-2.6-turbo', 's2.1-pro-free', 'seed-tts-2.0', 'eleven_multilingual_v2'
  ];
  const CONTACTS_VOICE_DEFAULT_POOL = [
    { id: 'alloy', name: 'Alloy（中性）' },
    { id: 'ash', name: 'Ash（中性）' },
    { id: 'coral', name: 'Coral（女声）' },
    { id: 'echo', name: 'Echo（男声）' },
    { id: 'fable', name: 'Fable（叙事）' },
    { id: 'nova', name: 'Nova（女声明亮）' },
    { id: 'onyx', name: 'Onyx（男声低沉）' },
    { id: 'shimmer', name: 'Shimmer（女声柔和）' }
  ];

  // 试听固定示例句（试听按钮统一读这一句）
  const CONTACTS_VOICE_TRY_TEXT = '你好呀，这是一段语音试听，听听这个音色读出来是什么效果。';

  function contactsVoiceDefaultConfig() {
    return {
      apiUrl: '',
      apiKey: '',
      model: '',
      speakEnabled: false,
      voices: CONTACTS_VOICE_DEFAULT_POOL.map(v => ({ id: v.id, name: v.name })),
      assign: {}
    };
  }

  function loadContactsVoiceConfig() {
    try {
      const raw = localStorage.getItem(CONTACTS_VOICE_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw) || {};
        return {
          apiUrl: typeof p.apiUrl === 'string' ? p.apiUrl : '',
          apiKey: typeof p.apiKey === 'string' ? p.apiKey : '',
          model: typeof p.model === 'string' ? p.model : '',
          speakEnabled: !!p.speakEnabled,
          voices: Array.isArray(p.voices)
            ? p.voices.filter(v => v && typeof v.id === 'string').map(v => ({ id: v.id, name: typeof v.name === 'string' ? v.name : '' }))
            : [],
          assign: (p.assign && typeof p.assign === 'object') ? p.assign : {}
        };
      }
    } catch (e) { /* ignore */ }
    return contactsVoiceDefaultConfig();
  }

  function saveContactsVoiceConfig(cfg) {
    try { localStorage.setItem(CONTACTS_VOICE_CONFIG_KEY, JSON.stringify(cfg)); } catch (e) { /* ignore */ }
  }

  function contactsVoiceNameOf(cfg, id) {
    const hit = ((cfg && cfg.voices) || []).find(v => v.id === id);
    return (hit && hit.name) ? hit.name : id;
  }

  // 角色音色快捷选择下拉：compact=true 用于通讯录列表行内，否则用于好友资料页
  function contactsVoiceAssignSelectHTML(cfg, charName, compact) {
    const cur = ((cfg && cfg.assign) || {})[charName] || '';
    const opts = ['<option value="">默认音色</option>'];
    let hasCur = !cur;
    ((cfg && cfg.voices) || []).forEach(v => {
      if (!v.id) return;
      if (v.id === cur) hasCur = true;
      opts.push('<option value="' + escapeAttr(v.id) + '"' + (v.id === cur ? ' selected' : '') + '>' + escapeHtml(v.name || v.id) + '</option>');
    });
    if (!hasCur) opts.push('<option value="' + escapeAttr(cur) + '" selected>' + escapeHtml(cur + '（不在音色池）') + '</option>');
    const st = compact
      ? 'max-width:88px;font-size:10.5px;padding:1px 2px;'
      : 'flex:1;min-width:0;font-size:12px;padding:4px 6px;';
    return '<select class="ct-voice-sel" data-name="' + escapeAttr(charName) + '" title="为该角色选择音色（音色池在通讯录右上角 ⚙️ 语音设置里维护）" style="' + st + 'background:var(--ubp-card-2);color:var(--ubp-text);border:1px solid var(--ubp-line);border-radius:7px;box-sizing:border-box;">' + opts.join('') + '</select>';
  }

  function contactsBindVoiceSelects(root) {
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll('select.ct-voice-sel').forEach(sel => {
      sel.addEventListener('change', () => {
        const n = sel.dataset.name || '';
        if (!n) return;
        const cfg = loadContactsVoiceConfig();
        const v = sel.value || '';
        if (v) cfg.assign[n] = v; else delete cfg.assign[n];
        saveContactsVoiceConfig(cfg);
        showToast(v ? '🎙️ 已为「' + n + '」指定音色：' + contactsVoiceNameOf(cfg, v) : '🎙️ 已恢复「' + n + '」的默认音色');
      });
    });
  }

  // —— 语音朗读引擎：开关打开后游戏 AI 发言按角色配置音色朗读；试听按钮用固定示例句 ——
  // 顺序播放队列上限 20 条：超出时丢弃最旧的待播条目，保证长局连发也能排队播完。
  const CONTACTS_VOICE_QUEUE_MAX = 20;
  let contactsVoiceAudio = null;
  let contactsVoiceQueue = [];
  let contactsVoicePlaying = false;
  let contactsVoiceSession = 0; // 语音会话号：StopAll 时自增，丢弃已过期的在途 TTS 请求，避免退出游戏后仍朗读
  let contactsVoiceAutoplayWarned = false;
  let contactsVoicePoolExpanded = false; // 音色池是否展开（默认收起，点「▼ 展开全部」查看所有音色）

  function contactsVoiceSpeechUrl(apiUrl) {
    const u = String(apiUrl || '').trim().replace(/\/+$/, '');
    if (!u) return '';
    if (/\/audio\/speech$/i.test(u)) return u;
    return u + '/audio/speech';
  }

  function contactsVoiceCleanText(text) {
    let s = String(text == null ? '' : text).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    if (s.length > 300) s = s.slice(0, 300);
    return s;
  }

  // 仅清空排队中尚未朗读的语音（不打断正在朗读的一条）；离开游戏请用 contactsVoiceStopAll() 清空排队并切断在读语音
  function contactsVoiceClearQueue() {
    contactsVoiceQueue = [];
  }

  function contactsVoiceStopAll() {
    contactsVoiceSession++;
    contactsVoiceQueue = [];
    if (contactsVoiceAudio) {
      try {
        contactsVoiceAudio.onended = null;
        contactsVoiceAudio.onerror = null;
        contactsVoiceAudio.pause();
        if (contactsVoiceAudio.src && contactsVoiceAudio.src.indexOf('blob:') === 0) URL.revokeObjectURL(contactsVoiceAudio.src);
      } catch (e) { /* ignore */ }
      contactsVoiceAudio = null;
    }
    contactsVoicePlaying = false;
  }

  function contactsVoicePlayBlob(blob, manual, onDone) {
    let objUrl = '';
    try {
      objUrl = URL.createObjectURL(blob);
      const audio = new Audio(objUrl);
      contactsVoiceAudio = audio;
      let finished = false;
      const finish = () => {
        if (finished) return;
        finished = true;
        if (contactsVoiceAudio === audio) contactsVoiceAudio = null;
        try { URL.revokeObjectURL(objUrl); } catch (e2) { /* ignore */ }
        onDone();
      };
      audio.onended = finish;
      audio.onerror = () => { if (manual) showToast('⚠️ 音频播放失败，请检查音色 ID 是否正确'); finish(); };
      const p = audio.play();
      if (p && typeof p.catch === 'function') {
        p.catch(() => {
          if (manual) showToast('⚠️ 浏览器拦截了播放，请再点一次试听');
          else if (!contactsVoiceAutoplayWarned) { contactsVoiceAutoplayWarned = true; showToast('⚠️ 浏览器拦截了语音自动播放，请先在页面上点一下'); }
          finish();
        });
      }
    } catch (e) {
      try { if (objUrl) URL.revokeObjectURL(objUrl); } catch (e2) { /* ignore */ }
      if (manual) showToast('⚠️ 播放失败：' + ((e && e.message) || e));
      onDone();
    }
  }

  function contactsVoicePump() {
    const item = contactsVoiceQueue.shift();
    if (!item) { contactsVoicePlaying = false; return; }
    contactsVoicePlaying = true;
    const session = contactsVoiceSession;
    const cfg = loadContactsVoiceConfig();
    const url = contactsVoiceSpeechUrl(cfg.apiUrl);
    if (!url) { contactsVoicePlaying = false; if (item.manual) showToast('⚠️ 请先在语音设置里填写 API 地址'); return; }
    const headers = { 'Content-Type': 'application/json' };
    if (cfg.apiKey) headers['Authorization'] = 'Bearer ' + cfg.apiKey;
    const body = { model: cfg.model || 'tts-1', input: item.text, voice: item.voiceId, response_format: 'mp3' };
    fetch(url, { method: 'POST', headers: headers, body: JSON.stringify(body) })
      .then(resp => {
        if (session !== contactsVoiceSession) return null;
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        return resp.blob();
      })
      .then(blob => {
        if (session !== contactsVoiceSession) return;
        if (!blob || !blob.size) throw new Error('空音频');
        contactsVoicePlayBlob(blob, item.manual, () => contactsVoicePump());
      })
      .catch(err => {
        if (session !== contactsVoiceSession) return;
        if (item.manual) showToast('⚠️ 试听失败：' + ((err && err.message) || '请检查 API 地址 / 密钥 / 音色 ID'));
        contactsVoicePump();
      });
  }

  function contactsVoiceEnqueue(voiceId, text, manual) {
    if (!voiceId || !text) return;
    contactsVoiceQueue.push({ voiceId: voiceId, text: text, manual: !!manual });
    if (contactsVoiceQueue.length > CONTACTS_VOICE_QUEUE_MAX) contactsVoiceQueue.splice(0, contactsVoiceQueue.length - CONTACTS_VOICE_QUEUE_MAX);
    if (!contactsVoicePlaying) contactsVoicePump();
  }

  // 手动试听：打断当前朗读与排队，立刻用示例句播放
  function contactsVoiceTryPlay(voiceId, label) {
    const cfg = loadContactsVoiceConfig();
    if (!cfg.apiUrl) { showToast('⚠️ 请先点 ⚙️ 语音设置填写 API 地址'); return; }
    if (!voiceId) { showToast('⚠️ 请先选择 / 填写音色'); return; }
    contactsVoiceStopAll();
    contactsVoiceEnqueue(voiceId, CONTACTS_VOICE_TRY_TEXT, true);
    showToast('🔊 正在试听音色：' + (label || voiceId));
  }

  // 游戏 AI 发言自动朗读：需开关打开、角色已分配音色；游戏面板已关闭则跳过
  function contactsVoiceAutoSpeak(charName, text) {
    try {
      const cfg = loadContactsVoiceConfig();
      if (!cfg.speakEnabled || !cfg.apiUrl) return;
      const name = String(charName || '').trim();
      if (!name || name === '我') return;
      const voiceId = (cfg.assign || {})[name];
      if (!voiceId) return;
      const clean = contactsVoiceCleanText(text);
      if (!clean) return;
      if (sheet && !sheet.isConnected) return;
      contactsVoiceEnqueue(voiceId, clean, false);
    } catch (e) { /* ignore */ }
  }

  function contactsBookList() {
    try {
      const result = loadContactsWithAvatars();
      return { contacts: (result && result.contacts) || [], error: result && result.error };
    } catch (e) {
      return { contacts: [], error: 'exception' };
    }
  }

  // 人物关系：小游戏机合并「自定义关系 + 数据库人物关系表」并按页面视角生成完整句子（谁是谁的什么，亲属/伴侣自动互逆）
  function contactRelationLines(name) {
    try {
      const all = (typeof getAllCharacterRelations === 'function') ? getAllCharacterRelations() : getCharacterRelationsFromDB();
      const rels = all.filter(r => isNameMatch(r.a, name) || isNameMatch(r.b, name));
      const out = [];
      const seen = new Set();
      for (const r of rels) {
        const other = isNameMatch(r.a, name) ? r.b : r.a;
        const text = (typeof relationTextForName === 'function') ? relationTextForName(r, name) : '';
        const key = text || (r.a + '|' + r.b + '|' + r.type);
        if (seen.has(key)) continue;
        seen.add(key);
        out.push({ other: other, type: r.type || '关系', state: r.state || '', custom: !!r.custom, idx: (r.idx == null ? -1 : r.idx), text: text });
        if (out.length >= 12) break;
      }
      return out;
    } catch (e) { return []; }
  }

