  function contactsBindVoiceSettings() {
    const root = sheet;
    if (!root) return;
    const cfg = loadContactsVoiceConfig();
    const urlEl = root.querySelector('#ct-voice-url');
    const keyEl = root.querySelector('#ct-voice-key');
    const modelEl = root.querySelector('#ct-voice-model');
    const savedEl = root.querySelector('#ct-voice-saved');
    const markSaved = () => { if (savedEl) { savedEl.textContent = '✅ 已自动保存'; savedEl.style.color = '#10B981'; } };
    const persist = () => {
      // 以最新存储为基准：音色池支持原地增删（不整页重绘），闭包里的旧 cfg 可能已过期
      const cur = loadContactsVoiceConfig();
      cur.apiUrl = urlEl ? urlEl.value.trim() : cur.apiUrl;
      cur.apiKey = keyEl ? keyEl.value.trim() : cur.apiKey;
      cur.model = modelEl ? modelEl.value.trim() : cur.model;
      root.querySelectorAll('.ct-voice-row').forEach(row => {
        const i = parseInt(row.dataset.vi, 10);
        if (!Number.isFinite(i) || !cur.voices[i]) return;
        const vid = row.querySelector('.ct-voice-vid');
        const vname = row.querySelector('.ct-voice-vname');
        if (vid) cur.voices[i].id = vid.value.trim();
        if (vname) cur.voices[i].name = vname.value.trim();
      });
      saveContactsVoiceConfig(cur);
      markSaved();
    };
    [urlEl, keyEl, modelEl].forEach(el => {
      if (!el) return;
      el.addEventListener('input', persist);
      el.addEventListener('change', persist);
    });
    // 委托到滚动容器：新增行无需重新绑定，容器随每次渲染重建也不会累积监听
    const poolScroller = root.querySelector('#ct-voice-settings-scroll');
    if (poolScroller) poolScroller.addEventListener('input', (e) => {
      const t = e.target;
      if (t && t.classList && (t.classList.contains('ct-voice-vid') || t.classList.contains('ct-voice-vname'))) persist();
    });
    const presetEl = root.querySelector('#ct-voice-model-preset');
    if (presetEl) presetEl.addEventListener('change', () => {
      const v = presetEl.value || '';
      if (v && modelEl) modelEl.value = v;
      persist();
    });
  }

  function handleContactsAction(act, target) {
    if (act === 'go-contacts') { contactsBookFilter = ''; renderContactsBook(); return; }
    if (act === 'contacts-back') { contactsBookFilter = ''; if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); renderSetup(); return; }
    if (act === 'contacts-list') { renderContactsBook(); return; }
    if (act === 'contacts-view') {
      const n = (target && target.dataset) ? target.dataset.name : '';
      if (n) renderContactDetail(n);
      return;
    }
    if (act === 'contacts-avatar-edit') {
      const n = (target && target.dataset) ? target.dataset.name : '';
      if (n && CONTACTS_AVATAR_EDIT && typeof openContactAvatarEditor === 'function') openContactAvatarEditor(n);
      return;
    }
    if (act === 'contacts-relation-add') {
      const n = (target && target.dataset) ? target.dataset.name : '';
      if (n && CONTACTS_RELATION_EDIT && typeof openRelationEditor === 'function') openRelationEditor(n, renderContactDetail);
      return;
    }
    if (act === 'contacts-relation-del') {
      const n = (target && target.dataset) ? target.dataset.name : '';
      const idx = parseInt((target && target.dataset && target.dataset.idx != null) ? target.dataset.idx : '-1', 10);
      if (CONTACTS_RELATION_EDIT && Number.isFinite(idx) && typeof removeCustomRelationAt === 'function') {
        const removed = removeCustomRelationAt(idx);
        if (removed) showToast('🗑️ 已删除关系：' + removed.a + ' ↔ ' + removed.b + '（' + removed.type + '）');
        if (n) renderContactDetail(n);
      }
      return;
    }
    if (act === 'contacts-voice-settings') { renderContactsVoiceSettings(); return; }
    if (act === 'contacts-voice-back') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); renderContactsBook(); return; }
    if (act === 'contacts-voice-pool-toggle') {
      contactsVoicePoolExpanded = !contactsVoicePoolExpanded;
      contactsVoiceApplyPoolVisibility();
      return;
    }
    if (act === 'contacts-voice-add') {
      const cfg = loadContactsVoiceConfig();
      const hadVoices = cfg.voices.length > 0;
      cfg.voices.push({ id: '', name: '' });
      saveContactsVoiceConfig(cfg);
      // 界面固定不跳转：能增量追加就绝不整页重绘
      const scroller = sheet ? sheet.querySelector('#ct-voice-settings-scroll') : null;
      const keepTop = scroller ? scroller.scrollTop : 0;
      const poolBox = sheet ? sheet.querySelector('#ct-voice-pool') : null;
      if (hadVoices && poolBox) {
        contactsVoicePoolExpanded = true;
        const holder = document.createElement('div');
        holder.innerHTML = contactsVoiceRowHTML(cfg.voices[cfg.voices.length - 1], cfg.voices.length - 1);
        const rowEl = holder.firstElementChild;
        if (rowEl) poolBox.appendChild(rowEl);
        contactsVoiceApplyPoolVisibility();
        contactsVoiceUpdatePoolTitle(cfg);
      } else {
        // 空池 -> 第一条：整页重绘（结构变化不可避免），但保持原滚动位置
        contactsVoicePoolExpanded = true;
        renderContactsVoiceSettings();
        const sc2 = sheet ? sheet.querySelector('#ct-voice-settings-scroll') : null;
        if (sc2) sc2.scrollTop = keepTop;
      }
      const rows = sheet.querySelectorAll('.ct-voice-row');
      const lastRow = rows[rows.length - 1];
      if (lastRow) contactsVoiceFocusRowInput(lastRow);
      showToast('🎵 已添加一条音色，填写音色 ID 后即可分配');
      return;
    }
    if (act === 'contacts-voice-del') {
      const vi = parseInt((target && target.dataset && target.dataset.vi != null) ? target.dataset.vi : '-1', 10);
      const cfg = loadContactsVoiceConfig();
      if (Number.isFinite(vi) && vi >= 0 && vi < cfg.voices.length) {
        const removed = cfg.voices.splice(vi, 1)[0];
        saveContactsVoiceConfig(cfg);
        // 界面固定不跳转：直接移除该行并重排索引（删到空池时才重绘）
        const rowEl = sheet ? sheet.querySelector('.ct-voice-row[data-vi="' + vi + '"]') : null;
        if (rowEl && cfg.voices.length > 0) {
          rowEl.remove();
          sheet.querySelectorAll('.ct-voice-row').forEach((r, i) => {
            r.dataset.vi = i;
            r.querySelectorAll('[data-vi]').forEach(el2 => { el2.dataset.vi = i; });
          });
          contactsVoiceUpdatePoolTitle(cfg);
        } else {
          const scroller = sheet ? sheet.querySelector('#ct-voice-settings-scroll') : null;
          const keepTop = scroller ? scroller.scrollTop : 0;
          renderContactsVoiceSettings();
          const sc2 = sheet ? sheet.querySelector('#ct-voice-settings-scroll') : null;
          if (sc2) sc2.scrollTop = keepTop;
        }
        showToast('🗑️ 已删除音色：' + ((removed && (removed.name || removed.id)) || '未命名'));
      }
      return;
    }
    if (act === 'contacts-voice-toggle') {
      const cfg = loadContactsVoiceConfig();
      cfg.speakEnabled = !cfg.speakEnabled;
      saveContactsVoiceConfig(cfg);
      if (!cfg.speakEnabled) contactsVoiceStopAll();
      renderContactsVoiceSettings();
      showToast(cfg.speakEnabled ? '🔊 已开启角色语音朗读：游戏里 AI 发言将按角色音色朗读' : '🔇 已关闭角色语音朗读');
      return;
    }
    if (act === 'contacts-voice-try') {
      const vi = parseInt((target && target.dataset && target.dataset.vi != null) ? target.dataset.vi : '-1', 10);
      const cfg = loadContactsVoiceConfig();
      const v = (Number.isFinite(vi) && vi >= 0 && vi < cfg.voices.length) ? cfg.voices[vi] : null;
      if (!v || !v.id) { showToast('⚠️ 请先填写这条音色的 ID 再试听'); return; }
      contactsVoiceTryPlay(v.id, v.name || v.id);
      return;
    }
    if (act === 'contacts-voice-try-char') {
      const n = (target && target.dataset) ? target.dataset.name : '';
      if (!n) return;
      const cfg = loadContactsVoiceConfig();
      const vid = (cfg.assign || {})[n] || '';
      if (!vid) { showToast('⚠️「' + n + '」还没有分配音色，请先在下拉里选一个'); return; }
      contactsVoiceTryPlay(vid, n);
      return;
    }
  }
  // __CONTACTS_ENGINE_END__

  // ========== 记忆翻牌 (Concentration · 单人配对 · 计翻牌次数与用时 · 通关+1积分) ==========
  // 规则：4×4=8 对 / 4×6=12 对 / 6×6=18 对；每轮翻恰好 2 张，图案相同保持翻开、不同短暂展示后翻回；
  //       全部配对即通关（+1 积分）；统计总翻牌次数与用时并记录各棋盘最佳成绩；
  //       设置内可自由开关限时模式与翻牌上限（默认均关闭，默认值 180 秒 / 80 次可自行修改）。
  // __MEMORY_ENGINE_BEGIN__

  const MEMORY_BEST_KEY = 'werewolf_extension_memory_best_v2';
  const MEMORY_CONFIG_KEY = 'werewolf_extension_memory_config';
  const MEMORY_TIME_DEFAULT = 180;
  const MEMORY_FLIP_DEFAULT = 80;

  const MEMORY_EMOJIS = [
    '🌟', '🌸', '🔥', '💎', '🎵', '🍀', '🌈', '🎮', '🎯', '🐱',
    '🐶', '🦊', '🐼', '🦄', '🐸', '🍕', '🍦', '🚀', '⚡', '💫',
    '🎪', '🎨', '🎭', '🎲', '🧩', '💜', '💛', '💚', '🩵', '🤍'
  ];

  const MEMORY_PRESETS = [
    { id: 'easy', name: '简单 4×4', rows: 4, cols: 4, pairs: 8, desc: '8 对 · 轻松上手' },
    { id: 'normal', name: '普通 4×6', rows: 4, cols: 6, pairs: 12, desc: '12 对 · 经典棋盘' },
    { id: 'hard', name: '困难 6×6', rows: 6, cols: 6, pairs: 18, desc: '18 对 · 记忆挑战' }
  ];

  let memoryGame = null;
  let memoryTimer = null;
  let memoryLockInput = false;

  const MEMORY_STYLE =
    '<style>' +
    '#mem-board .mem-tile{perspective:420px;user-select:none;-webkit-tap-highlight-color:transparent;}' +
    '#mem-board .mem-inner{position:relative;width:100%;height:100%;transition:transform .26s ease;transform-style:preserve-3d;}' +
    '#mem-board .mem-tile.mem-open .mem-inner{transform:rotateY(180deg);}' +
    '#mem-board .mem-face{position:absolute;top:0;left:0;right:0;bottom:0;display:flex;align-items:center;justify-content:center;border-radius:8px;backface-visibility:hidden;-webkit-backface-visibility:hidden;user-select:none;}' +
    '#mem-board .mem-face-back{background:linear-gradient(135deg,#6366F1,#8B5CF6);color:#fff;box-shadow:inset 0 0 0 1px rgba(255,255,255,0.18);}' +
    '#mem-board .mem-face-front{background:var(--ubp-card-2,#26262a);border:1px solid var(--ubp-line);transform:rotateY(180deg);}' +
    '#mem-board .mem-tile.mem-matched .mem-face-front{background:rgba(34,197,94,0.18);border:2px solid #22C55E;}' +
    '</style>';

  function memoryPresetOf(id) {
    return MEMORY_PRESETS.find(p => p.id === id) || MEMORY_PRESETS[0];
  }

  function memoryTimeText(sec) {
    const m = Math.floor((Number(sec) || 0) / 60).toString().padStart(2, '0');
    const s = Math.floor((Number(sec) || 0) % 60).toString().padStart(2, '0');
    return m + ':' + s;
  }

  function loadMemoryConfig() {
    const def = { preset: 'easy', timeEnabled: false, timeLimit: MEMORY_TIME_DEFAULT, flipEnabled: false, flipLimit: MEMORY_FLIP_DEFAULT };
    try {
      const raw = localStorage.getItem(MEMORY_CONFIG_KEY);
      if (!raw) return def;
      const c = JSON.parse(raw);
      if (!c || typeof c !== 'object') return def;
      const cfg = {
        preset: memoryPresetOf(c.preset).id,
        timeEnabled: !!c.timeEnabled,
        timeLimit: Number(c.timeLimit) > 0 ? Math.floor(Number(c.timeLimit)) : MEMORY_TIME_DEFAULT,
        flipEnabled: !!c.flipEnabled,
        flipLimit: Number(c.flipLimit) > 0 ? Math.floor(Number(c.flipLimit)) : MEMORY_FLIP_DEFAULT
      };
      // 兼容旧版配置：旧 timeLimit / stepLimit 为正数时视为已开启对应限制
      if (c.timeEnabled === undefined && Number(c.timeLimit) > 0) { cfg.timeEnabled = true; cfg.timeLimit = Math.floor(Number(c.timeLimit)); }
      if (c.flipEnabled === undefined && Number(c.stepLimit) > 0) { cfg.flipEnabled = true; cfg.flipLimit = Math.floor(Number(c.stepLimit)); }
      return cfg;
    } catch (e) { return def; }
  }

  function saveMemoryConfig(cfg) {
    try { localStorage.setItem(MEMORY_CONFIG_KEY, JSON.stringify(cfg)); } catch (e) { /* ignore */ }
  }

  function loadMemoryBest() {
    try { return JSON.parse(localStorage.getItem(MEMORY_BEST_KEY)) || {}; } catch (e) { return {}; }
  }

  function saveMemoryBest(presetId, flips, seconds) {
    try {
      const best = loadMemoryBest();
      const cur = best[presetId];
      if (!cur || flips < cur.flips || (flips === cur.flips && seconds < cur.seconds)) {
        best[presetId] = { flips: flips, seconds: seconds };
        localStorage.setItem(MEMORY_BEST_KEY, JSON.stringify(best));
      }
    } catch (e) { /* ignore */ }
  }

  const MEMORY_SAVE_KEY = 'werewolf_extension_memory_save';
  function hasSavedMemoryGame() { try { const raw = localStorage.getItem(MEMORY_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && d.cards && (d.phase === 'ready' || d.phase === 'play')); } catch (e) { return false; } }
  function clearMemorySave() { try { localStorage.removeItem(MEMORY_SAVE_KEY); } catch (e) { /* ignore */ } }
  function saveMemoryGame() {
    try {
      const g = memoryGame;
      if (!g || (g.phase !== 'ready' && g.phase !== 'play')) { clearMemorySave(); return false; }
      localStorage.setItem(MEMORY_SAVE_KEY, JSON.stringify({
        v: 1, session: g.session, presetId: g.presetId, rows: g.rows, cols: g.cols, pairs: g.pairs,
        cards: g.cards.map(c => ({ emoji: c.emoji, flipped: c.matched ? true : false, matched: !!c.matched })),
        flips: g.flips, matchedCount: g.matchedCount, elapsedSeconds: g.elapsedSeconds,
        timeLimit: g.timeLimit, flipLimit: g.flipLimit, phase: g.phase, rewardClaimed: !!g.rewardClaimed
      }));
      return true;
    } catch (e) { return false; }
  }
  function resumeMemoryGame() {
    let d = null;
    try { const raw = localStorage.getItem(MEMORY_SAVE_KEY); d = raw ? JSON.parse(raw) : null; } catch (e) { d = null; }
    if (!d || !d.cards) { memoryNewGame(); return; }
    memoryStop();
    memoryGame = {
      session: 'mem_' + Date.now() + '_' + Math.floor(Math.random() * 100000),
      presetId: d.presetId, rows: d.rows, cols: d.cols, pairs: d.pairs, cards: d.cards,
      selected: [], flips: d.flips || 0, matchedCount: d.matchedCount || 0,
      startAt: 0, elapsedSeconds: d.elapsedSeconds || 0,
      timeLimit: (d.timeLimit === undefined ? -1 : d.timeLimit),
      flipLimit: (d.flipLimit === undefined ? -1 : d.flipLimit),
      phase: (d.phase === 'play' ? 'play' : 'ready'), rewardClaimed: !!d.rewardClaimed
    };
    if (memoryGame.phase === 'play') {
      memoryGame.startAt = Date.now() - (memoryGame.elapsedSeconds || 0) * 1000;
      startMemoryTimer();
    }
    renderMemoryGameUI();
    showToast('🔖 已恢复进行中的记忆翻牌（已配对 ' + memoryGame.matchedCount + '/' + memoryGame.pairs + '）');
  }

  function memoryNewGame() {
    memoryStop();
    const cfg = loadMemoryConfig();
    const preset = memoryPresetOf(cfg.preset);
    const emojis = [...MEMORY_EMOJIS].sort(() => Math.random() - 0.5).slice(0, preset.pairs);
    const cards = [];
    for (const e of emojis) {
      cards.push({ emoji: e, flipped: false, matched: false });
      cards.push({ emoji: e, flipped: false, matched: false });
    }
    for (let i = cards.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [cards[i], cards[j]] = [cards[j], cards[i]];
    }
    memoryGame = {
      session: 'mem_' + Date.now() + '_' + Math.floor(Math.random() * 100000),
      presetId: preset.id,
      rows: preset.rows,
      cols: preset.cols,
      pairs: preset.pairs,
      cards: cards,
      selected: [],
      flips: 0,
      matchedCount: 0,
      startAt: 0,
      elapsedSeconds: 0,
      timeLimit: cfg.timeEnabled ? cfg.timeLimit : -1,
      flipLimit: cfg.flipEnabled ? cfg.flipLimit : -1,
      phase: 'ready',
      rewardClaimed: false
    };
    renderMemoryGameUI();
    const limitText = (memoryGame.timeLimit > 0 ? ' · 限时 ' + memoryGame.timeLimit + ' 秒' : '') + (memoryGame.flipLimit > 0 ? ' · 翻牌上限 ' + memoryGame.flipLimit + ' 次' : '');
    showToast('🧠 ' + preset.name + ' 开局：翻出两张相同图案即配对' + limitText);
  }

  // 停止计时并清空当前对局（返回大厅 / 重新开局前统一调用）
  function memoryStop() {
    stopMemoryTimer();
    memoryLockInput = false;
    memoryGame = null;
  }

  function startMemoryTimer() {
    stopMemoryTimer();
    memoryTimer = setInterval(() => {
      const g = memoryGame;
      if (!g || g.phase !== 'play') { stopMemoryTimer(); return; }
      g.elapsedSeconds = Math.floor((Date.now() - g.startAt) / 1000);
      memorySyncTimeEl();
      if (g.timeLimit > 0 && g.elapsedSeconds >= g.timeLimit) {
        g.elapsedSeconds = g.timeLimit;
        memoryFinish('timeout');
      }
    }, 500);
  }

  function stopMemoryTimer() {
    if (memoryTimer) { clearInterval(memoryTimer); memoryTimer = null; }
  }

  function handleMemoryCardClick(idx) {
    const g = memoryGame;
    if (!g || (g.phase !== 'ready' && g.phase !== 'play') || memoryLockInput) return;
    const card = g.cards[idx];
    if (!card || card.flipped || card.matched || g.selected.includes(idx) || g.selected.length >= 2) return;

    if (g.phase === 'ready') { g.phase = 'play'; g.startAt = Date.now(); startMemoryTimer(); }

    card.flipped = true;
    g.flips++;
    g.selected.push(idx);
    memoryUpdateTile(idx);
    memoryUpdateStats();

    // 翻牌上限：超过允许次数直接判负
    if (g.flipLimit > 0 && g.flips > g.flipLimit) { memoryFinish('fliplimit'); return; }

    if (g.selected.length < 2) return;

    const a = g.selected[0];
    const b = g.selected[1];
    const ca = g.cards[a];
    const cb = g.cards[b];
    if (ca.emoji === cb.emoji) {
      ca.matched = true;
      cb.matched = true;
      g.matchedCount++;
      g.selected = [];
      memoryUpdateTile(a);
      memoryUpdateTile(b);
      memoryUpdateStats();
      if (g.matchedCount === g.pairs) memoryFinish('win');
      return;
    }

    // 图案不同：短暂展示后翻回背面（展示期间锁定输入）
    const session = g.session;
    memoryLockInput = true;
    setTimeout(() => {
      if (!memoryGame || memoryGame.session !== session) { memoryLockInput = false; return; }
      ca.flipped = false;
      cb.flipped = false;
      memoryGame.selected = [];
      memoryLockInput = false;
      memoryUpdateTile(a);
      memoryUpdateTile(b);
    }, 800);
  }

  function memoryFinish(kind) {
    const g = memoryGame;
    if (!g || (g.phase !== 'ready' && g.phase !== 'play')) return;
    g.phase = kind;
    clearMemorySave();
    stopMemoryTimer();
    memoryLockInput = false;
    g.selected = [];
    if (kind === 'win') {
      saveMemoryBest(g.presetId, g.flips, g.elapsedSeconds);
      if (!g.rewardClaimed) {
        g.rewardClaimed = true;
        try { addPoints(1); } catch (e) { /* ignore */ }
        showToast('🎉 全部配对成功！+1 积分（' + g.flips + ' 次翻牌 / ' + memoryTimeText(g.elapsedSeconds) + '）');
      }
    } else if (kind === 'timeout') {
      showToast('⏰ 时间耗尽！已配对 ' + g.matchedCount + '/' + g.pairs + ' 对');
    } else {
      showToast('🚫 翻牌次数已达上限（' + g.flipLimit + ' 次）！');
    }
    memoryRevealAll();
    memoryUpdateStats();
    memoryUpdateResult();
  }

  function memoryMetrics() {
    const g = memoryGame;
    const maxW = 292;
    const gap = g.cols >= 6 ? 5 : 7;
    const tile = Math.max(34, Math.min(72, Math.floor((maxW - gap * (g.cols - 1)) / g.cols)));
    return { tile: tile, gap: gap, font: Math.max(16, Math.round(tile * 0.52)) };
  }

  function memoryBoardHTML() {
    const g = memoryGame;
    if (!g) return '';
    const m = memoryMetrics();
    let html = '<div style="display:grid;grid-template-columns:repeat(' + g.cols + ',' + m.tile + 'px);gap:' + m.gap + 'px;">';
    for (let i = 0; i < g.cards.length; i++) {
      const c = g.cards[i];
      const open = c.flipped || c.matched;
      html += '<div data-ubp-act="memory-tile" data-idx="' + i + '" class="mem-tile' + (open ? ' mem-open' : '') + (c.matched ? ' mem-matched' : '') + '" style="width:' + m.tile + 'px;height:' + m.tile + 'px;cursor:pointer;">' +
        '<div class="mem-inner">' +
          '<div class="mem-face mem-face-back" style="font-size:' + Math.round(m.font * 0.8) + 'px;">❓</div>' +
          '<div class="mem-face mem-face-front" style="font-size:' + m.font + 'px;">' + c.emoji + '</div>' +
        '</div></div>';
    }
    html += '</div>';
    return html;
  }

  function renderMemoryGameUI() {
    const g = memoryGame;
    if (!g || !sheet) return;
    const best = loadMemoryBest()[g.presetId];
    const bestPill = '<span style="font-size:11.5px;font-weight:600;color:#8B5CF6;background:rgba(139,92,246,0.15);padding:2px 8px;border-radius:999px;border:1px solid rgba(139,92,246,0.4);">🏆 ' + (best ? best.flips + ' 次 / ' + memoryTimeText(best.seconds) : '暂无记录') + '</span>';

    sheet.innerHTML =
      MEMORY_STYLE +
      '<div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;position:relative;">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 8px;flex:none;border-bottom:1px solid var(--ubp-line);">' +
          '<div style="display:flex;align-items:center;gap:8px;">' +
            '<button data-ubp-act="memory-back" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="返回小游戏大厅">←</button>' +
            '<span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🧠 记忆翻牌</span>' +
          '</div>' +
          '<div style="display:flex;align-items:center;gap:8px;">' +
            pointsLabelHTML() +
            bestPill +
            '<button data-ubp-act="memory-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏中心（不保存进度）">✕</button>' +
          '</div>' +
        '</div>' +
        '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;flex:none;font-size:12px;color:var(--ubp-text-2);">' +
          '<span id="mem-time"></span>' +
          '<span id="mem-flips"></span>' +
          '<span id="mem-progress"></span>' +
        '</div>' +
        '<div id="mem-limit-line" style="font-size:11px;color:var(--ubp-text-2);margin-bottom:6px;flex:none;"></div>' +
        '<div id="mem-board" style="position:relative;flex:1;display:flex;align-items:center;justify-content:center;min-height:0;overflow-y:auto;padding:4px 0;">' +
          '<div style="position:relative;display:inline-block;padding:8px;background:var(--ubp-card-2);border-radius:12px;border:1px solid var(--ubp-line);box-shadow:inset 0 2px 8px rgba(0,0,0,0.2);">' +
            memoryBoardHTML() +
          '</div>' +
        '</div>' +
        '<div id="mem-result" style="flex:none;"></div>' +
        '<div style="display:flex;gap:8px;align-items:center;justify-content:center;padding:6px 0 2px;flex:none;">' +
          '<button data-ubp-act="memory-new" class="ubp-btn" style="flex:1;padding:7px 0;font-size:12px;display:flex;align-items:center;justify-content:center;gap:3px;background:var(--ubp-card-2);border:1px solid var(--ubp-line);">🔄 重新开始</button>' +
          '<button data-ubp-act="memory-settings" class="ubp-btn" style="flex:1;padding:7px 0;font-size:12px;display:flex;align-items:center;justify-content:center;gap:3px;background:var(--ubp-card-2);border:1px solid var(--ubp-line);">⚙️ 难度 / 限时</button>' +
          '<button data-ubp-act="memory-back" class="ubp-btn" style="flex:1;padding:7px 0;font-size:12px;display:flex;align-items:center;justify-content:center;gap:3px;background:var(--ubp-card-2);border:1px solid var(--ubp-line);">🏠 返回大厅</button>' +
        '</div>' +
      '</div>';
    memoryUpdateStats();
  }

  function memoryUpdateTile(idx) {
    const g = memoryGame;
    if (!g || !sheet) return;
    const el = sheet.querySelector('[data-ubp-act="memory-tile"][data-idx="' + idx + '"]');
    if (!el) return;
    const c = g.cards[idx];
    el.classList.toggle('mem-open', !!(c.flipped || c.matched));
    el.classList.toggle('mem-matched', !!c.matched);
  }

  function memoryRevealAll() {
    const g = memoryGame;
    if (!g || !sheet) return;
    sheet.querySelectorAll('[data-ubp-act="memory-tile"]').forEach(el => {
      const c = g.cards[parseInt(el.dataset.idx, 10)];
      if (!c) return;
      if (!c.matched) el.classList.add('mem-open');
      if (g.phase !== 'win') el.style.opacity = c.matched ? '0.75' : '0.55';
    });
  }

  function memorySyncTimeEl() {
    const g = memoryGame;
    if (!g || !sheet) return;
    const timeEl = sheet.querySelector('#mem-time');
    if (timeEl) timeEl.textContent = '⏱ ' + memoryTimeText(g.elapsedSeconds) + (g.timeLimit > 0 ? ' / ' + memoryTimeText(g.timeLimit) : '');
  }

  function memoryUpdateStats() {
    const g = memoryGame;
    if (!g || !sheet) return;
    memorySyncTimeEl();
    const flipEl = sheet.querySelector('#mem-flips');
    if (flipEl) flipEl.textContent = '👆 翻牌 ' + g.flips + (g.flipLimit > 0 ? '/' + g.flipLimit : '');
    const progEl = sheet.querySelector('#mem-progress');
    if (progEl) progEl.textContent = '🎯 ' + g.matchedCount + '/' + g.pairs;
    const limitEl = sheet.querySelector('#mem-limit-line');
    if (limitEl) limitEl.textContent = (g.timeLimit > 0 ? '限时 ' + g.timeLimit + ' 秒' : '不限时') + ' · ' + (g.flipLimit > 0 ? '翻牌上限 ' + g.flipLimit + ' 次' : '不限步') + ' · ' + memoryPresetOf(g.presetId).name;
  }

  function memoryUpdateResult() {
    const g = memoryGame;
    const box = sheet && sheet.querySelector('#mem-result');
    if (!g || !box) return;
    if (g.phase === 'win') {
      box.innerHTML = '<div style="margin-top:8px;padding:8px 10px;border-radius:8px;text-align:center;font-size:13px;font-weight:600;background:rgba(139,92,246,0.15);color:#8B5CF6;">🎉 全部配对完成！' + g.flips + ' 次翻牌 / ' + memoryTimeText(g.elapsedSeconds) + '　<button data-ubp-act="memory-new" class="ubp-btn" style="padding:3px 10px;font-size:12px;margin-left:6px;">再来一局</button></div>';
    } else if (g.phase === 'timeout') {
      box.innerHTML = '<div style="margin-top:8px;padding:8px 10px;border-radius:8px;text-align:center;font-size:13px;font-weight:600;background:rgba(239,68,68,0.15);color:#EF4444;">⏰ 时间耗尽，未完成全部配对（已配对 ' + g.matchedCount + '/' + g.pairs + '）　<button data-ubp-act="memory-new" class="ubp-btn" style="padding:3px 10px;font-size:12px;margin-left:6px;">再来一局</button></div>';
    } else if (g.phase === 'fliplimit') {
      box.innerHTML = '<div style="margin-top:8px;padding:8px 10px;border-radius:8px;text-align:center;font-size:13px;font-weight:600;background:rgba(239,68,68,0.15);color:#EF4444;">🚫 翻牌次数已达上限（' + g.flipLimit + ' 次），挑战失败（已配对 ' + g.matchedCount + '/' + g.pairs + '）　<button data-ubp-act="memory-new" class="ubp-btn" style="padding:3px 10px;font-size:12px;margin-left:6px;">再来一局</button></div>';
    } else {
      box.innerHTML = '';
    }
  }

  function renderMemorySettings() {
    const cfg = loadMemoryConfig();
    let selPreset = cfg.preset;
    const ov = document.createElement('div');
    ov.className = 'memory-settings-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:60;background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const row = (p) => '<div data-mem-preset="' + p.id + '" style="display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:8px;margin-bottom:8px;cursor:pointer;background:' + (p.id === selPreset ? 'rgba(139,92,246,0.15)' : 'var(--ubp-card-2, #26262a)') + ';border:1.5px solid ' + (p.id === selPreset ? '#8B5CF6' : 'var(--ubp-line)') + ';"><div style="flex:1;min-width:0;"><div style="font-size:14px;font-weight:600;color:var(--ubp-text);">' + p.name + '</div><div style="font-size:11.5px;color:var(--ubp-text-3);margin-top:2px;">' + p.desc + ' · 全配需翻 ' + (p.pairs * 2) + ' 次起</div></div></div>';
    const limitRow = (id, title, desc, checked, val, min, max, unit) =>
      '<div style="padding:10px 12px;border-radius:8px;margin-bottom:8px;background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);">' +
        '<div style="display:flex;align-items:center;gap:10px;">' +
          '<div style="flex:1;min-width:0;"><div style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">' + title + '</div><div style="font-size:11px;color:var(--ubp-text-2);margin-top:2px;">' + desc + '</div></div>' +
          '<label style="display:flex;align-items:center;gap:5px;font-size:12px;color:var(--ubp-text-2);cursor:pointer;flex-shrink:0;"><input id="' + id + '-on" type="checkbox"' + (checked ? ' checked' : '') + ' style="width:15px;height:15px;accent-color:#8B5CF6;cursor:pointer;">开启</label>' +
        '</div>' +
        '<div style="display:flex;align-items:center;gap:6px;margin-top:8px;font-size:12px;color:var(--ubp-text-2);">' +
          '<input id="' + id + '" class="ubp-fieldinput" type="number" min="' + min + '" max="' + max + '" value="' + val + '" style="width:90px;padding:4px 8px;">' + unit +
        '</div>' +
      '</div>';
    ov.innerHTML =
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex:none;">' +
        '<span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">⚙️ 记忆翻牌设置</span>' +
        '<button data-mem-set="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>' +
      '</div>' +
      '<div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:8px;">棋盘大小与可选限制（保存后立即开始新一局；默认不限时、不限步）</div>' +
      '<div style="flex:1;overflow-y:auto;padding-right:2px;">' +
        MEMORY_PRESETS.map(row).join('') +
        limitRow('mem-cfg-time', '⏱ 限时模式', '超过限定时间未完成全部配对即失败，默认 ' + MEMORY_TIME_DEFAULT + ' 秒', cfg.timeEnabled, cfg.timeLimit, 10, 3600, '秒') +
        limitRow('mem-cfg-flip', '👆 翻牌上限', '超过允许的总翻牌次数即失败，默认 ' + MEMORY_FLIP_DEFAULT + ' 次（简单棋盘全配需 16 次起）', cfg.flipEnabled, cfg.flipLimit, 4, 999, '次') +
      '</div>' +
      '<div style="display:flex;gap:8px;margin-top:8px;flex:none;">' +
        '<button data-mem-set="save" class="ubp-btn" style="flex:2;padding:10px;background:#8B5CF6;color:#fff;border:none;font-size:13.5px;font-weight:600;">💾 保存并开始新游戏</button>' +
        '<button data-mem-set="cancel" class="ubp-btn" style="flex:1;padding:10px;background:var(--ubp-card-2);color:var(--ubp-text-2);border:1px solid var(--ubp-line);font-size:13.5px;">取消</button>' +
      '</div>';

    ov.querySelectorAll('[data-mem-preset]').forEach(el => {
      el.addEventListener('click', () => {
        selPreset = el.dataset.memPreset;
        ov.querySelectorAll('[data-mem-preset]').forEach(x => {
          const on = x.dataset.memPreset === selPreset;
          x.style.background = on ? 'rgba(139,92,246,0.15)' : 'var(--ubp-card-2, #26262a)';
          x.style.borderColor = on ? '#8B5CF6' : 'var(--ubp-line)';
        });
        const flipInput = ov.querySelector('#mem-cfg-flip');
        if (flipInput) {
          const minFlip = memoryPresetOf(selPreset).pairs * 2;
          flipInput.min = String(minFlip);
        }
      });
    });
    ov.querySelector('[data-mem-set="save"]').addEventListener('click', () => {
      const timeOn = !!ov.querySelector('#mem-cfg-time-on').checked;
      let timeVal = parseInt(ov.querySelector('#mem-cfg-time').value, 10);
      if (!Number.isFinite(timeVal)) timeVal = MEMORY_TIME_DEFAULT;
      timeVal = Math.max(10, Math.min(3600, timeVal));
      const flipOn = !!ov.querySelector('#mem-cfg-flip-on').checked;
      let flipVal = parseInt(ov.querySelector('#mem-cfg-flip').value, 10);
      const minFlip = memoryPresetOf(selPreset).pairs * 2;
      if (!Number.isFinite(flipVal)) flipVal = MEMORY_FLIP_DEFAULT;
      flipVal = Math.max(minFlip, Math.min(999, flipVal));
      saveMemoryConfig({ preset: selPreset, timeEnabled: timeOn, timeLimit: timeVal, flipEnabled: flipOn, flipLimit: flipVal });
      ov.remove();
      memoryNewGame();
    });
    ov.querySelector('[data-mem-set="cancel"]').addEventListener('click', () => ov.remove());
    sheet.appendChild(ov);
  }

  // __MEMORY_ENGINE_END__

  // __JUMP_ENGINE_BEGIN__
  // ========== 跳一跳（微信小游戏玩法复刻 · 独立按键长按蓄力 / 松开起跳） ==========
  // 规则：落到下一块方块 +1 分；跳到方块中心点 +2 分，连续命中中心叠加 2→4→6→8……最高连续 16 次后固定 +32 分每跳；
  //       无尽模式，分数越高方块尺寸越小、间距波动越大、容错越低；每累计 200 分 +1 积分，可选择继续游戏。
  // 说明：本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const JUMP_BEST_KEY = 'werewolf_extension_jump_best';
  const JUMP_CHARGE_MS = 1200;      // 蓄满力所需时间（毫秒）
  const JUMP_MIN_DIST = 34;         // 最短跳跃距离
  const JUMP_MAX_DIST = 360;        // 满蓄力跳跃距离
  const JUMP_GROUND_RATIO = 0.74;   // 地面线在画面中的高度比例
  const JUMP_PLAT_H = 30;           // 方块可见厚度
  const JUMP_REWARD_STEP = 200;     // 每累计 200 分 +1 积分
  const JUMP_COLORS = [
    ['#7DD3FC', '#0284C7'], ['#FCA5A5', '#DC2626'], ['#86EFAC', '#16A34A'],
    ['#FDE68A', '#D97706'], ['#C4B5FD', '#7C3AED'], ['#F9A8D4', '#DB2777'],
    ['#A5F3FC', '#0891B2'], ['#FDBA74', '#EA580C']
  ];

  let jumpGame = null;
  const jumpRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const jumpCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function jumpLoadBest() {
    try { const n = parseInt(localStorage.getItem(JUMP_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function jumpSaveBest(n) {
    try { localStorage.setItem(JUMP_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function jumpRand(min, max) { return min + Math.random() * (max - min); }
  function jumpWrap(v, m) { return ((v % m) + m) % m; }

  function jumpRoundRect(ctx, x, y, w, h, r) {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  // 难度：分数越高 → 方块越小、间距均值与波动越大
  function jumpAppendPlatform(g) {
    const d = Math.min(1, g.score / 240);
    const prev = g.platforms[g.platforms.length - 1];
    const w = Math.round(jumpRand(92 - 52 * d, 128 - 56 * d));
    const gapMin = 24 + 30 * d;
    const gapMax = 58 + 95 * d;
    const jitter = (Math.random() - 0.5) * (20 + 60 * d);
    const gap = Math.max(18, Math.min(178, jumpRand(gapMin, gapMax) + jitter));
    const c = JUMP_COLORS[Math.floor(Math.random() * JUMP_COLORS.length)];
    g.platforms.push({ x: prev.x + prev.w + gap, w, c1: c[0], c2: c[1] });
  }

  // 打开 / 重开一局
  const JUMP_SAVE_KEY = 'werewolf_extension_jump_save';
  function jumpHasSave() { try { const raw = localStorage.getItem(JUMP_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && d.platforms && d.platforms.length); } catch (e) { return false; } }
  function jumpClearSave() { try { localStorage.removeItem(JUMP_SAVE_KEY); } catch (e) { /* ignore */ } }
  function jumpSaveGame(g) {
    try {
      if (!g || g.over || g.pawn.state !== 'idle') { jumpClearSave(); return false; }
      const offset = Math.max(0, g.curIdx - 2);
      const payload = {
        v: 1, score: g.score, combo: g.combo, maxCombo: g.maxCombo, rewards: g.rewards, nextRewardAt: g.nextRewardAt,
        curIdx: g.curIdx - offset, pawnX: g.pawn.x, camX: g.camX,
        platforms: g.platforms.slice(offset).map(p => ({ x: p.x, w: p.w, c1: p.c1, c2: p.c2 }))
      };
      localStorage.setItem(JUMP_SAVE_KEY, JSON.stringify(payload));
      return true;
    } catch (e) { return false; }
  }
  function jumpResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(JUMP_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data || !data.platforms || !data.platforms.length) { jumpOpenGame(); return; }
    jumpOpenGame(data);
    showToast('🔖 已恢复进行中的跳一跳（得分 ' + (data.score || 0) + '）');
  }

  function jumpOpenGame(saveData) {
    if (jumpGame) jumpTeardown();
    if (!sheet) { renderMiniGameLobby(); return; }
    const first = { x: 40, w: 124, c1: JUMP_COLORS[0][0], c2: JUMP_COLORS[0][1] };
    const g = {
      score: 0,
      combo: 0,
      maxCombo: 0,
      rewards: 0,
      nextRewardAt: JUMP_REWARD_STEP,
      platforms: [first],
      curIdx: 0,
      pawn: { x: first.x + first.w / 2, y: 0, state: 'idle', charge: 0, chargeStart: 0, chargePointerId: null, fromX: 0, toX: 0, flyT: 0, flyD: 0.4, flyH: 90, rot: 0, fallVy: 0, landTime: 0 },
      camX: 0,
      time: 0,
      paused: false,
      over: false,
      shake: 0,
      stars: [],
      particles: [],
      floats: [],
      canvas: null,
      rafId: 0,
      lastTs: 0,
      W: 360,
      H: 480
    };
    if (saveData && saveData.platforms && saveData.platforms.length) {
      g.platforms = saveData.platforms.map(p => ({ x: p.x, w: p.w, c1: p.c1, c2: p.c2 }));
      g.curIdx = Math.max(0, Math.min(g.platforms.length - 1, saveData.curIdx || 0));
      g.score = saveData.score || 0;
      g.combo = saveData.combo || 0;
      g.maxCombo = saveData.maxCombo || 0;
      g.rewards = saveData.rewards || 0;
      g.nextRewardAt = saveData.nextRewardAt || JUMP_REWARD_STEP;
      g.pawn.x = Math.max(20, saveData.pawnX || (g.platforms[g.curIdx].x + g.platforms[g.curIdx].w / 2));
      g.camX = Math.max(0, saveData.camX || (g.pawn.x - 200));
    } else {
      while (g.platforms[g.platforms.length - 1].x < 2000) jumpAppendPlatform(g);
    }
    for (let i = 0; i < 42; i++) g.stars.push({ x: Math.random(), y: Math.random() * 0.55, r: Math.random() * 1.6 + 0.4, p: Math.random() });
    jumpGame = g;
    jumpRenderUI();
    g.lastTs = performance.now();
    g.rafId = jumpRaf(jumpLoop);
  }

  function jumpTeardown() {
    const g = jumpGame;
    if (g && g.rafId) jumpCaf(g.rafId);
    jumpGame = null;
  }

  function jumpExitToLobby() {
    const g = jumpGame;
    if (g && !g.over && !g.paused) {
      if (g.pawn.state === 'charging') jumpChargeCancel(g.pawn.chargePointerId);
      if (g.pawn.state === 'flying') jumpResolveLanding();
    }
    const savable = !!(g && !g.over && g.pawn.state === 'idle');
    if (savable) jumpSaveGame(g); else jumpClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    jumpTeardown();
    renderMiniGameLobby();
    showToast(savable ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
  }
  function jumpQuitToCenter() {
    jumpClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    jumpTeardown();
    renderSetup();
    showToast('🚪 已结束本局跳一跳');
  }

  function jumpRenderUI() {
    const g = jumpGame;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = jumpLoadBest();
    sheet.innerHTML = `
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="jump-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">♟️ 跳一跳</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="jump-points-label">${pointsLabelHTML()}</span>
            <span id="jump-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="jump-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏中心（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="jump-score-text" style="color:#10B981;font-size:18px;vertical-align:-1px;">0</b></div>
          <div id="jump-combo-text" style="font-size:12px;color:var(--ubp-text-2);">连续中心: <b style="color:#F59E0B;">0</b></div>
          <div id="jump-reward-text" style="font-size:11px;color:var(--ubp-text-3);">距 +1 积分还差 200 分</div>
        </div>
        <div id="jump-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#1b1730;">
          <canvas id="jump-canvas" style="width:100%;height:100%;display:block;touch-action:none;"></canvas>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="width:100%;height:7px;background:var(--ubp-card-2);border-radius:4px;overflow:hidden;border:1px solid var(--ubp-line);margin-bottom:7px;">
            <div id="jump-power-fill" style="width:0%;height:100%;background:linear-gradient(90deg,#22C55E,#F59E0B,#EF4444);"></div>
          </div>
          <button id="jump-charge-btn" style="width:100%;padding:12px 0;font-size:14px;font-weight:700;color:#fff;background:linear-gradient(135deg,#0891B2,#2563EB);border:none;border-radius:12px;cursor:pointer;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;touch-action:none;box-shadow:0 4px 12px rgba(37,99,235,0.35);">🎮 长按蓄力 · 松开起跳</button>
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;margin-top:5px;">落到下一块方块 +1 分 · 中心连击 2→4→6…最高 32 分 / 跳 · 每 200 分 +1 积分</div>
        </div>
      </div>
    `;
    g.canvas = sheet.querySelector('#jump-canvas');
    const btn = sheet.querySelector('#jump-charge-btn');
    if (btn) {
      btn.addEventListener('contextmenu', (e) => e.preventDefault());
      if (typeof window.PointerEvent !== 'undefined') {
        btn.addEventListener('pointerdown', (e) => {
          e.preventDefault();
          try { btn.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
          jumpChargeStart(e.pointerId);
        });
        btn.addEventListener('pointerup', (e) => { e.preventDefault(); jumpChargeRelease(e.pointerId); });
        btn.addEventListener('pointercancel', (e) => jumpChargeCancel(e.pointerId));
      } else {
        btn.addEventListener('touchstart', (e) => { e.preventDefault(); jumpChargeStart('touch'); });
        btn.addEventListener('touchend', (e) => { e.preventDefault(); jumpChargeRelease('touch'); });
        btn.addEventListener('touchcancel', () => jumpChargeCancel('touch'));
        btn.addEventListener('mousedown', () => jumpChargeStart('mouse'));
        btn.addEventListener('mouseup', () => jumpChargeRelease('mouse'));
        btn.addEventListener('mouseleave', () => jumpChargeCancel('mouse'));
      }
    }
  }

  function jumpChargeStart(pointerId) {
    const g = jumpGame;
    if (!g || g.over || g.paused || g.pawn.state !== 'idle') return;
    g.pawn.state = 'charging';
    g.pawn.charge = 0;
    g.pawn.chargeStart = performance.now();
    g.pawn.chargePointerId = pointerId;
  }

  function jumpChargeRelease(pointerId) {
    const g = jumpGame;
    if (!g || g.pawn.state !== 'charging') return;
    if (g.pawn.chargePointerId !== null && pointerId !== undefined && g.pawn.chargePointerId !== pointerId) return;
    g.pawn.chargePointerId = null;
    const power = Math.max(0, Math.min(1, g.pawn.charge));
    const dist = JUMP_MIN_DIST + power * (JUMP_MAX_DIST - JUMP_MIN_DIST);
    g.pawn.state = 'flying';
    g.pawn.charge = 0;
    g.pawn.fromX = g.pawn.x;
    g.pawn.toX = g.pawn.x + dist;
    g.pawn.flyT = 0;
    g.pawn.flyD = 0.34 + dist / 900;
    g.pawn.flyH = 66 + dist * 0.24;
    g.pawn.rot = 0;
  }

  function jumpChargeCancel(pointerId) {
    const g = jumpGame;
    if (!g || g.pawn.state !== 'charging') return;
    if (g.pawn.chargePointerId !== null && pointerId !== undefined && g.pawn.chargePointerId !== pointerId) return;
    g.pawn.chargePointerId = null;
    g.pawn.state = 'idle';
    g.pawn.charge = 0;
  }

  function jumpLoop(ts) {
    const g = jumpGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { jumpTeardown(); return; }
    const dt = Math.min(0.05, Math.max(0.001, ((ts || performance.now()) - g.lastTs) / 1000 || 0.016));
    g.lastTs = ts || performance.now();
    g.time += dt;
    if (!g.paused && !g.over) jumpUpdate(dt);
    jumpDraw();
    g.rafId = jumpRaf(jumpLoop);
  }

  function jumpUpdate(dt) {
    const g = jumpGame;
    if (!g) return;
    const p = g.pawn;
    if (p.state === 'charging') {
      p.charge = Math.min(1, (performance.now() - p.chargeStart) / JUMP_CHARGE_MS);
    } else if (p.state === 'flying') {
      p.flyT += dt / p.flyD;
      if (p.flyT >= 1) {
        p.flyT = 1;
        jumpResolveLanding();
      } else {
        const t = p.flyT;
        p.x = p.fromX + (p.toX - p.fromX) * t;
        p.y = -p.flyH * 4 * t * (1 - t);
        p.rot = Math.PI * 2 * t;
      }
    } else if (p.state === 'falling') {
      p.fallVy += 1600 * dt;
      p.y += p.fallVy * dt;
      p.rot += 3.2 * dt;
      if (p.y > g.H + 130) jumpGameOver();
    }
    if (p.landTime > 0) p.landTime = Math.max(0, p.landTime - dt);
    // 相机跟随
    const camTarget = Math.max(0, p.x - g.W * 0.35);
    g.camX += (camTarget - g.camX) * Math.min(1, dt * 5.2);
    // 粒子 / 飘字
    for (let i = g.particles.length - 1; i >= 0; i--) {
      const pt = g.particles[i];
      pt.x += pt.vx * dt;
      pt.y += pt.vy * dt;
      pt.vy += 620 * dt;
      pt.life -= dt;
      if (pt.life <= 0) g.particles.splice(i, 1);
    }
    for (let i = g.floats.length - 1; i >= 0; i--) {
      const ft = g.floats[i];
      ft.y += ft.vy * dt;
      ft.vy *= Math.max(0, 1 - dt * 2.2);
      ft.life -= dt;
      if (ft.life <= 0) g.floats.splice(i, 1);
    }
    if (g.shake > 0) g.shake = Math.max(0, g.shake - dt * 26);
    // 前方方块补给
    const need = g.camX + g.W + 520;
    let guard = 0;
    while (guard < 40) {
      const tail = g.platforms[g.platforms.length - 1];
      if (tail.x + tail.w >= need) break;
      jumpAppendPlatform(g);
      guard++;
    }
    // 蓄力条
    const fill = sheet ? sheet.querySelector('#jump-power-fill') : null;
    if (fill) fill.style.width = Math.round((p.state === 'charging' ? p.charge : 0) * 100) + '%';
  }

  function jumpResolveLanding() {
    const g = jumpGame;
    if (!g) return;
    const p = g.pawn;
    const landX = p.toX;
    let hit = -1;
    for (let i = g.curIdx; i < g.platforms.length; i++) {
      const pl = g.platforms[i];
      if (landX >= pl.x - 3 && landX <= pl.x + pl.w + 3) { hit = i; break; }
    }
    if (hit === -1) {
      p.state = 'falling';
      p.fallVy = 40;
      p.x = landX;
      p.y = 0;
      return;
    }
    const pl = g.platforms[hit];
    p.x = landX;
    p.y = 0;
    p.state = 'idle';
    p.rot = 0;
    p.landTime = 0.22;
    g.shake = 3.2;
    if (hit === g.curIdx) {
      jumpFloat(p.x, -26, '未得分', '#CBD5E1', 0.8);
      jumpUpdateHud();
      return;
    }
    g.curIdx = hit;
    const center = pl.x + pl.w / 2;
    const tol = Math.max(5, Math.min(9, pl.w * 0.2));
    const diff = Math.abs(landX - center);
    if (diff <= tol) {
      g.combo += 1;
      g.maxCombo = Math.max(g.maxCombo, g.combo);
      const gain = Math.min(2 * g.combo, 32);
      g.score += gain;
      jumpFloat(center, -36, '完美 +' + gain, '#FDE047', 1.15);
      if (g.combo >= 2) jumpFloat(p.x, -62, '连续中心 ×' + g.combo, '#F59E0B', 0.95);
      jumpDust(p.x, true);
    } else {
      g.combo = 0;
      g.score += 1;
      jumpDust(p.x, false);
      jumpFloat(center, -32, '+1', '#E2E8F0', 0.95);
    }
    jumpUpdateHud();
    jumpCheckMilestones();
  }

  function jumpDust(x, gold) {
    const g = jumpGame;
    if (!g) return;
    const n = gold ? 14 : 8;
    for (let i = 0; i < n; i++) {
      g.particles.push({
        x, y: -2,
        vx: (Math.random() - 0.5) * (gold ? 190 : 120),
        vy: -Math.random() * (gold ? 150 : 90) - 20,
        life: 0.4 + Math.random() * 0.3,
        r: 1.5 + Math.random() * 2,
        color: gold ? '#FDE047' : '#CBD5E1'
      });
    }
  }

  function jumpFloat(x, y, text, color, scale) {
    const g = jumpGame;
    if (!g) return;
    g.floats.push({ x, y, text, color, scale: scale || 1, life: 1.1, vy: -34 });
  }

  function jumpUpdateHud() {
    const g = jumpGame;
    if (!g || !sheet) return;
    const s = sheet.querySelector('#jump-score-text');
    if (s) s.textContent = String(g.score);
    const c = sheet.querySelector('#jump-combo-text');
    if (c) c.innerHTML = '连续中心: <b style="color:#F59E0B;">' + g.combo + '</b>';
    jumpUpdateRewardText();
  }

  function jumpUpdateRewardText() {
    const g = jumpGame;
    if (!g || !sheet) return;
    const el = sheet.querySelector('#jump-reward-text');
    if (!el) return;
    const remain = Math.max(0, g.nextRewardAt - g.score);
    el.textContent = '距 +1 积分还差 ' + remain + ' 分';
  }

  // 每累计 200 分：自动 +1 积分，并弹出「可选择继续游戏」里程碑（每再 200 分再 +1 积分）
  function jumpCheckMilestones() {
    const g = jumpGame;
    if (!g) return;
    let crossed = false;
    while (g.score >= g.nextRewardAt) {
      g.nextRewardAt += JUMP_REWARD_STEP;
      g.rewards += 1;
      addPoints(1);
      crossed = true;
    }
    const pl = sheet ? sheet.querySelector('#jump-points-label') : null;
    if (pl) pl.innerHTML = pointsLabelHTML();
    jumpUpdateRewardText();
    if (crossed) {
      g.paused = true;
      jumpShowMilestone(g.nextRewardAt - JUMP_REWARD_STEP);
    }
  }

  function jumpShowMilestone(scoreAt) {
    const stage = sheet ? sheet.querySelector('#jump-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.jump-overlay').forEach(el => el.remove());
    const ov = document.createElement('div');
    ov.className = 'jump-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.72);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #F59E0B;border-radius:14px;padding:20px 16px;width:100%;max-width:270px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:6px;">🎉</div>
        <div style="font-size:15.5px;font-weight:700;color:#F59E0B;margin-bottom:6px;">里程碑 ${scoreAt} 分达成！</div>
        <div style="font-size:12.5px;color:var(--ubp-text-2);line-height:1.7;margin-bottom:14px;">
          积分 <b style="color:#F59E0B;">+1</b>（当前 💎 ${loadPoints()}）<br>
          可选择继续游戏 · 每再累计 200 分再 +1 积分
        </div>
        <button data-ubp-act="jump-continue" class="ubp-btn primary" style="width:100%;padding:10px 0;font-size:13.5px;font-weight:700;background:#F59E0B;border:none;color:#fff;border-radius:10px;cursor:pointer;">► 继续游戏</button>
      </div>
    `;
    stage.appendChild(ov);
  }

  function jumpContinue() {
    const g = jumpGame;
    if (!g) return;
    if (sheet) sheet.querySelectorAll('.jump-overlay').forEach(el => el.remove());
    g.paused = false;
    g.lastTs = performance.now();
    showToast('🎮 继续游戏！每再累计 200 分再 +1 积分');
  }

  function jumpGameOver() {
    const g = jumpGame;
    if (!g || g.over) return;
    g.over = true;
    g.pawn.state = 'dead';
    jumpClearSave();
    const best = jumpLoadBest();
    const isNew = g.score > best;
    if (isNew) jumpSaveBest(g.score);
    const bestLabel = sheet ? sheet.querySelector('#jump-best-label') : null;
    if (bestLabel) bestLabel.textContent = '🏆 最高 ' + Math.max(best, g.score);
    const stage = sheet ? sheet.querySelector('#jump-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.jump-overlay').forEach(el => el.remove());
    const ov = document.createElement('div');
    ov.className = 'jump-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #22C55E;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '💀'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : '本局结束'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#10B981;font-size:17px;">${g.score}</b><br>
          连续完美最高：<b style="color:#F59E0B;">×${g.maxCombo}</b><br>
          最高分：<b style="color:#F59E0B;">${Math.max(best, g.score)}</b><br>
          本局积分奖励：<b style="color:#F59E0B;">+${g.rewards}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="jump-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#22C55E;border:none;color:#fff;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="jump-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">每累计 200 分 +1 积分 · 分数越高方块越小、间距越大</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function jumpDraw() {
    const g = jumpGame;
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    g.W = cssW;
    g.H = cssH;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssW, cssH);
    const groundY = Math.round(cssH * JUMP_GROUND_RATIO);
    // 天空
    const sky = ctx.createLinearGradient(0, 0, 0, cssH);
    sky.addColorStop(0, '#1D1A3A');
    sky.addColorStop(0.55, '#2C2757');
    sky.addColorStop(1, '#4B3F86');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, cssW, cssH);
    // 星星（视差）
    for (const st of g.stars) {
      const m = cssW + 40;
      const sx = jumpWrap(st.x * cssW * 1.6 - g.camX * 0.06 * (0.4 + st.p), m) - 20;
      const tw = 0.55 + 0.45 * Math.sin(g.time * (1.2 + st.p * 2) + st.p * 10);
      ctx.globalAlpha = 0.65 * tw;
      ctx.fillStyle = '#E0E7FF';
      ctx.beginPath();
      ctx.arc(sx, st.y * cssH, st.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // 月亮
    const moonX = cssW - 62 - jumpWrap(g.camX * 0.03, 80);
    const moonY = 54;
    const glow = ctx.createRadialGradient(moonX, moonY, 4, moonX, moonY, 34);
    glow.addColorStop(0, 'rgba(253,230,138,0.55)');
    glow.addColorStop(1, 'rgba(253,230,138,0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(moonX, moonY, 34, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#FDE68A';
    ctx.beginPath();
    ctx.arc(moonX, moonY, 15, 0, Math.PI * 2);
    ctx.fill();
    ctx.save();
    if (g.shake > 0) ctx.translate((Math.random() - 0.5) * g.shake, (Math.random() - 0.5) * g.shake);
    // 远山两层（视差）
    const drawHills = (factor, baseY, amp, color, seed) => {
      ctx.fillStyle = color;
      const off = -jumpWrap(g.camX * factor, 260);
      ctx.beginPath();
      ctx.moveTo(off - 260, baseY);
      for (let x = off - 260; x <= cssW + 260; x += 130) {
        ctx.quadraticCurveTo(x + 65, baseY - amp * (0.5 + 0.5 * Math.sin(x * 0.011 + seed)), x + 130, baseY);
      }
      ctx.lineTo(cssW + 260, cssH);
      ctx.lineTo(off - 260, cssH);
      ctx.closePath();
      ctx.fill();
    };
    drawHills(0.12, groundY - 26, 46, '#37306A', 2.1);
    drawHills(0.24, groundY - 4, 30, '#413877', 5.3);
    // 深渊渐隐
    const abyss = ctx.createLinearGradient(0, groundY + JUMP_PLAT_H, 0, cssH);
    abyss.addColorStop(0, 'rgba(8,6,20,0)');
    abyss.addColorStop(1, 'rgba(8,6,20,0.55)');
    ctx.fillStyle = abyss;
    ctx.fillRect(0, groundY + JUMP_PLAT_H, cssW, cssH - groundY - JUMP_PLAT_H);
    // 方块
    for (const pl of g.platforms) {
      const sx = pl.x - g.camX;
      if (sx + pl.w < -40 || sx > cssW + 40) continue;
      ctx.fillStyle = 'rgba(0,0,0,0.28)';
      ctx.beginPath();
      ctx.ellipse(sx + pl.w / 2, groundY + JUMP_PLAT_H + 5, pl.w * 0.5 + 6, 7, 0, 0, Math.PI * 2);
      ctx.fill();
      const grad = ctx.createLinearGradient(0, groundY, 0, groundY + JUMP_PLAT_H);
      grad.addColorStop(0, pl.c1);
      grad.addColorStop(1, pl.c2);
      ctx.fillStyle = grad;
      jumpRoundRect(ctx, sx, groundY, pl.w, JUMP_PLAT_H, 6);
      ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.5)';
      jumpRoundRect(ctx, sx + 2, groundY + 1.5, pl.w - 4, 5, 2.5);
      ctx.fill();
      ctx.fillStyle = 'rgba(0,0,0,0.22)';
      ctx.beginPath();
      ctx.ellipse(sx + pl.w / 2, groundY + JUMP_PLAT_H * 0.58, 2.4, 2.4, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    const p = g.pawn;
    const px = p.x - g.camX;
    const feetY = groundY + p.y;
    // 影子
    if (p.state === 'idle' || p.state === 'charging') {
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath();
      ctx.ellipse(px, groundY + 2.5, 12, 3.6, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    // 蓄力光环
    if (p.state === 'charging') {
      ctx.strokeStyle = 'rgba(250,204,21,' + (0.25 + 0.5 * p.charge).toFixed(2) + ')';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.ellipse(px, groundY + 2.5, 14 + 20 * p.charge, 4 + 5 * p.charge, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
    // 棋子（蓄力压扁 / 落地压扁 / 空中旋转）
    let sy = 1;
    let sxx = 1;
    if (p.state === 'charging') { sy = 1 - 0.4 * p.charge; sxx = 1 + 0.26 * p.charge; }
    if (p.landTime > 0) { const k = p.landTime / 0.22; sy *= 1 - 0.28 * k; sxx *= 1 + 0.18 * k; }
    ctx.save();
    ctx.translate(px, feetY);
    if (p.state === 'flying' || p.state === 'falling' || p.state === 'dead') {
      ctx.translate(0, -13);
      ctx.rotate(p.rot);
      ctx.translate(0, 13);
    }
    ctx.scale(sxx, sy);
    ctx.fillStyle = '#111318';
    jumpRoundRect(ctx, -11, -8, 22, 8.5, 3.5);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-9, -8);
    ctx.lineTo(9, -8);
    ctx.quadraticCurveTo(6.5, -15, 4.2, -18);
    ctx.lineTo(-4.2, -18);
    ctx.quadraticCurveTo(-6.5, -15, -9, -8);
    ctx.closePath();
    ctx.fill();
    ctx.beginPath();
    ctx.arc(0, -23.5, 6.8, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.28)';
    ctx.beginPath();
    ctx.arc(-2.4, -25.6, 2.1, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(148,163,184,0.5)';
    jumpRoundRect(ctx, -8.5, -7.6, 17, 1.6, 0.8);
    ctx.fill();
    ctx.restore();
    // 粒子
    for (const pt of g.particles) {
      ctx.globalAlpha = Math.max(0, Math.min(1, pt.life / 0.5));
      ctx.fillStyle = pt.color;
      ctx.beginPath();
      ctx.arc(pt.x - g.camX, groundY + pt.y, pt.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // 飘字
    ctx.textAlign = 'center';
    for (const ft of g.floats) {
      const a = Math.max(0, Math.min(1, ft.life / 0.9));
      ctx.globalAlpha = a;
      ctx.font = '700 ' + Math.round(13 * ft.scale) + 'px -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif';
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.lineWidth = 3;
      ctx.strokeText(ft.text, ft.x - g.camX, groundY + ft.y);
      ctx.fillStyle = ft.color;
      ctx.fillText(ft.text, ft.x - g.camX, groundY + ft.y);
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
    ctx.restore();
  }
  // __JUMP_ENGINE_END__

  // __G2048_ENGINE_BEGIN__
  // ========== 2048（经典 4×4 数字合并 · 方向键 / 滑动棋盘 / 方向按钮操作） ==========
  // 规则：4×4 棋盘开局随机 2 个方块（90% 为 2、10% 为 4）；滑动时所有方块向该方向滑到底，
  //       相同数字相撞合并为两数之和（同一直线每个方块每步只合并一次）；有效滑动后随机空位刷新新方块（无位移不刷新）；
  //       合成出 2048 即通关 +1 积分（可继续挑战 4096 等更高数字）；棋盘占满且四方向都无法滑动时游戏结束。
  // 说明：本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const G2048_BEST_KEY = 'werewolf_extension_2048_best';
  const G2048_SIZE = 4;
  const G2048_COLORS = {
    2: ['#EEE4DA', '#776E65'],
    4: ['#EDE0C8', '#776E65'],
    8: ['#F2B179', '#FFFFFF'],
    16: ['#F59563', '#FFFFFF'],
    32: ['#F67C5F', '#FFFFFF'],
    64: ['#F65E3B', '#FFFFFF'],
    128: ['#EDCF72', '#FFFFFF'],
    256: ['#EDCC61', '#FFFFFF'],
    512: ['#EDC850', '#FFFFFF'],
    1024: ['#EDC53F', '#FFFFFF'],
    2048: ['#EDC22E', '#FFFFFF']
  };

  let game2048 = null;

  function g2048LoadBest() {
    try { const n = parseInt(localStorage.getItem(G2048_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function g2048SaveBest(n) {
    try { localStorage.setItem(G2048_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function g2048TileStyle(v) {
    return G2048_COLORS[v] || ['#3C3A32', '#FFFFFF'];
  }
  function g2048FontSize(v, cell) {
    const digits = String(v).length;
    const base = cell * 0.42;
    if (digits <= 2) return base;
    if (digits === 3) return base * 0.78;
    if (digits === 4) return base * 0.62;
    return base * 0.5;
  }

  // 打开 / 重开一局
  const G2048_SAVE_KEY = 'werewolf_extension_2048_save';
  function g2048HasSave() { try { const raw = localStorage.getItem(G2048_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && d.grid && d.grid.length === G2048_SIZE); } catch (e) { return false; } }
  function g2048ClearSave() { try { localStorage.removeItem(G2048_SAVE_KEY); } catch (e) { /* ignore */ } }
  function g2048SaveGame(g) {
    try {
      if (!g || g.over) { g2048ClearSave(); return false; }
      localStorage.setItem(G2048_SAVE_KEY, JSON.stringify({ v: 1, grid: g.grid, score: g.score, moves: g.moves, won: g.won, rewarded: g.rewarded, victoryShown: g.victoryShown }));
      return true;
    } catch (e) { return false; }
  }
  function g2048ResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(G2048_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data || !data.grid) { g2048OpenGame(); return; }
    g2048OpenGame(data);
    showToast('🔖 已恢复进行中的 2048（得分 ' + (data.score || 0) + '）');
  }

  function g2048OpenGame(saveData) {
    g2048Teardown(false);
    if (!sheet) { renderMiniGameLobby(); return; }
    const g = {
      grid: [],
      tiles: [],
      nextId: 1,
      score: 0,
      startBest: g2048LoadBest(),
      moves: 0,
      won: false,
      rewarded: false,
      victoryShown: false,
      over: false,
      paused: false,
      animating: false,
      cell: 64,
      gap: 8,
      boardSize: 0,
      boardEl: null,
      stageEl: null,
      doc: null,
      keyHandler: null,
      _ro: null,
      _onWinResize: null
    };
    for (let r = 0; r < G2048_SIZE; r++) g.grid.push([0, 0, 0, 0]);
    game2048 = g;
    g2048RenderUI();
    if (saveData && saveData.grid) {
      for (let r = 0; r < G2048_SIZE; r++) {
        for (let c = 0; c < G2048_SIZE; c++) {
          const v = (saveData.grid[r] && saveData.grid[r][c]) || 0;
          g.grid[r][c] = v;
          if (v) {
            const t = { id: g.nextId++, r, c, v, el: null, face: null };
            g.tiles.push(t);
            g2048MakeTileEl(g, t);
            g2048PlaceTile(g, t, false);
          }
        }
      }
      g.score = saveData.score || 0;
      g.moves = saveData.moves || 0;
      g.won = !!saveData.won;
      g.rewarded = !!saveData.rewarded;
      g.victoryShown = !!saveData.victoryShown;
    } else {
      g2048SpawnTile(g);
      g2048SpawnTile(g);
    }
    g2048AttachInput(g);
    g2048UpdateHud(g);
  }

  function g2048Teardown(renderLobby) {
    const g = game2048;
    game2048 = null;
    if (g) {
      if (g.keyHandler && g.doc) { try { g.doc.removeEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ } }
      if (g._ro) { try { g._ro.disconnect(); } catch (e) { /* ignore */ } }
      if (g._onWinResize && g.doc) { try { (g.doc.defaultView || window).removeEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ } }
    }
    if (renderLobby) renderMiniGameLobby();
  }

  function g2048ExitToLobby() {
    const g = game2048;
    if (g && g.animating) {
      setTimeout(() => { if (game2048 === g) g2048ExitToLobby(); }, 160);
      return;
    }
    const saved = !!(g && g2048SaveGame(g));
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    g2048Teardown(true);
    showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
  }
  function g2048QuitToCenter() {
    g2048ClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    g2048Teardown(false);
    renderSetup();
    showToast('🚪 已结束本局 2048');
  }

  function g2048RenderUI() {
    const g = game2048;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = g2048LoadBest();
    sheet.innerHTML = `
      <style>
        @keyframes g2048-pop { 0% { transform: scale(1); } 55% { transform: scale(1.16); } 100% { transform: scale(1); } }
        @keyframes g2048-spawn { 0% { opacity: 0; transform: scale(0.3); } 100% { opacity: 1; transform: scale(1); } }
        .g2048-tile { position: absolute; left: 0; top: 0; transition: transform 110ms ease; will-change: transform; }
        .g2048-face { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; border-radius: 7px; font-weight: 800; box-sizing: border-box; }
        .g2048-face.pop { animation: g2048-pop 140ms ease; }
        .g2048-face.spawn { animation: g2048-spawn 130ms ease; }
      </style>
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="g2048-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🔢 2048</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="g2048-points-label">${pointsLabelHTML()}</span>
            <span id="g2048-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="g2048-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏中心（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="g2048-score-text" style="color:#38BDF8;font-size:18px;vertical-align:-1px;">0</b></div>
          <div style="font-size:12px;color:var(--ubp-text-2);">步数 <b id="g2048-moves-text" style="color:#F59E0B;">0</b> · 目标 <b style="color:#F59E0B;">2048</b></div>
        </div>
        <div id="g2048-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#1b1730;display:flex;align-items:center;justify-content:center;">
          <div id="g2048-board" style="position:relative;border-radius:10px;background:#33323B;touch-action:none;user-select:none;-webkit-user-select:none;"></div>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="display:flex;justify-content:center;align-items:center;gap:26px;">
            <div style="display:grid;grid-template-columns:repeat(3,42px);grid-template-rows:repeat(2,36px);gap:6px;">
              <span></span>
              <button data-g2048-dir="up" class="ubp-btn" style="padding:0;font-size:15px;">▲</button>
              <span></span>
              <button data-g2048-dir="left" class="ubp-btn" style="padding:0;font-size:15px;">◀</button>
              <button data-g2048-dir="down" class="ubp-btn" style="padding:0;font-size:15px;">▼</button>
              <button data-g2048-dir="right" class="ubp-btn" style="padding:0;font-size:15px;">▶</button>
            </div>
            <button data-ubp-act="g2048-restart" class="ubp-btn" style="padding:9px 14px;font-size:12.5px;">🔄 重开</button>
          </div>
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;margin-top:6px;">方向键 ↑↓←→ · 滑动棋盘 / 点按方向按钮 · 合成 2048 通关 +1 积分 · 可继续挑战 4096</div>
        </div>
      </div>
    `;
    g.boardEl = sheet.querySelector('#g2048-board');
    g.stageEl = sheet.querySelector('#g2048-stage');
    g2048Resize();
  }

  // 自适应尺寸 + 重排背景格与方块
  function g2048Resize() {
    const g = game2048;
    if (!g || !g.stageEl || !g.boardEl) return;
    const sw = g.stageEl.clientWidth || 0;
    const sh = g.stageEl.clientHeight || 0;
    if (sw <= 0 || sh <= 0) return;
    const size = Math.max(160, Math.min(sw, sh) - 10);
    const gap = Math.max(6, Math.round(size * 0.025));
    const cell = (size - gap * (G2048_SIZE + 1)) / G2048_SIZE;
    g.boardSize = size;
    g.gap = gap;
    g.cell = cell;
    g.boardEl.style.width = size + 'px';
    g.boardEl.style.height = size + 'px';
    g.boardEl.innerHTML = '';
    for (let r = 0; r < G2048_SIZE; r++) {
      for (let c = 0; c < G2048_SIZE; c++) {
        const bg = document.createElement('div');
        bg.style.cssText = 'position:absolute;border-radius:7px;background:rgba(255,255,255,0.07);';
        bg.style.width = cell + 'px';
        bg.style.height = cell + 'px';
        bg.style.transform = g2048Translate(g, r, c);
        g.boardEl.appendChild(bg);
      }
    }
    for (const t of g.tiles) {
      if (!t.el) g2048MakeTileEl(g, t);
      else g.boardEl.appendChild(t.el);
      if (t.face) t.face.style.fontSize = g2048FontSize(t.v, g.cell) + 'px';
      g2048PlaceTile(g, t, false);
    }
  }

  function g2048Translate(g, r, c) {
    return 'translate(' + (g.gap + c * (g.cell + g.gap)) + 'px,' + (g.gap + r * (g.cell + g.gap)) + 'px)';
  }

  function g2048MakeTileEl(g, t) {
    const el = document.createElement('div');
    el.className = 'g2048-tile';
    el.style.width = g.cell + 'px';
    el.style.height = g.cell + 'px';
    const face = document.createElement('div');
    face.className = 'g2048-face';
    t.face = face;
    t.el = el;
    el.appendChild(face);
    g2048PaintFace(g, t, false);
    g.boardEl.appendChild(el);
  }

  function g2048PaintFace(g, t, pop) {
    if (!t.face) return;
    const st = g2048TileStyle(t.v);
    t.face.textContent = String(t.v);
    t.face.style.background = st[0];
    t.face.style.color = st[1];
    t.face.style.fontSize = g2048FontSize(t.v, g.cell) + 'px';
    if (pop) {
      t.face.classList.remove('pop');
      void t.face.offsetWidth;
      t.face.classList.add('pop');
    }
  }

  function g2048PlaceTile(g, t, animate) {
    if (!t.el) return;
    if (animate === false) t.el.style.transition = 'none';
    t.el.style.transform = g2048Translate(g, t.r, t.c);
    if (animate === false) {
      setTimeout(() => { if (t.el) t.el.style.transition = ''; }, 30);
    }
  }

  // 随机空位刷新新方块：90% 为 2、10% 为 4
  function g2048SpawnTile(g) {
    const empties = [];
    for (let r = 0; r < G2048_SIZE; r++) {
      for (let c = 0; c < G2048_SIZE; c++) {
        if (!g.grid[r][c]) empties.push({ r, c });
      }
    }
    if (!empties.length) return null;
    const pos = empties[Math.floor(Math.random() * empties.length)];
    const v = Math.random() < 0.9 ? 2 : 4;
    const t = { id: g.nextId++, r: pos.r, c: pos.c, v, el: null, face: null };
    g.grid[pos.r][pos.c] = v;
    g.tiles.push(t);
    g2048MakeTileEl(g, t);
    g2048PlaceTile(g, t, false);
    if (t.face) t.face.classList.add('spawn');
    return t;
  }

  function g2048Dest(dir, lineIdx, slot) {
    if (dir === 'left') return { r: lineIdx, c: slot };
    if (dir === 'right') return { r: lineIdx, c: G2048_SIZE - 1 - slot };
    if (dir === 'up') return { r: slot, c: lineIdx };
    return { r: G2048_SIZE - 1 - slot, c: lineIdx };
  }

  // 计算一次滑动：返回 { changed, gained, moves, grid }
  // moves: [{ tile, dest, mergeInto }]；mergeInto 表示该方块将被并入的方块
  function g2048ComputeMove(g, dir) {
    const moves = [];
    let changed = false;
    let gained = 0;
    const newGrid = [];
    for (let r = 0; r < G2048_SIZE; r++) newGrid.push([0, 0, 0, 0]);
    const horiz = (dir === 'left' || dir === 'right');
    const ascending = (dir === 'left' || dir === 'up');
    const lineOf = (t) => (horiz ? t.r : t.c);
    const alongOf = (t) => (horiz ? t.c : t.r);
    for (let li = 0; li < G2048_SIZE; li++) {
      const list = g.tiles.filter(t => lineOf(t) === li)
        .sort((a, b) => (ascending ? alongOf(a) - alongOf(b) : alongOf(b) - alongOf(a)));
      const placed = [];
      for (const t of list) {
        const last = placed[placed.length - 1];
        if (last && last.value === t.v && !last.merged) {
          last.merged = true;
          last.value = t.v * 2;
          gained += last.value;
          changed = true;
          moves.push({ tile: t, dest: last.dest, mergeInto: last.tile });
        } else {
          const dest = g2048Dest(dir, li, placed.length);
          if (dest.r !== t.r || dest.c !== t.c) changed = true;
          moves.push({ tile: t, dest, mergeInto: null });
          placed.push({ tile: t, dest, value: t.v, merged: false });
        }
      }
      for (const pl of placed) newGrid[pl.dest.r][pl.dest.c] = pl.value;
    }
    return { changed, gained, moves, grid: newGrid };
  }

  function g2048HasAnyMove(grid) {
    for (let r = 0; r < G2048_SIZE; r++) {
      for (let c = 0; c < G2048_SIZE; c++) {
        const v = grid[r][c];
        if (!v) return true;
        if (c + 1 < G2048_SIZE && grid[r][c + 1] === v) return true;
        if (r + 1 < G2048_SIZE && grid[r + 1][c] === v) return true;
      }
    }
    return false;
  }

  function g2048Move(dir) {
    const g = game2048;
    if (!g || g.animating || g.paused || g.over) return;
    if (!g.boardEl || !g.boardEl.isConnected) { g2048Teardown(true); return; }
    const res = g2048ComputeMove(g, dir);
    if (!res.changed) {
      // 方块位置完全没变：不刷新方块；仍兜底检查是否已无路可走（如胜利弹窗跳过了失败结算）
      if (!g2048HasAnyMove(g.grid)) {
        g.over = true;
        g.paused = true;
        g2048GameOver(g);
      }
      return;
    }
    g.animating = true;
    g.moves += 1;
    g.score += res.gained;
    g2048UpdateHud(g);
    for (const m of res.moves) {
      if (m.tile.el) m.tile.el.style.transform = g2048Translate(g, m.dest.r, m.dest.c);
    }
    setTimeout(() => {
      if (game2048 !== g) return;
      // 移除被合并的方块
      for (const m of res.moves) {
        if (!m.mergeInto) continue;
        if (m.tile.el && m.tile.el.parentNode) m.tile.el.parentNode.removeChild(m.tile.el);
        const idx = g.tiles.indexOf(m.tile);
        if (idx >= 0) g.tiles.splice(idx, 1);
      }
      // 幸存方块落位并更新合并后的数值
      for (const m of res.moves) {
        if (m.mergeInto) {
          const target = m.mergeInto;
          target.v = target.v * 2;
          g2048PaintFace(g, target, true);
        } else {
          m.tile.r = m.dest.r;
          m.tile.c = m.dest.c;
        }
      }
      g.grid = res.grid;
      // 首次合成 2048：通关 +1 积分（每局仅一次）
      let hit2048 = false;
      for (const t of g.tiles) { if (t.v >= 2048) { hit2048 = true; break; } }
      if (hit2048 && !g.won) {
        g.won = true;
        if (!g.rewarded) {
          g.rewarded = true;
          addPoints(1);
          const pl = sheet ? sheet.querySelector('#g2048-points-label') : null;
          if (pl) pl.innerHTML = pointsLabelHTML();
        }
      }
      // 成功滑动后刷新新方块
      g2048SpawnTile(g);
      g.animating = false;
      g2048UpdateHud(g);
      if (g.won && !g.victoryShown) {
        g.victoryShown = true;
        g.paused = true;
        g2048ShowVictory(g);
        return;
      }
      if (!g2048HasAnyMove(g.grid)) {
        g.over = true;
        g.paused = true;
        g2048GameOver(g);
      }
    }, 120);
  }

  function g2048UpdateHud(g) {
    if (!g || !sheet) return;
    const s = sheet.querySelector('#g2048-score-text');
    if (s) s.textContent = String(g.score);
    const mv = sheet.querySelector('#g2048-moves-text');
    if (mv) mv.textContent = String(g.moves);
    const best = g2048LoadBest();
    if (g.score > best) g2048SaveBest(g.score);
    const bl = sheet.querySelector('#g2048-best-label');
    if (bl) bl.textContent = '🏆 最高 ' + Math.max(best, g.score);
  }

  function g2048Continue() {
    const g = game2048;
    if (!g) return;
    if (sheet) sheet.querySelectorAll('.g2048-overlay').forEach(el => el.remove());
    g.paused = false;
    showToast('🎮 继续挑战！冲击 4096 等更高数字');
  }

  function g2048ShowVictory(g) {
    const stage = sheet ? sheet.querySelector('#g2048-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.g2048-overlay').forEach(el => el.remove());
    const ov = document.createElement('div');
    ov.className = 'g2048-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.72);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #EDC22E;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:6px;">🎉</div>
        <div style="font-size:15.5px;font-weight:700;color:#EDC22E;margin-bottom:6px;">合成 2048 通关！</div>
        <div style="font-size:12.5px;color:var(--ubp-text-2);line-height:1.7;margin-bottom:14px;">
          积分 <b style="color:#F59E0B;">+1</b>（当前 💎 ${loadPoints()}）· 得分 <b style="color:#38BDF8;">${g.score}</b><br>
          可继续挑战 4096 / 8192 等更高数字
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="g2048-continue" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#EDC22E;border:none;color:#3C3A32;border-radius:10px;cursor:pointer;">► 继续挑战</button>
          <button data-ubp-act="g2048-restart" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
        </div>
        <div style="margin-top:8px;">
          <button data-ubp-act="g2048-exit" class="ubp-btn" style="width:100%;padding:8px 0;font-size:12px;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function g2048GameOver(g) {
    g2048ClearSave();
    const stage = sheet ? sheet.querySelector('#g2048-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.g2048-overlay').forEach(el => el.remove());
    const startBest = g.startBest || 0;
    const isNew = g.score > startBest;
    const best = Math.max(startBest, g.score);
    if (g.score > g2048LoadBest()) g2048SaveBest(g.score);
    const ov = document.createElement('div');
    ov.className = 'g2048-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #EF4444;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '💀'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : '游戏结束'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#38BDF8;font-size:17px;">${g.score}</b><br>
          步数：<b style="color:#F59E0B;">${g.moves}</b><br>
          最高分：<b style="color:#F59E0B;">${Math.max(best, g.score)}</b><br>
          最大方块：<b style="color:#F59E0B;">${g2048MaxTile(g)}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="g2048-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#38BDF8;border:none;color:#fff;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="g2048-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">棋盘占满且四方向都无法滑动时结束</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function g2048MaxTile(g) {
    let m = 0;
    for (const t of g.tiles) if (t.v > m) m = t.v;
    return m || '-';
  }

  function g2048AttachInput(g) {
    // 键盘方向键（输入框 / 文本框聚焦时自动忽略）
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    g.keyHandler = (e) => {
      const tgt = e.target;
      if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT' || tgt.isContentEditable)) return;
      const map = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down' };
      const dir = map[e.key];
      if (!dir) return;
      e.preventDefault();
      g2048Move(dir);
    };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    if (sheet) {
      // 方向按钮
      sheet.querySelectorAll('[data-g2048-dir]').forEach(btn => {
        btn.addEventListener('click', (e) => { e.preventDefault(); g2048Move(btn.dataset.g2048Dir); });
        btn.addEventListener('contextmenu', (e) => e.preventDefault());
      });
      // 滑动棋盘
      const board = g.boardEl;
      if (board) {
        let sx = 0;
        let sy = 0;
        let tracking = false;
        const start = (x, y) => { sx = x; sy = y; tracking = true; };
        const finish = (x, y) => {
          if (!tracking) return;
          tracking = false;
          const dx = x - sx;
          const dy = y - sy;
          if (Math.max(Math.abs(dx), Math.abs(dy)) < 24) return;
          if (Math.abs(dx) > Math.abs(dy)) g2048Move(dx > 0 ? 'right' : 'left');
          else g2048Move(dy > 0 ? 'down' : 'up');
        };
        if (typeof window.PointerEvent !== 'undefined') {
          board.addEventListener('pointerdown', (e) => {
            e.preventDefault();
            try { board.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
            start(e.clientX, e.clientY);
          });
          board.addEventListener('pointerup', (e) => { e.preventDefault(); finish(e.clientX, e.clientY); });
          board.addEventListener('pointercancel', () => { tracking = false; });
          board.addEventListener('contextmenu', (e) => e.preventDefault());
        } else {
          board.addEventListener('touchstart', (e) => { if (e.touches[0]) start(e.touches[0].clientX, e.touches[0].clientY); });
          board.addEventListener('touchend', (e) => { if (e.changedTouches[0]) finish(e.changedTouches[0].clientX, e.changedTouches[0].clientY); });
          board.addEventListener('mousedown', (e) => start(e.clientX, e.clientY));
          board.addEventListener('mouseup', (e) => finish(e.clientX, e.clientY));
        }
      }
    }
    // 面板尺寸自适应
    if (typeof ResizeObserver !== 'undefined') {
      try {
        g._ro = new ResizeObserver(() => g2048Resize());
        if (g.stageEl) g._ro.observe(g.stageEl);
      } catch (e) { /* ignore */ }
    }
    g._onWinResize = () => g2048Resize();
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }
  // __G2048_ENGINE_END__

  // __SUIKA_ENGINE_BEGIN__
  // ========== 合成大西瓜（水果下落合并 · 拖动 / 滑动选择落点 · 松手投放） ==========
  // 规则：顶部待投放水果可左右移动选择落点，松手 / 点击垂直落下；两个相同水果接触立刻合并为下一级，
  //       合并会连锁触发：葡萄→樱桃→橘子→柠檬→猕猴桃→番茄→桃子→菠萝→椰子→西瓜；
  //       每次投放的水果从低级水果（葡萄~猕猴桃）随机生成，并提前预览下一个；
  //       合成出西瓜达成目标 +1 积分（每局一次），游戏不结束可继续刷分；原版规则两个西瓜不会继续合并；
  //       任意水果静止后仍越过顶部红线即本局结束（下落途中短暂经过不算）。
  // 说明：本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const SUIKA_BEST_KEY = 'werewolf_extension_suika_best';
  const SUIKA_PENDING_Y = 38;
  const SUIKA_GRAVITY = 2400;
  const SUIKA_EMOJI = ['🍇', '🍒', '🍊', '🍋', '🥝', '🍅', '🍑', '🍍', '🥥', '🍉'];
  const SUIKA_NAMES = ['葡萄', '樱桃', '橘子', '柠檬', '猕猴桃', '番茄', '桃子', '菠萝', '椰子', '西瓜'];
  const SUIKA_COLORS = ['#8E44AD', '#E74C3C', '#E67E22', '#F1C40F', '#8DA845', '#D64541', '#F5A9A9', '#E9C46A', '#B08968', '#2ECC71'];
  // 各级半径 = 比例 × 画布宽度（比例基准宽度 360）
  const SUIKA_RATIOS = [0.048, 0.057, 0.068, 0.080, 0.092, 0.104, 0.117, 0.131, 0.146, 0.163];
  // 合成得分（三角数）：合成出樱桃 +1、橘子 +3、柠檬 +6 …… 西瓜 +45
  const SUIKA_GAIN = [0, 1, 3, 6, 10, 15, 21, 28, 36, 45];
  const SUIKA_NEXT_WEIGHTS = [0.30, 0.26, 0.20, 0.14, 0.10];

  let suikaGame = null;
  const suikaRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const suikaCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function suikaLoadBest() {
    try { const n = parseInt(localStorage.getItem(SUIKA_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function suikaSaveBest(n) {
    try { localStorage.setItem(SUIKA_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function suikaRadius(g, level) {
    return SUIKA_RATIOS[level] * (g.W || 380);
  }
  function suikaRandomNextLevel() {
    const r = Math.random();
    let acc = 0;
    for (let i = 0; i < SUIKA_NEXT_WEIGHTS.length; i++) {
      acc += SUIKA_NEXT_WEIGHTS[i];
      if (r < acc) return i;
    }
    return 0;
  }
  function suikaMakeFruit(g, level, x, y) {
    const r = suikaRadius(g, level);
    return { id: g.nextId++, level, x, y, vx: 0, vy: 0, r, inv: 1 / (r * r), omega: 0, rot: 0, appear: 0 };
  }

  const SUIKA_SAVE_KEY = 'werewolf_extension_suika_save';
  function suikaHasSave() { try { const raw = localStorage.getItem(SUIKA_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && (d.score > 0 || d.drops > 0 || (d.fruits && d.fruits.length > 0))); } catch (e) { return false; } }
  function suikaClearSave() { try { localStorage.removeItem(SUIKA_SAVE_KEY); } catch (e) { /* ignore */ } }
  function suikaSaveGame(g) {
    try {
      if (!g || g.over) { suikaClearSave(); return false; }
      localStorage.setItem(SUIKA_SAVE_KEY, JSON.stringify({
        v: 1, score: g.score, drops: g.drops, merges: g.merges, maxLevel: g.maxLevel, won: g.won, rewarded: g.rewarded,
        pendingLevel: g.pendingLevel, previewLevel: g.previewLevel, W: g.W,
        fruits: g.fruits.map(f => ({ level: f.level, x: f.x, y: f.y, vx: f.vx, vy: f.vy, rot: f.rot, omega: f.omega }))
      }));
      return true;
    } catch (e) { return false; }
  }
  function suikaResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(SUIKA_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data) { suikaOpenGame(); return; }
    suikaOpenGame(data);
    showToast('🔖 已恢复进行中的合成大西瓜（得分 ' + (data.score || 0) + '）');
  }

  function suikaOpenGame(saveData) {
    suikaTeardown(false);
    if (!sheet) { renderMiniGameLobby(); return; }
    const g = {
      fruits: [],
      nextId: 1,
      score: 0,
      startBest: suikaLoadBest(),
      drops: 0,
      merges: 0,
      maxLevel: -1,
      won: false,
      rewarded: false,
      over: false,
      paused: false,
      overTimer: 0,
      dropLock: 0,
      aimX: 0,
      aimInit: false,
      pressing: false,
      pendingLevel: suikaRandomNextLevel(),
      previewLevel: suikaRandomNextLevel(),
      W: 380,
      H: 520,
      lineY: 84,
      accum: 0,
      time: 0,
      particles: [],
      floats: [],
      canvas: null,
      stageEl: null,
      rafId: 0,
      lastTs: 0,
      doc: null,
      keyHandler: null,
      _onWinResize: null,
      _ro: null
    };
    if (saveData && saveData.fruits) {
      g.score = saveData.score || 0;
      g.drops = saveData.drops || 0;
      g.merges = saveData.merges || 0;
      g.maxLevel = (saveData.maxLevel === undefined || saveData.maxLevel === null) ? -1 : saveData.maxLevel;
      g.won = !!saveData.won;
      g.rewarded = !!saveData.rewarded;
      g.pendingLevel = (saveData.pendingLevel >= 0 && saveData.pendingLevel <= 4) ? saveData.pendingLevel : suikaRandomNextLevel();
      g.previewLevel = (saveData.previewLevel >= 0 && saveData.previewLevel <= 4) ? saveData.previewLevel : suikaRandomNextLevel();
      if (saveData.W) g.W = saveData.W;
      for (const f of saveData.fruits) {
        const nf = suikaMakeFruit(g, Math.max(0, Math.min(9, f.level || 0)), f.x, f.y);
        nf.vx = f.vx || 0;
        nf.vy = f.vy || 0;
        nf.rot = f.rot || 0;
        nf.omega = f.omega || 0;
        nf.x = Math.max(nf.r, Math.min(g.W - nf.r, nf.x));
        nf.y = Math.max(nf.r, Math.min(g.H - nf.r, nf.y));
        g.fruits.push(nf);
      }
      g._rescaleW = saveData.W || g.W;
    }
    suikaGame = g;
    suikaRenderUI();
    suikaAttachInput(g);
    g.lastTs = performance.now();
    g.rafId = suikaRaf(suikaTick);
  }

  function suikaTeardown(renderLobby) {
    const g = suikaGame;
    suikaGame = null;
    if (g) {
      if (g.rafId) suikaCaf(g.rafId);
      if (g.keyHandler && g.doc) { try { g.doc.removeEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ } }
      if (g._ro) { try { g._ro.disconnect(); } catch (e) { /* ignore */ } }
      if (g._onWinResize && g.doc) { try { (g.doc.defaultView || window).removeEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ } }
    }
    if (renderLobby) renderMiniGameLobby();
  }

  function suikaExitToLobby() {
    const saved = !!(suikaGame && suikaSaveGame(suikaGame));
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    suikaTeardown(true);
    showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
  }
  function suikaQuitToCenter() {
    suikaClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    suikaTeardown(false);
    renderSetup();
    showToast('🚪 已结束本局合成大西瓜');
  }

  function suikaRenderUI() {
    const g = suikaGame;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = suikaLoadBest();
    sheet.innerHTML = `
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="suika-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🍉 合成大西瓜</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="suika-points-label">${pointsLabelHTML()}</span>
            <span id="suika-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="suika-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏中心（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="suika-score-text" style="color:#FBBF24;font-size:18px;vertical-align:-1px;">0</b></div>
          <div id="suika-max-text" style="font-size:12px;color:var(--ubp-text-2);">最大: <b style="color:#F59E0B;">—</b></div>
          <div id="suika-next-text" style="font-size:12px;color:var(--ubp-text-2);">下一个: <b id="suika-next-emoji" style="font-size:14px;">🍇</b></div>
        </div>
        <div id="suika-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#0E3A46;">
          <canvas id="suika-canvas" style="width:100%;height:100%;display:block;touch-action:none;"></canvas>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;line-height:1.6;">按住 / 拖动选择落点 · 松手投放 · 相同水果相撞合并<br>合成西瓜 +1 积分（每局一次）· 水果静止后越过红线本局结束</div>
        </div>
      </div>
    `;
    g.stageEl = sheet.querySelector('#suika-stage');
    g.canvas = sheet.querySelector('#suika-canvas');
    suikaUpdateHud(g);
  }

  function suikaUpdateHud(g) {
    if (!g || !sheet) return;
    const s = sheet.querySelector('#suika-score-text');
    if (s) s.textContent = String(g.score);
    const mx = sheet.querySelector('#suika-max-text');
    if (mx) {
      if (g.maxLevel >= 0) mx.innerHTML = '最大: <b style="color:#F59E0B;">' + SUIKA_EMOJI[g.maxLevel] + ' ' + SUIKA_NAMES[g.maxLevel] + '</b>';
      else mx.innerHTML = '最大: <b style="color:#F59E0B;">—</b>';
    }
    const nx = sheet.querySelector('#suika-next-emoji');
    if (nx) nx.textContent = SUIKA_EMOJI[g.previewLevel];
    const best = suikaLoadBest();
    if (g.score > best) suikaSaveBest(g.score);
    const bl = sheet.querySelector('#suika-best-label');
    if (bl) bl.textContent = '🏆 最高 ' + Math.max(best, g.score);
  }

  function suikaDrop() {
    const g = suikaGame;
    if (!g || g.over || g.paused || g.dropLock > 0 || g.pendingLevel < 0) return null;
    if (!g.canvas || !g.canvas.isConnected) { suikaTeardown(true); return null; }
    const r = suikaRadius(g, g.pendingLevel);
    const x = Math.max(r + 2, Math.min(g.W - r - 2, g.aimInit ? g.aimX : g.W / 2));
    const f = suikaMakeFruit(g, g.pendingLevel, x, SUIKA_PENDING_Y + 4);
    g.fruits.push(f);
    g.drops += 1;
    g.dropLock = 0.35;
    g.pendingLevel = g.previewLevel;
    g.previewLevel = suikaRandomNextLevel();
    suikaUpdateHud(g);
    return f;
  }

  function suikaTick(ts) {
    const g = suikaGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { suikaTeardown(false); return; }
    const dtReal = Math.min(0.05, Math.max(0.001, ((ts || performance.now()) - g.lastTs) / 1000 || 0.016));
    g.lastTs = ts || performance.now();
    g.time += dtReal;
    if (!g.paused && !g.over) {
      if (g.dropLock > 0) g.dropLock = Math.max(0, g.dropLock - dtReal);
      g.accum += dtReal;
      const STEP = 1 / 120;
      let steps = 0;
      while (g.accum >= STEP && steps < 10 && !g.paused && !g.over) {
        suikaPhysicsStep(g, STEP);
        g.accum -= STEP;
        steps++;
      }
      if (steps >= 10) g.accum = 0;
    }
    // 粒子 / 飘字
    for (let i = g.particles.length - 1; i >= 0; i--) {
      const p = g.particles[i];
      p.x += p.vx * dtReal;
      p.y += p.vy * dtReal;
      p.vy += 900 * dtReal;
      p.life -= dtReal;
      if (p.life <= 0) g.particles.splice(i, 1);
    }
    for (let i = g.floats.length - 1; i >= 0; i--) {
      const ft = g.floats[i];
      ft.y += ft.vy * dtReal;
      ft.life -= dtReal;
      if (ft.life <= 0) g.floats.splice(i, 1);
    }
    suikaDraw();
    g.rafId = suikaRaf(suikaTick);
  }

  // 一步物理（固定步长）：重力 → 位置积分 → 多次约束求解（墙壁 / 圆-圆碰撞）→ 合并 → 出局检测
  function suikaPhysicsStep(g, dt) {
    const fruits = g.fruits;
    for (const f of fruits) {
      f.vy += SUIKA_GRAVITY * dt;
      f.vx *= 0.999;
      f.vy *= 0.999;
      const sp = Math.sqrt(f.vx * f.vx + f.vy * f.vy);
      if (sp > 3500) { f.vx *= 3500 / sp; f.vy *= 3500 / sp; }
      f.x += f.vx * dt;
      f.y += f.vy * dt;
      f.rot += f.omega * dt;
      f.omega *= 0.995;
      if (f.omega > 9) f.omega = 9;
      if (f.omega < -9) f.omega = -9;
      if (f.appear > 0) f.appear = Math.max(0, f.appear - dt * 5);
    }
    const ITER = 5;
    for (let it = 0; it < ITER; it++) {
      for (const f of fruits) {
        if (f.x - f.r < 0) { f.x = f.r; if (f.vx < 0) f.vx = -f.vx * 0.1; }
        if (f.x + f.r > g.W) { f.x = g.W - f.r; if (f.vx > 0) f.vx = -f.vx * 0.1; }
        if (f.y + f.r > g.H) {
          f.y = g.H - f.r;
          if (f.vy > 0) f.vy = -f.vy * 0.05;
          f.vx *= 0.94;
          f.omega += (f.vx / f.r - f.omega) * 0.3;
          if (Math.abs(f.vx) < 4) f.vx *= 0.8;
        }
      }
      for (let i = 0; i < fruits.length; i++) {
        const a = fruits[i];
        for (let j = i + 1; j < fruits.length; j++) {
          const b = fruits[j];
          const dx = b.x - a.x;
          const dy = b.y - a.y;
          const rr = a.r + b.r;
          const d2 = dx * dx + dy * dy;
          if (d2 >= rr * rr || d2 < 1e-9) continue;
          const d = Math.sqrt(d2);
          const nx = dx / d;
          const ny = dy / d;
          const overlap = rr - d;
          const invSum = a.inv + b.inv;
          const ca = a.inv / invSum;
          const cb = b.inv / invSum;
          a.x -= nx * overlap * ca;
          a.y -= ny * overlap * ca;
          b.x += nx * overlap * cb;
          b.y += ny * overlap * cb;
          const rvx = b.vx - a.vx;
          const rvy = b.vy - a.vy;
          const vn = rvx * nx + rvy * ny;
          if (vn < 0) {
            const jimp = -(1 + 0.06) * vn / invSum;
            a.vx -= jimp * nx * a.inv;
            a.vy -= jimp * ny * a.inv;
            b.vx += jimp * nx * b.inv;
            b.vy += jimp * ny * b.inv;
            const tx = -ny;
            const ty = nx;
            const vt = rvx * tx + rvy * ty;
            const jt = -vt * 0.16 / invSum;
            a.vx -= jt * tx * a.inv;
            a.vy -= jt * ty * a.inv;
            b.vx += jt * tx * b.inv;
            b.vy += jt * ty * b.inv;
            a.omega -= (vt / Math.max(8, a.r)) * 0.25;
            b.omega += (vt / Math.max(8, b.r)) * 0.25;
          }
        }
      }
    }
    // 合并（同一水果每轮最多合并一次；一轮内允许连锁，最多 3 轮）
    let pass = 0;
    let merged = true;
    while (merged && pass < 3) {
      merged = false;
      pass++;
      const queue = [];
      const dead = new Set();
      for (let i = 0; i < fruits.length; i++) {
        const a = fruits[i];
        if (dead.has(a) || a.level >= 9) continue;
        for (let j = i + 1; j < fruits.length; j++) {
          const b = fruits[j];
          if (dead.has(b) || b.level !== a.level) continue;
          const dx = b.x - a.x;
          const dy = b.y - a.y;
          const rr = a.r + b.r + 1;
          if (dx * dx + dy * dy <= rr * rr) {
            dead.add(a);
            dead.add(b);
            queue.push([a, b]);
            break;
          }
        }
      }
      for (const pair of queue) {
        suikaMergeFruits(g, pair[0], pair[1]);
        merged = true;
      }
    }
    suikaCheckGameOver(g, dt);
  }

  function suikaMergeFruits(g, a, b) {
    const ia = g.fruits.indexOf(a);
    if (ia >= 0) g.fruits.splice(ia, 1);
    const ib = g.fruits.indexOf(b);
    if (ib >= 0) g.fruits.splice(ib, 1);
    const level = a.level + 1;
    const x = (a.x + b.x) / 2;
    const y = (a.y + b.y) / 2;
    const f = suikaMakeFruit(g, level, x, y);
    f.vx = (a.vx + b.vx) * 0.25;
    f.vy = (a.vy + b.vy) * 0.25 - 30;
    f.appear = 1;
    g.fruits.push(f);
    const gain = SUIKA_GAIN[level] || 10;
    g.score += gain;
    g.merges += 1;
    g.maxLevel = Math.max(g.maxLevel, level);
    suikaBurst(g, x, y, SUIKA_COLORS[level]);
    suikaFloat(g, x, y - f.r - 6, '+' + gain);
    if (level === 9 && !g.won) {
      g.won = true;
      if (!g.rewarded) {
        g.rewarded = true;
        addPoints(1);
        const pl = sheet ? sheet.querySelector('#suika-points-label') : null;
        if (pl) pl.innerHTML = pointsLabelHTML();
      }
      g.paused = true;
      suikaShowVictory(g);
    }
    suikaUpdateHud(g);
  }

  // 出局检测：任意水果静止后顶部仍越过红线，持续 1.2 秒即结束（下落途中短暂经过不算）
  function suikaCheckGameOver(g, dt) {
    if (g.over) return;
    let violation = false;
    for (const f of g.fruits) {
      const speed = Math.sqrt(f.vx * f.vx + f.vy * f.vy);
      if (f.y - f.r < g.lineY - 2 && speed < 70) { violation = true; break; }
    }
    if (violation) {
      g.overTimer += dt;
      if (g.overTimer >= 1.2) {
        g.over = true;
        g.paused = true;
        suikaGameOver(g);
      }
    } else {
      g.overTimer = 0;
    }
  }

  function suikaBurst(g, x, y, color) {
    for (let i = 0; i < 12; i++) {
      const ang = Math.random() * Math.PI * 2;
      const sp = 60 + Math.random() * 180;
      g.particles.push({ x, y, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp - 60, life: 0.45 + Math.random() * 0.3, r: 1.5 + Math.random() * 2.4, color });
    }
  }
  function suikaFloat(g, x, y, text) {
    g.floats.push({ x, y, text, life: 0.9, vy: -40 });
  }

  function suikaContinue() {
    const g = suikaGame;
    if (!g) return;
    if (sheet) sheet.querySelectorAll('.suika-overlay').forEach(el => el.remove());
    g.paused = false;
    g.accum = 0;
    g.lastTs = performance.now();
    showToast('🎮 继续挑战！合成更多西瓜刷更高分');
  }

  function suikaShowVictory(g) {
    const stage = sheet ? sheet.querySelector('#suika-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.suika-overlay').forEach(el => el.remove());
    const ov = document.createElement('div');
    ov.className = 'suika-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.72);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #2ECC71;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:40px;margin-bottom:6px;">🍉</div>
        <div style="font-size:15.5px;font-weight:700;color:#2ECC71;margin-bottom:6px;">合成西瓜达成目标！</div>
        <div style="font-size:12.5px;color:var(--ubp-text-2);line-height:1.7;margin-bottom:14px;">
          积分 <b style="color:#F59E0B;">+1</b>（当前 💎 ${loadPoints()}）· 得分 <b style="color:#FBBF24;">${g.score}</b><br>
          游戏不会结束，可继续投放合成更多西瓜刷高分
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="suika-continue" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#2ECC71;border:none;color:#fff;border-radius:10px;cursor:pointer;">► 继续挑战</button>
          <button data-ubp-act="suika-restart" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
        </div>
        <div style="margin-top:8px;">
          <button data-ubp-act="suika-exit" class="ubp-btn" style="width:100%;padding:8px 0;font-size:12px;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function suikaGameOver(g) {
    suikaClearSave();
    const stage = sheet ? sheet.querySelector('#suika-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.suika-overlay').forEach(el => el.remove());
    const startBest = g.startBest || 0;
    const isNew = g.score > startBest;
    if (g.score > suikaLoadBest()) suikaSaveBest(g.score);
    const maxLabel = g.maxLevel >= 0 ? (SUIKA_EMOJI[g.maxLevel] + ' ' + SUIKA_NAMES[g.maxLevel]) : '—';
    const ov = document.createElement('div');
    ov.className = 'suika-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #EF4444;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '💀'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : '水果越过红线，本局结束'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#FBBF24;font-size:17px;">${g.score}</b><br>
          最大水果：<b style="color:#F59E0B;">${maxLabel}</b><br>
          投放 ${g.drops} 次 · 合并 ${g.merges} 次<br>
          最高分：<b style="color:#F59E0B;">${Math.max(startBest, g.score)}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="suika-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#FBBF24;border:none;color:#3C2A00;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="suika-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">水果静止后仍越过顶部红线即结束（下落途中短暂经过不算）</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function suikaDraw() {
    const g = suikaGame;
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    g.W = cssW;
    g.H = cssH;
    g.lineY = Math.max(64, Math.min(112, Math.round(cssH * 0.16)));
    if (!g.aimInit) { g.aimX = cssW / 2; g.aimInit = true; }
    if (g._rescaleW && Math.abs(cssW - g._rescaleW) > 1) {
      const k = cssW / g._rescaleW;
      for (const f of g.fruits) {
        f.r = f.r * k;
        f.inv = 1 / (f.r * f.r);
        f.x = Math.max(f.r, Math.min(cssW - f.r, f.x * k));
        f.y = Math.max(f.r, Math.min(cssH - f.r, f.y));
      }
      if (g.aimInit) g.aimX = Math.max(0, Math.min(cssW, g.aimX * k));
      g._rescaleW = 0;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssW, cssH);
    // 背景（水色渐变）
    const bg = ctx.createLinearGradient(0, 0, 0, cssH);
    bg.addColorStop(0, '#0E3A46');
    bg.addColorStop(0.55, '#123A58');
    bg.addColorStop(1, '#0B2440');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, cssW, cssH);
    // 底部微光
    const bottomGlow = ctx.createLinearGradient(0, cssH - 90, 0, cssH);
    bottomGlow.addColorStop(0, 'rgba(94,234,212,0)');
    bottomGlow.addColorStop(1, 'rgba(94,234,212,0.08)');
    ctx.fillStyle = bottomGlow;
    ctx.fillRect(0, cssH - 90, cssW, 90);
    // 侧壁
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    ctx.fillRect(0, 0, 3, cssH);
    ctx.fillRect(cssW - 3, 0, 3, cssH);
    // 红线（危险时闪烁加强）
    const danger = Math.min(1, g.overTimer / 1.2);
    ctx.save();
    ctx.setLineDash([9, 7]);
    ctx.lineWidth = 2.5;
    const blink = 0.62 + 0.18 * Math.sin(g.time * 4);
    ctx.strokeStyle = 'rgba(239,68,68,' + Math.min(1, blink + danger * 0.38).toFixed(2) + ')';
    ctx.beginPath();
    ctx.moveTo(6, g.lineY);
    ctx.lineTo(cssW - 6, g.lineY);
    ctx.stroke();
    ctx.restore();
    if (danger > 0.03) {
      ctx.fillStyle = 'rgba(239,68,68,' + (danger * 0.1).toFixed(2) + ')';
      ctx.fillRect(0, 0, cssW, cssH);
    }
    // 待投放水果 + 落点参考线
    if (!g.over && !g.paused && g.pendingLevel >= 0) {
      const pr = suikaRadius(g, g.pendingLevel);
      const px = Math.max(pr + 2, Math.min(cssW - pr - 2, g.aimX));
      ctx.save();
      ctx.setLineDash([5, 7]);
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(px, SUIKA_PENDING_Y + pr);
      ctx.lineTo(px, cssH - 4);
      ctx.stroke();
      ctx.restore();
      suikaDrawFruit(ctx, g, { x: px, y: SUIKA_PENDING_Y + Math.sin(g.time * 3) * 1.5, r: pr, level: g.pendingLevel, rot: 0, appear: 0 }, 0.95);
    }
    // 水果（按 y 排序，下方的先画）
    const sorted = g.fruits.slice().sort((a, b) => a.y - b.y);
    for (const f of sorted) suikaDrawFruit(ctx, g, f, 1);
    // 粒子
    for (const p of g.particles) {
      ctx.globalAlpha = Math.max(0, Math.min(1, p.life / 0.5));
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // 飘字
    ctx.textAlign = 'center';
    for (const ft of g.floats) {
      ctx.globalAlpha = Math.max(0, Math.min(1, ft.life / 0.9));
      ctx.font = '700 14px -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif';
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.lineWidth = 3;
      ctx.strokeText(ft.text, ft.x, ft.y);
      ctx.fillStyle = '#FBBF24';
      ctx.fillText(ft.text, ft.x, ft.y);
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
  }

  function suikaDrawFruit(ctx, g, f, alpha) {
    const r = f.r * (1 + 0.28 * (f.appear || 0));
    const color = SUIKA_COLORS[f.level] || '#2ECC71';
    ctx.globalAlpha = alpha;
    // 圆体
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(f.x, f.y, r, 0, Math.PI * 2);
    ctx.fill();
    // 果肉高光
    const grad = ctx.createRadialGradient(f.x - r * 0.32, f.y - r * 0.38, r * 0.12, f.x, f.y, r);
    grad.addColorStop(0, 'rgba(255,255,255,0.45)');
    grad.addColorStop(0.45, 'rgba(255,255,255,0.08)');
    grad.addColorStop(1, 'rgba(0,0,0,0.16)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(f.x, f.y, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.35)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(f.x, f.y, r - 0.75, 0, Math.PI * 2);
    ctx.stroke();
    // 表情（滚动旋转）
    ctx.save();
    ctx.translate(f.x, f.y);
    if (f.rot) ctx.rotate(f.rot);
    ctx.font = Math.round(r * 1.9) + 'px "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(SUIKA_EMOJI[f.level] || '🍉', 0, r * 0.05);
    ctx.restore();
    ctx.textBaseline = 'alphabetic';
    ctx.globalAlpha = 1;
  }

  function suikaAttachInput(g) {
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    g.keyHandler = (e) => {
      const tgt = e.target;
      if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT' || tgt.isContentEditable)) return;
      if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
        e.preventDefault();
        const step = e.key === 'ArrowLeft' ? -14 : 14;
        const r = suikaRadius(g, g.pendingLevel >= 0 ? g.pendingLevel : 0);
        g.aimX = Math.max(r + 2, Math.min(g.W - r - 2, (g.aimInit ? g.aimX : g.W / 2) + step));
        g.aimInit = true;
      } else if (e.key === 'ArrowDown' || e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        suikaDrop();
      }
    };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    const cv = g.canvas;
    if (cv) {
      const toX = (clientX) => {
        try {
          const rect = cv.getBoundingClientRect();
          return clientX - rect.left;
        } catch (e) { return clientX; }
      };
      cv.addEventListener('contextmenu', (e) => e.preventDefault());
      if (typeof window.PointerEvent !== 'undefined') {
        cv.addEventListener('pointerdown', (e) => {
          e.preventDefault();
          g.pressing = true;
          g.aimX = toX(e.clientX);
          g.aimInit = true;
          try { cv.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
        });
        cv.addEventListener('pointermove', (e) => {
          if (e.pointerType === 'touch' && !g.pressing) return;
          g.aimX = toX(e.clientX);
          g.aimInit = true;
        });
        cv.addEventListener('pointerup', (e) => {
          g.aimX = toX(e.clientX);
          g.aimInit = true;
          if (!g.pressing) return;
          g.pressing = false;
          suikaDrop();
        });
        cv.addEventListener('pointercancel', () => { g.pressing = false; });
      } else {
        cv.addEventListener('touchstart', (e) => { if (e.touches[0]) { g.pressing = true; g.aimX = toX(e.touches[0].clientX); g.aimInit = true; } });
        cv.addEventListener('touchmove', (e) => { if (e.touches[0]) { g.aimX = toX(e.touches[0].clientX); g.aimInit = true; } });
        cv.addEventListener('touchend', () => { if (g.pressing) { g.pressing = false; suikaDrop(); } });
        cv.addEventListener('mousemove', (e) => { g.aimX = toX(e.clientX); g.aimInit = true; });
        cv.addEventListener('mousedown', (e) => { g.pressing = true; g.aimX = toX(e.clientX); g.aimInit = true; });
        cv.addEventListener('mouseup', (e) => { g.aimX = toX(e.clientX); g.aimInit = true; if (g.pressing) { g.pressing = false; suikaDrop(); } });
      }
    }
    if (typeof ResizeObserver !== 'undefined') {
      try {
        g._ro = new ResizeObserver(() => { /* 尺寸由绘制循环自适应 */ });
        if (g.stageEl) g._ro.observe(g.stageEl);
      } catch (e) { /* ignore */ }
    }
    g._onWinResize = () => { /* 尺寸由绘制循环自适应 */ };
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }
  // __SUIKA_ENGINE_END__

  // __SNAKE_ENGINE_BEGIN__
  // ========== 贪吃蛇（20×20 网格 · 自动前进 · 方向键 / 方向按钮 / 滑动转向 · 加速 + 可选穿墙） ==========
  // 规则：开局 3 节，地图随机刷 1 个食物；吃到食物 +10 分并变长一节，随后在空白格重刷食物；
  //       蛇不能直接掉头（向右时按左无效，只能转上/下）；蛇持续朝当前方向自动移动，不是按一次动一格；
  //       撞墙（或开启穿墙时穿到对面）与撞到自己身体即结束；无尽模式，吃得越多移动越快；
  //       自选变体：底部可开关「穿墙」（经典诺基亚）；每累计 100 分自动 +1 积分。
  // 说明：本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const SNAKE_BEST_KEY = 'werewolf_extension_snake_best';
  const SNAKE_SAVE_KEY = 'werewolf_extension_snake_save';
  const SNAKE_WRAP_KEY = 'werewolf_extension_snake_wrap';
  const SNAKE_ACCEL_KEY = 'werewolf_extension_snake_accel';
  const SNAKE_GRID = 20;
  const SNAKE_START_LEN = 3;
  const SNAKE_BASE_MS = 175;        // 初始移动间隔（毫秒）
  const SNAKE_MIN_MS = 65;          // 最快移动间隔
  const SNAKE_SPEEDUP_PER_FOOD = 5; // 每吃 1 个食物提速
  const SNAKE_FOOD_SCORE = 10;
  const SNAKE_REWARD_STEP = 100;    // 每累计 100 分 +1 积分
  const SNAKE_DIRS = { up: { r: -1, c: 0 }, down: { r: 1, c: 0 }, left: { r: 0, c: -1 }, right: { r: 0, c: 1 } };

  let snakeGame = null;
  const snakeRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const snakeCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function snakeLoadBest() {
    try { const n = parseInt(localStorage.getItem(SNAKE_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function snakeSaveBest(n) {
    try { localStorage.setItem(SNAKE_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function snakeLoadWrap() {
    try { return localStorage.getItem(SNAKE_WRAP_KEY) === '1'; } catch (e) { return false; }
  }
  function snakeSaveWrap(v) {
    try { localStorage.setItem(SNAKE_WRAP_KEY, v ? '1' : '0'); } catch (e) { /* ignore */ }
  }
  function snakeLoadAccel() {
    try { const v = localStorage.getItem(SNAKE_ACCEL_KEY); return v === null ? true : v === '1'; } catch (e) { return true; }
  }
  function snakeSaveAccel(v) {
    try { localStorage.setItem(SNAKE_ACCEL_KEY, v ? '1' : '0'); } catch (e) { /* ignore */ }
  }
  function snakeTickMs(g) {
    if (g.accel === false) return SNAKE_BASE_MS; // 关闭加速：保持恒速
    return Math.max(SNAKE_MIN_MS, SNAKE_BASE_MS - (g.eaten || 0) * SNAKE_SPEEDUP_PER_FOOD);
  }
  function snakeHasSave() {
    try { const raw = localStorage.getItem(SNAKE_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && !d.over && Array.isArray(d.body) && d.body.length >= SNAKE_START_LEN); } catch (e) { return false; }
  }
  function snakeClearSave() { try { localStorage.removeItem(SNAKE_SAVE_KEY); } catch (e) { /* ignore */ } }
  function snakeSaveGame(g) {
    try {
      if (!g || g.over) { snakeClearSave(); return false; }
      localStorage.setItem(SNAKE_SAVE_KEY, JSON.stringify({
        v: 1, body: g.snake, dir: g.dir, food: g.food, score: g.score, eaten: g.eaten,
        rewards: g.rewards, nextRewardAt: g.nextRewardAt, wrap: g.wrap, accel: g.accel !== false, over: false
      }));
      return true;
    } catch (e) { return false; }
  }
  function snakeResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(SNAKE_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data || !Array.isArray(data.body) || data.body.length < SNAKE_START_LEN) { snakeOpenGame(); return; }
    snakeOpenGame(data);
    showToast('🔖 已恢复进行中的贪吃蛇（得分 ' + (data.score || 0) + '）');
  }

  // 打开 / 重开一局（saveData 存在时恢复存档）
  function snakeOpenGame(saveData) {
    snakeTeardown();
    if (!sheet) { renderMiniGameLobby(); return; }
    const mid = Math.floor(SNAKE_GRID / 2);
    const g = {
      snake: [],
      dir: 'right',
      pending: [],
      food: { r: mid, c: mid + 4 },
      score: 0,
      startBest: snakeLoadBest(),
      eaten: 0,
      rewards: 0,
      nextRewardAt: SNAKE_REWARD_STEP,
      wrap: snakeLoadWrap(),
      accel: snakeLoadAccel(),
      over: false,
      ended: false,
      time: 0,
      lastTs: 0,
      accum: 0,
      shake: 0,
      pop: 0,
      particles: [],
      floats: [],
      canvas: null,
      stageEl: null,
      rafId: 0,
      doc: null,
      keyHandler: null,
      _onWinResize: null
    };
    if (saveData && Array.isArray(saveData.body) && saveData.body.length >= SNAKE_START_LEN) {
      g.snake = saveData.body.map(s => ({ r: Math.max(0, Math.min(SNAKE_GRID - 1, s.r | 0)), c: Math.max(0, Math.min(SNAKE_GRID - 1, s.c | 0)) }));
      g.dir = SNAKE_DIRS[saveData.dir] ? saveData.dir : 'right';
      g.food = (saveData.food && Number.isFinite(saveData.food.r) && Number.isFinite(saveData.food.c))
        ? { r: Math.max(0, Math.min(SNAKE_GRID - 1, saveData.food.r | 0)), c: Math.max(0, Math.min(SNAKE_GRID - 1, saveData.food.c | 0)) }
        : { r: mid, c: mid + 4 };
      g.score = saveData.score || 0;
      g.eaten = saveData.eaten || 0;
      g.rewards = saveData.rewards || 0;
      g.nextRewardAt = saveData.nextRewardAt || (Math.floor(g.score / SNAKE_REWARD_STEP) + 1) * SNAKE_REWARD_STEP;
      g.wrap = !!saveData.wrap;
      g.accel = saveData.accel === undefined ? snakeLoadAccel() : !!saveData.accel;
    } else {
      for (let i = 0; i < SNAKE_START_LEN; i++) g.snake.push({ r: mid, c: mid - i });
      snakeSpawnFood(g);
    }
    snakeGame = g;
    snakeRenderUI();
    snakeAttachInput(g);
    g.lastTs = performance.now();
    g.rafId = snakeRaf(snakeTick);
  }

  function snakeTeardown(renderLobby) {
    const g = snakeGame;
    snakeGame = null;
    if (g) {
      if (g.rafId) snakeCaf(g.rafId);
      if (g.keyHandler && g.doc) { try { g.doc.removeEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ } }
      if (g._onWinResize && g.doc) { try { (g.doc.defaultView || window).removeEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ } }
    }
    if (renderLobby) renderMiniGameLobby();
  }

  function snakeExitToLobby() {
    const g = snakeGame;
    const saved = !!(g && snakeSaveGame(g));
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    snakeTeardown();
    renderMiniGameLobby();
    showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
  }

  function snakeQuitToCenter() {
    snakeClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    snakeTeardown();
    renderSetup();
    showToast('🚪 已结束本局贪吃蛇');
  }

  function snakeRenderUI() {
    const g = snakeGame;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = snakeLoadBest();
    sheet.innerHTML = `
      <style>
        @keyframes snake-shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-3px); } 75% { transform: translateX(3px); } }
      </style>
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="snake-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="保存进度并返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🐍 贪吃蛇</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="snake-points-label">${pointsLabelHTML()}</span>
            <span id="snake-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="snake-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏中心（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="snake-score-text" style="color:#4ADE80;font-size:18px;vertical-align:-1px;">0</b></div>
          <div id="snake-eaten-text" style="font-size:12px;color:var(--ubp-text-2);">食物: <b style="color:#4ADE80;">0</b></div>
          <div id="snake-speed-text" style="font-size:12px;color:var(--ubp-text-2);">速度: <b style="color:#F59E0B;">LV.1</b></div>
        </div>
        <div id="snake-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#0E1A12;">
          <canvas id="snake-canvas" style="width:100%;height:100%;display:block;touch-action:none;"></canvas>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="display:flex;justify-content:center;align-items:center;gap:22px;">
            <div style="display:grid;grid-template-columns:repeat(3,42px);grid-template-rows:repeat(2,36px);gap:6px;">
              <span></span>
              <button data-snake-dir="up" class="ubp-btn" style="padding:0;font-size:15px;">▲</button>
              <span></span>
              <button data-snake-dir="left" class="ubp-btn" style="padding:0;font-size:15px;">◀</button>
              <button data-snake-dir="down" class="ubp-btn" style="padding:0;font-size:15px;">▼</button>
              <button data-snake-dir="right" class="ubp-btn" style="padding:0;font-size:15px;">▶</button>
            </div>
            <div style="display:flex;flex-direction:column;gap:6px;">
              <button data-ubp-act="snake-wrap-toggle" id="snake-wrap-btn" class="ubp-btn" style="padding:8px 12px;font-size:12px;">🌀 穿墙: ${g.wrap ? '开' : '关'}</button>
              <button data-ubp-act="snake-accel-toggle" id="snake-accel-btn" class="ubp-btn" style="padding:8px 12px;font-size:12px;">⚡ 加速: ${g.accel === false ? '关' : '开'}</button>
              <button data-ubp-act="snake-restart" class="ubp-btn" style="padding:8px 12px;font-size:12px;">🔄 重开</button>
            </div>
          </div>
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;margin-top:6px;">方向键 ↑↓←→ / 点按方向按钮 / 滑动棋盘转向 · 不能直接掉头 · 每 100 分 +1 积分</div>
        </div>
      </div>
    `;
    g.stageEl = sheet.querySelector('#snake-stage');
    g.canvas = sheet.querySelector('#snake-canvas');
    snakeUpdateHud(g);
  }

  function snakeUpdateHud(g) {
    if (!g || !sheet) return;
    const s = sheet.querySelector('#snake-score-text');
    if (s) s.textContent = String(g.score);
    const e = sheet.querySelector('#snake-eaten-text');
    if (e) e.innerHTML = '食物: <b style="color:#4ADE80;">' + g.eaten + '</b>';
    const sp = sheet.querySelector('#snake-speed-text');
    if (sp) {
      const lv = Math.max(1, Math.round((SNAKE_BASE_MS - snakeTickMs(g)) / SNAKE_SPEEDUP_PER_FOOD) + 1);
      sp.innerHTML = '速度: <b style="color:#F59E0B;">LV.' + lv + '</b>';
    }
    const best = snakeLoadBest();
    if (g.score > best) snakeSaveBest(g.score);
    const bl = sheet.querySelector('#snake-best-label');
    if (bl) bl.textContent = '🏆 最高 ' + Math.max(best, g.score);
    const wb = sheet.querySelector('#snake-wrap-btn');
    if (wb) wb.textContent = '🌀 穿墙: ' + (g.wrap ? '开' : '关');
    const ab = sheet.querySelector('#snake-accel-btn');
    if (ab) ab.textContent = '⚡ 加速: ' + (g.accel === false ? '关' : '开');
  }

  // 转向（禁止 180° 掉头；最多缓存 2 个转向，支持快速连续拐弯）
  function snakeSetDirection(dir) {
    const g = snakeGame;
    if (!g || g.over || !SNAKE_DIRS[dir]) return;
    const last = g.pending.length ? g.pending[g.pending.length - 1] : g.dir;
    if (dir === last) return;
    const a = SNAKE_DIRS[last];
    const b = SNAKE_DIRS[dir];
    if (a.r + b.r === 0 && a.c + b.c === 0) return;
    if (g.pending.length < 2) g.pending.push(dir);
  }

  function snakeToggleWrap() {
    const g = snakeGame;
    if (g) {
      g.wrap = !g.wrap;
      snakeSaveWrap(g.wrap);
      snakeUpdateHud(g);
      showToast(g.wrap ? '🌀 穿墙模式：拖到边界从对面穿出' : '🚧 经典模式：碰到边界即结束');
      return;
    }
    const v = !snakeLoadWrap();
    snakeSaveWrap(v);
    showToast(v ? '🌀 穿墙模式已开启（下一局生效）' : '🚧 已关闭穿墙（下一局生效）');
  }

  function snakeToggleAccel() {
    const g = snakeGame;
    const cur = g ? g.accel !== false : snakeLoadAccel();
    const v = !cur;
    snakeSaveAccel(v);
    if (g) { g.accel = v; snakeUpdateHud(g); }
    showToast(v ? '⚡ 加速已开启：吃得越多蛇越快' : '🐢 加速已关闭：蛇保持恒速');
  }

  function snakeSpawnFood(g) {
    const occupied = new Set();
    for (const s of g.snake) occupied.add(s.r * SNAKE_GRID + s.c);
    const empties = [];
    for (let r = 0; r < SNAKE_GRID; r++) {
      for (let c = 0; c < SNAKE_GRID; c++) {
        if (!occupied.has(r * SNAKE_GRID + c)) empties.push({ r, c });
      }
    }
    if (!empties.length) { g.food = { r: -1, c: -1 }; return; }
    g.food = empties[Math.floor(Math.random() * empties.length)];
  }

  function snakeCheckMilestones(g) {
    let crossed = false;
    while (g.score >= g.nextRewardAt) {
      g.nextRewardAt += SNAKE_REWARD_STEP;
      g.rewards += 1;
      addPoints(1);
      crossed = true;
    }
    if (crossed) {
      const pl = sheet ? sheet.querySelector('#snake-points-label') : null;
      if (pl) pl.innerHTML = pointsLabelHTML();
      showToast('🎉 累计得分 ' + g.score + '！积分 +1（当前 ' + loadPoints() + '）');
    }
  }

  function snakeBurst(g, r, c) {
    for (let i = 0; i < 10; i++) {
      const ang = Math.random() * Math.PI * 2;
      const sp = 40 + Math.random() * 140;
      g.particles.push({ r, c, x: 0, y: 0, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp, life: 0.5, max: 0.5 });
    }
  }

  function snakeFloat(g, r, c, text) {
    g.floats.push({ r, c, text, life: 1, vy: -34 });
  }

  function snakeDie(g, reason) {
    if (g.over) return;
    g.over = true;
    g.shake = 1;
    snakeClearSave();
    showToast(reason);
    const ref = g;
    setTimeout(() => { if (snakeGame === ref) snakeGameOver(ref); }, 420);
  }

  function snakeStep(g) {
    if (g.pending.length) g.dir = g.pending.shift();
    const d = SNAKE_DIRS[g.dir];
    let nr = g.snake[0].r + d.r;
    let nc = g.snake[0].c + d.c;
    if (g.wrap) {
      nr = (nr + SNAKE_GRID) % SNAKE_GRID;
      nc = (nc + SNAKE_GRID) % SNAKE_GRID;
    } else if (nr < 0 || nr >= SNAKE_GRID || nc < 0 || nc >= SNAKE_GRID) {
      snakeDie(g, '💥 撞到墙了！');
      return;
    }
    const willEat = (nr === g.food.r && nc === g.food.c);
    const body = willEat ? g.snake : g.snake.slice(0, g.snake.length - 1);
    for (const s of body) {
      if (s.r === nr && s.c === nc) {
        snakeDie(g, '💥 撞到自己了！');
        return;
      }
    }
    g.snake.unshift({ r: nr, c: nc });
    if (willEat) {
      g.eaten += 1;
      g.score += SNAKE_FOOD_SCORE;
      g.pop = 1;
      snakeBurst(g, nr, nc);
      snakeFloat(g, nr, nc, '+' + SNAKE_FOOD_SCORE);
      snakeCheckMilestones(g);
      snakeSpawnFood(g);
      snakeUpdateHud(g);
    } else {
      g.snake.pop();
    }
  }

  function snakeTick(ts) {
    const g = snakeGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { snakeTeardown(false); return; }
    const dt = Math.min(0.1, Math.max(0.001, ((ts || performance.now()) - g.lastTs) / 1000 || 0.016));
    g.lastTs = ts || performance.now();
    g.time += dt;
    if (!g.over) {
      g.accum += dt * 1000;
      const stepMs = snakeTickMs(g);
      let guard = 0;
      while (g.accum >= stepMs && guard < 5 && !g.over) {
        snakeStep(g);
        g.accum -= stepMs;
        guard++;
      }
      if (guard >= 5) g.accum = 0;
    }
    if (g.pop > 0) g.pop = Math.max(0, g.pop - dt * 4);
    if (g.shake > 0) g.shake = Math.max(0, g.shake - dt * 2.4);
    for (let i = g.particles.length - 1; i >= 0; i--) {
      const p = g.particles[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 420 * dt;
      p.life -= dt;
      if (p.life <= 0) g.particles.splice(i, 1);
    }
    for (let i = g.floats.length - 1; i >= 0; i--) {
      const ft = g.floats[i];
      ft.vy *= Math.max(0, 1 - dt * 1.8);
      ft.life -= dt;
      if (ft.life <= 0) g.floats.splice(i, 1);
    }
    snakeDraw();
    g.rafId = snakeRaf(snakeTick);
  }

  function snakeDraw() {
    const g = snakeGame;
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssW, cssH);
    const pad = 6;
    const board = Math.max(120, Math.min(cssW, cssH) - pad * 2);
    const cell = board / SNAKE_GRID;
    const ox = Math.round((cssW - board) / 2);
    const oy = Math.round((cssH - board) / 2);
    // 背景
    const bg = ctx.createLinearGradient(0, 0, 0, cssH);
    bg.addColorStop(0, '#0C1B12');
    bg.addColorStop(1, '#0A140E');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, cssW, cssH);
    ctx.save();
    if (g.shake > 0) ctx.translate((Math.random() - 0.5) * 7 * g.shake, (Math.random() - 0.5) * 7 * g.shake);
    // 棋盘与网格
    ctx.fillStyle = '#10261A';
    ctx.fillRect(ox - 3, oy - 3, board + 6, board + 6);
    ctx.strokeStyle = 'rgba(74,222,128,0.14)';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(ox - 3, oy - 3, board + 6, board + 6);
    ctx.strokeStyle = 'rgba(255,255,255,0.045)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 1; i < SNAKE_GRID; i++) {
      const x = ox + i * cell;
      const y = oy + i * cell;
      ctx.moveTo(x, oy);
      ctx.lineTo(x, oy + board);
      ctx.moveTo(ox, y);
      ctx.lineTo(ox + board, y);
    }
    ctx.stroke();
    // 食物（脉动）
    if (g.food.r >= 0) {
      const pulse = 1 + 0.08 * Math.sin(g.time * 6);
      const fx = ox + (g.food.c + 0.5) * cell;
      const fy = oy + (g.food.r + 0.5) * cell;
      ctx.save();
      ctx.translate(fx, fy);
      ctx.scale(pulse, pulse);
      ctx.font = Math.round(cell * 0.92) + 'px "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('🍎', 0, cell * 0.05);
      ctx.restore();
    }
    // 蛇（头 → 尾渐变）
    const n = g.snake.length;
    for (let i = n - 1; i >= 0; i--) {
      const s = g.snake[i];
      const t = n <= 1 ? 0 : i / (n - 1);
      const x = ox + s.c * cell;
      const y = oy + s.r * cell;
      const inset = Math.max(0.8, cell * 0.06);
      const rad = Math.max(2, cell * 0.28);
      const grow = i === 0 ? g.pop * cell * 0.12 : 0;
      const r0 = 0.31 - 0.11 * t;
      const g0 = 0.85 - 0.35 * t;
      const b0 = 0.5 - 0.17 * t;
      ctx.fillStyle = 'rgb(' + Math.round(255 * r0) + ',' + Math.round(255 * g0) + ',' + Math.round(255 * b0) + ')';
      snakeRoundRect(ctx, x + inset - grow, y + inset - grow, cell - inset * 2 + grow * 2, cell - inset * 2 + grow * 2, rad);
      ctx.fill();
      if (i === 0) snakeDrawHead(ctx, g, x, y, cell);
    }
    // 粒子
    for (const p of g.particles) {
      ctx.globalAlpha = Math.max(0, p.life / p.max);
      ctx.fillStyle = '#F87171';
      ctx.beginPath();
      ctx.arc(ox + (p.c + 0.5) * cell + p.x, oy + (p.r + 0.5) * cell + p.y, Math.max(1.4, cell * 0.1), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // 飘字
    ctx.textAlign = 'center';
    for (const ft of g.floats) {
      const a = Math.max(0, Math.min(1, ft.life));
      const rise = (1 - ft.life) * 34;
      ctx.globalAlpha = a;
      ctx.font = '700 14px -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif';
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.lineWidth = 3;
      ctx.strokeText(ft.text, ox + (ft.c + 0.5) * cell, oy + ft.r * cell - 6 - rise);
      ctx.fillStyle = '#4ADE80';
      ctx.fillText(ft.text, ox + (ft.c + 0.5) * cell, oy + ft.r * cell - 6 - rise);
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
    ctx.restore();
  }

  function snakeDrawHead(ctx, g, x, y, cell) {
    const d = SNAKE_DIRS[g.dir] || SNAKE_DIRS.right;
    const cx = x + cell / 2;
    const cy = y + cell / 2;
    const ex = d.c * cell * 0.16;
    const ey = d.r * cell * 0.16;
    const px = -d.r * cell * 0.17;
    const py = d.c * cell * 0.17;
    ctx.fillStyle = '#052E16';
    ctx.beginPath();
    ctx.arc(cx + ex + px, cy + ey + py, Math.max(1.6, cell * 0.11), 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(cx + ex - px, cy + ey - py, Math.max(1.6, cell * 0.11), 0, Math.PI * 2);
    ctx.fill();
    // 舌头
    ctx.strokeStyle = '#F87171';
    ctx.lineWidth = Math.max(1.2, cell * 0.07);
    ctx.beginPath();
    ctx.moveTo(cx + d.c * cell * 0.3, cy + d.r * cell * 0.3);
    ctx.lineTo(cx + d.c * cell * 0.48, cy + d.r * cell * 0.48);
    ctx.stroke();
  }

  function snakeRoundRect(ctx, x, y, w, h, r) {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  function snakeGameOver(g) {
    snakeClearSave();
    const stage = sheet ? sheet.querySelector('#snake-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.snake-overlay').forEach(el => el.remove());
