  function snakeAttachInput(g) {
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    g.keyHandler = (e) => {
      const tgt = e.target;
      if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT' || tgt.isContentEditable)) return;
      const map = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down' };
      const dir = map[e.key];
      if (!dir) return;
      e.preventDefault();
      snakeSetDirection(dir);
    };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    if (sheet) {
      sheet.querySelectorAll('[data-snake-dir]').forEach(btn => {
        btn.addEventListener('click', (e) => { e.preventDefault(); snakeSetDirection(btn.dataset.snakeDir); });
        btn.addEventListener('contextmenu', (e) => e.preventDefault());
      });
      const cv = g.canvas;
      if (cv) {
        const toPos = (clientX, clientY) => {
          try {
            const rect = cv.getBoundingClientRect();
            return { x: clientX - rect.left, y: clientY - rect.top };
          } catch (e) { return { x: clientX, y: clientY }; }
        };
        let sx = 0;
        let sy = 0;
        let tracking = false;
        const start = (x, y) => { sx = x; sy = y; tracking = true; };
        const finish = (x, y) => {
          if (!tracking) return;
          tracking = false;
          const dx = x - sx;
          const dy = y - sy;
          if (Math.max(Math.abs(dx), Math.abs(dy)) < 22) return;
          if (Math.abs(dx) > Math.abs(dy)) snakeSetDirection(dx > 0 ? 'right' : 'left');
          else snakeSetDirection(dy > 0 ? 'down' : 'up');
        };
        cv.addEventListener('contextmenu', (e) => e.preventDefault());
        if (typeof window.PointerEvent !== 'undefined') {
          cv.addEventListener('pointerdown', (e) => {
            e.preventDefault();
            const pos = toPos(e.clientX, e.clientY);
            try { cv.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
            start(pos.x, pos.y);
          });
          cv.addEventListener('pointerup', (e) => {
            e.preventDefault();
            const pos = toPos(e.clientX, e.clientY);
            finish(pos.x, pos.y);
          });
          cv.addEventListener('pointercancel', () => { tracking = false; });
        } else {
          cv.addEventListener('touchstart', (e) => { if (e.touches[0]) start(e.touches[0].clientX, e.touches[0].clientY); });
          cv.addEventListener('touchend', (e) => { if (e.changedTouches[0]) finish(e.changedTouches[0].clientX, e.changedTouches[0].clientY); });
          cv.addEventListener('mousedown', (e) => start(e.clientX, e.clientY));
          cv.addEventListener('mouseup', (e) => finish(e.clientX, e.clientY));
        }
      }
    }
    g._onWinResize = () => { /* 尺寸由绘制循环自适应 */ };
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }
  // __SNAKE_ENGINE_END__

  // __PAC_ENGINE_BEGIN__
  // ========== 吃豆人（19×21 迷宫 · 幽灵独立 AI · 传送隧道 · 能量豆反吃 · 香蕉关卡提速） ==========
  // 规则：方向键 / 方向按钮 / 滑动控制黄色吃豆人；小点 +10、能量豆 +50（四角闪烁）；吃能量豆后幽灵变蓝逃跑，
  //       反吃幽灵 200→400→800→1600；幽灵被吃只剩眼睛跑回鬼屋重生；每关随机短暂出现水果拿额外高分；
  //       4 只幽灵（红直接追 / 粉预判 / 青包夹 / 橙远追近躲），追击与分散模式交替；左右两侧传送隧道；
  //       正常状态碰到幽灵损失 1 条命（共 3 条），吃光全部小点+能量豆进入下一关（幽灵更快、能量时间更短）；
  //       每通关一关 +1 积分。本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const PAC_BEST_KEY = 'werewolf_extension_pac_best';
  const PAC_SAVE_KEY = 'werewolf_extension_pac_save';
  const PAC_W = 19;
  const PAC_H = 21;
  const PAC_MAZE = [
    '###################',
    '#........#........#',
    '#.##.###.#.###.##.#',
    '#o.#.###.#.###.#.o#',
    '#.................#',
    '#.##.#.#####.#.##.#',
    '####.#.#.#.#.#.####',
    '####.#...#...#.####',
    '####.#.#####.#.####',
    '####.#.......#.####',
    ' .....###=###..... ',
    '####.##HHHHH##.####',
    '####.#########.####',
    '####.#.......#.####',
    '####.#.#####.#.####',
    '#........#........#',
    '#.##.###.#.###.##.#',
    '#o.#.###.#.###.#.o#',
    '##.#.#.#####.#.#.##',
    '#.................#',
    '###################'
  ];
  const PAC_PLAYER_START = { r: 19, c: 9 };
  const PAC_GATE = { r: 9, c: 9 };   // 鬼屋门前格
  const PAC_DOOR = { r: 10, c: 9 };
  const PAC_HOUSE = { r: 11, c: 9 };
  const PAC_DIRS = { up: { r: -1, c: 0 }, down: { r: 1, c: 0 }, left: { r: 0, c: -1 }, right: { r: 0, c: 1 } };
  const PAC_OPP = { up: 'down', down: 'up', left: 'right', right: 'left' };
  const PAC_PLAYER_SPEED = 7.6;
  const PAC_WALL_COLORS = ['#2563EB', '#16A34A', '#9333EA', '#EA580C', '#DC2626', '#0891B2'];
  const PAC_GHOST_DEFS = [
    { id: 'blinky', color: '#EF4444', start: { r: 9, c: 9 }, dir: 'left', scatter: { r: 1, c: 17 }, release: 0 },
    { id: 'pinky', color: '#F9A8D4', start: { r: 11, c: 7 }, dir: 'up', scatter: { r: 1, c: 1 }, release: 2 },
    { id: 'inky', color: '#22D3EE', start: { r: 11, c: 9 }, dir: 'up', scatter: { r: 17, c: 17 }, release: 5 },
    { id: 'clyde', color: '#FB923C', start: { r: 11, c: 11 }, dir: 'up', scatter: { r: 17, c: 1 }, release: 8 }
  ];
  const PAC_FRUITS = [
    { emoji: '🍒', name: '樱桃', score: 100 },
    { emoji: '🍓', name: '草莓', score: 300 },
    { emoji: '🍊', name: '橘子', score: 500 },
    { emoji: '🍎', name: '苹果', score: 700 },
    { emoji: '🍈', name: '蜜瓜', score: 1000 }
  ];

  let pacGame = null;
  const pacRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const pacCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function pacLoadBest() {
    try { const n = parseInt(localStorage.getItem(PAC_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function pacSaveBest(n) {
    try { localStorage.setItem(PAC_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function pacFrightTime(level) { return Math.max(2.5, 8 - (level - 1) * 0.8); }
  function pacScatterTime(level) { return Math.max(3, 7 - (level - 1) * 0.5); }
  function pacGhostSpeed(g, gh) {
    if (gh.state === 'eaten' || gh.state === 'entering') return 16;
    if (gh.frightened) return 4.6;
    return Math.min(8.4, 6.7 + (g.level - 1) * 0.3);
  }
  function pacFruitForLevel(level) { return PAC_FRUITS[Math.min(Math.max(0, level - 1), PAC_FRUITS.length - 1)]; }
  function pacWrapC(c) { if (c < 0) return PAC_W - 1; if (c >= PAC_W) return 0; return c; }
  function pacCharAt(g, r, c) {
    if (r < 0 || r >= PAC_H) return '#';
    return g.grid[r][pacWrapC(c)];
  }
  function pacAdvanceTile(tile, name) {
    const d = PAC_DIRS[name];
    return { r: tile.r + d.r, c: pacWrapC(tile.c + d.c) };
  }
  function pacIsEdgeWrap(tile, name) {
    const d = PAC_DIRS[name];
    return d.c !== 0 && (tile.c + d.c < 0 || tile.c + d.c >= PAC_W);
  }
  function pacPlayerWalkable(g, r, c) {
    const ch = pacCharAt(g, r, c);
    return ch === '.' || ch === 'o' || ch === ' ';
  }
  function pacGhostWalk(g, gh, r, c) {
    const ch = pacCharAt(g, r, c);
    if (ch === '.' || ch === 'o' || ch === ' ') return true;
    if (ch === '=' || ch === 'H') return gh.state === 'eaten' || gh.state === 'entering' || gh.state === 'leaving' || gh.state === 'house';
    return false;
  }
  function pacCanMove(g, tile, name) {
    if (!PAC_DIRS[name]) return false;
    const nt = pacAdvanceTile(tile, name);
    return pacPlayerWalkable(g, nt.r, nt.c);
  }
  function pacEntityPx(e) {
    const d = PAC_DIRS[e.dir] || PAC_DIRS.left;
    return { x: e.tile.c + d.c * e.prog, y: e.tile.r + d.r * e.prog };
  }
  function pacPixelDist2(a, b) {
    const pa = pacEntityPx(a);
    const pb = pacEntityPx(b);
    const dx = pa.x - pb.x;
    const dy = pa.y - pb.y;
    return dx * dx + dy * dy;
  }

  function pacCountDots(grid) {
    let n = 0;
    for (const row of grid) for (const ch of row) if (ch === '.' || ch === 'o') n++;
    return n;
  }
  function pacResetMaze(g) {
    g.grid = PAC_MAZE.map(row => row.split(''));
    g.grid[PAC_PLAYER_START.r][PAC_PLAYER_START.c] = ' ';
    g.dotsLeft = pacCountDots(g.grid);
    g.dotsEaten = 0;
    g.fruit = { active: false, type: 0, emoji: '🍒', value: 100, r: 13, c: 9, timer: 0 };
    g.fruitSpawns = 0;
  }
  function pacMakeGhost(g, def) {
    return {
      id: def.id, color: def.color, scatter: def.scatter,
      tile: { r: def.start.r, c: def.start.c }, dir: def.dir,
      prog: 0, moving: false,
      state: def.release > 0 ? 'house' : 'normal',
      releaseLeft: def.release, frightened: false, forceReverse: false
    };
  }
  function pacResetRound(g) {
    g.player.tile = { r: PAC_PLAYER_START.r, c: PAC_PLAYER_START.c };
    g.player.dir = 'left';
    g.player.want = null;
    g.player.prog = 0;
    g.player.moving = false;
    g.ghosts = PAC_GHOST_DEFS.map(def => pacMakeGhost(g, def));
    g.frightLeft = 0;
    g.chain = 1;
    g.mode = 'scatter';
    g.modeLeft = pacScatterTime(g.level);
  }

  function pacHasSave() {
    try {
      const raw = localStorage.getItem(PAC_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && Array.isArray(d.grid) && d.grid.length === PAC_H && (d.lives | 0) > 0);
    } catch (e) { return false; }
  }
  function pacClearSave() { try { localStorage.removeItem(PAC_SAVE_KEY); } catch (e) { /* ignore */ } }
  function pacSaveGame(g) {
    try {
      if (!g || g.over) { pacClearSave(); return false; }
      const payload = {
        v: 1, level: g.level, score: g.score, lives: g.lives, rewards: g.rewards,
        dotsLeft: g.dotsLeft, dotsEaten: g.dotsEaten,
        grid: g.grid.map(row => row.join('')),
        player: { tile: { r: g.player.tile.r, c: g.player.tile.c }, dir: g.player.dir, want: g.player.want },
        ghosts: g.ghosts.map(gh => ({ id: gh.id, state: gh.state, frightened: !!gh.frightened, tile: { r: gh.tile.r, c: gh.tile.c }, dir: gh.dir, releaseLeft: gh.releaseLeft })),
        frightLeft: g.frightLeft, chain: g.chain, mode: g.mode, modeLeft: g.modeLeft,
        fruit: { active: g.fruit.active, type: g.fruit.type, r: g.fruit.r, c: g.fruit.c, timer: g.fruit.timer },
        fruitSpawns: g.fruitSpawns
      };
      localStorage.setItem(PAC_SAVE_KEY, JSON.stringify(payload));
      return true;
    } catch (e) { return false; }
  }
  function pacResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(PAC_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data || !Array.isArray(data.grid) || data.grid.length !== PAC_H) { pacOpenGame(); return; }
    pacOpenGame(data);
    showToast('🔖 已恢复进行中的吃豆人（第 ' + data.level + ' 关 · 得分 ' + (data.score || 0) + '）');
  }

  function pacOpenGame(saveData) {
    pacTeardown();
    if (!sheet) { renderMiniGameLobby(); return; }
    const g = {
      level: 1, score: 0, startBest: pacLoadBest(), lives: 3, rewards: 0,
      grid: [], dotsLeft: 0, dotsEaten: 0,
      player: { tile: { r: PAC_PLAYER_START.r, c: PAC_PLAYER_START.c }, dir: 'left', want: null, prog: 0, moving: false },
      ghosts: [],
      state: 'ready', readyLeft: 1.8, dyingLeft: 0, clearLeft: 0,
      frightLeft: 0, chain: 1, mode: 'scatter', modeLeft: 0,
      fruit: { active: false, type: 0, emoji: '🍒', value: 100, r: 13, c: 9, timer: 0 },
      fruitSpawns: 0,
      over: false, time: 0, lastTs: 0,
      particles: [], floats: [],
      canvas: null, stageEl: null, rafId: 0, doc: null, keyHandler: null, _onWinResize: null
    };
    if (saveData && Array.isArray(saveData.grid) && saveData.grid.length === PAC_H) {
      g.grid = saveData.grid.map(row => String(row).split(''));
      g.level = Math.max(1, saveData.level | 0);
      g.score = saveData.score || 0;
      g.lives = Math.max(1, saveData.lives | 0);
      g.rewards = saveData.rewards || 0;
      g.dotsLeft = saveData.dotsLeft | 0;
      g.dotsEaten = saveData.dotsEaten | 0;
      g.frightLeft = saveData.frightLeft || 0;
      g.chain = saveData.chain || 1;
      g.mode = saveData.mode === 'chase' ? 'chase' : 'scatter';
      g.modeLeft = saveData.modeLeft || pacScatterTime(g.level);
      g.fruitSpawns = saveData.fruitSpawns || 0;
      const ft = pacFruitForLevel(saveData.fruit && saveData.fruit.type != null ? saveData.fruit.type + 1 : g.level);
      g.fruit = {
        active: !!(saveData.fruit && saveData.fruit.active),
        type: (saveData.fruit && saveData.fruit.type) || 0,
        emoji: ft.emoji, value: ft.score,
        r: (saveData.fruit && saveData.fruit.r) || 13,
        c: (saveData.fruit && saveData.fruit.c) || 9,
        timer: (saveData.fruit && saveData.fruit.timer) || 0
      };
      g.ghosts = PAC_GHOST_DEFS.map(def => {
        const saved = (saveData.ghosts || []).find(x => x && x.id === def.id);
        const gh = pacMakeGhost(g, def);
        if (saved) {
          gh.state = saved.state || gh.state;
          gh.frightened = !!saved.frightened;
          if (saved.tile && Number.isFinite(saved.tile.r) && Number.isFinite(saved.tile.c)) gh.tile = { r: saved.tile.r | 0, c: saved.tile.c | 0 };
          if (PAC_DIRS[saved.dir]) gh.dir = saved.dir;
          if (Number.isFinite(saved.releaseLeft)) gh.releaseLeft = saved.releaseLeft;
        }
        return gh;
      });
      if (saveData.player && saveData.player.tile) {
        g.player.tile = { r: saveData.player.tile.r | 0, c: saveData.player.tile.c | 0 };
        if (PAC_DIRS[saveData.player.dir]) g.player.dir = saveData.player.dir;
        g.player.want = PAC_DIRS[saveData.player.want] ? saveData.player.want : null;
      }
      g.state = 'ready';
      g.readyLeft = 1.6;
    } else {
      pacResetMaze(g);
      pacResetRound(g);
    }
    pacGame = g;
    pacRenderUI();
    pacAttachInput(g);
    g.lastTs = performance.now();
    g.rafId = pacRaf(pacTick);
  }

  function pacTeardown(renderLobby) {
    const g = pacGame;
    pacGame = null;
    if (g) {
      if (g.rafId) pacCaf(g.rafId);
      if (g.keyHandler && g.doc) { try { g.doc.removeEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ } }
      if (g._onWinResize && g.doc) { try { (g.doc.defaultView || window).removeEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ } }
    }
    if (renderLobby) renderMiniGameLobby();
  }

  function pacExitToLobby() {
    const g = pacGame;
    const saved = !!(g && pacSaveGame(g));
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
