    showToast('🚪 已结束本局吃豆人');
  }

  function pacRenderUI() {
    const g = pacGame;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = pacLoadBest();
    sheet.innerHTML = `
      <style>
        @keyframes pac-ready-pop { 0% { transform: scale(0.8); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
      </style>
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="pac-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="保存进度并返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🟡 吃豆人</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="pac-points-label">${pointsLabelHTML()}</span>
            <span id="pac-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="pac-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏中心（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="pac-score-text" style="color:#FDE047;font-size:18px;vertical-align:-1px;">0</b></div>
          <div id="pac-level-text" style="font-size:12px;color:var(--ubp-text-2);">第 <b style="color:#F59E0B;">1</b> 关</div>
          <div id="pac-lives-text" style="font-size:12px;color:var(--ubp-text-2);">❤️❤️❤️</div>
        </div>
        <div id="pac-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#08081A;">
          <canvas id="pac-canvas" style="width:100%;height:100%;display:block;touch-action:none;"></canvas>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="display:flex;justify-content:center;align-items:center;gap:22px;">
            <div style="display:grid;grid-template-columns:repeat(3,42px);grid-template-rows:repeat(2,36px);gap:6px;">
              <span></span>
              <button data-pac-dir="up" class="ubp-btn" style="padding:0;font-size:15px;">▲</button>
              <span></span>
              <button data-pac-dir="left" class="ubp-btn" style="padding:0;font-size:15px;">◀</button>
              <button data-pac-dir="down" class="ubp-btn" style="padding:0;font-size:15px;">▼</button>
              <button data-pac-dir="right" class="ubp-btn" style="padding:0;font-size:15px;">▶</button>
            </div>
            <button data-ubp-act="pac-restart" class="ubp-btn" style="padding:9px 14px;font-size:12.5px;">🔄 重开</button>
          </div>
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;margin-top:6px;">方向键 / 方向按钮 / 滑动迷宫 · 能量豆后反吃幽灵 200→1600 · 清空豆子进入下一关（每关 +1 积分）</div>
        </div>
      </div>
    `;
    g.stageEl = sheet.querySelector('#pac-stage');
    g.canvas = sheet.querySelector('#pac-canvas');
    pacUpdateHud(g);
  }

  function pacUpdateHud(g) {
    if (!g || !sheet) return;
    const s = sheet.querySelector('#pac-score-text');
    if (s) s.textContent = String(g.score);
    const lv = sheet.querySelector('#pac-level-text');
    if (lv) lv.innerHTML = '第 <b style="color:#F59E0B;">' + g.level + '</b> 关';
    const li = sheet.querySelector('#pac-lives-text');
    if (li) li.textContent = '❤️'.repeat(Math.max(0, g.lives)) || '—';
    const best = pacLoadBest();
    if (g.score > best) pacSaveBest(g.score);
    const bl = sheet.querySelector('#pac-best-label');
    if (bl) bl.textContent = '🏆 最高 ' + Math.max(best, g.score);
  }

  function pacSetDirection(dir) {
    const g = pacGame;
    if (!g || g.over || !PAC_DIRS[dir]) return;
    if (g.state !== 'play' && g.state !== 'ready') return;
    const p = g.player;
    p.want = dir;
    if (g.state !== 'play') return;
    if (dir === p.dir) return;
    if (p.moving && p.prog > 0) {
      if (dir === PAC_OPP[p.dir]) {
        // 两格之间原地掉头
        p.tile = pacAdvanceTile(p.tile, p.dir);
        p.prog = 1 - p.prog;
        p.dir = dir;
        return;
      }
      // 转向容错（cornering）：距格中心较近时按方向立即生效，不必等到下一格
      const CORNER = 0.42;
      if (p.prog <= CORNER && pacCanMove(g, p.tile, dir)) {
        p.prog = 0;
        p.dir = dir;
        p.moving = true;
        return;
      }
      const ahead = pacAdvanceTile(p.tile, p.dir);
      if ((1 - p.prog) <= CORNER && pacCanMove(g, ahead, dir)) {
        p.tile = ahead;
        p.prog = 0;
        p.dir = dir;
        p.moving = true;
        pacPlayerArrive(g); // 提前吸附到下一格中心：补算吃豆 / 水果
        return;
      }
      return; // 记住转向意图，到下一格中心再转
    }
    if (!p.moving && p.prog <= 0) p.dir = dir;
  }

  function pacFloat(g, r, c, text) {
    g.floats.push({ r, c, text, life: 1.1, vy: -30 });
  }
  function pacBurst(g, r, c) {
    for (let i = 0; i < 8; i++) {
      const ang = Math.random() * Math.PI * 2;
      const sp = 30 + Math.random() * 90;
      g.particles.push({ r, c, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp, life: 0.45 });
    }
  }

  function pacPlayerArrive(g) {
    const p = g.player;
    const ch = g.grid[p.tile.r][p.tile.c];
    if (ch === '.') {
      g.grid[p.tile.r][p.tile.c] = ' ';
      g.score += 10;
      g.dotsLeft -= 1;
      g.dotsEaten += 1;
      pacMaybeSpawnFruit(g);
      pacUpdateHud(g);
      if (g.dotsLeft <= 0) { pacLevelClear(g); return; }
    } else if (ch === 'o') {
      g.grid[p.tile.r][p.tile.c] = ' ';
      g.score += 50;
      g.dotsLeft -= 1;
      g.dotsEaten += 1;
      pacFloat(g, p.tile.r, p.tile.c, '+50');
      g.frightLeft = pacFrightTime(g.level);
      g.chain = 1;
      for (const gh of g.ghosts) {
        if (gh.state === 'normal') { gh.frightened = true; gh.forceReverse = true; }
      }
      pacMaybeSpawnFruit(g);
      pacUpdateHud(g);
      if (g.dotsLeft <= 0) { pacLevelClear(g); return; }
    }
    if (g.fruit.active && g.fruit.r === p.tile.r && g.fruit.c === p.tile.c) {
      g.score += g.fruit.value;
      pacFloat(g, p.tile.r, p.tile.c, g.fruit.emoji + ' +' + g.fruit.value);
      g.fruit.active = false;
      pacUpdateHud(g);
    }
  }

  function pacMaybeSpawnFruit(g) {
    if (g.fruitSpawns >= 2) return;
    if (g.dotsEaten !== 40 && g.dotsEaten !== 110) return;
    const t = pacFruitForLevel(g.level);
    g.fruit = { active: true, type: Math.min(g.level - 1, PAC_FRUITS.length - 1), emoji: t.emoji, value: t.score, r: 13, c: 9, timer: 9 };
    g.fruitSpawns += 1;
    showToast(t.emoji + ' 水果出现！吃掉 +' + t.score + ' 分（限时 ' + 9 + ' 秒）');
  }

  function pacLevelClear(g) {
    g.state = 'levelclear';
    g.clearLeft = 1.5;
    g.rewards += 1;
    addPoints(1);
    const pl = sheet ? sheet.querySelector('#pac-points-label') : null;
    if (pl) pl.innerHTML = pointsLabelHTML();
    showToast('🎉 第 ' + g.level + ' 关通关！积分 +1（当前 ' + loadPoints() + '）');
  }

  function pacNextLevel(g) {
    g.level += 1;
    pacResetMaze(g);
    pacResetRound(g);
    g.state = 'ready';
    g.readyLeft = 1.7;
    pacUpdateHud(g);
    showToast('🚀 进入第 ' + g.level + ' 关：幽灵更快、能量豆时间更短');
  }

  function pacPlayerDie(g) {
    if (g.state !== 'play') return;
    g.state = 'dying';
    g.dyingLeft = 1.5;
    g.frightLeft = 0;
    for (const gh of g.ghosts) gh.frightened = false;
  }

  function pacAfterDeath(g) {
    g.lives -= 1;
    pacUpdateHud(g);
    if (g.lives <= 0) {
      g.over = true;
      pacClearSave();
      g.state = 'over';
      pacGameOver(g);
      return;
    }
    pacResetRound(g);
    g.state = 'ready';
    g.readyLeft = 1.7;
    showToast('💔 损失一条命！剩余生命 ' + g.lives);
  }

  function pacUpdatePlay(g, dt) {
    // 模式计时（惊吓期间暂停）
    if (g.frightLeft > 0) {
      g.frightLeft = Math.max(0, g.frightLeft - dt);
      if (g.frightLeft === 0) {
        for (const gh of g.ghosts) gh.frightened = false;
      }
    } else {
      g.modeLeft -= dt;
      if (g.modeLeft <= 0) {
        g.mode = g.mode === 'scatter' ? 'chase' : 'scatter';
        g.modeLeft = g.mode === 'scatter' ? pacScatterTime(g.level) : 20;
        for (const gh of g.ghosts) { if (gh.state === 'normal') gh.forceReverse = true; }
      }
    }
    // 水果限时
    if (g.fruit.active) {
      g.fruit.timer -= dt;
      if (g.fruit.timer <= 0) g.fruit.active = false;
    }
    // 鬼屋释放
    for (const gh of g.ghosts) {
      if (gh.state === 'house') {
        gh.releaseLeft -= dt;
        if (gh.releaseLeft <= 0) { gh.state = 'leaving'; }
      }
    }
    // 移动
    pacStepEntity(g, g.player, PAC_PLAYER_SPEED, dt, pacPlayerDecide);
    for (const gh of g.ghosts) {
      pacStepEntity(g, gh, pacGhostSpeed(g, gh), dt, pacGhostDecide);
    }
    pacCheckCollisions(g);
  }

  function pacStepEntity(g, e, speed, dt, decide) {
    let dist = speed * dt;
    let guard = 0;
    while (dist > 1e-9 && guard++ < 10) {
      if (!e.moving) {
        decide(g, e);
        if (!e.moving) { e.prog = 0; break; }
      }
      const remain = 1 - e.prog;
      if (dist < remain) {
        e.prog += dist;
        dist = 0;
      } else {
        dist -= remain;
        e.tile = pacAdvanceTile(e.tile, e.dir);
        e.prog = 0;
        e.moving = false;
        if (e === g.player) pacPlayerArrive(g);
        if (g.state !== 'play') return;
      }
    }
  }

  function pacPlayerDecide(g, e) {
    if (e.want && pacCanMove(g, e.tile, e.want)) e.dir = e.want;
    if (pacCanMove(g, e.tile, e.dir)) e.moving = true;
    else e.moving = false;
  }

  function pacGhostTarget(g, gh) {
    const p = g.player;
    const pd = PAC_DIRS[p.dir] || PAC_DIRS.left;
    if (g.mode === 'scatter') return gh.scatter;
    if (gh.id === 'blinky') return { r: p.tile.r, c: p.tile.c };
    if (gh.id === 'pinky') return { r: p.tile.r + pd.r * 4, c: p.tile.c + pd.c * 4 };
    if (gh.id === 'inky') {
      const blinky = g.ghosts.find(x => x.id === 'blinky');
      const piv = { r: p.tile.r + pd.r * 2, c: p.tile.c + pd.c * 2 };
      const br = blinky ? blinky.tile.r : piv.r;
      const bc = blinky ? blinky.tile.c : piv.c;
      return { r: piv.r * 2 - br, c: piv.c * 2 - bc };
    }
    // clyde：距离远追、靠近回角落
    const dr = gh.tile.r - p.tile.r;
    const dc = gh.tile.c - p.tile.c;
    return (dr * dr + dc * dc) > 64 ? { r: p.tile.r, c: p.tile.c } : gh.scatter;
  }

  function pacGhostChoose(g, gh, target, flee) {
    const opp = PAC_OPP[gh.dir];
    const opts = [];
    for (const name of ['up', 'left', 'down', 'right']) {
      if (name === opp) continue;
      const nt = pacAdvanceTile(gh.tile, name);
      if (!pacGhostWalk(g, gh, nt.r, nt.c)) continue;
      opts.push({ name, nt });
    }
    if (!opts.length) {
      const nt = pacAdvanceTile(gh.tile, opp);
      if (pacGhostWalk(g, gh, nt.r, nt.c)) { gh.dir = opp; gh.moving = true; }
      else gh.moving = false;
      return;
    }
    let best = opts[0];
    let bestScore = Infinity;
    for (const o of opts) {
      let score;
      if (flee) {
        const dr = o.nt.r - g.player.tile.r;
        const dc = o.nt.c - g.player.tile.c;
        score = -(dr * dr + dc * dc) + Math.random() * 0.8;
      } else {
        const dr = o.nt.r - target.r;
        const dc = o.nt.c - target.c;
        score = dr * dr + dc * dc;
      }
      if (score < bestScore) { bestScore = score; best = o; }
    }
    gh.dir = best.name;
    gh.moving = true;
  }

  function pacGhostDecide(g, gh) {
    if (gh.state === 'house') { gh.moving = false; return; }
    if (gh.state === 'leaving') {
      if (gh.tile.r === 9 && gh.tile.c === 9) {
        gh.state = 'normal';
        gh.frightened = g.frightLeft > 0;
        gh.forceReverse = false;
        // 落到下面继续按普通 AI 决策
      } else {
        let dir = null;
        if (gh.tile.r === 11 && gh.tile.c !== 9) dir = gh.tile.c < 9 ? 'right' : 'left';
        else if (gh.tile.r >= 10) dir = 'up';
        if (dir) { gh.dir = dir; gh.moving = true; return; }
        gh.moving = false;
        return;
      }
    }
    if (gh.state === 'entering') {
      if (gh.tile.r < 11) { gh.dir = 'down'; gh.moving = true; return; }
      gh.state = 'house';
      gh.releaseLeft = 1.0;
      gh.frightened = false;
      gh.moving = false;
      return;
    }
    if (gh.state === 'eaten') {
      if (gh.tile.r === PAC_GATE.r && gh.tile.c === PAC_GATE.c) {
        gh.state = 'entering';
        gh.dir = 'down';
        gh.moving = true;
        return;
      }
      pacGhostChoose(g, gh, PAC_GATE, false);
      return;
    }
    if (gh.frightened) {
      gh.forceReverse = false;
      pacGhostChoose(g, gh, null, true);
      return;
    }
    if (gh.forceReverse) {
      gh.forceReverse = false;
      const opp = PAC_OPP[gh.dir];
      const nt = pacAdvanceTile(gh.tile, opp);
      if (pacGhostWalk(g, gh, nt.r, nt.c)) { gh.dir = opp; gh.moving = true; return; }
    }
    pacGhostChoose(g, gh, pacGhostTarget(g, gh), false);
  }

  function pacCheckCollisions(g) {
    const p = g.player;
    for (const gh of g.ghosts) {
      if (gh.state === 'eaten' || gh.state === 'entering' || gh.state === 'house') continue;
      const same = gh.tile.r === p.tile.r && gh.tile.c === p.tile.c && gh.prog === 0 && p.prog === 0;
      if (!same && pacPixelDist2(p, gh) > 0.36) continue;
      if (gh.state === 'normal' && gh.frightened) {
        const pts = Math.min(200 * Math.pow(2, g.chain - 1), 1600);
        g.chain = Math.min(g.chain + 1, 5);
        g.score += pts;
        gh.state = 'eaten';
        gh.frightened = false;
        gh.forceReverse = false;
        pacFloat(g, gh.tile.r, gh.tile.c, '+' + pts);
        pacBurst(g, gh.tile.r, gh.tile.c);
        pacUpdateHud(g);
      } else if (!gh.frightened) {
        pacPlayerDie(g);
        return;
      }
    }
  }

  function pacUpdate(g, dt) {
    if (!g) return;
    g.time += dt;
    if (g.state === 'ready') {
      g.readyLeft -= dt;
      if (g.readyLeft <= 0) g.state = 'play';
    } else if (g.state === 'play') {
      pacUpdatePlay(g, dt);
    } else if (g.state === 'dying') {
      g.dyingLeft -= dt;
      if (g.dyingLeft <= 0) pacAfterDeath(g);
    } else if (g.state === 'levelclear') {
      g.clearLeft -= dt;
      if (g.clearLeft <= 0) pacNextLevel(g);
    }
    for (let i = g.particles.length - 1; i >= 0; i--) {
      const pt = g.particles[i];
      pt.r += pt.vy * dt * 0.01;
      pt.life -= dt;
      if (pt.life <= 0) g.particles.splice(i, 1);
    }
    for (let i = g.floats.length - 1; i >= 0; i--) {
      const ft = g.floats[i];
      ft.vy *= Math.max(0, 1 - dt * 1.8);
      ft.life -= dt;
      if (ft.life <= 0) g.floats.splice(i, 1);
    }
  }

  function pacGameOver(g) {
    pacClearSave();
    const stage = sheet ? sheet.querySelector('#pac-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.pac-overlay').forEach(el => el.remove());
    const startBest = g.startBest || 0;
    const isNew = g.score > startBest;
    const best = Math.max(startBest, g.score);
    if (g.score > pacLoadBest()) pacSaveBest(g.score);
    const bl = sheet ? sheet.querySelector('#pac-best-label') : null;
    if (bl) bl.textContent = '🏆 最高 ' + best;
    const ov = document.createElement('div');
    ov.className = 'pac-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #FDE047;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '💀'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : 'GAME OVER'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#FDE047;font-size:17px;">${g.score}</b><br>
          到达关卡：<b style="color:#F59E0B;">第 ${g.level} 关</b><br>
          最高分：<b style="color:#F59E0B;">${best}</b><br>
          本局积分奖励：<b style="color:#F59E0B;">+${g.rewards}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="pac-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#FDE047;border:none;color:#422006;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="pac-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">生命耗尽即结束 · 每通关一关 +1 积分</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function pacTick(ts) {
    const g = pacGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { pacTeardown(false); return; }
    const dt = Math.min(0.05, Math.max(0.001, ((ts || performance.now()) - g.lastTs) / 1000 || 0.016));
    g.lastTs = ts || performance.now();
    pacUpdate(g, dt);
    pacDraw();
    g.rafId = pacRaf(pacTick);
  }

  function pacRoundRect(ctx, x, y, w, h, r) {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  function pacDraw() {
    const g = pacGame;
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const bg = ctx.createLinearGradient(0, 0, 0, cssH);
    bg.addColorStop(0, '#08081A');
    bg.addColorStop(1, '#0B0B22');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, cssW, cssH);
    const pad = 6;
    const cell = Math.min((cssW - pad * 2) / PAC_W, (cssH - pad * 2) / PAC_H);
    const ox = Math.round((cssW - cell * PAC_W) / 2);
    const oy = Math.round((cssH - cell * PAC_H) / 2);
    // 墙壁
    const wallColor = PAC_WALL_COLORS[(g.level - 1) % PAC_WALL_COLORS.length];
    for (let r = 0; r < PAC_H; r++) {
      for (let c = 0; c < PAC_W; c++) {
        if (g.grid[r][c] !== '#') continue;
        const x = ox + c * cell;
        const y = oy + r * cell;
        ctx.fillStyle = wallColor;
        pacRoundRect(ctx, x + cell * 0.06, y + cell * 0.06, cell * 0.88, cell * 0.88, cell * 0.2);
        ctx.fill();
        ctx.strokeStyle = 'rgba(255,255,255,0.16)';
        ctx.lineWidth = Math.max(1, cell * 0.05);
        pacRoundRect(ctx, x + cell * 0.18, y + cell * 0.18, cell * 0.64, cell * 0.64, cell * 0.14);
        ctx.stroke();
      }
    }
    // 鬼屋门
    ctx.fillStyle = '#F9A8D4';
    ctx.fillRect(ox + PAC_DOOR.c * cell + cell * 0.08, oy + PAC_DOOR.r * cell + cell * 0.42, cell * 0.84, Math.max(2, cell * 0.16));
    // 豆子
    for (let r = 0; r < PAC_H; r++) {
      for (let c = 0; c < PAC_W; c++) {
        const ch = g.grid[r][c];
        if (ch !== '.' && ch !== 'o') continue;
        const x = ox + (c + 0.5) * cell;
        const y = oy + (r + 0.5) * cell;
        if (ch === '.') {
          ctx.fillStyle = 'rgba(252,211,77,0.9)';
          ctx.beginPath();
          ctx.arc(x, y, Math.max(1, cell * 0.11), 0, Math.PI * 2);
          ctx.fill();
        } else {
          const blink = 0.5 + 0.5 * Math.sin(g.time * 6);
          ctx.globalAlpha = 0.5 + 0.5 * blink;
          ctx.fillStyle = '#FDE047';
          ctx.beginPath();
          ctx.arc(x, y, cell * 0.28, 0, Math.PI * 2);
          ctx.fill();
          ctx.globalAlpha = 1;
        }
      }
    }
    // 水果
    if (g.fruit.active) {
      const fx = ox + (g.fruit.c + 0.5) * cell;
      const fy = oy + (g.fruit.r + 0.5) * cell;
      const blink = g.fruit.timer < 3 ? (Math.floor(g.time * 6) % 2 === 0 ? 1 : 0.35) : 1;
      ctx.globalAlpha = blink;
      ctx.font = Math.round(cell * 1.05) + 'px "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(g.fruit.emoji, fx, fy);
      ctx.globalAlpha = 1;
      ctx.textBaseline = 'alphabetic';
    }
    // 玩家
    if (!g.over) pacDrawPlayer(ctx, g, cell, ox, oy);
    // 幽灵
    for (const gh of g.ghosts) pacDrawGhost(ctx, g, gh, cell, ox, oy);
    // 粒子
    for (const pt of g.particles) {
      ctx.globalAlpha = Math.max(0, Math.min(1, pt.life / 0.45));
      ctx.fillStyle = '#A5B4FC';
      ctx.beginPath();
      ctx.arc(ox + (pt.c + 0.5) * cell, oy + (pt.r + 0.5) * cell, Math.max(1.2, cell * 0.08), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // 飘字
    ctx.textAlign = 'center';
    for (const ft of g.floats) {
      const a = Math.max(0, Math.min(1, ft.life));
      const rise = (1.1 - ft.life) * 34;
      ctx.globalAlpha = a;
      ctx.font = '700 14px -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif';
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.lineWidth = 3;
      const tx = ox + (ft.c + 0.5) * cell;
      const ty = oy + ft.r * cell - 6 - rise;
      ctx.strokeText(ft.text, tx, ty);
      ctx.fillStyle = '#FDE047';
      ctx.fillText(ft.text, tx, ty);
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
    // READY!
    if (g.state === 'ready') {
      ctx.textAlign = 'center';
      ctx.font = '800 ' + Math.round(cell * 1.05) + 'px -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif';
      ctx.fillStyle = '#FDE047';
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 4;
      const ty = oy + 13.5 * cell;
      ctx.strokeText('READY!', ox + PAC_W * cell / 2, ty);
      ctx.fillText('READY!', ox + PAC_W * cell / 2, ty);
      ctx.textAlign = 'left';
    }
    // 通关闪白
    if (g.state === 'levelclear') {
      const k = 0.5 + 0.5 * Math.sin(g.time * 22);
      ctx.fillStyle = 'rgba(255,255,255,' + (0.16 * k).toFixed(3) + ')';
      ctx.fillRect(0, 0, cssW, cssH);
    }
  }

  function pacDrawPlayer(ctx, g, cell, ox, oy) {
    const p = g.player;
    const d = PAC_DIRS[p.dir] || PAC_DIRS.left;
    const x = ox + (p.tile.c + d.c * p.prog + 0.5) * cell;
    const y = oy + (p.tile.r + d.r * p.prog + 0.5) * cell;
    const r = cell * 0.42;
    let mouth;
    let alpha = 1;
    if (g.state === 'dying') {
      const k = 1 - Math.max(0, g.dyingLeft / 1.5);
      mouth = Math.min(Math.PI, k * Math.PI * 1.35);
      alpha = Math.max(0.1, 1 - k * 0.5);
    } else {
      mouth = (0.12 + 0.23 * (0.5 + 0.5 * Math.sin(g.time * 13))) * Math.PI;
    }
    const ang = { right: 0, down: Math.PI / 2, left: Math.PI, up: -Math.PI / 2 }[p.dir] || 0;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = '#FDE047';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.arc(x, y, r, ang + mouth, ang + Math.PI * 2 - mouth);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(253,224,71,0.5)';
    ctx.lineWidth = Math.max(1, cell * 0.06);
    ctx.stroke();
    ctx.restore();
  }

  function pacDrawGhost(ctx, g, gh, cell, ox, oy) {
    const d = PAC_DIRS[gh.dir] || PAC_DIRS.up;
    const bob = gh.state === 'house' ? Math.sin(g.time * 5 + gh.id.length) * cell * 0.06 : 0;
    const x = ox + (gh.tile.c + d.c * gh.prog + 0.5) * cell;
    const y = oy + (gh.tile.r + d.r * gh.prog + 0.5) * cell + bob;
    const r = cell * 0.44;
    const eyesOnly = gh.state === 'eaten';
    if (!eyesOnly) {
      const flashing = gh.frightened && g.frightLeft < 2 && Math.floor(g.time * 6) % 2 === 0;
      const color = gh.frightened ? (flashing ? '#F8FAFC' : '#2563EB') : gh.color;
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(x, y, r, Math.PI, 0);
      ctx.lineTo(x + r, y + r * 0.7);
      const zig = 3;
      for (let i = 0; i < zig; i++) {
        const x1 = x + r - (2 * r * (i + 0.5)) / zig;
        const x2 = x + r - (2 * r * (i + 1)) / zig;
        ctx.quadraticCurveTo(x1, y + r * 0.32, x2, y + r * 0.7);
      }
      ctx.closePath();
      ctx.fill();
      if (gh.frightened) {
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(x - r * 0.34, y - r * 0.12, r * 0.14, 0, Math.PI * 2);
        ctx.arc(x + r * 0.34, y - r * 0.12, r * 0.14, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(1, r * 0.12);
        ctx.beginPath();
        const my = y + r * 0.3;
        ctx.moveTo(x - r * 0.5, my);
        for (let i = 0; i < 3; i++) {
          ctx.lineTo(x - r * 0.5 + (r * (i * 2 + 1)) / 3, my + (i % 2 === 0 ? -r * 0.18 : r * 0.18));
        }
        ctx.lineTo(x + r * 0.5, my);
        ctx.stroke();
        return;
      }
    }
    // 眼睛
    const ex = x + d.c * r * 0.12;
    const ey = y + d.r * r * 0.12;
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.ellipse(ex - r * 0.34, ey - r * 0.1, r * 0.28, r * 0.32, 0, 0, Math.PI * 2);
    ctx.ellipse(ex + r * 0.34, ey - r * 0.1, r * 0.28, r * 0.32, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#1E3A8A';
    ctx.beginPath();
    ctx.arc(ex - r * 0.34 + d.c * r * 0.12, ey - r * 0.1 + d.r * r * 0.12, r * 0.14, 0, Math.PI * 2);
    ctx.arc(ex + r * 0.34 + d.c * r * 0.12, ey - r * 0.1 + d.r * r * 0.12, r * 0.14, 0, Math.PI * 2);
    ctx.fill();
  }

  function pacAttachInput(g) {
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    g.keyHandler = (e) => {
      const tgt = e.target;
      if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT' || tgt.isContentEditable)) return;
      const map = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down' };
      const dir = map[e.key];
      if (!dir) return;
      e.preventDefault();
      pacSetDirection(dir);
    };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    if (sheet) {
      sheet.querySelectorAll('[data-pac-dir]').forEach(btn => {
        btn.addEventListener('click', (e) => { e.preventDefault(); pacSetDirection(btn.dataset.pacDir); });
        btn.addEventListener('contextmenu', (e) => e.preventDefault());
      });
      const cv = g.canvas;
      if (cv) {
        const toPos = (clientX, clientY) => {
          try {
            const rect = cv.getBoundingClientRect();
            return { x: clientX - rect.left, y: clientY - rect.top };
          } catch (e) { return { x: clientX, y: clientY }; }
        };
        let sx = 0;
        let sy = 0;
        let tracking = false;
        const start = (x, y) => { sx = x; sy = y; tracking = true; };
        const finish = (x, y) => {
          if (!tracking) return;
          tracking = false;
          const dx = x - sx;
          const dy = y - sy;
          if (Math.max(Math.abs(dx), Math.abs(dy)) < 22) return;
          if (Math.abs(dx) > Math.abs(dy)) pacSetDirection(dx > 0 ? 'right' : 'left');
          else pacSetDirection(dy > 0 ? 'down' : 'up');
        };
        cv.addEventListener('contextmenu', (e) => e.preventDefault());
        if (typeof window.PointerEvent !== 'undefined') {
          cv.addEventListener('pointerdown', (e) => {
            e.preventDefault();
            const pos = toPos(e.clientX, e.clientY);
            try { cv.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
            start(pos.x, pos.y);
          });
          cv.addEventListener('pointerup', (e) => {
            e.preventDefault();
            const pos = toPos(e.clientX, e.clientY);
            finish(pos.x, pos.y);
          });
          cv.addEventListener('pointercancel', () => { tracking = false; });
        } else {
          cv.addEventListener('touchstart', (e) => { if (e.touches[0]) start(e.touches[0].clientX, e.touches[0].clientY); });
          cv.addEventListener('touchend', (e) => { if (e.changedTouches[0]) finish(e.changedTouches[0].clientX, e.changedTouches[0].clientY); });
          cv.addEventListener('mousedown', (e) => start(e.clientX, e.clientY));
          cv.addEventListener('mouseup', (e) => finish(e.clientX, e.clientY));
        }
      }
    }
    g._onWinResize = () => { /* 尺寸由绘制循环自适应 */ };
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }
  // __PAC_ENGINE_END__

  // __DINO_ENGINE_BEGIN__
  // ========== 恐龙游戏（Chrome 离线小恐龙 · 黑白像素无尽跑酷） ==========
  // 规则：恐龙持续向右奔跑、背景向左滚动；空格 / ↑ / 点击画面上半部跳跃（空中可再跳一次=二段跳），↓ / 按住画面下半部下蹲（碰撞盒变矮）；
  //       障碍：仙人掌（小/大、成组，需跳跃跨越）、翼龙（两种高度：低空的跳过去，头顶高度的蹲下去）；
  //       速度随得分递增、障碍间隔变小；每 700 分昼夜切换；持续跑动自动加分（每段距离 +1，封顶 99999）；
  //       任何部位碰到障碍立即结束；每累计 500 分自动 +1 积分。本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const DINO_BEST_KEY = 'werewolf_extension_dino_best';
  const DINO_SAVE_KEY = 'werewolf_extension_dino_save';
  const DINO_REWARD_STEP = 500;
  const DINO_MAX_SCORE = 99999;
  const DINO_REF_W = 400;
  const DINO_DAY_NIGHT_STEP = 700;

  let dinoGame = null;
  const dinoRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const dinoCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function dinoLoadBest() {
    try { const n = parseInt(localStorage.getItem(DINO_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function dinoSaveBest(n) {
    try { localStorage.setItem(DINO_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function dinoHasSave() {
    try {
      const raw = localStorage.getItem(DINO_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && d.dino && Array.isArray(d.obstacles) && (d.score | 0) > 0);
    } catch (e) { return false; }
  }
  function dinoClearSave() { try { localStorage.removeItem(DINO_SAVE_KEY); } catch (e) { /* ignore */ } }
  function dinoSaveGame(g) {
    try {
      if (!g || g.over) { dinoClearSave(); return false; }
      localStorage.setItem(DINO_SAVE_KEY, JSON.stringify({
        v: 1, score: g.score, rewards: g.rewards, nextRewardAt: g.nextRewardAt, time: g.time, bgShift: g.bgShift, night: g.night,
        dino: { y: g.dino.y, vy: g.dino.vy, duck: g.dino.duck, jumpsLeft: g.dino.jumpsLeft, runT: g.dino.runT },
        obstacles: g.obstacles.map(o => ({ type: o.type, x: o.x, w: o.w, h: o.h, bottom: o.bottom, group: o.group, frame: o.frame })),
        pebbles: g.pebbles.map(p => ({ x: p.x, len: p.len, y: p.y })),
        clouds: g.clouds.map(c => ({ x: c.x, y: c.y, s: c.s })),
        nextSpawnIn: g.nextSpawnIn, over: false
      }));
      return true;
    } catch (e) { return false; }
  }
  function dinoResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(DINO_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data || !data.dino || !Array.isArray(data.obstacles)) { dinoOpenGame(); return; }
    dinoOpenGame(data);
    showToast('🔖 已恢复进行中的恐龙跑酷（得分 ' + Math.floor(data.score || 0) + '）');
  }

  function dinoSizes(g) {
    const W0 = Math.max(26, Math.round((g.W || DINO_REF_W) * 0.105));
    return { W0, H0: Math.round(W0 * 1.07) };
  }
  function dinoGroundY(g) { return (g.H || 480) * 0.78; }
  function dinoFactor(g) { return Math.min(2.7, 1 + g.score / 2200); }
  function dinoSpeed(g) { return (g.W || DINO_REF_W) * 0.55 * dinoFactor(g); }
  function dinoTheme(g) {
    const night = !!g.night;
    return night
      ? { bg: '#1B1B22', fg: '#D8D8E0', dim: '#8A8A96', ground: '#D8D8E0' }
      : { bg: '#F5F5F3', fg: '#4B4B4B', dim: '#9A9A97', ground: '#535353' };
  }
  function dinoPlayerBox(g) {
    const { W0, H0 } = dinoSizes(g);
    const grounded = g.dino.y <= 0.5;
    const duck = g.dino.duck && grounded;
    const w = duck ? W0 * 1.25 : W0;
    const h = duck ? H0 * 0.6 : H0;
    const top = dinoGroundY(g) - g.dino.y - h;
    return { x: g.dinoX + 4, y: top + 3, w: w - 8, h: h - 4 };
  }
  function dinoObstacleBox(g, ob) {
    const groundY = dinoGroundY(g);
    if (ob.type === 'ptero') return { x: ob.x + 3, y: groundY - ob.bottom - ob.h + 3, w: ob.w - 6, h: ob.h - 6 };
    return { x: ob.x + 2, y: groundY - ob.h + 2, w: ob.w - 4, h: ob.h - 2 };
  }
  function dinoOverlap(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }
  function dinoNextGap(g) {
    const speed = dinoSpeed(g);
    const hard = Math.min(0.28, g.score / 10000);
    const t = (0.62 + Math.random() * 0.55) * (1 - hard);
    return Math.max((g.W || DINO_REF_W) * 0.35, speed * t);
  }

  function dinoSpawnObstacle(g) {
    const { W0, H0 } = dinoSizes(g);
    const r = Math.random();
    const canPtero = g.score > 300;
    let ob;
    if (canPtero && r < 0.28) {
      const low = Math.random() < 0.5;
      const h = H0 * 0.55;
      const bottom = low ? H0 * 0.30 : H0 * 0.80; // 低空=需跳；头顶=需蹲（80% 站立身高：站立必撞、下蹲可过）
      ob = { type: 'ptero', x: (g.W || DINO_REF_W) + 20, bottom, h, w: W0 * 1.0, group: 1, frame: 0 };
    } else {
      const large = g.score > 150 && Math.random() < 0.45;
      let group;
      if (large) group = Math.random() < 0.25 ? 2 : 1;
      else group = Math.random() < 0.22 ? 3 : (Math.random() < 0.5 ? 2 : 1);
      const wSingle = large ? W0 * 0.55 : W0 * 0.36;
      const h = large ? H0 * 1.05 : H0 * 0.72;
      const w = wSingle * group + (group - 1) * 3;
      ob = { type: large ? 'cactus_large' : 'cactus_small', x: (g.W || DINO_REF_W) + 20, w, h, group, frame: 0 };
    }
    g.obstacles.push(ob);
  }

  function dinoResetWorld(g) {
    const W = g.W || DINO_REF_W;
    const H = g.H || 480;
    g.obstacles = [];
    g.pebbles = [];
    for (let i = 0; i < 12; i++) {
      g.pebbles.push({ x: Math.random() * W, len: 4 + Math.random() * 10, y: 3 + Math.random() * 7 });
    }
    g.clouds = [];
    for (let i = 0; i < 3; i++) {
      g.clouds.push({ x: Math.random() * W, y: H * (0.08 + Math.random() * 0.24), s: 0.7 + Math.random() * 0.6 });
    }
    g.stars = [];
    for (let i = 0; i < 46; i++) {
      g.stars.push({ x: Math.random(), y: Math.random() * 0.52, r: 1 + Math.random() * 1.4 });
    }
    g.nextSpawnIn = W * 0.9;
    g.time = 0;
    g.bgShift = 0;
    g.flash = 0;
    g.night = false;
    g.hudT = 0;
    g.shake = 0;
  }

  function dinoOpenGame(saveData) {
    dinoTeardown();
    if (!sheet) { renderMiniGameLobby(); return; }
    const g = {
      W: DINO_REF_W, H: 480,
      score: 0, startBest: dinoLoadBest(), rewards: 0, nextRewardAt: DINO_REWARD_STEP,
      dinoX: DINO_REF_W * 0.10,
      dino: { y: 0, vy: 0, duck: false, jumpsLeft: 2, runT: 0 },
      obstacles: [], pebbles: [], clouds: [], stars: [],
      nextSpawnIn: DINO_REF_W * 0.9,
      night: false, flash: 0, shake: 0, over: false, time: 0, bgShift: 0, hudT: 0,
      canvas: null, stageEl: null, rafId: 0, lastTs: 0, doc: null, keyHandler: null, keyUpHandler: null, _onWinResize: null
    };
    dinoResetWorld(g);
    if (saveData && saveData.dino) {
      g.score = saveData.score || 0;
      g.rewards = saveData.rewards || 0;
      g.nextRewardAt = saveData.nextRewardAt || (Math.floor(g.score / DINO_REWARD_STEP) + 1) * DINO_REWARD_STEP;
      g.time = saveData.time || 0;
      g.bgShift = saveData.bgShift || 0;
      g.night = !!saveData.night;
      g.nextSpawnIn = saveData.nextSpawnIn || DINO_REF_W * 0.9;
      g.dino = {
        y: saveData.dino.y || 0,
        vy: saveData.dino.vy || 0,
        duck: !!saveData.dino.duck,
        jumpsLeft: saveData.dino.jumpsLeft === undefined ? 2 : saveData.dino.jumpsLeft,
        runT: saveData.dino.runT || 0
      };
      g.obstacles = (saveData.obstacles || []).map(o => ({ type: o.type, x: o.x, w: o.w, h: o.h, bottom: o.bottom, group: o.group, frame: o.frame || 0 }));
      if (Array.isArray(saveData.pebbles) && saveData.pebbles.length) g.pebbles = saveData.pebbles.map(p => ({ x: p.x, len: p.len, y: p.y }));
      if (Array.isArray(saveData.clouds) && saveData.clouds.length) g.clouds = saveData.clouds.map(c => ({ x: c.x, y: c.y, s: c.s }));
    }
    dinoGame = g;
    dinoRenderUI();
    dinoAttachInput(g);
    g.lastTs = performance.now();
    g.rafId = dinoRaf(dinoTick);
  }

  function dinoTeardown(renderLobby) {
    const g = dinoGame;
    dinoGame = null;
    if (g) {
      if (g.rafId) dinoCaf(g.rafId);
      if (g.keyHandler && g.doc) { try { g.doc.removeEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ } }
      if (g.keyUpHandler && g.doc) { try { g.doc.removeEventListener('keyup', g.keyUpHandler); } catch (e) { /* ignore */ } }
      if (g._onWinResize && g.doc) { try { (g.doc.defaultView || window).removeEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ } }
    }
    if (renderLobby) renderMiniGameLobby();
  }

  function dinoExitToLobby() {
    const g = dinoGame;
    const saved = !!(g && dinoSaveGame(g));
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    dinoTeardown();
    renderMiniGameLobby();
    showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
  }

  function dinoQuitToCenter() {
    dinoClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    dinoTeardown();
    renderSetup();
    showToast('🚪 已结束本局恐龙游戏');
  }

  function dinoRenderUI() {
    const g = dinoGame;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = dinoLoadBest();
    sheet.innerHTML = `
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="dino-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="保存进度并返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🦖 恐龙游戏</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="dino-points-label">${pointsLabelHTML()}</span>
            <span id="dino-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="dino-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏中心（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="dino-score-text" style="color:#38BDF8;font-size:18px;vertical-align:-1px;">0</b></div>
          <div id="dino-mode-text" style="font-size:12px;color:var(--ubp-text-2);">☀️ 白天</div>
          <div id="dino-speed-text" style="font-size:12px;color:var(--ubp-text-2);">速度: <b style="color:#F59E0B;">LV.1</b></div>
        </div>
        <div id="dino-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#F5F5F3;">
          <canvas id="dino-canvas" style="width:100%;height:100%;display:block;touch-action:none;"></canvas>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="display:flex;justify-content:center;align-items:center;gap:10px;">
            <button id="dino-jump-btn" data-dino-act="jump" class="ubp-btn primary" style="flex:1;max-width:150px;padding:11px 0;font-size:13.5px;font-weight:700;">⬆ 跳跃</button>
            <button id="dino-duck-btn" data-dino-act="duck" class="ubp-btn" style="flex:1;max-width:150px;padding:11px 0;font-size:13.5px;">⬇ 下蹲（按住）</button>
            <button data-ubp-act="dino-restart" class="ubp-btn" style="padding:11px 12px;font-size:13px;">🔄</button>
          </div>
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;margin-top:6px;">空格 / ↑ 跳跃（空中可再跳一次）· ↓ 按住下蹲 · 低空翼龙跳、头顶翼龙蹲 · 每 500 分 +1 积分</div>
        </div>
      </div>
    `;
    g.stageEl = sheet.querySelector('#dino-stage');
    g.canvas = sheet.querySelector('#dino-canvas');
    dinoUpdateHud(g);
  }

  function dinoUpdateHud(g) {
    if (!g || !sheet) return;
    const s = sheet.querySelector('#dino-score-text');
    if (s) s.textContent = String(Math.floor(g.score));
    const md = sheet.querySelector('#dino-mode-text');
    if (md) md.textContent = g.night ? '🌙 夜晚' : '☀️ 白天';
    const sp = sheet.querySelector('#dino-speed-text');
    if (sp) {
      const lv = Math.min(10, Math.floor((dinoFactor(g) - 1) / 0.2) + 1);
      sp.innerHTML = '速度: <b style="color:#F59E0B;">LV.' + lv + '</b>';
    }
    const best = dinoLoadBest();
    if (g.score > best) dinoSaveBest(g.score);
    const bl = sheet.querySelector('#dino-best-label');
    if (bl) bl.textContent = '🏆 最高 ' + Math.round(Math.max(best, g.score));
  }

  function dinoJump() {
    const g = dinoGame;
    if (!g || g.over) return;
    const d = g.dino;
    if (d.y <= 0) {
      d.vy = 1.5 * (g.W || DINO_REF_W);
      d.jumpsLeft = 1;
      d.y = 0.0001;
    } else if (d.jumpsLeft > 0) {
      d.vy = 1.35 * (g.W || DINO_REF_W);
      d.jumpsLeft -= 1;
    }
  }

  function dinoSetDuck(held) {
    const g = dinoGame;
    if (!g || g.over) return;
    g.dino.duck = !!held;
  }

  function dinoCheckMilestones(g) {
    let crossed = false;
    while (g.score >= g.nextRewardAt) {
      g.nextRewardAt += DINO_REWARD_STEP;
      g.rewards += 1;
      addPoints(1);
      crossed = true;
    }
    if (crossed) {
      const pl = sheet ? sheet.querySelector('#dino-points-label') : null;
      if (pl) pl.innerHTML = pointsLabelHTML();
      showToast('🎉 累计得分 ' + Math.floor(g.score) + '！积分 +1（当前 ' + loadPoints() + '）');
    }
  }

  function dinoDie(g) {
    if (g.over) return;
    g.over = true;
    g.shake = 1;
    dinoClearSave();
    const ref = g;
    setTimeout(() => { if (dinoGame === ref) dinoGameOver(ref); }, 480);
  }

  function dinoUpdate(g, dt) {
    if (!g) return;
    g.time += dt;
    if (g.flash > 0) g.flash = Math.max(0, g.flash - dt);
    if (g.shake > 0) g.shake = Math.max(0, g.shake - dt * 2.2);
    if (g.over) return;
    const W = g.W || DINO_REF_W;
    const speed = dinoSpeed(g);
    // 计分（封顶 99999）
    if (g.score < DINO_MAX_SCORE) {
      g.score = Math.min(DINO_MAX_SCORE, g.score + dt * 10 * dinoFactor(g));
      dinoCheckMilestones(g);
    }
    // 昼夜切换
    const night = Math.floor(g.score / DINO_DAY_NIGHT_STEP) % 2 === 1;
    if (night !== g.night) {
      g.night = night;
      g.flash = 0.35;
      if (sheet) {
        const md = sheet.querySelector('#dino-mode-text');
        if (md) md.textContent = night ? '🌙 夜晚' : '☀️ 白天';
      }
    }
    // 背景层
    g.bgShift += speed * 0.2 * dt;
    for (const p of g.pebbles) {
      p.x -= speed * dt;
      if (p.x < -30) { p.x += W + 40 + Math.random() * 80; p.len = 4 + Math.random() * 10; p.y = 3 + Math.random() * 7; }
    }
    for (const c of g.clouds) {
      c.x -= speed * 0.45 * dt;
      if (c.x < -90) { c.x += W + 100 + Math.random() * 140; c.y = (g.H || 480) * (0.08 + Math.random() * 0.24); }
    }
    // 障碍生成与移动
    g.nextSpawnIn -= speed * dt;
    if (g.nextSpawnIn <= 0) {
      dinoSpawnObstacle(g);
      g.nextSpawnIn = dinoNextGap(g);
    }
    for (let i = g.obstacles.length - 1; i >= 0; i--) {
      const ob = g.obstacles[i];
      ob.x -= speed * dt;
      if (ob.type === 'ptero') ob.frame = Math.floor(g.time * 8) % 2;
      if (ob.x + ob.w < -30) g.obstacles.splice(i, 1);
    }
    // 恐龙物理
    const G = 6.5 * W;
    const d = g.dino;
    if (d.y > 0 || d.vy !== 0) {
      let grav = G;
      if (d.duck) grav *= 1.9; // 空中按住 ↓ 快速下落
      d.vy -= grav * dt;
      d.y += d.vy * dt;
      if (d.y <= 0) { d.y = 0; d.vy = 0; d.jumpsLeft = 2; }
    } else {
      d.jumpsLeft = 2;
    }
    d.runT += dt;
    // 碰撞
    const pb = dinoPlayerBox(g);
    for (const ob of g.obstacles) {
      if (dinoOverlap(pb, dinoObstacleBox(g, ob))) { dinoDie(g); return; }
    }
    // HUD 节流刷新
    g.hudT += dt;
    if (g.hudT >= 0.25) {
      g.hudT = 0;
      dinoUpdateHud(g);
    }
  }

  function dinoGameOver(g) {
    dinoClearSave();
    const stage = sheet ? sheet.querySelector('#dino-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.dino-overlay').forEach(el => el.remove());
    const startBest = g.startBest || 0;
    const scoreI = Math.floor(g.score);
    const isNew = scoreI > startBest;
    const best = Math.max(startBest, scoreI);
    if (scoreI > dinoLoadBest()) dinoSaveBest(scoreI);
    const bl = sheet ? sheet.querySelector('#dino-best-label') : null;
    if (bl) bl.textContent = '🏆 最高 ' + best;
    const ov = document.createElement('div');
    ov.className = 'dino-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.72);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #38BDF8;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '🦴'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : 'GAME OVER'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#38BDF8;font-size:17px;">${scoreI}</b><br>
          速度等级：<b style="color:#F59E0B;">LV.${Math.min(10, Math.floor((dinoFactor(g) - 1) / 0.2) + 1)}</b><br>
          最高分：<b style="color:#F59E0B;">${best}</b><br>
          本局积分奖励：<b style="color:#F59E0B;">+${g.rewards}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="dino-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#38BDF8;border:none;color:#fff;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="dino-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">碰到仙人掌 / 翼龙即结束 · 每 500 分 +1 积分</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function dinoTick(ts) {
    const g = dinoGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { dinoTeardown(false); return; }
    const dt = Math.min(0.05, Math.max(0.001, ((ts || performance.now()) - g.lastTs) / 1000 || 0.016));
    g.lastTs = ts || performance.now();
    dinoUpdate(g, dt);
    dinoDraw();
    g.rafId = dinoRaf(dinoTick);
  }

  function dinoDraw() {
    const g = dinoGame;
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    g.W = cssW;
    g.H = cssH;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const theme = dinoTheme(g);
    const W = g.W;
    const H = g.H;
    const groundY = dinoGroundY(g);
    ctx.fillStyle = theme.bg;
    ctx.fillRect(0, 0, W, H);
    // 夜晚：星星 + 月亮
    if (g.night) {
      ctx.fillStyle = '#F5F5C8';
      for (const st of g.stars) {
        const sx = ((st.x * W - g.bgShift * 0.6) % W + W) % W;
        ctx.globalAlpha = 0.75;
        ctx.fillRect(Math.round(sx), Math.round(st.y * H * 0.8), Math.max(1, Math.round(st.r)), Math.max(1, Math.round(st.r)));
      }
      ctx.globalAlpha = 1;
      const mx = W * 0.82;
      const my = H * 0.16;
      const mr = Math.max(10, H * 0.045);
      ctx.fillStyle = '#F5F5C8';
      ctx.beginPath();
      ctx.arc(mx, my, mr, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = theme.bg;
      ctx.beginPath();
      ctx.arc(mx - mr * 0.45, my - mr * 0.2, mr * 0.85, 0, Math.PI * 2);
      ctx.fill();
    }
    // 云朵
    ctx.fillStyle = theme.dim;
    for (const c of g.clouds) {
      const ch = Math.max(6, H * 0.022 * c.s);
      const cw = ch * 3.2;
      ctx.globalAlpha = g.night ? 0.5 : 0.9;
      ctx.fillRect(Math.round(c.x), Math.round(c.y), Math.round(cw), Math.round(ch));
      ctx.fillRect(Math.round(c.x + cw * 0.2), Math.round(c.y - ch * 0.7), Math.round(cw * 0.5), Math.round(ch * 0.8));
      ctx.fillRect(Math.round(c.x + cw * 0.55), Math.round(c.y - ch * 0.4), Math.round(cw * 0.34), Math.round(ch * 0.5));
    }
    ctx.globalAlpha = 1;
    // 地面
    ctx.fillStyle = theme.ground;
    ctx.fillRect(0, Math.round(groundY), W, 2);
    for (const p of g.pebbles) {
      ctx.fillStyle = theme.dim;
      ctx.fillRect(Math.round(p.x), Math.round(groundY + p.y), Math.round(p.len), 1);
    }
    // 障碍
    for (const ob of g.obstacles) {
      ctx.fillStyle = theme.fg;
      if (ob.type === 'ptero') dinoDrawPtero(ctx, g, ob, theme);
      else dinoDrawCactus(ctx, g, ob);
    }
    // 恐龙
    const shakeX = g.shake > 0 ? (Math.random() - 0.5) * 6 * g.shake : 0;
    ctx.save();
    ctx.translate(shakeX, 0);
    dinoDrawDino(ctx, g, theme);
    ctx.restore();
    // 分数（经典 5 位）
    ctx.font = '700 ' + Math.max(12, Math.round(H * 0.045)) + 'px "Courier New", monospace';
    ctx.textAlign = 'left';
    const raw = String(Math.floor(g.score)).padStart(5, '0');
    const bestI = Math.min(DINO_MAX_SCORE, Math.max(dinoLoadBest(), Math.floor(g.score)));
    const pre = 'HI ' + String(bestI).padStart(5, '0') + '  ';
    const total = ctx.measureText(pre + raw).width;
    const x0 = W - 14 - total;
    const ty = Math.max(20, H * 0.12);
    ctx.fillStyle = theme.dim;
    ctx.fillText(pre, x0, ty);
    ctx.fillStyle = theme.fg;
    ctx.fillText(raw, x0 + ctx.measureText(pre).width, ty);
    // 昼夜切换闪光
    if (g.flash > 0) {
      ctx.fillStyle = theme.bg;
      ctx.globalAlpha = Math.min(1, g.flash * 2.2);
      ctx.fillRect(0, 0, W, H);
      ctx.globalAlpha = 1;
    }
    // GAME OVER 文字
    if (g.over) {
      ctx.textAlign = 'center';
      ctx.fillStyle = theme.fg;
      ctx.font = '700 ' + Math.max(14, Math.round(H * 0.055)) + 'px "Courier New", monospace';
      ctx.fillText('GAME OVER', W / 2, groundY - H * 0.18);
      ctx.textAlign = 'left';
    }
  }

  function dinoDrawDino(ctx, g, theme) {
    const { W0, H0 } = dinoSizes(g);
    const groundY = dinoGroundY(g);
    const d = g.dino;
    const duck = d.duck && d.y <= 0.5;
    const w = duck ? W0 * 1.25 : W0;
    const h = duck ? H0 * 0.6 : H0;
    const x = Math.round(g.dinoX);
    const yTop = Math.round(groundY - d.y - h);
    ctx.fillStyle = theme.fg;
    const rect = (rx, ry, rw, rh) => ctx.fillRect(Math.round(rx), Math.round(ry), Math.max(1, Math.round(rw)), Math.max(1, Math.round(rh)));
    if (duck) {
      rect(x - w * 0.10, yTop + h * 0.38, w * 0.22, h * 0.24);
      rect(x + w * 0.08, yTop + h * 0.22, w * 0.62, h * 0.58);
      rect(x + w * 0.62, yTop + h * 0.02, w * 0.34, h * 0.40);
      rect(x + w * 0.80, yTop + h * 0.12, w * 0.20, h * 0.14);
      ctx.save();
      ctx.fillStyle = theme.bg;
      rect(x + w * 0.84, yTop + h * 0.08, w * 0.06, h * 0.08);
      ctx.restore();
      const f = Math.floor(d.runT * 9) % 2;
      rect(x + w * 0.14 + f * 5, yTop + h * 0.78, w * 0.14, h * 0.22);
      rect(x + w * 0.46 - f * 5, yTop + h * 0.78, w * 0.14, h * 0.22);
      return;
    }
    const running = d.y <= 0;
    rect(x - w * 0.10, yTop + h * 0.36, w * 0.26, h * 0.16);
    rect(x + w * 0.12, yTop + h * 0.30, w * 0.60, h * 0.42);
    rect(x + w * 0.52, yTop + h * 0.02, w * 0.34, h * 0.34);
    rect(x + w * 0.78, yTop + h * 0.12, w * 0.22, h * 0.14);
    ctx.save();
    ctx.fillStyle = theme.bg;
    rect(x + w * 0.70, yTop + h * 0.10, w * 0.07, h * 0.07);
    ctx.restore();
    rect(x + w * 0.54, yTop + h * 0.52, w * 0.12, h * 0.08);
    if (running) {
      const f = Math.floor(d.runT * 9) % 2;
      const legY = yTop + h * 0.72;
      const legH = h * 0.28;
      if (f === 0) {
        rect(x + w * 0.20, legY, w * 0.14, legH);
        rect(x + w * 0.46, legY, w * 0.14, legH * 0.7);
      } else {
        rect(x + w * 0.24, legY, w * 0.14, legH * 0.7);
        rect(x + w * 0.42, legY, w * 0.14, legH);
      }
    } else {
      rect(x + w * 0.22, yTop + h * 0.70, w * 0.14, h * 0.20);
      rect(x + w * 0.46, yTop + h * 0.70, w * 0.14, h * 0.20);
    }
  }

  function dinoDrawCactus(ctx, g, ob) {
    const groundY = dinoGroundY(g);
    const single = (ob.w - (ob.group - 1) * 3) / ob.group;
    for (let i = 0; i < ob.group; i++) {
      const x = ob.x + i * (single + 3);
      const top = groundY - ob.h;
      const rect = (rx, ry, rw, rh) => ctx.fillRect(Math.round(rx), Math.round(ry), Math.max(1, Math.round(rw)), Math.max(1, Math.round(rh)));
      rect(x + single * 0.28, top, single * 0.44, ob.h);
      if (ob.h > 22) {
        rect(x, top + ob.h * 0.28, single * 0.26, ob.h * 0.18);
        rect(x, top + ob.h * 0.28, single * 0.12, ob.h * 0.46);
        rect(x + single * 0.74, top + ob.h * 0.20, single * 0.26, ob.h * 0.18);
        rect(x + single * 0.88, top + ob.h * 0.20, single * 0.12, ob.h * 0.5);
      }
    }
  }

  function dinoDrawPtero(ctx, g, ob, theme) {
    const groundY = dinoGroundY(g);
    const top = groundY - ob.bottom - ob.h;
    const x = ob.x;
    const w = ob.w;
    const h = ob.h;
    const rect = (rx, ry, rw, rh) => ctx.fillRect(Math.round(rx), Math.round(ry), Math.max(1, Math.round(rw)), Math.max(1, Math.round(rh)));
    rect(x + w * 0.2, top + h * 0.32, w * 0.5, h * 0.34);
    rect(x + w * 0.68, top + h * 0.38, w * 0.30, h * 0.14);
    if (ob.frame === 0) rect(x + w * 0.14, top, w * 0.52, h * 0.34);
    else rect(x + w * 0.14, top + h * 0.64, w * 0.52, h * 0.34);
    ctx.save();
    ctx.fillStyle = theme.bg;
    rect(x + w * 0.56, top + h * 0.42, w * 0.06, h * 0.1);
    ctx.restore();
  }

  function dinoAttachInput(g) {
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    g.keyHandler = (e) => {
      const tgt = e.target;
      if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT' || tgt.isContentEditable)) return;
      if (e.key === ' ' || e.key === 'ArrowUp' || e.key === 'w' || e.key === 'W') {
        e.preventDefault();
        if (!e.repeat) dinoJump();
      } else if (e.key === 'ArrowDown' || e.key === 's' || e.key === 'S') {
        e.preventDefault();
        dinoSetDuck(true);
      }
    };
    g.keyUpHandler = (e) => {
      if (e.key === 'ArrowDown' || e.key === 's' || e.key === 'S') dinoSetDuck(false);
    };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    try { doc.addEventListener('keyup', g.keyUpHandler); } catch (e) { /* ignore */ }
    if (sheet) {
      const jumpBtn = sheet.querySelector('#dino-jump-btn');
      if (jumpBtn) {
        jumpBtn.addEventListener('click', (e) => { e.preventDefault(); dinoJump(); });
        jumpBtn.addEventListener('contextmenu', (e) => e.preventDefault());
      }
      const duckBtn = sheet.querySelector('#dino-duck-btn');
      if (duckBtn) {
        duckBtn.addEventListener('contextmenu', (e) => e.preventDefault());
        const on = (e) => { e.preventDefault(); try { duckBtn.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ } dinoSetDuck(true); };
        const off = (e) => { if (e) e.preventDefault(); dinoSetDuck(false); };
        if (typeof window.PointerEvent !== 'undefined') {
          duckBtn.addEventListener('pointerdown', on);
          duckBtn.addEventListener('pointerup', off);
          duckBtn.addEventListener('pointercancel', off);
        } else {
          duckBtn.addEventListener('touchstart', on);
          duckBtn.addEventListener('touchend', off);
          duckBtn.addEventListener('mousedown', on);
          duckBtn.addEventListener('mouseup', off);
          duckBtn.addEventListener('mouseleave', () => dinoSetDuck(false));
        }
      }
      const cv = g.canvas;
      if (cv) {
        const act = (e, down) => {
          const rect = (() => { try { return cv.getBoundingClientRect(); } catch (err) { return { left: 0, top: 0, width: g.W, height: g.H }; } })();
          const y = e.clientY - rect.top;
          if (y > rect.height * 0.7) {
            if (down) { e.preventDefault(); try { cv.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ } dinoSetDuck(true); }
            else { dinoSetDuck(false); }
          } else if (down) {
            e.preventDefault();
            dinoJump();
          }
        };
        cv.addEventListener('contextmenu', (e) => e.preventDefault());
        if (typeof window.PointerEvent !== 'undefined') {
          cv.addEventListener('pointerdown', (e) => act(e, true));
          cv.addEventListener('pointerup', (e) => act(e, false));
          cv.addEventListener('pointercancel', () => dinoSetDuck(false));
        } else {
          cv.addEventListener('touchstart', (e) => { if (e.touches[0]) act(e.touches[0], true); });
          cv.addEventListener('touchend', (e) => { if (e.changedTouches[0]) act(e.changedTouches[0], false); });
          cv.addEventListener('mousedown', (e) => act(e, true));
          cv.addEventListener('mouseup', (e) => act(e, false));
        }
      }
    }
    g._onWinResize = () => { /* 尺寸由绘制循环自适应 */ };
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }
